							hitData.m_skillRaiseAmount = m_raiseSkillAmount;
							hitData.m_damage.Add(m_weapon.GetDamage());
							hitData.m_point = vector;
							hitData.m_dir = vector2;
							hitData.m_hitCollider = collider;
