					if (((!m_hitFriendly || m_character.IsTamed()) && !m_character.IsPlayer() && !flag) || (!m_weapon.m_shared.m_tamedOnly && m_character.IsPlayer() && !m_character.IsPVPEnabled() && !flag) || (m_weapon.m_shared.m_tamedOnly && !component2.IsTamed()))
					{
