using System.Collections.Generic;
using UnityEngine;

public class BackgroundLoadingBudgetController
{
	private const ThreadPriority c_defaultBudget = ThreadPriority.Low;

	private static List<ThreadPriority> m_budgetRequests = new List<ThreadPriority>();

	[RuntimeInitializeOnLoadMethod]
	private static void OnLoad()
	{
		ApplyBudget();
	}

	public static ThreadPriority RequestLoadingBudget(ThreadPriority priority)
	{
		AddRequest(priority);
		ApplyBudget();
		return priority;
	}

	public static ThreadPriority UpdateLoadingBudgetRequest(ThreadPriority oldPriority, ThreadPriority newPriority)
	{
		RemoveRequest(oldPriority);
		AddRequest(newPriority);
		ApplyBudget();
		return newPriority;
	}

	public static void ReleaseLoadingBudgetRequest(ThreadPriority priority)
	{
		RemoveRequest(priority);
		ApplyBudget();
	}

	private static void AddRequest(ThreadPriority priority)
	{
		int num = m_budgetRequests.BinarySearch(priority);
		if (num < 0)
		{
			num = ~num;
		}
		m_budgetRequests.Insert(num, priority);
	}

	private static void RemoveRequest(ThreadPriority priority)
	{
		int num = m_budgetRequests.BinarySearch(priority);
		if (num >= 0)
		{
			m_budgetRequests.RemoveAt(num);
		}
		else
		{
			ZLog.LogError($"Failed to remove loading budget request {priority}");
		}
	}

	private static void ApplyBudget()
	{
		ThreadPriority threadPriority = (Application.backgroundLoadingPriority = ((m_budgetRequests.Count > 0 && m_budgetRequests[m_budgetRequests.Count - 1] >= ThreadPriority.Low) ? m_budgetRequests[m_budgetRequests.Count - 1] : ThreadPriority.Low));
		ZLog.Log($"Set background loading budget to {threadPriority}");
	}
}
using UnityEngine;

public class Barber : MonoBehaviour, Hoverable, Interactable
{
	public string m_name = "Chair";

	public float m_useDistance = 2f;

	public Transform m_attachPoint;

	public Vector3 m_detachOffset = new Vector3(0f, 0.5f, 0f);

	public string m_attachAnimation = "attach_chair";

	public Transform m_cameraPosition;

	private const float m_minSitDelay = 2f;

	private static float m_lastSitTime;

	public string GetHoverText()
	{
		if (Time.time - m_lastSitTime < 2f)
		{
			return "";
		}
		if (!InUseDistance(Player.m_localPlayer))
		{
			return Localization.instance.Localize("<color=#888888>$piece_toofar</color>");
		}
		return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_use");
	}

	public string GetHoverName()
	{
		return m_name;
	}

	private void Update()
	{
		if (!PlayerCustomizaton.IsBarberGuiVisible() && (bool)Player.m_localPlayer && (bool)m_attachPoint && Player.m_localPlayer.GetAttachPoint() == m_attachPoint && !InventoryGui.IsVisible() && !Minimap.IsOpen() && !Game.IsPaused())
		{
			PlayerCustomizaton.ShowBarberGui();
		}
	}

	public bool Interact(Humanoid human, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		Player player = human as Player;
		if (!InUseDistance(player))
		{
			return false;
		}
		if (Time.time - m_lastSitTime < 2f)
		{
			return false;
		}
		Player closestPlayer = Player.GetClosestPlayer(m_attachPoint.position, 0.1f);
		if (closestPlayer != null && closestPlayer != Player.m_localPlayer)
		{
			Player.m_localPlayer.Message(MessageHud.MessageType.Center, "$msg_blocked");
			return false;
		}
		if ((bool)player)
		{
			if (player.IsEncumbered())
			{
				return false;
			}
			player.AttachStart(m_attachPoint, null, hideWeapons: false, isBed: false, onShip: false, m_attachAnimation, m_detachOffset, m_cameraPosition);
			PlayerCustomizaton.ShowBarberGui();
			m_lastSitTime = Time.time;
		}
		return false;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private bool InUseDistance(Humanoid human)
	{
		return Vector3.Distance(human.transform.position, m_attachPoint.position) < m_useDistance;
	}
}
