	protected virtual void RPC_OnNearProjectileHit(long sender, Vector3 center, float range, ZDOID attacker)
	{
		if (!ZoneSystem.instance.GetGlobalKey(GlobalKeys.PassiveMobs))
		{
			Alert();
		}
