			if (Vector3.Distance(point, instance.transform.position) < instance.m_range)
			{
				becons.Add(instance);
			}
		}
	}
}
using UnityEngine;

public class Bed : MonoBehaviour, Hoverable, Interactable
{
	public Transform m_spawnPoint;

	public float m_monsterCheckRadius = 20f;

	private ZNetView m_nview;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		if (m_nview.GetZDO() != null)
		{
			m_nview.Register<long, string>("SetOwner", RPC_SetOwner);
		}
	}

	public string GetHoverText()
	{
		string ownerName = GetOwnerName();
		if (ownerName == "")
		{
			return Localization.instance.Localize("$piece_bed_unclaimed\n[<color=yellow><b>$KEY_Use</b></color>] $piece_bed_claim");
		}
		string text = ownerName + "'s $piece_bed";
		if (IsMine())
		{
			if (IsCurrent())
			{
				return Localization.instance.Localize(text + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_bed_sleep");
			}
			return Localization.instance.Localize(text + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_bed_setspawn");
		}
		return Localization.instance.Localize(text);
	}

	public string GetHoverName()
	{
		return Localization.instance.Localize("$piece_bed");
	}

	public bool Interact(Humanoid human, bool repeat, bool alt)
	{
		if (repeat)
		{
			return false;
		}
		if (m_nview.GetZDO() == null)
		{
			return false;
		}
		long playerID = Game.instance.GetPlayerProfile().GetPlayerID();
		long owner = GetOwner();
		Player human2 = human as Player;
		if (owner == 0L)
		{
			ZLog.Log("Has no creator");
			if (!CheckExposure(human2))
			{
				return false;
			}
			SetOwner(playerID, Game.instance.GetPlayerProfile().GetName());
			Game.instance.GetPlayerProfile().SetCustomSpawnPoint(GetSpawnPoint());
			human.Message(MessageHud.MessageType.Center, "$msg_spawnpointset");
		}
		else if (IsMine())
		{
			ZLog.Log("Is mine");
			if (IsCurrent())
			{
				ZLog.Log("is current spawnpoint");
				if (!EnvMan.CanSleep())
				{
					human.Message(MessageHud.MessageType.Center, "$msg_cantsleep");
					return false;
				}
				if (!CheckEnemies(human2))
				{
					return false;
				}
				if (!CheckExposure(human2))
				{
					return false;
				}
				if (!CheckFire(human2))
				{
					return false;
				}
				if (!CheckWet(human2))
				{
					return false;
				}
				human.AttachStart(m_spawnPoint, base.gameObject, hideWeapons: true, isBed: true, onShip: false, "attach_bed", new Vector3(0f, 0.5f, 0f));
				return false;
			}
			ZLog.Log("Not current spawn point");
			if (!CheckExposure(human2))
			{
				return false;
			}
			Game.instance.GetPlayerProfile().SetCustomSpawnPoint(GetSpawnPoint());
			human.Message(MessageHud.MessageType.Center, "$msg_spawnpointset");
		}
		return false;
	}

	private bool CheckWet(Player human)
	{
		if (human.GetSEMan().HaveStatusEffect(SEMan.s_statusEffectWet))
		{
			human.Message(MessageHud.MessageType.Center, "$msg_bedwet");
			return false;
		}
		return true;
	}

	private bool CheckEnemies(Player human)
	{
		if (human.IsSensed())
		{
			human.Message(MessageHud.MessageType.Center, "$msg_bedenemiesnearby");
			return false;
		}
		return true;
	}

	private bool CheckExposure(Player human)
	{
		Cover.GetCoverForPoint(GetSpawnPoint(), out var coverPercentage, out var underRoof);
		if (!underRoof)
		{
			human.Message(MessageHud.MessageType.Center, "$msg_bedneedroof");
			return false;
		}
		if (coverPercentage < 0.8f)
		{
			human.Message(MessageHud.MessageType.Center, "$msg_bedtooexposed");
			return false;
		}
		ZLog.Log("exporeusre check " + coverPercentage + "  " + underRoof);
		return true;
	}

	private bool CheckFire(Player human)
	{
		if (!EffectArea.IsPointInsideArea(base.transform.position, EffectArea.Type.Heat))
		{
			human.Message(MessageHud.MessageType.Center, "$msg_bednofire");
			return false;
		}
		return true;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	public bool IsCurrent()
	{
		if (!IsMine())
		{
			return false;
		}
		return Vector3.Distance(GetSpawnPoint(), Game.instance.GetPlayerProfile().GetCustomSpawnPoint()) < 1f;
	}

	public Vector3 GetSpawnPoint()
	{
		return m_spawnPoint.position;
	}

	private bool IsMine()
	{
		long playerID = Game.instance.GetPlayerProfile().GetPlayerID();
		long owner = GetOwner();
		return playerID == owner;
	}

	private void SetOwner(long uid, string name)
	{
		m_nview.InvokeRPC("SetOwner", uid, name);
	}

	private void RPC_SetOwner(long sender, long uid, string name)
	{
		if (m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_owner, uid);
			m_nview.GetZDO().Set(ZDOVars.s_ownerName, name);
		}
	}

	private long GetOwner()
	{
		if (m_nview.GetZDO() == null)
		{
			return 0L;
		}
		return m_nview.GetZDO().GetLong(ZDOVars.s_owner, 0L);
	}

	private string GetOwnerName()
	{
		if (m_nview.GetZDO() == null)
		{
			return "";
		}
		if (!IsMine())
		{
			return CensorShittyWords.FilterUGC(m_nview.GetZDO().GetString(ZDOVars.s_ownerName), UGCType.CharacterName, GetOwner());
		}
		return m_nview.GetZDO().GetString(ZDOVars.s_ownerName);
	}
}
using System;
using UnityEngine;

public class Beehive : MonoBehaviour, Hoverable, Interactable
{
	public string m_name = "";

	public Transform m_coverPoint;

	public Transform m_spawnPoint;

	public GameObject m_beeEffect;

	public bool m_effectOnlyInDaylight = true;

	public float m_maxCover = 0.25f;

	[BitMask(typeof(Heightmap.Biome))]
	public Heightmap.Biome m_biome;

	public float m_secPerUnit = 10f;

	public int m_maxHoney = 4;

	public ItemDrop m_honeyItem;

	public EffectList m_spawnEffect = new EffectList();

	[Header("Texts")]
	public string m_extractText = "$piece_beehive_extract";

	public string m_checkText = "$piece_beehive_check";

	public string m_areaText = "$piece_beehive_area";

	public string m_freespaceText = "$piece_beehive_freespace";

	public string m_sleepText = "$piece_beehive_sleep";

	public string m_happyText = "$piece_beehive_happy";

	public string m_notConnectedText;

	public string m_blockedText;

	private ZNetView m_nview;

	private Collider m_collider;

	private Piece m_piece;

	private ZNetView m_connectedObject;

	private Piece m_blockingPiece;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_collider = GetComponentInChildren<Collider>();
		m_piece = GetComponent<Piece>();
		if (m_nview.GetZDO() != null)
		{
			if (m_nview.IsOwner() && m_nview.GetZDO().GetLong(ZDOVars.s_lastTime, 0L) == 0L)
			{
				m_nview.GetZDO().Set(ZDOVars.s_lastTime, ZNet.instance.GetTime().Ticks);
			}
			m_nview.Register("RPC_Extract", RPC_Extract);
			InvokeRepeating("UpdateBees", 0f, 10f);
		}
	}

	public string GetHoverText()
	{
		if (!PrivateArea.CheckAccess(base.transform.position, 0f, flash: false))
		{
			return Localization.instance.Localize(m_name + "\n$piece_noaccess");
		}
		int honeyLevel = GetHoneyLevel();
		if (honeyLevel > 0)
		{
			return Localization.instance.Localize($"{m_name} ( {m_honeyItem.m_itemData.m_shared.m_name} x {honeyLevel} )\n[<color=yellow><b>$KEY_Use</b></color>] {m_extractText}");
		}
		return Localization.instance.Localize(m_name + " ( $piece_container_empty )\n[<color=yellow><b>$KEY_Use</b></color>] " + m_checkText);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool repeat, bool alt)
	{
		if (repeat)
		{
			return false;
		}
		if (!PrivateArea.CheckAccess(base.transform.position))
		{
			return true;
		}
		if (GetHoneyLevel() > 0)
		{
			Extract();
			Game.instance.IncrementPlayerStat(PlayerStatType.BeesHarvested);
		}
		else
		{
			if (!CheckBiome())
			{
				character.Message(MessageHud.MessageType.Center, m_areaText);
				return true;
			}
			if (!HaveFreeSpace())
			{
				character.Message(MessageHud.MessageType.Center, m_freespaceText);
				return true;
			}
			if (!EnvMan.IsDaylight() && m_effectOnlyInDaylight)
			{
				character.Message(MessageHud.MessageType.Center, m_sleepText);
				return true;
			}
			character.Message(MessageHud.MessageType.Center, m_happyText);
		}
		return true;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void Extract()
	{
		m_nview.InvokeRPC("RPC_Extract");
	}

	private void RPC_Extract(long caller)
	{
		int honeyLevel = GetHoneyLevel();
		if (honeyLevel > 0)
		{
			m_spawnEffect.Create(m_spawnPoint.position, Quaternion.identity);
			for (int i = 0; i < honeyLevel; i++)
			{
				Vector2 vector = UnityEngine.Random.insideUnitCircle * 0.5f;
				Vector3 position = m_spawnPoint.position + new Vector3(vector.x, 0.25f * (float)i, vector.y);
				UnityEngine.Object.Instantiate(m_honeyItem, position, Quaternion.identity).GetComponent<ItemDrop>()?.SetStack(Game.instance.ScaleDrops(m_honeyItem.m_itemData, 1));
			}
			ResetLevel();
		}
	}

	private float GetTimeSinceLastUpdate()
	{
		DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_lastTime, ZNet.instance.GetTime().Ticks));
		DateTime time = ZNet.instance.GetTime();
		TimeSpan timeSpan = time - dateTime;
		m_nview.GetZDO().Set(ZDOVars.s_lastTime, time.Ticks);
		double num = timeSpan.TotalSeconds;
		if (num < 0.0)
		{
			num = 0.0;
		}
		return (float)num;
	}

	private void ResetLevel()
	{
		m_nview.GetZDO().Set(ZDOVars.s_level, 0);
	}

	private void IncreseLevel(int i)
	{
		int honeyLevel = GetHoneyLevel();
		honeyLevel += i;
		honeyLevel = Mathf.Clamp(honeyLevel, 0, m_maxHoney);
		m_nview.GetZDO().Set(ZDOVars.s_level, honeyLevel);
	}

	private int GetHoneyLevel()
	{
		if (m_nview == null || !m_nview.IsValid())
		{
			return 0;
		}
		return m_nview.GetZDO().GetInt(ZDOVars.s_level);
	}

	private void UpdateBees()
	{
		bool flag = CheckBiome() && HaveFreeSpace();
		bool active = flag && (!m_effectOnlyInDaylight || EnvMan.IsDaylight());
		m_beeEffect.SetActive(active);
		if (m_nview.IsOwner() && flag)
		{
			float timeSinceLastUpdate = GetTimeSinceLastUpdate();
			float num = m_nview.GetZDO().GetFloat(ZDOVars.s_product);
			num += timeSinceLastUpdate;
			if (num > m_secPerUnit)
			{
				int i = (int)(num / m_secPerUnit);
				IncreseLevel(i);
				num = 0f;
			}
			m_nview.GetZDO().Set(ZDOVars.s_product, num);
		}
	}

	private bool HaveFreeSpace()
	{
		if (m_maxCover <= 0f)
		{
			return true;
		}
		Cover.GetCoverForPoint(m_coverPoint.position, out var coverPercentage, out var _);
		return coverPercentage < m_maxCover;
	}

	private bool CheckBiome()
	{
		return (Heightmap.FindBiome(base.transform.position) & m_biome) != 0;
	}
}
using UnityEngine;

public class Billboard : MonoBehaviour
{
	public bool m_vertical = true;

	public bool m_invert;

	private Vector3 m_normal;

	private void Awake()
	{
		m_normal = base.transform.up;
	}

	private void LateUpdate()
	{
		Camera mainCamera = Utils.GetMainCamera();
		if (!(mainCamera == null))
		{
			Vector3 vector = mainCamera.transform.position;
			if (m_invert)
			{
				vector = base.transform.position - (vector - base.transform.position);
			}
			if (m_vertical)
			{
				vector.y = base.transform.position.y;
				base.transform.LookAt(vector, m_normal);
			}
			else
			{
				base.transform.LookAt(vector);
			}
		}
	}
}
