using System.Collections;
using UnityEngine;

public class BossStone : MonoBehaviour
{
	public ItemStand m_itemStand;

	public GameObject m_activeEffect;

	public EffectList m_activateStep1 = new EffectList();

	public EffectList m_activateStep2 = new EffectList();

	public EffectList m_activateStep3 = new EffectList();

	public string m_completedMessage = "";

	public MeshRenderer m_mesh;

	public int m_emissiveMaterialIndex;

	public Color m_activeEmissiveColor = Color.white;

	private bool m_active;

	private ZNetView m_nview;

	private void Start()
	{
		if (m_mesh.materials[m_emissiveMaterialIndex].HasProperty("_EmissionColor"))
		{
			m_mesh.materials[m_emissiveMaterialIndex].SetColor("_EmissionColor", Color.black);
		}
		if ((bool)m_activeEffect)
		{
			m_activeEffect.SetActive(value: false);
		}
		SetActivated(m_itemStand.HaveAttachment(), triggerEffect: false);
		InvokeRepeating("UpdateVisual", 1f, 1f);
	}

	private void UpdateVisual()
	{
		SetActivated(m_itemStand.HaveAttachment(), triggerEffect: true);
	}

	private void SetActivated(bool active, bool triggerEffect)
	{
		if (active == m_active)
		{
			return;
		}
		m_active = active;
		if (triggerEffect && active)
		{
			Invoke("DelayedAttachEffects_Step1", 1f);
			Invoke("DelayedAttachEffects_Step2", 5f);
			Invoke("DelayedAttachEffects_Step3", 11f);
			return;
		}
		if ((bool)m_activeEffect)
		{
			m_activeEffect.SetActive(active);
		}
		StopCoroutine("FadeEmission");
		StartCoroutine("FadeEmission");
	}

	private void DelayedAttachEffects_Step1()
	{
		m_activateStep1.Create(m_itemStand.transform.position, base.transform.rotation);
	}

	private void DelayedAttachEffects_Step2()
	{
		m_activateStep2.Create(base.transform.position, base.transform.rotation);
	}

	private void DelayedAttachEffects_Step3()
	{
		if ((bool)m_activeEffect)
		{
			m_activeEffect.SetActive(value: true);
		}
		m_activateStep3.Create(base.transform.position, base.transform.rotation);
		StopCoroutine("FadeEmission");
		StartCoroutine("FadeEmission");
		Player.MessageAllInRange(base.transform.position, 20f, MessageHud.MessageType.Center, m_completedMessage);
	}

	private IEnumerator FadeEmission()
	{
		if ((bool)m_mesh && m_mesh.materials[m_emissiveMaterialIndex].HasProperty("_EmissionColor"))
		{
			Color startColor = m_mesh.materials[m_emissiveMaterialIndex].GetColor("_EmissionColor");
			Color targetColor = (m_active ? m_activeEmissiveColor : Color.black);
			for (float t = 0f; t < 1f; t += Time.deltaTime)
			{
				Color value = Color.Lerp(startColor, targetColor, t / 1f);
				m_mesh.materials[m_emissiveMaterialIndex].SetColor("_EmissionColor", value);
				yield return null;
			}
		}
		ZLog.Log("Done fading color");
	}

	public bool IsActivated()
	{
		return m_active;
	}
}
using UnityEngine;
using UnityEngine.PostProcessing;
using UnityStandardAssets.ImageEffects;

public class CameraEffects : MonoBehaviour
{
	private static CameraEffects m_instance;

	public bool m_forceDof;

	public LayerMask m_dofRayMask;

	public bool m_dofAutoFocus;

	public float m_dofMinDistance = 50f;

	public float m_dofMinDistanceShip = 50f;

	public float m_dofMaxDistance = 3000f;

	private PostProcessingBehaviour m_postProcessing;

	private DepthOfField m_dof;

	public static CameraEffects instance => m_instance;

	private void Awake()
	{
		m_instance = this;
		m_postProcessing = GetComponent<PostProcessingBehaviour>();
		m_dof = GetComponent<DepthOfField>();
		GraphicsSettingsManager.GraphicsSettingsChanged += ApplySettings;
		ApplySettings();
	}

	private void OnDestroy()
	{
		GraphicsSettingsManager.GraphicsSettingsChanged -= ApplySettings;
		if (m_instance == this)
		{
			m_instance = null;
		}
	}

	private void ApplySettings()
	{
		GraphicsSettingsState currentSettingsWithCurrentPresetApplied = GraphicsSettingsManager.Instance.GetCurrentSettingsWithCurrentPresetApplied(includeBackground: true);
		SetDof(currentSettingsWithCurrentPresetApplied.m_depthOfField);
		SetBloom(currentSettingsWithCurrentPresetApplied.m_bloom);
		SetSSAO(currentSettingsWithCurrentPresetApplied.m_ssao);
		SetSunShafts(currentSettingsWithCurrentPresetApplied.m_sunShafts);
		SetAntiAliasing(currentSettingsWithCurrentPresetApplied.m_antiAliasing);
		SetCA(currentSettingsWithCurrentPresetApplied.m_chromaticAberration);
		SetMotionBlur(currentSettingsWithCurrentPresetApplied.m_motionBlur);
	}

	public void SetSunShafts(bool enabled)
	{
		SunShafts component = GetComponent<SunShafts>();
		if (component != null)
		{
			component.enabled = enabled;
		}
	}

	private void SetBloom(bool enabled)
	{
		m_postProcessing.profile.bloom.enabled = enabled;
	}

	private void SetSSAO(int value)
	{
		PostProcessingProfile profile = m_postProcessing.profile;
		AmbientOcclusionModel.Settings settings = profile.ambientOcclusion.settings;
		switch (value)
		{
		case 0:
			profile.ambientOcclusion.enabled = false;
			break;
		case 1:
			profile.ambientOcclusion.enabled = true;
			settings.downsampling = true;
			settings.farDistance = 100f;
			settings.sampleCount = AmbientOcclusionModel.SampleCount.Low;
			break;
		default:
			profile.ambientOcclusion.enabled = true;
			settings.downsampling = false;
			settings.farDistance = 150f;
			settings.sampleCount = AmbientOcclusionModel.SampleCount.Medium;
			break;
		}
		profile.ambientOcclusion.settings = settings;
	}

	private void SetMotionBlur(bool enabled)
	{
		m_postProcessing.profile.motionBlur.enabled = enabled;
	}

	private void SetAntiAliasing(bool enabled)
	{
		m_postProcessing.profile.antialiasing.enabled = enabled;
	}

	private void SetCA(bool enabled)
	{
		m_postProcessing.profile.chromaticAberration.enabled = enabled;
	}

	private void SetDof(bool enabled)
	{
		m_dof.enabled = enabled || m_forceDof;
	}

	private void LateUpdate()
	{
		UpdateDOF();
	}

	private bool ControllingShip()
	{
		if (Player.m_localPlayer == null || Player.m_localPlayer.GetControlledShip() != null)
		{
			return true;
		}
		return false;
	}

	private void UpdateDOF()
	{
		if (m_dof.enabled && m_dofAutoFocus)
		{
			float num = m_dofMaxDistance;
			if (Physics.Raycast(base.transform.position, base.transform.forward, out var hitInfo, m_dofMaxDistance, m_dofRayMask))
			{
				num = hitInfo.distance;
			}
			if (ControllingShip() && num < m_dofMinDistanceShip)
			{
				num = m_dofMinDistanceShip;
			}
			if (num < m_dofMinDistance)
			{
				num = m_dofMinDistance;
			}
			m_dof.focalLength = Mathf.Lerp(m_dof.focalLength, num, 0.2f);
		}
	}
}
using System.Collections;
using UnityEngine;

public class CamShaker : MonoBehaviour
{
	public float m_strength = 1f;

	public float m_range = 50f;

	public float m_delay;

	public bool m_continous;

	public float m_continousDuration;

	public bool m_localOnly;

	private void Start()
	{
		if (m_continous)
		{
			if (m_delay <= 0f)
			{
				StartCoroutine("TriggerContinous");
			}
			else
			{
				Invoke("DelayedTriggerContinous", m_delay);
			}
		}
		else if (m_delay <= 0f)
		{
			Trigger();
		}
		else
		{
			Invoke("Trigger", m_delay);
		}
	}

	private void DelayedTriggerContinous()
	{
		StartCoroutine("TriggerContinous");
	}

	private IEnumerator TriggerContinous()
	{
		float t = 0f;
		while (true)
		{
			Trigger();
			t += Time.deltaTime;
			if (m_continousDuration > 0f && t > m_continousDuration)
			{
				break;
			}
			yield return null;
		}
	}

	private void Trigger()
	{
		if (!GameCamera.instance)
		{
			return;
		}
		if (m_localOnly)
		{
			ZNetView component = GetComponent<ZNetView>();
			if ((bool)component && component.IsValid() && !component.IsOwner())
			{
				return;
			}
		}
		GameCamera.instance.AddShake(base.transform.position, m_range, m_strength, m_continous);
	}
}
using System.Collections;

public class CancelableTaskPopup : LivePopupBase
{
	public readonly PopupButtonCallback cancelCallback;

	public override PopupType Type => PopupType.CancelableTask;

	public CancelableTaskPopup(RetrieveFromStringSource headerRetrievalFunc, RetrieveFromStringSource textRetrievalFunc, RetrieveFromBoolSource shouldCloseRetrievalFunc, PopupButtonCallback cancelCallback)
		: base(headerRetrievalFunc, textRetrievalFunc, shouldCloseRetrievalFunc)
	{
		SetUpdateRoutine(UpdateRoutine());
		this.cancelCallback = cancelCallback;
	}

	private IEnumerator UpdateRoutine()
	{
		while (!shouldCloseRetrievalFunc())
		{
			headerText.text = headerRetrievalFunc();
			bodyText.text = textRetrievalFunc();
			yield return null;
		}
		base.ShouldClose = true;
	}
}
using UnityEngine;
using UnityEngine.UI;

public class CaptionArrow : MonoBehaviour
{
	public float m_fadeTime = 1.5f;

	private Vector3 m_sfxPosition;

	private float m_timer;

	public RawImage m_imageComponent;

	private Color m_color;

	private ClosedCaptions.CaptionType m_type;

	private float m_alpha;

	public AnimationCurve m_distanceCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);

	private static readonly int s_CaptionDistance = Shader.PropertyToID("_CaptionDistance");

	public void Setup(ClosedCaptions.CaptionType type, Vector3 position, float distanceFactor = 0f)
	{
		m_alpha = m_imageComponent.color.a;
		m_color = ClosedCaptions.Instance.GetCaptionColor(type);
		m_color.a = m_alpha;
		m_imageComponent.color = m_color;
		m_timer = m_fadeTime;
		m_sfxPosition = position;
		RotateArrow();
		m_imageComponent.material = new Material(m_imageComponent.material);
		m_imageComponent.material.SetFloat(s_CaptionDistance, m_distanceCurve.Evaluate(distanceFactor));
	}

	private void Update()
	{
		m_timer -= Time.deltaTime;
		if (m_timer <= 0f)
		{
			Object.Destroy(base.gameObject);
			return;
		}
		m_color.a = m_alpha * Mathf.Clamp01(m_timer / m_fadeTime);
		m_color.a = Mathf.SmoothStep(0f, 1f, m_color.a);
		m_imageComponent.color = m_color;
		RotateArrow();
	}

	public void RotateArrow()
	{
		Vector3 position = AudioMan.instance.GetActiveAudioListener().transform.position;
		position.y = m_sfxPosition.y;
		Vector3 normalized = Vector3.ProjectOnPlane(Utils.GetMainCamera().transform.forward, Vector3.up).normalized;
		Vector3 to = position.DirTo(m_sfxPosition);
		float num = Vector3.SignedAngle(normalized, to, Vector3.up);
		base.transform.localEulerAngles = new Vector3(0f, 0f, 0f - num);
	}
}
using System;
using TMPro;
using UnityEngine;

public class CaptionItem : MonoBehaviour
{
	public string m_captionText;

	public ClosedCaptions.CaptionType m_type;

	private TextMeshProUGUI m_text;

	private float m_timer;

	private bool m_dying;

	public bool Killed => m_dying;

	public float TimeSinceSpawn { get; private set; }

	public event Action<CaptionItem> OnDestroyingCaption = delegate
	{
	};

	public void Setup()
	{
		m_text = GetComponent<TextMeshProUGUI>();
		m_text.color = ClosedCaptions.Instance.GetCaptionColor(m_type);
		m_text.text = m_captionText ?? "";
		MonoBehaviour.print(Localization.instance);
		Refresh();
	}

	private void OnDestroy()
	{
		this.OnDestroyingCaption?.Invoke(this);
	}

	public void CustomUpdate(float dt)
	{
		m_timer -= dt;
		TimeSinceSpawn += dt;
		if (m_timer <= 0f)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		float a = Mathf.Clamp01(TimeSinceSpawn * 2f);
		float b = Mathf.Clamp01(m_timer * 4f);
		float num = Mathf.Min(a, b);
		Vector3 localScale = base.transform.localScale;
		localScale.y = num;
		localScale.x = 1f;
		localScale.z = 1f;
		base.transform.localScale = localScale;
		m_text.alpha = num;
	}

	public void Refresh()
	{
		if (!m_dying)
		{
			m_timer = ClosedCaptions.Instance.m_captionDuration;
		}
	}

	public void Kill()
	{
		m_dying = true;
		m_timer = Mathf.Min(m_timer, 0.5f);
	}

	public int GetImportance()
	{
		return (int)m_type;
	}
}
