	public TMP_Text m_ping;

	public TMP_Text m_quality;

	private float m_playerListBaseSize;

	private List<GameObject> m_playerListElements = new List<GameObject>();

	public TMP_Text m_serverOptions;

	private int m_frameSamples;

	private float m_frameTimer;

	public static ConnectPanel instance => m_instance;

	private void Start()
	{
		m_instance = this;
		m_root.gameObject.SetActive(value: false);
		m_playerListBaseSize = m_playerList.rect.height;
	}

	public static bool IsVisible()
	{
		if ((bool)m_instance)
		{
			return m_instance.m_root.gameObject.activeSelf;
		}
		return false;
	}

	private void Update()
	{
		if (ZInput.GetKeyDown(KeyCode.F2) || (ZInput.GetButton("JoyLTrigger") && ZInput.GetButton("JoyLBumper") && ZInput.GetButtonDown("JoyBack")))
		{
			m_root.gameObject.SetActive(!m_root.gameObject.activeSelf);
		}
		if (!m_root.gameObject.activeInHierarchy)
		{
			return;
		}
		if (!ZNet.instance.IsServer() && ZNet.GetConnectionStatus() == ZNet.ConnectionStatus.Connected)
		{
			m_serverField.gameObject.SetActive(value: true);
			m_serverField.text = ZNet.GetServerString();
		}
		else
		{
			m_serverField.gameObject.SetActive(value: false);
		}
		m_worldField.text = ZNet.instance.GetWorldName();
		UpdateFps();
		m_serverOptions.text = Localization.instance.Localize(Game.m_serverOptionsSummary);
		m_myPort.gameObject.SetActive(ZNet.instance.IsServer());
		m_myPort.text = ZNet.instance.GetHostPort().ToString();
		m_myUID.text = ZNet.GetUID().ToString();
		if (ZDOMan.instance != null)
		{
			m_zdos.text = ZDOMan.instance.NrOfObjects().ToString();
			ZDOMan.instance.GetAverageStats(out var sentZdos, out var recvZdos);
			m_zdosSent.text = sentZdos.ToString("0.0");
			m_zdosRecv.text = recvZdos.ToString("0.0");
			m_activePeers.text = ZNet.instance.GetNrOfPlayers().ToString();
		}
		m_zdosPool.text = ZDOPool.GetPoolActive() + " / " + ZDOPool.GetPoolSize() + " / " + ZDOPool.GetPoolTotal();
		if ((bool)ZNetScene.instance)
		{
			m_zdosInstances.text = ZNetScene.instance.NrOfInstances().ToString();
		}
		ZNet.instance.GetNetStats(out var localQuality, out var remoteQuality, out var ping, out var outByteSec, out var inByteSec);
		m_dataSent.text = (outByteSec / 1024f).ToString("0.0") + "kb/s";
		m_dataRecv.text = (inByteSec / 1024f).ToString("0.0") + "kb/s";
		m_ping.text = ping.ToString("0") + "ms";
		m_quality.text = (int)(localQuality * 100f) + "% / " + (int)(remoteQuality * 100f) + "%";
		m_clientSendQueue.text = ZDOMan.instance.GetClientChangeQueue().ToString();
		m_nrOfConnections.text = ZNet.instance.GetPeerConnections().ToString();
		string text = "";
		foreach (ZNetPeer connectedPeer in ZNet.instance.GetConnectedPeers())
		{
			text = ((!connectedPeer.IsReady()) ? (text + connectedPeer.m_socket.GetEndPointString() + " connecting \n") : (text + connectedPeer.m_socket.GetEndPointString() + " UID: " + connectedPeer.m_uid + "\n"));
		}
		m_connections.text = text;
		List<ZNet.PlayerInfo> playerList = ZNet.instance.GetPlayerList();
		float num = 16f;
		if (playerList.Count != m_playerListElements.Count)
		{
			foreach (GameObject playerListElement in m_playerListElements)
			{
				Object.Destroy(playerListElement);
			}
			m_playerListElements.Clear();
			for (int i = 0; i < playerList.Count; i++)
			{
				GameObject gameObject = Object.Instantiate(m_playerElement, m_playerList);
				(gameObject.transform as RectTransform).anchoredPosition = new Vector2(0f, (float)i * (0f - num));
				m_playerListElements.Add(gameObject);
			}
			float b = (float)playerList.Count * num;
			b = Mathf.Max(m_playerListBaseSize, b);
			m_playerList.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, b);
			m_playerListScroll.value = 1f;
		}
		for (int j = 0; j < playerList.Count; j++)
		{
			ZNet.PlayerInfo playerInfo = playerList[j];
			TMP_Text component = m_playerListElements[j].transform.Find("name").GetComponent<TMP_Text>();
			TMP_Text component2 = m_playerListElements[j].transform.Find("hostname").GetComponent<TMP_Text>();
			Button component3 = m_playerListElements[j].transform.Find("KickButton").GetComponent<Button>();
			component.text = CensorShittyWords.FilterUGC(playerInfo.m_name, UGCType.CharacterName, playerInfo.m_userInfo.m_id, 0L);
			component2.text = playerInfo.m_userInfo.m_id.ToString();
			component3.gameObject.SetActive(value: false);
		}
		m_connectButton.interactable = ValidHost();
	}

	private void UpdateFps()
	{
		m_frameTimer += Time.deltaTime;
		m_frameSamples++;
		if (m_frameTimer > 1f)
		{
			float num = m_frameTimer / (float)m_frameSamples;
			m_fps.text = (1f / num).ToString("0.0");
			m_frameTime.text = "( " + (num * 1000f).ToString("00.0") + "ms )";
			m_frameSamples = 0;
			m_frameTimer = 0f;
		}
	}

	private bool ValidHost()
	{
		int num = 0;
		try
		{
			num = int.Parse(m_hostPort.text);
		}
		catch
		{
			return false;
		}
		if (string.IsNullOrEmpty(m_hostName.text) || num == 0)
		{
			return false;
		}
		return true;
	}
}
using TMPro;
using UnityEngine;

public class Console : Terminal
{
	private static Console m_instance;

	private static bool m_consoleEnabled;

	private static bool m_consoleEnabledPermanent;

	public TMP_Text m_devTest;

	public static Console instance => m_instance;

	protected override Terminal m_terminalInstance => m_instance;

	public override void Awake()
	{
		LoadQuickSelect();
		base.Awake();
		m_instance = this;
		AddString("Valheim " + Version.GetVersionString() + " (network version " + 36u + ")");
		AddString("");
		AddString("type \"help\" - for commands");
		AddString("");
		m_chatWindow.gameObject.SetActive(value: false);
		SetConsoleEnabled(PlatformPrefs.GetInt("EnableConsole") == 1);
	}

	public override void Update()
	{
		m_focused = false;
		if ((bool)ZNet.instance && ZNet.instance.InPasswordDialog())
		{
			m_chatWindow.gameObject.SetActive(value: false);
		}
		else
		{
			if (!IsConsoleEnabled())
			{
				return;
			}
			if (ZInput.GetButtonDown("Console") || (IsVisible() && ZInput.GetKeyDown(KeyCode.Escape)) || (IsVisible() && ZInput.GetButtonDown("JoyButtonB")) || (ZInput.GetButton("JoyLTrigger") && ZInput.GetButton("JoyLBumper") && ZInput.GetButtonDown("JoyStart")))
			{
				m_chatWindow.gameObject.SetActive(!m_chatWindow.gameObject.activeSelf);
				if (ZInput.IsGamepadActive())
				{
					AddString("Gamepad console controls:\n   A: Enter text when empty (only in big picture mode), or send text when not.\n   LB: Erase.\n   DPad up/down: Cycle history.\n   DPad right: Autocomplete.\n   DPad left: Show commands (help).\n   Left Stick: Scroll.\n   RStick + LStick: show/hide console.\n   X+DPad: Save quick select option.\n   Y+DPad: Load quick select option.");
				}
				if (m_chatWindow.gameObject.activeInHierarchy)
				{
					m_input.ActivateInputField();
				}
			}
			if (m_chatWindow.gameObject.activeInHierarchy)
			{
				m_focused = true;
			}
			if (m_focused)
			{
				if (ZInput.GetButtonDown("JoyTabLeft") && m_input.text.Length > 0)
				{
					m_input.text = m_input.text.Substring(0, m_input.text.Length - 1);
				}
				else if (ZInput.GetButtonDown("JoyDPadLeft"))
				{
					TryRunCommand("help");
				}
			}
			if ((bool)instance && Terminal.m_threadSafeConsoleLog.TryDequeue(out var result))
			{
				instance.AddString(result);
			}
			if ((bool)Player.m_localPlayer && Terminal.m_threadSafeMessages.TryDequeue(out var result2))
			{
				Player.m_localPlayer.Message(MessageHud.MessageType.TopLeft, result2);
			}
			base.Update();
			if (ZInput.GetButtonDown("JoyDPadLeft") && !ZInput.GetButton("JoyButtonX") && !ZInput.GetButton("JoyButtonY"))
			{
				TryRunCommand("help");
			}
		}
	}

	public static bool IsVisible()
	{
		if ((bool)m_instance)
		{
			return m_instance.m_chatWindow.gameObject.activeInHierarchy;
		}
		return false;
	}

	public void Print(string text)
	{
		AddString(text);
	}

	public bool IsConsoleEnabled()
	{
		return m_consoleEnabled;
	}

	public static void SetConsoleEnabled(bool enabled)
	{
		m_consoleEnabled = enabled || m_consoleEnabledPermanent;
	}

	public static void SetConsoleEnabledForThisSession()
	{
		m_consoleEnabled = true;
		m_consoleEnabledPermanent = true;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Container : MonoBehaviour, Hoverable, Interactable
{
	public enum PrivacySetting
	{
		Private,
		Group,
		Public
	}

	private float m_lastTakeAllTime;

	public Action m_onTakeAllSuccess;

	public string m_name = "Container";

	public Sprite m_bkg;

	public int m_width = 3;

	public int m_height = 2;

	public PrivacySetting m_privacy = PrivacySetting.Public;

	public bool m_checkGuardStone;

	public bool m_autoDestroyEmpty;

	public DropTable m_defaultItems = new DropTable();

	public GameObject m_open;

	public GameObject m_closed;

	public EffectList m_openEffects = new EffectList();

	public EffectList m_closeEffects = new EffectList();

	public ZNetView m_rootObjectOverride;

	public Vagon m_wagon;

	public GameObject m_destroyedLootPrefab;

	private Inventory m_inventory;

	private ZNetView m_nview;

	private Piece m_piece;

	private bool m_inUse;

	private bool m_loading;

	private uint m_lastRevision = uint.MaxValue;

	private string m_lastDataString;

	private void Awake()
	{
		m_nview = (m_rootObjectOverride ? m_rootObjectOverride.GetComponent<ZNetView>() : GetComponent<ZNetView>());
		if (m_nview.GetZDO() != null)
		{
			m_inventory = new Inventory(m_name, m_bkg, m_width, m_height);
			Inventory inventory = m_inventory;
			inventory.m_onChanged = (Action)Delegate.Combine(inventory.m_onChanged, new Action(OnContainerChanged));
			m_piece = GetComponent<Piece>();
			if ((bool)m_nview)
			{
				m_nview.Register<long>("RequestOpen", RPC_RequestOpen);
				m_nview.Register<bool>("OpenRespons", RPC_OpenRespons);
				m_nview.Register<long>("RPC_RequestStack", RPC_RequestStack);
				m_nview.Register<bool>("RPC_StackResponse", RPC_StackResponse);
				m_nview.Register<long>("RequestTakeAll", RPC_RequestTakeAll);
				m_nview.Register<bool>("TakeAllRespons", RPC_TakeAllRespons);
			}
			WearNTear wearNTear = (m_rootObjectOverride ? m_rootObjectOverride.GetComponent<WearNTear>() : GetComponent<WearNTear>());
			if ((bool)wearNTear)
			{
				wearNTear.m_onDestroyed = (Action)Delegate.Combine(wearNTear.m_onDestroyed, new Action(OnDestroyed));
			}
			Destructible destructible = (m_rootObjectOverride ? m_rootObjectOverride.GetComponent<Destructible>() : GetComponent<Destructible>());
			if ((bool)destructible)
			{
				destructible.m_onDestroyed = (Action)Delegate.Combine(destructible.m_onDestroyed, new Action(OnDestroyed));
			}
			if (m_nview.IsOwner() && !m_nview.GetZDO().GetBool(ZDOVars.s_addedDefaultItems))
			{
				AddDefaultItems();
				m_nview.GetZDO().Set(ZDOVars.s_addedDefaultItems, value: true);
			}
			InvokeRepeating("CheckForChanges", 0f, 1f);
		}
	}

	private void AddDefaultItems()
	{
		foreach (ItemDrop.ItemData dropListItem in m_defaultItems.GetDropListItems())
		{
			m_inventory.AddItem(dropListItem);
		}
	}

	private void DropAllItems(GameObject lootContainerPrefab)
	{
		while (m_inventory.NrOfItems() > 0)
		{
			Vector3 position = base.transform.position + UnityEngine.Random.insideUnitSphere * 1f;
			UnityEngine.Object.Instantiate(lootContainerPrefab, position, UnityEngine.Random.rotation).GetComponent<Container>().GetInventory()
				.MoveAll(m_inventory);
		}
	}

	private void DropAllItems()
	{
		List<ItemDrop.ItemData> allItems = m_inventory.GetAllItems();
		int num = 1;
		foreach (ItemDrop.ItemData item in allItems)
		{
			Vector3 position = base.transform.position + Vector3.up * 0.5f + UnityEngine.Random.insideUnitSphere * 0.3f;
			Quaternion rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
			ItemDrop.DropItem(item, 0, position, rotation);
			num++;
		}
		m_inventory.RemoveAll();
		Save();
	}

	private void OnDestroyed()
	{
		if (m_nview.IsOwner())
		{
			if ((bool)m_destroyedLootPrefab)
			{
				DropAllItems(m_destroyedLootPrefab);
			}
			else
			{
				DropAllItems();
			}
		}
	}

	private void CheckForChanges()
	{
		if (m_nview.IsValid() && Load())
		{
			UpdateUseVisual();
			if (m_autoDestroyEmpty && m_nview.IsOwner() && !IsInUse() && m_inventory.NrOfItems() == 0)
			{
				m_nview.Destroy();
			}
		}
	}

	private void UpdateUseVisual()
	{
		bool flag;
		if (m_nview.IsOwner())
		{
			flag = m_inUse;
			m_nview.GetZDO().Set(ZDOVars.s_inUse, m_inUse ? 1 : 0);
		}
		else
		{
			flag = m_nview.GetZDO().GetInt(ZDOVars.s_inUse) == 1;
		}
		if ((bool)m_open)
		{
			m_open.SetActive(flag);
		}
		if ((bool)m_closed)
		{
			m_closed.SetActive(!flag);
		}
	}

	public string GetHoverText()
	{
		if (m_checkGuardStone && !PrivateArea.CheckAccess(base.transform.position, 0f, flash: false))
		{
			return Localization.instance.Localize(m_name + "\n$piece_noaccess");
		}
		string text = ((m_inventory.NrOfItems() != 0) ? m_name : (m_name + " ( $piece_container_empty )"));
		text += "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_container_open $msg_stackall_hover";
		return Localization.instance.Localize(text);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		if (m_checkGuardStone && !PrivateArea.CheckAccess(base.transform.position))
		{
			return true;
		}
		long playerID = Game.instance.GetPlayerProfile().GetPlayerID();
		if (!CheckAccess(playerID))
		{
			character.Message(MessageHud.MessageType.Center, "$msg_cantopen");
			return true;
		}
		m_nview.InvokeRPC("RequestOpen", playerID);
		return true;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	public bool CanBeRemoved()
	{
		if (m_privacy == PrivacySetting.Private && GetInventory().NrOfItems() > 0)
		{
			return false;
		}
		return true;
	}

	private bool CheckAccess(long playerID)
	{
		return m_privacy switch
		{
			PrivacySetting.Public => true, 
			PrivacySetting.Private => m_piece.GetCreator() == playerID, 
			PrivacySetting.Group => false, 
			_ => false, 
		};
	}

	public bool IsOwner()
	{
		return m_nview.IsOwner();
	}

	public bool IsInUse()
	{
		return m_inUse;
	}

	public void SetInUse(bool inUse)
	{
		if (m_nview.IsOwner() && m_inUse != inUse)
		{
			m_inUse = inUse;
			UpdateUseVisual();
			if (inUse)
			{
				m_openEffects.Create(base.transform.position, base.transform.rotation);
			}
			else
			{
				m_closeEffects.Create(base.transform.position, base.transform.rotation);
			}
		}
	}

	public Inventory GetInventory()
	{
		return m_inventory;
	}

	private void RPC_RequestOpen(long uid, long playerID)
	{
		ZLog.Log("Player " + uid + " wants to open " + base.gameObject.name + "   im: " + ZDOMan.GetSessionID());
		if (!m_nview.IsOwner())
		{
			ZLog.Log("  but im not the owner");
		}
		else if ((IsInUse() || ((bool)m_wagon && m_wagon.InUse())) && uid != ZNet.GetUID())
		{
			ZLog.Log("  in use");
			m_nview.InvokeRPC(uid, "OpenRespons", false);
		}
		else if (!CheckAccess(playerID))
		{
			ZLog.Log("  not yours");
			m_nview.InvokeRPC(uid, "OpenRespons", false);
		}
		else
		{
			ZDOMan.instance.ForceSendZDO(uid, m_nview.GetZDO().m_uid);
			m_nview.GetZDO().SetOwner(uid);
			m_nview.InvokeRPC(uid, "OpenRespons", true);
		}
	}

	private void RPC_OpenRespons(long uid, bool granted)
	{
		if ((bool)Player.m_localPlayer)
		{
			if (granted)
			{
				InventoryGui.instance.Show(this);
			}
			else
			{
				Player.m_localPlayer.Message(MessageHud.MessageType.Center, "$msg_inuse");
			}
		}
	}

	public void StackAll()
	{
		long playerID = Game.instance.GetPlayerProfile().GetPlayerID();
		m_nview.InvokeRPC("RPC_RequestStack", playerID);
	}

	private void RPC_RequestStack(long uid, long playerID)
	{
		ZLog.Log("Player " + uid + " wants to stack all in " + base.gameObject.name + "   im: " + ZDOMan.GetSessionID());
		if (!m_nview.IsOwner())
		{
			ZLog.Log("  but im not the owner");
		}
		else if ((IsInUse() || ((bool)m_wagon && m_wagon.InUse())) && uid != ZNet.GetUID())
		{
			ZLog.Log("  in use");
			m_nview.InvokeRPC(uid, "RPC_StackResponse", false);
		}
		else if (!CheckAccess(playerID))
		{
			ZLog.Log("  not yours");
			m_nview.InvokeRPC(uid, "RPC_StackResponse", false);
		}
		else
		{
			ZDOMan.instance.ForceSendZDO(uid, m_nview.GetZDO().m_uid);
			m_nview.GetZDO().SetOwner(uid);
			m_nview.InvokeRPC(uid, "RPC_StackResponse", true);
		}
	}

	private void RPC_StackResponse(long uid, bool granted)
	{
		if (!Player.m_localPlayer)
		{
			return;
		}
		if (granted)
		{
			if (m_inventory.StackAll(Player.m_localPlayer.GetInventory(), message: true) > 0)
			{
				InventoryGui.instance.m_moveItemEffects.Create(base.transform.position, Quaternion.identity);
			}
		}
		else
		{
			Player.m_localPlayer.Message(MessageHud.MessageType.Center, "$msg_inuse");
		}
	}

	public bool TakeAll(Humanoid character)
	{
		if (m_checkGuardStone && !PrivateArea.CheckAccess(base.transform.position))
		{
			return false;
		}
		long playerID = Game.instance.GetPlayerProfile().GetPlayerID();
		if (!CheckAccess(playerID))
		{
			character.Message(MessageHud.MessageType.Center, "$msg_cantopen");
			return false;
		}
		m_nview.InvokeRPC("RequestTakeAll", playerID);
		return true;
	}

	private void RPC_RequestTakeAll(long uid, long playerID)
	{
		ZLog.Log("Player " + uid + " wants to takeall from " + base.gameObject.name + "   im: " + ZDOMan.GetSessionID());
		if (!m_nview.IsOwner())
		{
			ZLog.Log("  but im not the owner");
		}
		else if ((IsInUse() || ((bool)m_wagon && m_wagon.InUse())) && uid != ZNet.GetUID())
		{
			ZLog.Log("  in use");
			m_nview.InvokeRPC(uid, "TakeAllRespons", false);
		}
		else if (!CheckAccess(playerID))
		{
			ZLog.Log("  not yours");
			m_nview.InvokeRPC(uid, "TakeAllRespons", false);
		}
		else if (!(Time.time - m_lastTakeAllTime < 2f))
		{
			m_lastTakeAllTime = Time.time;
			m_nview.InvokeRPC(uid, "TakeAllRespons", true);
		}
	}

	private void RPC_TakeAllRespons(long uid, bool granted)
	{
		if (!Player.m_localPlayer)
		{
			return;
		}
		if (granted)
		{
			m_nview.ClaimOwnership();
			ZDOMan.instance.ForceSendZDO(uid, m_nview.GetZDO().m_uid);
			Player.m_localPlayer.GetInventory().MoveAll(m_inventory);
			if (m_onTakeAllSuccess != null)
			{
				m_onTakeAllSuccess();
			}
		}
		else
		{
			Player.m_localPlayer.Message(MessageHud.MessageType.Center, "$msg_inuse");
		}
	}

	private void OnContainerChanged()
	{
		if (!m_loading && IsOwner())
		{
			Save();
		}
	}

	private void Save()
	{
		ZPackage zPackage = new ZPackage();
		m_inventory.Save(zPackage);
		string @base = zPackage.GetBase64();
		m_nview.GetZDO().Set(ZDOVars.s_items, @base);
		m_lastRevision = m_nview.GetZDO().DataRevision;
		m_lastDataString = @base;
	}

	private bool Load()
	{
		if (m_nview.GetZDO().DataRevision == m_lastRevision)
		{
			return false;
		}
		m_lastRevision = m_nview.GetZDO().DataRevision;
		string text = m_nview.GetZDO().GetString(ZDOVars.s_items);
		if (text == m_lastDataString)
		{
			m_lastDataString = text;
			return true;
		}
		if (string.IsNullOrEmpty(text))
		{
			m_lastDataString = text;
			return true;
		}
		ZPackage pkg = new ZPackage(text);
		m_loading = true;
		m_inventory.Load(pkg);
		m_loading = false;
		m_lastDataString = text;
		return true;
	}
}
using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.Rendering;

public class CookingStation : MonoBehaviour, Interactable, Hoverable, IHasHoverMenuExtended
{
	[Serializable]
	public class ItemConversion
	{
		public ItemDrop m_from;

		public ItemDrop m_to;

		public float m_cookTime = 10f;
	}

	[Serializable]
	public class ItemMessage
	{
		public ItemDrop m_item;

		public string m_message;
	}

	private enum Status
	{
		NotDone,
		Done,
		Burnt
	}

	public Switch m_addFoodSwitch;

	public Switch m_addFuelSwitch;

	public EffectList m_addEffect = new EffectList();

	public EffectList m_doneEffect = new EffectList();

	public EffectList m_overcookedEffect = new EffectList();

	public EffectList m_pickEffector = new EffectList();

	public string m_addItemTooltip = "$piece_cstand_cook";

	public Transform m_spawnPoint;

	public float m_spawnForce = 5f;

	public ItemDrop m_overCookedItem;

	public List<ItemConversion> m_conversion = new List<ItemConversion>();

	public List<ItemMessage> m_incompatibleItems = new List<ItemMessage>();

	public Transform[] m_slots;

	public ParticleSystem[] m_donePS;

	public ParticleSystem[] m_burntPS;

	public string m_name = "";

	public bool m_requireFire = true;

	public Transform[] m_fireCheckPoints;

	public float m_fireCheckRadius = 0.25f;

	public bool m_useFuel;

	public ItemDrop m_fuelItem;

	public int m_maxFuel = 10;

	public int m_secPerFuel = 5000;

	public EffectList m_fuelAddedEffects = new EffectList();

	public GameObject m_haveFuelObject;

	public GameObject m_haveFireObject;

	private bool m_cheapFireCheck;

	private ZNetView m_nview;

	private ParticleSystem[] m_ps;

	private AudioSource[] m_as;

	private void Awake()
	{
		m_nview = base.gameObject.GetComponent<ZNetView>();
		if (m_nview.GetZDO() != null)
		{
			m_ps = new ParticleSystem[m_slots.Length];
			m_as = new AudioSource[m_slots.Length];
			for (int i = 0; i < m_slots.Length; i++)
			{
				m_ps[i] = m_slots[i].GetComponent<ParticleSystem>();
				m_as[i] = m_slots[i].GetComponent<AudioSource>();
			}
			m_nview.Register<Vector3, int>("RPC_RemoveDoneItem", RPC_RemoveDoneItem);
			m_nview.Register<string>("RPC_AddItem", RPC_AddItem);
			m_nview.Register("RPC_AddFuel", RPC_AddFuel);
			m_nview.Register<int, string>("RPC_SetSlotVisual", RPC_SetSlotVisual);
			if ((bool)m_addFoodSwitch)
			{
				m_addFoodSwitch.m_onUse = OnAddFoodSwitch;
				m_addFoodSwitch.m_hoverText = HoverText();
			}
			if ((bool)m_addFuelSwitch)
			{
				m_addFuelSwitch.m_onUse = OnAddFuelSwitch;
				m_addFuelSwitch.m_onHover = OnHoverFuelSwitch;
			}
			WearNTear component = GetComponent<WearNTear>();
			if ((bool)component)
			{
				component.m_onDestroyed = (Action)Delegate.Combine(component.m_onDestroyed, new Action(OnDestroyed));
			}
			m_cheapFireCheck = m_fireCheckRadius == 0.25f;
			InvokeRepeating("UpdateCooking", 0f, 1f);
		}
	}

	private void DropAllItems()
	{
		if (m_fuelItem != null)
		{
			float fuel = GetFuel();
			for (int i = 0; i < (int)fuel; i++)
			{
				drop(m_fuelItem);
			}
			SetFuel(0f);
		}
		for (int j = 0; j < m_slots.Length; j++)
		{
			GetSlot(j, out var itemName, out var _, out var status);
			if (!(itemName != ""))
			{
				continue;
			}
			switch (status)
			{
			case Status.Done:
				drop(GetItemConversion(itemName).m_to);
				break;
			case Status.Burnt:
				drop(m_overCookedItem);
				break;
			case Status.NotDone:
			{
				GameObject prefab = ZNetScene.instance.GetPrefab(itemName);
				if (prefab != null)
				{
					ItemDrop component = prefab.GetComponent<ItemDrop>();
					if ((bool)component)
					{
						drop(component);
					}
				}
				break;
			}
			}
			SetSlot(j, "", 0f, Status.NotDone);
		}
		void drop(ItemDrop item)
		{
			Vector3 position = base.transform.position + Vector3.up + UnityEngine.Random.insideUnitSphere * 0.3f;
			Quaternion rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
			ItemDrop.OnCreateNew(UnityEngine.Object.Instantiate(item.gameObject, position, rotation));
		}
	}

	private void OnDestroyed()
	{
		if (m_nview.IsOwner())
		{
			DropAllItems();
		}
	}

	private void UpdateCooking()
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		bool flag = (m_requireFire && IsFireLit()) || (m_useFuel && GetFuel() > 0f);
		if (m_nview.IsOwner())
		{
			float deltaTime = GetDeltaTime();
			if (flag)
			{
				UpdateFuel(deltaTime);
				for (int i = 0; i < m_slots.Length; i++)
				{
					GetSlot(i, out var itemName, out var cookedTime, out var status);
					if (!(itemName != "") || status == Status.Burnt)
					{
						continue;
					}
					ItemConversion itemConversion = GetItemConversion(itemName);
					if (itemConversion == null)
					{
						SetSlot(i, "", 0f, Status.NotDone);
						continue;
					}
					cookedTime += deltaTime;
					if (cookedTime > itemConversion.m_cookTime * 2f)
					{
						m_overcookedEffect.Create(m_slots[i].position, Quaternion.identity);
						SetSlot(i, m_overCookedItem.name, cookedTime, Status.Burnt);
					}
					else if (cookedTime > itemConversion.m_cookTime && itemName == itemConversion.m_from.name)
					{
						m_doneEffect.Create(m_slots[i].position, Quaternion.identity);
						SetSlot(i, itemConversion.m_to.name, cookedTime, Status.Done);
					}
					else
					{
						SetSlot(i, itemName, cookedTime, status);
					}
				}
			}
		}
		UpdateVisual(flag);
	}

	private float GetDeltaTime()
	{
		DateTime time = ZNet.instance.GetTime();
		DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_startTime, time.Ticks));
		double totalSeconds = (time - dateTime).TotalSeconds;
		m_nview.GetZDO().Set(ZDOVars.s_startTime, time.Ticks);
		return (float)totalSeconds;
	}

	private void UpdateFuel(float dt)
	{
		if (m_useFuel)
		{
			float num = dt / (float)m_secPerFuel;
			float fuel = GetFuel();
			fuel -= num;
			if (fuel < 0f)
			{
				fuel = 0f;
			}
			SetFuel(fuel);
		}
	}

	private void UpdateVisual(bool fireLit)
	{
		for (int i = 0; i < m_slots.Length; i++)
		{
			GetSlot(i, out var itemName, out var _, out var status);
			SetSlotVisual(i, itemName, fireLit, status);
		}
		if (m_useFuel)
		{
			bool active = GetFuel() > 0f;
			if ((bool)m_haveFireObject)
			{
				m_haveFireObject.SetActive(fireLit);
			}
			if ((bool)m_haveFuelObject)
			{
				m_haveFuelObject.SetActive(active);
			}
		}
	}

	private void RPC_SetSlotVisual(long sender, int slot, string item)
	{
		SetSlotVisual(slot, item, fireLit: false, Status.NotDone);
	}

	private void SetSlotVisual(int i, string item, bool fireLit, Status status)
	{
		if (item == "")
		{
			ParticleSystem.EmissionModule emission = m_ps[i].emission;
			emission.enabled = false;
			if (m_burntPS.Length != 0)
			{
				ParticleSystem.EmissionModule emission2 = m_burntPS[i].emission;
				emission2.enabled = false;
			}
			if (m_donePS.Length != 0)
			{
				ParticleSystem.EmissionModule emission3 = m_donePS[i].emission;
				emission3.enabled = false;
			}
			m_as[i].mute = true;
			if (m_slots[i].childCount > 0)
			{
				UnityEngine.Object.Destroy(m_slots[i].GetChild(0).gameObject);
			}
			return;
		}
		ParticleSystem.EmissionModule emission4 = m_ps[i].emission;
		emission4.enabled = fireLit && status != Status.Burnt;
		if (m_burntPS.Length != 0)
		{
			ParticleSystem.EmissionModule emission5 = m_burntPS[i].emission;
			emission5.enabled = fireLit && status == Status.Burnt;
		}
		if (m_donePS.Length != 0)
		{
			ParticleSystem.EmissionModule emission6 = m_donePS[i].emission;
			emission6.enabled = fireLit && status == Status.Done;
		}
		m_as[i].mute = !fireLit;
		if (m_slots[i].childCount == 0 || m_slots[i].GetChild(0).name != item)
		{
			if (m_slots[i].childCount > 0)
			{
				UnityEngine.Object.Destroy(m_slots[i].GetChild(0).gameObject);
			}
			Transform obj = ObjectDB.instance.GetItemPrefab(item).transform.Find("attach");
			Transform transform = m_slots[i];
			GameObject obj2 = UnityEngine.Object.Instantiate(obj.gameObject, transform.position, transform.rotation, transform);
			obj2.name = item;
			Renderer[] componentsInChildren = obj2.GetComponentsInChildren<Renderer>();
			for (int j = 0; j < componentsInChildren.Length; j++)
			{
				componentsInChildren[j].shadowCastingMode = ShadowCastingMode.Off;
			}
		}
	}

	private void RPC_RemoveDoneItem(long sender, Vector3 userPoint, int amount)
	{
		for (int i = 0; i < m_slots.Length; i++)
		{
			GetSlot(i, out var itemName, out var _, out var _);
			if (itemName != "" && IsItemDone(itemName))
			{
				for (int j = 0; j < amount; j++)
				{
					SpawnItem(itemName, i, userPoint);
				}
				SetSlot(i, "", 0f, Status.NotDone);
				m_nview.InvokeRPC(ZNetView.Everybody, "RPC_SetSlotVisual", i, "");
				break;
			}
		}
	}

	private bool HaveDoneItem()
	{
		for (int i = 0; i < m_slots.Length; i++)
		{
			GetSlot(i, out var itemName, out var _, out var _);
			if (itemName != "" && IsItemDone(itemName))
			{
				return true;
			}
		}
		return false;
	}

	private bool IsItemDone(string itemName)
	{
		if (itemName == m_overCookedItem.name)
		{
			return true;
		}
		ItemConversion itemConversion = GetItemConversion(itemName);
		if (itemConversion == null)
		{
			return false;
		}
		if (itemName == itemConversion.m_to.name)
		{
			return true;
		}
		return false;
	}

	private void SpawnItem(string name, int slot, Vector3 userPoint)
	{
		GameObject itemPrefab = ObjectDB.instance.GetItemPrefab(name);
		Vector3 vector;
		Vector3 vector2;
		if (m_spawnPoint != null)
		{
			vector = m_spawnPoint.position;
			vector2 = m_spawnPoint.forward;
		}
		else
		{
			Vector3 position = m_slots[slot].position;
			Vector3 vector3 = userPoint - position;
			vector3.y = 0f;
			vector3.Normalize();
			vector = position + vector3 * 0.5f;
			vector2 = vector3;
		}
		Quaternion rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
		GameObject obj = UnityEngine.Object.Instantiate(itemPrefab, vector, rotation);
		ItemDrop.OnCreateNew(obj);
		obj.GetComponent<Rigidbody>().linearVelocity = vector2 * m_spawnForce;
		m_pickEffector.Create(vector, Quaternion.identity);
	}

	public string GetHoverText()
	{
		if (m_addFoodSwitch != null)
		{
			return "";
		}
		return Localization.instance.Localize(HoverText());
	}

	private string HoverText()
	{
		return m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] " + m_addItemTooltip + (ZInput.GamepadActive ? "" : ("\n[<color=yellow><b>1-8</b></color>] " + m_addItemTooltip));
	}

	public string GetHoverName()
	{
		return m_name;
	}

	private bool OnAddFuelSwitch(Switch sw, Humanoid user, ItemDrop.ItemData item)
	{
		if (item != null && item.m_shared.m_name != m_fuelItem.m_itemData.m_shared.m_name)
		{
			user.Message(MessageHud.MessageType.Center, "$msg_wrongitem");
			return false;
		}
		if (GetFuel() > (float)(m_maxFuel - 1))
		{
			user.Message(MessageHud.MessageType.Center, "$msg_itsfull");
			return false;
		}
		if (!user.GetInventory().HaveItem(m_fuelItem.m_itemData.m_shared.m_name))
		{
			user.Message(MessageHud.MessageType.Center, "$msg_donthaveany " + m_fuelItem.m_itemData.m_shared.m_name);
			return false;
		}
		user.Message(MessageHud.MessageType.Center, "$msg_added " + m_fuelItem.m_itemData.m_shared.m_name);
		user.GetInventory().RemoveItem(m_fuelItem.m_itemData.m_shared.m_name, 1);
		m_nview.InvokeRPC("RPC_AddFuel");
		return true;
	}

	private void RPC_AddFuel(long sender)
	{
		if (m_nview.IsOwner())
		{
			ZLog.Log("Add fuel");
			float fuel = GetFuel();
			SetFuel(fuel + 1f);
			m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation, base.transform);
		}
	}

	private string OnHoverFuelSwitch()
	{
		float fuel = GetFuel();
		Localization instance = Localization.instance;
		string[] obj = new string[9]
		{
			m_name,
			" (",
			m_fuelItem.m_itemData.m_shared.m_name,
			" ",
			Mathf.Ceil(fuel).ToString(),
			"/",
			null,
			null,
			null
		};
		int maxFuel = m_maxFuel;
		obj[6] = maxFuel.ToString();
		obj[7] = ")\n[<color=yellow><b>$KEY_Use</b></color>] $piece_smelter_add ";
		obj[8] = m_fuelItem.m_itemData.m_shared.m_name;
		return instance.Localize(string.Concat(obj));
	}

	private bool OnAddFoodSwitch(Switch caller, Humanoid user, ItemDrop.ItemData item)
	{
		ZLog.Log("add food switch");
		if (item != null)
		{
			return OnUseItem(user, item);
		}
		return OnInteract(user);
	}

	public bool Interact(Humanoid user, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		if (m_addFoodSwitch != null)
		{
			return false;
		}
		return OnInteract(user);
	}

	private bool OnInteract(Humanoid user)
	{
		if (HaveDoneItem())
		{
			Player.m_localPlayer.RaiseSkill(Skills.SkillType.Cooking, 0.6f);
			int num = 1;
			float skillFactor = Player.m_localPlayer.GetSkillFactor(Skills.SkillType.Cooking);
			if (UnityEngine.Random.value < skillFactor * InventoryGui.instance.m_craftBonusChance)
			{
				num += InventoryGui.instance.m_craftBonusAmount;
				DamageText.instance.ShowText(DamageText.TextType.Bonus, base.transform.position + Vector3.up, "+" + InventoryGui.instance.m_craftBonusAmount, player: true);
				InventoryGui.instance.m_craftBonusEffect.Create(base.transform.position, Quaternion.identity);
				ZLog.Log("Bonus food cooking station!");
			}
			m_nview.InvokeRPC("RPC_RemoveDoneItem", user.transform.position, num);
			return true;
		}
		ItemDrop.ItemData itemData = FindCookableItem(user.GetInventory());
		if (itemData == null)
		{
			ItemMessage itemMessage = FindIncompatibleItem(user.GetInventory());
			if (itemMessage != null)
			{
				user.Message(MessageHud.MessageType.Center, itemMessage.m_message + " " + itemMessage.m_item.m_itemData.m_shared.m_name);
			}
			else
			{
				user.Message(MessageHud.MessageType.Center, "$msg_nocookitems");
			}
			return false;
		}
		if (OnUseItem(user, itemData))
		{
			Player.m_localPlayer.RaiseSkill(Skills.SkillType.Cooking, 0.4f);
			return true;
		}
		return false;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		if (m_addFoodSwitch != null)
		{
			return false;
		}
		return OnUseItem(user, item);
	}

	private bool OnUseItem(Humanoid user, ItemDrop.ItemData item)
	{
		if (m_requireFire && !IsFireLit())
		{
			user.Message(MessageHud.MessageType.Center, "$msg_needfire");
			user.UseIemBlockkMessage();
			return false;
		}
		if (GetFreeSlot() == -1)
		{
			user.Message(MessageHud.MessageType.Center, "$msg_nocookroom");
			user.UseIemBlockkMessage();
			return false;
		}
		return CookItem(user, item);
	}

	private bool IsFireLit()
	{
		if (m_fireCheckPoints != null && m_fireCheckPoints.Length != 0)
		{
			Transform[] fireCheckPoints = m_fireCheckPoints;
			foreach (Transform transform in fireCheckPoints)
			{
				if (m_cheapFireCheck)
				{
					if (!EffectArea.IsPointPlus025InsideBurningArea(transform.position))
					{
						return false;
					}
				}
				else if (!EffectArea.IsPointInsideArea(transform.position, EffectArea.Type.Burning, m_fireCheckRadius))
				{
					return false;
				}
			}
			return true;
		}
		if (m_cheapFireCheck)
		{
			return EffectArea.IsPointPlus025InsideBurningArea(base.transform.position);
		}
		return EffectArea.IsPointInsideArea(base.transform.position, EffectArea.Type.Burning, m_fireCheckRadius);
	}

	private ItemDrop.ItemData FindCookableItem(Inventory inventory)
	{
		foreach (ItemConversion item2 in m_conversion)
		{
			ItemDrop.ItemData item = inventory.GetItem(item2.m_from.m_itemData.m_shared.m_name);
			if (item != null)
			{
				return item;
			}
		}
		return null;
	}

	private ItemMessage FindIncompatibleItem(Inventory inventory)
	{
		foreach (ItemMessage incompatibleItem in m_incompatibleItems)
		{
			if (inventory.GetItem(incompatibleItem.m_item.m_itemData.m_shared.m_name) != null)
			{
				return incompatibleItem;
			}
		}
		return null;
	}

	private bool CookItem(Humanoid user, ItemDrop.ItemData item)
	{
		string text = item.m_dropPrefab.name;
		if (!m_nview.HasOwner())
		{
			m_nview.ClaimOwnership();
		}
		foreach (ItemMessage incompatibleItem in m_incompatibleItems)
		{
			if (incompatibleItem.m_item.m_itemData.m_shared.m_name == item.m_shared.m_name)
			{
				user.Message(MessageHud.MessageType.Center, incompatibleItem.m_message + " " + incompatibleItem.m_item.m_itemData.m_shared.m_name);
				return true;
			}
		}
		if (!IsItemAllowed(item))
		{
			return false;
		}
		if (GetFreeSlot() == -1)
		{
			return false;
		}
		user.GetInventory().RemoveOneItem(item);
		m_nview.InvokeRPC("RPC_AddItem", text);
		return true;
	}

	private void RPC_AddItem(long sender, string itemName)
	{
		if (IsItemAllowed(itemName))
		{
			int freeSlot = GetFreeSlot();
			if (freeSlot != -1)
			{
				SetSlot(freeSlot, itemName, 0f, Status.NotDone);
				m_nview.InvokeRPC(ZNetView.Everybody, "RPC_SetSlotVisual", freeSlot, itemName);
				m_addEffect.Create(m_slots[freeSlot].position, Quaternion.identity);
			}
		}
	}

	private void SetSlot(int slot, string itemName, float cookedTime, Status status)
	{
		if (m_nview.IsValid())
		{
			m_nview.GetZDO().Set("slot" + slot, itemName);
			m_nview.GetZDO().Set("slot" + slot, cookedTime);
			m_nview.GetZDO().Set("slotstatus" + slot, (int)status);
		}
	}

	private void GetSlot(int slot, out string itemName, out float cookedTime, out Status status)
	{
		if (!m_nview.IsValid())
		{
			itemName = "";
			status = Status.NotDone;
			cookedTime = 0f;
		}
		else
		{
			itemName = m_nview.GetZDO().GetString("slot" + slot);
			cookedTime = m_nview.GetZDO().GetFloat("slot" + slot);
			status = (Status)m_nview.GetZDO().GetInt("slotstatus" + slot);
		}
	}

	private bool IsEmpty()
	{
		for (int i = 0; i < m_slots.Length; i++)
		{
			if (m_nview.GetZDO().GetString("slot" + i) != "")
			{
				return false;
			}
		}
		return true;
	}

	private int GetFreeSlot()
	{
		for (int i = 0; i < m_slots.Length; i++)
		{
			if (m_nview.GetZDO().GetString("slot" + i) == "")
			{
				return i;
			}
		}
		return -1;
	}

	private bool IsItemAllowed(ItemDrop.ItemData item)
	{
		return IsItemAllowed(item.m_dropPrefab.name);
	}

	private bool IsItemAllowed(string itemName)
	{
		foreach (ItemConversion item in m_conversion)
		{
			if (item.m_from.gameObject.name == itemName)
			{
				return true;
			}
		}
		return false;
	}

	private ItemConversion GetItemConversion(string itemName)
	{
		foreach (ItemConversion item in m_conversion)
		{
			if (item.m_from.gameObject.name == itemName || item.m_to.gameObject.name == itemName)
			{
				return item;
			}
		}
		return null;
	}

	private void SetFuel(float fuel)
	{
		m_nview.GetZDO().Set(ZDOVars.s_fuel, fuel);
	}

	private float GetFuel()
	{
		return m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
	}

	public bool TryGetItems(Player player, Switch switchRef, out List<string> items)
	{
		items = new List<string>();
		if (!switchRef && (bool)m_addFoodSwitch)
		{
			return false;
		}
		if (!CanUseItems(player, switchRef))
		{
			return true;
		}
		if (switchRef == null || switchRef == m_addFoodSwitch)
		{
			items.AddRange(m_conversion.Select((ItemConversion conversion) => conversion.m_from.m_itemData.m_shared.m_name));
		}
		else if (switchRef == m_addFuelSwitch)
		{
			items.Add(m_fuelItem.m_itemData.m_shared.m_name);
		}
		return true;
	}

	public bool CanUseItems(Player player, Switch switchRef, bool sendErrorMessage = true)
	{
		if (switchRef == null || switchRef == m_addFoodSwitch)
		{
			if (m_requireFire && !IsFireLit())
			{
				if (sendErrorMessage)
				{
					player.Message(MessageHud.MessageType.Center, "$msg_needfire");
				}
				return false;
			}
			if (GetFreeSlot() == -1)
			{
				if (sendErrorMessage)
				{
					player.Message(MessageHud.MessageType.Center, "$msg_nocookroom");
				}
				return false;
			}
			if (FindCookableItem(player.GetInventory()) != null)
			{
				return true;
			}
			if (sendErrorMessage)
			{
				player.Message(MessageHud.MessageType.Center, "$msg_nocookitems");
			}
			return false;
		}
		if (switchRef != m_addFuelSwitch)
		{
			return false;
		}
		if (GetFuel() > (float)(m_maxFuel - 1))
		{
			if (sendErrorMessage)
			{
				player.Message(MessageHud.MessageType.Center, "$msg_itsfull");
			}
			return false;
		}
		if (player.GetInventory().HaveItem(m_fuelItem.m_itemData.m_shared.m_name))
		{
			return true;
		}
		if (sendErrorMessage)
		{
			player.Message(MessageHud.MessageType.Center, "$msg_donthaveany " + m_fuelItem.m_itemData.m_shared.m_name);
		}
		return false;
	}

	private void OnDrawGizmosSelected()
	{
		if (!m_requireFire)
		{
			return;
		}
		if (m_fireCheckPoints != null && m_fireCheckPoints.Length != 0)
		{
			Transform[] fireCheckPoints = m_fireCheckPoints;
			foreach (Transform obj in fireCheckPoints)
			{
				Gizmos.color = Color.red;
				Gizmos.DrawWireSphere(obj.position, m_fireCheckRadius);
			}
		}
		else
		{
			Gizmos.color = Color.red;
			Gizmos.DrawWireSphere(base.transform.position, m_fireCheckRadius);
		}
	}
}
using UnityEngine;

public class Corpse : MonoBehaviour
{
	private static readonly float m_updateDt = 2f;

	public float m_emptyDespawnDelaySec = 10f;

	private float m_emptyTimer;

	private Container m_container;

	private ZNetView m_nview;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_container = GetComponent<Container>();
		if (m_nview.IsOwner() && m_nview.GetZDO().GetLong(ZDOVars.s_timeOfDeath, 0L) == 0L)
		{
			m_nview.GetZDO().Set(ZDOVars.s_timeOfDeath, ZNet.instance.GetTime().Ticks);
		}
		InvokeRepeating("UpdateDespawn", m_updateDt, m_updateDt);
	}

	private void UpdateDespawn()
	{
		if (!m_nview.IsOwner() || m_container.IsInUse())
		{
			return;
		}
		if (m_container.GetInventory().NrOfItems() <= 0)
		{
			m_emptyTimer += m_updateDt;
			if (m_emptyTimer >= m_emptyDespawnDelaySec)
			{
				ZLog.Log("Despawning looted corpse");
				m_nview.Destroy();
			}
		}
		else
		{
			m_emptyTimer = 0f;
		}
	}
}
using System.Collections.Generic;
using UnityEngine;

public class CraftingStation : MonoBehaviour, Hoverable, Interactable, IMonoUpdater
{
	public string m_name = "";

	public Sprite m_icon;

	public float m_discoverRange = 4f;

	public float m_rangeBuild = 10f;

	public float m_extraRangePerLevel;

	public bool m_craftRequireRoof = true;

	public bool m_craftRequireFire = true;

	public Transform m_roofCheckPoint;

	public Transform m_connectionPoint;

	public bool m_showBasicRecipies;

	public float m_useDistance = 2f;

	public Collider m_effectAreaCollider;

	public int m_useAnimation;

	public Skills.SkillType m_craftingSkill = Skills.SkillType.Crafting;

	public GameObject m_areaMarker;

	public GameObject m_inUseObject;

	public GameObject m_haveFireObject;

	public EffectList m_craftItemEffects = new EffectList();

	public EffectList m_craftItemDoneEffects = new EffectList();

	public EffectList m_repairItemDoneEffects = new EffectList();

	private const float m_updateExtensionInterval = 2f;

	private float m_updateExtensionTimer;

	private bool m_initialized;

	private float m_useTimer = 10f;

	private bool m_haveFire;

	private float m_buildRange;

	private ZNetView m_nview;

	private List<StationExtension> m_attachedExtensions = new List<StationExtension>();

	private static List<CraftingStation> m_allStations = new List<CraftingStation>();

	private static int m_triggerMask = 0;

	private CircleProjector m_areaMarkerCircle;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Start()
	{
		m_nview = GetComponent<ZNetView>();
		if (!m_nview || m_nview.GetZDO() != null)
		{
			m_allStations.Add(this);
			if ((bool)m_areaMarker)
			{
				m_areaMarker.SetActive(value: false);
				m_areaMarkerCircle = m_areaMarker.GetComponent<CircleProjector>();
			}
			if (m_craftRequireFire)
			{
				InvokeRepeating("CheckFire", 1f, 1f);
			}
			m_updateExtensionTimer = 2f;
		}
	}

	protected virtual void OnEnable()
	{
		Instances.Add(this);
	}

	protected virtual void OnDisable()
	{
		Instances.Remove(this);
	}

	private void OnDestroy()
	{
		m_allStations.Remove(this);
	}

	public bool Interact(Humanoid user, bool repeat, bool alt)
	{
		if (repeat)
		{
			return false;
		}
		if (user == Player.m_localPlayer)
		{
			if (!InUseDistance(user))
			{
				return false;
			}
			Player player = user as Player;
			if (CheckUsable(player, showMessage: true))
			{
				player.SetCraftingStation(this);
				InventoryGui.instance.Show(null, 3);
				return false;
			}
		}
		return false;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	public bool CheckUsable(Player player, bool showMessage)
	{
		if (m_craftRequireRoof && !player.NoCostCheat())
		{
			Cover.GetCoverForPoint(m_roofCheckPoint.position, out var coverPercentage, out var underRoof);
			if (!underRoof)
			{
				if (showMessage)
				{
					player.Message(MessageHud.MessageType.Center, "$msg_stationneedroof");
				}
				return false;
			}
			if (coverPercentage < 0.7f)
			{
				if (showMessage)
				{
					player.Message(MessageHud.MessageType.Center, "$msg_stationtooexposed");
				}
				return false;
			}
		}
		if (m_craftRequireFire && !player.NoCostCheat() && !m_haveFire)
		{
			if (showMessage)
			{
				player.Message(MessageHud.MessageType.Center, "$msg_needfire");
			}
			return false;
		}
		return true;
	}

	public string GetHoverText()
	{
		if (!InUseDistance(Player.m_localPlayer))
		{
			return Localization.instance.Localize("<color=#888888>$piece_toofar</color>");
		}
		return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_use ");
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public void ShowAreaMarker()
	{
		if ((bool)m_areaMarker)
		{
			m_areaMarker.SetActive(value: true);
			CancelInvoke("HideMarker");
			Invoke("HideMarker", 0.5f);
			PokeInUse();
		}
	}

	private void HideMarker()
	{
		m_areaMarker.SetActive(value: false);
	}

	public static void UpdateKnownStationsInRange(Player player)
	{
		Vector3 position = player.transform.position;
		foreach (CraftingStation allStation in m_allStations)
		{
			if (Vector3.Distance(allStation.transform.position, position) < allStation.m_discoverRange)
			{
				player.AddKnownStation(allStation);
			}
		}
	}

	public void CustomUpdate(float deltaTime, float time)
	{
		if (m_nview == null || !m_nview.IsValid())
		{
			return;
		}
		m_useTimer += deltaTime;
		m_updateExtensionTimer += deltaTime;
		if ((bool)m_inUseObject)
		{
			bool flag = m_useTimer < 1f;
			if (m_inUseObject.activeSelf != flag)
			{
				m_inUseObject.SetActive(flag);
			}
		}
	}

	private void CheckFire()
	{
		m_haveFire = EffectArea.IsPointPlus025InsideBurningArea(base.transform.position);
		if ((bool)m_haveFireObject)
		{
			m_haveFireObject.SetActive(m_haveFire);
		}
	}

	public void PokeInUse()
	{
		m_useTimer = 0f;
		TriggerExtensionEffects();
	}

	public static CraftingStation GetCraftingStation(Vector3 point)
	{
		if (m_triggerMask == 0)
		{
			m_triggerMask = LayerMask.GetMask("character_trigger");
		}
		Collider[] array = Physics.OverlapSphere(point, 0.1f, m_triggerMask, QueryTriggerInteraction.Collide);
		foreach (Collider collider in array)
		{
			if (collider.gameObject.CompareTag("StationUseArea"))
			{
				CraftingStation componentInParent = collider.GetComponentInParent<CraftingStation>();
				if (componentInParent != null)
				{
					return componentInParent;
				}
			}
		}
		return null;
	}

	public static CraftingStation HaveBuildStationInRange(string name, Vector3 point)
	{
		foreach (CraftingStation allStation in m_allStations)
		{
			if (!(allStation.m_name != name))
			{
				float stationBuildRange = allStation.GetStationBuildRange();
				point.y = allStation.transform.position.y;
				if (Vector3.Distance(allStation.transform.position, point) < stationBuildRange)
				{
					return allStation;
				}
			}
		}
		return null;
	}

	public static void FindStationsInRange(string name, Vector3 point, float range, List<CraftingStation> stations)
	{
		foreach (CraftingStation allStation in m_allStations)
		{
			if (!(allStation.m_name != name) && Vector3.Distance(allStation.transform.position, point) < range)
			{
				stations.Add(allStation);
			}
		}
	}

	public static CraftingStation FindClosestStationInRange(string name, Vector3 point, float range)
	{
		CraftingStation craftingStation = null;
		float num = 99999f;
		foreach (CraftingStation allStation in m_allStations)
		{
			if (!(allStation.m_name != name))
			{
				float num2 = Vector3.Distance(allStation.transform.position, point);
				if (num2 < range && (num2 < num || craftingStation == null))
				{
					craftingStation = allStation;
					num = num2;
				}
			}
		}
		return craftingStation;
	}

	private List<StationExtension> GetExtensions()
	{
		if (m_updateExtensionTimer >= 2f)
		{
			m_updateExtensionTimer = 0f;
			m_attachedExtensions.Clear();
			StationExtension.FindExtensions(this, base.transform.position, m_attachedExtensions);
			m_buildRange = m_rangeBuild + (float)GetExtentionCount(checkExtensions: false) * m_extraRangePerLevel;
			if ((bool)m_areaMarker)
			{
				m_areaMarkerCircle.m_radius = m_buildRange;
			}
			if (m_effectAreaCollider == null)
			{
				return m_attachedExtensions;
			}
			Collider effectAreaCollider = m_effectAreaCollider;
			if (!(effectAreaCollider is SphereCollider sphereCollider))
			{
				if (effectAreaCollider is CapsuleCollider capsuleCollider)
				{
					capsuleCollider.radius = m_buildRange;
				}
			}
			else
			{
				sphereCollider.radius = m_buildRange;
			}
		}
		return m_attachedExtensions;
	}

	private void TriggerExtensionEffects()
	{
		Vector3 connectionEffectPoint = GetConnectionEffectPoint();
		foreach (StationExtension extension in GetExtensions())
		{
			if ((bool)extension)
			{
				extension.StartConnectionEffect(connectionEffectPoint);
			}
		}
	}

	public Vector3 GetConnectionEffectPoint()
	{
		if ((bool)m_connectionPoint)
		{
			return m_connectionPoint.position;
		}
		return base.transform.position;
	}

	public int GetLevel(bool checkExtensions = true)
	{
		return 1 + GetExtentionCount(checkExtensions);
	}

	public int GetExtentionCount(bool checkExtensions = true)
	{
		if (checkExtensions)
		{
			GetExtensions();
		}
		return m_attachedExtensions.Count;
	}

	public float GetStationBuildRange()
	{
		GetExtensions();
		return m_buildRange;
	}

	public bool InUseDistance(Humanoid human)
	{
		return Vector3.Distance(human.transform.position, base.transform.position) < m_useDistance;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class CreatureSpawner : MonoBehaviour
{
	public class Group : HashSet<CreatureSpawner>
	{
		private readonly List<CreatureSpawner> m_activeSpawners = new List<CreatureSpawner>();

		public void CountSpawns(out int spawnedNow, out int spawnedEver)
		{
			spawnedNow = (spawnedEver = 0);
			using Enumerator enumerator = GetEnumerator();
			while (enumerator.MoveNext())
			{
				CreatureSpawner current = enumerator.Current;
				if (current.m_nview == null || current.m_nview.GetZDO() == null)
				{
					continue;
				}
				current.m_lastSpawnID = current.m_nview.GetZDO().GetConnectionZDOID(ZDOExtraData.ConnectionType.Spawned);
				if (current.m_nview.GetZDO().GetConnectionType() != ZDOExtraData.ConnectionType.None)
				{
					spawnedEver++;
					current.m_lastSpawnID = current.m_nview.GetZDO().GetConnectionZDOID(ZDOExtraData.ConnectionType.Spawned);
					if (ZDOMan.instance.GetZDO(current.m_lastSpawnID) != null)
					{
						spawnedNow++;
					}
				}
			}
		}

		public void SpawnWeighted()
		{
			m_activeSpawners.Clear();
			float num = 0f;
			using (Enumerator enumerator = GetEnumerator())
			{
				while (enumerator.MoveNext())
				{
					CreatureSpawner current = enumerator.Current;
					if (current.m_lastSpawnID.IsNone() || (current.CanRespawnNow(current.m_lastSpawnID) && !current.SpawnedCreatureStillExists(current.m_lastSpawnID)))
					{
						m_activeSpawners.Add(current);
						num += current.m_spawnerWeight;
					}
				}
			}
			float num2 = UnityEngine.Random.Range(0f, num);
			float num3 = 0f;
			foreach (CreatureSpawner activeSpawner in m_activeSpawners)
			{
				num3 += activeSpawner.m_spawnerWeight;
				if (num2 < num3)
				{
					activeSpawner.Spawn();
					return;
				}
			}
			ZLog.LogError("No active spawners for group but something is still calling it!");
		}
	}

	private const float m_radius = 0.75f;

	public GameObject m_creaturePrefab;

	[Header("Level")]
	public int m_maxLevel = 1;

	public int m_minLevel = 1;

	public float m_levelupChance = 10f;

	[Header("Spawn settings")]
	public float m_respawnTimeMinuts = 20f;

	public float m_triggerDistance = 60f;

	public float m_triggerNoise;

	public bool m_spawnAtNight = true;

	public bool m_spawnAtDay = true;

	public bool m_requireSpawnArea;

	public bool m_spawnInPlayerBase;

	public bool m_wakeUpAnimation;

	public int m_spawnInterval = 5;

	public string m_requiredGlobalKey = "";

	public string m_blockingGlobalKey = "";

	public bool m_setPatrolSpawnPoint;

	[Header("Spawn group blocking")]
	[Tooltip("Spawners sharing the same ID within eachothers radiuses will be grouped together, and will never spawn more than the specified max group size. Weight will also be taken into account, prioritizing those with higher weight randomly.")]
	public int m_spawnGroupID;

	public int m_maxGroupSpawned = 1;

	public float m_spawnGroupRadius;

	public float m_spawnerWeight = 1f;

	[Space]
	public EffectList m_spawnEffects = new EffectList();

	private ZNetView m_nview;

	private Group m_spawnGroup;

	private ZDOID m_lastSpawnID;

	private bool m_checkedLocation;

	private Location m_location;

	private static List<CreatureSpawner> m_creatureSpawners = new List<CreatureSpawner>();

	private static List<CreatureSpawner> m_groupUnchecked = new List<CreatureSpawner>();

	private static HashSet<CreatureSpawner> m_grouped = new HashSet<CreatureSpawner>();

	private static Stack<CreatureSpawner> m_groupNew = new Stack<CreatureSpawner>();

	private static List<Group> m_groups = new List<Group>();

	private void Awake()
	{
		m_creatureSpawners.Add(this);
		m_nview = GetComponent<ZNetView>();
		if (m_nview.GetZDO() != null)
		{
			InvokeRepeating("UpdateSpawner", UnityEngine.Random.Range(m_spawnInterval / 2, m_spawnInterval), m_spawnInterval);
		}
	}

	private void OnDestroy()
	{
		m_creatureSpawners.Remove(this);
	}

	private void UpdateSpawner()
	{
		if (!m_nview.IsOwner())
		{
			return;
		}
		if (!m_checkedLocation)
		{
			m_location = Location.GetLocation(base.transform.position);
			m_checkedLocation = true;
			if ((bool)m_location && m_location.m_blockSpawnGroups.Contains(m_spawnGroupID))
			{
				m_nview.Destroy();
				return;
			}
		}
		ZDOConnection connection = m_nview.GetZDO().GetConnection();
		bool flag = connection != null && connection.m_type == ZDOExtraData.ConnectionType.Spawned;
		if (m_respawnTimeMinuts <= 0f && flag)
		{
			return;
		}
		ZDOID connectionZDOID = m_nview.GetZDO().GetConnectionZDOID(ZDOExtraData.ConnectionType.Spawned);
		if (SpawnedCreatureStillExists(connectionZDOID) || !CanRespawnNow(connectionZDOID) || (!m_spawnAtDay && EnvMan.IsDay()) || (!m_spawnAtNight && EnvMan.IsNight()))
		{
			return;
		}
		_ = m_requireSpawnArea;
		if (!m_spawnInPlayerBase && (bool)EffectArea.IsPointInsideArea(base.transform.position, EffectArea.Type.PlayerBase))
		{
			return;
		}
		if (m_triggerNoise > 0f)
		{
			if (!Player.IsPlayerInRange(base.transform.position, m_triggerDistance, m_triggerNoise))
			{
				return;
			}
		}
		else if (!Player.IsPlayerInRange(base.transform.position, m_triggerDistance))
		{
			return;
		}
		if (!CheckGlobalKeys() && !CheckGroupSpawnBlocked())
		{
			if (m_spawnGroup != null)
			{
				m_spawnGroup.SpawnWeighted();
			}
			else
			{
				Spawn();
			}
		}
	}

	private bool CheckGlobalKeys()
	{
		List<string> globalKeys = ZoneSystem.instance.GetGlobalKeys();
		if (m_blockingGlobalKey != "" && globalKeys.Contains(m_blockingGlobalKey))
		{
			return true;
		}
		if (m_requiredGlobalKey != "" && !globalKeys.Contains(m_requiredGlobalKey))
		{
			return true;
		}
		return false;
	}

	private bool SpawnedCreatureStillExists(ZDOID spawnID)
	{
		if (!spawnID.IsNone() && ZDOMan.instance.GetZDO(spawnID) != null)
		{
			m_nview.GetZDO().Set(ZDOVars.s_aliveTime, ZNet.instance.GetTime().Ticks);
			return true;
		}
		return false;
	}

	private bool CanRespawnNow(ZDOID spawnID)
	{
		if (m_respawnTimeMinuts > 0f)
		{
			DateTime time = ZNet.instance.GetTime();
			DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_aliveTime, 0L));
			if ((time - dateTime).TotalMinutes < (double)m_respawnTimeMinuts)
			{
				return false;
			}
		}
		return true;
	}

	private bool HasSpawned()
	{
		if (m_nview == null || m_nview.GetZDO() == null)
		{
			return false;
		}
		ZDOConnection connection = m_nview.GetZDO().GetConnection();
		if (connection != null)
		{
			return connection.m_type == ZDOExtraData.ConnectionType.Spawned;
		}
		return false;
	}

	private ZNetView Spawn()
	{
		if (SpawnSystem.m_nospawn)
		{
			return null;
		}
		Vector3 position = base.transform.position;
		if (ZoneSystem.instance.FindFloor(position, out var height))
		{
			position.y = height;
		}
		Quaternion rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0f, 360f), 0f);
		GameObject gameObject = UnityEngine.Object.Instantiate(m_creaturePrefab, position, rotation);
		ZNetView component = gameObject.GetComponent<ZNetView>();
		if (m_wakeUpAnimation)
		{
			gameObject.GetComponent<ZSyncAnimation>()?.SetBool("wakeup", value: true);
		}
		BaseAI component2 = gameObject.GetComponent<BaseAI>();
		if (component2 != null && m_setPatrolSpawnPoint)
		{
			component2.SetPatrolPoint();
		}
		int num = m_minLevel;
		int num2 = m_maxLevel;
		float num3 = m_levelupChance;
		if (m_location != null && !m_location.m_excludeEnemyLevelOverrideGroups.Contains(m_spawnGroupID))
		{
			if (m_location.m_enemyMinLevelOverride >= 0)
			{
				num = m_location.m_enemyMinLevelOverride;
			}
			if (m_location.m_enemyMaxLevelOverride >= 0)
			{
				num2 = m_location.m_enemyMaxLevelOverride;
			}
			if (m_location.m_enemyLevelUpOverride >= 0f)
			{
				num3 = m_location.m_enemyLevelUpOverride;
			}
		}
		if (num2 > 1)
		{
			Character component3 = gameObject.GetComponent<Character>();
			if ((bool)component3)
			{
				int i;
				for (i = num; i < num2; i++)
				{
					if (!(UnityEngine.Random.Range(0f, 100f) <= SpawnSystem.GetLevelUpChance(num3)))
					{
						break;
					}
				}
				if (i > 1)
				{
					component3.SetLevel(i);
				}
			}
			else
			{
				ItemDrop component4 = gameObject.GetComponent<ItemDrop>();
				if ((bool)component4)
				{
					int j;
					for (j = num; j < num2; j++)
					{
						if (!(UnityEngine.Random.Range(0f, 100f) <= num3))
						{
							break;
						}
					}
					if (j > 1)
					{
						component4.SetQuality(j);
					}
				}
			}
		}
		m_nview.GetZDO().SetConnection(ZDOExtraData.ConnectionType.Spawned, component.GetZDO().m_uid);
		m_nview.GetZDO().Set(ZDOVars.s_aliveTime, ZNet.instance.GetTime().Ticks);
		SpawnEffect(gameObject);
		return component;
	}

	private void SpawnEffect(GameObject spawnedObject)
	{
		Character component = spawnedObject.GetComponent<Character>();
		Vector3 basePos = (component ? component.GetCenterPoint() : (base.transform.position + Vector3.up * 0.75f));
		m_spawnEffects.Create(basePos, Quaternion.identity);
	}

	private float GetRadius()
	{
		return 0.75f;
	}

	private void OnDrawGizmos()
	{
	}

	private bool CheckGroupSpawnBlocked()
	{
		if (m_spawnGroupRadius <= 0f || m_maxGroupSpawned < 1)
		{
			return false;
		}
		if (m_spawnGroup == null)
		{
			m_groupNew.Clear();
			m_grouped.Clear();
			m_groupUnchecked.Clear();
			m_groupUnchecked.AddRange(m_creatureSpawners);
			m_groupUnchecked.Remove(this);
			m_groupNew.Push(this);
			m_grouped.Add(this);
			while (m_groupNew.Count > 0)
			{
				CreatureSpawner creatureSpawner = m_groupNew.Pop();
				for (int num = m_groupUnchecked.Count - 1; num >= 0; num--)
				{
					CreatureSpawner creatureSpawner2 = m_groupUnchecked[num];
					if (creatureSpawner.m_spawnGroupID == creatureSpawner2.m_spawnGroupID && Vector3.Distance(creatureSpawner.transform.position, creatureSpawner2.transform.position) <= creatureSpawner.m_spawnGroupRadius + creatureSpawner2.m_spawnGroupRadius)
					{
						m_groupNew.Push(creatureSpawner2);
						m_grouped.Add(creatureSpawner2);
						m_groupUnchecked.Remove(creatureSpawner2);
					}
				}
			}
			m_groups.Clear();
			foreach (CreatureSpawner item in m_grouped)
			{
				if (item.m_spawnGroup != null)
				{
					m_groups.Add(item.m_spawnGroup);
				}
			}
			Group obj = null;
			if (m_groups.Count > 0)
			{
				if (m_groups.Count > 1)
				{
					ZLog.Log(string.Format("{0} {1} merged for {2} spawners.", m_groups.Count, "Group", m_grouped.Count));
				}
				obj = m_groups[0];
			}
			else
			{
				obj = new Group();
			}
			foreach (CreatureSpawner item2 in m_grouped)
			{
				obj.Add(item2);
				item2.m_spawnGroup = obj;
			}
			ZLog.Log(string.Format("{0} created for {1} spawners.", "Group", obj.Count));
		}
		m_spawnGroup.CountSpawns(out var spawnedNow, out var spawnedEver);
		if (m_respawnTimeMinuts <= 0f)
		{
			if (spawnedEver < m_maxGroupSpawned && spawnedNow < m_maxGroupSpawned)
			{
				return false;
			}
			Terminal.Log($"Group spawnID #{m_spawnGroupID} blocked: I have not spawned, but someone else has made us reach the maximum, abort!");
			return true;
		}
		if (spawnedNow < m_maxGroupSpawned)
		{
			return false;
		}
		Terminal.Log($"Group spawnID #{m_spawnGroupID} blocked: I allow respawning, but we are currently at our maxium, abort!");
		return true;
	}
}
using System;
using System.Diagnostics;
using UnityEngine;

public class CustomLogger : MonoBehaviour
{
	private static string s_link = Application.persistentDataPath + "/Player.log";

	private static string s_target = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "/Library/Logs/IronGate/Valheim/Player.log";

	public static void SetupSymbolicLink()
	{
		if (Application.platform != RuntimePlatform.OSXPlayer && Application.platform != RuntimePlatform.OSXEditor)
		{
			UnityEngine.Debug.LogError("Only use SetupSymbolicLink on MacOS in its current incarnation!");
			return;
		}
		try
		{
			Process.Start(new ProcessStartInfo("/bin/ln", "-sf \"" + s_target + "\" \"" + s_link + "\"")
			{
				UseShellExecute = false,
				CreateNoWindow = true
			});
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("Error when trying to create symbolic link to log file in Application.persistentDataPath! " + ex.Message);
		}
	}
}
using System.Collections.Generic;
using System.Globalization;
using TMPro;
using UnityEngine;

public class DamageText : MonoBehaviour
{
	public enum TextType
	{
		Normal,
		Resistant,
		Weak,
		Immune,
		Heal,
		TooHard,
		Blocked,
		Bonus
	}

	private class WorldTextInstance
	{
		public Vector3 m_worldPos;

		public GameObject m_gui;

		public float m_timer;

		public TMP_Text m_textField;

		public float m_duration;
	}

	private static DamageText m_instance;

	public float m_textDuration = 1.5f;

	public float m_maxTextDistance = 30f;

	public int m_largeFontSize = 16;

	public int m_smallFontSize = 8;

	public float m_smallFontDistance = 10f;

	public GameObject m_worldTextBase;

	private List<WorldTextInstance> m_worldTexts = new List<WorldTextInstance>();

	public static DamageText instance => m_instance;

	private void Awake()
	{
		m_instance = this;
		ZRoutedRpc.instance.Register<ZPackage>("RPC_DamageText", RPC_DamageText);
	}

	private void LateUpdate()
	{
		UpdateWorldTexts(Time.deltaTime);
	}

	private void UpdateWorldTexts(float dt)
	{
		WorldTextInstance worldTextInstance = null;
		Camera mainCamera = Utils.GetMainCamera();
		foreach (WorldTextInstance worldText in m_worldTexts)
		{
			worldText.m_timer += dt;
			if (worldText.m_timer > worldText.m_duration && worldTextInstance == null)
			{
				worldTextInstance = worldText;
			}
			worldText.m_worldPos.y += dt;
			float f = Mathf.Clamp01(worldText.m_timer / worldText.m_duration);
			Color color = worldText.m_textField.color;
			color.a = 1f - Mathf.Pow(f, 3f);
			worldText.m_textField.color = color;
			Vector3 position = mainCamera.WorldToScreenPointScaled(worldText.m_worldPos);
			if (position.x < 0f || position.x > (float)Screen.width || position.y < 0f || position.y > (float)Screen.height || position.z < 0f)
			{
				worldText.m_gui.SetActive(value: false);
				continue;
			}
			worldText.m_gui.SetActive(value: true);
			worldText.m_gui.transform.position = position;
		}
		if (worldTextInstance != null)
		{
			Object.Destroy(worldTextInstance.m_gui);
			m_worldTexts.Remove(worldTextInstance);
		}
	}

	private void AddInworldText(TextType type, Vector3 pos, float distance, string text, bool mySelf)
	{
		if (!(text == "0") || m_worldTexts.Count <= 200)
		{
			WorldTextInstance worldTextInstance = new WorldTextInstance();
			worldTextInstance.m_duration = m_textDuration;
			worldTextInstance.m_worldPos = pos + Random.insideUnitSphere * 0.5f;
			worldTextInstance.m_gui = Object.Instantiate(m_worldTextBase, base.transform);
			worldTextInstance.m_textField = worldTextInstance.m_gui.GetComponent<TMP_Text>();
			m_worldTexts.Add(worldTextInstance);
			text = Localization.instance.Localize(text);
			Color color = ((mySelf && type <= TextType.Immune) ? ((!(text == "0")) ? new Color(1f, 0f, 0f, 1f) : new Color(0.5f, 0.5f, 0.5f, 1f)) : (type switch
			{
				TextType.Normal => new Color(1f, 1f, 1f, 1f), 
				TextType.Resistant => new Color(0.6f, 0.6f, 0.6f, 1f), 
				TextType.Weak => new Color(1f, 1f, 0f, 1f), 
				TextType.Immune => new Color(0.6f, 0.6f, 0.6f, 1f), 
				TextType.TooHard => new Color(0.8f, 0.7f, 0.7f, 1f), 
				TextType.Bonus => new Color(1f, 0.63f, 0.24f, 1f), 
				TextType.Heal => new Color(0.5f, 1f, 0.5f, 0.7f), 
				_ => Color.white, 
			}));
			worldTextInstance.m_textField.color = color;
			if (distance > m_smallFontDistance)
			{
				worldTextInstance.m_textField.fontSize = m_smallFontSize;
			}
			else
			{
				worldTextInstance.m_textField.fontSize = m_largeFontSize;
			}
			switch (type)
			{
			case TextType.TooHard:
				text = Localization.instance.Localize("$msg_toohard");
				break;
			case TextType.Heal:
				text = "+" + text;
				break;
			case TextType.Blocked:
				text = Localization.instance.Localize("$msg_blocked: " + text);
				break;
			case TextType.Bonus:
				worldTextInstance.m_textField.fontSize *= 1.5f;
				worldTextInstance.m_duration = 3f;
				break;
			}
			worldTextInstance.m_textField.text = text;
			worldTextInstance.m_timer = 0f;
		}
	}

	public void ShowText(HitData.DamageModifier type, Vector3 pos, float dmg, bool player = false)
	{
		TextType type2 = TextType.Normal;
		switch (type)
		{
		case HitData.DamageModifier.Normal:
			type2 = TextType.Normal;
			break;
		case HitData.DamageModifier.Immune:
			type2 = TextType.Immune;
			break;
		case HitData.DamageModifier.SlightlyResistant:
			type2 = TextType.Resistant;
			break;
		case HitData.DamageModifier.Resistant:
			type2 = TextType.Resistant;
			break;
		case HitData.DamageModifier.VeryResistant:
			type2 = TextType.Resistant;
			break;
		case HitData.DamageModifier.SlightlyWeak:
			type2 = TextType.Weak;
			break;
		case HitData.DamageModifier.Weak:
			type2 = TextType.Weak;
			break;
		case HitData.DamageModifier.VeryWeak:
			type2 = TextType.Weak;
			break;
		}
		ShowText(type2, pos, dmg, player);
	}

	public void ShowText(TextType type, Vector3 pos, float dmg, bool player = false)
	{
		ShowText(type, pos, dmg.ToString("0.#", CultureInfo.InvariantCulture), player);
	}

	public void ShowText(TextType type, Vector3 pos, string text, bool player = false)
	{
		ZPackage zPackage = new ZPackage();
		zPackage.Write((int)type);
		zPackage.Write(pos);
		zPackage.Write(text);
		zPackage.Write(player);
		ZRoutedRpc.instance.InvokeRoutedRPC(ZRoutedRpc.Everybody, "RPC_DamageText", zPackage);
	}

	private void RPC_DamageText(long sender, ZPackage pkg)
	{
		Camera mainCamera = Utils.GetMainCamera();
		if ((bool)mainCamera && !Hud.IsUserHidden())
		{
			TextType type = (TextType)pkg.ReadInt();
			Vector3 vector = pkg.ReadVector3();
			string text = pkg.ReadString();
			bool flag = pkg.ReadBool();
			float num = Vector3.Distance(mainCamera.transform.position, vector);
			if (!(num > m_maxTextDistance))
			{
				bool mySelf = flag && sender == ZNet.GetUID();
				AddInworldText(type, vector, num, text, mySelf);
			}
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Demister : MonoBehaviour
{
	public float m_disableForcefieldDelay;

	[NonSerialized]
	public ParticleSystemForceField m_forceField;

	private Vector3 m_lastUpdatePosition;

	private static List<Demister> m_instances = new List<Demister>();

	private void Awake()
	{
		m_forceField = GetComponent<ParticleSystemForceField>();
		m_lastUpdatePosition = base.transform.position;
		if (m_disableForcefieldDelay > 0f)
		{
			Invoke("DisableForcefield", m_disableForcefieldDelay);
		}
	}

	private void OnEnable()
	{
		m_instances.Add(this);
	}

	private void OnDisable()
	{
		m_instances.Remove(this);
	}

	private void DisableForcefield()
	{
		m_forceField.enabled = false;
	}

	public float GetMovedDistance()
	{
		Vector3 position = base.transform.position;
		if (position == m_lastUpdatePosition)
		{
			return 0f;
		}
		float a = Vector3.Distance(position, m_lastUpdatePosition);
		m_lastUpdatePosition = position;
		return Mathf.Min(a, 10f);
	}

	public static List<Demister> GetDemisters()
	{
		return m_instances;
	}
}
using UnityEngine;

public class DepthCamera : MonoBehaviour
{
	public Shader m_depthShader;

	public float m_offset = 50f;

	public RenderTexture m_texture;

	public float m_updateInterval = 1f;

	private Camera m_camera;

	private void Start()
	{
		m_camera = GetComponent<Camera>();
		InvokeRepeating("RenderDepth", m_updateInterval, m_updateInterval);
	}

	private void RenderDepth()
	{
		Camera mainCamera = Utils.GetMainCamera();
		if (!(mainCamera == null))
		{
			Vector3 position = (Player.m_localPlayer ? Player.m_localPlayer.transform.position : mainCamera.transform.position) + Vector3.up * m_offset;
			position.x = Mathf.Round(position.x);
			position.y = Mathf.Round(position.y);
			position.z = Mathf.Round(position.z);
			base.transform.position = position;
			float lodBias = QualitySettings.lodBias;
			QualitySettings.lodBias = 10f;
			m_camera.RenderWithShader(m_depthShader, "RenderType");
			QualitySettings.lodBias = lodBias;
			Shader.SetGlobalTexture("_SkyAlphaTexture", m_texture);
			Shader.SetGlobalVector("_SkyAlphaPosition", base.transform.position);
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Destructible : MonoBehaviour, IDestructible
{
	public Action m_onDestroyed;

	public Action m_onDamaged;

	[Header("Destruction")]
	public DestructibleType m_destructibleType = DestructibleType.Default;

	public float m_health = 1f;

	public HitData.DamageModifiers m_damages;

	public float m_minDamageTreshold;

	public int m_minToolTier;

	public float m_hitNoise;

	public float m_destroyNoise;

	public bool m_triggerPrivateArea;

	public float m_ttl;

	public GameObject m_spawnWhenDestroyed;

	[Header("Effects")]
	public EffectList m_destroyedEffect = new EffectList();

	public EffectList m_hitEffect = new EffectList();

	public bool m_autoCreateFragments;

	private ZNetView m_nview;

	private Rigidbody m_body;

	private bool m_firstFrame = true;

	private bool m_destroyed;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_body = GetComponent<Rigidbody>();
		if ((bool)m_nview && m_nview.GetZDO() != null)
		{
			m_nview.Register<HitData>("RPC_Damage", RPC_Damage);
			if (m_autoCreateFragments)
			{
				m_nview.Register("RPC_CreateFragments", RPC_CreateFragments);
			}
			if (m_ttl > 0f)
			{
				InvokeRepeating("DestroyNow", m_ttl, 1f);
			}
		}
	}

	private void Start()
	{
		m_firstFrame = false;
	}

	public GameObject GetParentObject()
	{
		return null;
	}

	public DestructibleType GetDestructibleType()
	{
		return m_destructibleType;
	}

	public void Damage(HitData hit)
	{
		if (!m_firstFrame && m_nview.IsValid())
		{
			m_nview.InvokeRPC("RPC_Damage", hit);
		}
	}

	private void RPC_Damage(long sender, HitData hit)
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner() || m_destroyed)
		{
			return;
		}
		float num = m_nview.GetZDO().GetFloat(ZDOVars.s_health, m_health + (float)Game.m_worldLevel * m_health * Game.instance.m_worldLevelMineHPMultiplier);
		if (num <= 0f || m_destroyed)
		{
			return;
		}
		hit.ApplyResistance(m_damages, out var significantModifier);
		float totalDamage = hit.GetTotalDamage();
		if ((bool)m_body)
		{
			m_body.AddForceAtPosition(hit.m_dir * hit.m_pushForce, hit.m_point, ForceMode.Impulse);
		}
		if (!hit.CheckToolTier(m_minToolTier))
		{
			DamageText.instance.ShowText(DamageText.TextType.TooHard, hit.m_point, 0f);
			return;
		}
		DamageText.instance.ShowText(significantModifier, hit.m_point, totalDamage);
		if (totalDamage <= 0f)
		{
			return;
		}
		num -= totalDamage;
		m_nview.GetZDO().Set(ZDOVars.s_health, num);
		if (m_triggerPrivateArea)
		{
			Character attacker = hit.GetAttacker();
			if ((bool)attacker)
			{
				bool destroyed = num <= 0f;
				PrivateArea.OnObjectDamaged(base.transform.position, attacker, destroyed);
			}
		}
		m_hitEffect.Create(hit.m_point, Quaternion.identity, base.transform);
		if (m_onDamaged != null)
		{
			m_onDamaged();
		}
		if (m_hitNoise > 0f && hit.m_hitType != HitData.HitType.CinderFire)
		{
			Player closestPlayer = Player.GetClosestPlayer(hit.m_point, 10f);
			if ((bool)closestPlayer)
			{
				closestPlayer.AddNoise(m_hitNoise);
			}
		}
		if (num <= 0f)
		{
			Destroy(hit);
		}
	}

	public void DestroyNow()
	{
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			Destroy();
		}
	}

	public void Destroy(HitData hit = null)
	{
		Vector3 hitPoint = hit?.m_point ?? Vector3.zero;
		Vector3 hitDir = hit?.m_dir ?? Vector3.zero;
		CreateDestructionEffects(hitPoint, hitDir);
		if (m_destroyNoise > 0f && (hit == null || hit.m_hitType != HitData.HitType.CinderFire))
		{
			Player closestPlayer = Player.GetClosestPlayer(base.transform.position, 10f);
			if ((bool)closestPlayer)
			{
				closestPlayer.AddNoise(m_destroyNoise);
			}
		}
		if ((bool)m_spawnWhenDestroyed)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(m_spawnWhenDestroyed, base.transform.position, base.transform.rotation);
			gameObject.GetComponent<ZNetView>().SetLocalScale(base.transform.localScale);
			gameObject.GetComponent<Gibber>()?.Setup(hitPoint, hitDir);
			if (hit != null)
			{
				gameObject.GetComponent<MineRock5>()?.Damage(hit);
			}
		}
		if (m_onDestroyed != null)
		{
			m_onDestroyed();
		}
		ZNetScene.instance.Destroy(base.gameObject);
		m_destroyed = true;
	}

	private void CreateDestructionEffects(Vector3 hitPoint, Vector3 hitDir)
	{
		GameObject[] array = m_destroyedEffect.Create(base.transform.position, base.transform.rotation, base.transform);
		for (int i = 0; i < array.Length; i++)
		{
			Gibber component = array[i].GetComponent<Gibber>();
			if ((bool)component)
			{
				component.Setup(hitPoint, hitDir);
			}
		}
		if (m_autoCreateFragments)
		{
			m_nview.InvokeRPC(ZNetView.Everybody, "RPC_CreateFragments");
		}
	}

	private void RPC_CreateFragments(long peer)
	{
		CreateFragments(base.gameObject);
	}

	public static void CreateFragments(GameObject rootObject, bool visibleOnly = true)
	{
		MeshRenderer[] componentsInChildren = rootObject.GetComponentsInChildren<MeshRenderer>(includeInactive: true);
		int layer = LayerMask.NameToLayer("effect");
		List<Rigidbody> list = new List<Rigidbody>();
		MeshRenderer[] array = componentsInChildren;
		foreach (MeshRenderer meshRenderer in array)
		{
			if (!meshRenderer.gameObject.activeInHierarchy || (visibleOnly && !meshRenderer.isVisible))
			{
				continue;
			}
			MeshFilter component = meshRenderer.gameObject.GetComponent<MeshFilter>();
			if (!(component == null))
			{
				if (component.sharedMesh == null)
				{
					ZLog.Log("Meshfilter missing mesh " + component.gameObject.name);
					continue;
				}
				GameObject gameObject = new GameObject();
				gameObject.layer = layer;
				gameObject.transform.position = component.gameObject.transform.position;
				gameObject.transform.rotation = component.gameObject.transform.rotation;
				gameObject.transform.localScale = component.gameObject.transform.lossyScale * 0.9f;
				gameObject.AddComponent<MeshFilter>().sharedMesh = component.sharedMesh;
				gameObject.AddComponent<MeshRenderer>().sharedMaterials = meshRenderer.sharedMaterials;
				MaterialMan.instance.SetValue(gameObject, ShaderProps._RippleDistance, 0f);
				MaterialMan.instance.SetValue(gameObject, ShaderProps._ValueNoise, 0f);
				Rigidbody item = gameObject.AddComponent<Rigidbody>();
				gameObject.AddComponent<BoxCollider>();
				list.Add(item);
				gameObject.AddComponent<TimedDestruction>().Trigger(UnityEngine.Random.Range(2, 4));
			}
		}
		if (list.Count <= 0)
		{
			return;
		}
		Vector3 zero = Vector3.zero;
		int num = 0;
		foreach (Rigidbody item2 in list)
		{
			zero += item2.worldCenterOfMass;
			num++;
		}
		zero /= (float)num;
		foreach (Rigidbody item3 in list)
		{
			Vector3 force = (item3.worldCenterOfMass - zero).normalized * 4f;
			force += UnityEngine.Random.onUnitSphere * 1f;
			item3.AddForce(force, ForceMode.VelocityChange);
		}
	}
}
