using System;
using UnityEngine;

public class DistantFogEmitter : MonoBehaviour
{
	public float m_interval = 1f;

	public float m_minRadius = 100f;

	public float m_maxRadius = 500f;

	public float m_mountainSpawnChance = 1f;

	public float m_landSpawnChance = 0.5f;

	public float m_waterSpawnChance = 0.25f;

	public float m_mountainLimit = 120f;

	public float m_emitStep = 10f;

	public int m_emitPerStep = 10;

	public int m_particles = 100;

	public float m_placeOffset = 1f;

	public ParticleSystem[] m_psystems;

	public bool m_skipWater;

	private float m_placeTimer;

	private bool m_emit = true;

	private Vector3 m_lastPosition = Vector3.zero;

	public void SetEmit(bool emit)
	{
		m_emit = emit;
	}

	private void Update()
	{
		if (!m_emit || WorldGenerator.instance == null)
		{
			return;
		}
		m_placeTimer += Time.deltaTime;
		if (m_placeTimer > m_interval)
		{
			m_placeTimer = 0f;
			int num = Mathf.Max(0, m_particles - TotalNrOfParticles());
			num /= 4;
			for (int i = 0; i < num; i++)
			{
				PlaceOne();
			}
		}
	}

	private int TotalNrOfParticles()
	{
		int num = 0;
		ParticleSystem[] psystems = m_psystems;
		foreach (ParticleSystem particleSystem in psystems)
		{
			num += particleSystem.particleCount;
		}
		return num;
	}

	private void PlaceOne()
	{
		if (GetRandomPoint(base.transform.position, out var p))
		{
			ParticleSystem.EmitParams emitParams = new ParticleSystem.EmitParams
			{
				position = p + Vector3.up * m_placeOffset
			};
			m_psystems[UnityEngine.Random.Range(0, m_psystems.Length)].Emit(emitParams, 1);
		}
	}

	private bool GetRandomPoint(Vector3 center, out Vector3 p)
	{
		float f = UnityEngine.Random.value * MathF.PI * 2f;
		float num = Mathf.Sqrt(UnityEngine.Random.value) * (m_maxRadius - m_minRadius) + m_minRadius;
		p = center + new Vector3(Mathf.Sin(f) * num, 0f, Mathf.Cos(f) * num);
		p.y = WorldGenerator.instance.GetHeight(p.x, p.z);
		if (p.y < 30f)
		{
			if (m_skipWater)
			{
				return false;
			}
			if (UnityEngine.Random.value > m_waterSpawnChance)
			{
				return false;
			}
			p.y = 30f;
		}
		else if (p.y > m_mountainLimit)
		{
			if (UnityEngine.Random.value > m_mountainSpawnChance)
			{
				return false;
			}
		}
		else if (UnityEngine.Random.value > m_landSpawnChance)
		{
			return false;
		}
		return true;
	}
}
using System;
using System.Collections.Generic;
using Steamworks;
using UnityEngine;

public class DLCMan : MonoBehaviour
{
	[Serializable]
	public class DLCInfo
	{
		public string m_name = "DLC";

		public uint[] m_steamAPPID = new uint[0];

		[NonSerialized]
		public bool m_installed;
	}

	private static DLCMan m_instance;

	public List<DLCInfo> m_dlcs = new List<DLCInfo>();

	public static DLCMan instance => m_instance;

	private void Awake()
	{
		m_instance = this;
		CheckDLCsSTEAM();
	}

	private void OnDestroy()
	{
		if (m_instance == this)
		{
			m_instance = null;
		}
	}

	public bool IsDLCInstalled(string name)
	{
		if (name.Length == 0)
		{
			return true;
		}
		foreach (DLCInfo dlc in m_dlcs)
		{
			if (dlc.m_name == name)
			{
				return dlc.m_installed;
			}
		}
		ZLog.LogWarning("DLC " + name + " not registered in DLCMan");
		return false;
	}

	private void CheckDLCsSTEAM()
	{
		if (!SteamManager.Initialized)
		{
			ZLog.Log("Steam not initialized");
			return;
		}
		ZLog.Log("Checking for installed DLCs");
		foreach (DLCInfo dlc in m_dlcs)
		{
			dlc.m_installed = IsDLCInstalled(dlc);
			ZLog.Log("DLC:" + dlc.m_name + " installed:" + dlc.m_installed);
		}
	}

	private bool IsDLCInstalled(DLCInfo dlc)
	{
		uint[] steamAPPID = dlc.m_steamAPPID;
		foreach (uint id in steamAPPID)
		{
			if (IsDLCInstalled(id))
			{
				return true;
			}
		}
		return false;
	}

	private bool IsDLCInstalled(uint id)
	{
		AppId_t appId_t = new AppId_t(id);
		int dLCCount = SteamApps.GetDLCCount();
		for (int i = 0; i < dLCCount; i++)
		{
			if (SteamApps.BGetDLCDataByIndex(i, out var pAppID, out var _, out var _, 200) && appId_t == pAppID)
			{
				ZLog.Log("DLC installed:" + id);
				return SteamApps.BIsDlcInstalled(pAppID);
			}
		}
		return false;
	}
}
using System;

[Flags]
public enum DnsResolveFlags
{
	None = 0,
	CacheOnly = 1,
	DontCheckCache = 2
}
using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Sockets;
using NetworkingUtils;

public class DnsResolver
{
	private readonly Dictionary<string, IPv6Address?> m_dnsResolveCache = new Dictionary<string, IPv6Address?>();

	private readonly Dictionary<string, DnsResolveRequest> m_dnsResolveRequests = new Dictionary<string, DnsResolveRequest>();

	public bool ResolveDomainName(string domainName, out IPv6Address? address, DnsResolveFlags flags = DnsResolveFlags.None)
	{
		if (!flags.HasFlag(DnsResolveFlags.DontCheckCache) && m_dnsResolveCache.TryGetValue(domainName, out address))
		{
			return true;
		}
		if (flags.HasFlag(DnsResolveFlags.CacheOnly))
		{
			address = null;
			return false;
		}
		if (!URLToIP(domainName, out address))
		{
			m_dnsResolveCache.Add(domainName, null);
			return false;
		}
		SetCacheEntry(domainName, address);
		return true;
	}

	public void ResolveDomainNameAsync(string domainName, ResolveDomainCompletedHandler completedCallback, DnsResolveFlags flags = DnsResolveFlags.None)
	{
		DnsResolveRequest value2;
		if (!flags.HasFlag(DnsResolveFlags.DontCheckCache) && m_dnsResolveCache.TryGetValue(domainName, out var value))
		{
			completedCallback?.Invoke(succeeded: true, value);
		}
		else if (flags.HasFlag(DnsResolveFlags.CacheOnly))
		{
			completedCallback?.Invoke(succeeded: false, null);
		}
		else if (!m_dnsResolveRequests.TryGetValue(domainName, out value2))
		{
			value2 = new DnsResolveRequest(domainName, OnResolveDomainNameAsyncCompleted);
			m_dnsResolveRequests.Add(domainName, value2);
			value2.Completed += completedCallback;
			value2.RunAsync();
		}
		else
		{
			value2.Completed += completedCallback;
		}
	}

	public void ClearCache()
	{
		m_dnsResolveCache.Clear();
	}

	private void OnResolveDomainNameAsyncCompleted(DnsResolveRequest request)
	{
		m_dnsResolveRequests.Remove(request.m_domainName);
		SetCacheEntry(request.m_domainName, request.Address);
	}

	private void SetCacheEntry(string domainName, IPv6Address? address)
	{
		m_dnsResolveCache.Remove(domainName);
		m_dnsResolveCache.Add(domainName, address);
	}

	public static bool URLToIP(string url, out IPv6Address? ip)
	{
		ip = null;
		try
		{
			IPAddress[] hostAddresses = Dns.GetHostAddresses(url);
			if (hostAddresses.Length == 0)
			{
				return false;
			}
			ZLog.Log("Got dns entries: " + hostAddresses.Length);
			IPAddress[] array = hostAddresses;
			IPv6Address? pv6Address;
			foreach (IPAddress iPAddress in array)
			{
				if (iPAddress.AddressFamily == AddressFamily.InterNetwork)
				{
					ip = new IPv4Address(iPAddress.GetAddressBytes());
					return true;
				}
				pv6Address = ip;
				if (!pv6Address.HasValue && iPAddress.AddressFamily == AddressFamily.InterNetworkV6)
				{
					ip = new IPv6Address(iPAddress.GetAddressBytes());
				}
			}
			pv6Address = ip;
			return pv6Address.HasValue;
		}
		catch (Exception ex)
		{
			ZLog.Log("Exception while finding ip:" + ex.ToString());
			ip = null;
			return false;
		}
	}
}
using System;
using System.ComponentModel;
using NetworkingUtils;

public class DnsResolveRequest
{
	public readonly string m_domainName;

	private bool m_succeeded;

	private IPv6Address? m_resolvedAddress;

	private readonly BackgroundWorker m_worker;

	private bool m_completed;

	private DnsResolveRequestCompletedHandler m_callback;

	public IPv6Address? Address
	{
		get
		{
			if (!m_completed)
			{
				throw new InvalidOperationException("Must wait for worker to complete before checking if it succeeded!");
			}
			return m_resolvedAddress;
		}
	}

	public event ResolveDomainCompletedHandler Completed;

	public DnsResolveRequest(string domainName, DnsResolveRequestCompletedHandler completedCallback)
	{
		m_domainName = domainName;
		m_worker = new BackgroundWorker();
		m_worker.DoWork += delegate
		{
			m_succeeded = DnsResolver.URLToIP(m_domainName, out m_resolvedAddress);
		};
		m_worker.RunWorkerCompleted += delegate
		{
			m_completed = true;
			m_callback?.Invoke(this);
			this.Completed?.Invoke(m_succeeded, m_resolvedAddress);
		};
		m_callback = completedCallback;
	}

	public void RunAsync()
	{
		m_worker.RunWorkerAsync(this);
	}
}
public delegate void DnsResolveRequestCompletedHandler(DnsResolveRequest request);
using UnityEngine;

public class Door : MonoBehaviour, Hoverable, Interactable
{
	public string m_name = "door";

	public ItemDrop m_keyItem;

	public bool m_canNotBeClosed;

	public bool m_invertedOpenClosedText;

	public bool m_checkGuardStone = true;

	public GameObject m_openEnable;

	public EffectList m_openEffects = new EffectList();

	public EffectList m_closeEffects = new EffectList();

	public EffectList m_lockedEffects = new EffectList();

	private ZNetView m_nview;

	private Animator m_animator;

	private uint m_lastDataRevision = uint.MaxValue;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		if (m_nview.GetZDO() != null)
		{
			m_animator = GetComponentInChildren<Animator>();
			if ((bool)m_nview)
			{
				m_nview.Register<bool>("UseDoor", RPC_UseDoor);
			}
			InvokeRepeating("UpdateState", 0f, 0.2f);
		}
	}

	private void UpdateState()
	{
		if (m_nview.IsValid())
		{
			uint dataRevision = m_nview.GetZDO().DataRevision;
			if (m_lastDataRevision != dataRevision)
			{
				m_lastDataRevision = dataRevision;
				int state = m_nview.GetZDO().GetInt(ZDOVars.s_state);
				SetState(state);
			}
		}
	}

	private void SetState(int state)
	{
		if (m_animator.GetInteger("state") != state)
		{
			if (state != 0)
			{
				m_openEffects.Create(base.transform.position, base.transform.rotation);
			}
			else
			{
				m_closeEffects.Create(base.transform.position, base.transform.rotation);
			}
			m_animator.SetInteger("state", state);
		}
		if ((bool)m_openEnable)
		{
			m_openEnable.SetActive(state != 0);
		}
	}

	private bool CanInteract()
	{
		if ((m_keyItem != null || m_canNotBeClosed) && m_nview.GetZDO().GetInt(ZDOVars.s_state) != 0)
		{
			return false;
		}
		if (!m_animator.GetCurrentAnimatorStateInfo(0).IsTag("open"))
		{
			return m_animator.GetCurrentAnimatorStateInfo(0).IsTag("closed");
		}
		return true;
	}

	public string GetHoverText()
	{
		if (!m_nview.IsValid())
		{
			return "";
		}
		if (m_canNotBeClosed && !CanInteract())
		{
			return "";
		}
		if (m_checkGuardStone && !PrivateArea.CheckAccess(base.transform.position, 0f, flash: false))
		{
			return Localization.instance.Localize(m_name + "\n$piece_noaccess");
		}
		if (CanInteract())
		{
			if (m_nview.GetZDO().GetInt(ZDOVars.s_state) != 0)
			{
				return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] " + (m_invertedOpenClosedText ? "$piece_door_open" : "$piece_door_close"));
			}
			return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] " + (m_invertedOpenClosedText ? "$piece_door_close" : "$piece_door_open"));
		}
		return Localization.instance.Localize(m_name);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		if (!CanInteract())
		{
			return false;
		}
		if (m_checkGuardStone && !PrivateArea.CheckAccess(base.transform.position))
		{
			return true;
		}
		if (m_keyItem != null)
		{
			if (!HaveKey(character))
			{
				m_lockedEffects.Create(base.transform.position, base.transform.rotation);
				if (Game.m_worldLevel > 0 && HaveKey(character, matchWorldLevel: false))
				{
					character.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_ng_the_x") + m_keyItem.m_itemData.m_shared.m_name + Localization.instance.Localize("$msg_ng_x_is_too_low"));
				}
				else
				{
					character.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_door_needkey", m_keyItem.m_itemData.m_shared.m_name));
				}
				return true;
			}
			character.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_door_usingkey", m_keyItem.m_itemData.m_shared.m_name));
		}
		Vector3 normalized = (character.transform.position - base.transform.position).normalized;
		Game.instance.IncrementPlayerStat((m_nview.GetZDO().GetInt(ZDOVars.s_state) == 0) ? PlayerStatType.DoorsOpened : PlayerStatType.DoorsClosed);
		Open(normalized);
		return true;
	}

	private void Open(Vector3 userDir)
	{
		bool flag = Vector3.Dot(base.transform.forward, userDir) < 0f;
		m_nview.InvokeRPC("UseDoor", flag);
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		if (m_keyItem != null && m_keyItem.m_itemData.m_shared.m_name == item.m_shared.m_name)
		{
			if (!CanInteract())
			{
				return false;
			}
			if (m_checkGuardStone && !PrivateArea.CheckAccess(base.transform.position))
			{
				return true;
			}
			user.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_door_usingkey", m_keyItem.m_itemData.m_shared.m_name));
			Vector3 normalized = (user.transform.position - base.transform.position).normalized;
			Open(normalized);
			return true;
		}
		return false;
	}

	private bool HaveKey(Humanoid player, bool matchWorldLevel = true)
	{
		if (m_keyItem == null)
		{
			return true;
		}
		return player.GetInventory().HaveItem(m_keyItem.m_itemData.m_shared.m_name, matchWorldLevel);
	}

	private void RPC_UseDoor(long uid, bool forward)
	{
		if (!CanInteract())
		{
			return;
		}
		if (m_nview.GetZDO().GetInt(ZDOVars.s_state) == 0)
		{
			if (forward)
			{
				m_nview.GetZDO().Set(ZDOVars.s_state, 1);
			}
			else
			{
				m_nview.GetZDO().Set(ZDOVars.s_state, -1);
			}
		}
		else
		{
			m_nview.GetZDO().Set(ZDOVars.s_state, 0);
		}
		UpdateState();
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class DreamTexts : MonoBehaviour
{
	[Serializable]
	public class DreamText
	{
		public string m_text = "Fluffy sheep";

		public float m_chanceToDream = 0.1f;

		public List<string> m_trueKeys = new List<string>();

		public List<string> m_falseKeys = new List<string>();
	}

	public List<DreamText> m_texts = new List<DreamText>();

	public DreamText GetRandomDreamText()
	{
		List<DreamText> list = new List<DreamText>();
		foreach (DreamText text in m_texts)
		{
			if (HaveGlobalKeys(text))
			{
				list.Add(text);
			}
		}
		if (list.Count == 0)
		{
			return null;
		}
		DreamText dreamText = list[UnityEngine.Random.Range(0, list.Count)];
		if (UnityEngine.Random.value <= dreamText.m_chanceToDream)
		{
			return dreamText;
		}
		return null;
	}

	private bool HaveGlobalKeys(DreamText dream)
	{
		foreach (string trueKey in dream.m_trueKeys)
		{
			if (!ZoneSystem.instance.GetGlobalKey(trueKey))
			{
				return false;
			}
		}
		foreach (string falseKey in dream.m_falseKeys)
		{
			if (ZoneSystem.instance.GetGlobalKey(falseKey))
			{
				return false;
			}
		}
		return true;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class DropOnDestroyed : MonoBehaviour
{
	[Header("Drops")]
	public DropTable m_dropWhenDestroyed = new DropTable();

	public float m_spawnYOffset = 0.5f;

	public float m_spawnYStep = 0.3f;

	private void Awake()
	{
		IDestructible component = GetComponent<IDestructible>();
		Destructible destructible = component as Destructible;
		if ((bool)destructible)
		{
			destructible.m_onDestroyed = (Action)Delegate.Combine(destructible.m_onDestroyed, new Action(OnDestroyed));
		}
		WearNTear wearNTear = component as WearNTear;
		if ((bool)wearNTear)
		{
			wearNTear.m_onDestroyed = (Action)Delegate.Combine(wearNTear.m_onDestroyed, new Action(OnDestroyed));
		}
	}

	private void OnDestroyed()
	{
		float groundHeight = ZoneSystem.instance.GetGroundHeight(base.transform.position);
		Vector3 position = base.transform.position;
		if (position.y < groundHeight)
		{
			position.y = groundHeight + 0.1f;
		}
		List<GameObject> dropList = m_dropWhenDestroyed.GetDropList();
		for (int i = 0; i < dropList.Count; i++)
		{
			Vector2 vector = UnityEngine.Random.insideUnitCircle * 0.5f;
			Vector3 position2 = position + Vector3.up * m_spawnYOffset + new Vector3(vector.x, m_spawnYStep * (float)i, vector.y);
			Quaternion rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
			ItemDrop.OnCreateNew(UnityEngine.Object.Instantiate(dropList[i], position2, rotation));
		}
	}
}
using UnityEngine;

public class DropProjectileOverDistance : MonoBehaviour
{
	public GameObject m_projectilePrefab;

	public float m_distancePerProjectile = 5f;

	public float m_spawnHeight = 1f;

	public bool m_snapToGround;

	[Tooltip("If higher than 0, will force a spawn if nothing has spawned in that amount of time.")]
	public float m_timeToForceSpawn = -1f;

	public float m_minVelocity;

	public float m_maxVelocity;

	private Character m_character;

	private ZNetView m_nview;

	private Vector3 lastPosition;

	private float m_distanceAccumulator;

	private float m_spawnTimer;

	private const int c_MaxSpawnsPerFrame = 3;

	private void Awake()
	{
		m_character = GetComponent<Character>();
		m_nview = GetComponent<ZNetView>();
		if ((object)m_projectilePrefab == null)
		{
			base.enabled = false;
		}
	}

	private void FixedUpdate()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner())
		{
			return;
		}
		Vector3 vector = base.transform.position.Horizontal();
		m_distanceAccumulator += Vector3.Distance(lastPosition, vector);
		Vector3 vector2 = lastPosition.DirTo(vector);
		if (lastPosition != vector)
		{
			lastPosition = vector;
		}
		if (m_timeToForceSpawn > 0f)
		{
			m_spawnTimer += Time.deltaTime;
			if (m_spawnTimer > m_timeToForceSpawn)
			{
				SpawnProjectile(base.transform.position, vector2);
				m_distanceAccumulator -= m_distancePerProjectile;
				m_distanceAccumulator = Mathf.Max(m_distanceAccumulator, 0f);
			}
		}
		if (!(m_distanceAccumulator < m_distancePerProjectile))
		{
			int num = Mathf.FloorToInt(m_distanceAccumulator / m_distancePerProjectile);
			for (int i = 0; i < Mathf.Min(3, num); i++)
			{
				SpawnProjectile(base.transform.position - vector2 * i, vector2);
				m_distanceAccumulator -= m_distancePerProjectile;
				num--;
			}
			m_distanceAccumulator -= m_distancePerProjectile * (float)num;
		}
	}

	private void SpawnProjectile(Vector3 point, Vector3 travelDirection)
	{
		m_spawnTimer = 0f;
		if (m_projectilePrefab.GetComponent<IProjectile>() == null)
		{
			ZLog.LogWarning("Attempted to spawn non-projectile");
		}
		point.y += m_spawnHeight;
		if (m_snapToGround)
		{
			ZoneSystem.instance.GetSolidHeight(point, out var height);
			point.y = height;
		}
		Object.Instantiate(m_projectilePrefab, point, Quaternion.LookRotation(travelDirection)).GetComponent<IProjectile>().Setup(m_character, travelDirection * Random.Range(m_minVelocity, m_maxVelocity), -1f, null, null, null);
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = new Color(0.76f, 0.52f, 0.55f);
		Gizmos.DrawLine(base.transform.position, base.transform.position + Vector3.up * m_spawnHeight);
		Vector3 vector = base.transform.position + base.transform.forward * m_distancePerProjectile;
		Gizmos.DrawLine(base.transform.position + Vector3.up * 0.5f * m_spawnHeight, vector + Vector3.up * 0.5f * m_spawnHeight);
		Gizmos.DrawLine(vector, vector + Vector3.up * m_spawnHeight);
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public class DropTable
{
	[Serializable]
	public struct DropData
	{
		public GameObject m_item;

		public int m_stackMin;

		public int m_stackMax;

		public float m_weight;

		public bool m_dontScale;
	}

	private static List<DropData> drops = new List<DropData>();

	private static List<ItemDrop.ItemData> toDrop = new List<ItemDrop.ItemData>();

	private static List<DropData> dropsTemp = new List<DropData>();

	public List<DropData> m_drops = new List<DropData>();

	public int m_dropMin = 1;

	public int m_dropMax = 1;

	[Range(0f, 1f)]
	public float m_dropChance = 1f;

	public bool m_oneOfEach;

	public DropTable Clone()
	{
		return MemberwiseClone() as DropTable;
	}

	public List<ItemDrop.ItemData> GetDropListItems()
	{
		toDrop.Clear();
		if (m_drops.Count == 0)
		{
			return toDrop;
		}
		if (UnityEngine.Random.value > m_dropChance)
		{
			return toDrop;
		}
		drops.Clear();
		drops.AddRange(m_drops);
		float num = 0f;
		foreach (DropData drop in drops)
		{
			num += drop.m_weight;
		}
		int num2 = UnityEngine.Random.Range(m_dropMin, m_dropMax + 1);
		for (int i = 0; i < num2; i++)
		{
			float num3 = UnityEngine.Random.Range(0f, num);
			bool flag = false;
			float num4 = 0f;
			foreach (DropData drop2 in drops)
			{
				num4 += drop2.m_weight;
				if (num3 <= num4)
				{
					flag = true;
					AddItemToList(toDrop, drop2);
					if (m_oneOfEach)
					{
						drops.Remove(drop2);
						num -= drop2.m_weight;
					}
					break;
				}
			}
			if (!flag && drops.Count > 0)
			{
				AddItemToList(toDrop, drops[0]);
			}
		}
		return toDrop;
	}

	private void AddItemToList(List<ItemDrop.ItemData> toDrop, DropData data)
	{
		ItemDrop.ItemData itemData = data.m_item.GetComponent<ItemDrop>().m_itemData;
		ItemDrop.ItemData itemData2 = itemData.Clone();
		itemData2.m_dropPrefab = data.m_item;
		int num = Mathf.Max(1, data.m_stackMin);
		int num2 = Mathf.Min(itemData.m_shared.m_maxStackSize, data.m_stackMax);
		itemData2.m_stack = (data.m_dontScale ? UnityEngine.Random.Range(num, num2 + 1) : Game.instance.ScaleDrops(itemData2, num, num2 + 1));
		itemData2.m_worldLevel = (byte)Game.m_worldLevel;
		toDrop.Add(itemData2);
	}

	public List<GameObject> GetDropList()
	{
		int amount = UnityEngine.Random.Range(m_dropMin, m_dropMax + 1);
		return GetDropList(amount);
	}

	private List<GameObject> GetDropList(int amount)
	{
		List<GameObject> list = new List<GameObject>();
		if (m_drops.Count == 0)
		{
			return list;
		}
		if (UnityEngine.Random.value > m_dropChance)
		{
			return list;
		}
		float num = Mathf.Ceil(Game.m_resourceRate);
		for (int i = 0; (float)i < num; i++)
		{
			dropsTemp.Clear();
			dropsTemp.AddRange(m_drops);
			bool num2 = (float)(i + 1) == num;
			float num3 = Game.m_resourceRate % 1f;
			if (num3 == 0f)
			{
				num3 = 1f;
			}
			float num4 = ((!num2) ? 1f : ((num3 == 0f) ? 1f : num3));
			float num5 = 0f;
			foreach (DropData item in dropsTemp)
			{
				num5 += item.m_weight;
				if (item.m_weight <= 0f && dropsTemp.Count > 1)
				{
					ZLog.LogWarning($"Droptable item '{item.m_item}' has a weight of 0 and will not be dropped correctly!");
				}
			}
			if (num4 < 1f && amount > dropsTemp.Count)
			{
				amount = (int)Mathf.Max(1f, Mathf.Round((float)amount * num4));
			}
			for (int j = 0; j < amount; j++)
			{
				float num6 = UnityEngine.Random.Range(0f, num5);
				bool flag = false;
				float num7 = 0f;
				foreach (DropData item2 in dropsTemp)
				{
					num7 += item2.m_weight;
					if (num6 <= num7)
					{
						flag = true;
						int num8 = 0;
						num8 = ((!item2.m_dontScale) ? ((int)Mathf.Max(1f, Mathf.Round(UnityEngine.Random.Range(Mathf.Round((float)item2.m_stackMin * num4), Mathf.Round((float)item2.m_stackMax * num4))))) : ((i == 0) ? UnityEngine.Random.Range(item2.m_stackMin, item2.m_stackMax) : 0));
						for (int k = 0; k < num8; k++)
						{
							list.Add(item2.m_item);
						}
						if (m_oneOfEach)
						{
							dropsTemp.Remove(item2);
							num5 -= item2.m_weight;
						}
						break;
					}
				}
				if (!flag && dropsTemp.Count > 0)
				{
					list.Add(dropsTemp[0].m_item);
				}
			}
		}
		return list;
	}

	public bool IsEmpty()
	{
		return m_drops.Count == 0;
	}
}
using System;
using System.Collections.Generic;
using SoftReferenceableAssets;
using UnityEngine;

public class DungeonDB : MonoBehaviour
{
	[Serializable]
	public class RoomData
	{
		public SoftReference<GameObject> m_prefab;

		public bool m_enabled;

		[BitMask(typeof(Room.Theme))]
		public Room.Theme m_theme;

		[NonSerialized]
		private Room m_loadedRoom;

		public Room RoomInPrefab
		{
			get
			{
				if (m_loadedRoom == null)
				{
					if (m_prefab.Asset != null)
					{
						m_loadedRoom = m_prefab.Asset.GetComponent<Room>();
					}
					else
					{
						Debug.LogError($"Room {m_prefab} wasn't loaded!");
					}
				}
				return m_loadedRoom;
			}
		}

		public int Hash => m_prefab.Name.GetStableHashCode();
	}

	private static DungeonDB m_instance;

	public List<string> m_roomScenes = new List<string>();

	public List<GameObject> m_roomLists = new List<GameObject>();

	private List<RoomData> m_rooms = new List<RoomData>();

	private Dictionary<int, RoomData> m_roomByHash = new Dictionary<int, RoomData>();

	private bool m_error;

	public static DungeonDB instance => m_instance;

	private void Awake()
	{
		m_instance = this;
		ZLog.Log("DungeonDB Awake " + Time.frameCount);
	}

	public bool SkipSaving()
	{
		return m_error;
	}

	private void Start()
	{
		ZLog.Log("DungeonDB Start " + Time.frameCount);
		SetupRooms();
		GenerateHashList();
		LoadRooms();
	}

	private void SetupRooms()
	{
		foreach (GameObject roomList in m_roomLists)
		{
			UnityEngine.Object.Instantiate(roomList);
		}
		foreach (RoomList allRoomList in RoomList.GetAllRoomLists())
		{
			m_rooms.AddRange(allRoomList.m_rooms);
		}
	}

	public static List<RoomData> GetRooms()
	{
		return m_instance.m_rooms;
	}

	public RoomData GetRoom(int hash)
	{
		if (m_roomByHash.TryGetValue(hash, out var value))
		{
			return value;
		}
		return null;
	}

	private void GenerateHashList()
	{
		m_roomByHash.Clear();
		foreach (RoomData room in m_rooms)
		{
			int hash = room.Hash;
			if (m_roomByHash.ContainsKey(hash))
			{
				ZLog.LogError("Room with name " + room.m_prefab.Name + " already registered");
			}
			else
			{
				m_roomByHash.Add(hash, room);
			}
		}
	}

	private void LoadRooms()
	{
		if (!Settings.AssetMemoryUsagePolicy.HasFlag(AssetMemoryUsagePolicy.KeepAsynchronousLoadedBit))
		{
			return;
		}
		ReferenceHolder referenceHolder = base.gameObject.AddComponent<ReferenceHolder>();
		foreach (RoomData room in m_rooms)
		{
			if (room.m_enabled)
			{
				room.m_prefab.Load();
				referenceHolder.HoldReferenceTo(room.m_prefab);
				room.m_prefab.Release();
			}
		}
	}
}
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using SoftReferenceableAssets;
using UnityEngine;

public class DungeonGenerator : MonoBehaviour
{
	[Serializable]
	public class DoorDef
	{
		public GameObject m_prefab;

		public string m_connectionType = "";

		[Tooltip("Will use default door chance set in DungeonGenerator if set to zero to default to old behaviour")]
		[Range(0f, 1f)]
		public float m_chance;
	}

	private struct RoomPlacementData(DungeonDB.RoomData roomData, Vector3 position, Quaternion rotation)
	{
		public DungeonDB.RoomData m_roomData = roomData;

		public Vector3 m_position = position;

		public Quaternion m_rotation = rotation;
	}

	public enum Algorithm
	{
		Dungeon,
		CampGrid,
		CampRadial
	}

	private static MemoryStream saveStream = new MemoryStream();

	private static BinaryWriter saveWriter = new BinaryWriter(saveStream);

	public static int m_forceSeed = int.MinValue;

	public Algorithm m_algorithm;

	public int m_maxRooms = 3;

	public int m_minRooms = 20;

	public int m_minRequiredRooms;

	public List<string> m_requiredRooms = new List<string>();

	[Tooltip("Rooms and endcaps will be placed using weights.")]
	public bool m_alternativeFunctionality;

	[BitMask(typeof(Room.Theme))]
	public Room.Theme m_themes = Room.Theme.Crypt;

	[Header("Dungeon")]
	public List<DoorDef> m_doorTypes = new List<DoorDef>();

	[Range(0f, 1f)]
	public float m_doorChance = 0.5f;

	[Header("Camp")]
	public float m_maxTilt = 10f;

	public float m_tileWidth = 8f;

	public int m_gridSize = 4;

	public float m_spawnChance = 1f;

	[Header("Camp radial")]
	public float m_campRadiusMin = 15f;

	public float m_campRadiusMax = 30f;

	public float m_minAltitude = 1f;

	public int m_perimeterSections;

	public float m_perimeterBuffer = 2f;

	[Header("Misc")]
	public Vector3 m_zoneCenter = new Vector3(0f, 0f, 0f);

	public Vector3 m_zoneSize = new Vector3(64f, 64f, 64f);

	[Tooltip("Makes the dungeon entrance start at the given interior transform (including rotation) rather than straight above the entrance, which gives the dungeon much more room to fill out the entire zone. Must use together with Location.m_useCustomInteriorTransform to make sure seeds are deterministic.")]
	public bool m_useCustomInteriorTransform;

	[HideInInspector]
	public int m_generatedSeed;

	private bool m_hasGeneratedSeed;

	private ZDO m_zdoSetToBeLoadingInZone;

	private int m_roomsToLoad;

	private RoomPlacementData[] m_loadedRooms;

	private List<IReferenceCounted> m_heldReferences = new List<IReferenceCounted>();

	private static List<Room> m_placedRooms = new List<Room>();

	private static List<RoomConnection> m_openConnections = new List<RoomConnection>();

	private static List<RoomConnection> m_doorConnections = new List<RoomConnection>();

	private static List<DungeonDB.RoomData> m_availableRooms = new List<DungeonDB.RoomData>();

	private static List<DungeonDB.RoomData> m_tempRooms = new List<DungeonDB.RoomData>();

	private BoxCollider m_colliderA;

	private BoxCollider m_colliderB;

	private ZNetView m_nview;

	[HideInInspector]
	public Vector3 m_originalPosition;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		Load();
		if (m_loadedRooms.Length != 0)
		{
			LoadRoomPrefabsAsync();
		}
	}

	private void OnDestroy()
	{
		ReleaseHeldReferences();
	}

	private void ReleaseHeldReferences()
	{
		for (int i = 0; i < m_heldReferences.Count; i++)
		{
			m_heldReferences[i].Release();
		}
		m_heldReferences.Clear();
		if (m_zdoSetToBeLoadingInZone != null)
		{
			ZoneSystem.instance.UnsetLoadingInZone(m_zdoSetToBeLoadingInZone);
			m_zdoSetToBeLoadingInZone = null;
		}
	}

	public void Clear()
	{
		while (base.transform.childCount > 0)
		{
			UnityEngine.Object.DestroyImmediate(base.transform.GetChild(0).gameObject);
		}
	}

	public void Generate(ZoneSystem.SpawnMode mode)
	{
		int seed = GetSeed();
		Generate(seed, mode);
	}

	public int GetSeed()
	{
		if (m_hasGeneratedSeed)
		{
			return m_generatedSeed;
		}
		if (m_forceSeed != int.MinValue)
		{
			m_generatedSeed = m_forceSeed;
			m_forceSeed = int.MinValue;
		}
		else
		{
			int seed = WorldGenerator.instance.GetSeed();
			Vector3 position = base.transform.position;
			Vector2i zone = ZoneSystem.GetZone(base.transform.position);
			m_generatedSeed = seed + zone.x * 4271 + zone.y * -7187 + (int)position.x * -4271 + (int)position.y * 9187 + (int)position.z * -2134;
		}
		m_hasGeneratedSeed = true;
		return m_generatedSeed;
	}

	public void Generate(int seed, ZoneSystem.SpawnMode mode)
	{
		DateTime now = DateTime.Now;
		m_generatedSeed = seed;
		Clear();
		SetupColliders();
		SetupAvailableRooms();
		for (int i = 0; i < m_availableRooms.Count; i++)
		{
			m_availableRooms[i].m_prefab.Load();
		}
		if ((bool)ZoneSystem.instance)
		{
			Vector2i zone = ZoneSystem.GetZone(base.transform.position);
			m_zoneCenter = ZoneSystem.GetZonePos(zone);
			m_zoneCenter.y = base.transform.position.y - m_originalPosition.y;
		}
		Bounds bounds = new Bounds(m_zoneCenter, m_zoneSize);
		ZLog.Log($"Generating {base.name}, Seed: {seed}, Bounds diff: {bounds.min - base.transform.position} / {bounds.max - base.transform.position}");
		ZLog.Log("Available rooms:" + m_availableRooms.Count);
		ZLog.Log("To place:" + m_maxRooms);
		m_placedRooms.Clear();
		m_openConnections.Clear();
		m_doorConnections.Clear();
		UnityEngine.Random.State state = UnityEngine.Random.state;
		UnityEngine.Random.InitState(seed);
		GenerateRooms(mode);
		for (int j = 0; j < m_availableRooms.Count; j++)
		{
			m_availableRooms[j].m_prefab.Release();
		}
		Save();
		ZLog.Log("Placed " + m_placedRooms.Count + " rooms");
		UnityEngine.Random.state = state;
		SnapToGround.SnappAll();
		if (mode == ZoneSystem.SpawnMode.Ghost)
		{
			foreach (Room placedRoom in m_placedRooms)
			{
				UnityEngine.Object.DestroyImmediate(placedRoom.gameObject);
			}
		}
		UnityEngine.Object.DestroyImmediate(m_colliderA);
		UnityEngine.Object.DestroyImmediate(m_colliderB);
		m_placedRooms.Clear();
		m_openConnections.Clear();
		m_doorConnections.Clear();
		_ = DateTime.Now - now;
	}

	private void LoadRoomPrefabsAsync()
	{
		ZLog.Log("Loading room prefabs asynchronously");
		if (m_zdoSetToBeLoadingInZone == null)
		{
			m_zdoSetToBeLoadingInZone = m_nview.GetZDO();
			ZoneSystem.instance.SetLoadingInZone(m_zdoSetToBeLoadingInZone);
		}
		m_roomsToLoad = m_loadedRooms.Length;
		int num = m_loadedRooms.Length;
		for (int i = 0; i < num; i++)
		{
			m_heldReferences.Add(m_loadedRooms[i].m_roomData.m_prefab);
			m_loadedRooms[i].m_roomData.m_prefab.LoadAsync(OnRoomLoaded);
		}
	}

	private void OnRoomLoaded(AssetID assetID, LoadResult result)
	{
		if (result == LoadResult.Succeeded && !(this == null) && !(base.gameObject == null))
		{
			m_roomsToLoad--;
			if (m_roomsToLoad <= 0)
			{
				Spawn();
				ReleaseHeldReferences();
			}
		}
	}

	private void Spawn()
	{
		ZLog.Log("Spawning dungeon");
		for (int i = 0; i < m_loadedRooms.Length; i++)
		{
			PlaceRoom(m_loadedRooms[i].m_roomData, m_loadedRooms[i].m_position, m_loadedRooms[i].m_rotation, null, ZoneSystem.SpawnMode.Client);
		}
		SnapToGround.SnappAll();
		m_loadedRooms = null;
	}

	private void GenerateRooms(ZoneSystem.SpawnMode mode)
	{
		switch (m_algorithm)
		{
		case Algorithm.Dungeon:
			GenerateDungeon(mode);
			break;
		case Algorithm.CampGrid:
			GenerateCampGrid(mode);
			break;
		case Algorithm.CampRadial:
			GenerateCampRadial(mode);
			break;
		}
	}

	private void GenerateDungeon(ZoneSystem.SpawnMode mode)
	{
		PlaceStartRoom(mode);
		PlaceRooms(mode);
		PlaceEndCaps(mode);
		PlaceDoors(mode);
	}

	private void GenerateCampGrid(ZoneSystem.SpawnMode mode)
	{
		float num = Mathf.Cos(MathF.PI / 180f * m_maxTilt);
		Vector3 vector = base.transform.position + new Vector3((float)(-m_gridSize) * m_tileWidth * 0.5f, 0f, (float)(-m_gridSize) * m_tileWidth * 0.5f);
		for (int i = 0; i < m_gridSize; i++)
		{
			for (int j = 0; j < m_gridSize; j++)
			{
				if (UnityEngine.Random.value > m_spawnChance)
				{
					continue;
				}
				Vector3 p = vector + new Vector3((float)j * m_tileWidth, 0f, (float)i * m_tileWidth);
				DungeonDB.RoomData randomWeightedRoom = GetRandomWeightedRoom(perimeterRoom: false);
				if (randomWeightedRoom == null)
				{
					continue;
				}
				if ((bool)ZoneSystem.instance)
				{
					ZoneSystem.instance.GetGroundData(ref p, out var normal, out var _, out var _, out var _);
					if (normal.y < num)
					{
						continue;
					}
				}
				Quaternion rot = Quaternion.Euler(0f, (float)UnityEngine.Random.Range(0, 16) * 22.5f, 0f);
				PlaceRoom(randomWeightedRoom, p, rot, null, mode);
			}
		}
	}

	private void GenerateCampRadial(ZoneSystem.SpawnMode mode)
	{
		float num = UnityEngine.Random.Range(m_campRadiusMin, m_campRadiusMax);
		float num2 = Mathf.Cos(MathF.PI / 180f * m_maxTilt);
		int num3 = UnityEngine.Random.Range(m_minRooms, m_maxRooms);
		int num4 = num3 * 20;
		int num5 = 0;
		for (int i = 0; i < num4; i++)
		{
			Vector3 p = base.transform.position + Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f) * Vector3.forward * UnityEngine.Random.Range(0f, num - m_perimeterBuffer);
			DungeonDB.RoomData randomWeightedRoom = GetRandomWeightedRoom(perimeterRoom: false);
			if (randomWeightedRoom == null)
			{
				continue;
			}
			if ((bool)ZoneSystem.instance)
			{
				ZoneSystem.instance.GetGroundData(ref p, out var normal, out var _, out var _, out var _);
				if (normal.y < num2 || p.y - 30f < m_minAltitude)
				{
					continue;
				}
			}
			Quaternion campRoomRotation = GetCampRoomRotation(randomWeightedRoom, p);
			if (!TestCollision(randomWeightedRoom.RoomInPrefab, p, campRoomRotation))
			{
				PlaceRoom(randomWeightedRoom, p, campRoomRotation, null, mode);
				num5++;
				if (num5 >= num3)
				{
					break;
				}
			}
		}
		if (m_perimeterSections > 0)
		{
			PlaceWall(num, m_perimeterSections, mode);
		}
	}

	private Quaternion GetCampRoomRotation(DungeonDB.RoomData room, Vector3 pos)
	{
		if (room.RoomInPrefab.m_faceCenter)
		{
			Vector3 vector = base.transform.position - pos;
			vector.y = 0f;
			if (vector == Vector3.zero)
			{
				vector = Vector3.forward;
			}
			vector.Normalize();
			float y = Mathf.Round(Utils.YawFromDirection(vector) / 22.5f) * 22.5f;
			return Quaternion.Euler(0f, y, 0f);
		}
		return Quaternion.Euler(0f, (float)UnityEngine.Random.Range(0, 16) * 22.5f, 0f);
	}

	private void PlaceWall(float radius, int sections, ZoneSystem.SpawnMode mode)
	{
		float num = Mathf.Cos(MathF.PI / 180f * m_maxTilt);
		int num2 = 0;
		int num3 = sections * 20;
		for (int i = 0; i < num3; i++)
		{
			DungeonDB.RoomData randomWeightedRoom = GetRandomWeightedRoom(perimeterRoom: true);
			if (randomWeightedRoom == null)
			{
				continue;
			}
			Vector3 p = base.transform.position + Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f) * Vector3.forward * radius;
			Quaternion campRoomRotation = GetCampRoomRotation(randomWeightedRoom, p);
			if ((bool)ZoneSystem.instance)
			{
				ZoneSystem.instance.GetGroundData(ref p, out var normal, out var _, out var _, out var _);
				if (normal.y < num || p.y - 30f < m_minAltitude)
				{
					continue;
				}
			}
			if (!TestCollision(randomWeightedRoom.RoomInPrefab, p, campRoomRotation))
			{
				PlaceRoom(randomWeightedRoom, p, campRoomRotation, null, mode);
				num2++;
				if (num2 >= sections)
				{
					break;
				}
			}
		}
	}

	private void Save()
	{
		if (m_nview == null)
		{
			return;
		}
		ZDO zDO = m_nview.GetZDO();
		saveStream.SetLength(0L);
		saveWriter.Write(m_placedRooms.Count);
		for (int i = 0; i < m_placedRooms.Count; i++)
		{
			Room room = m_placedRooms[i];
			saveWriter.Write(room.GetHash());
			saveWriter.Write(room.transform.position);
			saveWriter.Write(room.transform.rotation);
		}
		zDO.Set(ZDOVars.s_roomData, saveStream.ToArray());
		if (zDO.GetInt(ZDOVars.s_rooms, out var value))
		{
			zDO.RemoveInt(ZDOVars.s_rooms);
			for (int j = 0; j < value; j++)
			{
				string text = "room" + j;
				zDO.RemoveInt(text);
				zDO.RemoveVec3(text + "_pos");
				zDO.RemoveQuaternion(text + "_rot");
				zDO.RemoveInt(text + "_seed");
			}
			ZLog.Log($"Cleaned up old dungeon data format for {value} rooms.");
		}
	}

	private void Load()
	{
		if (m_nview == null)
		{
			return;
		}
		DateTime now = DateTime.Now;
		ZLog.Log("Loading dungeon");
		ZDO zDO = m_nview.GetZDO();
		int num = 0;
		if (zDO.GetByteArray(ZDOVars.s_roomData, out var value))
		{
			BinaryReader binaryReader = new BinaryReader(new MemoryStream(value));
			int num2 = binaryReader.ReadInt32();
			m_loadedRooms = new RoomPlacementData[num2];
			for (int i = 0; i < num2; i++)
			{
				int hash = binaryReader.ReadInt32();
				Vector3 position = binaryReader.ReadVector3();
				Quaternion rotation = binaryReader.ReadQuaternion();
				DungeonDB.RoomData room = DungeonDB.instance.GetRoom(hash);
				if (room == null)
				{
					ZLog.LogWarning("Missing room:" + hash);
				}
				else
				{
					m_loadedRooms[num++] = new RoomPlacementData(room, position, rotation);
				}
			}
			ZLog.Log($"Dungeon loaded with {num2} rooms in {(DateTime.Now - now).TotalMilliseconds} ms.");
		}
		else
		{
			int num3 = zDO.GetInt("rooms");
			m_loadedRooms = new RoomPlacementData[num3];
			for (int j = 0; j < num3; j++)
			{
				string text = "room" + j;
				int hash2 = zDO.GetInt(text);
				Vector3 vec = zDO.GetVec3(text + "_pos", Vector3.zero);
				Quaternion quaternion = zDO.GetQuaternion(text + "_rot", Quaternion.identity);
				DungeonDB.RoomData room2 = DungeonDB.instance.GetRoom(hash2);
				if (room2 == null)
				{
					ZLog.LogWarning("Missing room:" + hash2);
				}
				else
				{
					m_loadedRooms[num++] = new RoomPlacementData(room2, vec, quaternion);
				}
			}
			ZLog.Log($"Dungeon loaded with {num3} rooms from old format in {(DateTime.Now - now).TotalMilliseconds} ms.");
		}
		if (num < m_loadedRooms.Length)
		{
			RoomPlacementData[] array = new RoomPlacementData[num];
			Array.Copy(m_loadedRooms, array, num);
			m_loadedRooms = array;
		}
	}

	private void SetupAvailableRooms()
	{
		m_availableRooms.Clear();
		foreach (DungeonDB.RoomData room in DungeonDB.GetRooms())
		{
			if ((room.m_theme & m_themes) != Room.Theme.None && room.m_enabled)
			{
				m_availableRooms.Add(room);
			}
		}
	}

	public SoftReference<GameObject>[] GetAvailableRoomPrefabs()
	{
		SetupAvailableRooms();
		SoftReference<GameObject>[] array = new SoftReference<GameObject>[m_availableRooms.Count];
		for (int i = 0; i < m_availableRooms.Count; i++)
		{
			array[i] = m_availableRooms[i].m_prefab;
		}
		return array;
	}

	private DoorDef FindDoorType(string type)
	{
		List<DoorDef> list = new List<DoorDef>();
		foreach (DoorDef doorType in m_doorTypes)
		{
			if (doorType.m_connectionType == type)
			{
				list.Add(doorType);
			}
		}
		if (list.Count == 0)
		{
			return null;
		}
		return list[UnityEngine.Random.Range(0, list.Count)];
	}

	private void PlaceDoors(ZoneSystem.SpawnMode mode)
	{
		int num = 0;
		foreach (RoomConnection doorConnection in m_doorConnections)
		{
			DoorDef doorDef = FindDoorType(doorConnection.m_type);
			if (doorDef == null)
			{
				ZLog.Log("No door type for connection:" + doorConnection.m_type);
			}
			else if ((!(doorDef.m_chance > 0f) || !(UnityEngine.Random.value > doorDef.m_chance)) && (!(doorDef.m_chance <= 0f) || !(UnityEngine.Random.value > m_doorChance)))
			{
				GameObject obj = UnityEngine.Object.Instantiate(doorDef.m_prefab, doorConnection.transform.position, doorConnection.transform.rotation);
				if (mode == ZoneSystem.SpawnMode.Ghost)
				{
					UnityEngine.Object.Destroy(obj);
				}
				num++;
			}
		}
		ZLog.Log("placed " + num + " doors");
	}

	private void PlaceEndCaps(ZoneSystem.SpawnMode mode)
	{
		for (int i = 0; i < m_openConnections.Count; i++)
		{
			RoomConnection roomConnection = m_openConnections[i];
			RoomConnection roomConnection2 = null;
			for (int j = 0; j < m_openConnections.Count; j++)
			{
				if (j != i && roomConnection.TestContact(m_openConnections[j]))
				{
					roomConnection2 = m_openConnections[j];
					break;
				}
			}
			if (roomConnection2 != null)
			{
				if (roomConnection.m_type != roomConnection2.m_type)
				{
					FindDividers(m_tempRooms);
					if (m_tempRooms.Count > 0)
					{
						DungeonDB.RoomData weightedRoom = GetWeightedRoom(m_tempRooms);
						RoomConnection[] connections = weightedRoom.RoomInPrefab.GetConnections();
						CalculateRoomPosRot(connections[0], roomConnection.transform.position, roomConnection.transform.rotation, out var pos, out var rot);
						bool flag = false;
						foreach (Room placedRoom in m_placedRooms)
						{
							if (placedRoom.m_divider && Vector3.Distance(placedRoom.transform.position, pos) < 0.5f)
							{
								flag = true;
								break;
							}
						}
						if (!flag)
						{
							PlaceRoom(weightedRoom, pos, rot, roomConnection, mode);
							ZLog.Log("Cyclic detected. Door missmatch for cyclic room '" + roomConnection.m_type + "'-'" + roomConnection2.m_type + "', placing divider: " + weightedRoom.m_prefab.Name);
						}
					}
					else
					{
						ZLog.LogWarning("Cyclic detected. Door missmatch for cyclic room '" + roomConnection.m_type + "'-'" + roomConnection2.m_type + "', but no dividers defined!");
					}
				}
				else
				{
					ZLog.Log("cyclic detected and door types match, cool");
				}
				continue;
			}
			FindEndCaps(roomConnection, m_tempRooms);
			bool flag2 = false;
			if (m_alternativeFunctionality)
			{
				for (int k = 0; k < 5; k++)
				{
					DungeonDB.RoomData weightedRoom2 = GetWeightedRoom(m_tempRooms);
					if (PlaceRoom(roomConnection, weightedRoom2, mode))
					{
						flag2 = true;
						break;
					}
				}
			}
			IOrderedEnumerable<DungeonDB.RoomData> orderedEnumerable = m_tempRooms.OrderByDescending((DungeonDB.RoomData item) => item.RoomInPrefab.m_endCapPrio);
			if (!flag2)
			{
				foreach (DungeonDB.RoomData item in orderedEnumerable)
				{
					if (PlaceRoom(roomConnection, item, mode))
					{
						flag2 = true;
						break;
					}
				}
			}
			if (!flag2)
			{
				ZLog.LogWarning("Failed to place end cap " + roomConnection.name + " " + roomConnection.transform.parent.gameObject.name);
			}
		}
	}

	private void FindDividers(List<DungeonDB.RoomData> rooms)
	{
		rooms.Clear();
		foreach (DungeonDB.RoomData availableRoom in m_availableRooms)
		{
			if (availableRoom.RoomInPrefab.m_divider)
			{
				rooms.Add(availableRoom);
			}
		}
		rooms.Shuffle(useUnityRandom: true);
	}

	private void FindEndCaps(RoomConnection connection, List<DungeonDB.RoomData> rooms)
	{
		rooms.Clear();
		foreach (DungeonDB.RoomData availableRoom in m_availableRooms)
		{
			if (availableRoom.RoomInPrefab.m_endCap && availableRoom.RoomInPrefab.HaveConnection(connection))
			{
				rooms.Add(availableRoom);
			}
		}
		rooms.Shuffle(useUnityRandom: true);
	}

	private DungeonDB.RoomData FindEndCap(RoomConnection connection)
	{
		m_tempRooms.Clear();
		foreach (DungeonDB.RoomData availableRoom in m_availableRooms)
		{
			if (availableRoom.RoomInPrefab.m_endCap && availableRoom.RoomInPrefab.HaveConnection(connection))
			{
				m_tempRooms.Add(availableRoom);
			}
		}
		if (m_tempRooms.Count == 0)
		{
			return null;
		}
		return m_tempRooms[UnityEngine.Random.Range(0, m_tempRooms.Count)];
	}

	private void PlaceRooms(ZoneSystem.SpawnMode mode)
	{
		for (int i = 0; i < m_maxRooms; i++)
		{
			PlaceOneRoom(mode);
			if (CheckRequiredRooms() && m_placedRooms.Count > m_minRooms)
			{
				ZLog.Log("All required rooms have been placed, stopping generation");
				break;
			}
		}
	}

	private void PlaceStartRoom(ZoneSystem.SpawnMode mode)
	{
		DungeonDB.RoomData roomData = FindStartRoom();
		RoomConnection entrance = roomData.RoomInPrefab.GetEntrance();
		Quaternion rotation = base.transform.rotation;
		CalculateRoomPosRot(entrance, base.transform.position, rotation, out var pos, out var rot);
		PlaceRoom(roomData, pos, rot, entrance, mode);
	}

	private bool PlaceOneRoom(ZoneSystem.SpawnMode mode)
	{
		RoomConnection openConnection = GetOpenConnection();
		if (openConnection == null)
		{
			return false;
		}
		for (int i = 0; i < 10; i++)
		{
			DungeonDB.RoomData roomData = (m_alternativeFunctionality ? GetRandomWeightedRoom(openConnection) : GetRandomRoom(openConnection));
			if (roomData == null)
			{
				break;
			}
			if (PlaceRoom(openConnection, roomData, mode))
			{
				return true;
			}
		}
		return false;
	}

	private void CalculateRoomPosRot(RoomConnection roomCon, Vector3 exitPos, Quaternion exitRot, out Vector3 pos, out Quaternion rot)
	{
		Quaternion quaternion = Quaternion.Inverse(roomCon.transform.localRotation);
		rot = exitRot * quaternion;
		Vector3 localPosition = roomCon.transform.localPosition;
		pos = exitPos - rot * localPosition;
	}

	private bool PlaceRoom(RoomConnection connection, DungeonDB.RoomData roomData, ZoneSystem.SpawnMode mode)
	{
		SoftReference<GameObject> prefab = roomData.m_prefab;
		prefab.Load();
		Room component = prefab.Asset.GetComponent<Room>();
		Quaternion rotation = connection.transform.rotation;
		rotation *= Quaternion.Euler(0f, 180f, 0f);
		RoomConnection connection2 = component.GetConnection(connection);
		if (connection2.transform.parent.gameObject != component.gameObject)
		{
			ZLog.LogWarning("Connection '" + component.name + "->" + connection2.name + "' is not placed as a direct child of room!");
		}
		CalculateRoomPosRot(connection2, connection.transform.position, rotation, out var pos, out var rot);
		if (component.m_size.x != 0 && component.m_size.z != 0 && TestCollision(component, pos, rot))
		{
			prefab.Release();
			return false;
		}
		PlaceRoom(roomData, pos, rot, connection, mode);
		if (!component.m_endCap)
		{
			if (connection.m_allowDoor && (!connection.m_doorOnlyIfOtherAlsoAllowsDoor || connection2.m_allowDoor))
			{
				m_doorConnections.Add(connection);
			}
			m_openConnections.Remove(connection);
		}
		prefab.Release();
		return true;
	}

	private Room PlaceRoom(DungeonDB.RoomData roomData, Vector3 pos, Quaternion rot, RoomConnection fromConnection, ZoneSystem.SpawnMode mode)
	{
		roomData.m_prefab.Load();
		Room component = roomData.m_prefab.Asset.GetComponent<Room>();
		ZNetView[] enabledComponentsInChildren = Utils.GetEnabledComponentsInChildren<ZNetView>(roomData.m_prefab.Asset);
		RandomSpawn[] enabledComponentsInChildren2 = Utils.GetEnabledComponentsInChildren<RandomSpawn>(roomData.m_prefab.Asset);
		for (int i = 0; i < enabledComponentsInChildren2.Length; i++)
		{
			enabledComponentsInChildren2[i].Prepare();
		}
		Vector3 vector = pos;
		if (m_useCustomInteriorTransform)
		{
			vector = pos - base.transform.position;
		}
		int seed = (int)vector.x * 4271 + (int)vector.y * 9187 + (int)vector.z * 2134;
		UnityEngine.Random.State state = UnityEngine.Random.state;
		UnityEngine.Random.InitState(seed);
		Vector3 position = component.transform.position;
		Quaternion quaternion = Quaternion.Inverse(component.transform.rotation);
		RandomSpawn[] array;
		ZNetView[] array2;
		if (mode == ZoneSystem.SpawnMode.Full || mode == ZoneSystem.SpawnMode.Ghost)
		{
			UnityEngine.Random.InitState(seed);
			array = enabledComponentsInChildren2;
			foreach (RandomSpawn randomSpawn in array)
			{
				Vector3 vector2 = quaternion * (randomSpawn.gameObject.transform.position - position);
				Vector3 pos2 = pos + rot * vector2;
				randomSpawn.Randomize(pos2, null, this);
			}
			array2 = enabledComponentsInChildren;
			foreach (ZNetView zNetView in array2)
			{
				if (zNetView.gameObject.activeSelf)
				{
					Vector3 vector3 = quaternion * (zNetView.gameObject.transform.position - position);
					Vector3 position2 = pos + rot * vector3;
					Quaternion quaternion2 = quaternion * zNetView.gameObject.transform.rotation;
					Quaternion rotation = rot * quaternion2;
					GameObject gameObject = UnityEngine.Object.Instantiate(zNetView.gameObject, position2, rotation);
					gameObject.HoldReferenceTo(roomData.m_prefab);
					if (mode == ZoneSystem.SpawnMode.Ghost)
					{
						UnityEngine.Object.Destroy(gameObject);
					}
				}
			}
		}
		else
		{
			UnityEngine.Random.InitState(seed);
			array = enabledComponentsInChildren2;
			foreach (RandomSpawn randomSpawn2 in array)
			{
				Vector3 vector4 = quaternion * (randomSpawn2.gameObject.transform.position - position);
				Vector3 pos3 = pos + rot * vector4;
				randomSpawn2.Randomize(pos3, null, this);
			}
		}
		array2 = enabledComponentsInChildren;
		for (int j = 0; j < array2.Length; j++)
		{
			array2[j].gameObject.SetActive(value: false);
		}
		Room component2 = SoftReferenceableAssets.Utils.Instantiate(roomData.m_prefab, pos, rot, base.transform).GetComponent<Room>();
		component2.gameObject.name = roomData.m_prefab.Name;
		if (mode != ZoneSystem.SpawnMode.Client)
		{
			component2.m_placeOrder = (fromConnection ? (fromConnection.m_placeOrder + 1) : 0);
			component2.m_seed = seed;
			m_placedRooms.Add(component2);
			AddOpenConnections(component2, fromConnection);
		}
		UnityEngine.Random.state = state;
		array = enabledComponentsInChildren2;
		for (int j = 0; j < array.Length; j++)
		{
			array[j].Reset();
		}
		array2 = enabledComponentsInChildren;
		for (int j = 0; j < array2.Length; j++)
		{
			array2[j].gameObject.SetActive(value: true);
		}
		roomData.m_prefab.Release();
		return component2;
	}

	private void AddOpenConnections(Room newRoom, RoomConnection skipConnection)
	{
		RoomConnection[] connections = newRoom.GetConnections();
		if (skipConnection != null)
		{
			RoomConnection[] array = connections;
			foreach (RoomConnection roomConnection in array)
			{
				if (!roomConnection.m_entrance && !(Vector3.Distance(roomConnection.transform.position, skipConnection.transform.position) < 0.1f))
				{
					roomConnection.m_placeOrder = newRoom.m_placeOrder;
					m_openConnections.Add(roomConnection);
				}
			}
		}
		else
		{
			RoomConnection[] array = connections;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].m_placeOrder = newRoom.m_placeOrder;
			}
			m_openConnections.AddRange(connections);
		}
	}

	private void SetupColliders()
	{
		if (!(m_colliderA != null))
		{
			BoxCollider[] componentsInChildren = base.gameObject.GetComponentsInChildren<BoxCollider>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				UnityEngine.Object.DestroyImmediate(componentsInChildren[i]);
			}
			m_colliderA = base.gameObject.AddComponent<BoxCollider>();
			m_colliderB = base.gameObject.AddComponent<BoxCollider>();
		}
	}

	public void Derp()
	{
	}

	private bool IsInsideDungeon(Room room, Vector3 pos, Quaternion rot)
	{
		Bounds bounds = new Bounds(m_zoneCenter, m_zoneSize);
		Vector3 vector = room.m_size;
		vector *= 0.5f;
		if (!bounds.Contains(pos + rot * new Vector3(vector.x, vector.y, 0f - vector.z)))
		{
			return false;
		}
		if (!bounds.Contains(pos + rot * new Vector3(0f - vector.x, vector.y, 0f - vector.z)))
		{
			return false;
		}
		if (!bounds.Contains(pos + rot * new Vector3(vector.x, vector.y, vector.z)))
		{
			return false;
		}
		if (!bounds.Contains(pos + rot * new Vector3(0f - vector.x, vector.y, vector.z)))
		{
			return false;
		}
		if (!bounds.Contains(pos + rot * new Vector3(vector.x, 0f - vector.y, 0f - vector.z)))
		{
			return false;
		}
		if (!bounds.Contains(pos + rot * new Vector3(0f - vector.x, 0f - vector.y, 0f - vector.z)))
		{
			return false;
		}
		if (!bounds.Contains(pos + rot * new Vector3(vector.x, 0f - vector.y, vector.z)))
		{
			return false;
		}
		if (!bounds.Contains(pos + rot * new Vector3(0f - vector.x, 0f - vector.y, vector.z)))
		{
			return false;
		}
		return true;
	}

	private bool TestCollision(Room room, Vector3 pos, Quaternion rot)
	{
		if (!IsInsideDungeon(room, pos, rot))
		{
			return true;
		}
		m_colliderA.size = new Vector3((float)room.m_size.x - 0.1f, (float)room.m_size.y - 0.1f, (float)room.m_size.z - 0.1f);
		foreach (Room placedRoom in m_placedRooms)
		{
			m_colliderB.size = placedRoom.m_size;
			if (Physics.ComputePenetration(m_colliderA, pos, rot, m_colliderB, placedRoom.transform.position, placedRoom.transform.rotation, out var _, out var _))
			{
				return true;
			}
		}
		return false;
	}

	private DungeonDB.RoomData GetRandomWeightedRoom(bool perimeterRoom)
	{
		m_tempRooms.Clear();
		float num = 0f;
		foreach (DungeonDB.RoomData availableRoom in m_availableRooms)
		{
			if (!availableRoom.RoomInPrefab.m_entrance && !availableRoom.RoomInPrefab.m_endCap && !availableRoom.RoomInPrefab.m_divider && availableRoom.RoomInPrefab.m_perimeter == perimeterRoom)
			{
				num += availableRoom.RoomInPrefab.m_weight;
				m_tempRooms.Add(availableRoom);
			}
		}
		if (m_tempRooms.Count == 0)
		{
			return null;
		}
		float num2 = UnityEngine.Random.Range(0f, num);
		float num3 = 0f;
		foreach (DungeonDB.RoomData tempRoom in m_tempRooms)
		{
			num3 += tempRoom.RoomInPrefab.m_weight;
			if (num2 <= num3)
			{
				return tempRoom;
			}
		}
		return m_tempRooms[0];
	}

	private DungeonDB.RoomData GetRandomWeightedRoom(RoomConnection connection)
	{
		m_tempRooms.Clear();
		foreach (DungeonDB.RoomData availableRoom in m_availableRooms)
		{
			if (!availableRoom.RoomInPrefab.m_entrance && !availableRoom.RoomInPrefab.m_endCap && !availableRoom.RoomInPrefab.m_divider && (!connection || (availableRoom.RoomInPrefab.HaveConnection(connection) && connection.m_placeOrder >= availableRoom.RoomInPrefab.m_minPlaceOrder)))
			{
				m_tempRooms.Add(availableRoom);
			}
		}
		if (m_tempRooms.Count == 0)
		{
			return null;
		}
		return GetWeightedRoom(m_tempRooms);
	}

	private DungeonDB.RoomData GetWeightedRoom(List<DungeonDB.RoomData> rooms)
	{
		float num = 0f;
		foreach (DungeonDB.RoomData room in rooms)
		{
			num += room.RoomInPrefab.m_weight;
		}
		float num2 = UnityEngine.Random.Range(0f, num);
		float num3 = 0f;
		foreach (DungeonDB.RoomData room2 in rooms)
		{
			num3 += room2.RoomInPrefab.m_weight;
			if (num2 <= num3)
			{
				return room2;
			}
		}
		return m_tempRooms[0];
	}

	private DungeonDB.RoomData GetRandomRoom(RoomConnection connection)
	{
		m_tempRooms.Clear();
		foreach (DungeonDB.RoomData availableRoom in m_availableRooms)
		{
			if (!availableRoom.RoomInPrefab.m_entrance && !availableRoom.RoomInPrefab.m_endCap && !availableRoom.RoomInPrefab.m_divider && (!connection || (availableRoom.RoomInPrefab.HaveConnection(connection) && connection.m_placeOrder >= availableRoom.RoomInPrefab.m_minPlaceOrder)))
			{
				m_tempRooms.Add(availableRoom);
			}
		}
		if (m_tempRooms.Count == 0)
		{
			return null;
		}
		return m_tempRooms[UnityEngine.Random.Range(0, m_tempRooms.Count)];
	}

	private RoomConnection GetOpenConnection()
	{
		if (m_openConnections.Count == 0)
		{
			return null;
		}
		return m_openConnections[UnityEngine.Random.Range(0, m_openConnections.Count)];
	}

	private DungeonDB.RoomData FindStartRoom()
	{
		m_tempRooms.Clear();
		foreach (DungeonDB.RoomData availableRoom in m_availableRooms)
		{
			if (availableRoom.RoomInPrefab.m_entrance)
			{
				m_tempRooms.Add(availableRoom);
			}
		}
		return m_tempRooms[UnityEngine.Random.Range(0, m_tempRooms.Count)];
	}

	private bool CheckRequiredRooms()
	{
		if (m_minRequiredRooms == 0 || m_requiredRooms.Count == 0)
		{
			return false;
		}
		int num = 0;
		foreach (Room placedRoom in m_placedRooms)
		{
			if (m_requiredRooms.Contains(placedRoom.gameObject.name))
			{
				num++;
			}
		}
		return num >= m_minRequiredRooms;
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = new Color(0f, 1.5f, 0f, 0.5f);
		Gizmos.DrawWireCube(m_zoneCenter, new Vector3(m_zoneSize.x, m_zoneSize.y, m_zoneSize.z));
		Gizmos.matrix = Matrix4x4.identity;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class EffectArea : MonoBehaviour, IMonoUpdater
{
	[Flags]
	public enum Type : byte
	{
		None = 0,
		Heat = 1,
		Fire = 2,
		PlayerBase = 4,
		Burning = 8,
		Teleport = 0x10,
		NoMonsters = 0x20,
		WarmCozyArea = 0x40,
		PrivateProperty = 0x80
	}

	private KeyValuePair<Bounds, EffectArea> noMonsterArea;

	private KeyValuePair<Bounds, EffectArea> noMonsterCloseToArea;

	private KeyValuePair<Bounds, EffectArea> burnCloseToArea;

	[BitMask(typeof(Type))]
	public Type m_type;

	public string m_statusEffect = "";

	public bool m_playerOnly;

	private int m_statusEffectHash;

	private Collider m_collider;

	private int m_collisions;

	private List<Character> m_collidedWithCharacter = new List<Character>();

	private bool m_isHeatType;

	private static int s_characterMask = 0;

	private static readonly List<EffectArea> s_allAreas = new List<EffectArea>();

	private static readonly List<KeyValuePair<Bounds, EffectArea>> s_noMonsterAreas = new List<KeyValuePair<Bounds, EffectArea>>();

	private static readonly List<KeyValuePair<Bounds, EffectArea>> s_noMonsterCloseToAreas = new List<KeyValuePair<Bounds, EffectArea>>();

	private static readonly List<KeyValuePair<Bounds, EffectArea>> s_BurningAreas = new List<KeyValuePair<Bounds, EffectArea>>();

	private static Collider[] m_tempColliders = new Collider[128];

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		if (!string.IsNullOrEmpty(m_statusEffect))
		{
			m_statusEffectHash = m_statusEffect.GetStableHashCode();
		}
		if (s_characterMask == 0)
		{
			s_characterMask = LayerMask.GetMask("character_trigger");
		}
		m_collider = GetComponent<Collider>();
		m_collider.isTrigger = true;
		if ((m_type & Type.NoMonsters) != Type.None)
		{
			noMonsterArea = new KeyValuePair<Bounds, EffectArea>(m_collider.bounds, this);
			s_noMonsterAreas.Add(noMonsterArea);
			Bounds bounds = m_collider.bounds;
			bounds.Expand(new Vector3(15f, 15f, 15f));
			noMonsterCloseToArea = new KeyValuePair<Bounds, EffectArea>(bounds, this);
			s_noMonsterCloseToAreas.Add(noMonsterCloseToArea);
		}
		if ((m_type & Type.Burning) != Type.None)
		{
			Bounds bounds2 = m_collider.bounds;
			bounds2.Expand(new Vector3(0.25f, 0.25f, 0.25f));
			burnCloseToArea = new KeyValuePair<Bounds, EffectArea>(bounds2, this);
			s_BurningAreas.Add(burnCloseToArea);
		}
		m_isHeatType = m_type.HasFlag(Type.Heat);
		s_allAreas.Add(this);
	}

	private void OnDestroy()
	{
		s_allAreas.Remove(this);
		if (s_noMonsterAreas.Contains(noMonsterArea))
		{
			s_noMonsterAreas.Remove(noMonsterArea);
		}
		if (s_noMonsterCloseToAreas.Contains(noMonsterCloseToArea))
		{
			s_noMonsterCloseToAreas.Remove(noMonsterCloseToArea);
		}
		if (s_BurningAreas.Contains(burnCloseToArea))
		{
			s_BurningAreas.Remove(burnCloseToArea);
		}
	}

	protected virtual void OnEnable()
	{
		Instances.Add(this);
	}

	protected virtual void OnDisable()
	{
		Instances.Remove(this);
	}

	private void OnTriggerEnter(Collider other)
	{
		m_collisions++;
		if (m_isHeatType || m_statusEffectHash != 0)
		{
			Character component = other.GetComponent<Character>();
			if ((bool)component && component.IsOwner() && (!m_playerOnly || component.IsPlayer()) && !m_collidedWithCharacter.Contains(component))
			{
				m_collidedWithCharacter.Add(component);
			}
		}
	}

	private void OnTriggerExit(Collider other)
	{
		m_collisions--;
		Character component = other.GetComponent<Character>();
		if (component != null)
		{
			m_collidedWithCharacter.Remove(component);
		}
	}

	public void CustomFixedUpdate(float deltaTime)
	{
		if (m_collisions <= 0 || m_collidedWithCharacter.Count == 0 || ZNet.instance == null)
		{
			return;
		}
		foreach (Character item in m_collidedWithCharacter)
		{
			if (m_statusEffectHash != 0)
			{
				item.GetSEMan().AddStatusEffect(m_statusEffectHash, resetTime: true);
			}
			if (m_isHeatType)
			{
				item.OnNearFire(base.transform.position);
			}
		}
	}

	public float GetRadius()
	{
		Collider collider = m_collider;
		if (!(collider is SphereCollider { radius: var radius }))
		{
			if (!(collider is CapsuleCollider { radius: var radius2 }))
			{
				return m_collider.bounds.size.magnitude;
			}
			return radius2;
		}
		return radius;
	}

	public static EffectArea IsPointInsideNoMonsterArea(Vector3 p)
	{
		foreach (KeyValuePair<Bounds, EffectArea> s_noMonsterArea in s_noMonsterAreas)
		{
			if (s_noMonsterArea.Key.Contains(p))
			{
				return s_noMonsterArea.Value;
			}
		}
		return null;
	}

	public static EffectArea IsPointCloseToNoMonsterArea(Vector3 p)
	{
		foreach (KeyValuePair<Bounds, EffectArea> s_noMonsterCloseToArea in s_noMonsterCloseToAreas)
		{
			if (s_noMonsterCloseToArea.Key.Contains(p))
			{
				return s_noMonsterCloseToArea.Value;
			}
		}
		return null;
	}

	public static EffectArea IsPointInsideArea(Vector3 p, Type type, float radius = 0f)
	{
		if (type == Type.Burning && radius.Equals(0.25f))
		{
			return GetBurningAreaPointPlus025(p);
		}
		int num = Physics.OverlapSphereNonAlloc(p, radius, m_tempColliders, s_characterMask);
		for (int i = 0; i < num; i++)
		{
			EffectArea component = m_tempColliders[i].GetComponent<EffectArea>();
			if ((bool)component && (component.m_type & type) != Type.None)
			{
				return component;
			}
		}
		return null;
	}

	public static bool IsPointPlus025InsideBurningArea(Vector3 p)
	{
		foreach (KeyValuePair<Bounds, EffectArea> s_BurningArea in s_BurningAreas)
		{
			if (s_BurningArea.Key.Contains(p))
			{
				return true;
			}
		}
		return false;
	}

	private static EffectArea GetBurningAreaPointPlus025(Vector3 p)
	{
		foreach (KeyValuePair<Bounds, EffectArea> s_BurningArea in s_BurningAreas)
		{
			if (s_BurningArea.Key.Contains(p))
			{
				return s_BurningArea.Value;
			}
		}
		return null;
	}

	public static int GetBaseValue(Vector3 p, float radius)
	{
		int num = 0;
		int num2 = Physics.OverlapSphereNonAlloc(p, radius, m_tempColliders, s_characterMask);
		for (int i = 0; i < num2; i++)
		{
			EffectArea component = m_tempColliders[i].GetComponent<EffectArea>();
			if ((bool)component && (component.m_type & Type.PlayerBase) != Type.None)
			{
				num++;
			}
		}
		return num;
	}

	public static List<EffectArea> GetAllAreas()
	{
		return s_allAreas;
	}
}
using UnityEngine;

public class EffectFade : MonoBehaviour
{
	public float m_fadeDuration = 1f;

	private ParticleSystem[] m_particles;

	private Light m_light;

	private AudioSource m_audioSource;

	private float m_baseVolume;

	private float m_lightBaseIntensity;

	private bool m_active = true;

	private float m_intensity;

	private void Awake()
	{
		m_particles = base.gameObject.GetComponentsInChildren<ParticleSystem>();
		m_light = base.gameObject.GetComponentInChildren<Light>();
		m_audioSource = base.gameObject.GetComponentInChildren<AudioSource>();
		if ((bool)m_light)
		{
			m_lightBaseIntensity = m_light.intensity;
			m_light.intensity = 0f;
		}
		if ((bool)m_audioSource)
		{
			m_baseVolume = m_audioSource.volume;
			m_audioSource.volume = 0f;
		}
		SetActive(active: false);
	}

	private void Update()
	{
		m_intensity = Mathf.MoveTowards(m_intensity, m_active ? 1f : 0f, Time.deltaTime / m_fadeDuration);
		if ((bool)m_light)
		{
			m_light.intensity = m_intensity * m_lightBaseIntensity;
			m_light.enabled = m_light.intensity > 0f;
		}
		if ((bool)m_audioSource)
		{
			m_audioSource.volume = m_intensity * m_baseVolume;
		}
	}

	public void SetActive(bool active)
	{
		if (m_active != active)
		{
			m_active = active;
			ParticleSystem[] particles = m_particles;
			for (int i = 0; i < particles.Length; i++)
			{
				ParticleSystem.EmissionModule emission = particles[i].emission;
				emission.enabled = active;
			}
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Animations;

[Serializable]
public class EffectList
{
	[Serializable]
	public class EffectData
	{
		public GameObject m_prefab;

		public bool m_enabled = true;

		public int m_variant = -1;

		public bool m_attach;

		public bool m_follow;

		public bool m_inheritParentRotation;

		public bool m_inheritParentScale;

		public bool m_multiplyParentVisualScale;

		public bool m_randomRotation;

		public bool m_scale;

		public string m_childTransform;
	}

	public EffectData[] m_effectPrefabs = new EffectData[0];

	public GameObject[] Create(Vector3 basePos, Quaternion baseRot, Transform baseParent = null, float scale = 1f, int variant = -1)
	{
		List<GameObject> list = new List<GameObject>();
		for (int i = 0; i < m_effectPrefabs.Length; i++)
		{
			EffectData effectData = m_effectPrefabs[i];
			if (!effectData.m_enabled || (variant >= 0 && effectData.m_variant >= 0 && variant != effectData.m_variant))
			{
				continue;
			}
			Transform transform = baseParent;
			Vector3 position = basePos;
			Quaternion rotation = baseRot;
			if (!string.IsNullOrEmpty(effectData.m_childTransform) && baseParent != null)
			{
				Transform transform2 = Utils.FindChild(transform, effectData.m_childTransform);
				if ((bool)transform2)
				{
					transform = transform2;
					position = transform.position;
				}
			}
			if ((bool)transform && effectData.m_inheritParentRotation)
			{
				rotation = transform.rotation;
			}
			if (effectData.m_randomRotation)
			{
				rotation = UnityEngine.Random.rotation;
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(effectData.m_prefab, position, rotation);
			if (effectData.m_scale)
			{
				if ((bool)baseParent && effectData.m_inheritParentScale)
				{
					Vector3 localScale = baseParent.localScale * scale;
					gameObject.transform.localScale = localScale;
				}
				else
				{
					gameObject.transform.localScale = new Vector3(scale, scale, scale);
				}
			}
			else if ((bool)baseParent)
			{
				if (effectData.m_multiplyParentVisualScale)
				{
					Transform transform3 = baseParent.Find("Visual");
					if ((object)transform3 != null)
					{
						gameObject.transform.localScale = Vector3.Scale(gameObject.transform.localScale, transform3.localScale);
						goto IL_0166;
					}
				}
				if (effectData.m_inheritParentScale)
				{
					gameObject.transform.localScale = baseParent.localScale;
				}
			}
			goto IL_0166;
			IL_0166:
			if (effectData.m_attach && transform != null)
			{
				gameObject.transform.SetParent(transform);
			}
			if (effectData.m_follow)
			{
				ParentConstraint parentConstraint = gameObject.AddComponent<ParentConstraint>();
				ConstraintSource source = new ConstraintSource
				{
					sourceTransform = transform,
					weight = 1f
				};
				parentConstraint.AddSource(source);
				parentConstraint.locked = true;
				parentConstraint.SetTranslationOffset(0, effectData.m_prefab.transform.position);
				parentConstraint.SetRotationOffset(0, effectData.m_prefab.transform.rotation.eulerAngles);
				parentConstraint.constraintActive = true;
			}
			list.Add(gameObject);
		}
		return list.ToArray();
	}

	public bool HasEffects()
	{
		if (m_effectPrefabs == null || m_effectPrefabs.Length == 0)
		{
			return false;
		}
		EffectData[] effectPrefabs = m_effectPrefabs;
		for (int i = 0; i < effectPrefabs.Length; i++)
		{
			if (effectPrefabs[i].m_enabled)
			{
				return true;
			}
		}
		return false;
	}
}
using UnityEngine;

public class EggGrow : MonoBehaviour, Hoverable
{
	public float m_growTime = 60f;

	public GameObject m_grownPrefab;

	public bool m_tamed;

	public float m_updateInterval = 5f;

	public bool m_requireNearbyFire = true;

	public bool m_requireUnderRoof = true;

	public float m_requireCoverPercentige = 0.7f;

	public EffectList m_hatchEffect;

	public GameObject m_growingObject;

	public GameObject m_notGrowingObject;

	private ZNetView m_nview;

	private ItemDrop m_item;

	private void Start()
	{
		m_nview = GetComponent<ZNetView>();
		m_item = GetComponent<ItemDrop>();
		InvokeRepeating("GrowUpdate", Random.Range(m_updateInterval, m_updateInterval * 2f), m_updateInterval);
		if ((bool)m_growingObject)
		{
			m_growingObject.SetActive(value: false);
		}
		if ((bool)m_notGrowingObject)
		{
			m_notGrowingObject.SetActive(value: true);
		}
	}

	private void GrowUpdate()
	{
		float num = m_nview.GetZDO().GetFloat(ZDOVars.s_growStart);
		if (!m_nview.IsValid() || !m_nview.IsOwner() || m_item.m_itemData.m_stack > 1)
		{
			UpdateEffects(num);
			return;
		}
		if (CanGrow())
		{
			if (num == 0f)
			{
				num = (float)ZNet.instance.GetTimeSeconds();
			}
		}
		else
		{
			num = 0f;
		}
		m_nview.GetZDO().Set(ZDOVars.s_growStart, num);
		UpdateEffects(num);
		if (num > 0f && ZNet.instance.GetTimeSeconds() > (double)(num + m_growTime))
		{
			Character component = Object.Instantiate(m_grownPrefab, base.transform.position, base.transform.rotation).GetComponent<Character>();
			m_hatchEffect.Create(base.transform.position, base.transform.rotation);
			if ((bool)component)
			{
				component.SetTamed(m_tamed);
				component.SetLevel(m_item.m_itemData.m_quality);
			}
			m_nview.Destroy();
		}
	}

	private bool CanGrow()
	{
		if (m_item.m_itemData.m_stack > 1)
		{
			return false;
		}
		if (m_requireNearbyFire && !EffectArea.IsPointInsideArea(base.transform.position, EffectArea.Type.Heat, 0.5f))
		{
			return false;
		}
		if (m_requireUnderRoof)
		{
			Cover.GetCoverForPoint(base.transform.position, out var coverPercentage, out var underRoof, 0.1f);
			if (!underRoof || coverPercentage < m_requireCoverPercentige)
			{
				return false;
			}
		}
		return true;
	}

	private void UpdateEffects(float grow)
	{
		if ((bool)m_growingObject)
		{
			m_growingObject.SetActive(grow > 0f);
		}
		if ((bool)m_notGrowingObject)
		{
			m_notGrowingObject.SetActive(grow == 0f);
		}
	}

	public string GetHoverText()
	{
		if (!m_item)
		{
			return "";
		}
		if (!m_nview || !m_nview.IsValid())
		{
			return m_item.GetHoverText();
		}
		bool flag = m_nview.GetZDO().GetFloat(ZDOVars.s_growStart) > 0f;
		string text = ((m_item.m_itemData.m_stack > 1) ? "$item_chicken_egg_stacked" : (flag ? "$item_chicken_egg_warm" : "$item_chicken_egg_cold"));
		string hoverText = m_item.GetHoverText();
		int num = hoverText.IndexOf('\n');
		if (num > 0)
		{
			return hoverText.Substring(0, num) + " " + Localization.instance.Localize(text) + hoverText.Substring(num);
		}
		return m_item.GetHoverText();
	}

	public string GetHoverName()
	{
		return m_item.GetHoverName();
	}
}
using UnityEngine;

public class EggHatch : MonoBehaviour
{
	public float m_triggerDistance = 5f;

	[Range(0f, 1f)]
	public float m_chanceToHatch = 1f;

	public Vector3 m_spawnOffset = new Vector3(0f, 0.5f, 0f);

	public GameObject m_spawnPrefab;

	public EffectList m_hatchEffect;

	private ZNetView m_nview;

	private void Start()
	{
		m_nview = GetComponent<ZNetView>();
		if (Random.value <= m_chanceToHatch)
		{
			InvokeRepeating("CheckSpawn", Random.Range(1f, 2f), 1f);
		}
	}

	private void CheckSpawn()
	{
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			Player closestPlayer = Player.GetClosestPlayer(base.transform.position, m_triggerDistance);
			if ((bool)closestPlayer && !closestPlayer.InGhostMode())
			{
				Hatch();
			}
		}
	}

	private void Hatch()
	{
		m_hatchEffect.Create(base.transform.position, base.transform.rotation);
		Object.Instantiate(m_spawnPrefab, base.transform.TransformPoint(m_spawnOffset), Quaternion.Euler(0f, Random.Range(0, 360), 0f));
		m_nview.Destroy();
	}
}
using UnityEngine;

public class EmitterRotation : MonoBehaviour
{
	public float m_maxSpeed = 10f;

	public float m_rotSpeed = 90f;

	private Vector3 m_lastPos;

	private ParticleSystem m_ps;

	private void Start()
	{
		m_lastPos = base.transform.position;
		m_ps = GetComponentInChildren<ParticleSystem>();
	}

	private void Update()
	{
		if (m_ps.emission.enabled)
		{
			Vector3 position = base.transform.position;
			Vector3 vector = position - m_lastPos;
			m_lastPos = position;
			float t = Mathf.Clamp01(vector.magnitude / Time.deltaTime / m_maxSpeed);
			if (vector == Vector3.zero)
			{
				vector = Vector3.up;
			}
			Quaternion a = Quaternion.LookRotation(Vector3.up);
			Quaternion b = Quaternion.LookRotation(vector);
			Quaternion to = Quaternion.Lerp(a, b, t);
			base.transform.rotation = Quaternion.RotateTowards(base.transform.rotation, to, Time.deltaTime * m_rotSpeed);
		}
	}
}
