using System.Collections.Generic;
using UnityEngine;

public class Fire : MonoBehaviour
{
	public static List<Fire> s_fires = new List<Fire>();

	private static Collider[] m_colliders = new Collider[128];

	private static List<KeyValuePair<IDestructible, Collider>> m_destructibles = new List<KeyValuePair<IDestructible, Collider>>();

	public float m_dotInterval = 1f;

	public float m_dotRadius = 1f;

	public float m_fireDamage = 10f;

	public float m_chopDamage = 10f;

	public short m_toolTier = 2;

	public int m_spread = 4;

	public float m_updateRate = 2f;

	[Header("Terrain hit")]
	public float m_terrainHitDelay;

	public float m_terrainMaxDist;

	public bool m_terrainCheckCultivated;

	public bool m_terrainCheckCleared;

	public GameObject m_terrainHitSpawn;

	public Heightmap.Biome m_terrainHitBiomes = Heightmap.Biome.All;

	[Header("Burn fuel from fireplaces")]
	public float m_fuelBurnChance = 0.5f;

	public float m_fuelBurnAmount = 0.1f;

	[Header("Smoke")]
	public SmokeSpawner m_smokeSpawner;

	public float m_smokeCheckHeight = 0.25f;

	public float m_smokeCheckRadius = 0.5f;

	public float m_smokeOxygenCheckHeight = 1.25f;

	public float m_smokeOxygenCheckRadius = 1.5f;

	public float m_smokeSuffocationPerHit = 0.2f;

	public int m_oxygenSmokeTolerance = 2;

	public int m_oxygenInteriorChecks = 5;

	public float m_smokeDieChance = 0.5f;

	public float m_maxSmoke = 3f;

	[Header("Effects")]
	public EffectList m_hitEffect;

	private static int s_dotMask = 0;

	private static int s_solidMask = 0;

	private static int s_terrainMask = 0;

	private static int s_smokeRayMask = 0;

	private static readonly RaycastHit[] s_raycastHits = new RaycastHit[32];

	private static readonly Collider[] s_hits = new Collider[32];

	private int m_smokeHits;

	private bool m_inSmoke;

	private GameObject m_roof;

	private ZNetView m_nview;

	private float m_suffocating;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		if (s_dotMask == 0)
		{
			s_dotMask = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece", "piece_nonsolid", "character", "character_net", "character_ghost", "hitbox", "character_noenv", "vehicle");
			s_solidMask = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece");
			s_terrainMask = LayerMask.GetMask("terrain");
			s_smokeRayMask = LayerMask.GetMask("smoke");
		}
		InvokeRepeating("Dot", m_dotInterval, m_dotInterval);
		if ((bool)m_terrainHitSpawn && (m_terrainHitBiomes == Heightmap.Biome.All || m_terrainHitBiomes.HasFlag(WorldGenerator.instance.GetBiome(base.transform.position))))
		{
			Invoke("HitTerrain", m_terrainHitDelay);
		}
		InvokeRepeating("UpdateFire", Random.Range(m_updateRate / 2f, m_updateRate), m_updateRate);
		s_fires.Add(this);
	}

	private void OnDestroy()
	{
		s_fires.Remove(this);
	}

	private void Dot()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner())
		{
			return;
		}
		m_destructibles.Clear();
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, m_dotRadius, m_colliders, s_dotMask);
		for (int i = 0; i < num; i++)
		{
			GameObject gameObject = Projectile.FindHitObject(m_colliders[i]);
			IDestructible component = gameObject.GetComponent<IDestructible>();
			if (Random.Range(0f, 1f) < m_fuelBurnChance)
			{
				gameObject.GetComponent<Fireplace>()?.AddFuel(0f - m_fuelBurnAmount);
			}
			if ((bool)gameObject.GetComponent<Character>())
			{
				DoDamage(component, m_colliders[i]);
				continue;
			}
			WearNTear component2 = gameObject.GetComponent<WearNTear>();
			if (((object)component2 == null || component2.m_burnable) && component != null)
			{
				m_destructibles.Add(new KeyValuePair<IDestructible, Collider>(component, m_colliders[i]));
			}
		}
		if (m_destructibles.Count > 0)
		{
			KeyValuePair<IDestructible, Collider> keyValuePair = m_destructibles[Random.Range(0, m_destructibles.Count)];
			DoDamage(keyValuePair.Key, keyValuePair.Value);
		}
	}

	private void DoDamage(IDestructible toHit, Collider collider)
	{
		HitData hitData = new HitData();
		hitData.m_hitCollider = collider;
		hitData.m_damage.m_fire = m_fireDamage;
		hitData.m_damage.m_chop = m_chopDamage;
		hitData.m_toolTier = m_toolTier;
		hitData.m_point = (base.transform.position + collider.bounds.center) * 0.5f;
		hitData.m_dodgeable = false;
		hitData.m_blockable = false;
		hitData.m_hitType = HitData.HitType.CinderFire;
		m_hitEffect.Create(hitData.m_point, Quaternion.identity);
		toHit.Damage(hitData);
	}

	private void HitTerrain()
	{
		if (Physics.Raycast(base.transform.position, Vector3.down, out var hitInfo, m_terrainMaxDist, s_terrainMask))
		{
			Heightmap component = hitInfo.collider.GetComponent<Heightmap>();
			if ((object)component != null && !component.IsLava(hitInfo.point) && ((m_terrainCheckCultivated && !component.IsCultivated(hitInfo.point)) || (m_terrainCheckCleared && !component.IsCleared(hitInfo.point)) || (!m_terrainCheckCleared && !m_terrainCheckCultivated)))
			{
				Object.Instantiate(m_terrainHitSpawn, hitInfo.point, Quaternion.identity);
			}
		}
	}

	private void UpdateFire()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner())
		{
			return;
		}
		if (!m_roof)
		{
			WearNTear.RoofCheck(base.transform.position, out m_roof);
		}
		if (!m_roof && EnvMan.IsWet())
		{
			ZNetScene.instance.Destroy(base.gameObject);
		}
		if ((bool)m_roof)
		{
			m_smokeHits = Physics.OverlapSphereNonAlloc(base.transform.position + Vector3.up * m_smokeOxygenCheckHeight, m_smokeOxygenCheckRadius, s_hits, s_smokeRayMask);
			m_smokeHits -= m_oxygenSmokeTolerance;
			if (m_smokeHits > 0)
			{
				m_suffocating += (float)m_smokeHits * m_smokeSuffocationPerHit;
				Terminal.Log($"Fire suffocation in interior with {m_smokeHits} smoke hits");
			}
			else
			{
				m_suffocating = Mathf.Max(0f, m_suffocating - 1f);
			}
		}
		else
		{
			m_inSmoke = Physics.CheckSphere(base.transform.position + Vector3.up * m_smokeCheckHeight, m_smokeCheckRadius, s_smokeRayMask);
			if (m_inSmoke)
			{
				m_suffocating += 1f;
				Terminal.Log("Fire in direct smoke");
			}
			else
			{
				m_suffocating = Mathf.Max(0f, m_suffocating - 1f);
			}
		}
		if (m_suffocating >= m_maxSmoke && (m_smokeDieChance >= 1f || Random.Range(0f, 1f) < m_smokeDieChance))
		{
			Terminal.Log("Fire suffocated");
			ZNetScene.instance.Destroy(base.gameObject);
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Fireplace : MonoBehaviour, Hoverable, Interactable, IHasHoverMenu
{
	[Serializable]
	public struct FireworkItem
	{
		public ItemDrop m_fireworkItem;

		public int m_fireworkItemCount;

		public EffectList m_fireworksEffects;
	}

	private ZNetView m_nview;

	private Piece m_piece;

	[Header("Fire")]
	public string m_name = "Fire";

	public float m_startFuel = 3f;

	public float m_maxFuel = 10f;

	public float m_secPerFuel = 3f;

	public bool m_infiniteFuel;

	public bool m_disableCoverCheck;

	public float m_checkTerrainOffset = 0.2f;

	public float m_coverCheckOffset = 0.5f;

	private const float m_minimumOpenSpace = 0.5f;

	public float m_holdRepeatInterval = 0.2f;

	public float m_halfThreshold = 0.5f;

	public bool m_canTurnOff;

	public bool m_canRefill = true;

	public bool m_lowWetOverHalf = true;

	public GameObject m_enabledObject;

	public GameObject m_enabledObjectLow;

	public GameObject m_enabledObjectHigh;

	public GameObject m_fullObject;

	public GameObject m_halfObject;

	public GameObject m_emptyObject;

	public GameObject m_playerBaseObject;

	public ItemDrop m_fuelItem;

	public SmokeSpawner m_smokeSpawner;

	public EffectList m_fuelAddedEffects = new EffectList();

	public EffectList m_toggleOnEffects = new EffectList();

	[Header("Fireworks")]
	[Range(0f, 60f)]
	public float m_fireworksMaxRandomAngle = 5f;

	public FireworkItem[] m_fireworkItemList;

	[Header("Ignite Pieces")]
	public float m_igniteInterval;

	public float m_igniteChance;

	public int m_igniteSpread = 4;

	public float m_igniteCapsuleRadius;

	public Vector3 m_igniteCapsuleStart;

	public Vector3 m_igniteCapsuleEnd;

	public GameObject m_firePrefab;

	private bool m_blocked;

	private bool m_wet;

	private Heightmap.Biome m_biome;

	private float m_lastUseTime;

	private bool m_checkWaterLevel;

	private WaterVolume m_previousWaterVolume;

	private static int m_solidRayMask = 0;

	private static Collider[] s_tempColliders = new Collider[20];

	public void Awake()
	{
		m_nview = base.gameObject.GetComponent<ZNetView>();
		m_piece = base.gameObject.GetComponent<Piece>();
		if (m_nview.GetZDO() == null)
		{
			return;
		}
		if (m_solidRayMask == 0)
		{
			m_solidRayMask = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece", "terrain");
		}
		if (m_nview.IsOwner() && m_nview.GetZDO().GetFloat(ZDOVars.s_fuel, -1f) == -1f)
		{
			m_nview.GetZDO().Set(ZDOVars.s_fuel, m_startFuel);
			if (m_startFuel > 0f)
			{
				m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation);
			}
		}
		Vector3 p = (m_enabledObject ? m_enabledObject.transform.position : base.transform.position);
		p.y -= 15f;
		m_checkWaterLevel = Floating.IsUnderWater(p, ref m_previousWaterVolume);
		m_nview.Register("RPC_AddFuel", RPC_AddFuel);
		m_nview.Register<float>("RPC_AddFuelAmount", RPC_AddFuelAmount);
		m_nview.Register<float>("RPC_SetFuelAmount", RPC_SetFuelAmount);
		m_nview.Register("RPC_ToggleOn", RPC_ToggleOn);
		InvokeRepeating("UpdateFireplace", 0f, 2f);
		InvokeRepeating("CheckEnv", 4f, 4f);
		if (m_igniteInterval > 0f && m_igniteCapsuleRadius > 0f)
		{
			InvokeRepeating("UpdateIgnite", m_igniteInterval, m_igniteInterval);
		}
	}

	private void Start()
	{
		if ((bool)m_playerBaseObject && (bool)m_piece)
		{
			m_playerBaseObject.SetActive(m_piece.IsPlacedByPlayer());
		}
	}

	private double GetTimeSinceLastUpdate()
	{
		DateTime time = ZNet.instance.GetTime();
		DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_lastTime, time.Ticks));
		TimeSpan timeSpan = time - dateTime;
		m_nview.GetZDO().Set(ZDOVars.s_lastTime, time.Ticks);
		double num = timeSpan.TotalSeconds;
		if (num < 0.0)
		{
			num = 0.0;
		}
		return num;
	}

	private void UpdateFireplace()
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		if (m_nview.IsOwner() && m_secPerFuel > 0f)
		{
			float num = m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
			double timeSinceLastUpdate = GetTimeSinceLastUpdate();
			bool flag = m_nview.GetZDO().GetInt(ZDOVars.s_state, 1) == 1;
			if (IsBurning() && !m_infiniteFuel && flag)
			{
				float num2 = (float)(timeSinceLastUpdate / (double)m_secPerFuel);
				num -= num2;
				if (num <= 0f)
				{
					num = 0f;
				}
				m_nview.GetZDO().Set(ZDOVars.s_fuel, num);
			}
		}
		UpdateState();
	}

	private void CheckEnv()
	{
		CheckUnderTerrain();
		if (m_enabledObjectLow != null && m_enabledObjectHigh != null)
		{
			CheckWet();
		}
	}

	private void CheckUnderTerrain()
	{
		m_blocked = false;
		if (!m_disableCoverCheck)
		{
			RaycastHit hitInfo;
			if (Heightmap.GetHeight(base.transform.position, out var height) && height > base.transform.position.y + m_checkTerrainOffset)
			{
				m_blocked = true;
			}
			else if (Physics.Raycast(base.transform.position + Vector3.up * m_coverCheckOffset, Vector3.up, out hitInfo, 0.5f, m_solidRayMask))
			{
				m_blocked = true;
			}
			else if ((bool)m_smokeSpawner && m_smokeSpawner.IsBlocked())
			{
				m_blocked = true;
			}
		}
	}

	private void CheckWet()
	{
		m_wet = false;
		bool flag = EnvMan.instance.GetWindIntensity() >= 0.8f;
		bool flag2 = EnvMan.IsWet();
		if (flag || flag2)
		{
			Cover.GetCoverForPoint(base.transform.position + Vector3.up * m_coverCheckOffset, out var coverPercentage, out var underRoof);
			if (flag && coverPercentage < 0.7f)
			{
				m_wet = true;
			}
			else if (flag2 && !underRoof)
			{
				m_wet = true;
			}
		}
	}

	private void UpdateState()
	{
		float num = m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
		bool flag = num >= m_halfThreshold;
		bool flag2 = num <= 0f;
		if (m_lowWetOverHalf)
		{
			_ = !m_wet;
		}
		else
			_ = 0;
		if (IsBurning())
		{
			if ((bool)m_enabledObject)
			{
				m_enabledObject.SetActive(value: true);
			}
			if ((bool)m_enabledObjectHigh && (bool)m_enabledObjectLow)
			{
				if (m_enabledObjectHigh.activeSelf != !m_wet)
				{
					m_enabledObjectHigh.SetActive(!m_wet);
				}
				if (m_enabledObjectLow.activeSelf != m_wet)
				{
					m_enabledObjectLow.SetActive(m_wet);
				}
			}
			if (m_canTurnOff && m_wet && m_nview.IsOwner() && m_nview.GetZDO().GetInt(ZDOVars.s_state, 1) == 1)
			{
				m_nview.InvokeRPC("RPC_ToggleOn");
			}
		}
		else
		{
			if ((bool)m_enabledObject)
			{
				m_enabledObject.SetActive(value: false);
			}
			if ((bool)m_enabledObjectHigh && (bool)m_enabledObjectLow)
			{
				if (m_enabledObjectLow.activeSelf)
				{
					m_enabledObjectLow.SetActive(value: false);
				}
				if (m_enabledObjectHigh.activeSelf)
				{
					m_enabledObjectHigh.SetActive(value: false);
				}
			}
		}
		if ((bool)m_fullObject && (bool)m_halfObject)
		{
			m_fullObject.SetActive(flag);
			m_halfObject.SetActive(!flag);
		}
		if (!m_emptyObject)
		{
			return;
		}
		if (flag2)
		{
			if ((bool)m_fullObject && m_fullObject.activeSelf)
			{
				m_fullObject.SetActive(value: false);
			}
			if ((bool)m_halfObject && m_halfObject.activeSelf)
			{
				m_halfObject.SetActive(value: false);
			}
		}
		if (m_emptyObject.activeSelf != flag2)
		{
			m_emptyObject.SetActive(flag2);
		}
	}

	public string GetHoverText()
	{
		if (!m_nview.IsValid() || m_infiniteFuel)
		{
			return "";
		}
		float num = m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
		string text = m_name;
		if (m_canRefill)
		{
			text += $"\n( $piece_fire_fuel {Mathf.Ceil(num)}/{(int)m_maxFuel} )\n[<color=yellow><b>$KEY_Use</b></color>] $piece_use {m_fuelItem.m_itemData.m_shared.m_name}\n[<color=yellow><b>1-8</b></color>] $piece_useitem";
		}
		else if (m_canTurnOff && num > 0f)
		{
			text += "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_use";
		}
		return Localization.instance.Localize(text);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public void AddFuel(float fuel)
	{
		if ((bool)m_nview && m_nview.IsValid())
		{
			float num = m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
			if ((fuel < 0f && num > 0f) || (fuel > 0f && num < m_maxFuel))
			{
				m_nview.InvokeRPC("RPC_AddFuelAmount", fuel);
			}
		}
	}

	public bool Interact(Humanoid user, bool hold, bool alt)
	{
		if (hold)
		{
			if (m_holdRepeatInterval <= 0f)
			{
				return false;
			}
			if (Time.time - m_lastUseTime < m_holdRepeatInterval)
			{
				return false;
			}
		}
		if (!m_nview.HasOwner())
		{
			m_nview.ClaimOwnership();
		}
		float num = m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
		if (m_canTurnOff && !hold && !alt && num > 0f)
		{
			m_nview.InvokeRPC("RPC_ToggleOn");
			return true;
		}
		if (m_canRefill)
		{
			Inventory inventory = user.GetInventory();
			if (inventory != null)
			{
				if (m_infiniteFuel)
				{
					return false;
				}
				if (inventory.HaveItem(m_fuelItem.m_itemData.m_shared.m_name))
				{
					if ((float)Mathf.CeilToInt(num) >= m_maxFuel)
					{
						user.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_cantaddmore", m_fuelItem.m_itemData.m_shared.m_name));
						return false;
					}
					user.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_fireadding", m_fuelItem.m_itemData.m_shared.m_name));
					inventory.RemoveItem(m_fuelItem.m_itemData.m_shared.m_name, 1);
					m_nview.InvokeRPC("RPC_AddFuel");
					return true;
				}
				user.Message(MessageHud.MessageType.Center, "$msg_outof " + m_fuelItem.m_itemData.m_shared.m_name);
				return false;
			}
		}
		return false;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		if (!m_canRefill)
		{
			return false;
		}
		if (item.m_shared.m_name == m_fuelItem.m_itemData.m_shared.m_name && !m_infiniteFuel)
		{
			if ((float)Mathf.CeilToInt(m_nview.GetZDO().GetFloat(ZDOVars.s_fuel)) >= m_maxFuel)
			{
				user.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_cantaddmore", item.m_shared.m_name));
				return true;
			}
			Inventory inventory = user.GetInventory();
			user.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_fireadding", item.m_shared.m_name));
			inventory.RemoveItem(item, 1);
			m_nview.InvokeRPC("RPC_AddFuel");
			return true;
		}
		for (int i = 0; i < m_fireworkItemList.Length; i++)
		{
			if (item.m_shared.m_name == m_fireworkItemList[i].m_fireworkItem.m_itemData.m_shared.m_name)
			{
				if (!IsBurning())
				{
					user.Message(MessageHud.MessageType.Center, "$msg_firenotburning");
					return true;
				}
				if (user.GetInventory().CountItems(m_fireworkItemList[i].m_fireworkItem.m_itemData.m_shared.m_name) < m_fireworkItemList[i].m_fireworkItemCount)
				{
					user.Message(MessageHud.MessageType.Center, "$msg_toofew " + m_fireworkItemList[i].m_fireworkItem.m_itemData.m_shared.m_name);
					return true;
				}
				user.GetInventory().RemoveItem(item.m_shared.m_name, m_fireworkItemList[i].m_fireworkItemCount);
				user.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_throwinfire", item.m_shared.m_name));
				float x = UnityEngine.Random.Range(0f - m_fireworksMaxRandomAngle, m_fireworksMaxRandomAngle);
				float z = UnityEngine.Random.Range(0f - m_fireworksMaxRandomAngle, m_fireworksMaxRandomAngle);
				Quaternion baseRot = Quaternion.Euler(x, 0f, z);
				m_fireworkItemList[i].m_fireworksEffects.Create(base.transform.position, baseRot);
				m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation);
				return true;
			}
		}
		return false;
	}

	private void RPC_AddFuel(long sender)
	{
		if (m_nview.IsOwner())
		{
			float num = m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
			if (!((float)Mathf.CeilToInt(num) >= m_maxFuel))
			{
				num = Mathf.Clamp(num, 0f, m_maxFuel);
				num += 1f;
				num = Mathf.Clamp(num, 0f, m_maxFuel);
				m_nview.GetZDO().Set(ZDOVars.s_fuel, num);
				m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation);
				UpdateState();
			}
		}
	}

	private void RPC_ToggleOn(long sender)
	{
		if (m_nview.IsOwner())
		{
			bool flag = m_nview.GetZDO().GetInt(ZDOVars.s_state, 1) == 1;
			m_nview.GetZDO().Set(ZDOVars.s_state, (!flag) ? 1 : 2);
			m_toggleOnEffects.Create(base.transform.position, Quaternion.identity, null, 1f, (!flag) ? 1 : 2);
		}
		UpdateState();
	}

	private void RPC_AddFuelAmount(long sender, float amount)
	{
		if (m_nview.IsOwner())
		{
			float num = m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
			num = Mathf.Clamp(num + amount, 0f, m_maxFuel);
			m_nview.GetZDO().Set(ZDOVars.s_fuel, num);
			m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation);
			UpdateState();
		}
	}

	public void SetFuel(float fuel)
	{
		if ((bool)m_nview && m_nview.IsValid())
		{
			float num = m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
			fuel = Mathf.Clamp(fuel, 0f, m_maxFuel);
			if (fuel != num)
			{
				m_nview.InvokeRPC("RPC_SetFuelAmount", fuel);
			}
		}
	}

	private void RPC_SetFuelAmount(long sender, float fuel)
	{
		if (m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_fuel, fuel);
			m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation);
			UpdateState();
		}
	}

	public bool CanBeRemoved()
	{
		return !IsBurning();
	}

	public bool IsBurning()
	{
		if (m_blocked)
		{
			return false;
		}
		if (m_nview.GetZDO().GetInt(ZDOVars.s_state, 1) != 1)
		{
			return false;
		}
		if (m_checkWaterLevel && Floating.IsUnderWater(m_enabledObject ? m_enabledObject.transform.position : base.transform.position, ref m_previousWaterVolume))
		{
			return false;
		}
		if (!(m_nview.GetZDO().GetFloat(ZDOVars.s_fuel) > 0f))
		{
			return m_infiniteFuel;
		}
		return true;
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.white;
		Gizmos.DrawWireSphere(base.transform.position + Vector3.up * m_coverCheckOffset, 0.5f);
		Gizmos.color = Color.yellow;
		Gizmos.DrawWireCube(base.transform.position + Vector3.up * m_checkTerrainOffset, new Vector3(1f, 0.01f, 1f));
		Gizmos.color = Color.red;
		Utils.DrawGizmoCapsule(base.transform.position + m_igniteCapsuleStart, base.transform.position + m_igniteCapsuleEnd, m_igniteCapsuleRadius);
	}

	private void UpdateIgnite()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner() || !m_firePrefab || !CanIgnite() || !IsBurning())
		{
			return;
		}
		int num = Physics.OverlapCapsuleNonAlloc(base.transform.position + m_igniteCapsuleStart, base.transform.position + m_igniteCapsuleEnd, m_igniteCapsuleRadius, s_tempColliders);
		for (int i = 0; i < num; i++)
		{
			Collider collider = s_tempColliders[i];
			if (!(collider.gameObject == base.gameObject) && (!(collider.transform.parent != null) || !(collider.transform.parent.gameObject == base.gameObject)) && !collider.isTrigger && UnityEngine.Random.Range(0f, 1f) <= m_igniteChance && Cinder.CanBurn(collider, collider.transform.position, out var _))
			{
				UnityEngine.Object.Instantiate(m_firePrefab, collider.transform.position + Utils.RandomVector3(-0.1f, 0.1f), Quaternion.identity).GetComponent<CinderSpawner>()?.Setup(m_igniteSpread, collider.gameObject);
			}
		}
	}

	public bool TryGetItems(Player player, out List<string> items)
	{
		items = new List<string>();
		if (m_infiniteFuel)
		{
			return false;
		}
		if (!CanUseItems(player))
		{
			return true;
		}
		items.Add(m_fuelItem.m_itemData.m_shared.m_name);
		return true;
	}

	public bool CanUseItems(Player player, bool sendErrorMessage = true)
	{
		if (m_infiniteFuel)
		{
			return false;
		}
		if (!player.GetInventory().HaveItem(m_fuelItem.m_itemData.m_shared.m_name))
		{
			if (sendErrorMessage)
			{
				player.Message(MessageHud.MessageType.Center, "$msg_outof " + m_fuelItem.m_itemData.m_shared.m_name);
			}
			return false;
		}
		if (!((float)Mathf.CeilToInt(m_nview.GetZDO().GetFloat(ZDOVars.s_fuel)) >= m_maxFuel))
		{
			return true;
		}
		if (sendErrorMessage)
		{
			player.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_cantaddmore", m_fuelItem.m_itemData.m_shared.m_name));
		}
		return false;
	}

	public bool CanIgnite()
	{
		return CinderSpawner.CanSpawnCinder(base.transform, ref m_biome);
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Fish : MonoBehaviour, IWaterInteractable, Hoverable, Interactable, IMonoUpdater
{
	[Serializable]
	public class BaitSetting
	{
		public ItemDrop m_bait;

		[Range(0f, 1f)]
		public float m_chance;
	}

	public string m_name = "Fish";

	public float m_swimRange = 20f;

	public float m_minDepth = 1f;

	public float m_maxDepth = 4f;

	public float m_speed = 10f;

	public float m_acceleration = 5f;

	public float m_turnRate = 10f;

	public float m_wpDurationMin = 4f;

	public float m_wpDurationMax = 4f;

	public float m_avoidSpeedScale = 2f;

	public float m_avoidRange = 5f;

	public float m_height = 0.2f;

	public float m_hookForce = 4f;

	public float m_staminaUse = 1f;

	public float m_escapeStaminaUse = 2f;

	public float m_escapeMin = 0.5f;

	public float m_escapeMax = 3f;

	public float m_escapeWaitMin = 0.75f;

	public float m_escapeWaitMax = 4f;

	public float m_escapeMaxPerLevel = 1.5f;

	public float m_baseHookChance = 0.5f;

	public GameObject m_pickupItem;

	public int m_pickupItemStackSize = 1;

	[Tooltip("Fish aren't smart enough to change their mind too often (and makes reactions/collisions feel less artificial)")]
	public float m_blockChangeDurationMin = 0.1f;

	public float m_blockChangeDurationMax = 0.6f;

	public float m_collisionFleeTimeout = 1.5f;

	private Vector3 m_waypoint;

	private FishingFloat m_waypointFF;

	private FishingFloat m_failedBait;

	private bool m_haveWaypoint;

	[Header("Baits")]
	public List<BaitSetting> m_baits = new List<BaitSetting>();

	public DropTable m_extraDrops = new DropTable();

	[Header("Jumping")]
	public float m_jumpSpeed = 3f;

	public float m_jumpHeight = 14f;

	public float m_jumpForwardStrength = 16f;

	public float m_jumpHeightLand = 3f;

	public float m_jumpChance = 0.25f;

	public float m_jumpOnLandChance = 0.5f;

	public float m_jumpOnLandDecay = 0.5f;

	public float m_maxJumpDepthOffset = 0.5f;

	public float m_jumpFrequencySeconds = 0.1f;

	public float m_jumpOnLandRotation = 2f;

	public float m_waveJumpMultiplier = 0.05f;

	public float m_jumpMaxLevel = 2f;

	public EffectList m_jumpEffects = new EffectList();

	private float m_JumpHeightStrength;

	private bool m_jumpedFromLand;

	private int m_isColliding;

	private bool m_isJumping;

	private float m_lastJumpCheck;

	private float m_swimTimer;

	private float m_lastNibbleTime;

	private float m_escapeTime;

	private float m_nextEscape;

	private Vector3 m_spawnPoint;

	private bool m_fast;

	private float m_lastCollision;

	private float m_blockChange;

	[Header("Waves")]
	public float m_waveFollowDirection = 7f;

	private float m_lastWave;

	private float m_inWater = -10000f;

	private WaterVolume m_waterVolume;

	private LiquidSurface m_liquidSurface;

	private FishingFloat m_fishingFloat;

	private float m_pickupTime;

	private long m_lastOwner = -1L;

	private Vector3 m_originalLocalRef;

	private bool m_lodVisible = true;

	private ZNetView m_nview;

	private Rigidbody m_body;

	private ItemDrop m_itemDrop;

	private LODGroup m_lodGroup;

	private static Vector4 s_wind;

	private static float s_wrappedTimeSeconds;

	private static float s_deltaTime;

	private static float s_time;

	private static float s_dawnDusk;

	private static int s_updatedFrame;

	private float m_waterDepth;

	private float m_waterWave;

	private int m_waterWaveCount;

	private readonly int[] m_liquids = new int[2];

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_body = GetComponent<Rigidbody>();
		m_itemDrop = GetComponent<ItemDrop>();
		m_lodGroup = GetComponent<LODGroup>();
		if ((bool)m_itemDrop)
		{
			if (m_itemDrop.m_itemData.m_quality > 1)
			{
				m_itemDrop.SetQuality(m_itemDrop.m_itemData.m_quality);
			}
			ItemDrop itemDrop = m_itemDrop;
			itemDrop.m_onDrop = (Action<ItemDrop>)Delegate.Combine(itemDrop.m_onDrop, new Action<ItemDrop>(onDrop));
			if (m_pickupItem == null)
			{
				m_pickupItem = base.gameObject;
			}
		}
		m_waterWaveCount = UnityEngine.Random.Range(0, 1);
		if ((bool)m_lodGroup)
		{
			m_originalLocalRef = m_lodGroup.localReferencePoint;
		}
	}

	private void Start()
	{
		m_spawnPoint = m_nview.GetZDO().GetVec3(ZDOVars.s_spawnPoint, base.transform.position);
		if (m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_spawnPoint, m_spawnPoint);
			RandomizeWaypoint(canHook: true, Time.time);
		}
		if (m_nview.IsValid())
		{
			m_nview.Register("RequestPickup", RPC_RequestPickup);
			m_nview.Register("Pickup", RPC_Pickup);
		}
		if (m_waterVolume != null)
		{
			m_waterDepth = m_waterVolume.Depth(base.transform.position);
			m_waterWave = m_waterVolume.CalcWave(base.transform.position, m_waterDepth, s_wrappedTimeSeconds, 1f);
		}
	}

	private void OnEnable()
	{
		Instances.Add(this);
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public string GetHoverText()
	{
		string text = m_name;
		if (IsOutOfWater())
		{
			if ((bool)m_itemDrop)
			{
				return m_itemDrop.GetHoverText();
			}
			text += "\n[<color=yellow><b>$KEY_Use</b></color>] $inventory_pickup";
		}
		return Localization.instance.Localize(text);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool repeat, bool alt)
	{
		if (repeat)
		{
			return false;
		}
		if (!IsOutOfWater())
		{
			return false;
		}
		if (Pickup(character))
		{
			return true;
		}
		return false;
	}

	public bool Pickup(Humanoid character)
	{
		if ((bool)m_itemDrop)
		{
			m_itemDrop.Pickup(character);
			return true;
		}
		if (m_pickupItem == null)
		{
			return false;
		}
		if (!character.GetInventory().CanAddItem(m_pickupItem, m_pickupItemStackSize))
		{
			character.Message(MessageHud.MessageType.Center, "$msg_noroom");
			return false;
		}
		m_nview.InvokeRPC("RequestPickup");
		return true;
	}

	private void RPC_RequestPickup(long uid)
	{
		if (Time.time - m_pickupTime > 2f)
		{
			m_pickupTime = Time.time;
			m_nview.InvokeRPC(uid, "Pickup");
		}
	}

	private void RPC_Pickup(long uid)
	{
		if ((bool)Player.m_localPlayer && Player.m_localPlayer.PickupPrefab(m_pickupItem, m_pickupItemStackSize) != null)
		{
			m_nview.ClaimOwnership();
			m_nview.Destroy();
		}
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	public void SetLiquidLevel(float level, LiquidType type, Component liquidObj)
	{
		if (type == LiquidType.Water)
		{
			m_inWater = level;
		}
		m_liquidSurface = null;
		m_waterVolume = null;
		if (liquidObj is WaterVolume waterVolume)
		{
			m_waterVolume = waterVolume;
		}
		else if (liquidObj is LiquidSurface liquidSurface)
		{
			m_liquidSurface = liquidSurface;
		}
	}

	public Transform GetTransform()
	{
		if (this == null)
		{
			return null;
		}
		return base.transform;
	}

	public bool IsOutOfWater()
	{
		return m_inWater < base.transform.position.y - m_height;
	}

	public void CustomFixedUpdate(float fixedDeltaTime)
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		if (Time.frameCount != s_updatedFrame)
		{
			EnvMan.instance.GetWindData(out var wind, out var wind2, out var _);
			s_wind = wind + wind2;
			s_wrappedTimeSeconds = ZNet.instance.GetWrappedDayTimeSeconds();
			s_deltaTime = fixedDeltaTime;
			s_time = Time.time;
			s_dawnDusk = 1f - Utils.Abs(Utils.Abs(EnvMan.instance.GetDayFraction() * 2f - 1f) - 0.5f) * 2f;
			s_updatedFrame = Time.frameCount;
		}
		if (m_isColliding > 0)
		{
			if (s_time > m_lastCollision + 0.5f)
			{
				onCollision();
			}
			if (m_isJumping)
			{
				m_isJumping = false;
			}
		}
		Vector3 position = base.transform.position;
		bool flag = IsOutOfWater();
		if (m_waterVolume != null)
		{
			if ((++m_waterWaveCount & 1) == 1)
			{
				m_waterDepth = m_waterVolume.Depth(position);
			}
			else
			{
				m_waterWave = m_waterVolume.CalcWave(position, m_waterDepth, s_wrappedTimeSeconds, 1f);
			}
		}
		SetVisible(m_nview.HasOwner());
		if (m_lastOwner != m_nview.GetZDO().GetOwner())
		{
			m_lastOwner = m_nview.GetZDO().GetOwner();
			m_body.WakeUp();
		}
		if (!flag && UnityEngine.Random.value > 0.975f && m_nview.GetZDO().GetInt(ZDOVars.s_hooked) == 1 && m_nview.GetZDO().GetFloat(ZDOVars.s_escape) > 0f)
		{
			m_jumpEffects.Create(position, Quaternion.identity, base.transform);
		}
		if (!m_nview.IsOwner())
		{
			return;
		}
		FishingFloat fishingFloat = FishingFloat.FindFloat(this);
		if ((bool)fishingFloat)
		{
			Utils.Pull(m_body, fishingFloat.transform.position, 1f, m_hookForce, 1f, 0.5f);
		}
		if (m_isColliding > 0 && flag)
		{
			ConsiderJump(s_time);
		}
		if (m_escapeTime > 0f)
		{
			m_body.rotation *= Quaternion.AngleAxis(MathF.Sin(m_escapeTime * 40f) * 12f, Vector3.up);
			m_escapeTime -= s_deltaTime;
			if (m_escapeTime <= 0f)
			{
				m_nview.GetZDO().Set(ZDOVars.s_escape, 0);
				m_nextEscape = s_time + UnityEngine.Random.Range(m_escapeWaitMin, m_escapeWaitMax);
			}
		}
		else if (s_time > m_nextEscape && IsHooked())
		{
			Escape();
		}
		if (m_inWater <= -10000f || m_inWater < position.y + m_height)
		{
			m_body.useGravity = true;
			if (flag)
			{
				if (m_isJumping)
				{
					Vector3 linearVelocity = m_body.linearVelocity;
					if (!m_jumpedFromLand && linearVelocity != Vector3.zero)
					{
						linearVelocity.y *= 1.6f;
						m_body.rotation = Quaternion.RotateTowards(m_body.rotation, Quaternion.LookRotation(linearVelocity), 5f);
					}
				}
				return;
			}
		}
		if (m_isJumping)
		{
			if (m_body.linearVelocity.y < 0f)
			{
				m_jumpEffects.Create(position, Quaternion.identity);
				m_isJumping = false;
				m_body.rotation = Quaternion.Euler(0f, m_body.rotation.eulerAngles.y, 0f);
				RandomizeWaypoint(canHook: true, s_time);
			}
		}
		else if (m_waterWave >= m_minDepth && m_waterWave < m_minDepth + m_maxJumpDepthOffset)
		{
			ConsiderJump(s_time);
		}
		m_JumpHeightStrength = 1f;
		m_body.useGravity = false;
		m_fast = false;
		bool flag2 = s_time > m_blockChange;
		Player playerNoiseRange = Player.GetPlayerNoiseRange(position);
		if ((bool)playerNoiseRange)
		{
			if (Vector3.Distance(position, playerNoiseRange.transform.position) > m_avoidRange / 2f && !IsHooked())
			{
				if (flag2 || s_time > m_lastCollision + m_collisionFleeTimeout)
				{
					Vector3 normalized = (position - playerNoiseRange.transform.position).normalized;
					SwimDirection(normalized, fast: true, avoidLand: true, s_deltaTime);
				}
				return;
			}
			m_fast = true;
			if (m_swimTimer > 0.5f)
			{
				m_swimTimer = 0.5f;
			}
		}
		m_swimTimer -= s_deltaTime;
		if (m_swimTimer <= 0f && flag2)
		{
			RandomizeWaypoint(!m_fast, s_time);
		}
		if (m_haveWaypoint)
		{
			if ((bool)m_waypointFF)
			{
				m_waypoint = m_waypointFF.transform.position + Vector3.down;
			}
			if (Vector2.Distance(m_waypoint, position) < 0.2f || (m_escapeTime < 0f && IsHooked()))
			{
				if (!m_waypointFF)
				{
					m_haveWaypoint = false;
					return;
				}
				if (s_time - m_lastNibbleTime > 1f && m_failedBait != m_waypointFF)
				{
					m_lastNibbleTime = s_time;
					bool flag3 = TestBate(m_waypointFF);
					m_waypointFF.Nibble(this, flag3);
					if (!flag3)
					{
						m_failedBait = m_waypointFF;
					}
				}
			}
			Vector3 dir = Vector3.Normalize(m_waypoint - position);
			SwimDirection(dir, m_fast, avoidLand: false, s_deltaTime);
		}
		else
		{
			Stop(s_deltaTime);
		}
		if (!flag && m_waterVolume != null)
		{
			m_body.AddForce(new Vector3(0f, m_waterWave - m_lastWave, 0f) * 10f, ForceMode.VelocityChange);
			m_lastWave = m_waterWave;
			if (m_waterWave > 0f)
			{
				m_body.AddForce((Vector3)s_wind * m_waveFollowDirection * m_waterWave);
			}
		}
	}

	private void Stop(float dt)
	{
		if (!(m_inWater < base.transform.position.y + m_height))
		{
			Vector3 forward = base.transform.forward;
			forward.y = 0f;
			forward.Normalize();
			Quaternion to = Quaternion.LookRotation(forward, Vector3.up);
			Quaternion rot = Quaternion.RotateTowards(m_body.rotation, to, m_turnRate * dt);
			m_body.MoveRotation(rot);
			Vector3 force = -m_body.linearVelocity * m_acceleration;
			m_body.AddForce(force, ForceMode.VelocityChange);
		}
	}

	private void SwimDirection(Vector3 dir, bool fast, bool avoidLand, float dt)
	{
		Vector3 vector = dir;
		vector.y = 0f;
		if (vector == Vector3.zero)
		{
			ZLog.LogWarning("Invalid swim direction");
			return;
		}
		vector.Normalize();
		float num = m_turnRate;
		if (fast)
		{
			num *= m_avoidSpeedScale;
		}
		Quaternion to = Quaternion.LookRotation(vector, Vector3.up);
		Quaternion rotation = Quaternion.RotateTowards(base.transform.rotation, to, num * dt);
		if (!m_isJumping || !(m_body.linearVelocity.y > 0f))
		{
			if (!m_isJumping)
			{
				m_body.rotation = rotation;
			}
			float num2 = m_speed;
			if (fast)
			{
				num2 *= m_avoidSpeedScale;
			}
			if (avoidLand && GetPointDepth(base.transform.position + base.transform.forward) < m_minDepth)
			{
				num2 = 0f;
			}
			if (fast && Vector3.Dot(dir, base.transform.forward) < 0f)
			{
				num2 = 0f;
			}
			Vector3 forward = base.transform.forward;
			forward.y = dir.y;
			Vector3 vector2 = forward * num2 - m_body.linearVelocity;
			if (m_inWater < base.transform.position.y + m_height && vector2.y > 0f)
			{
				vector2.y = 0f;
			}
			m_body.AddForce(vector2 * m_acceleration, ForceMode.VelocityChange);
		}
	}

	private FishingFloat FindFloat()
	{
		foreach (FishingFloat allInstance in FishingFloat.GetAllInstances())
		{
			if (allInstance.IsInWater() && !(Vector3.Distance(base.transform.position, allInstance.transform.position) > allInstance.m_range) && !(allInstance.GetCatch() != null))
			{
				float baseHookChance = m_baseHookChance;
				if (UnityEngine.Random.value < baseHookChance)
				{
					return allInstance;
				}
			}
		}
		return null;
	}

	private bool TestBate(FishingFloat ff)
	{
		string bait = ff.GetBait();
		foreach (BaitSetting bait2 in m_baits)
		{
			if (bait2.m_bait.name == bait && UnityEngine.Random.value < bait2.m_chance)
			{
				return true;
			}
		}
		return false;
	}

	private bool RandomizeWaypoint(bool canHook, float timeNow)
	{
		if (m_isJumping)
		{
			return false;
		}
		Vector2 vector = UnityEngine.Random.insideUnitCircle * m_swimRange;
		m_waypoint = m_spawnPoint + new Vector3(vector.x, 0f, vector.y);
		m_waypointFF = null;
		if (canHook)
		{
			FishingFloat fishingFloat = FindFloat();
			if ((bool)fishingFloat && fishingFloat != m_failedBait)
			{
				m_waypointFF = fishingFloat;
				m_waypoint = fishingFloat.transform.position + Vector3.down;
			}
		}
		float pointDepth = GetPointDepth(m_waypoint);
		if (pointDepth < m_minDepth)
		{
			return false;
		}
		Vector3 p = (m_waypoint + base.transform.position) * 0.5f;
		if (GetPointDepth(p) < m_minDepth)
		{
			return false;
		}
		float maxInclusive = Mathf.Min(m_maxDepth, pointDepth - m_height);
		float waterLevel = GetWaterLevel(m_waypoint);
		m_waypoint.y = waterLevel - UnityEngine.Random.Range(m_minDepth, maxInclusive);
		m_haveWaypoint = true;
		m_swimTimer = UnityEngine.Random.Range(m_wpDurationMin, m_wpDurationMax);
		m_blockChange = timeNow + UnityEngine.Random.Range(m_blockChangeDurationMin, m_blockChangeDurationMax);
		return true;
	}

	private void Escape()
	{
		m_escapeTime = UnityEngine.Random.Range(m_escapeMin, m_escapeMax + (float)((!m_itemDrop) ? 1 : m_itemDrop.m_itemData.m_quality) * m_escapeMaxPerLevel);
		m_nview.GetZDO().Set(ZDOVars.s_escape, m_escapeTime);
	}

	private float GetPointDepth(Vector3 p)
	{
		if ((bool)ZoneSystem.instance && ZoneSystem.instance.GetSolidHeight(p, out var height, (!(m_waterVolume != null)) ? 1000 : 0))
		{
			return GetWaterLevel(p) - height;
		}
		return 0f;
	}

	private float GetWaterLevel(Vector3 point)
	{
		if (!(m_waterVolume != null))
		{
			return 30f;
		}
		return m_waterVolume.GetWaterSurface(point);
	}

	private bool DangerNearby()
	{
		return Player.GetPlayerNoiseRange(base.transform.position) != null;
	}

	public ZDOID GetZDOID()
	{
		return m_nview.GetZDO().m_uid;
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.blue;
		Gizmos.DrawWireCube(base.transform.position + Vector3.up * m_height, new Vector3(1f, 0.02f, 1f));
	}

	private void OnCollisionEnter(Collision collision)
	{
		m_isColliding++;
	}

	private void OnCollisionExit(Collision collision)
	{
		m_isColliding--;
	}

	private void onCollision()
	{
		m_lastCollision = s_time;
		if (!m_nview || !m_nview.IsOwner())
		{
			return;
		}
		for (int i = 0; i < 10; i++)
		{
			if (RandomizeWaypoint(!m_fast, s_time))
			{
				break;
			}
		}
	}

	private void onDrop(ItemDrop item)
	{
		m_JumpHeightStrength = 0f;
	}

	private void ConsiderJump(float timeNow)
	{
		if (((bool)m_itemDrop && (float)m_itemDrop.m_itemData.m_quality > m_jumpMaxLevel) || !(m_JumpHeightStrength > 0f) || !(timeNow > m_lastJumpCheck + m_jumpFrequencySeconds))
		{
			return;
		}
		m_lastJumpCheck = timeNow;
		if (IsOutOfWater())
		{
			if (UnityEngine.Random.Range(0f, 1f) < m_jumpOnLandChance * m_JumpHeightStrength)
			{
				Jump();
			}
		}
		else if (UnityEngine.Random.Range(0f, 1f) < (m_jumpChance + Mathf.Min(0f, m_lastWave) * m_waveJumpMultiplier) * s_dawnDusk)
		{
			Jump();
		}
	}

	private void Jump()
	{
		if (!m_isJumping)
		{
			m_isJumping = true;
			if (IsOutOfWater())
			{
				m_jumpedFromLand = true;
				m_JumpHeightStrength *= m_jumpOnLandDecay;
				float jumpOnLandRotation = m_jumpOnLandRotation;
				m_body.AddForce(new Vector3(0f, m_JumpHeightStrength * m_jumpHeightLand * base.transform.localScale.y, 0f), ForceMode.Impulse);
				m_body.AddTorque(UnityEngine.Random.Range(0f - jumpOnLandRotation, jumpOnLandRotation), UnityEngine.Random.Range(0f - jumpOnLandRotation, jumpOnLandRotation), UnityEngine.Random.Range(0f - jumpOnLandRotation, jumpOnLandRotation), ForceMode.Impulse);
			}
			else
			{
				m_jumpedFromLand = false;
				m_jumpEffects.Create(base.transform.position, Quaternion.identity);
				m_body.AddForce(new Vector3(0f, m_jumpHeight * base.transform.localScale.y, 0f), ForceMode.Impulse);
				m_body.AddForce(base.transform.forward * (m_jumpForwardStrength * base.transform.localScale.y), ForceMode.Impulse);
			}
		}
	}

	public void OnHooked(FishingFloat ff)
	{
		if ((bool)m_nview && m_nview.IsValid())
		{
			m_nview.ClaimOwnership();
		}
		m_fishingFloat = ff;
		if (m_nview.IsValid())
		{
			m_nview.GetZDO().Set(ZDOVars.s_hooked, (ff != null) ? 1 : 0);
			Escape();
		}
	}

	public bool IsHooked()
	{
		return m_fishingFloat != null;
	}

	public bool IsEscaping()
	{
		if (m_escapeTime > 0f)
		{
			return IsHooked();
		}
		return false;
	}

	public float GetStaminaUse()
	{
		if (!IsEscaping())
		{
			return m_staminaUse;
		}
		return m_escapeStaminaUse;
	}

	protected void SetVisible(bool visible)
	{
		if (!(m_lodGroup == null) && m_lodVisible != visible)
		{
			m_lodVisible = visible;
			if (m_lodVisible)
			{
				m_lodGroup.localReferencePoint = m_originalLocalRef;
			}
			else
			{
				m_lodGroup.localReferencePoint = new Vector3(999999f, 999999f, 999999f);
			}
		}
	}

	public int Increment(LiquidType type)
	{
		return ++m_liquids[(int)type];
	}

	public int Decrement(LiquidType type)
	{
		return --m_liquids[(int)type];
	}
}
using System.Collections.Generic;
using UnityEngine;

public class FishingFloat : MonoBehaviour, IProjectile
{
	public float m_maxDistance = 30f;

	public float m_moveForce = 10f;

	public float m_pullLineSpeed = 1f;

	public float m_pullLineSpeedMaxSkill = 2f;

	public float m_pullStaminaUse = 10f;

	public float m_pullStaminaUseMaxSkillMultiplier = 0.2f;

	public float m_hookedStaminaPerSec = 1f;

	public float m_hookedStaminaPerSecMaxSkill = 0.2f;

	private float m_fishingSkillImproveTimer;

	private float m_fishingSkillImproveHookedMultiplier = 2f;

	private bool m_baitConsumed;

	public float m_breakDistance = 4f;

	public float m_range = 10f;

	public float m_nibbleForce = 10f;

	public EffectList m_nibbleEffect = new EffectList();

	public EffectList m_lineBreakEffect = new EffectList();

	public float m_maxLineSlack = 0.3f;

	public LineConnect m_rodLine;

	public LineConnect m_hookLine;

	private ZNetView m_nview;

	private Rigidbody m_body;

	private Floating m_floating;

	private float m_lineLength;

	private float m_msgTime;

	private Fish m_nibbler;

	private float m_nibbleTime;

	private static List<FishingFloat> m_allInstances = new List<FishingFloat>();

	public string GetTooltipString(int itemQuality)
	{
		return "";
	}

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_body = GetComponent<Rigidbody>();
		m_floating = GetComponent<Floating>();
		m_nview.Register<ZDOID, bool>("RPC_Nibble", RPC_Nibble);
		m_allInstances.Add(this);
	}

	private void OnDestroy()
	{
		m_allInstances.Remove(this);
	}

	public void Setup(Character owner, Vector3 velocity, float hitNoise, HitData hitData, ItemDrop.ItemData item, ItemDrop.ItemData ammo)
	{
		FishingFloat fishingFloat = FindFloat(owner);
		if ((bool)fishingFloat)
		{
			ZNetScene.instance.Destroy(fishingFloat.gameObject);
		}
		long userID = owner.GetZDOID().UserID;
		m_nview.GetZDO().Set(ZDOVars.s_rodOwner, userID);
		m_nview.GetZDO().Set(ZDOVars.s_bait, ammo.m_dropPrefab.name);
		Transform rodTop = GetRodTop(owner);
		if (rodTop == null)
		{
			ZLog.LogWarning("Failed to find fishing rod top");
			return;
		}
		m_rodLine.SetPeer(owner.GetZDOID());
		m_lineLength = Vector3.Distance(rodTop.position, base.transform.position);
		owner.Message(MessageHud.MessageType.Center, m_lineLength.ToString("0m"));
	}

	private Character GetOwner()
	{
		if (!m_nview.IsValid())
		{
			return null;
		}
		long num = m_nview.GetZDO().GetLong(ZDOVars.s_rodOwner, 0L);
		foreach (ZNet.PlayerInfo player in ZNet.instance.GetPlayerList())
		{
			ZDOID characterID = player.m_characterID;
			if (characterID.UserID == num)
			{
				GameObject gameObject = ZNetScene.instance.FindInstance(player.m_characterID);
				if (gameObject == null)
				{
					return null;
				}
				return gameObject.GetComponent<Character>();
			}
		}
		return null;
	}

	private Transform GetRodTop(Character owner)
	{
		Transform transform = Utils.FindChild(owner.transform, "_RodTop");
		if (transform == null)
		{
			ZLog.LogWarning("Failed to find fishing rod top");
			return null;
		}
		return transform;
	}

	private void FixedUpdate()
	{
		if (!m_nview.IsOwner())
		{
			return;
		}
		float fixedDeltaTime = Time.fixedDeltaTime;
		Character owner = GetOwner();
		if (!owner)
		{
			ZLog.LogWarning("Fishing rod not found, destroying fishing float");
			m_nview.Destroy();
			return;
		}
		Transform rodTop = GetRodTop(owner);
		if (!rodTop)
		{
			ZLog.LogWarning("Fishing rod not found, destroying fishing float");
			m_nview.Destroy();
			return;
		}
		Fish fish = GetCatch();
		if (owner.InAttack() || owner.IsDrawingBow())
		{
			ReturnBait();
			if ((bool)fish)
			{
				fish.OnHooked(null);
			}
			m_nview.Destroy();
			return;
		}
		float magnitude = (rodTop.transform.position - base.transform.position).magnitude;
		ItemDrop itemDrop = (fish ? fish.gameObject.GetComponent<ItemDrop>() : null);
		if (!owner.HaveStamina() && fish != null)
		{
			SetCatch(null);
			fish = null;
			Message("$msg_fishing_lost", prioritized: true);
		}
		float skillFactor = owner.GetSkillFactor(Skills.SkillType.Fishing);
		float num = Mathf.Lerp(m_hookedStaminaPerSec, m_hookedStaminaPerSecMaxSkill, skillFactor);
		if ((bool)fish)
		{
			owner.UseStamina(num * fixedDeltaTime);
		}
		if (!fish && Utils.LengthXZ(m_body.linearVelocity) > 2f)
		{
			TryToHook();
		}
		if (owner.IsBlocking() && owner.HaveStamina())
		{
			float num2 = m_pullStaminaUse;
			if (fish != null)
			{
				num2 += fish.GetStaminaUse() * (float)((itemDrop == null) ? 1 : itemDrop.m_itemData.m_quality);
			}
			num2 = Mathf.Lerp(num2, num2 * m_pullStaminaUseMaxSkillMultiplier, skillFactor);
			owner.UseStamina(num2 * fixedDeltaTime);
			if (m_lineLength > magnitude - 0.2f)
			{
				float lineLength = m_lineLength;
				float num3 = Mathf.Lerp(m_pullLineSpeed, m_pullLineSpeedMaxSkill, skillFactor);
				if ((bool)fish && fish.IsEscaping())
				{
					num3 /= 2f;
				}
				m_lineLength -= fixedDeltaTime * num3;
				m_fishingSkillImproveTimer += fixedDeltaTime * ((fish == null) ? 1f : m_fishingSkillImproveHookedMultiplier);
				if (m_fishingSkillImproveTimer > 1f)
				{
					m_fishingSkillImproveTimer = 0f;
					owner.RaiseSkill(Skills.SkillType.Fishing);
				}
				TryToHook();
				if ((int)m_lineLength != (int)lineLength)
				{
					Message(m_lineLength.ToString("0m"));
				}
			}
			if (m_lineLength <= 0.5f)
			{
				if ((bool)fish)
				{
					string msg = Catch(fish, owner);
					Message(msg, prioritized: true);
					SetCatch(null);
					fish.OnHooked(null);
					m_nview.Destroy();
				}
				else
				{
					ReturnBait();
					m_nview.Destroy();
				}
				return;
			}
		}
		m_rodLine.SetSlack((1f - Utils.LerpStep(m_lineLength / 2f, m_lineLength, magnitude)) * m_maxLineSlack);
		if (magnitude - m_lineLength > m_breakDistance || magnitude > m_maxDistance)
		{
			Message("$msg_fishing_linebroke", prioritized: true);
			if ((bool)fish)
			{
				fish.OnHooked(null);
			}
			m_nview.Destroy();
			m_lineBreakEffect.Create(base.transform.position, Quaternion.identity);
		}
		else
		{
			if ((bool)fish)
			{
				Utils.Pull(m_body, fish.transform.position, 0.5f, m_moveForce, 0.5f, 0.3f);
			}
			Utils.Pull(m_body, rodTop.transform.position, m_lineLength, m_moveForce, 1f, 0.3f);
		}
	}

	public static string Catch(Fish fish, Character owner)
	{
		Humanoid humanoid = owner as Humanoid;
		ItemDrop itemDrop = (fish ? fish.gameObject.GetComponent<ItemDrop>() : null);
		if ((bool)itemDrop)
		{
			itemDrop.Pickup(humanoid);
		}
		else
		{
			fish.Pickup(humanoid);
		}
		string text = "$msg_fishing_catched " + fish.GetHoverName();
		if (!fish.m_extraDrops.IsEmpty())
		{
			foreach (ItemDrop.ItemData dropListItem in fish.m_extraDrops.GetDropListItems())
			{
				text = text + " & " + dropListItem.m_shared.m_name;
				if (humanoid.GetInventory().CanAddItem(dropListItem.m_dropPrefab, dropListItem.m_stack))
				{
					ZLog.Log($"picking up {dropListItem.m_stack}x {dropListItem.m_dropPrefab.name}");
					humanoid.GetInventory().AddItem(dropListItem.m_dropPrefab, dropListItem.m_stack);
				}
				else
				{
					ZLog.Log($"no room, dropping {dropListItem.m_stack}x {dropListItem.m_dropPrefab.name}");
					Object.Instantiate(dropListItem.m_dropPrefab, fish.transform.position, Quaternion.Euler(0f, Random.Range(0, 360), 0f)).GetComponent<ItemDrop>().SetStack(dropListItem.m_stack);
					Player.m_localPlayer.Message(MessageHud.MessageType.TopLeft, Localization.instance.Localize("$inventory_full"));
				}
			}
		}
		return text;
	}

	private void ReturnBait()
	{
		if (!m_baitConsumed)
		{
			Character owner = GetOwner();
			string bait = GetBait();
			GameObject prefab = ZNetScene.instance.GetPrefab(bait);
			if ((bool)prefab && owner is Player player)
			{
				player.GetInventory().AddItem(prefab, 1);
			}
		}
	}

	private void TryToHook()
	{
		if (m_nibbler != null && Time.time - m_nibbleTime < 0.5f && GetCatch() == null)
		{
			Message("$msg_fishing_hooked", prioritized: true);
			SetCatch(m_nibbler);
			m_nibbler = null;
		}
	}

	private void SetCatch(Fish fish)
	{
		if ((bool)fish)
		{
			m_nview.GetZDO().Set(ZDOVars.s_sessionCatchID, fish.GetZDOID());
			m_hookLine.SetPeer(fish.GetZDOID());
			fish.OnHooked(this);
			m_baitConsumed = true;
		}
		else
		{
			m_nview.GetZDO().Set(ZDOVars.s_sessionCatchID, ZDOID.None);
			m_hookLine.SetPeer(ZDOID.None);
		}
	}

	public Fish GetCatch()
	{
		if (!m_nview.IsValid())
		{
			return null;
		}
		ZDOID zDOID = m_nview.GetZDO().GetZDOID(ZDOVars.s_sessionCatchID);
		if (!zDOID.IsNone())
		{
			GameObject gameObject = ZNetScene.instance.FindInstance(zDOID);
			if ((bool)gameObject)
			{
				return gameObject.GetComponent<Fish>();
			}
		}
		return null;
	}

	public string GetBait()
	{
		if (m_nview == null || m_nview.GetZDO() == null)
		{
			return null;
		}
		return m_nview.GetZDO().GetString(ZDOVars.s_bait);
	}

	public bool IsInWater()
	{
		return m_floating.HaveLiquidLevel();
	}

	public void Nibble(Fish fish, bool correctBait)
	{
		m_nview.InvokeRPC("RPC_Nibble", fish.GetZDOID(), correctBait);
	}

	public void RPC_Nibble(long sender, ZDOID fishID, bool correctBait)
	{
		if (Time.time - m_nibbleTime < 1f || GetCatch() != null)
		{
			return;
		}
		if (correctBait)
		{
			m_nibbleEffect.Create(base.transform.position, Quaternion.identity, base.transform);
			m_body.AddForce(Vector3.down * m_nibbleForce, ForceMode.VelocityChange);
			GameObject gameObject = ZNetScene.instance.FindInstance(fishID);
			if ((bool)gameObject)
			{
				m_nibbler = gameObject.GetComponent<Fish>();
				m_nibbleTime = Time.time;
			}
		}
		else
		{
			m_body.AddForce(Vector3.down * m_nibbleForce * 0.5f, ForceMode.VelocityChange);
			Message("$msg_fishing_wrongbait", prioritized: true);
		}
	}

	public static List<FishingFloat> GetAllInstances()
	{
		return m_allInstances;
	}

	private static FishingFloat FindFloat(Character owner)
	{
		foreach (FishingFloat allInstance in m_allInstances)
		{
			if (owner == allInstance.GetOwner())
			{
				return allInstance;
			}
		}
		return null;
	}

	public static FishingFloat FindFloat(Fish fish)
	{
		foreach (FishingFloat allInstance in m_allInstances)
		{
			if (allInstance.GetCatch() == fish)
			{
				return allInstance;
			}
		}
		return null;
	}

	private void Message(string msg, bool prioritized = false)
	{
		if (prioritized || !(Time.time - m_msgTime < 1f))
		{
			m_msgTime = Time.time;
			Character owner = GetOwner();
			if ((bool)owner)
			{
				owner.Message(MessageHud.MessageType.Center, Localization.instance.Localize(msg));
			}
		}
	}
}
public abstract class FixedPopupBase : PopupBase
{
	public readonly string header;

	public readonly string text;

	public FixedPopupBase(string header, string text, bool localizeText = true)
	{
		this.header = (localizeText ? Localization.instance.Localize(header) : header);
		this.text = (localizeText ? Localization.instance.Localize(text) : text);
	}
}
using System.Collections.Generic;
using UnityEngine;

public class Floating : MonoBehaviour, IWaterInteractable, IMonoUpdater
{
	public float m_waterLevelOffset;

	public float m_forceDistance = 1f;

	public float m_force = 0.5f;

	public float m_balanceForceFraction = 0.02f;

	public float m_damping = 0.05f;

	public EffectList m_impactEffects = new EffectList();

	public GameObject m_surfaceEffects;

	private static int s_waterVolumeMask = 0;

	private static readonly Collider[] s_tempColliderArray = new Collider[256];

	private static readonly Dictionary<int, WaterVolume> s_waterVolumeCache = new Dictionary<int, WaterVolume>();

	private static readonly Dictionary<int, LiquidSurface> s_liquidSurfaceCache = new Dictionary<int, LiquidSurface>();

	private float m_waterLevel = -10000f;

	private float m_tarLevel = -10000f;

	private bool m_beenFloating;

	private bool m_wasInWater = true;

	private const float c_MinImpactEffectVelocity = 0.5f;

	private Rigidbody m_body;

	private Collider m_collider;

	private ZNetView m_nview;

	private readonly int[] m_liquids = new int[2];

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_body = GetComponent<Rigidbody>();
		m_collider = GetComponentInChildren<Collider>();
		SetSurfaceEffect(enabled: false);
		s_waterVolumeMask = LayerMask.GetMask("WaterVolume");
		InvokeRepeating("TerrainCheck", Random.Range(10f, 30f), 30f);
	}

	private void OnEnable()
	{
		Instances.Add(this);
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public Transform GetTransform()
	{
		if (this == null)
		{
			return null;
		}
		return base.transform;
	}

	private void TerrainCheck()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner())
		{
			return;
		}
		float groundHeight = ZoneSystem.instance.GetGroundHeight(base.transform.position);
		if (base.transform.position.y - groundHeight < -1f)
		{
			Vector3 position = base.transform.position;
			position.y = groundHeight + 1f;
			base.transform.position = position;
			Rigidbody component = GetComponent<Rigidbody>();
			if ((bool)component)
			{
				component.linearVelocity = Vector3.zero;
			}
			ZLog.Log("Moved up item " + base.gameObject.name);
		}
	}

	public void CustomFixedUpdate(float fixedDeltaTime)
	{
		CheckBody();
		if (!m_body || !m_nview.IsValid() || !m_nview.IsOwner())
		{
			return;
		}
		if (!HaveLiquidLevel())
		{
			SetSurfaceEffect(enabled: false);
			return;
		}
		UpdateImpactEffect();
		float floatDepth = GetFloatDepth();
		if (floatDepth > 0f)
		{
			SetSurfaceEffect(enabled: false);
			return;
		}
		SetSurfaceEffect(enabled: true);
		Vector3 position = m_collider.ClosestPoint(base.transform.position + Vector3.down * 1000f);
		Vector3 worldCenterOfMass = m_body.worldCenterOfMass;
		float num = Mathf.Clamp01(Mathf.Abs(floatDepth) / m_forceDistance);
		Vector3 vector = m_force * num * (fixedDeltaTime * 50f) * Vector3.up;
		m_body.WakeUp();
		m_body.AddForceAtPosition(vector * m_balanceForceFraction * m_body.mass, position, ForceMode.Impulse);
		m_body.AddForceAtPosition(vector * m_body.mass, worldCenterOfMass, ForceMode.Impulse);
		m_body.linearVelocity -= m_damping * num * m_body.linearVelocity;
		m_body.angularVelocity -= m_damping * num * m_body.angularVelocity;
	}

	public bool HaveLiquidLevel()
	{
		if (!(m_waterLevel > -10000f))
		{
			return m_tarLevel > -10000f;
		}
		return true;
	}

	private void SetSurfaceEffect(bool enabled)
	{
		if (m_surfaceEffects != null)
		{
			m_surfaceEffects.SetActive(enabled);
		}
	}

	private void UpdateImpactEffect()
	{
		CheckBody();
		if (!m_body || m_body.IsSleeping() || !m_impactEffects.HasEffects())
		{
			return;
		}
		Vector3 vector = m_collider.ClosestPoint(base.transform.position + Vector3.down * 1000f);
		float num = Mathf.Max(m_waterLevel, m_tarLevel);
		if (vector.y < num)
		{
			if (!m_wasInWater)
			{
				m_wasInWater = true;
				Vector3 basePos = vector;
				basePos.y = num;
				if (m_body.GetPointVelocity(vector).magnitude > 0.5f)
				{
					m_impactEffects.Create(basePos, Quaternion.identity);
				}
			}
		}
		else
		{
			m_wasInWater = false;
		}
	}

	private float GetFloatDepth()
	{
		CheckBody();
		if (!m_body)
		{
			return 0f;
		}
		Vector3 worldCenterOfMass = m_body.worldCenterOfMass;
		float num = Mathf.Max(m_waterLevel, m_tarLevel);
		return worldCenterOfMass.y - num - m_waterLevelOffset;
	}

	public bool IsInTar()
	{
		CheckBody();
		if (m_tarLevel <= -10000f)
		{
			return false;
		}
		return m_body.worldCenterOfMass.y - m_tarLevel - m_waterLevelOffset < -0.2f;
	}

	public void SetLiquidLevel(float level, LiquidType type, Component liquidObj)
	{
		if (type == LiquidType.Water || type == LiquidType.Tar)
		{
			if (type == LiquidType.Water)
			{
				m_waterLevel = level;
			}
			else
			{
				m_tarLevel = level;
			}
			if (!m_beenFloating && level > -10000f && GetFloatDepth() < 0f)
			{
				m_beenFloating = true;
			}
		}
	}

	private void CheckBody()
	{
		if (!m_body)
		{
			m_body = FloatingTerrain.GetBody(base.gameObject);
		}
	}

	public bool BeenFloating()
	{
		return m_beenFloating;
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.blue;
		Gizmos.DrawWireCube(base.transform.position + Vector3.down * m_waterLevelOffset, new Vector3(1f, 0.05f, 1f));
	}

	public static float GetLiquidLevel(Vector3 p, float waveFactor = 1f, LiquidType type = LiquidType.All)
	{
		if (s_waterVolumeMask == 0)
		{
			s_waterVolumeMask = LayerMask.GetMask("WaterVolume");
		}
		float num = -10000f;
		int num2 = Physics.OverlapSphereNonAlloc(p, 0f, s_tempColliderArray, s_waterVolumeMask);
		for (int i = 0; i < num2; i++)
		{
			Collider collider = s_tempColliderArray[i];
			int instanceID = collider.GetInstanceID();
			if (!s_waterVolumeCache.TryGetValue(instanceID, out var value))
			{
				value = collider.GetComponent<WaterVolume>();
				s_waterVolumeCache[instanceID] = value;
			}
			if ((bool)value)
			{
				if (type == LiquidType.All || value.GetLiquidType() == type)
				{
					num = Mathf.Max(num, value.GetWaterSurface(p, waveFactor));
				}
				continue;
			}
			if (!s_liquidSurfaceCache.TryGetValue(instanceID, out var value2))
			{
				value2 = collider.GetComponent<LiquidSurface>();
				s_liquidSurfaceCache[instanceID] = value2;
			}
			if ((bool)value2 && (type == LiquidType.All || value2.GetLiquidType() == type))
			{
				num = Mathf.Max(num, value2.GetSurface(p));
			}
		}
		return num;
	}

	public static float GetWaterLevel(Vector3 p, ref WaterVolume previousAndOut)
	{
		if (previousAndOut != null && previousAndOut.gameObject.GetComponent<Collider>().bounds.Contains(p))
		{
			return previousAndOut.GetWaterSurface(p);
		}
		float num = -10000f;
		int num2 = Physics.OverlapSphereNonAlloc(p, 0f, s_tempColliderArray, s_waterVolumeMask);
		for (int i = 0; i < num2; i++)
		{
			Collider collider = s_tempColliderArray[i];
			int instanceID = collider.GetInstanceID();
			if (!s_waterVolumeCache.TryGetValue(instanceID, out var value))
			{
				value = collider.GetComponent<WaterVolume>();
				s_waterVolumeCache[instanceID] = value;
			}
			if ((bool)value)
			{
				if (value.GetLiquidType() == LiquidType.Water)
				{
					float waterSurface = value.GetWaterSurface(p);
					if (waterSurface > num)
					{
						num = waterSurface;
						previousAndOut = value;
					}
				}
			}
			else
			{
				if (!s_liquidSurfaceCache.TryGetValue(instanceID, out var value2))
				{
					value2 = collider.GetComponent<LiquidSurface>();
					s_liquidSurfaceCache[instanceID] = value2;
				}
				if ((bool)value2 && value2.GetLiquidType() == LiquidType.Water)
				{
					num = Mathf.Max(num, value2.GetSurface(p));
				}
			}
		}
		return num;
	}

	public static bool IsUnderWater(Vector3 p, ref WaterVolume previousAndOut)
	{
		if (previousAndOut != null && previousAndOut.gameObject.GetComponent<Collider>().bounds.Contains(p))
		{
			return previousAndOut.GetWaterSurface(p) > p.y;
		}
		float num = -10000f;
		previousAndOut = null;
		int num2 = Physics.OverlapSphereNonAlloc(p, 0f, s_tempColliderArray, s_waterVolumeMask);
		for (int i = 0; i < num2; i++)
		{
			Collider collider = s_tempColliderArray[i];
			int instanceID = collider.GetInstanceID();
			if (!s_waterVolumeCache.TryGetValue(instanceID, out var value))
			{
				value = collider.GetComponent<WaterVolume>();
				s_waterVolumeCache[instanceID] = value;
			}
			if ((bool)value)
			{
				if (value.GetLiquidType() == LiquidType.Water)
				{
					float waterSurface = value.GetWaterSurface(p);
					if (waterSurface > num)
					{
						num = waterSurface;
						previousAndOut = value;
					}
				}
			}
			else
			{
				if (!s_liquidSurfaceCache.TryGetValue(instanceID, out var value2))
				{
					value2 = collider.GetComponent<LiquidSurface>();
					s_liquidSurfaceCache[instanceID] = value2;
				}
				if ((bool)value2 && value2.GetLiquidType() == LiquidType.Water)
				{
					num = Mathf.Max(num, value2.GetSurface(p));
				}
			}
		}
		return num > p.y;
	}

	public int Increment(LiquidType type)
	{
		return ++m_liquids[(int)type];
	}

	public int Decrement(LiquidType type)
	{
		return --m_liquids[(int)type];
	}
}
using System;
using UnityEngine;

public class FloatingTerrain : MonoBehaviour
{
	public float m_padding;

	public float m_waveMinOffset;

	public float m_waveFreq;

	public float m_waveAmp;

	public FloatingTerrainDummy m_dummy;

	public float m_maxCorrectionSpeed = 0.025f;

	public bool m_copyLayer = true;

	private Rigidbody m_body;

	[NonSerialized]
	public Rigidbody m_dummyBody;

	private BoxCollider m_collider;

	private BoxCollider m_dummyCollider;

	private Heightmap m_lastHeightmap;

	private Vector3 m_lastGroundNormal;

	private float m_targetOffset;

	private float m_currentOffset;

	private float m_lastHeightmapTime;

	private float m_waveTime;

	private void Start()
	{
		m_body = GetComponent<Rigidbody>();
		m_collider = GetComponentInChildren<BoxCollider>();
		InvokeRepeating("UpdateTerrain", UnityEngine.Random.Range(0.1f, 0.4f), 0.24f);
		UpdateTerrain();
	}

	private void UpdateTerrain()
	{
		if (!m_lastHeightmap)
		{
			m_targetOffset = 0f;
			return;
		}
		m_targetOffset = m_lastHeightmap.GetHeightOffset(base.transform.position) + m_padding;
		if (!m_dummy)
		{
			GameObject gameObject = new GameObject();
			if (m_copyLayer)
			{
				gameObject.layer = base.gameObject.layer;
			}
			m_dummy = gameObject.AddComponent<FloatingTerrainDummy>();
			m_dummy.m_parent = this;
			m_dummyBody = gameObject.AddComponent<Rigidbody>();
			m_dummyBody.mass = m_body.mass;
			m_dummyBody.linearDamping = m_body.linearDamping;
			m_dummyBody.angularDamping = m_body.angularDamping;
			m_dummyBody.constraints = m_body.constraints;
			m_dummyCollider = gameObject.AddComponent<BoxCollider>();
			m_dummyCollider.center = m_collider.center;
			m_dummyCollider.size = m_collider.size;
			if (m_collider.gameObject != this)
			{
				m_dummyCollider.size = Vector3.Scale(m_collider.size, m_collider.transform.localScale);
				m_dummyCollider.center = Vector3.Scale(m_collider.center, m_collider.transform.localScale);
				m_dummyCollider.center -= m_collider.transform.localPosition;
			}
			gameObject.transform.parent = base.transform.parent;
			gameObject.transform.position = base.transform.position;
			m_collider.isTrigger = true;
			UnityEngine.Object.Destroy(m_body);
		}
	}

	private void FixedUpdate()
	{
		if ((bool)m_dummy)
		{
			float maxCorrectionSpeed = m_maxCorrectionSpeed;
			float value = m_targetOffset - m_currentOffset;
			m_currentOffset += Mathf.Clamp(value, 0f - maxCorrectionSpeed, maxCorrectionSpeed);
			float num = m_currentOffset;
			if (m_waveFreq > 0f && num > m_waveMinOffset)
			{
				m_waveTime += Time.fixedDeltaTime;
				num += Mathf.Cos(m_waveTime * m_waveFreq) * m_waveAmp;
			}
			base.transform.position = m_dummy.transform.position + new Vector3(0f, num, 0f);
			base.transform.rotation = m_dummy.transform.rotation;
		}
	}

	public void OnDummyCollision(Collision collision)
	{
		OnCollisionStay(collision);
	}

	private void OnCollisionStay(Collision collision)
	{
		Heightmap component = collision.gameObject.GetComponent<Heightmap>();
		if ((object)component != null)
		{
			m_lastGroundNormal = collision.contacts[0].normal;
			m_lastHeightmapTime = Time.time;
			if (m_lastHeightmap != component)
			{
				m_lastHeightmap = component;
				UpdateTerrain();
			}
		}
		else if (m_lastHeightmapTime > 0.2f)
		{
			m_lastHeightmap = null;
		}
	}

	private void OnDrawGizmos()
	{
		if ((bool)m_dummyCollider && m_dummyCollider.enabled)
		{
			Gizmos.color = Color.yellow;
			Gizmos.matrix = Matrix4x4.TRS(m_dummyCollider.transform.position, m_dummyCollider.transform.rotation, m_dummyCollider.transform.lossyScale);
			Gizmos.DrawWireCube(m_dummyCollider.center, m_dummyCollider.size);
		}
		if (m_dummy != null)
		{
			Gizmos.DrawLine(base.transform.position, base.transform.position + new Vector3(0f, m_currentOffset, 0f));
		}
	}

	private void OnDestroy()
	{
		if ((bool)m_dummy)
		{
			UnityEngine.Object.Destroy(m_dummy.gameObject);
		}
	}

	public static Rigidbody GetBody(GameObject obj)
	{
		FloatingTerrain component = obj.GetComponent<FloatingTerrain>();
		if ((object)component != null && (bool)component.m_dummy && (bool)component.m_dummyBody)
		{
			return component.m_dummyBody;
		}
		return null;
	}
}
using UnityEngine;

public class FloatingTerrainDummy : MonoBehaviour
{
	public FloatingTerrain m_parent;

	private void OnCollisionStay(Collision collision)
	{
		if (!m_parent)
		{
			Object.Destroy(this);
		}
		m_parent.OnDummyCollision(collision);
	}
}
using UnityEngine;

public class FollowPlayer : MonoBehaviour
{
	public enum Type
	{
		Player,
		Camera,
		Average
	}

	public Type m_follow = Type.Camera;

	public bool m_lockYPos;

	public float m_maxYPos = 1000000f;

	private void LateUpdate()
	{
		Camera mainCamera = Utils.GetMainCamera();
		if (!(Player.m_localPlayer == null) && !(mainCamera == null))
		{
			Vector3 zero = Vector3.zero;
			zero = ((m_follow == Type.Camera || GameCamera.InFreeFly()) ? mainCamera.transform.position : ((m_follow != Type.Average) ? Player.m_localPlayer.transform.position : ((!GameCamera.InFreeFly()) ? ((mainCamera.transform.position + Player.m_localPlayer.transform.position) * 0.5f) : mainCamera.transform.position)));
			if (m_lockYPos)
			{
				zero.y = base.transform.position.y;
			}
			if (zero.y > m_maxYPos)
			{
				zero.y = m_maxYPos;
			}
			base.transform.position = zero;
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class FootStep : MonoBehaviour, IMonoUpdater
{
	[Flags]
	public enum MotionType
	{
		Jog = 1,
		Run = 2,
		Sneak = 4,
		Climbing = 8,
		Swimming = 0x10,
		Land = 0x20,
		Walk = 0x40
	}

	[Flags]
	public enum GroundMaterial
	{
		None = 0,
		Default = 1,
		Water = 2,
		Stone = 4,
		Wood = 8,
		Snow = 0x10,
		Mud = 0x20,
		Grass = 0x40,
		GenericGround = 0x80,
		Metal = 0x100,
		Tar = 0x200,
		Ashlands = 0x400,
		Lava = 0x800,
		Everything = 0xFFF
	}

	[Serializable]
	public class StepEffect
	{
		public string m_name = "";

		[BitMask(typeof(MotionType))]
		public MotionType m_motionType = MotionType.Jog;

		[BitMask(typeof(GroundMaterial))]
		public GroundMaterial m_material = GroundMaterial.Default;

		public GameObject[] m_effectPrefabs = Array.Empty<GameObject>();
	}

	[Header("Footless")]
	public bool m_footlessFootsteps;

	public float m_footlessTriggerDistance = 1f;

	[Space(16f)]
	public float m_footstepCullDistance = 20f;

	public List<StepEffect> m_effects = new List<StepEffect>();

	public Transform[] m_feet = Array.Empty<Transform>();

	private static readonly int s_footstepID = ZSyncAnimation.GetHash("footstep");

	private static readonly int s_forwardSpeedID = ZSyncAnimation.GetHash("forward_speed");

	private static readonly int s_sidewaySpeedID = ZSyncAnimation.GetHash("sideway_speed");

	private static readonly Queue<GameObject> s_stepInstances = new Queue<GameObject>();

	private float m_footstep;

	private float m_footstepTimer;

	private int m_pieceLayer;

	private float m_distanceAccumulator;

	private Vector3 m_lastPosition;

	private const float c_MinFootstepInterval = 0.2f;

	private const int c_MaxFootstepInstances = 30;

	private Animator m_animator;

	private Character m_character;

	private ZNetView m_nview;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Start()
	{
		m_animator = GetComponentInChildren<Animator>();
		m_character = GetComponent<Character>();
		m_nview = GetComponent<ZNetView>();
		m_footstep = m_animator.GetFloat(s_footstepID);
		if (m_pieceLayer == 0)
		{
			m_pieceLayer = LayerMask.NameToLayer("piece");
		}
		Character character = m_character;
		character.m_onLand = (Action<Vector3>)Delegate.Combine(character.m_onLand, new Action<Vector3>(OnLand));
		m_lastPosition = m_character.transform.position;
		if (m_nview.IsValid())
		{
			m_nview.Register<int, Vector3>("Step", RPC_Step);
		}
	}

	private void OnEnable()
	{
		Instances.Add(this);
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public void CustomUpdate(float dt, float time)
	{
		if (!(m_nview == null) && m_nview.IsOwner())
		{
			UpdateFootstep(dt);
			UpdateFootlessFootstep(dt);
		}
	}

	private void UpdateFootstep(float dt)
	{
		if (m_feet.Length != 0)
		{
			Camera mainCamera = Utils.GetMainCamera();
			if (!(mainCamera == null) && !(Vector3.Distance(base.transform.position, mainCamera.transform.position) > m_footstepCullDistance))
			{
				UpdateFootstepCurveTrigger(dt);
			}
		}
	}

	private void UpdateFootlessFootstep(float dt)
	{
		if (m_feet.Length == 0 && m_footlessFootsteps)
		{
			Vector3 position = base.transform.position;
			if (!m_character.IsOnGround())
			{
				m_distanceAccumulator = 0f;
			}
			else
			{
				m_distanceAccumulator += Vector3.Distance(position, m_lastPosition);
			}
			m_lastPosition = position;
			if (m_distanceAccumulator > m_footlessTriggerDistance)
			{
				m_distanceAccumulator -= m_footlessTriggerDistance;
				OnFoot(base.transform);
			}
		}
	}

	private void UpdateFootstepCurveTrigger(float dt)
	{
		m_footstepTimer += dt;
		float num = m_animator.GetFloat(s_footstepID);
		if (Utils.SignDiffers(num, m_footstep) && Mathf.Max(Mathf.Abs(m_animator.GetFloat(s_forwardSpeedID)), Mathf.Abs(m_animator.GetFloat(s_sidewaySpeedID))) > 0.2f && m_footstepTimer > 0.2f)
		{
			m_footstepTimer = 0f;
			OnFoot();
		}
		m_footstep = num;
	}

	private Transform FindActiveFoot()
	{
		Transform transform = null;
		float num = 9999f;
		Vector3 forward = base.transform.forward;
		Transform[] feet = m_feet;
		foreach (Transform transform2 in feet)
		{
			if (!(transform2 == null))
			{
				Vector3 rhs = transform2.position - base.transform.position;
				float num2 = Vector3.Dot(forward, rhs);
				if (num2 > num || transform == null)
				{
					transform = transform2;
					num = num2;
				}
			}
		}
		return transform;
	}

	private Transform FindFoot(string name)
	{
		Transform[] feet = m_feet;
		foreach (Transform transform in feet)
		{
			if (transform.gameObject.name == name)
			{
				return transform;
			}
		}
		return null;
	}

	public void OnFoot()
	{
		Transform foot = FindActiveFoot();
		OnFoot(foot);
	}

	public void OnFoot(string name)
	{
		Transform transform = FindFoot(name);
		if (transform == null)
		{
			ZLog.LogWarning("FAiled to find foot:" + name);
		}
		else
		{
			OnFoot(transform);
		}
	}

	private void OnLand(Vector3 point)
	{
		if (m_nview.IsValid())
		{
			GroundMaterial groundMaterial = GetGroundMaterial(m_character, point);
			int num = FindBestStepEffect(groundMaterial, MotionType.Land);
			if (num != -1)
			{
				m_nview.InvokeRPC(ZNetView.Everybody, "Step", num, point);
			}
		}
	}

	private void OnFoot(Transform foot)
	{
		if (m_nview.IsValid())
		{
			Vector3 vector = ((foot != null) ? foot.position : base.transform.position);
			MotionType motionType = GetMotionType(m_character);
			GroundMaterial groundMaterial = GetGroundMaterial(m_character, vector);
			int num = FindBestStepEffect(groundMaterial, motionType);
			if (num != -1)
			{
				m_nview.InvokeRPC(ZNetView.Everybody, "Step", num, vector);
			}
		}
	}

	private static void PurgeOldEffects()
	{
		while (s_stepInstances.Count > 30)
		{
			GameObject gameObject = s_stepInstances.Dequeue();
			if ((bool)gameObject)
			{
				UnityEngine.Object.Destroy(gameObject);
			}
		}
	}

	private void DoEffect(StepEffect effect, Vector3 point)
	{
		GameObject[] effectPrefabs = effect.m_effectPrefabs;
		foreach (GameObject gameObject in effectPrefabs)
		{
			GameObject gameObject2 = UnityEngine.Object.Instantiate(gameObject, point, base.transform.rotation);
			s_stepInstances.Enqueue(gameObject2);
			if (gameObject2.GetComponent<ZNetView>() != null)
			{
				ZLog.LogWarning("Foot step effect " + effect.m_name + " prefab " + gameObject.name + " in " + m_character.gameObject.name + " should not contain a ZNetView component");
			}
		}
		PurgeOldEffects();
	}

	private void RPC_Step(long sender, int effectIndex, Vector3 point)
	{
		StepEffect effect = m_effects[effectIndex];
		DoEffect(effect, point);
	}

	private static MotionType GetMotionType(Character character)
	{
		if (character.IsWalking())
		{
			return MotionType.Walk;
		}
		if (character.IsSwimming())
		{
			return MotionType.Swimming;
		}
		if (character.IsWallRunning())
		{
			return MotionType.Climbing;
		}
		if (character.IsRunning())
		{
			return MotionType.Run;
		}
		if (character.IsSneaking())
		{
			return MotionType.Sneak;
		}
		return MotionType.Jog;
	}

	private GroundMaterial GetGroundMaterial(Character character, Vector3 point)
	{
		if (character.InWater())
		{
			return GroundMaterial.Water;
		}
		if (character.InLiquid())
		{
			return GroundMaterial.Tar;
		}
		Collider lastGroundCollider = character.GetLastGroundCollider();
		if (lastGroundCollider == null)
		{
			return GroundMaterial.Default;
		}
		Heightmap component = lastGroundCollider.GetComponent<Heightmap>();
		if (component != null)
		{
			Vector3 lastGroundNormal = character.GetLastGroundNormal();
			return component.GetGroundMaterial(lastGroundNormal, point);
		}
		if (lastGroundCollider.gameObject.layer != m_pieceLayer)
		{
			return GroundMaterial.Default;
		}
		WearNTear componentInParent = lastGroundCollider.GetComponentInParent<WearNTear>();
		if (!componentInParent)
		{
			return GroundMaterial.Default;
		}
		switch (componentInParent.m_materialType)
		{
		case WearNTear.MaterialType.Wood:
			return GroundMaterial.Wood;
		case WearNTear.MaterialType.Stone:
		case WearNTear.MaterialType.Marble:
			return GroundMaterial.Stone;
		case WearNTear.MaterialType.HardWood:
			return GroundMaterial.Wood;
		case WearNTear.MaterialType.Iron:
			return GroundMaterial.Metal;
		default:
			return GroundMaterial.Default;
		}
	}

	public void FindJoints()
	{
		ZLog.Log("Finding joints");
		Transform transform = Utils.FindChild(base.transform, "LeftFootFront");
		Transform transform2 = Utils.FindChild(base.transform, "RightFootFront");
		Transform transform3 = Utils.FindChild(base.transform, "LeftFoot");
		if (transform3 == null)
		{
			transform3 = Utils.FindChild(base.transform, "LeftFootBack");
		}
		if (transform3 == null)
		{
			transform3 = Utils.FindChild(base.transform, "l_foot");
		}
		if (transform3 == null)
		{
			transform3 = Utils.FindChild(base.transform, "Foot.l");
		}
		if (transform3 == null)
		{
			transform3 = Utils.FindChild(base.transform, "foot.l");
		}
		Transform transform4 = Utils.FindChild(base.transform, "RightFoot");
		if (transform4 == null)
		{
			transform4 = Utils.FindChild(base.transform, "RightFootBack");
		}
		if (transform4 == null)
		{
			transform4 = Utils.FindChild(base.transform, "r_foot");
		}
		if (transform4 == null)
		{
			transform4 = Utils.FindChild(base.transform, "Foot.r");
		}
		if (transform4 == null)
		{
			transform4 = Utils.FindChild(base.transform, "foot.r");
		}
		List<Transform> list = new List<Transform>();
		if ((bool)transform)
		{
			list.Add(transform);
		}
		if ((bool)transform2)
		{
			list.Add(transform2);
		}
		if ((bool)transform3)
		{
			list.Add(transform3);
		}
		if ((bool)transform4)
		{
			list.Add(transform4);
		}
		m_feet = list.ToArray();
	}

	private int FindBestStepEffect(GroundMaterial material, MotionType motion)
	{
		StepEffect stepEffect = null;
		int result = -1;
		for (int i = 0; i < m_effects.Count; i++)
		{
			StepEffect stepEffect2 = m_effects[i];
			if (((stepEffect2.m_material & material) != GroundMaterial.None || (stepEffect == null && (stepEffect2.m_material & GroundMaterial.Default) != GroundMaterial.None)) && (stepEffect2.m_motionType & motion) != 0)
			{
				stepEffect = stepEffect2;
				result = i;
			}
		}
		return result;
	}
}
