public struct GameVersion
{
	public int m_major;

	public int m_minor;

	public int m_patch;

	public static GameVersion None => default(GameVersion);

	public GameVersion(int major, int minor, int patch)
	{
		m_major = major;
		m_minor = minor;
		m_patch = patch;
	}

	public static GameVersion ParseGameVersion(string versionString)
	{
		TryParseGameVersion(versionString, out var version);
		return version;
	}

	public static bool TryParseGameVersion(string versionString, out GameVersion version)
	{
		version = default(GameVersion);
		string[] array = versionString.Split('.');
		if (array.Length < 2)
		{
			return false;
		}
		if (!TryGetFirstIntFromString(array[0], out var output) || !TryGetFirstIntFromString(array[1], out var output2))
		{
			return false;
		}
		if (array.Length == 2)
		{
			version = new GameVersion(output, output2, 0);
			return true;
		}
		int output3;
		if (array[2].StartsWith("rc"))
		{
			if (!TryGetFirstIntFromString(array[2].Substring(2), out output3))
			{
				return false;
			}
			output3 = -output3;
		}
		else if (!TryGetFirstIntFromString(array[2], out output3))
		{
			return false;
		}
		version = new GameVersion(output, output2, output3);
		return true;
		static bool TryGetFirstIntFromString(string input, out int reference)
		{
			reference = 0;
			char[] array2 = new char[input.Length];
			int num = 0;
			for (int i = 0; i < input.Length; i++)
			{
				if ((num == 0 && input[i] == '-') || char.IsNumber(input[i]))
				{
					array2[num++] = input[i];
				}
				else if (num > 0)
				{
					break;
				}
			}
			if (num > 0)
			{
				return int.TryParse(new string(array2, 0, num), out reference);
			}
			return false;
		}
	}

	public bool Equals(GameVersion other)
	{
		if (m_major == other.m_major && m_minor == other.m_minor)
		{
			return m_patch == other.m_patch;
		}
		return false;
	}

	private static bool IsVersionNewer(GameVersion other, GameVersion reference)
	{
		if (other.m_major > reference.m_major)
		{
			return true;
		}
		if (other.m_major == reference.m_major && other.m_minor > reference.m_minor)
		{
			return true;
		}
		if (other.m_major == reference.m_major && other.m_minor == reference.m_minor)
		{
			if (reference.m_patch >= 0)
			{
				return other.m_patch > reference.m_patch;
			}
			if (other.m_patch >= 0)
			{
				return true;
			}
			return other.m_patch < reference.m_patch;
		}
		return false;
	}

	public bool IsValid()
	{
		return this != None;
	}

	public override string ToString()
	{
		if (!IsValid())
		{
			return "";
		}
		if (m_patch == 0)
		{
			return m_major + "." + m_minor;
		}
		if (m_patch < 0)
		{
			return m_major + "." + m_minor + ".rc" + -m_patch;
		}
		return m_major + "." + m_minor + "." + m_patch;
	}

	public override bool Equals(object other)
	{
		if (other == null)
		{
			return false;
		}
		if (!(other is GameVersion))
		{
			return false;
		}
		return Equals((GameVersion)other);
	}

	public override int GetHashCode()
	{
		return ((313811945 * -1521134295 + m_major.GetHashCode()) * -1521134295 + m_minor.GetHashCode()) * -1521134295 + m_patch.GetHashCode();
	}

	public static bool operator ==(GameVersion lhs, GameVersion rhs)
	{
		return lhs.Equals(rhs);
	}

	public static bool operator !=(GameVersion lhs, GameVersion rhs)
	{
		return !(lhs == rhs);
	}

	public static bool operator >(GameVersion lhs, GameVersion rhs)
	{
		return IsVersionNewer(lhs, rhs);
	}

	public static bool operator <(GameVersion lhs, GameVersion rhs)
	{
		return IsVersionNewer(rhs, lhs);
	}

	public static bool operator >=(GameVersion lhs, GameVersion rhs)
	{
		if (!(lhs == rhs))
		{
			return lhs > rhs;
		}
		return true;
	}

	public static bool operator <=(GameVersion lhs, GameVersion rhs)
	{
		if (!(lhs == rhs))
		{
			return lhs < rhs;
		}
		return true;
	}
}
using System;
using UnityEngine;

public class Gibber : MonoBehaviour
{
	[Serializable]
	public class GibbData
	{
		public GameObject m_object;

		public float m_chanceToSpawn = 1f;
	}

	public EffectList m_punchEffector = new EffectList();

	public GameObject m_gibHitEffect;

	public GameObject m_gibDestroyEffect;

	public float m_gibHitDestroyChance;

	public GibbData[] m_gibbs = new GibbData[0];

	public float m_minVel = 10f;

	public float m_maxVel = 20f;

	public float m_maxRotVel = 20f;

	public float m_impactDirectionMix = 0.5f;

	public float m_timeout = 5f;

	public float m_delay;

	[Range(0f, 1f)]
	public float m_chanceToRemoveGib;

	private ZNetView m_nview;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
	}

	private void Start()
	{
		Vector3 vector = base.transform.position;
		Vector3 vector2 = Vector3.zero;
		if ((bool)m_nview && m_nview.IsValid())
		{
			vector = m_nview.GetZDO().GetVec3(ZDOVars.s_hitPoint, vector);
			vector2 = m_nview.GetZDO().GetVec3(ZDOVars.s_hitDir, vector2);
		}
		if (m_delay > 0f)
		{
			Invoke("Explode", m_delay);
		}
		else
		{
			Explode(vector, vector2);
		}
	}

	public void Setup(Vector3 hitPoint, Vector3 hitDir)
	{
		if ((bool)m_nview && m_nview.IsValid())
		{
			m_nview.GetZDO().Set(ZDOVars.s_hitPoint, hitPoint);
			m_nview.GetZDO().Set(ZDOVars.s_hitDir, hitDir);
		}
	}

	private void DestroyAll()
	{
		if ((bool)m_nview)
		{
			if (!m_nview.GetZDO().HasOwner())
			{
				m_nview.ClaimOwnership();
			}
			if (m_nview.IsOwner())
			{
				ZNetScene.instance.Destroy(base.gameObject);
			}
		}
		else
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private void CreateBodies()
	{
		MeshRenderer[] componentsInChildren = base.gameObject.GetComponentsInChildren<MeshRenderer>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			GameObject gameObject = componentsInChildren[i].gameObject;
			if (m_chanceToRemoveGib > 0f && UnityEngine.Random.value < m_chanceToRemoveGib)
			{
				UnityEngine.Object.Destroy(gameObject);
			}
			else if (!gameObject.GetComponent<Rigidbody>())
			{
				gameObject.AddComponent<BoxCollider>();
				gameObject.AddComponent<Rigidbody>().maxDepenetrationVelocity = 2f;
				TimedDestruction timedDestruction = gameObject.AddComponent<TimedDestruction>();
				timedDestruction.m_timeout = UnityEngine.Random.Range(m_timeout / 2f, m_timeout);
				timedDestruction.Trigger();
			}
		}
	}

	private void Explode()
	{
		Explode(Vector3.zero, Vector3.zero);
	}

	private void Explode(Vector3 hitPoint, Vector3 hitDir)
	{
		InvokeRepeating("DestroyAll", m_timeout, 1f);
		float t = (((double)hitDir.magnitude > 0.01) ? m_impactDirectionMix : 0f);
		CreateBodies();
		Rigidbody[] componentsInChildren = base.gameObject.GetComponentsInChildren<Rigidbody>();
		if (componentsInChildren.Length == 0)
		{
			return;
		}
		Vector3 zero = Vector3.zero;
		int num = 0;
		Rigidbody[] array = componentsInChildren;
		foreach (Rigidbody rigidbody in array)
		{
			zero += rigidbody.worldCenterOfMass;
			num++;
		}
		zero /= (float)num;
		array = componentsInChildren;
		foreach (Rigidbody obj in array)
		{
			float num2 = UnityEngine.Random.Range(m_minVel, m_maxVel);
			Vector3 vector = Vector3.Lerp(Vector3.Normalize(obj.worldCenterOfMass - zero), hitDir, t);
			obj.linearVelocity = vector * num2;
			obj.angularVelocity = new Vector3(UnityEngine.Random.Range(0f - m_maxRotVel, m_maxRotVel), UnityEngine.Random.Range(0f - m_maxRotVel, m_maxRotVel), UnityEngine.Random.Range(0f - m_maxRotVel, m_maxRotVel));
		}
		GibbData[] gibbs = m_gibbs;
		foreach (GibbData gibbData in gibbs)
		{
			if ((bool)gibbData.m_object && gibbData.m_chanceToSpawn < 1f && UnityEngine.Random.value > gibbData.m_chanceToSpawn)
			{
				UnityEngine.Object.Destroy(gibbData.m_object);
			}
		}
		if ((double)hitDir.magnitude > 0.01)
		{
			Quaternion baseRot = Quaternion.LookRotation(hitDir);
			m_punchEffector.Create(hitPoint, baseRot);
		}
	}
}
