		Mathf.Max(size + 56f, 138f);
		m_healthBarRoot.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, size);
		m_healthBarSlow.SetWidth(size);
		m_healthBarFast.SetWidth(size);
