	private void UpdateAttack(float dt)
	{
		m_lastCombatTimer += dt;
		if (m_currentAttack != null && GetCurrentWeapon() != null)
		{
			m_currentAttack.Update(dt);
		}
		if (InAttack())
		{
			m_timeSinceLastAttack = 0f;
		}
		else
		{
			m_timeSinceLastAttack += dt;
		}
	}

