using UnityEngine;

public class ImpactEffect : MonoBehaviour
{
	public EffectList m_hitEffect = new EffectList();

	public EffectList m_destroyEffect = new EffectList();

	public float m_hitDestroyChance;

	public float m_minVelocity;

	public float m_maxVelocity;

	public bool m_damageToSelf;

	public bool m_damagePlayers = true;

	public bool m_damageFish;

	public HitData.HitType m_hitType = HitData.HitType.Impact;

	public int m_toolTier;

	public HitData.DamageTypes m_damages;

	public LayerMask m_triggerMask;

	public float m_interval = 0.5f;

	private bool m_firstHit = true;

	private bool m_hitEffectEnabled = true;

	private ZNetView m_nview;

	private Rigidbody m_body;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_body = GetComponent<Rigidbody>();
		if (m_maxVelocity < m_minVelocity)
		{
			m_maxVelocity = m_minVelocity;
		}
	}

	public void OnCollisionEnter(Collision info)
	{
		if (!m_nview.IsValid() || ((bool)m_nview && !m_nview.IsOwner()) || info.contacts.Length == 0 || !m_hitEffectEnabled || (m_triggerMask.value & (1 << info.collider.gameObject.layer)) == 0)
		{
			return;
		}
		float magnitude = info.relativeVelocity.magnitude;
		if (magnitude < m_minVelocity)
		{
			return;
		}
		ContactPoint contactPoint = info.contacts[0];
		Vector3 point = contactPoint.point;
		Vector3 pointVelocity = m_body.GetPointVelocity(point);
		m_hitEffectEnabled = false;
		Invoke("ResetHitTimer", m_interval);
		if (m_damages.HaveDamage())
		{
			GameObject gameObject = Projectile.FindHitObject(contactPoint.otherCollider);
			float num = (num = Utils.LerpStep(m_minVelocity, m_maxVelocity, magnitude));
			IDestructible component = gameObject.GetComponent<IDestructible>();
			if (component != null)
			{
				Character character = component as Character;
				if ((bool)character)
				{
					if (!m_damagePlayers && character.IsPlayer())
					{
						return;
					}
					float num2 = Vector3.Dot(-info.relativeVelocity.normalized, pointVelocity);
					if (num2 < m_minVelocity)
					{
						return;
					}
					ZLog.Log("Rel vel " + num2);
					num = Utils.LerpStep(m_minVelocity, m_maxVelocity, num2);
					if (character.GetSEMan().HaveStatusAttribute(StatusEffect.StatusAttribute.DoubleImpactDamage))
					{
						num *= 2f;
					}
				}
				if (!m_damageFish && (bool)gameObject.GetComponent<Fish>())
				{
					return;
				}
				HitData hitData = new HitData();
				hitData.m_point = point;
				hitData.m_dir = pointVelocity.normalized;
				hitData.m_hitCollider = info.collider;
				hitData.m_toolTier = (short)m_toolTier;
				hitData.m_hitType = m_hitType;
				hitData.m_damage = m_damages.Clone();
				hitData.m_damage.Modify(num);
				component.Damage(hitData);
			}
			if (m_damageToSelf)
			{
				IDestructible component2 = GetComponent<IDestructible>();
				if (component2 != null)
				{
					HitData hitData2 = new HitData();
					hitData2.m_point = point;
					hitData2.m_dir = -pointVelocity.normalized;
					hitData2.m_toolTier = (short)m_toolTier;
					hitData2.m_hitType = m_hitType;
					hitData2.m_damage = m_damages.Clone();
					hitData2.m_damage.Modify(num);
					component2.Damage(hitData2);
				}
			}
		}
		Vector3 rhs = Vector3.Cross(-Vector3.Normalize(info.relativeVelocity), contactPoint.normal);
		Vector3 vector = Vector3.Cross(contactPoint.normal, rhs);
		Quaternion baseRot = Quaternion.identity;
		if (vector != Vector3.zero && contactPoint.normal != Vector3.zero)
		{
			baseRot = Quaternion.LookRotation(vector, contactPoint.normal);
		}
		m_hitEffect.Create(point, baseRot);
		if (m_firstHit && m_hitDestroyChance > 0f && Random.value <= m_hitDestroyChance)
		{
			m_destroyEffect.Create(point, baseRot);
			GameObject obj = base.gameObject;
			if ((bool)base.transform.parent)
			{
				Animator componentInParent = base.transform.GetComponentInParent<Animator>();
				if ((bool)componentInParent)
				{
					obj = componentInParent.gameObject;
				}
			}
			Object.Destroy(obj);
		}
		m_firstHit = false;
	}

	private Vector3 GetAVGPos(ContactPoint[] points)
	{
		ZLog.Log("Pooints " + points.Length);
		Vector3 zero = Vector3.zero;
		for (int i = 0; i < points.Length; i++)
		{
			ContactPoint contactPoint = points[i];
			ZLog.Log("P " + contactPoint.otherCollider.gameObject.name);
			zero += contactPoint.point;
		}
		return zero;
	}

	private void ResetHitTimer()
	{
		m_hitEffectEnabled = true;
	}
}
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class Incinerator : MonoBehaviour
{
	[Serializable]
	public class IncineratorConversion
	{
		public List<Requirement> m_requirements;

		public ItemDrop m_result;

		public int m_resultAmount = 1;

		public int m_priority;

		[Tooltip("True: Requires only one of the list of ingredients to be able to produce the result. False: All of the ingredients are required.")]
		public bool m_requireOnlyOneIngredient;

		public int AttemptCraft(Inventory inv, List<ItemDrop> toAdd)
		{
			int num = int.MaxValue;
			int num2 = 0;
			Requirement requirement = null;
			foreach (Requirement requirement2 in m_requirements)
			{
				int num3 = inv.CountItems(requirement2.m_resItem.m_itemData.m_shared.m_name) / requirement2.m_amount;
				if (num3 == 0 && !m_requireOnlyOneIngredient)
				{
					return 0;
				}
				if (num3 > num2)
				{
					num2 = num3;
					requirement = requirement2;
				}
				if (num3 < num)
				{
					num = num3;
				}
			}
			int num4 = (m_requireOnlyOneIngredient ? num2 : num);
			if (num4 == 0)
			{
				return 0;
			}
			if (m_requireOnlyOneIngredient)
			{
				inv.RemoveItem(requirement.m_resItem.m_itemData.m_shared.m_name, requirement.m_amount * num4);
			}
			else
			{
				foreach (Requirement requirement3 in m_requirements)
				{
					inv.RemoveItem(requirement3.m_resItem.m_itemData.m_shared.m_name, requirement3.m_amount * num4);
				}
			}
			num4 *= m_resultAmount;
			for (int i = 0; i < num4; i++)
			{
				toAdd.Add(m_result);
			}
			return num4;
		}
	}

	[Serializable]
	public class Requirement
	{
		public ItemDrop m_resItem;

		public int m_amount = 1;
	}

	public enum Response
	{
		Fail,
		Success,
		Conversion,
		Empty
	}

	public Switch m_incinerateSwitch;

	public Container m_container;

	public Animator m_leverAnim;

	public GameObject m_lightingAOEs;

	public EffectList m_leverEffects = new EffectList();

	public float m_effectDelayMin = 5f;

	public float m_effectDelayMax = 7f;

	[Header("Conversion")]
	public List<IncineratorConversion> m_conversions;

	public ItemDrop m_defaultResult;

	public int m_defaultCost = 1;

	private ZNetView m_nview;

	private bool isInUse;

	private void Awake()
	{
		Switch incinerateSwitch = m_incinerateSwitch;
		incinerateSwitch.m_onUse = (Switch.Callback)Delegate.Combine(incinerateSwitch.m_onUse, new Switch.Callback(OnIncinerate));
		Switch incinerateSwitch2 = m_incinerateSwitch;
		incinerateSwitch2.m_onHover = (Switch.TooltipCallback)Delegate.Combine(incinerateSwitch2.m_onHover, new Switch.TooltipCallback(GetLeverHoverText));
		m_conversions.Sort((IncineratorConversion a, IncineratorConversion b) => b.m_priority.CompareTo(a.m_priority));
		m_nview = GetComponent<ZNetView>();
		if (!(m_nview == null) && m_nview.GetZDO() != null)
		{
			m_nview.Register<long>("RPC_RequestIncinerate", RPC_RequestIncinerate);
			m_nview.Register<int>("RPC_IncinerateRespons", RPC_IncinerateRespons);
			m_nview.Register("RPC_AnimateLever", RPC_AnimateLever);
			m_nview.Register("RPC_AnimateLeverReturn", RPC_AnimateLeverReturn);
		}
	}

	private void StopAOE()
	{
		isInUse = false;
	}

	public string GetLeverHoverText()
	{
		if (!PrivateArea.CheckAccess(base.transform.position))
		{
			return Localization.instance.Localize("$piece_incinerator\n$piece_noaccess");
		}
		return Localization.instance.Localize("[<color=yellow><b>$KEY_Use</b></color>] $piece_pulllever");
	}

	private bool OnIncinerate(Switch sw, Humanoid user, ItemDrop.ItemData item)
	{
		if (!m_nview.IsValid() || !m_nview.HasOwner())
		{
			return false;
		}
		if (!PrivateArea.CheckAccess(base.transform.position))
		{
			return false;
		}
		long playerID = Game.instance.GetPlayerProfile().GetPlayerID();
		m_nview.InvokeRPC("RPC_RequestIncinerate", playerID);
		return true;
	}

	private void RPC_RequestIncinerate(long uid, long playerID)
	{
		ZLog.Log("Player " + uid + " wants to incinerate " + base.gameObject.name + "   im: " + ZDOMan.GetSessionID());
		if (!m_nview.IsOwner())
		{
			ZLog.Log("  but im not the owner");
		}
		else if (m_container.IsInUse() || isInUse)
		{
			m_nview.InvokeRPC(uid, "RPC_IncinerateRespons", 0);
			ZLog.Log("  but it's in use");
		}
		else if (m_container.GetInventory().NrOfItems() == 0)
		{
			m_nview.InvokeRPC(uid, "RPC_IncinerateRespons", 3);
			ZLog.Log("  but it's empty");
		}
		else
		{
			StartCoroutine(Incinerate(uid));
		}
	}

	private IEnumerator Incinerate(long uid)
	{
		isInUse = true;
		m_nview.InvokeRPC(ZNetView.Everybody, "RPC_AnimateLever");
		m_leverEffects.Create(base.transform.position, base.transform.rotation);
		yield return new WaitForSeconds(UnityEngine.Random.Range(m_effectDelayMin, m_effectDelayMax));
		m_nview.InvokeRPC(ZNetView.Everybody, "RPC_AnimateLeverReturn");
		if (!m_nview.IsValid() || !m_nview.IsOwner() || m_container.IsInUse())
		{
			isInUse = false;
			yield break;
		}
		Invoke("StopAOE", 4f);
		UnityEngine.Object.Instantiate(m_lightingAOEs, base.transform.position, base.transform.rotation);
		Inventory inventory = m_container.GetInventory();
		List<ItemDrop> list = new List<ItemDrop>();
		int num = 0;
		foreach (IncineratorConversion conversion in m_conversions)
		{
			num += conversion.AttemptCraft(inventory, list);
		}
		if (m_defaultResult != null && m_defaultCost > 0)
		{
			int num2 = inventory.NrOfItemsIncludingStacks() / m_defaultCost;
			num += num2;
			for (int i = 0; i < num2; i++)
			{
				list.Add(m_defaultResult);
			}
		}
		inventory.RemoveAll();
		foreach (ItemDrop item in list)
		{
			inventory.AddItem(item.gameObject, 1);
		}
		m_nview.InvokeRPC(uid, "RPC_IncinerateRespons", (num <= 0) ? 1 : 2);
	}

	private void RPC_IncinerateRespons(long uid, int r)
	{
		if ((bool)Player.m_localPlayer)
		{
			string text = null;
			Player.m_localPlayer.Message(MessageHud.MessageType.Center, (Response)r switch
			{
				Response.Success => "$piece_incinerator_success", 
				Response.Conversion => "$piece_incinerator_conversion", 
				Response.Empty => "$piece_incinerator_empty", 
				_ => "$piece_incinerator_fail", 
			});
		}
	}

	private void RPC_AnimateLever(long uid)
	{
		ZLog.Log("DO THE THING WITH THE LEVER!");
		m_leverAnim.SetBool("Pulled", value: true);
	}

	private void RPC_AnimateLeverReturn(long uid)
	{
		ZLog.Log("Lever return");
		m_leverAnim.SetBool("Pulled", value: false);
	}
}
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

public class InstanceRenderer : MonoBehaviour, IMonoUpdater
{
	public Mesh m_mesh;

	public Material m_material;

	public Vector3 m_scale = Vector3.one;

	public bool m_frustumCull = true;

	public bool m_useLod;

	public bool m_useXZLodDistance = true;

	public float m_lodMinDistance = 5f;

	public float m_lodMaxDistance = 20f;

	public ShadowCastingMode m_shadowCasting;

	private bool m_dirtyBounds = true;

	private BoundingSphere m_bounds;

	private float m_lodCount;

	private Matrix4x4[] m_instances = new Matrix4x4[1024];

	private int m_instanceCount;

	private bool m_firstFrame = true;

	private static int s_layer = -1;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void OnEnable()
	{
		if (s_layer == -1)
		{
			s_layer = LayerMask.NameToLayer("InstanceRenderer");
		}
		Instances.Add(this);
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public void CustomUpdate(float deltaTime, float time)
	{
		Camera mainCamera = Utils.GetMainCamera();
		if (m_instanceCount == 0 || mainCamera == null)
		{
			return;
		}
		if (m_frustumCull)
		{
			if (m_dirtyBounds)
			{
				UpdateBounds();
			}
			if (!Utils.InsideMainCamera(m_bounds))
			{
				return;
			}
		}
		if (m_useLod)
		{
			float num = (m_useXZLodDistance ? Utils.DistanceXZ(mainCamera.transform.position, base.transform.position) : Vector3.Distance(mainCamera.transform.position, base.transform.position));
			int num2 = (int)((1f - Utils.LerpStep(m_lodMinDistance, m_lodMaxDistance, num)) * (float)m_instanceCount);
			float maxDelta = deltaTime * (float)m_instanceCount;
			m_lodCount = Mathf.MoveTowards(m_lodCount, num2, maxDelta);
			if (m_firstFrame)
			{
				if (num < m_lodMinDistance)
				{
					m_lodCount = num2;
				}
				m_firstFrame = false;
			}
			m_lodCount = Mathf.Min(m_lodCount, m_instanceCount);
			int num3 = (int)m_lodCount;
			if (num3 > 0)
			{
				Graphics.DrawMeshInstanced(m_mesh, 0, m_material, m_instances, num3, null, m_shadowCasting, receiveShadows: true, s_layer);
			}
		}
		else
		{
			Graphics.DrawMeshInstanced(m_mesh, 0, m_material, m_instances, m_instanceCount, null, m_shadowCasting, receiveShadows: true, s_layer);
		}
	}

	private void UpdateBounds()
	{
		m_dirtyBounds = false;
		Vector3 vector = new Vector3(9999999f, 9999999f, 9999999f);
		Vector3 vector2 = new Vector3(-9999999f, -9999999f, -9999999f);
		float magnitude = m_mesh.bounds.extents.magnitude;
		for (int i = 0; i < m_instanceCount; i++)
		{
			Matrix4x4 matrix4x = m_instances[i];
			Vector3 vector3 = new Vector3(matrix4x[0, 3], matrix4x[1, 3], matrix4x[2, 3]);
			Vector3 lossyScale = matrix4x.lossyScale;
			float num = Mathf.Max(Mathf.Max(lossyScale.x, lossyScale.y), lossyScale.z);
			Vector3 vector4 = new Vector3(num * magnitude, num * magnitude, num * magnitude);
			vector2 = Vector3.Max(vector2, vector3 + vector4);
			vector = Vector3.Min(vector, vector3 - vector4);
		}
		m_bounds.position = (vector2 + vector) * 0.5f;
		m_bounds.radius = Vector3.Distance(vector2, m_bounds.position);
	}

	public void AddInstance(Vector3 pos, Quaternion rot, float scale)
	{
		Matrix4x4 m = Matrix4x4.TRS(pos, rot, m_scale * scale);
		AddInstance(m);
	}

	public void AddInstance(Vector3 pos, Quaternion rot)
	{
		Matrix4x4 m = Matrix4x4.TRS(pos, rot, m_scale);
		AddInstance(m);
	}

	public void AddInstance(Matrix4x4 m)
	{
		if (m_instanceCount < 1023)
		{
			m_instances[m_instanceCount] = m;
			m_instanceCount++;
			m_dirtyBounds = true;
		}
	}

	public void Clear()
	{
		m_instanceCount = 0;
		m_dirtyBounds = true;
	}

	public void SetInstance(int index, Vector3 pos, Quaternion rot, float scale)
	{
		Matrix4x4 matrix4x = Matrix4x4.TRS(pos, rot, m_scale * scale);
		m_instances[index] = matrix4x;
		m_dirtyBounds = true;
	}

	private void Resize(int instances)
	{
		m_instanceCount = instances;
		m_dirtyBounds = true;
	}

	public void SetInstances(List<Transform> transforms, bool faceCamera = false)
	{
		Resize(transforms.Count);
		for (int i = 0; i < transforms.Count; i++)
		{
			Transform transform = transforms[i];
			m_instances[i] = Matrix4x4.TRS(transform.position, transform.rotation, transform.lossyScale);
		}
		m_dirtyBounds = true;
	}

	public void SetInstancesBillboard(List<Vector4> points)
	{
		Camera mainCamera = Utils.GetMainCamera();
		if (!(mainCamera == null))
		{
			Vector3 forward = -mainCamera.transform.forward;
			Resize(points.Count);
			for (int i = 0; i < points.Count; i++)
			{
				Vector4 vector = points[i];
				Vector3 pos = new Vector3(vector.x, vector.y, vector.z);
				float w = vector.w;
				Quaternion q = Quaternion.LookRotation(forward);
				m_instances[i] = Matrix4x4.TRS(pos, q, w * m_scale);
			}
			m_dirtyBounds = true;
		}
	}

	private void OnDrawGizmosSelected()
	{
	}
}
