public class LightFlicker : MonoBehaviour, IMonoUpdater
{
	public enum LightFlashSettings
	{
		[InspectorName("Unchanged")]
		Default,
		[InspectorName("Remove Flicker, Keep Fade")]
		OnIncludeFade,
		[InspectorName("Disable light")]
		Off,
		AlwaysOn,
		SmoothedFlicker
	}

	private Vector3 m_offset;

	public float m_flickerIntensity = 0.1f;

	public float m_flickerSpeed = 10f;

	public float m_movement = 0.1f;

	public float m_ttl;

	public float m_fadeDuration = 0.2f;

	public float m_fadeInDuration;

	[FormerlySerializedAs("m_flashingLightingsAccessibility")]
	[Header("Accessibility")]
	public LightFlashSettings m_flashingLightsSetting;

	[Range(0f, 1f)]
	public float m_accessibilityBrightnessMultiplier = 1f;

	private Light m_light;

	private float m_baseIntensity = 1f;

	private Vector3 m_basePosition = Vector3.zero;

	private float m_time;

	private float m_flickerOffset;

	private float m_smoothedIntensity;

	private float m_targetIntensity;

	private bool m_reducedFlashing;

	private bool m_smoothFlicker;

	private float m_multiplier = 1f;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		m_light = GetComponent<Light>();
		m_baseIntensity = m_light.intensity;
		m_basePosition = base.transform.localPosition;
		m_flickerOffset = UnityEngine.Random.Range(0f, 10f);
		if (Settings.ReduceFlashingLights)
		{
			m_light.intensity = 0f;
		}
		m_reducedFlashing = Settings.ReduceFlashingLights && m_flashingLightsSetting == LightFlashSettings.OnIncludeFade;
		m_multiplier = (Settings.ReduceFlashingLights ? m_accessibilityBrightnessMultiplier : 1f);
		m_smoothFlicker = Settings.ReduceFlashingLights && m_flashingLightsSetting == LightFlashSettings.SmoothedFlicker;
	}

	private void ApplySettings()
	{
		if (!base.enabled)
		{
			return;
		}
		Instances.Remove(this);
		m_reducedFlashing = Settings.ReduceFlashingLights && m_flashingLightsSetting == LightFlashSettings.OnIncludeFade;
		m_multiplier = (Settings.ReduceFlashingLights ? m_accessibilityBrightnessMultiplier : 1f);
		m_smoothFlicker = Settings.ReduceFlashingLights && m_flashingLightsSetting == LightFlashSettings.SmoothedFlicker;
		m_light.intensity = 0f;
		if (Settings.ReduceFlashingLights)
		{
			if (m_flashingLightsSetting == LightFlashSettings.Off)
			{
				m_light.intensity = 0f;
			}
			else if (m_flashingLightsSetting == LightFlashSettings.AlwaysOn)
			{
				m_light.intensity = 1f;
			}
			else
			{
				Instances.Add(this);
			}
		}
		else
		{
			Instances.Add(this);
		}
	}

	private void OnEnable()
	{
		m_time = 0f;
		if ((bool)m_light)
		{
			GraphicsSettingsManager.GraphicsSettingsChanged += ApplySettings;
			ApplySettings();
		}
	}

	private void OnDisable()
	{
		GraphicsSettingsManager.GraphicsSettingsChanged -= ApplySettings;
		Instances.Remove(this);
	}

	public void CustomUpdate(float deltaTime, float time)
	{
		if (!m_light)
		{
			ZLog.LogError("Light was null! This should never happen!");
		}
		else
		{
			if (!m_light.enabled)
			{
				return;
			}
			m_time += deltaTime;
			float num = m_flickerOffset + time * m_flickerSpeed;
			m_targetIntensity = 1f;
			if (!m_reducedFlashing)
			{
				m_targetIntensity += MathF.Sin(num) * MathF.Sin(num * 0.56436f) * MathF.Cos(num * 0.758348f) * m_flickerIntensity;
			}
			if (m_fadeInDuration > 0f)
			{
				m_targetIntensity *= Utils.LerpStep(0f, m_fadeInDuration, m_time);
			}
			if (m_ttl > 0f)
			{
				if (m_time > m_ttl)
				{
					UnityEngine.Object.Destroy(base.gameObject);
					return;
				}
				float l = m_ttl - m_fadeDuration;
				m_targetIntensity *= 1f - Utils.LerpStep(l, m_ttl, m_time);
			}
			if (m_smoothFlicker)
			{
				float h = ((m_time > m_ttl - m_fadeDuration && m_ttl > 0f) ? 0.075f : 0.15f);
				m_smoothedIntensity = Utils.LerpSmooth(m_smoothedIntensity, m_targetIntensity, deltaTime, h);
			}
			else
			{
				m_smoothedIntensity = m_targetIntensity;
			}
			m_light.intensity = m_baseIntensity * m_smoothedIntensity * m_multiplier;
			m_offset.x = MathF.Sin(num) * MathF.Sin(num * 0.56436f);
			m_offset.y = MathF.Sin(num * 0.56436f) * MathF.Sin(num * 0.688742f);
			m_offset.z = MathF.Cos(num * 0.758348f) * MathF.Cos(num * 0.4563696f);
			m_offset *= m_movement;
			base.transform.localPosition = m_basePosition + m_offset;
		}
	}
}
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class LightLod : MonoBehaviour
{
	private static HashSet<LightLod> m_lights = new HashSet<LightLod>();

	private static List<LightLod> m_sortedLights = new List<LightLod>();

	public static int m_lightLimit = -1;

	public static int m_shadowLimit = -1;

	public bool m_lightLod = true;

	public float m_lightDistance = 40f;

	public bool m_shadowLod = true;

	public float m_shadowDistance = 20f;

	private const float m_lightSizeWeight = 0.25f;

	private static float m_updateTimer = 0f;

	private static readonly WaitForSeconds s_waitFor1Sec = new WaitForSeconds(1f);

	private int m_lightPrio;

	private float m_cameraDistanceOuter;

	private Light m_light;

	private float m_baseRange;

	private float m_baseShadowStrength;

	private void Awake()
	{
		m_light = GetComponent<Light>();
		m_baseRange = m_light.range;
		m_baseShadowStrength = m_light.shadowStrength;
		if (m_shadowLod && m_light.shadows == LightShadows.None)
		{
			m_shadowLod = false;
		}
		if (m_lightLod)
		{
			m_light.range = 0f;
			m_light.enabled = false;
		}
		if (m_shadowLod)
		{
			m_light.shadowStrength = 0f;
			m_light.shadows = LightShadows.None;
		}
		m_lights.Add(this);
	}

	private void OnEnable()
	{
		StartCoroutine("UpdateLoop");
	}

	private void OnDisable()
	{
		StopCoroutine("UpdateLoop");
	}

	private void OnDestroy()
	{
		m_lights.Remove(this);
	}

	private IEnumerator UpdateLoop()
	{
		while (true)
		{
			if ((object)Utils.GetMainCamera() != null && (bool)m_light)
			{
				Vector3 lightReferencePoint = GetLightReferencePoint();
				float distance = Vector3.Distance(lightReferencePoint, base.transform.position);
				if (m_lightLod)
				{
					if (distance < m_lightDistance && (m_lightPrio < m_lightLimit || m_lightLimit < 0))
					{
						while ((bool)m_light && (m_light.range < m_baseRange || !m_light.enabled))
						{
							m_light.enabled = true;
							m_light.range = Mathf.Min(m_baseRange, m_light.range + Time.deltaTime * m_baseRange);
							yield return null;
						}
					}
					else
					{
						while ((bool)m_light && (m_light.range > 0f || m_light.enabled))
						{
							m_light.range = Mathf.Max(0f, m_light.range - Time.deltaTime * m_baseRange);
							if (m_light.range <= 0f)
							{
								m_light.enabled = false;
							}
							yield return null;
						}
					}
				}
				if (m_shadowLod)
				{
					if (distance < m_shadowDistance && (m_lightPrio < m_shadowLimit || m_shadowLimit < 0))
					{
						while ((bool)m_light && (m_light.shadowStrength < m_baseShadowStrength || m_light.shadows == LightShadows.None))
						{
							m_light.shadows = LightShadows.Soft;
							m_light.shadowStrength = Mathf.Min(m_baseShadowStrength, m_light.shadowStrength + Time.deltaTime * m_baseShadowStrength);
							yield return null;
						}
					}
					else
					{
						while ((bool)m_light && (m_light.shadowStrength > 0f || m_light.shadows != LightShadows.None))
						{
							m_light.shadowStrength = Mathf.Max(0f, m_light.shadowStrength - Time.deltaTime * m_baseShadowStrength);
							if (m_light.shadowStrength <= 0f)
							{
								m_light.shadows = LightShadows.None;
							}
							yield return null;
						}
					}
				}
			}
			yield return s_waitFor1Sec;
		}
	}

	private static Vector3 GetLightReferencePoint()
	{
		Camera mainCamera = Utils.GetMainCamera();
		if (GameCamera.InFreeFly() || (object)Player.m_localPlayer == null)
		{
			return mainCamera.transform.position;
		}
		return Player.m_localPlayer.transform.position;
	}

	public static void UpdateLights(float dt)
	{
		if (m_lightLimit < 0 && m_shadowLimit < 0)
		{
			return;
		}
		m_updateTimer += dt;
		if (m_updateTimer < 1f)
		{
			return;
		}
		m_updateTimer = 0f;
		if (Utils.GetMainCamera() == null)
		{
			return;
		}
		Vector3 lightReferencePoint = GetLightReferencePoint();
		m_sortedLights.Clear();
		foreach (LightLod light in m_lights)
		{
			if (light.enabled && (bool)light.m_light && light.m_light.type == LightType.Point)
			{
				light.m_cameraDistanceOuter = Vector3.Distance(lightReferencePoint, light.transform.position) - light.m_lightDistance * 0.25f;
				m_sortedLights.Add(light);
			}
		}
		m_sortedLights.Sort((LightLod a, LightLod b) => a.m_cameraDistanceOuter.CompareTo(b.m_cameraDistanceOuter));
		for (int num = 0; num < m_sortedLights.Count; num++)
		{
			m_sortedLights[num].m_lightPrio = num;
		}
	}

	private void OnDrawGizmosSelected()
	{
		if (m_lightLod)
		{
			Gizmos.color = Color.yellow;
			Gizmos.DrawWireSphere(base.transform.position, m_lightDistance);
		}
		if (m_shadowLod)
		{
			Gizmos.color = Color.grey;
			Gizmos.DrawWireSphere(base.transform.position, m_shadowDistance);
		}
	}
}
