	private List<ManageSavesMenuElement> listElements = new List<ManageSavesMenuElement>();

	private bool elementHeightChanged;

	private ClosedCallback closedCallback;

	private SavesModifiedCallback savesModifiedCallback;

	private string m_queuedNameToSelect;

	private int selectedSaveIndex = -1;

	private int selectedBackupIndex = -1;

	private float timeClicked;

	private const float doubleClickTime = 0.5f;

	private int pleaseWaitCount;

	private void Update()
	{
		bool flag = false;
		if (!blockerInfo.IsBlocked())
		{
			bool flag2 = true;
			if (ZInput.GetKeyDown(KeyCode.LeftArrow) && IsSelectedExpanded())
			{
				CollapseSelected();
				flag = true;
				flag2 = false;
			}
			if (ZInput.GetKeyDown(KeyCode.RightArrow) && !IsSelectedExpanded())
			{
				ExpandSelected();
				flag = true;
			}
			if (flag2)
			{
				if (ZInput.GetKeyDown(KeyCode.DownArrow))
				{
					SelectRelative(1);
					flag = true;
				}
				if (ZInput.GetKeyDown(KeyCode.UpArrow))
				{
					SelectRelative(-1);
					flag = true;
				}
			}
			if (ZInput.IsGamepadActive())
			{
				if (ZInput.GetButtonDown("JoyLStickDown") || ZInput.GetButtonDown("JoyDPadDown"))
				{
					SelectRelative(1);
					flag = true;
				}
				if (ZInput.GetButtonDown("JoyLStickUp") || ZInput.GetButtonDown("JoyDPadUp"))
				{
					SelectRelative(-1);
					flag = true;
				}
			}
		}
		if (flag)
		{
			UpdateButtons();
			CenterSelected();
		}
		else
		{
			UpdateButtonsInteractable();
		}
	}

	private void LateUpdate()
	{
		if (elementHeightChanged)
		{
			elementHeightChanged = false;
			UpdateElementPositions();
		}
	}

	private void UpdateButtons()
	{
		moveButton.gameObject.SetActive(FileHelpers.CloudStorageEnabled && FileHelpers.LocalStorageSupported);
		if (selectedSaveIndex < 0)
		{
			actionButton.GetComponentInChildren<TMP_Text>().text = Localization.instance.Localize("$menu_expand");
		}
		else
		{
			if (selectedBackupIndex < 0)
			{
				if (listElements[selectedSaveIndex].BackupCount > 0)
				{
					actionButton.GetComponentInChildren<TMP_Text>().text = Localization.instance.Localize(listElements[selectedSaveIndex].IsExpanded ? "$menu_collapse" : "$menu_expand");
				}
			}
			else
			{
				actionButton.GetComponentInChildren<TMP_Text>().text = Localization.instance.Localize("$menu_restorebackup");
			}
			if (selectedBackupIndex < 0)
			{
				if (!currentList[selectedSaveIndex].IsDeleted)
				{
					moveButton.GetComponentInChildren<TMP_Text>().text = Localization.instance.Localize((currentList[selectedSaveIndex].PrimaryFile.m_source != FileHelpers.FileSource.Cloud) ? "$menu_movetocloud" : "$menu_movetolocal");
				}
			}
			else
			{
				moveButton.GetComponentInChildren<TMP_Text>().text = Localization.instance.Localize((currentList[selectedSaveIndex].BackupFiles[selectedBackupIndex].m_source != FileHelpers.FileSource.Cloud) ? "$menu_movetocloud" : "$menu_movetolocal");
			}
		}
		UpdateButtonsInteractable();
	}

	private void UpdateButtonsInteractable()
	{
		bool flag = (DateTime.Now - mostRecentBackupCreatedTime).TotalSeconds >= 1.0;
		int num;
		int num2;
		if (selectedSaveIndex >= 0)
		{
			num = ((selectedSaveIndex < listElements.Count) ? 1 : 0);
			if (num != 0)
			{
				num2 = ((selectedBackupIndex >= 0) ? 1 : 0);
				goto IL_0059;
			}
		}
		else
		{
			num = 0;
		}
		num2 = 0;
		goto IL_0059;
		IL_0059:
		bool flag2 = (byte)num2 != 0;
		bool flag3 = num != 0 && listElements[selectedSaveIndex].BackupCount > 0 && selectedBackupIndex < 0;
		actionButton.interactable = flag3 || (flag2 && flag);
		bool flag4 = num != 0 && (selectedBackupIndex >= 0 || !currentList[selectedSaveIndex].IsDeleted);
		removeButton.interactable = flag4;
		moveButton.interactable = flag4 && flag;
	}

	private void OnSaveElementHeighChanged()
	{
		elementHeightChanged = true;
	}

	private void UpdateCloudUsageAsync(UpdateCloudUsageFinishedCallback callback = null)
	{
		if (FileHelpers.CloudStorageEnabled)
		{
			PushPleaseWait();
			BackgroundWorker backgroundWorker = new BackgroundWorker();
			ulong usedBytes = 0uL;
			ulong capacityBytes = 0uL;
			backgroundWorker.DoWork += delegate
			{
				usedBytes = FileHelpers.GetTotalCloudUsage();
				capacityBytes = FileHelpers.GetTotalCloudCapacity();
			};
			backgroundWorker.RunWorkerCompleted += delegate
			{
				storageUsed.gameObject.SetActive(value: true);
				storageBar.parent.gameObject.SetActive(value: true);
				storageUsed.text = Localization.instance.Localize("$menu_cloudstorageused", FileHelpers.BytesAsNumberString(usedBytes, 1u), FileHelpers.BytesAsNumberString(capacityBytes, 1u));
				storageBar.localScale = new Vector3((float)usedBytes / (float)capacityBytes, storageBar.localScale.y, storageBar.localScale.z);
				PopPleaseWait();
				callback?.Invoke();
			};
			backgroundWorker.RunWorkerAsync();
		}
		else
		{
			storageUsed.gameObject.SetActive(value: false);
			storageBar.parent.gameObject.SetActive(value: false);
			callback?.Invoke();
		}
	}

	private void OnBackButton()
	{
		Close();
	}

	private void OnRemoveButton()
	{
		if (selectedSaveIndex >= 0)
		{
			bool isBackup = selectedBackupIndex >= 0;
			string text = (isBackup ? "$menu_removebackup" : (tabHandler.GetActiveTab() switch
			{
				0 => "$menu_removeworld", 
				1 => "$menu_removecharacter", 
				_ => "Remove?", 
			}));
			SaveFile toDelete = (isBackup ? currentList[selectedSaveIndex].BackupFiles[selectedBackupIndex] : currentList[selectedSaveIndex].PrimaryFile);
			UnifiedPopup.Push(new YesNoPopup(Localization.instance.Localize(text), isBackup ? toDelete.FileName : currentList[selectedSaveIndex].m_name, delegate
			{
				UnifiedPopup.Pop();
				DeleteSaveFile(toDelete, isBackup);
			}, delegate
			{
				UnifiedPopup.Pop();
			}, localizeText: false));
		}
	}

	private void OnMoveButton()
	{
		if (selectedSaveIndex < 0)
		{
			return;
		}
		bool flag = selectedBackupIndex >= 0;
		SaveFile saveFile = (flag ? currentList[selectedSaveIndex].BackupFiles[selectedBackupIndex] : currentList[selectedSaveIndex].PrimaryFile);
		FileHelpers.FileSource fileSource = ((saveFile.m_source == FileHelpers.FileSource.Cloud) ? FileHelpers.FileSource.Local : FileHelpers.FileSource.Cloud);
		SaveFile saveFile2 = null;
		for (int i = 0; i < currentList[selectedSaveIndex].BackupFiles.Length; i++)
		{
			if (i != selectedBackupIndex && currentList[selectedSaveIndex].BackupFiles[i].m_source == fileSource && currentList[selectedSaveIndex].BackupFiles[i].FileName == saveFile.FileName)
			{
				saveFile2 = currentList[selectedSaveIndex].BackupFiles[i];
				break;
			}
		}
		if (saveFile2 == null && flag && !currentList[selectedSaveIndex].IsDeleted && currentList[selectedSaveIndex].PrimaryFile.m_source == fileSource && currentList[selectedSaveIndex].PrimaryFile.FileName == saveFile.FileName)
		{
			saveFile2 = currentList[selectedSaveIndex].PrimaryFile;
		}
		if (saveFile2 != null)
		{
			UnifiedPopup.Push(new WarningPopup(Localization.instance.Localize("$menu_cantmovesave"), Localization.instance.Localize("$menu_duplicatefileprompttext", saveFile.FileName), delegate
			{
				UnifiedPopup.Pop();
			}, localizeText: false));
		}
		else if (SaveSystem.IsCorrupt(saveFile))
		{
			UnifiedPopup.Push(new WarningPopup("$menu_cantmovesave", "$menu_savefilecorrupt", delegate
			{
				UnifiedPopup.Pop();
			}));
		}
		else
		{
			MoveSource(saveFile, flag, fileSource);
		}
	}

	private void OnPrimaryActionButton()
	{
		if (selectedSaveIndex >= 0)
		{
			if (selectedBackupIndex >= 0)
			{
				RestoreBackup();
			}
			else if (listElements[selectedSaveIndex].BackupCount > 0)
			{
				listElements[selectedSaveIndex].SetExpanded(!listElements[selectedSaveIndex].IsExpanded);
				UpdateButtons();
			}
		}
	}

	private void RestoreBackup()
	{
		SaveWithBackups saveWithBackups = currentList[selectedSaveIndex];
		SaveFile backup = currentList[selectedSaveIndex].BackupFiles[selectedBackupIndex];
		UnifiedPopup.Push(new YesNoPopup(Localization.instance.Localize("$menu_backuprestorepromptheader"), saveWithBackups.IsDeleted ? Localization.instance.Localize("$menu_backuprestorepromptrecover", saveWithBackups.m_name, backup.FileName) : Localization.instance.Localize("$menu_backuprestorepromptreplace", saveWithBackups.m_name, backup.FileName), delegate
		{
			UnifiedPopup.Pop();
			RestoreBackupAsync();
		}, delegate
		{
			UnifiedPopup.Pop();
		}, localizeText: false));
		void RestoreBackupAsync()
		{
			PushPleaseWait();
			SaveSystem.RestoreBackupResult result = SaveSystem.RestoreBackupResult.UnknownError;
			BackgroundWorker backgroundWorker = new BackgroundWorker();
			backgroundWorker.DoWork += delegate
			{
				result = SaveSystem.RestoreBackup(backup);
			};
			backgroundWorker.RunWorkerCompleted += delegate
			{
				PopPleaseWait();
				if (result != SaveSystem.RestoreBackupResult.Success)
				{
					ZLog.LogError($"Failed to restore backup: {result}");
					RestoreBackupFailed();
				}
				mostRecentBackupCreatedTime = DateTime.Now;
				savesModifiedCallback?.Invoke(GetCurrentListType());
				UpdateGuiAfterFileModification();
			};
			backgroundWorker.RunWorkerAsync();
		}
		static void RestoreBackupFailed()
		{
			UnifiedPopup.Push(new WarningPopup("$menu_backuprestorefailedheader", "$menu_tryagainorrestart", delegate
			{
				UnifiedPopup.Pop();
			}));
		}
	}

	private void UpdateGuiAfterFileModification(bool alwaysSelectSave = false)
	{
		string saveName = ((selectedSaveIndex >= 0) ? listElements[selectedSaveIndex].Save.m_name : "");
		string backupName = ((selectedSaveIndex >= 0 && selectedBackupIndex >= 0 && selectedBackupIndex < listElements[selectedSaveIndex].Save.BackupFiles.Length) ? listElements[selectedSaveIndex].Save.BackupFiles[selectedBackupIndex].FileName : "");
		int saveIndex = selectedSaveIndex;
		int backupIndex = selectedBackupIndex;
		DeselectCurrent();
		UpdateCloudUsageAsync();
		ReloadSavesAsync(delegate(bool success)
		{
			if (success)
			{
				UpdateGuiAsync();
			}
			else
			{
				ShowReloadError();
			}
		});
		void UpdateGuiAsync()
		{
			UpdateSavesListGuiAsync(delegate
			{
				int num = -1;
				for (int i = 0; i < listElements.Count; i++)
				{
					if (listElements[i].Save.m_name == saveName)
					{
						num = i;
						break;
					}
				}
				if (num >= 0)
				{
					if (backupIndex < 0 || alwaysSelectSave)
					{
						SelectByIndex(num);
					}
					else
					{
						int num2 = -1;
						for (int j = 0; j < listElements[num].Save.BackupFiles.Length; j++)
						{
							if (listElements[num].Save.BackupFiles[j].FileName == backupName)
							{
								num2 = j;
								break;
							}
						}
						if (num2 >= 0)
						{
							SelectByIndex(num, num2);
						}
						else
						{
							SelectByIndex(num, backupIndex);
						}
					}
					CenterSelected();
				}
				else
				{
					SelectByIndex(saveIndex);
					CenterSelected();
				}
				UpdateButtons();
			});
		}
	}

	public void OnWorldTab()
	{
		if (pleaseWaitCount <= 0)
		{
			ChangeList(SaveDataType.World);
		}
	}

	public void OnCharacterTab()
	{
		if (pleaseWaitCount <= 0)
		{
			ChangeList(SaveDataType.Character);
		}
	}

	private void ChangeList(SaveDataType dataType)
	{
		DeselectCurrent();
		currentList = SaveSystem.GetSavesByType(dataType);
		currentListType = dataType;
		UpdateSavesListGuiAsync(delegate
		{
			bool flag = false;
			if (!string.IsNullOrEmpty(m_queuedNameToSelect))
			{
				for (int i = 0; i < currentList.Length; i++)
				{
					if (!currentList[i].IsDeleted && currentList[i].PrimaryFile.FileName == m_queuedNameToSelect)
					{
						SelectByIndex(i);
						flag = true;
						break;
					}
				}
				m_queuedNameToSelect = null;
			}
			if (!flag || listElements.Count <= 0)
			{
				SelectByIndex(0);
			}
			if (selectedSaveIndex >= 0)
			{
				CenterSelected();
			}
			UpdateButtons();
		});
	}

	private void DeleteSaveFile(SaveFile file, bool isBackup)
	{
		PushPleaseWait();
		bool success = false;
		BackgroundWorker backgroundWorker = new BackgroundWorker();
		backgroundWorker.DoWork += delegate
		{
			success = SaveSystem.Delete(file);
		};
		backgroundWorker.RunWorkerCompleted += delegate
		{
			PopPleaseWait();
			if (!success)
			{
				DeleteSaveFailed();
				ZLog.LogError("Failed to delete save " + file.FileName);
			}
			mostRecentBackupCreatedTime = DateTime.Now;
			savesModifiedCallback?.Invoke(GetCurrentListType());
			UpdateGuiAfterFileModification();
		};
		backgroundWorker.RunWorkerAsync();
		static void DeleteSaveFailed()
		{
			UnifiedPopup.Push(new WarningPopup("$menu_deletefailedheader", "$menu_tryagainorrestart", delegate
			{
				UnifiedPopup.Pop();
			}));
		}
	}

	private void MoveSource(SaveFile file, bool isBackup, FileHelpers.FileSource destinationSource)
	{
		PushPleaseWait();
		bool cloudQuotaExceeded = false;
		bool success = false;
		BackgroundWorker backgroundWorker = new BackgroundWorker();
		backgroundWorker.DoWork += delegate
		{
			success = SaveSystem.MoveSource(file, isBackup, destinationSource, out cloudQuotaExceeded);
		};
		backgroundWorker.RunWorkerCompleted += delegate
		{
			PopPleaseWait();
			if (cloudQuotaExceeded)
			{
				ShowCloudQuotaWarning();
			}
			else if (!success)
			{
				MoveSourceFailed();
			}
			mostRecentBackupCreatedTime = DateTime.Now;
			savesModifiedCallback?.Invoke(GetCurrentListType());
			UpdateGuiAfterFileModification();
		};
		backgroundWorker.RunWorkerAsync();
		static void MoveSourceFailed()
		{
			UnifiedPopup.Push(new WarningPopup("$menu_movefailedheader", "$menu_tryagainorrestart", delegate
			{
				UnifiedPopup.Pop();
			}));
		}
	}

	private SaveDataType GetCurrentListType()
	{
		return currentListType;
	}

	private void ReloadSavesAsync(ReloadSavesFinishedCallback callback)
	{
		PushPleaseWait();
		Exception reloadException = null;
		BackgroundWorker backgroundWorker = new BackgroundWorker();
		backgroundWorker.DoWork += delegate
		{
			try
			{
				SaveSystem.ForceRefreshCache();
			}
			catch (Exception ex)
			{
				reloadException = ex;
			}
		};
		backgroundWorker.RunWorkerCompleted += delegate
		{
			currentList = SaveSystem.GetSavesByType(currentListType);
			PopPleaseWait();
			if (reloadException != null)
			{
				ZLog.LogError(reloadException.ToString());
			}
			callback?.Invoke(reloadException == null);
		};
		backgroundWorker.RunWorkerAsync();
	}

	private void UpdateElementPositions()
	{
		float num = 0f;
		for (int i = 0; i < listElements.Count; i++)
		{
			listElements[i].rectTransform.anchoredPosition = new Vector2(listElements[i].rectTransform.anchoredPosition.x, 0f - num);
			num += listElements[i].rectTransform.sizeDelta.y;
		}
		listRoot.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num);
	}

	private IEnumerator UpdateElementPositionsEnumerator()
	{
		float pos = 0f;
		for (int i = 0; i < listElements.Count; i++)
		{
			listElements[i].rectTransform.anchoredPosition = new Vector2(listElements[i].rectTransform.anchoredPosition.x, 0f - pos);
			pos += listElements[i].rectTransform.sizeDelta.y;
			yield return null;
		}
		listRoot.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, pos);
	}

	private ManageSavesMenuElement CreateElement()
	{
		GameObject obj = UnityEngine.Object.Instantiate(saveElement, listRoot);
		ManageSavesMenuElement component = obj.GetComponent<ManageSavesMenuElement>();
		obj.SetActive(value: true);
		component.HeightChanged += OnSaveElementHeighChanged;
		component.ElementClicked += OnElementClicked;
		component.ElementExpandedChanged += OnElementExpandedChanged;
		return component;
	}

	private void UpdateSavesListGui()
	{
		List<ManageSavesMenuElement> list = new List<ManageSavesMenuElement>();
		Dictionary<string, ManageSavesMenuElement> dictionary = new Dictionary<string, ManageSavesMenuElement>();
		for (int i = 0; i < listElements.Count; i++)
		{
			dictionary.Add(listElements[i].Save.m_name, listElements[i]);
		}
		for (int j = 0; j < currentList.Length; j++)
		{
			if (dictionary.ContainsKey(currentList[j].m_name))
			{
				dictionary[currentList[j].m_name].UpdateElement(currentList[j]);
				list.Add(dictionary[currentList[j].m_name]);
				dictionary.Remove(currentList[j].m_name);
			}
			else
			{
				ManageSavesMenuElement manageSavesMenuElement = CreateElement();
				manageSavesMenuElement.SetUp(manageSavesMenuElement.Save);
				list.Add(manageSavesMenuElement);
			}
		}
		foreach (KeyValuePair<string, ManageSavesMenuElement> item in dictionary)
		{
			UnityEngine.Object.Destroy(item.Value.gameObject);
		}
		listElements = list;
		UpdateElementPositions();
	}

	private IEnumerator UpdateSaveListGuiAsyncCoroutine(UpdateGuiListFinishedCallback callback)
	{
		PushPleaseWait();
		float timeBudget = 0.25f / (float)Application.targetFrameRate;
		DateTime now = DateTime.Now;
		for (int i = listElements.Count - 1; i >= 0; i--)
		{
			listElements[i].rectTransform.anchoredPosition = new Vector2(listElements[i].rectTransform.anchoredPosition.x, 1000000f);
			if ((DateTime.Now - now).TotalSeconds >= (double)timeBudget)
			{
				yield return null;
				now = DateTime.Now;
			}
		}
		if ((DateTime.Now - now).TotalSeconds >= (double)timeBudget)
		{
			yield return null;
			now = DateTime.Now;
		}
		List<ManageSavesMenuElement> newSaveElementsList = new List<ManageSavesMenuElement>();
		Dictionary<string, ManageSavesMenuElement> saveNameToElementMap = new Dictionary<string, ManageSavesMenuElement>();
		for (int i = 0; i < listElements.Count; i++)
		{
			saveNameToElementMap.Add(listElements[i].Save.m_name, listElements[i]);
			if ((DateTime.Now - now).TotalSeconds >= (double)timeBudget)
			{
				yield return null;
				now = DateTime.Now;
			}
		}
		for (int i = 0; i < currentList.Length; i++)
		{
			if (saveNameToElementMap.ContainsKey(currentList[i].m_name))
			{
				IEnumerator updateElementEnumerator = saveNameToElementMap[currentList[i].m_name].UpdateElementEnumerator(currentList[i]);
				while (updateElementEnumerator.MoveNext())
				{
					if ((DateTime.Now - now).TotalSeconds >= (double)timeBudget)
					{
						yield return null;
						now = DateTime.Now;
					}
				}
				newSaveElementsList.Add(saveNameToElementMap[currentList[i].m_name]);
				saveNameToElementMap.Remove(currentList[i].m_name);
			}
			else
			{
				ManageSavesMenuElement manageSavesMenuElement = CreateElement();
				newSaveElementsList.Add(manageSavesMenuElement);
				newSaveElementsList[newSaveElementsList.Count - 1].rectTransform.anchoredPosition = new Vector2(newSaveElementsList[newSaveElementsList.Count - 1].rectTransform.anchoredPosition.x, 1000000f);
				IEnumerator updateElementEnumerator = manageSavesMenuElement.SetUpEnumerator(currentList[i]);
				while (updateElementEnumerator.MoveNext())
				{
					if ((DateTime.Now - now).TotalSeconds >= (double)timeBudget)
					{
						yield return null;
						now = DateTime.Now;
					}
				}
			}
			if ((DateTime.Now - now).TotalSeconds >= (double)timeBudget)
			{
				yield return null;
				now = DateTime.Now;
			}
		}
		foreach (KeyValuePair<string, ManageSavesMenuElement> item in saveNameToElementMap)
		{
			UnityEngine.Object.Destroy(item.Value.gameObject);
			if ((DateTime.Now - now).TotalSeconds > (double)timeBudget)
			{
				yield return null;
				now = DateTime.Now;
			}
		}
		listElements = newSaveElementsList;
		if ((DateTime.Now - now).TotalSeconds >= (double)timeBudget)
		{
			yield return null;
			now = DateTime.Now;
		}
		IEnumerator updateElementPositionsEnumerator = UpdateElementPositionsEnumerator();
		while (updateElementPositionsEnumerator.MoveNext())
		{
			if ((DateTime.Now - now).TotalSeconds >= (double)timeBudget)
			{
				yield return null;
				now = DateTime.Now;
			}
		}
		PopPleaseWait();
		callback?.Invoke();
	}

	private void UpdateSavesListGuiAsync(UpdateGuiListFinishedCallback callback)
	{
		StartCoroutine(UpdateSaveListGuiAsyncCoroutine(callback));
	}

	private void DestroyGui()
	{
		for (int i = 0; i < listElements.Count; i++)
		{
			UnityEngine.Object.Destroy(listElements[i].gameObject);
		}
		listElements.Clear();
	}

	public void Open(SaveDataType dataType, string selectedSaveName, ClosedCallback closedCallback, SavesModifiedCallback savesModifiedCallback)
	{
		QueueSelectByName(selectedSaveName);
		Open(dataType, closedCallback, savesModifiedCallback);
	}

	public void Open(SaveDataType dataType, ClosedCallback closedCallback, SavesModifiedCallback savesModifiedCallback)
	{
		this.closedCallback = closedCallback;
		this.savesModifiedCallback = savesModifiedCallback;
		if (base.gameObject.activeSelf && tabHandler.GetActiveTab() == GetTabIndexFromSaveDataType(dataType))
		{
			return;
		}
		backButton.onClick.AddListener(OnBackButton);
		removeButton.onClick.AddListener(OnRemoveButton);
		moveButton.onClick.AddListener(OnMoveButton);
		actionButton.onClick.AddListener(OnPrimaryActionButton);
		storageUsed.gameObject.SetActive(value: false);
		storageBar.parent.gameObject.SetActive(value: false);
		base.gameObject.SetActive(value: true);
		UpdateCloudUsageAsync();
		ReloadSavesAsync(delegate(bool success)
		{
			if (!success)
			{
				ShowReloadError();
			}
			tabHandler.SetActiveTabWithoutInvokingOnClick(GetTabIndexFromSaveDataType(dataType));
			ChangeList(dataType);
		});
	}

	private void QueueSelectByName(string name)
	{
		m_queuedNameToSelect = name;
	}

	private int GetTabIndexFromSaveDataType(SaveDataType dataType)
	{
		return dataType switch
		{
			SaveDataType.World => 0, 
			SaveDataType.Character => 1, 
			_ => throw new ArgumentException($"{dataType} does not have a tab!"), 
		};
	}

	public void Close()
	{
		DestroyGui();
		backButton.onClick.RemoveListener(OnBackButton);
		removeButton.onClick.RemoveListener(OnRemoveButton);
		moveButton.onClick.RemoveListener(OnMoveButton);
		actionButton.onClick.RemoveListener(OnPrimaryActionButton);
		base.gameObject.SetActive(value: false);
		closedCallback?.Invoke();
	}

	public bool IsVisible()
	{
		return base.gameObject.activeInHierarchy;
	}

	private void SelectByIndex(int saveIndex, int backupIndex = -1)
	{
		DeselectCurrent();
		selectedSaveIndex = saveIndex;
		selectedBackupIndex = backupIndex;
		if (listElements.Count <= 0)
		{
			selectedSaveIndex = -1;
			selectedBackupIndex = -1;
		}
		else
		{
			selectedSaveIndex = Mathf.Clamp(selectedSaveIndex, 0, listElements.Count - 1);
			listElements[selectedSaveIndex].Select(ref selectedBackupIndex);
		}
	}

	private void SelectRelative(int offset)
	{
		int num = selectedSaveIndex;
		int num2 = selectedBackupIndex;
		DeselectCurrent();
		if (listElements.Count <= 0)
		{
			selectedSaveIndex = -1;
			selectedBackupIndex = -1;
			return;
		}
		if (num < 0)
		{
			num = 0;
			num2 = -1;
		}
		else if (num > listElements.Count - 1)
		{
			num = listElements.Count - 1;
			num2 = (listElements[num].IsExpanded ? listElements[num].BackupCount : (-1));
		}
		int num3 = offset;
		while (num3 != 0)
		{
			int num4 = Math.Sign(num3);
			if (listElements[num].IsExpanded)
			{
				if (num2 + num4 < -1 || num2 + num4 > listElements[num].BackupCount - 1)
				{
					if (num + num4 >= 0 && num + num4 <= listElements.Count - 1)
					{
						num += num4;
						num2 = ((num4 < 0 && listElements[num].IsExpanded) ? (listElements[num].BackupCount - 1) : (-1));
					}
				}
				else
				{
					num2 += num4;
				}
			}
			else if (num2 >= 0)
			{
				if (num + num4 >= 0 && num + num4 <= listElements.Count - 1 && num4 > 0)
				{
					num += num4;
				}
				num2 = -1;
			}
			else if (num + num4 >= 0 && num + num4 <= listElements.Count - 1)
			{
				num += num4;
				num2 = ((num4 < 0 && listElements[num].IsExpanded) ? (listElements[num].BackupCount - 1) : (-1));
			}
			num3 -= num4;
		}
		SelectByIndex(num, num2);
	}

	private void DeselectCurrent()
	{
		if (selectedSaveIndex >= 0 && selectedSaveIndex <= listElements.Count - 1)
		{
			listElements[selectedSaveIndex].Deselect(selectedBackupIndex);
		}
		selectedSaveIndex = -1;
		selectedBackupIndex = -1;
	}

	private bool IsSelectedExpanded()
	{
		if (selectedSaveIndex < 0 || selectedSaveIndex > listElements.Count - 1)
		{
			ZLog.LogError("Failed to expand save: Index " + selectedSaveIndex + " was outside of the valid range 0-" + (listElements.Count - 1) + ".");
			return false;
		}
		return listElements[selectedSaveIndex].IsExpanded;
	}

	private void ExpandSelected()
	{
		if (selectedSaveIndex < 0 || selectedSaveIndex > listElements.Count - 1)
		{
			ZLog.LogWarning("Failed to expand save: Index " + selectedSaveIndex + " was outside of the valid range 0-" + (listElements.Count - 1) + ". Ignoring.");
		}
		else
		{
			listElements[selectedSaveIndex].SetExpanded(value: true);
		}
	}

	private void CollapseSelected()
	{
		if (selectedSaveIndex < 0 || selectedSaveIndex > listElements.Count - 1)
		{
			ZLog.LogWarning("Failed to collapse save: Index " + selectedSaveIndex + " was outside of the valid range 0-" + (listElements.Count - 1) + ". Ignoring.");
		}
		else
		{
			listElements[selectedSaveIndex].SetExpanded(value: false);
		}
	}

	private void CenterSelected()
	{
		if (selectedSaveIndex < 0 || selectedSaveIndex > listElements.Count - 1)
		{
			ZLog.LogWarning("Failed to center save: Index " + selectedSaveIndex + " was outside of the valid range 0-" + (listElements.Count - 1) + ". Ignoring.");
		}
		else
		{
			scrollRectEnsureVisible.CenterOnItem(listElements[selectedSaveIndex].GetTransform(selectedBackupIndex));
		}
	}

	private void OnElementClicked(ManageSavesMenuElement element, int backupElementIndex)
	{
		int num = selectedSaveIndex;
		int num2 = selectedBackupIndex;
		int saveIndex = listElements.IndexOf(element);
		DeselectCurrent();
		SelectByIndex(saveIndex, backupElementIndex);
		if (selectedSaveIndex == num && selectedBackupIndex == num2 && Time.time < timeClicked + 0.5f)
		{
			OnPrimaryActionButton();
			timeClicked = Time.time - 0.5f;
		}
		else
		{
			timeClicked = Time.time;
		}
		UpdateButtons();
	}

	private void OnElementExpandedChanged(ManageSavesMenuElement element, bool isExpanded)
	{
		int num = listElements.IndexOf(element);
		if (selectedSaveIndex == num)
		{
			if (!isExpanded && selectedBackupIndex >= 0)
			{
				DeselectCurrent();
				SelectByIndex(num);
			}
			UpdateButtons();
		}
	}

	public void ShowCloudQuotaWarning()
	{
		UnifiedPopup.Push(new WarningPopup("$menu_cloudstoragefull", "$menu_cloudstoragefulloperationfailed", delegate
		{
			UnifiedPopup.Pop();
		}));
	}

	public void ShowReloadError()
	{
		UnifiedPopup.Push(new WarningPopup("$menu_reloadfailed", "$menu_checklogfile", delegate
		{
			UnifiedPopup.Pop();
		}));
	}

	private void PushPleaseWait()
	{
		if (pleaseWaitCount == 0)
		{
			pleaseWait.SetActive(value: true);
		}
		pleaseWaitCount++;
	}

	private void PopPleaseWait()
	{
		pleaseWaitCount--;
		if (pleaseWaitCount == 0)
		{
			pleaseWait.SetActive(value: false);
		}
	}
}
using System.Collections;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

public class ManageSavesMenuElement : MonoBehaviour
{
	public delegate void BackupElementClickedHandler();

	private class BackupElement
	{
		public SaveFile File { get; private set; }

		public GameObject GuiInstance { get; private set; }

		public Button Button { get; private set; }

		public RectTransform rectTransform => GuiInstance.transform as RectTransform;

		public BackupElement(GameObject guiInstance, SaveFile backup, BackupElementClickedHandler clickedCallback)
		{
			GuiInstance = guiInstance;
			GuiInstance.SetActive(value: true);
			Button = GuiInstance.GetComponent<Button>();
			UpdateElement(backup, clickedCallback);
		}

		public void UpdateElement(SaveFile backup, BackupElementClickedHandler clickedCallback)
		{
			File = backup;
			Button.onClick.RemoveAllListeners();
			Button.onClick.AddListener(delegate
			{
				clickedCallback?.Invoke();
			});
			string text = backup.FileName;
			if (SaveSystem.IsCorrupt(backup))
			{
				text += " [CORRUPT]";
			}
			if (SaveSystem.IsWorldWithMissingMetaFile(backup))
			{
				text += " [MISSING META FILE]";
			}
			rectTransform.Find("name").GetComponent<TMP_Text>().text = text;
			rectTransform.Find("size").GetComponent<TMP_Text>().text = FileHelpers.BytesAsNumberString(backup.Size, 1u);
			rectTransform.Find("date").GetComponent<TMP_Text>().text = backup.LastModified.ToShortDateString() + " " + backup.LastModified.ToShortTimeString();
			Transform transform = rectTransform.Find("source");
			transform.Find("source_cloud")?.gameObject.SetActive(backup.m_source == FileHelpers.FileSource.Cloud);
			transform.Find("source_local")?.gameObject.SetActive(backup.m_source == FileHelpers.FileSource.Local);
			transform.Find("source_legacy")?.gameObject.SetActive(backup.m_source == FileHelpers.FileSource.Legacy);
		}
	}

	public delegate void HeightChangedHandler();

	public delegate void ElementClickedHandler(ManageSavesMenuElement element, int backupElementIndex);

	public delegate void ElementExpandedChangedHandler(ManageSavesMenuElement element, bool isExpanded);

	[SerializeField]
	private Button primaryElement;

	[SerializeField]
	private Button backupElement;

	[SerializeField]
	private GameObject selectedBackground;

	[SerializeField]
	private Button arrow;

	[SerializeField]
	private TMP_Text nameText;

	[SerializeField]
	private TMP_Text sizeText;

	[SerializeField]
	private TMP_Text backupCountText;

	[SerializeField]
	private TMP_Text dateText;

	[SerializeField]
	private RectTransform sourceParent;

	private float elementHeight = 32f;

	private List<BackupElement> backupElements = new List<BackupElement>();

	private Coroutine arrowAnimationCoroutine;

	private Coroutine listAnimationCoroutine;

	public RectTransform rectTransform => base.transform as RectTransform;

	private RectTransform arrowRectTransform => arrow.transform as RectTransform;

	public bool IsExpanded { get; private set; }

	public int BackupCount => backupElements.Count;

	public SaveWithBackups Save { get; private set; }

	public event HeightChangedHandler HeightChanged;

	public event ElementClickedHandler ElementClicked;

	public event ElementExpandedChangedHandler ElementExpandedChanged;

	public void SetUp(SaveWithBackups save)
	{
		UpdatePrimaryElement();
		for (int i = 0; i < Save.BackupFiles.Length; i++)
		{
			BackupElement item = CreateBackupElement(Save.BackupFiles[i], i);
			backupElements.Add(item);
		}
		UpdateElementPositions();
	}

	public IEnumerator SetUpEnumerator(SaveWithBackups save)
	{
		Save = save;
		UpdatePrimaryElement();
		yield return null;
		for (int i = 0; i < Save.BackupFiles.Length; i++)
		{
			BackupElement item = CreateBackupElement(Save.BackupFiles[i], i);
			backupElements.Add(item);
			yield return null;
		}
		IEnumerator updateElementPositions = UpdateElementPositionsEnumerator();
		while (updateElementPositions.MoveNext())
		{
			yield return null;
		}
	}

	public void UpdateElement(SaveWithBackups save)
	{
		Save = save;
		UpdatePrimaryElement();
		List<BackupElement> list = new List<BackupElement>();
		Dictionary<string, Dictionary<FileHelpers.FileSource, BackupElement>> dictionary = new Dictionary<string, Dictionary<FileHelpers.FileSource, BackupElement>>();
		for (int i = 0; i < backupElements.Count; i++)
		{
			if (!dictionary.ContainsKey(backupElements[i].File.FileName))
			{
				dictionary.Add(backupElements[i].File.FileName, new Dictionary<FileHelpers.FileSource, BackupElement>());
			}
			dictionary[backupElements[i].File.FileName].Add(backupElements[i].File.m_source, backupElements[i]);
		}
		for (int j = 0; j < Save.BackupFiles.Length; j++)
		{
			SaveFile saveFile = Save.BackupFiles[j];
			if (dictionary.ContainsKey(saveFile.FileName) && dictionary[saveFile.FileName].ContainsKey(saveFile.m_source))
			{
				int currentIndex = j;
				dictionary[saveFile.FileName][saveFile.m_source].UpdateElement(saveFile, delegate
				{
					OnBackupElementClicked(currentIndex);
				});
				list.Add(dictionary[saveFile.FileName][saveFile.m_source]);
				dictionary[saveFile.FileName].Remove(saveFile.m_source);
				if (dictionary.Count <= 0)
				{
					dictionary.Remove(saveFile.FileName);
				}
			}
			else
			{
				BackupElement item = CreateBackupElement(saveFile, j);
				list.Add(item);
			}
		}
		foreach (KeyValuePair<string, Dictionary<FileHelpers.FileSource, BackupElement>> item2 in dictionary)
		{
			foreach (KeyValuePair<FileHelpers.FileSource, BackupElement> item3 in item2.Value)
			{
				Object.Destroy(item3.Value.GuiInstance);
			}
		}
		backupElements = list;
		float num = UpdateElementPositions();
		rectTransform.sizeDelta = new Vector2(rectTransform.sizeDelta.x, IsExpanded ? num : elementHeight);
	}

	public IEnumerator UpdateElementEnumerator(SaveWithBackups save)
	{
		Save = save;
		UpdatePrimaryElement();
		List<BackupElement> newBackupElementsList = new List<BackupElement>();
		Dictionary<string, Dictionary<FileHelpers.FileSource, BackupElement>> backupNameToElementMap = new Dictionary<string, Dictionary<FileHelpers.FileSource, BackupElement>>();
		for (int i = 0; i < backupElements.Count; i++)
		{
			if (!backupNameToElementMap.ContainsKey(backupElements[i].File.FileName))
			{
				backupNameToElementMap.Add(backupElements[i].File.FileName, new Dictionary<FileHelpers.FileSource, BackupElement>());
			}
			backupNameToElementMap[backupElements[i].File.FileName].Add(backupElements[i].File.m_source, backupElements[i]);
			yield return null;
		}
		for (int i = 0; i < Save.BackupFiles.Length; i++)
		{
			SaveFile saveFile = Save.BackupFiles[i];
			if (backupNameToElementMap.ContainsKey(saveFile.FileName) && backupNameToElementMap[saveFile.FileName].ContainsKey(saveFile.m_source))
			{
				int currentIndex = i;
				backupNameToElementMap[saveFile.FileName][saveFile.m_source].UpdateElement(saveFile, delegate
				{
					OnBackupElementClicked(currentIndex);
				});
				newBackupElementsList.Add(backupNameToElementMap[saveFile.FileName][saveFile.m_source]);
				backupNameToElementMap[saveFile.FileName].Remove(saveFile.m_source);
				if (backupNameToElementMap.Count <= 0)
				{
					backupNameToElementMap.Remove(saveFile.FileName);
				}
			}
			else
			{
				BackupElement item = CreateBackupElement(saveFile, i);
				newBackupElementsList.Add(item);
			}
			yield return null;
		}
		foreach (KeyValuePair<string, Dictionary<FileHelpers.FileSource, BackupElement>> item2 in backupNameToElementMap)
		{
			foreach (KeyValuePair<FileHelpers.FileSource, BackupElement> item3 in item2.Value)
			{
				Object.Destroy(item3.Value.GuiInstance);
				yield return null;
			}
		}
		backupElements = newBackupElementsList;
		float num = UpdateElementPositions();
		rectTransform.sizeDelta = new Vector2(rectTransform.sizeDelta.x, IsExpanded ? num : elementHeight);
	}

	private BackupElement CreateBackupElement(SaveFile backup, int index)
	{
		return new BackupElement(Object.Instantiate(backupElement.gameObject, rectTransform), backup, delegate
		{
			OnBackupElementClicked(index);
		});
	}

	private float UpdateElementPositions()
	{
		float num = elementHeight;
		for (int i = 0; i < backupElements.Count; i++)
		{
			backupElements[i].rectTransform.anchoredPosition = new Vector2(backupElements[i].rectTransform.anchoredPosition.x, 0f - num);
			num += backupElements[i].rectTransform.sizeDelta.y;
		}
		return num;
	}

	private IEnumerator UpdateElementPositionsEnumerator()
	{
		float pos = elementHeight;
		for (int i = 0; i < backupElements.Count; i++)
		{
			backupElements[i].rectTransform.anchoredPosition = new Vector2(backupElements[i].rectTransform.anchoredPosition.x, 0f - pos);
			pos += backupElements[i].rectTransform.sizeDelta.y;
			yield return null;
		}
	}

	private void UpdatePrimaryElement()
	{
		arrow.gameObject.SetActive(Save.BackupFiles.Length != 0);
		string text = Save.m_name;
		if (!Save.IsDeleted)
		{
			text = Save.PrimaryFile.FileName;
			if (SaveSystem.IsCorrupt(Save.PrimaryFile))
			{
				text += " [CORRUPT]";
			}
			if (SaveSystem.IsWorldWithMissingMetaFile(Save.PrimaryFile))
			{
				text += " [MISSING META]";
			}
		}
		nameText.text = text;
		sizeText.text = FileHelpers.BytesAsNumberString(Save.IsDeleted ? 0 : Save.PrimaryFile.Size, 1u) + "/" + FileHelpers.BytesAsNumberString(Save.SizeWithBackups, 1u);
		backupCountText.text = Localization.instance.Localize("$menu_backupcount", Save.BackupFiles.Length.ToString());
		dateText.text = (Save.IsDeleted ? Localization.instance.Localize("$menu_deleted") : (Save.PrimaryFile.LastModified.ToShortDateString() + " " + Save.PrimaryFile.LastModified.ToShortTimeString()));
		sourceParent.Find("source_cloud")?.gameObject.SetActive(!Save.IsDeleted && Save.PrimaryFile.m_source == FileHelpers.FileSource.Cloud);
		sourceParent.Find("source_local")?.gameObject.SetActive(!Save.IsDeleted && Save.PrimaryFile.m_source == FileHelpers.FileSource.Local);
		sourceParent.Find("source_legacy")?.gameObject.SetActive(!Save.IsDeleted && Save.PrimaryFile.m_source == FileHelpers.FileSource.Legacy);
		if (IsExpanded && Save.BackupFiles.Length == 0)
		{
			SetExpanded(value: false, animated: false);
		}
	}

	private void OnDestroy()
	{
		foreach (BackupElement backupElement in backupElements)
		{
			Object.Destroy(backupElement.GuiInstance);
		}
		backupElements.Clear();
	}

	private void Start()
	{
		elementHeight = rectTransform.sizeDelta.y;
	}

	private void OnEnable()
	{
		primaryElement.onClick.AddListener(OnElementClicked);
		arrow.onClick.AddListener(OnArrowClicked);
	}

	private void OnDisable()
	{
		primaryElement.onClick.RemoveListener(OnElementClicked);
		arrow.onClick.RemoveListener(OnArrowClicked);
	}

	private void OnElementClicked()
	{
		this.ElementClicked?.Invoke(this, -1);
	}

	private void OnBackupElementClicked(int index)
	{
		this.ElementClicked?.Invoke(this, index);
	}

	private void OnArrowClicked()
	{
		SetExpanded(!IsExpanded);
	}

	public void SetExpanded(bool value, bool animated = true)
	{
		if (IsExpanded != value)
		{
			IsExpanded = value;
			this.ElementExpandedChanged?.Invoke(this, IsExpanded);
			if (arrowAnimationCoroutine != null)
			{
				StopCoroutine(arrowAnimationCoroutine);
			}
			if (listAnimationCoroutine != null)
			{
				StopCoroutine(listAnimationCoroutine);
			}
			if (animated)
			{
				arrowAnimationCoroutine = StartCoroutine(AnimateArrow());
				listAnimationCoroutine = StartCoroutine(AnimateList());
				return;
			}
			float z = ((!IsExpanded) ? 90 : 0);
			arrowRectTransform.rotation = Quaternion.Euler(0f, 0f, z);
			float y = (IsExpanded ? (elementHeight * (float)(backupElements.Count + 1)) : elementHeight);
			rectTransform.sizeDelta = new Vector2(rectTransform.sizeDelta.x, y);
			this.HeightChanged?.Invoke();
		}
	}

	public void Select(ref int backupIndex)
	{
		if (backupIndex < 0 || BackupCount <= 0)
		{
			selectedBackground.gameObject.SetActive(value: true);
			backupIndex = -1;
		}
		else
		{
			backupIndex = Mathf.Clamp(backupIndex, 0, BackupCount - 1);
			backupElements[backupIndex].rectTransform.Find("selected").gameObject.SetActive(value: true);
		}
	}

	public void Deselect(int backupIndex = -1)
	{
		if (backupIndex < 0)
		{
			selectedBackground.gameObject.SetActive(value: false);
		}
		else if (backupIndex > backupElements.Count - 1)
		{
			ZLog.LogWarning("Failed to deselect backup: Index " + backupIndex + " was outside of the valid range -1-" + (backupElements.Count - 1) + ". Ignoring.");
		}
		else
		{
			backupElements[backupIndex].rectTransform.Find("selected").gameObject.SetActive(value: false);
		}
	}

	public RectTransform GetTransform(int backupIndex = -1)
	{
		if (backupIndex < 0)
		{
			return primaryElement.transform as RectTransform;
		}
		return backupElements[backupIndex].rectTransform;
	}

	private IEnumerator AnimateArrow()
	{
		float currentRotation = arrowRectTransform.rotation.eulerAngles.z;
		float targetRotation = ((!IsExpanded) ? 90 : 0);
		float sign = Mathf.Sign(targetRotation - currentRotation);
		while (true)
		{
			currentRotation += sign * 90f * 10f * Time.deltaTime;
			if (currentRotation * sign > targetRotation * sign)
			{
				currentRotation = targetRotation;
			}
			arrowRectTransform.rotation = Quaternion.Euler(0f, 0f, currentRotation);
			if (currentRotation == targetRotation)
			{
				break;
			}
			yield return null;
		}
		arrowAnimationCoroutine = null;
	}

	private IEnumerator AnimateList()
	{
		float currentSize = rectTransform.sizeDelta.y;
		float targetSize = (IsExpanded ? (elementHeight * (float)(backupElements.Count + 1)) : elementHeight);
		float sign = Mathf.Sign(targetSize - currentSize);
		float velocity = 0f;
		while (true)
		{
			currentSize = Mathf.SmoothDamp(currentSize, targetSize, ref velocity, 0.06f);
			if (currentSize * sign + 0.1f > targetSize * sign)
			{
				currentSize = targetSize;
			}
			rectTransform.sizeDelta = new Vector2(rectTransform.sizeDelta.x, currentSize);
			this.HeightChanged?.Invoke();
			if (currentSize == targetSize)
			{
				break;
			}
			yield return null;
		}
		listAnimationCoroutine = null;
	}
}
using System;
using UnityEngine;

public class MapTable : MonoBehaviour
{
	public string m_name = "$piece_maptable";

	public Switch m_readSwitch;

	public Switch m_writeSwitch;

	public EffectList m_writeEffects = new EffectList();

	private ZNetView m_nview;

	private void Start()
	{
		m_nview = GetComponent<ZNetView>();
		m_nview.Register<ZPackage>("MapData", RPC_MapData);
		Switch readSwitch = m_readSwitch;
		readSwitch.m_onUse = (Switch.Callback)Delegate.Combine(readSwitch.m_onUse, new Switch.Callback(OnRead));
		Switch readSwitch2 = m_readSwitch;
		readSwitch2.m_onHover = (Switch.TooltipCallback)Delegate.Combine(readSwitch2.m_onHover, new Switch.TooltipCallback(GetReadHoverText));
		Switch writeSwitch = m_writeSwitch;
		writeSwitch.m_onUse = (Switch.Callback)Delegate.Combine(writeSwitch.m_onUse, new Switch.Callback(OnWrite));
		Switch writeSwitch2 = m_writeSwitch;
		writeSwitch2.m_onHover = (Switch.TooltipCallback)Delegate.Combine(writeSwitch2.m_onHover, new Switch.TooltipCallback(GetWriteHoverText));
	}

	private string GetReadHoverText()
	{
		if (!PrivateArea.CheckAccess(base.transform.position, 0f, flash: false))
		{
			return Localization.instance.Localize(m_name + "\n$piece_noaccess");
		}
		return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_readmap ");
	}

	private string GetWriteHoverText()
	{
		if (!PrivateArea.CheckAccess(base.transform.position, 0f, flash: false))
		{
			return Localization.instance.Localize(m_name + "\n$piece_noaccess");
		}
		return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_writemap ");
	}

	private bool OnRead(Switch caller, Humanoid user, ItemDrop.ItemData item)
	{
		return OnRead(caller, user, item, showMessage: true);
	}

	private bool OnRead(Switch caller, Humanoid user, ItemDrop.ItemData item, bool showMessage)
	{
		if (item != null)
		{
			return false;
		}
		_ = Time.realtimeSinceStartup;
		byte[] byteArray = m_nview.GetZDO().GetByteArray(ZDOVars.s_data);
		if (byteArray != null)
		{
			byte[] dataArray = Utils.Decompress(byteArray);
			bool flag = Minimap.instance.AddSharedMapData(dataArray);
			if (showMessage)
			{
				if (flag)
				{
					user.Message(MessageHud.MessageType.Center, "$msg_mapsynced");
				}
				else
				{
					user.Message(MessageHud.MessageType.Center, "$msg_alreadysynced");
				}
			}
		}
		else if (showMessage)
		{
			user.Message(MessageHud.MessageType.Center, "$msg_mapnodata");
		}
		return false;
	}

	private bool OnWrite(Switch caller, Humanoid user, ItemDrop.ItemData item)
	{
		OnRead(caller, user, item, showMessage: false);
		if (item != null)
		{
			return false;
		}
		if (!m_nview.IsValid())
		{
			return false;
		}
		if (!PrivateArea.CheckAccess(base.transform.position))
		{
			return true;
		}
		byte[] array = m_nview.GetZDO().GetByteArray(ZDOVars.s_data);
		if (array != null)
		{
			array = Utils.Decompress(array);
		}
		ZPackage mapData = GetMapData(array);
		m_nview.InvokeRPC("MapData", mapData);
		user.Message(MessageHud.MessageType.Center, "$msg_mapsaved");
		m_writeEffects.Create(base.transform.position, base.transform.rotation);
		return true;
	}

	private void RPC_MapData(long sender, ZPackage pkg)
	{
		if (m_nview.IsOwner())
		{
			byte[] array = pkg.GetArray();
			m_nview.GetZDO().Set(ZDOVars.s_data, array);
		}
	}

	private ZPackage GetMapData(byte[] currentMapData)
	{
		byte[] array = Utils.Compress(Minimap.instance.GetSharedMapData(currentMapData));
		ZLog.Log("Compressed map data:" + array.Length);
		return new ZPackage(array);
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}
}
using System;
using System.Collections.Generic;
using Splatform;
using UnityEngine;

public class MasterClient
{
	private const int statVersion = 2;

	public Action<List<ServerData>> m_onServerList;

	private string m_msHost = "dvoid.noip.me";

	private int m_msPort = 9983;

	private long m_sessionUID;

	private ZConnector2 m_connector;

	private ZSocket2 m_socket;

	private ZRpc m_rpc;

	private bool m_haveServerlist;

	private List<ServerData> m_servers = new List<ServerData>();

	private ZPackage m_registerPkg;

	private float m_sendStatsTimer;

	private int m_serverListRevision;

	private string m_nameFilter = "";

	private static MasterClient m_instance;

	public static MasterClient instance => m_instance;

	public static void Initialize()
	{
		if (m_instance == null)
		{
			m_instance = new MasterClient();
		}
	}

	public MasterClient()
	{
		m_sessionUID = Utils.GenerateUID();
	}

	public void Dispose()
	{
		if (m_socket != null)
		{
			m_socket.Dispose();
		}
		if (m_connector != null)
		{
			m_connector.Dispose();
		}
		if (m_rpc != null)
		{
			m_rpc.Dispose();
		}
		if (m_instance == this)
		{
			m_instance = null;
		}
	}

	public void Update(float dt)
	{
	}

	private void SendStats(float duration)
	{
		ZPackage zPackage = new ZPackage();
		zPackage.Write(2);
		zPackage.Write(m_sessionUID);
		zPackage.Write(Time.time);
		bool flag = Player.m_localPlayer != null;
		zPackage.Write(flag ? duration : 0f);
		bool flag2 = (bool)ZNet.instance && !ZNet.instance.IsServer();
		zPackage.Write(flag2 ? duration : 0f);
		zPackage.Write(Version.CurrentVersion.ToString());
		zPackage.Write(36u);
		bool flag3 = (bool)ZNet.instance && ZNet.instance.IsServer();
		zPackage.Write(flag3);
		if (flag3)
		{
			zPackage.Write(ZNet.instance.GetWorldUID());
			zPackage.Write(duration);
			int num = ZNet.instance.GetPeerConnections();
			if (Player.m_localPlayer != null)
			{
				num++;
			}
			zPackage.Write(num);
			bool data = ZNet.instance.GetZNat() != null && ZNet.instance.GetZNat().GetStatus();
			zPackage.Write(data);
		}
		PlayerProfile playerProfile = ((Game.instance != null) ? Game.instance.GetPlayerProfile() : null);
		if (playerProfile != null)
		{
			zPackage.Write(data: true);
			zPackage.Write(playerProfile.GetPlayerID());
			zPackage.Write(105);
			for (int i = 0; i < 105; i++)
			{
				zPackage.Write(playerProfile.m_playerStats.m_stats[(PlayerStatType)i]);
			}
			zPackage.Write(playerProfile.m_usedCheats);
			zPackage.Write(new DateTimeOffset(playerProfile.m_dateCreated).ToUnixTimeSeconds());
			zPackage.Write(playerProfile.m_knownWorlds.Count);
			foreach (KeyValuePair<string, float> knownWorld in playerProfile.m_knownWorlds)
			{
				zPackage.Write(knownWorld.Key);
				zPackage.Write(knownWorld.Value);
			}
			zPackage.Write(playerProfile.m_knownWorldKeys.Count);
			foreach (KeyValuePair<string, float> knownWorldKey in playerProfile.m_knownWorldKeys)
			{
				zPackage.Write(knownWorldKey.Key);
				zPackage.Write(knownWorldKey.Value);
			}
			zPackage.Write(playerProfile.m_knownCommands.Count);
			foreach (KeyValuePair<string, float> knownCommand in playerProfile.m_knownCommands)
			{
				zPackage.Write(knownCommand.Key);
				zPackage.Write(knownCommand.Value);
			}
			zPackage.Write(playerProfile.m_enemyStats.Count);
			foreach (KeyValuePair<string, float> enemyStat in playerProfile.m_enemyStats)
			{
				zPackage.Write(enemyStat.Key);
				zPackage.Write(enemyStat.Value);
			}
			zPackage.Write(playerProfile.m_itemPickupStats.Count);
			foreach (KeyValuePair<string, float> itemPickupStat in playerProfile.m_itemPickupStats)
			{
				zPackage.Write(itemPickupStat.Key);
				zPackage.Write(itemPickupStat.Value);
			}
			zPackage.Write(playerProfile.m_itemCraftStats.Count);
			foreach (KeyValuePair<string, float> itemCraftStat in playerProfile.m_itemCraftStats)
			{
				zPackage.Write(itemCraftStat.Key);
				zPackage.Write(itemCraftStat.Value);
			}
		}
		else
		{
			zPackage.Write(data: false);
		}
		m_rpc.Invoke("Stats", zPackage);
	}

	public void RegisterServer(string name, string host, int port, bool password, bool upnp, long worldUID, GameVersion gameVersion, uint networkVersion, string[] modifiers)
	{
		m_registerPkg = new ZPackage();
		m_registerPkg.Write(1);
		m_registerPkg.Write(name);
		m_registerPkg.Write(host);
		m_registerPkg.Write(port);
		m_registerPkg.Write(password);
		m_registerPkg.Write(upnp);
		m_registerPkg.Write(worldUID);
		m_registerPkg.Write(gameVersion.ToString());
		m_registerPkg.Write(networkVersion);
		m_registerPkg.Write(StringUtils.EncodeStringListAsString(modifiers));
		if (m_rpc != null)
		{
			m_rpc.Invoke("RegisterServer2", m_registerPkg);
		}
		ZLog.Log("Registering server " + name + "  " + host + ":" + port);
	}

	public void UnregisterServer()
	{
		if (m_registerPkg != null)
		{
			if (m_rpc != null)
			{
				m_rpc.Invoke("UnregisterServer");
			}
			m_registerPkg = null;
		}
	}

	public List<ServerData> GetServers()
	{
		return m_servers;
	}

	public bool GetServers(List<ServerData> servers)
	{
		if (!m_haveServerlist)
		{
			return false;
		}
		servers.Clear();
		servers.AddRange(m_servers);
		return true;
	}

	public void RequestServerlist()
	{
		if (m_rpc != null)
		{
			m_rpc.Invoke("RequestServerlist2");
		}
	}

	private void RPC_ServerList(ZRpc rpc, ZPackage pkg)
	{
		m_haveServerlist = true;
		m_serverListRevision++;
		pkg.ReadInt();
		int num = pkg.ReadInt();
		m_servers.Clear();
		for (int i = 0; i < num; i++)
		{
			string text = pkg.ReadString();
			string text2 = pkg.ReadString();
			int num2 = pkg.ReadInt();
			bool isPasswordProtected = pkg.ReadBool();
			pkg.ReadBool();
			pkg.ReadLong();
			string versionString = pkg.ReadString();
			uint networkVersion = 0u;
			if (GameVersion.TryParseGameVersion(versionString, out var version) && version >= Version.FirstVersionWithNetworkVersion)
			{
				networkVersion = pkg.ReadUInt();
			}
			int playerCount = pkg.ReadInt();
			string[] decodedArray;
			if (version >= Version.FirstVersionWithModifiers)
			{
				StringUtils.TryDecodeStringAsArray(pkg.ReadString(), out decodedArray);
			}
			else
			{
				decodedArray = new string[0];
			}
			ServerJoinData joinData = new ServerJoinData(new ServerJoinDataDedicated(text2 + ":" + num2));
			ServerMatchmakingData matchmakingData = new ServerMatchmakingData(DateTime.UtcNow, text, (uint)playerCount, 10u, PlatformUserID.None, version, networkVersion, null, isPasswordProtected, Platform.Unknown, decodedArray);
			if (m_nameFilter.Length <= 0 || !text.Contains(m_nameFilter))
			{
				m_servers.Add(new ServerData(joinData, matchmakingData));
			}
		}
		if (m_onServerList != null)
		{
			m_onServerList(m_servers);
		}
	}

