using Splatform;

public class MatchmakingManager
{
	private static MatchmakingManager s_instance;

	private Invite? m_pendingInvite;

	public static void Initialize()
	{
		if (s_instance != null)
		{
			ZLog.LogError("MatchmakingManager already initialized!");
		}
		else
		{
			s_instance = new MatchmakingManager();
		}
	}

	private MatchmakingManager()
	{
		IMatchmakingProvider matchmakingProvider = PlatformManager.DistributionPlatform.MatchmakingProvider;
		if (matchmakingProvider == null)
		{
			ZLog.Log("Platform doesn't implement matchmaking! Don't initialize matchmaking manager.");
			s_instance = null;
		}
		else
		{
			matchmakingProvider.AcceptMultiplayerSessionInvite += OnAcceptMultiplayerSessionInvite;
		}
	}

	private void OnAcceptMultiplayerSessionInvite(Invite invite)
	{
		if (m_pendingInvite.HasValue)
		{
			ZLog.Log("Existing pending invite was reset");
		}
		m_pendingInvite = null;
		_ = FejdStartup.instance != null;
		if (Game.instance != null && !Game.instance.IsShuttingDown() && UnifiedPopup.IsAvailable() && Menu.instance != null)
		{
			string header;
			string text;
			switch (invite.m_inviteType)
			{
			case InviteType.Invite:
				header = "$menu_acceptedinvite";
				text = "$menu_logoutprompt";
				break;
			case InviteType.JoinSession:
				header = "$menu_joindifferentserver";
				text = "$menu_logoutprompt";
				break;
			default:
				ZLog.LogError("This part of the code should be unreachable - can't join a game via the invite/join system without having been invited or joined!");
				return;
			}
			m_pendingInvite = invite;
			UnifiedPopup.Push(new YesNoPopup(header, text, delegate
			{
				UnifiedPopup.Pop();
				if (Menu.instance != null)
				{
					Menu.instance.OnLogoutYes();
				}
			}, delegate
			{
				UnifiedPopup.Pop();
				m_pendingInvite = null;
			}));
		}
		else
		{
			m_pendingInvite = invite;
		}
	}

	public static bool TryConsumePendingInvite(out Invite invite)
	{
		if (s_instance == null)
		{
			invite = default(Invite);
			return false;
		}
		if (!s_instance.m_pendingInvite.HasValue)
		{
			invite = default(Invite);
			return false;
		}
		invite = s_instance.m_pendingInvite.Value;
		s_instance.m_pendingInvite = null;
		return true;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class MaterialFader : MonoBehaviour
{
	[Serializable]
	public class FadeProperty
	{
		[Header("Settings")]
		public string m_propertyName;

		public AnimationCurve m_animationCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);

		[Tooltip("Single Vector Channel mode will work on Colors too, if you just want to affect alpha color for example.")]
		public PropertyType m_propertyType;

		[Min(0.1f)]
		public float m_fadeTime = 5f;

		[Min(0f)]
		public float m_delay;

		[NonSerialized]
		public int m_shaderID;

		[Header("Values")]
		[Tooltip("Used for floats and single vector channels")]
		public float m_finalFloatValue;

		public Color m_finalColorValue;

		public Vector3 m_finalVectorValue;

		[Tooltip("Only used for single vector channel mode.")]
		public VectorChannel m_vectorChannel;

		[NonSerialized]
		public float m_startFloatValue;

		[NonSerialized]
		public Color m_startColorValue;

		[NonSerialized]
		public Vector4 m_startVectorValue;

		private float m_fadeTimer;

		private bool m_startedFade;

		private bool m_finished;

		private Material m_originalMaterial;

		public void Initalize(Material mat)
		{
			m_shaderID = Shader.PropertyToID(m_propertyName);
			m_originalMaterial = mat;
		}

		public void Reset()
		{
			m_fadeTimer = 0f;
			m_finished = false;
			m_startedFade = false;
		}

		private void GetMaterialValues(MaterialPropertyBlock propertyBlock)
		{
			m_startedFade = true;
			if (propertyBlock.HasProperty(m_shaderID))
			{
				switch (m_propertyType)
				{
				case PropertyType.Float:
					m_startFloatValue = propertyBlock.GetFloat(m_shaderID);
					break;
				case PropertyType.Color:
					m_startColorValue = propertyBlock.GetColor(m_shaderID);
					break;
				case PropertyType.Vector3:
					m_startVectorValue = propertyBlock.GetVector(m_shaderID);
					break;
				case PropertyType.SingleVectorChannel:
					m_startVectorValue = propertyBlock.GetVector(m_shaderID);
					m_startFloatValue = m_startVectorValue[(int)m_vectorChannel];
					break;
				}
			}
			else
			{
				switch (m_propertyType)
				{
				case PropertyType.Float:
					m_startFloatValue = m_originalMaterial.GetFloat(m_shaderID);
					break;
				case PropertyType.Color:
					m_startColorValue = m_originalMaterial.GetColor(m_shaderID);
					break;
				case PropertyType.Vector3:
					m_startVectorValue = m_originalMaterial.GetVector(m_shaderID);
					break;
				case PropertyType.SingleVectorChannel:
					m_startVectorValue = m_originalMaterial.GetVector(m_shaderID);
					m_startFloatValue = m_startVectorValue[(int)m_vectorChannel];
					break;
				}
			}
		}

		public void Update(float delta, ref MaterialPropertyBlock propertyBlock)
		{
			m_fadeTimer += delta;
			if (!m_finished && !(m_fadeTimer < m_delay))
			{
				if (!m_startedFade)
				{
					GetMaterialValues(propertyBlock);
				}
				float time = Mathf.Clamp01((m_fadeTimer - m_delay) / m_fadeTime);
				time = m_animationCurve.Evaluate(time);
				switch (m_propertyType)
				{
				case PropertyType.Float:
					propertyBlock.SetFloat(m_shaderID, Mathf.Lerp(m_startFloatValue, m_finalFloatValue, time));
					break;
				case PropertyType.Color:
					propertyBlock.SetColor(m_shaderID, Color.Lerp(m_startColorValue, m_finalColorValue, time));
					break;
				case PropertyType.Vector3:
					propertyBlock.SetVector(m_shaderID, Vector3.Lerp(m_startVectorValue, m_finalVectorValue, time));
					break;
				case PropertyType.SingleVectorChannel:
				{
					Vector4 startVectorValue = m_startVectorValue;
					startVectorValue[(int)m_vectorChannel] = Mathf.Lerp(m_startFloatValue, m_finalFloatValue, time);
					propertyBlock.SetVector(m_shaderID, startVectorValue);
					break;
				}
				}
				if (time == 1f)
				{
					m_finished = true;
				}
			}
		}
	}

	[Serializable]
	public enum PropertyType
	{
		Float,
		Color,
		SingleVectorChannel,
		Vector3
	}

	[Serializable]
	public enum VectorChannel
	{
		X,
		Y,
		Z,
		W
	}

	public List<Renderer> m_renderers;

	public bool m_triggerOnAwake = true;

	public List<FadeProperty> m_fadeProperties;

	private MaterialPropertyBlock m_propertyBlock;

	private bool m_started;

	private void Awake()
	{
		if (m_renderers == null)
		{
			m_renderers = new List<Renderer>();
			Renderer[] componentsInChildren = GetComponentsInChildren<Renderer>();
			if (componentsInChildren != null)
			{
				m_renderers.AddRange(componentsInChildren);
			}
			Renderer component = GetComponent<Renderer>();
			if (component != null)
			{
				m_renderers.Add(component);
			}
		}
		if (m_renderers.Count == 0)
		{
			ZLog.LogError("No MeshRenderer components assigned to MaterialFader!");
		}
		foreach (FadeProperty fadeProperty in m_fadeProperties)
		{
			fadeProperty.Initalize(m_renderers[0].material);
		}
		m_propertyBlock = new MaterialPropertyBlock();
		if (m_renderers[0].HasPropertyBlock())
		{
			m_renderers[0].GetPropertyBlock(m_propertyBlock);
		}
		m_started = m_triggerOnAwake;
	}

	public void TriggerFade()
	{
		if (m_started)
		{
			foreach (FadeProperty fadeProperty in m_fadeProperties)
			{
				fadeProperty.Reset();
			}
		}
		m_started = true;
	}

	private void Update()
	{
		if (!m_started)
		{
			return;
		}
		foreach (FadeProperty fadeProperty in m_fadeProperties)
		{
			fadeProperty.Update(Time.deltaTime, ref m_propertyBlock);
		}
		foreach (Renderer renderer in m_renderers)
		{
			renderer.SetPropertyBlock(m_propertyBlock);
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class MaterialMan : MonoBehaviour
{
	private class PropertyContainer
	{
		private List<Renderer> m_assignedRenderers = new List<Renderer>();

		private Dictionary<int, ShaderPropertyBase> m_shaderProperties = new Dictionary<int, ShaderPropertyBase>();

		private MaterialPropertyBlock m_propertyBlock;

		public Action<PropertyContainer> MarkDirty;

		public PropertyContainer(GameObject go, MaterialPropertyBlock block)
		{
			MeshRenderer[] componentsInChildren = go.GetComponentsInChildren<MeshRenderer>(includeInactive: true);
			if (componentsInChildren != null)
			{
				m_assignedRenderers.AddRange(componentsInChildren);
			}
			SkinnedMeshRenderer[] componentsInChildren2 = go.GetComponentsInChildren<SkinnedMeshRenderer>(includeInactive: true);
			if (componentsInChildren2 != null)
			{
				m_assignedRenderers.AddRange(componentsInChildren2);
			}
			m_propertyBlock = block;
		}

		public void UpdateBlock()
		{
			m_propertyBlock.Clear();
			foreach (KeyValuePair<int, ShaderPropertyBase> shaderProperty in m_shaderProperties)
			{
				if (shaderProperty.Value.PropertyType == typeof(int))
				{
					m_propertyBlock.SetInt(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<int>).Get());
				}
				else if (shaderProperty.Value.PropertyType == typeof(float))
				{
					m_propertyBlock.SetFloat(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<float>).Get());
				}
				else if (shaderProperty.Value.PropertyType == typeof(float[]))
				{
					m_propertyBlock.SetFloatArray(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<float[]>).Get());
				}
				else if (shaderProperty.Value.PropertyType == typeof(Color))
				{
					m_propertyBlock.SetColor(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<Color>).Get());
				}
				else if (shaderProperty.Value.PropertyType == typeof(Vector4))
				{
					m_propertyBlock.SetVector(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<Vector4>).Get());
				}
				else if (shaderProperty.Value.PropertyType == typeof(Vector4[]))
				{
					m_propertyBlock.SetVectorArray(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<Vector4[]>).Get());
				}
				else if (shaderProperty.Value.PropertyType == typeof(Vector3))
				{
					m_propertyBlock.SetVector(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<Vector3>).Get());
				}
				else if (shaderProperty.Value.PropertyType == typeof(Vector2))
				{
					m_propertyBlock.SetVector(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<Vector2>).Get());
				}
				else if (shaderProperty.Value.PropertyType == typeof(ComputeBuffer))
				{
					m_propertyBlock.SetBuffer(shaderProperty.Key, (shaderProperty.Value as ShaderProperty<ComputeBuffer>).Get());
				}
			}
			for (int num = m_assignedRenderers.Count - 1; num >= 0; num--)
			{
				if (m_assignedRenderers[num] == null)
				{
					m_assignedRenderers.RemoveAt(num);
				}
				else
				{
					m_assignedRenderers[num].SetPropertyBlock(m_propertyBlock);
				}
			}
		}

		public void ResetValue(int nameID)
		{
			m_shaderProperties.Remove(nameID);
			MarkDirty?.Invoke(this);
		}

		public void SetValue<T>(int nameID, T value)
		{
			if (m_shaderProperties.ContainsKey(nameID))
			{
				(m_shaderProperties[nameID] as ShaderProperty<T>).Set(value);
			}
			else
			{
				m_shaderProperties.Add(nameID, new ShaderProperty<T>(nameID, value));
			}
			MarkDirty?.Invoke(this);
		}
	}

	private abstract class ShaderPropertyBase
	{
		public readonly int NameID;

		public abstract Type PropertyType { get; }

		protected ShaderPropertyBase(int nameID)
		{
			NameID = nameID;
		}
	}

	private class ShaderProperty<T> : ShaderPropertyBase
	{
		private T _value;

		public override Type PropertyType => typeof(T);

		public ShaderProperty(int nameID, T value)
			: base(nameID)
		{
			_value = value;
		}

		public void Set(T value)
		{
			_value = value;
		}

		public T Get()
		{
			return _value;
		}
	}

	private static MaterialMan s_instance;

	private Dictionary<int, PropertyContainer> m_blocks = new Dictionary<int, PropertyContainer>();

	private List<PropertyContainer> m_containersToUpdate = new List<PropertyContainer>();

	private MaterialPropertyBlock m_propertyBlock;

	public static MaterialMan instance => s_instance;

	private void Awake()
	{
		if (s_instance == null)
		{
			s_instance = this;
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	private void Start()
	{
		m_propertyBlock = new MaterialPropertyBlock();
	}

	private void Update()
	{
		for (int num = m_containersToUpdate.Count - 1; num >= 0; num--)
		{
			m_containersToUpdate[num].UpdateBlock();
			m_containersToUpdate.RemoveAt(num);
		}
	}

	private void RegisterRenderers(GameObject gameObject)
	{
		if (!m_blocks.ContainsKey(gameObject.GetInstanceID()))
		{
			gameObject.AddComponent<MaterialManNotifier>();
			PropertyContainer propertyContainer = new PropertyContainer(gameObject, m_propertyBlock);
			propertyContainer.MarkDirty = (Action<PropertyContainer>)Delegate.Combine(propertyContainer.MarkDirty, new Action<PropertyContainer>(QueuePropertyUpdate));
			m_blocks.Add(gameObject.GetInstanceID(), propertyContainer);
		}
	}

	public void UnregisterRenderers(GameObject gameObject)
	{
		if (!m_blocks.TryGetValue(gameObject.GetInstanceID(), out var value))
		{
			ZLog.LogError("Can't unregister renderer for " + gameObject.name);
			return;
		}
		PropertyContainer propertyContainer = value;
		propertyContainer.MarkDirty = (Action<PropertyContainer>)Delegate.Remove(propertyContainer.MarkDirty, new Action<PropertyContainer>(QueuePropertyUpdate));
		if (m_containersToUpdate.Contains(value))
		{
			m_containersToUpdate.Remove(value);
		}
		m_blocks.Remove(gameObject.GetInstanceID());
	}

	private void QueuePropertyUpdate(PropertyContainer p)
	{
		if (!m_containersToUpdate.Contains(p))
		{
			m_containersToUpdate.Add(p);
		}
	}

	public void SetValue<T>(GameObject go, int nameID, T value)
	{
		RegisterRenderers(go);
		m_blocks[go.GetInstanceID()].SetValue(nameID, value);
	}

	public void ResetValue(GameObject go, int nameID)
	{
		if (m_blocks.ContainsKey(go.GetInstanceID()))
		{
			m_blocks[go.GetInstanceID()].ResetValue(nameID);
		}
	}
}
