using NetworkingUtils;
using UnityEngine;

public class MultiBackendMatchmaking : MonoBehaviour
{
	private static MultiBackendMatchmaking s_instance;

	private uint m_referenceCounter;

	private List<IMatchmakingBackend> m_backends;

	public readonly Dictionary<ServerJoinData, ServerNameAtTimePoint> m_serverNames = new Dictionary<ServerJoinData, ServerNameAtTimePoint>();

	public readonly DnsResolver m_dnsResolver = new DnsResolver();

	public static MultiBackendMatchmaking Instance => s_instance;

	public IReadOnlyList<IMatchmakingBackend> Backends => m_backends;

	public static PlayFabMatchmaking PlayFabBackend
	{
		get
		{
			if ((object)s_instance == null)
			{
				ZLog.LogError("s_instance was null!");
				return null;
			}
			return s_instance.m_backends[0] as PlayFabMatchmaking;
		}
	}

	public static void Hold()
	{
		if ((object)s_instance == null)
		{
			GameObject obj = new GameObject("MultiBackendMatchmaking", typeof(MultiBackendMatchmaking));
			s_instance = obj.GetComponent<MultiBackendMatchmaking>();
			UnityEngine.Object.DontDestroyOnLoad(obj);
		}
		s_instance.m_referenceCounter++;
	}

	public static void Release()
	{
		if (!(s_instance == null))
		{
			s_instance.m_referenceCounter--;
			if (s_instance.m_referenceCounter == 0)
			{
				UnityEngine.Object.Destroy(s_instance.gameObject);
				s_instance = null;
			}
		}
	}

	private MultiBackendMatchmaking()
	{
		m_backends = new List<IMatchmakingBackend>
		{
			new PlayFabMatchmaking(),
			new SteamworksMatchmaking()
		};
	}

	private void OnDestroy()
	{
		for (int i = 0; i < m_backends.Count; i++)
		{
			m_backends[i].Dispose();
		}
		m_backends.Clear();
	}

	private void Update()
	{
		for (int i = 0; i < m_backends.Count; i++)
		{
			m_backends[i].Tick();
		}
	}

	public static ServerMatchmakingData GetServerMatchmakingData(ServerJoinData server, DateTime newerThanUtc = default(DateTime))
	{
		if ((object)s_instance == null)
		{
			ZLog.LogError(string.Format("{0} was null! Couldn't get server matchmaking data for server {1}, returning {2} as a fallback.", "s_instance", server, "None"));
			return ServerMatchmakingData.None;
		}
		if (!server.IsValid)
		{
			throw new ArgumentException("Server has to be valid!");
		}
		int num = 0;
		int num2 = 0;
		ServerMatchmakingData result = ServerMatchmakingData.None;
		for (int i = 0; i < s_instance.m_backends.Count; i++)
		{
			if (!s_instance.m_backends[i].IsAvailable)
			{
				continue;
			}
			num++;
			ServerMatchmakingData serverMatchmakingData = s_instance.m_backends[i].GetServerMatchmakingData(server, newerThanUtc);
			if (serverMatchmakingData.IsValid)
			{
				num2++;
				if (!result.IsValid || result.m_onlineStatus < serverMatchmakingData.m_onlineStatus || (serverMatchmakingData.m_onlineStatus.IsOnline() && serverMatchmakingData.m_timestampUtc <= result.m_timestampUtc))
				{
					result = serverMatchmakingData;
				}
				if (result.m_onlineStatus.IsOnline())
				{
					break;
				}
			}
		}
		if (!result.m_onlineStatus.IsOnline() && num2 < num)
		{
			return ServerMatchmakingData.None;
		}
		return result;
	}

	public static string GetServerName(ServerJoinData server)
	{
		if (!TryGetServerName(server, out var serverName))
		{
			return server.ToString();
		}
		return serverName;
	}

	public static bool TryGetServerName(ServerJoinData server, out string serverName)
	{
		ServerNameAtTimePoint serverNameAtTimePoint;
		ServerNameSource source;
		bool result = TryGetServerName(server, out serverNameAtTimePoint, out source);
		serverName = serverNameAtTimePoint.m_name;
		return result;
	}

	public static bool TryGetServerName(ServerJoinData server, out ServerNameAtTimePoint serverNameAtTimePoint, out ServerNameSource source)
	{
		if (!server.IsValid)
		{
			throw new ArgumentException("Server has to be valid!");
		}
		source = ServerNameSource.ManuallySet;
		serverNameAtTimePoint = default(ServerNameAtTimePoint);
		if ((object)s_instance == null)
		{
			ZLog.LogError(string.Format("{0} was null! Couldn't get server name for server {1}.", "s_instance", server));
			return false;
		}
		if (s_instance.m_serverNames.TryGetValue(server, out serverNameAtTimePoint))
		{
			source = ServerNameSource.ManuallySet;
		}
		else
		{
			serverNameAtTimePoint = ServerNameAtTimePoint.None;
		}
		for (int i = 0; i < s_instance.m_backends.Count; i++)
		{
			ServerMatchmakingData serverMatchmakingData = s_instance.m_backends[i].GetServerMatchmakingData(server);
			if (serverMatchmakingData.m_onlineStatus.IsOnline() && !(serverMatchmakingData.m_timestampUtc <= serverNameAtTimePoint.m_timestampUtc))
			{
				serverNameAtTimePoint = new ServerNameAtTimePoint(serverMatchmakingData.m_serverName, serverMatchmakingData.m_timestampUtc);
				source = ServerNameSource.Matchmaking;
			}
		}
		return serverNameAtTimePoint.m_name != null;
	}

	public static void SetServerName(ServerJoinData server, ServerNameAtTimePoint nameAndFileTimestamp)
	{
		ServerNameAtTimePoint value;
		if ((object)s_instance == null)
		{
			ZLog.LogError(string.Format("{0} was null! Couldn't set server name for server {1}, doing nothing as a fallback.", "s_instance", server));
		}
		else if (!s_instance.m_serverNames.TryGetValue(server, out value) || !(value.m_timestampUtc > nameAndFileTimestamp.m_timestampUtc))
		{
			s_instance.m_serverNames[server] = nameAndFileTimestamp;
		}
	}

	public static void GetServerIPAsync(ServerJoinDataDedicated server, ResolveDomainCompletedHandler completedHandler)
	{
		if ((object)s_instance == null)
		{
			ZLog.LogError("s_instance was null! If the IP address is not already part of the join data, the operation will fail.");
		}
		if (server.TryGetIPAddress(out var address))
		{
			completedHandler?.Invoke(succeeded: true, address);
		}
		else if ((object)s_instance == null)
		{
			completedHandler?.Invoke(succeeded: false, null);
		}
		else
		{
			s_instance.m_dnsResolver.ResolveDomainNameAsync(server.m_host, completedHandler);
		}
	}

	public static bool GetServerIPCached(ServerJoinDataDedicated server, out IPv6Address? address)
	{
		if ((object)s_instance == null)
		{
			ZLog.LogError("s_instance was null! If the IP address is not already part of the join data, the operation will fail.");
		}
		if (server.TryGetIPAddress(out var address2))
		{
			address = address2;
			return true;
		}
		if ((object)s_instance == null)
		{
			address = null;
			return false;
		}
		return s_instance.m_dnsResolver.ResolveDomainName(server.m_host, out address, DnsResolveFlags.CacheOnly);
	}

	public static bool ServerIPAddressIsKnown(ServerJoinDataDedicated server)
	{
		IPv6Address? address;
		return GetServerIPCached(server, out address);
	}
}
using UnityEngine;

public class MusicLocation : MonoBehaviour
{
	private float volume;

	public bool m_addRadiusFromLocation = true;

	public float m_radius = 10f;

	public bool m_oneTime = true;

	public bool m_notIfEnemies = true;

	public bool m_forceFade;

	private ZNetView m_nview;

	private AudioSource m_audioSource;

	private float m_baseVolume;

	private bool m_blockLoopAndFade;

	private void Awake()
	{
		m_audioSource = GetComponent<AudioSource>();
		m_baseVolume = m_audioSource.volume;
		m_nview = GetComponent<ZNetView>();
		if ((bool)m_nview)
		{
			m_nview.Register("SetPlayed", SetPlayed);
		}
		if (m_addRadiusFromLocation)
		{
			Location componentInParent = GetComponentInParent<Location>();
			if ((object)componentInParent != null)
			{
				m_radius += componentInParent.GetMaxRadius();
			}
		}
	}

	private void Update()
	{
		if (Player.m_localPlayer == null)
		{
			return;
		}
		float p_X = Vector3.Distance(base.transform.position, Player.m_localPlayer.transform.position);
		float target = 1f - Utils.SmoothStep(m_radius * 0.5f, m_radius, p_X);
		volume = Mathf.MoveTowards(volume, target, Time.deltaTime);
		float num = volume * m_baseVolume * MusicMan.m_masterMusicVolume;
		if (volume > 0f && !m_audioSource.isPlaying && !m_blockLoopAndFade)
		{
			if ((m_oneTime && HasPlayed()) || (m_notIfEnemies && BaseAI.HaveEnemyInRange(Player.m_localPlayer, base.transform.position, m_radius)))
			{
				return;
			}
			m_audioSource.time = 0f;
			m_audioSource.Play();
		}
		if (!Settings.ContinousMusic && m_audioSource.loop)
		{
			m_audioSource.loop = false;
			m_blockLoopAndFade = true;
		}
		if (m_blockLoopAndFade || m_forceFade)
		{
			float num2 = m_audioSource.time - m_audioSource.clip.length + 1.5f;
			if (num2 > 0f)
			{
				num *= 1f - num2 / 1.5f;
			}
			if (Terminal.m_showTests)
			{
				Terminal.m_testList["Music location fade"] = num2 + " " + (1f - num2 / 1.5f);
			}
		}
		m_audioSource.volume = num;
		if (m_blockLoopAndFade && volume <= 0f)
		{
			m_blockLoopAndFade = false;
			m_audioSource.loop = true;
		}
		if (Terminal.m_showTests && m_audioSource.isPlaying)
		{
			Terminal.m_testList["Music location current"] = m_audioSource.name;
			Terminal.m_testList["Music location vol / volume"] = num + " / " + volume;
			if (ZInput.GetKeyDown(KeyCode.N) && ZInput.GetKey(KeyCode.LeftShift))
			{
				m_audioSource.time = m_audioSource.clip.length - 4f;
			}
		}
		if (m_oneTime && volume > 0f && m_audioSource.time > m_audioSource.clip.length * 0.75f && !HasPlayed())
		{
			SetPlayed();
		}
	}

	private void SetPlayed()
	{
		m_nview.InvokeRPC("SetPlayed");
	}

	private void SetPlayed(long sender)
	{
		if (m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_played, value: true);
			ZLog.Log("Setting location music as played");
		}
	}

	private bool HasPlayed()
	{
		return m_nview.GetZDO().GetBool(ZDOVars.s_played);
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = new Color(0.6f, 0.8f, 0.8f, 0.5f);
		Gizmos.DrawWireSphere(base.transform.position, m_radius);
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Audio;

public class MusicMan : MonoBehaviour
{
	[Serializable]
	public class NamedMusic
	{
		public string m_name = "";

		public AudioClip[] m_clips;

		public float m_volume = 1f;

		public float m_fadeInTime = 3f;

		public bool m_alwaysFadeout;

		public bool m_loop;

		public bool m_resume;

		public bool m_enabled = true;

		public bool m_ambientMusic;

		[NonSerialized]
		public int m_savedPlaybackPos;

		[NonSerialized]
		public float m_lastPlayedTime;
	}

	private string m_triggeredMusic = "";

	private static MusicMan m_instance;

	public static float m_masterMusicVolume = 1f;

	public AudioMixerGroup m_musicMixer;

	public List<NamedMusic> m_music = new List<NamedMusic>();

	public float m_musicResetNonContinous = 120f;

	private readonly Dictionary<int, NamedMusic> m_musicHashes = new Dictionary<int, NamedMusic>();

	[Header("Combat")]
	public float m_combatMusicTimeout = 4f;

	[Header("Sailing")]
	public float m_sailMusicShipSpeedThreshold = 3f;

	public float m_sailMusicMinSailTime = 20f;

	[Header("Ambient music")]
	public float m_randomMusicIntervalMin = 300f;

	public float m_randomMusicIntervalMax = 500f;

	private NamedMusic m_queuedMusic;

	private NamedMusic m_currentMusic;

	private NamedMusic m_lastStartedMusic;

	private float m_musicVolume = 1f;

	private float m_musicFadeTime = 3f;

	private bool m_alwaysFadeout;

	private bool m_stopMusic;

	private string m_randomEventMusic;

	private float m_lastAmbientMusicTime;

	private float m_randomAmbientInterval;

	private string m_triggerMusic;

	private string m_locationMusic;

	public string m_lastLocationMusic;

	private DateTime m_lastLocationMusicChange;

	public int m_repeatLocationMusicResetSeconds = 300;

	private float m_combatTimer;

	private float m_resetMusicTimer;

	private AudioSource m_musicSource;

	private float m_currentMusicVol;

	public float m_currentMusicVolMax = 1f;

	private float m_sailDuration;

	private float m_notSailDuration;

	private float m_musicOnTopDuckVolume;

	private const string c_Duckmusic = "Music_ontop_ducking";

	public static MusicMan instance => m_instance;

	private void Awake()
	{
		if ((bool)m_instance)
		{
			return;
		}
		m_instance = this;
		GameObject gameObject = new GameObject("music");
		gameObject.transform.SetParent(base.transform);
		m_musicSource = gameObject.AddComponent<AudioSource>();
		m_musicSource.loop = true;
		m_musicSource.spatialBlend = 0f;
		m_musicSource.outputAudioMixerGroup = m_musicMixer;
		m_musicSource.priority = 0;
		m_musicSource.bypassReverbZones = true;
		m_randomAmbientInterval = UnityEngine.Random.Range(m_randomMusicIntervalMin, m_randomMusicIntervalMax);
		m_masterMusicVolume = PlatformPrefs.GetFloat("MusicVolume", 1f);
		ApplySettings();
		foreach (NamedMusic item in m_music)
		{
			AudioClip[] clips = item.m_clips;
			foreach (AudioClip audioClip in clips)
			{
				if (audioClip == null || !audioClip)
				{
					item.m_enabled = false;
					ZLog.LogWarning("Missing audio clip in music " + item.m_name);
					break;
				}
			}
		}
		foreach (NamedMusic item2 in m_music)
		{
			if (item2.m_enabled && item2.m_clips.Length != 0 && item2.m_clips[0] != null)
			{
				m_musicHashes.Add(item2.m_name.GetStableHashCode(), item2);
			}
		}
	}

	public void ApplySettings()
	{
		foreach (NamedMusic item in m_music)
		{
			if (item.m_ambientMusic)
			{
				item.m_loop = Settings.ContinousMusic;
				if (!Settings.ContinousMusic && GetCurrentMusic() == item.m_name && m_musicSource.loop)
				{
					ZLog.Log("Stopping looping music because continous music is disabled");
					StopMusic();
				}
			}
		}
	}

	private void OnDestroy()
	{
		if (m_instance == this)
		{
			m_instance = null;
		}
	}

	private void Update()
	{
		if (!(m_instance != this))
		{
			float deltaTime = Time.deltaTime;
			UpdateCurrentMusic(deltaTime);
			UpdateCombatMusic(deltaTime);
			m_currentMusicVolMax = MusicVolume.UpdateProximityVolumes(m_musicSource);
			UpdateMusic(deltaTime);
		}
	}

	private void UpdateCurrentMusic(float dt)
	{
		string currentMusic = GetCurrentMusic();
		if (Game.instance != null)
		{
			if (Game.instance.InIntro() || ((bool)Player.m_localPlayer && Player.m_localPlayer.InIntro()))
			{
				StartMusic("intro");
				return;
			}
			if (currentMusic == "intro")
			{
				StopMusic();
			}
			if (Player.m_localPlayer == null)
			{
				StartMusic("respawn");
				return;
			}
			if (currentMusic == "respawn")
			{
				StopMusic();
			}
		}
		float target = ((m_randomEventMusic == null) ? 0f : (-80f));
		m_musicOnTopDuckVolume = Mathf.MoveTowards(m_musicOnTopDuckVolume, target, 80f * Time.deltaTime);
		m_musicMixer.audioMixer.SetFloat("Music_ontop_ducking", m_musicOnTopDuckVolume);
		if (!HandleEventMusic(currentMusic) && !HandleLocationMusic(currentMusic) && !HandleSailingMusic(dt, currentMusic) && !HandleTriggerMusic(currentMusic))
		{
			HandleEnvironmentMusic(dt, currentMusic);
		}
	}

	private bool HandleEnvironmentMusic(float dt, string currentMusic)
	{
		if (!EnvMan.instance)
		{
			return false;
		}
		NamedMusic environmentMusic = GetEnvironmentMusic();
		string currentMusic2 = GetCurrentMusic();
		if (environmentMusic == null || (m_currentMusic != null && environmentMusic.m_name != currentMusic2))
		{
			StopMusic();
			return true;
		}
		if (environmentMusic.m_name == currentMusic2)
		{
			return true;
		}
		if (!environmentMusic.m_loop)
		{
			if (Time.time - m_lastAmbientMusicTime < m_randomAmbientInterval)
			{
				return false;
			}
			m_randomAmbientInterval = UnityEngine.Random.Range(m_randomMusicIntervalMin, m_randomMusicIntervalMax);
			m_lastAmbientMusicTime = Time.time;
			ZLog.Log("Environment music starting at random ambient interval");
		}
		StartMusic(environmentMusic);
		return true;
	}

	private NamedMusic GetEnvironmentMusic()
	{
		string text = null;
		text = ((!Player.m_localPlayer || !Player.m_localPlayer.IsSafeInHome()) ? EnvMan.instance.GetAmbientMusic() : "home");
		return FindMusic(text);
	}

	private bool HandleTriggerMusic(string currentMusic)
	{
		if (m_triggerMusic != null)
		{
			StartMusic(m_triggerMusic);
			m_triggeredMusic = m_triggerMusic;
			m_triggerMusic = null;
			return true;
		}
		if (m_triggeredMusic != null)
		{
			if (currentMusic == m_triggeredMusic)
			{
				return true;
			}
			m_triggeredMusic = null;
		}
		return false;
	}

	public void LocationMusic(string name)
	{
		m_locationMusic = name;
	}

	private bool HandleLocationMusic(string currentMusic)
	{
		if (m_lastLocationMusic != null && DateTime.Now > m_lastLocationMusicChange + TimeSpan.FromSeconds(m_repeatLocationMusicResetSeconds))
		{
			m_lastLocationMusic = null;
			m_lastLocationMusicChange = DateTime.Now;
		}
		if (m_locationMusic != null)
		{
			if (currentMusic == m_locationMusic && !m_musicSource.isPlaying)
			{
				m_locationMusic = null;
				return false;
			}
			if (currentMusic != m_locationMusic)
			{
				m_lastLocationMusicChange = DateTime.Now;
			}
			if (StartMusic(m_locationMusic))
			{
				m_lastLocationMusic = m_locationMusic;
			}
			else
			{
				ZLog.Log("Location music missing: " + m_locationMusic);
				m_locationMusic = null;
			}
			return true;
		}
		return false;
	}

	private bool HandleEventMusic(string currentMusic)
	{
		if ((bool)RandEventSystem.instance)
		{
			string musicOverride = RandEventSystem.instance.GetMusicOverride();
			if (musicOverride != null)
			{
				StartMusic(musicOverride);
				m_randomEventMusic = musicOverride;
				return true;
			}
			if (currentMusic == m_randomEventMusic)
			{
				m_randomEventMusic = null;
				StopMusic();
			}
		}
		return false;
	}

	private bool HandleCombatMusic(string currentMusic)
	{
		if (InCombat())
		{
			StartMusic("combat");
			return true;
		}
		if (currentMusic == "combat")
		{
			StopMusic();
		}
		return false;
	}

	private bool HandleSailingMusic(float dt, string currentMusic)
	{
		if (IsSailing())
		{
			m_notSailDuration = 0f;
			m_sailDuration += dt;
			if (m_sailDuration > m_sailMusicMinSailTime)
			{
				StartMusic(GetSailingMusic());
				return true;
			}
		}
		else
		{
			m_sailDuration = 0f;
			m_notSailDuration += dt;
			if (m_notSailDuration > m_sailMusicMinSailTime / 2f && currentMusic == GetSailingMusic() && currentMusic != EnvMan.instance.GetAmbientMusic())
			{
				StopMusic();
			}
		}
		return false;
	}

	public string GetSailingMusic()
	{
		if ((bool)Player.m_localPlayer && Player.m_localPlayer.GetCurrentBiome() == Heightmap.Biome.AshLands)
		{
			return "sailing_ashlands";
		}
		return "sailing";
	}

	private bool IsSailing()
	{
		if (!Player.m_localPlayer)
		{
			return false;
		}
		Ship localShip = Ship.GetLocalShip();
		if ((bool)localShip && localShip.GetSpeed() > m_sailMusicShipSpeedThreshold)
		{
			return true;
		}
		return false;
	}

	private void UpdateMusic(float dt)
	{
		if (m_queuedMusic != null || m_stopMusic)
		{
			if (!m_musicSource.isPlaying || m_currentMusicVol <= 0f)
			{
				if (m_musicSource.isPlaying && m_currentMusic != null && m_currentMusic.m_loop && m_currentMusic.m_resume)
				{
					m_currentMusic.m_lastPlayedTime = Time.time;
					m_currentMusic.m_savedPlaybackPos = m_musicSource.timeSamples;
					ZLog.Log("Stopped music " + m_currentMusic.m_name + " at " + m_currentMusic.m_savedPlaybackPos);
				}
				m_musicSource.Stop();
				m_stopMusic = false;
				m_currentMusic = null;
				if (m_queuedMusic != null)
				{
					m_musicSource.clip = m_queuedMusic.m_clips[UnityEngine.Random.Range(0, m_queuedMusic.m_clips.Length)];
					m_musicSource.loop = m_queuedMusic.m_loop;
					m_musicSource.volume = 0f;
					m_musicSource.timeSamples = 0;
					m_musicSource.Play();
					if (m_queuedMusic.m_loop && m_queuedMusic.m_resume && Time.time - m_queuedMusic.m_lastPlayedTime < m_musicSource.clip.length * 2f)
					{
						m_musicSource.timeSamples = m_queuedMusic.m_savedPlaybackPos;
						ZLog.Log("Resumed music " + m_queuedMusic.m_name + " at " + m_queuedMusic.m_savedPlaybackPos);
					}
					m_currentMusicVol = 0f;
					m_musicVolume = m_queuedMusic.m_volume;
					m_musicFadeTime = m_queuedMusic.m_fadeInTime;
					m_alwaysFadeout = m_queuedMusic.m_alwaysFadeout;
					m_currentMusic = m_queuedMusic;
					m_queuedMusic = null;
				}
			}
			else
			{
				float num = ((m_queuedMusic != null) ? Mathf.Min(m_queuedMusic.m_fadeInTime, m_musicFadeTime) : m_musicFadeTime);
				m_currentMusicVol = Mathf.MoveTowards(m_currentMusicVol, 0f, dt / num);
				m_musicSource.volume = Utils.SmoothStep(0f, 1f, m_currentMusicVol) * m_musicVolume * m_masterMusicVolume;
			}
		}
		else if (m_musicSource.isPlaying)
		{
			float num2 = m_musicSource.clip.length - m_musicSource.time;
			if (m_alwaysFadeout && !m_musicSource.loop && num2 < m_musicFadeTime)
			{
				m_currentMusicVol = Mathf.MoveTowards(m_currentMusicVol, 0f, dt / m_musicFadeTime);
				m_musicSource.volume = Utils.SmoothStep(0f, 1f, m_currentMusicVol) * m_musicVolume * m_masterMusicVolume;
			}
			else
			{
				m_currentMusicVol = Mathf.MoveTowards(m_currentMusicVol, m_currentMusicVolMax, dt / m_musicFadeTime);
				m_musicSource.volume = Utils.SmoothStep(0f, 1f, m_currentMusicVol) * m_musicVolume * m_masterMusicVolume;
			}
			if (!Settings.ContinousMusic && num2 < m_musicFadeTime)
			{
				StopMusic();
				ZLog.Log("Music stopped after finishing, because continous music is disabled");
			}
		}
		else if (m_currentMusic != null && !m_musicSource.isPlaying)
		{
			m_currentMusic = null;
		}
		if (m_resetMusicTimer > 0f)
		{
			m_resetMusicTimer -= dt;
		}
		if (Terminal.m_showTests)
		{
			Terminal.m_testList["Music current"] = ((m_currentMusic == null) ? "NULL" : m_currentMusic.m_name);
			Terminal.m_testList["Music last started"] = ((m_lastStartedMusic == null) ? "NULL" : m_lastStartedMusic.m_name);
			Terminal.m_testList["Music queued"] = ((m_queuedMusic == null) ? "NULL" : m_queuedMusic.m_name);
			Terminal.m_testList["Music stopping"] = m_stopMusic.ToString();
			Terminal.m_testList["Music reset non continous"] = $"{m_resetMusicTimer} / {m_musicResetNonContinous}";
			if (ZInput.GetKeyDown(KeyCode.N) && ZInput.GetKey(KeyCode.LeftShift) && m_musicSource != null && m_musicSource.isPlaying)
			{
				m_musicSource.time = m_musicSource.clip.length - 4f;
			}
		}
	}

	private void UpdateCombatMusic(float dt)
	{
		if (m_combatTimer > 0f)
		{
			m_combatTimer -= Time.deltaTime;
		}
	}

	public void ResetCombatTimer()
	{
		m_combatTimer = m_combatMusicTimeout;
	}

	private bool InCombat()
	{
		return m_combatTimer > 0f;
	}

	public void TriggerMusic(string name)
	{
		m_triggerMusic = name;
	}

	private bool StartMusic(string name)
	{
		if (GetCurrentMusic() == name)
		{
			return true;
		}
		NamedMusic music = FindMusic(name);
		return StartMusic(music);
	}

	private bool StartMusic(NamedMusic music)
	{
		if (music != null && GetCurrentMusic() == music.m_name)
		{
			return true;
		}
		if (music == m_lastStartedMusic && !Settings.ContinousMusic && m_resetMusicTimer > 0f)
		{
			return false;
		}
		m_lastStartedMusic = music;
		m_resetMusicTimer = m_musicResetNonContinous + ((music != null && music.m_clips.Length != 0) ? music.m_clips[0].length : 0f);
		if (music != null)
		{
			m_queuedMusic = music;
			m_stopMusic = false;
			ZLog.Log("Starting music " + music.m_name);
			return true;
		}
		StopMusic();
		return false;
	}

	private NamedMusic FindMusic(string musicName)
	{
		if (string.IsNullOrEmpty(musicName))
		{
			return null;
		}
		return m_musicHashes.GetValueOrDefault(musicName.GetStableHashCode());
	}

	public bool IsPlaying()
	{
		return m_musicSource.isPlaying;
	}

	private string GetCurrentMusic()
	{
		if (m_stopMusic)
		{
			return "";
		}
		if (m_queuedMusic != null)
		{
			return m_queuedMusic.m_name;
		}
		if (m_currentMusic != null)
		{
			return m_currentMusic.m_name;
		}
		return "";
	}

	private void StopMusic()
	{
		m_queuedMusic = null;
		m_stopMusic = true;
	}

	public void Reset()
	{
		StopMusic();
		m_combatTimer = 0f;
		m_randomEventMusic = null;
		m_triggerMusic = null;
		m_locationMusic = null;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class MusicVolume : MonoBehaviour
{
	private ZNetView m_nview;

	public static List<MusicVolume> m_proximityMusicVolumes = new List<MusicVolume>();

	private static MusicVolume m_lastProximityVolume;

	private static List<MusicVolume> m_close = new List<MusicVolume>();

	public bool m_addRadiusFromLocation = true;

	public float m_radius = 10f;

	public float m_outerRadiusExtra = 0.5f;

	public float m_surroundingPlayersAdditionalRadius = 50f;

	public Bounds m_boundsInner;

	[Tooltip("Takes dimension from the room it's a part of and sets bounds to it's size.")]
	public Room m_sizeFromRoom;

	[Header("Music")]
	public string m_musicName = "";

	public float m_musicChance = 0.7f;

	[Tooltip("If the music can play again before playing a different location music first.")]
	public bool m_musicCanRepeat = true;

	public bool m_loopMusic;

	public bool m_stopMusicOnExit;

	public int m_maxPlaysPerActivation;

	[Tooltip("Makes the music fade by distance between inner/outer bounds. With this enabled loop, repeat, stoponexit, chance, etc is ignored.")]
	public bool m_fadeByProximity;

	[HideInInspector]
	public int m_PlayCount;

	private double m_lastEnterCheck;

	private bool m_lastWasInside;

	private bool m_lastWasInsideWide;

	private bool m_isLooping;

	private float m_proximity;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		if ((bool)m_nview)
		{
			m_PlayCount = m_nview.GetZDO().GetInt(ZDOVars.s_plays);
			m_nview.Register("RPC_PlayMusic", RPC_PlayMusic);
		}
		if (m_addRadiusFromLocation)
		{
			Location componentInParent = GetComponentInParent<Location>();
			if ((object)componentInParent != null)
			{
				m_radius += componentInParent.GetMaxRadius();
			}
		}
		if (m_fadeByProximity)
		{
			m_proximityMusicVolumes.Add(this);
		}
	}

	private void OnDestroy()
	{
		m_proximityMusicVolumes.Remove(this);
	}

	private void RPC_PlayMusic(long sender)
	{
		bool flag = Vector3.Distance(Player.m_localPlayer.transform.position, base.transform.position) < m_radius + m_surroundingPlayersAdditionalRadius;
		if (flag)
		{
			PlayMusic();
		}
		if ((bool)m_nview && m_nview.IsValid() && m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_plays, flag ? m_PlayCount : (m_PlayCount + 1));
		}
	}

	private void PlayMusic()
	{
		ZLog.Log("MusicLocation '" + base.name + "' Playing Music: " + m_musicName);
		m_PlayCount++;
		MusicMan.instance.LocationMusic(m_musicName);
		if (m_loopMusic)
		{
			m_isLooping = true;
		}
	}

	private void Update()
	{
		if (Player.m_localPlayer == null || m_fadeByProximity)
		{
			return;
		}
		double timeSeconds = ZNet.instance.GetTimeSeconds();
		if (timeSeconds > m_lastEnterCheck + 1.0)
		{
			m_lastEnterCheck = timeSeconds;
			if (IsInside(Player.m_localPlayer.transform.position))
			{
				if (!m_lastWasInside)
				{
					m_lastWasInside = (m_lastWasInsideWide = true);
					OnEnter();
				}
			}
			else
			{
				if (m_lastWasInside)
				{
					m_lastWasInside = false;
					OnExit();
				}
				if (m_lastWasInsideWide && !IsInside(Player.m_localPlayer.transform.position, checkOuter: true))
				{
					m_lastWasInsideWide = false;
					OnExitWide();
				}
			}
		}
		if (m_isLooping && m_lastWasInside && !string.IsNullOrEmpty(m_musicName))
		{
			MusicMan.instance.LocationMusic(m_musicName);
		}
	}

	private void OnEnter()
	{
		ZLog.Log("MusicLocation.OnEnter: " + base.name);
		if (!string.IsNullOrEmpty(m_musicName) && (m_maxPlaysPerActivation == 0 || m_PlayCount < m_maxPlaysPerActivation) && UnityEngine.Random.Range(0f, 1f) <= m_musicChance && (m_musicCanRepeat || MusicMan.instance.m_lastLocationMusic != m_musicName))
		{
			if ((bool)m_nview)
			{
				m_nview.InvokeRPC(ZNetView.Everybody, "RPC_PlayMusic");
			}
			else
			{
				PlayMusic();
			}
		}
	}

	private void OnExit()
	{
		ZLog.Log("MusicLocation.OnExit: " + base.name);
	}

	private void OnExitWide()
	{
		ZLog.Log("MusicLocation.OnExitWide: " + base.name);
		if (MusicMan.instance.m_lastLocationMusic == m_musicName && (m_stopMusicOnExit || m_loopMusic))
		{
			MusicMan.instance.LocationMusic(null);
		}
		m_isLooping = false;
	}

	public bool IsInside(Vector3 point, bool checkOuter = false)
	{
		if (IsBox())
		{
			if (!checkOuter)
			{
				return GetInnerBounds().Contains(point);
			}
			return GetOuterBounds().Contains(point);
		}
		float num = Vector3.Distance(base.transform.position, point);
		if (checkOuter)
		{
			return num < m_radius + m_outerRadiusExtra;
		}
		return num < m_radius;
	}

	private void OnDrawGizmos()
	{
		if (!IsBox())
		{
			Gizmos.color = new Color(0.6f, 0.8f, 0.8f, 0.5f);
			Gizmos.DrawWireSphere(base.transform.position, m_radius);
			Gizmos.color = new Color(0.6f, 0.8f, 0.8f, 0.25f);
			Gizmos.DrawWireSphere(base.transform.position, m_radius + m_outerRadiusExtra);
		}
		else
		{
			Gizmos.color = new Color(0.6f, 0.8f, 0.8f, 0.5f);
			Gizmos.DrawWireCube(GetInnerBounds().center, GetBox().size);
			Gizmos.color = new Color(0.6f, 0.8f, 0.8f, 0.25f);
			Gizmos.DrawWireCube(GetOuterBounds().center, GetOuterBounds().size);
		}
	}

	private bool IsBox()
	{
		return GetBox().size.x != 0f;
	}

	private Bounds GetBox()
	{
		if (!m_sizeFromRoom)
		{
			return m_boundsInner;
		}
		return new Bounds(Vector3.zero, m_sizeFromRoom.m_size);
	}

	private Bounds GetInnerBounds()
	{
		Bounds box = GetBox();
		return new Bounds(box.center + base.transform.position, box.size);
	}

	private Bounds GetOuterBounds()
	{
		Bounds box = GetBox();
		return new Bounds(box.center + base.transform.position, box.size + new Vector3(m_outerRadiusExtra, m_outerRadiusExtra, m_outerRadiusExtra));
	}

	private float MinBoundDimension()
	{
		Bounds box = GetBox();
		if (!(box.size.x < box.size.y) || !(box.size.x < box.size.z))
		{
			if (!(box.size.y < box.size.z))
			{
				return box.size.z;
			}
			return box.size.y;
		}
		return box.size.x;
	}

	public static float UpdateProximityVolumes(AudioSource musicSource)
	{
		if (!Player.m_localPlayer)
		{
			return 1f;
		}
		float num = 0f;
		if (m_lastProximityVolume != null && m_lastProximityVolume.GetInnerBounds().Contains(Player.m_localPlayer.transform.position))
		{
			num = 1f;
		}
		else
		{
			m_lastProximityVolume = null;
			m_close.Clear();
			foreach (MusicVolume proximityMusicVolume in m_proximityMusicVolumes)
			{
				if ((bool)proximityMusicVolume && proximityMusicVolume.IsInside(Player.m_localPlayer.transform.position, checkOuter: true))
				{
					m_close.Add(proximityMusicVolume);
				}
			}
			if (m_close.Count == 0)
			{
				MusicMan.instance.LocationMusic(null);
				return 1f;
			}
			foreach (MusicVolume item in m_close)
			{
				if (item.IsInside(Player.m_localPlayer.transform.position))
				{
					m_lastProximityVolume = item;
					num = 1f;
				}
			}
			if (num == 0f)
			{
				MusicVolume musicVolume = null;
				foreach (MusicVolume item2 in m_close)
				{
					float num2;
					float num3;
					if (item2.IsBox())
					{
						num2 = Vector3.Distance(item2.GetInnerBounds().ClosestPoint(Player.m_localPlayer.transform.position), Player.m_localPlayer.transform.position);
						num3 = item2.m_outerRadiusExtra - num2;
					}
					else
					{
						float num4 = Vector3.Distance(item2.transform.position, Player.m_localPlayer.transform.position);
						num2 = num4 - item2.m_radius;
						num3 = item2.m_radius + item2.m_outerRadiusExtra - num4;
					}
					item2.m_proximity = 1f - Math.Min(1f, num2 / (num2 + num3));
					if (musicVolume == null || item2.m_proximity > musicVolume.m_proximity)
					{
						musicVolume = item2;
					}
				}
				m_lastProximityVolume = musicVolume;
				num = musicVolume.m_proximity;
			}
		}
		MusicMan.instance.LocationMusic(m_lastProximityVolume.m_musicName);
		return num;
	}
}
using System.Collections.Generic;
using UnityEngine;

public class NavmeshTest : MonoBehaviour
{
	public Transform m_target;

	public Pathfinding.AgentType m_agentType = Pathfinding.AgentType.Humanoid;

	public bool m_cleanPath = true;

	private List<Vector3> m_path = new List<Vector3>();

	private bool m_havePath;

	private void Awake()
	{
	}

	private void Update()
	{
		if (Pathfinding.instance.GetPath(base.transform.position, m_target.position, m_path, m_agentType, requireFullPath: false, m_cleanPath))
		{
			m_havePath = true;
		}
		else
		{
			m_havePath = false;
		}
	}

	private void OnDrawGizmos()
	{
		if (m_target == null)
		{
			return;
		}
		if (m_havePath)
		{
			Gizmos.color = Color.yellow;
			for (int i = 0; i < m_path.Count - 1; i++)
			{
				Vector3 vector = m_path[i];
				Gizmos.DrawLine(to: m_path[i + 1] + Vector3.up * 0.2f, from: vector + Vector3.up * 0.2f);
			}
			foreach (Vector3 item in m_path)
			{
				Gizmos.DrawSphere(item + Vector3.up * 0.2f, 0.1f);
			}
			Gizmos.color = Color.green;
			Gizmos.DrawSphere(base.transform.position, 0.3f);
			Gizmos.DrawSphere(m_target.position, 0.3f);
		}
		else
		{
			Gizmos.color = Color.red;
			Gizmos.DrawLine(base.transform.position + Vector3.up * 0.2f, m_target.position + Vector3.up * 0.2f);
			Gizmos.DrawSphere(base.transform.position, 0.3f);
			Gizmos.DrawSphere(m_target.position, 0.3f);
		}
	}
}
