using System;
using System.Collections.Generic;
using UnityEngine;

public class NpcTalk : MonoBehaviour
{
	private class QueuedSay
	{
		public string text;

		public string trigger;

		public EffectList m_effect;
	}

	private float m_lastTargetUpdate;

	public string m_name = "Haldor";

	public float m_maxRange = 15f;

	public float m_greetRange = 10f;

	public float m_byeRange = 15f;

	public float m_offset = 2f;

	public float m_minTalkInterval = 1.5f;

	private const int m_maxQueuedTexts = 3;

	public float m_hideDialogDelay = 5f;

	public float m_randomTalkInterval = 10f;

	public float m_randomTalkChance = 1f;

	public List<string> m_randomTalk = new List<string>();

	public List<string> m_randomTalkInFactionBase = new List<string>();

	public List<string> m_randomGreets = new List<string>();

	public List<string> m_randomGoodbye = new List<string>();

	public List<string> m_privateAreaAlarm = new List<string>();

	public List<string> m_aggravated = new List<string>();

	public EffectList m_randomTalkFX = new EffectList();

	public EffectList m_randomGreetFX = new EffectList();

	public EffectList m_randomGoodbyeFX = new EffectList();

	private bool m_didGreet;

	private bool m_didGoodbye;

	private MonsterAI m_monsterAI;

	private Animator m_animator;

	private Character m_character;

	private ZNetView m_nview;

	private Player m_targetPlayer;

	private bool m_seeTarget;

	private bool m_hearTarget;

	private Queue<QueuedSay> m_queuedTexts = new Queue<QueuedSay>();

	private static float m_lastTalkTime;

	private void Start()
	{
		m_character = GetComponentInChildren<Character>();
		m_monsterAI = GetComponent<MonsterAI>();
		m_animator = GetComponentInChildren<Animator>();
		m_nview = GetComponent<ZNetView>();
		MonsterAI monsterAI = m_monsterAI;
		monsterAI.m_onBecameAggravated = (Action<BaseAI.AggravatedReason>)Delegate.Combine(monsterAI.m_onBecameAggravated, new Action<BaseAI.AggravatedReason>(OnBecameAggravated));
		InvokeRepeating("RandomTalk", UnityEngine.Random.Range(m_randomTalkInterval / 5f, m_randomTalkInterval), m_randomTalkInterval);
	}

	private void Update()
	{
		if (m_monsterAI.GetTargetCreature() != null || m_monsterAI.GetStaticTarget() != null || !m_nview.IsValid())
		{
			return;
		}
		UpdateTarget();
		if ((bool)m_targetPlayer)
		{
			if (m_nview.IsOwner() && m_character.GetVelocity().magnitude < 0.5f)
			{
				Vector3 normalized = (m_targetPlayer.GetEyePoint() - m_character.GetEyePoint()).normalized;
				m_character.SetLookDir(normalized);
			}
			if (m_seeTarget)
			{
				float num = Vector3.Distance(m_targetPlayer.transform.position, base.transform.position);
				if (!m_didGreet && num < m_greetRange)
				{
					m_didGreet = true;
					QueueSay(m_randomGreets, "Greet", m_randomGreetFX);
				}
				if (m_didGreet && !m_didGoodbye && num > m_byeRange)
				{
					m_didGoodbye = true;
					QueueSay(m_randomGoodbye, "Greet", m_randomGoodbyeFX);
				}
			}
		}
		UpdateSayQueue();
	}

	private void UpdateTarget()
	{
		if (!(Time.time - m_lastTargetUpdate > 1f))
		{
			return;
		}
		m_lastTargetUpdate = Time.time;
		m_targetPlayer = null;
		Player closestPlayer = Player.GetClosestPlayer(base.transform.position, m_maxRange);
		if (!(closestPlayer == null) && !m_monsterAI.IsEnemy(closestPlayer))
		{
			m_seeTarget = m_monsterAI.CanSeeTarget(closestPlayer);
			m_hearTarget = m_monsterAI.CanHearTarget(closestPlayer);
			if (m_seeTarget || m_hearTarget)
			{
				m_targetPlayer = closestPlayer;
			}
		}
	}

	private void OnBecameAggravated(BaseAI.AggravatedReason reason)
	{
		QueueSay(m_aggravated, "Aggravated", null);
	}

	public void OnPrivateAreaAttacked(Character attacker)
	{
		if (attacker.IsPlayer() && m_monsterAI.IsAggravatable() && !m_monsterAI.IsAggravated() && Vector3.Distance(base.transform.position, attacker.transform.position) < m_maxRange)
		{
			QueueSay(m_privateAreaAlarm, "Angry", null);
		}
	}

	private void RandomTalk()
	{
		if (!(Time.time - m_lastTalkTime < m_minTalkInterval) && !(UnityEngine.Random.Range(0f, 1f) > m_randomTalkChance))
		{
			UpdateTarget();
			if ((bool)m_targetPlayer && m_seeTarget)
			{
				List<string> texts = (InFactionBase() ? m_randomTalkInFactionBase : m_randomTalk);
				QueueSay(texts, "Talk", m_randomTalkFX);
			}
		}
	}

	private void QueueSay(List<string> texts, string trigger, EffectList effect)
	{
		if (texts.Count != 0 && m_queuedTexts.Count < 3)
		{
			QueuedSay queuedSay = new QueuedSay();
			queuedSay.text = texts[UnityEngine.Random.Range(0, texts.Count)];
			queuedSay.trigger = trigger;
			queuedSay.m_effect = effect;
			m_queuedTexts.Enqueue(queuedSay);
		}
	}

	private void UpdateSayQueue()
	{
		if (m_queuedTexts.Count != 0 && !(Time.time - m_lastTalkTime < m_minTalkInterval))
		{
			QueuedSay queuedSay = m_queuedTexts.Dequeue();
			Say(queuedSay.text, queuedSay.trigger);
			if (queuedSay.m_effect != null)
			{
				queuedSay.m_effect.Create(base.transform.position, Quaternion.identity);
			}
		}
	}

	private void Say(string text, string trigger)
	{
		m_lastTalkTime = Time.time;
		Chat.instance.SetNpcText(base.gameObject, Vector3.up * m_offset, 20f, m_hideDialogDelay, "", text, large: false);
		if (trigger.Length > 0)
		{
			m_animator.SetTrigger(trigger);
		}
	}

	private bool InFactionBase()
	{
		return PrivateArea.InsideFactionArea(base.transform.position, m_character.GetFaction());
	}
}
using System.Collections.Generic;
using UnityEngine;

public class ObjectDB : MonoBehaviour
{
	private static ObjectDB m_instance;

	public List<StatusEffect> m_StatusEffects = new List<StatusEffect>();

	public List<GameObject> m_items = new List<GameObject>();

	public List<Recipe> m_recipes = new List<Recipe>();

	private Dictionary<int, GameObject> m_itemByHash = new Dictionary<int, GameObject>();

	private Dictionary<ItemDrop.ItemData.SharedData, GameObject> m_itemByData = new Dictionary<ItemDrop.ItemData.SharedData, GameObject>();

	public static ObjectDB instance => m_instance;

	private void Awake()
	{
		m_instance = this;
		UpdateRegisters();
	}

	public void CopyOtherDB(ObjectDB other)
	{
		m_items = other.m_items;
		m_recipes = other.m_recipes;
		m_StatusEffects = other.m_StatusEffects;
		UpdateRegisters();
	}

	private void UpdateRegisters()
	{
		m_itemByHash.Clear();
		m_itemByData.Clear();
		foreach (GameObject item in m_items)
		{
			m_itemByHash.Add(item.name.GetStableHashCode(), item);
			ItemDrop component = item.GetComponent<ItemDrop>();
			if ((object)component != null)
			{
				m_itemByData[component.m_itemData.m_shared] = item;
			}
		}
	}

	public StatusEffect GetStatusEffect(int nameHash)
	{
		foreach (StatusEffect statusEffect in m_StatusEffects)
		{
			if (statusEffect.NameHash() == nameHash)
			{
				return statusEffect;
			}
		}
		return null;
	}

	public GameObject GetItemPrefab(string name)
	{
		return GetItemPrefab(name.GetStableHashCode());
	}

	public GameObject GetItemPrefab(int hash)
	{
		if (TryGetItemPrefab(hash, out var prefab))
		{
			return prefab;
		}
		return null;
	}

	public GameObject GetItemPrefab(ItemDrop.ItemData.SharedData sharedData)
	{
		if (TryGetItemPrefab(sharedData, out var prefab))
		{
			return prefab;
		}
		return null;
	}

	public bool TryGetItemPrefab(string name, out GameObject prefab)
	{
		return TryGetItemPrefab(name.GetStableHashCode(), out prefab);
	}

	public bool TryGetItemPrefab(int hash, out GameObject prefab)
	{
		return m_itemByHash.TryGetValue(hash, out prefab);
	}

	public bool TryGetItemPrefab(ItemDrop.ItemData.SharedData sharedData, out GameObject prefab)
	{
		return m_itemByData.TryGetValue(sharedData, out prefab);
	}

	public int GetPrefabHash(GameObject prefab)
	{
		return prefab.name.GetStableHashCode();
	}

	public List<ItemDrop> GetAllItems(ItemDrop.ItemData.ItemType type, string startWith)
	{
		List<ItemDrop> list = new List<ItemDrop>();
		foreach (GameObject item in m_items)
		{
			ItemDrop component = item.GetComponent<ItemDrop>();
			if (component.m_itemData.m_shared.m_itemType == type && component.gameObject.name.CustomStartsWith(startWith))
			{
				list.Add(component);
			}
		}
		return list;
	}

	public Recipe GetRecipe(ItemDrop.ItemData item)
	{
		foreach (Recipe recipe in m_recipes)
		{
			if (!(recipe.m_item == null) && recipe.m_item.m_itemData.m_shared.m_name == item.m_shared.m_name)
			{
				return recipe;
			}
		}
		return null;
	}
}
using UnityEngine;

public class OceanBubbleParticles : MonoBehaviour
{
	private ParticleSystem m_particleSystem;

	private ParticleSystem.Particle[] m_particles;

	private void Start()
	{
		m_particleSystem = GetComponent<ParticleSystem>();
	}

	private void Update()
	{
		if (m_particles == null)
		{
			m_particles = new ParticleSystem.Particle[m_particleSystem.main.maxParticles];
		}
		int particles = m_particleSystem.GetParticles(m_particles);
		for (int i = 0; i < particles; i++)
		{
			float liquidLevel = Floating.GetLiquidLevel(m_particles[i].position);
			Vector3 position = m_particles[i].position;
			position.y = liquidLevel;
			m_particles[i].position = position;
		}
		m_particleSystem.SetParticles(m_particles);
	}
}
using UnityEngine;

public class Odin : MonoBehaviour
{
	public float m_despawnCloseDistance = 20f;

	public float m_despawnFarDistance = 50f;

	public EffectList m_despawn = new EffectList();

	public float m_ttl = 300f;

	private float m_time;

	private ZNetView m_nview;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
	}

	private void Update()
	{
		if (!m_nview.IsOwner())
		{
			return;
		}
		Player closestPlayer = Player.GetClosestPlayer(base.transform.position, m_despawnFarDistance);
		if (closestPlayer == null)
		{
			m_despawn.Create(base.transform.position, base.transform.rotation);
			m_nview.Destroy();
			ZLog.Log("No player in range, despawning");
			return;
		}
		Vector3 forward = closestPlayer.transform.position - base.transform.position;
		forward.y = 0f;
		forward.Normalize();
		base.transform.rotation = Quaternion.LookRotation(forward);
		if (Vector3.Distance(closestPlayer.transform.position, base.transform.position) < m_despawnCloseDistance)
		{
			m_despawn.Create(base.transform.position, base.transform.rotation);
			m_nview.Destroy();
			ZLog.Log("Player go too close,despawning");
			return;
		}
		m_time += Time.deltaTime;
		if (m_time > m_ttl)
		{
			m_despawn.Create(base.transform.position, base.transform.rotation);
			m_nview.Destroy();
			ZLog.Log("timeout " + m_time + " , despawning");
		}
	}
}
using System.Collections.Generic;
using UnityEngine;

public class OfferingBowl : MonoBehaviour, Hoverable, Interactable
{
	[Header("Tokens")]
	public string m_name = "$piece_offerbowl";

	public string m_useItemText = "$piece_offerbowl_offeritem";

	public string m_usedAltarText = "$msg_offerdone";

	public string m_cantOfferText = "$msg_cantoffer";

	public string m_wrongOfferText = "$msg_offerwrong";

	public string m_incompleteOfferText = "$msg_incompleteoffering";

	[Header("Settings")]
	public ItemDrop m_bossItem;

	public int m_bossItems = 1;

	public GameObject m_bossPrefab;

	public ItemDrop m_itemPrefab;

	public Transform m_itemSpawnPoint;

	public string m_setGlobalKey = "";

	public bool m_renderSpawnAreaGizmos;

	public bool m_alertOnSpawn;

	[Header("Boss")]
	public float m_spawnBossDelay = 5f;

	public float m_spawnBossMaxDistance = 40f;

	public float m_spawnBossMinDistance;

	public float m_spawnBossMaxYDistance = 9999f;

	public int m_getSolidHeightMargin = 1000;

	public bool m_enableSolidHeightCheck = true;

	public float m_spawnPointClearingRadius;

	public float m_spawnYOffset = 1f;

	public Vector3 m_spawnAreaOffset;

	public List<GameObject> m_spawnPoints = new List<GameObject>();

	[Header("Use itemstands")]
	public bool m_useItemStands;

	public string m_itemStandPrefix = "";

	public float m_itemstandMaxRange = 20f;

	[Header("Effects")]
	public EffectList m_fuelAddedEffects = new EffectList();

	public EffectList m_spawnBossStartEffects = new EffectList();

	public EffectList m_spawnBossDoneffects = new EffectList();

	private Vector3 m_bossSpawnPoint;

	private int m_solidRayMask;

	private static readonly Collider[] s_tempColliders = new Collider[1];

	private ZNetView m_nview;

	private Humanoid m_interactUser;

	private ItemDrop.ItemData m_usedSpawnItem;

	private void Awake()
	{
		m_solidRayMask = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece");
	}

	private void Start()
	{
		m_nview = GetComponentInParent<ZNetView>();
		if ((bool)m_nview)
		{
			m_nview.Register<Vector3, bool>("RPC_SpawnBoss", RPC_SpawnBoss);
			m_nview.Register("RPC_BossSpawnInitiated", RPC_BossSpawnInitiated);
			m_nview.Register("RPC_RemoveBossSpawnInventoryItems", RPC_RemoveBossSpawnInventoryItems);
		}
	}

	public string GetHoverText()
	{
		if (m_useItemStands)
		{
			return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] " + m_useItemText);
		}
		return Localization.instance.Localize(m_name + "\n[<color=yellow><b>1-8</b></color>] " + m_useItemText);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid user, bool hold, bool alt)
	{
		if (hold || IsBossSpawnQueued() || !m_useItemStands)
		{
			return false;
		}
		foreach (ItemStand item in FindItemStands())
		{
			if (!item.HaveAttachment())
			{
				user.Message(MessageHud.MessageType.Center, m_incompleteOfferText);
				return false;
			}
		}
		m_interactUser = user;
		InitiateSpawnBoss(GetSpawnPosition(), removeItemsFromInventory: false);
		return true;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		if (m_useItemStands)
		{
			return false;
		}
		if (IsBossSpawnQueued())
		{
			return true;
		}
		if (m_bossItem != null)
		{
			if (item.m_shared.m_name == m_bossItem.m_itemData.m_shared.m_name)
			{
				int num = user.GetInventory().CountItems(m_bossItem.m_itemData.m_shared.m_name);
				if (num < m_bossItems)
				{
					if (num == 0 && Game.m_worldLevel > 0 && user.GetInventory().CountItems(m_bossItem.m_itemData.m_shared.m_name, -1, matchWorldLevel: false) > 0)
					{
						user.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$msg_ng_the_x") + item.m_shared.m_name + Localization.instance.Localize("$msg_ng_x_is_too_low"));
					}
					else
					{
						user.Message(MessageHud.MessageType.Center, $"{m_incompleteOfferText}: {m_bossItem.m_itemData.m_shared.m_name} {num.ToString()} / {m_bossItems}");
					}
					return true;
				}
				if (m_bossPrefab != null)
				{
					m_usedSpawnItem = item;
					m_interactUser = user;
					InitiateSpawnBoss(GetSpawnPosition(), removeItemsFromInventory: true);
				}
				else if (m_itemPrefab != null && SpawnItem(m_itemPrefab, user as Player))
				{
					user.GetInventory().RemoveItem(item.m_shared.m_name, m_bossItems);
					user.ShowRemovedMessage(m_bossItem.m_itemData, m_bossItems);
					user.Message(MessageHud.MessageType.Center, m_usedAltarText);
					m_fuelAddedEffects.Create(m_itemSpawnPoint.position, base.transform.rotation);
				}
				if (!string.IsNullOrEmpty(m_setGlobalKey))
				{
					ZoneSystem.instance.SetGlobalKey(m_setGlobalKey);
				}
				return true;
			}
			user.Message(MessageHud.MessageType.Center, m_wrongOfferText);
			return true;
		}
		return false;
	}

	private bool SpawnItem(ItemDrop item, Player player)
	{
		if (item.m_itemData.m_shared.m_questItem && player.HaveUniqueKey(item.m_itemData.m_shared.m_name))
		{
			player.Message(MessageHud.MessageType.Center, m_cantOfferText);
			return false;
		}
		Object.Instantiate(item, m_itemSpawnPoint.position, Quaternion.identity);
		return true;
	}

	private Vector3 GetSpawnPosition()
	{
		if (m_spawnPoints.Count > 0)
		{
			return m_spawnPoints[Random.Range(0, m_spawnPoints.Count)].transform.position;
		}
		Vector3 vector = base.transform.localToWorldMatrix * m_spawnAreaOffset;
		return base.transform.position + vector;
	}

	private void InitiateSpawnBoss(Vector3 point, bool removeItemsFromInventory)
	{
		m_nview.InvokeRPC("RPC_SpawnBoss", point, removeItemsFromInventory);
	}

	private void RPC_SpawnBoss(long senderId, Vector3 point, bool removeItemsFromInventory)
	{
		if (m_nview.IsOwner() && !IsBossSpawnQueued() && CanSpawnBoss(point, out var spawnPoint) && ((bool)m_nview || !m_nview.IsValid()))
		{
			SpawnBoss(spawnPoint);
			m_nview.InvokeRPC(senderId, "RPC_BossSpawnInitiated");
			if (removeItemsFromInventory)
			{
				m_nview.InvokeRPC(senderId, "RPC_RemoveBossSpawnInventoryItems");
			}
			else
			{
				RemoveAltarItems();
			}
		}
	}

	private void SpawnBoss(Vector3 spawnPoint)
	{
		Invoke("DelayedSpawnBoss", m_spawnBossDelay);
		m_spawnBossStartEffects.Create(spawnPoint, Quaternion.identity);
		m_bossSpawnPoint = spawnPoint;
	}

	private void RPC_RemoveBossSpawnInventoryItems(long senderId)
	{
		m_interactUser.GetInventory().RemoveItem(m_usedSpawnItem.m_shared.m_name, m_bossItems);
		m_interactUser.ShowRemovedMessage(m_bossItem.m_itemData, m_bossItems);
		m_interactUser.Message(MessageHud.MessageType.Center, m_usedAltarText);
		if ((bool)m_itemSpawnPoint)
		{
			m_fuelAddedEffects.Create(m_itemSpawnPoint.position, base.transform.rotation);
		}
	}

	private void RemoveAltarItems()
	{
		foreach (ItemStand item in FindItemStands())
		{
			item.DestroyAttachment();
		}
		if ((bool)m_itemSpawnPoint)
		{
			m_fuelAddedEffects.Create(m_itemSpawnPoint.position, base.transform.rotation);
		}
	}

	private void RPC_BossSpawnInitiated(long senderId)
	{
		m_interactUser.Message(MessageHud.MessageType.Center, m_usedAltarText);
	}

	private bool CanSpawnBoss(Vector3 point, out Vector3 spawnPoint)
	{
		spawnPoint = Vector3.zero;
		for (int i = 0; i < 100; i++)
		{
			Vector2 vector = Random.insideUnitCircle * m_spawnBossMaxDistance;
			spawnPoint = point + new Vector3(vector.x, 0f, vector.y);
			if (m_enableSolidHeightCheck)
			{
				ZoneSystem.instance.GetSolidHeight(spawnPoint, out var height, m_getSolidHeightMargin);
				if (height < 0f || Mathf.Abs(height - base.transform.position.y) > m_spawnBossMaxYDistance || Vector3.Distance(spawnPoint, point) < m_spawnBossMinDistance)
				{
					continue;
				}
				if (m_spawnPointClearingRadius > 0f)
				{
					spawnPoint.y = height + m_spawnYOffset;
					int num = Physics.OverlapSphereNonAlloc(spawnPoint, m_spawnPointClearingRadius, null, m_solidRayMask);
					if (num > 0)
					{
						ZLog.Log(num);
						continue;
					}
				}
				spawnPoint.y = height + m_spawnYOffset;
			}
			return true;
		}
		return false;
	}

	private bool IsBossSpawnQueued()
	{
		return IsInvoking("DelayedSpawnBoss");
	}

	private void DelayedSpawnBoss()
	{
		GameObject gameObject = Object.Instantiate(m_bossPrefab, m_bossSpawnPoint, Quaternion.identity);
		BaseAI component = gameObject.GetComponent<BaseAI>();
		if (component != null)
		{
			component.SetPatrolPoint();
			if (m_alertOnSpawn)
			{
				component.Alert();
			}
		}
		GameObject[] array = m_spawnBossDoneffects.Create(m_bossSpawnPoint, Quaternion.identity);
		for (int i = 0; i < array.Length; i++)
		{
			IProjectile[] componentsInChildren = array[i].GetComponentsInChildren<IProjectile>();
			if (componentsInChildren.Length != 0)
			{
				IProjectile[] array2 = componentsInChildren;
				for (int j = 0; j < array2.Length; j++)
				{
					array2[j].Setup(gameObject.GetComponent<Character>(), Vector3.zero, -1f, null, null, null);
				}
			}
		}
	}

	private List<ItemStand> FindItemStands()
	{
		List<ItemStand> list = new List<ItemStand>();
		ItemStand[] array = Object.FindObjectsOfType<ItemStand>();
		foreach (ItemStand itemStand in array)
		{
			if (!(Vector3.Distance(base.transform.position, itemStand.transform.position) > m_itemstandMaxRange) && itemStand.gameObject.name.CustomStartsWith(m_itemStandPrefix))
			{
				list.Add(itemStand);
			}
		}
		return list;
	}

	private void OnDrawGizmosSelected()
	{
		if (m_renderSpawnAreaGizmos)
		{
			Gizmos.color = Color.green;
			Utils.DrawGizmoCylinder(GetSpawnPosition(), m_spawnBossMaxDistance, m_spawnBossMaxYDistance, 32);
			Gizmos.color = Color.red;
			if (m_spawnBossMinDistance > 0f)
			{
				Utils.DrawGizmoCylinder(GetSpawnPosition(), m_spawnBossMinDistance, m_spawnBossMaxYDistance, 32);
			}
		}
	}
}
public enum OnlineBackendType
