using System;
using UnityEngine;

public class Pickable : MonoBehaviour, Hoverable, Interactable
{
	public delegate bool SpawnCheck(Pickable p);

	public GameObject m_hideWhenPicked;

	public GameObject m_itemPrefab;

	public int m_amount = 1;

	public int m_minAmountScaled = 1;

	public bool m_dontScale;

	public DropTable m_extraDrops = new DropTable();

	public string m_overrideName = "";

	public float m_respawnTimeMinutes;

	public float m_respawnTimeInitMin;

	public float m_respawnTimeInitMax;

	public float m_spawnOffset = 0.5f;

	public EffectList m_pickEffector = new EffectList();

	public bool m_pickEffectAtSpawnPoint;

	public bool m_useInteractAnimation;

	public bool m_tarPreventsPicking;

	public float m_aggravateRange;

	public bool m_defaultPicked;

	public bool m_defaultEnabled = true;

	public SpawnCheck m_spawnCheck;

	public bool m_harvestable;

	public Skills.SkillType m_pickRaiseSkill;

	public float m_maxLevelBonusChance = 0.25f;

	public int m_bonusYieldAmount = 1;

	public EffectList m_bonusEffect;

	private ZNetView m_nview;

	private Floating m_floating;

	private bool m_picked;

	private int m_enabled = 2;

	private long m_pickedTime;

	public int GetEnabled => m_enabled;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		ZDO zDO = m_nview.GetZDO();
		if (zDO != null)
		{
			m_nview.Register<bool>("RPC_SetPicked", RPC_SetPicked);
			m_nview.Register<int>("RPC_Pick", RPC_Pick);
			m_picked = zDO.GetBool(ZDOVars.s_picked, m_defaultPicked);
			m_pickedTime = m_nview.GetZDO().GetLong(ZDOVars.s_pickedTime, 0L);
			if (m_enabled == 2)
			{
				m_enabled = (zDO.GetBool(ZDOVars.s_enabled, defaultValue: true) ? 1 : 0);
			}
			else if (m_nview.IsOwner())
			{
				zDO.Set(ZDOVars.s_enabled, m_enabled == 1);
			}
			if ((bool)m_hideWhenPicked)
			{
				m_hideWhenPicked.SetActive(!m_picked && m_enabled == 1);
			}
			float repeatRate = 60f;
			if (m_respawnTimeMinutes > 0f)
			{
				InvokeRepeating("UpdateRespawn", UnityEngine.Random.Range(1f, 5f), repeatRate);
			}
			if (m_respawnTimeMinutes <= 0f && m_hideWhenPicked == null && m_nview.GetZDO().GetBool(ZDOVars.s_picked))
			{
				m_nview.ClaimOwnership();
				m_nview.Destroy();
				ZLog.Log("Destroying old picked " + base.name);
			}
		}
	}

	public string GetHoverText()
	{
		if (m_picked || m_enabled == 0)
		{
			return "";
		}
		return Localization.instance.Localize(GetHoverName() + "\n[<color=yellow><b>$KEY_Use</b></color>] $inventory_pickup");
	}

	public string GetHoverName()
	{
		if (!string.IsNullOrEmpty(m_overrideName))
		{
			return m_overrideName;
		}
		return m_itemPrefab.GetComponent<ItemDrop>().m_itemData.m_shared.m_name;
	}

	private void UpdateRespawn()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner() || !m_picked)
		{
			return;
		}
		if (m_pickedTime == 0L)
		{
			m_pickedTime = ZNet.instance.GetTime().Ticks - TimeSpan.FromMinutes(UnityEngine.Random.Range(m_respawnTimeInitMin * 100f, m_respawnTimeInitMax * 100f)).Ticks;
			if (m_pickedTime < 1)
			{
				m_pickedTime = 1L;
			}
			m_nview.GetZDO().Set(ZDOVars.s_pickedTime, m_pickedTime);
		}
		if (m_enabled == 0)
		{
			if ((bool)m_hideWhenPicked)
			{
				m_hideWhenPicked.SetActive(value: false);
			}
		}
		else if (ShouldRespawn())
		{
			m_nview.InvokeRPC(ZNetView.Everybody, "RPC_SetPicked", false);
		}
	}

	private bool ShouldRespawn()
	{
		if (!m_nview)
		{
			return false;
		}
		long num = m_nview.GetZDO().GetLong(ZDOVars.s_pickedTime, 0L);
		DateTime dateTime = new DateTime(num);
		TimeSpan timeSpan = ZNet.instance.GetTime() - dateTime;
		if (num > 1 && timeSpan.TotalMinutes <= (double)m_respawnTimeMinutes)
		{
			return false;
		}
		if (m_spawnCheck != null)
		{
			return m_spawnCheck(this);
		}
		return true;
	}

	public bool Interact(Humanoid character, bool repeat, bool alt)
	{
		if (!m_nview.IsValid() || m_enabled == 0)
		{
			return false;
		}
		if (m_tarPreventsPicking)
		{
			if (m_floating == null)
			{
				m_floating = GetComponent<Floating>();
			}
			if ((bool)m_floating && m_floating.IsInTar())
			{
				character.Message(MessageHud.MessageType.Center, "$hud_itemstucktar");
				return m_useInteractAnimation;
			}
		}
		int num = 0;
		if (!m_picked && m_pickRaiseSkill != Skills.SkillType.None && character is Player player)
		{
			player.RaiseSkill(m_pickRaiseSkill);
			float skillFactor = player.GetSkillFactor(m_pickRaiseSkill);
			if (UnityEngine.Random.value < skillFactor * m_maxLevelBonusChance)
			{
				num = m_bonusYieldAmount;
				DamageText.instance.ShowText(DamageText.TextType.Bonus, base.transform.position + Vector3.up * m_spawnOffset, $"+{num}", player: true);
				m_bonusEffect.Create(base.transform.position, Quaternion.identity);
				ZLog.Log("Bonus food picked!");
			}
		}
		m_nview.InvokeRPC("RPC_Pick", num);
		return m_useInteractAnimation;
	}

	private void RPC_Pick(long sender, int bonus)
	{
		if (!m_nview.IsOwner() || m_picked)
		{
			return;
		}
		Vector3 basePos = (m_pickEffectAtSpawnPoint ? (base.transform.position + Vector3.up * m_spawnOffset) : base.transform.position);
		m_pickEffector.Create(basePos, Quaternion.identity);
		int num = (m_dontScale ? m_amount : Mathf.Max(m_minAmountScaled, Game.instance.ScaleDrops(m_itemPrefab, m_amount)));
		num += bonus;
		int num2 = 0;
		for (int i = 0; i < num; i++)
		{
			Drop(m_itemPrefab, num2++, 1);
		}
		if (!m_extraDrops.IsEmpty())
		{
			foreach (ItemDrop.ItemData dropListItem in m_extraDrops.GetDropListItems())
			{
				Drop(dropListItem.m_dropPrefab, num2++, dropListItem.m_stack);
			}
		}
		if (m_aggravateRange > 0f)
		{
			BaseAI.AggravateAllInArea(base.transform.position, m_aggravateRange, BaseAI.AggravatedReason.Theif);
		}
		m_nview.InvokeRPC(ZNetView.Everybody, "RPC_SetPicked", true);
	}

	private void RPC_SetPicked(long sender, bool picked)
	{
		SetPicked(picked);
	}

	public void SetPicked(bool picked)
	{
		m_picked = picked;
		if ((bool)m_hideWhenPicked)
		{
			m_hideWhenPicked.SetActive(!picked);
		}
		if (!m_nview || !m_nview.IsOwner())
		{
			return;
		}
		if (m_respawnTimeMinutes > 0f || m_hideWhenPicked != null)
		{
			m_nview.GetZDO().Set(ZDOVars.s_picked, m_picked);
			if (picked && m_respawnTimeMinutes > 0f)
			{
				DateTime time = ZNet.instance.GetTime();
				m_nview.GetZDO().Set(ZDOVars.s_pickedTime, time.Ticks);
			}
		}
		else if (picked)
		{
			m_nview.Destroy();
		}
	}

	public bool GetPicked()
	{
		return m_picked;
	}

	public void SetEnabled(bool value)
	{
		SetEnabled(value ? 1 : 0);
	}

	public void SetEnabled(int value)
	{
		m_enabled = value;
		if ((bool)m_nview && m_nview.IsOwner() && m_nview.GetZDO() != null)
		{
			m_nview.GetZDO().Set(ZDOVars.s_enabled, base.enabled);
		}
		if ((bool)m_hideWhenPicked)
		{
			m_hideWhenPicked.SetActive(base.enabled && ShouldRespawn());
		}
	}

	public bool CanBePicked()
	{
		if (!m_hideWhenPicked || !m_hideWhenPicked.activeInHierarchy)
		{
			if (!m_picked)
			{
				return m_enabled == 1;
			}
			return false;
		}
		return true;
	}

	private void Drop(GameObject prefab, int offset, int stack)
	{
		Vector2 vector = UnityEngine.Random.insideUnitCircle * 0.2f;
		Vector3 position = base.transform.position + Vector3.up * m_spawnOffset + new Vector3(vector.x, 0.5f * (float)offset, vector.y);
		Quaternion rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
		GameObject obj = UnityEngine.Object.Instantiate(prefab, position, rotation);
		ItemDrop component = obj.GetComponent<ItemDrop>();
		if ((object)component != null)
		{
			component.SetStack(stack);
			ItemDrop.OnCreateNew(component);
		}
		obj.GetComponent<Rigidbody>().linearVelocity = Vector3.up * 4f;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}
}
using System;
using UnityEngine;

public class PickableItem : MonoBehaviour, Hoverable, Interactable
{
	[Serializable]
	public struct RandomItem
	{
		public ItemDrop m_itemPrefab;

		public int m_stackMin;

		public int m_stackMax;
	}

	public ItemDrop m_itemPrefab;

	public int m_stack;

	public RandomItem[] m_randomItemPrefabs = Array.Empty<RandomItem>();

	public EffectList m_pickEffector = new EffectList();

	private ZNetView m_nview;

	private GameObject m_instance;

	private bool m_picked;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		if (m_nview.GetZDO() != null)
		{
			SetupRandomPrefab();
			m_nview.Register("Pick", RPC_Pick);
			SetupItem(enabled: true);
		}
	}

	private void SetupRandomPrefab()
	{
		if (!(m_itemPrefab == null) || m_randomItemPrefabs.Length == 0)
		{
			return;
		}
		int num = m_nview.GetZDO().GetInt(ZDOVars.s_itemPrefab);
		if (num == 0)
		{
			if (m_nview.IsOwner())
			{
				RandomItem randomItem = m_randomItemPrefabs[UnityEngine.Random.Range(0, m_randomItemPrefabs.Length)];
				m_itemPrefab = randomItem.m_itemPrefab;
				m_stack = Game.instance.ScaleDrops(randomItem.m_itemPrefab.m_itemData, randomItem.m_stackMin, randomItem.m_stackMax + 1);
				int prefabHash = ObjectDB.instance.GetPrefabHash(m_itemPrefab.gameObject);
				m_nview.GetZDO().Set(ZDOVars.s_itemPrefab, prefabHash);
				m_nview.GetZDO().Set(ZDOVars.s_itemStack, m_stack);
			}
		}
		else
		{
			GameObject itemPrefab = ObjectDB.instance.GetItemPrefab(num);
			if (itemPrefab == null)
			{
				ZLog.LogError("Failed to find saved prefab " + num + " in PickableItem " + base.gameObject.name);
				return;
			}
			m_itemPrefab = itemPrefab.GetComponent<ItemDrop>();
			m_stack = m_nview.GetZDO().GetInt(ZDOVars.s_itemStack);
		}
	}

	public string GetHoverText()
	{
		if (m_picked)
		{
			return "";
		}
		return Localization.instance.Localize(GetHoverName() + "\n[<color=yellow><b>$KEY_Use</b></color>] $inventory_pickup");
	}

	public string GetHoverName()
	{
		if ((bool)m_itemPrefab)
		{
			int stackSize = GetStackSize();
			if (stackSize > 1)
			{
				return m_itemPrefab.m_itemData.m_shared.m_name + " x " + stackSize;
			}
			return m_itemPrefab.m_itemData.m_shared.m_name;
		}
		return "None";
	}

	public bool Interact(Humanoid character, bool repeat, bool alt)
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		m_nview.InvokeRPC("Pick");
		return true;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void RPC_Pick(long sender)
	{
		if (m_nview.IsOwner() && !m_picked)
		{
			m_picked = true;
			m_pickEffector.Create(base.transform.position, Quaternion.identity);
			Drop();
			m_nview.Destroy();
		}
	}

	private void Drop()
	{
		Vector3 position = base.transform.position + Vector3.up * 0.2f;
		GameObject obj = UnityEngine.Object.Instantiate(m_itemPrefab.gameObject, position, base.transform.rotation);
		ItemDrop component = obj.GetComponent<ItemDrop>();
		if ((object)component != null)
		{
			component.m_itemData.m_stack = GetStackSize();
			ItemDrop.OnCreateNew(component);
		}
		obj.GetComponent<Rigidbody>().linearVelocity = Vector3.up * 4f;
	}

	private int GetStackSize()
	{
		return Mathf.Clamp((m_stack > 0) ? m_stack : m_itemPrefab.m_itemData.m_stack, 1, (int)Math.Round((float)m_itemPrefab.m_itemData.m_shared.m_maxStackSize * Game.m_resourceRate));
	}

	private GameObject GetAttachPrefab()
	{
		Transform transform = m_itemPrefab.transform.Find("attach");
		if ((bool)transform)
		{
			return transform.gameObject;
		}
		return null;
	}

	private void SetupItem(bool enabled)
	{
		if (!enabled)
		{
			if ((bool)m_instance)
			{
				UnityEngine.Object.Destroy(m_instance);
				m_instance = null;
			}
		}
		else if (!m_instance && !(m_itemPrefab == null))
		{
			GameObject attachPrefab = GetAttachPrefab();
			if (attachPrefab == null)
			{
				ZLog.LogWarning("Failed to get attach prefab for item " + m_itemPrefab.name);
				return;
			}
			m_instance = UnityEngine.Object.Instantiate(attachPrefab, base.transform.position, base.transform.rotation, base.transform);
			m_instance.transform.localPosition = attachPrefab.transform.localPosition;
			m_instance.transform.localRotation = attachPrefab.transform.localRotation;
		}
	}

	private bool DrawPrefabMesh(ItemDrop prefab)
	{
		if (prefab == null)
		{
			return false;
		}
		bool result = false;
		Gizmos.color = Color.yellow;
		MeshFilter[] componentsInChildren = prefab.gameObject.GetComponentsInChildren<MeshFilter>();
		foreach (MeshFilter meshFilter in componentsInChildren)
		{
			if ((bool)meshFilter && (bool)meshFilter.sharedMesh)
			{
				Vector3 position = prefab.transform.position;
				Quaternion quaternion = Quaternion.Inverse(prefab.transform.rotation);
				Vector3 vector = meshFilter.transform.position - position;
				Vector3 position2 = base.transform.position + base.transform.rotation * vector;
				Quaternion quaternion2 = quaternion * meshFilter.transform.rotation;
				Quaternion rotation = base.transform.rotation * quaternion2;
				Gizmos.DrawMesh(meshFilter.sharedMesh, position2, rotation, meshFilter.transform.lossyScale);
				result = true;
			}
		}
		return result;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Piece : StaticTarget, IPlaced
{
	public enum PieceCategory
	{
		Misc = 0,
		Crafting = 1,
		BuildingWorkbench = 2,
		BuildingStonecutter = 3,
		Furniture = 4,
		Feasts = 5,
		Food = 6,
		Meads = 7,
		Max = 8,
		All = 100
	}

	public enum ComfortGroup
	{
		None,
		Fire,
		Bed,
		Banner,
		Chair,
		Table,
		Carpet
	}

	[Serializable]
	public class Requirement
	{
		[Header("Resource")]
		public ItemDrop m_resItem;

		public int m_amount = 1;

		public int m_extraAmountOnlyOneIngredient;

		[Header("Item")]
		public int m_amountPerLevel = 1;

		[Header("Piece")]
		public bool m_recover = true;

		public int GetAmount(int qualityLevel)
		{
			if (qualityLevel <= 1)
			{
				return m_amount;
			}
			return (qualityLevel - 1) * m_amountPerLevel;
		}
	}

	public bool m_targetNonPlayerBuilt = true;

	[Header("Basic stuffs")]
	public Sprite m_icon;

	public string m_name = "";

	public string m_description = "";

	public bool m_enabled = true;

	public PieceCategory m_category;

	public bool m_isUpgrade;

	[Header("Comfort")]
	public int m_comfort;

	public ComfortGroup m_comfortGroup;

	public GameObject m_comfortObject;

	[Header("Placement rules")]
	public bool m_groundPiece;

	public bool m_allowAltGroundPlacement;

	public bool m_groundOnly;

	public bool m_cultivatedGroundOnly;

	public bool m_waterPiece;

	public bool m_clipGround;

	public bool m_clipEverything;

	public bool m_noInWater;

	public bool m_notOnWood;

	public bool m_notOnTiltingSurface;

	public bool m_inCeilingOnly;

	public bool m_notOnFloor;

	public bool m_noClipping;

	public bool m_onlyInTeleportArea;

	public bool m_allowedInDungeons;

	public float m_spaceRequirement;

	public bool m_repairPiece;

	public bool m_removePiece;

	public bool m_canRotate = true;

	public bool m_randomInitBuildRotation;

	public bool m_canBeRemoved = true;

	public bool m_canRockJade;

	public bool m_allowRotatedOverlap;

	public bool m_vegetationGroundOnly;

	public List<Piece> m_blockingPieces = new List<Piece>();

	public float m_blockRadius;

	public ZNetView m_mustConnectTo;

	public float m_connectRadius;

	public bool m_mustBeAboveConnected;

	public bool m_noVines;

	public int m_extraPlacementDistance;

	[BitMask(typeof(Heightmap.Biome))]
	public Heightmap.Biome m_onlyInBiome;

	[Header("Harvest")]
	public bool m_harvest;

	public float m_harvestRadius;

	public float m_harvestRadiusMaxLevel;

	[Header("Effects")]
	public EffectList m_placeEffect = new EffectList();

	[Header("Requirements")]
	public string m_dlc = "";

	public CraftingStation m_craftingStation;

	public float m_returnResourceHeightOffset = 1f;

	public Requirement[] m_resources = Array.Empty<Requirement>();

	public GameObject m_destroyedLootPrefab;

	private ZNetView m_nview;

	private long m_creator;

	private int m_myListIndex = -1;

	private static int s_ghostLayer = 0;

	private static int s_pieceRayMask = 0;

	private static int s_harvestRayMask = 0;

	private static readonly Collider[] s_pieceColliders = new Collider[2000];

	private static readonly List<Piece> s_allPieces = new List<Piece>();

	private static readonly HashSet<Piece> s_allComfortPieces = new HashSet<Piece>();

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		s_allPieces.Add(this);
		m_myListIndex = s_allPieces.Count - 1;
		if (m_comfort > 0)
		{
			s_allComfortPieces.Add(this);
		}
		if ((bool)m_nview && m_nview.IsValid())
		{
			m_creator = m_nview.GetZDO().GetLong(ZDOVars.s_creator, 0L);
		}
		if (s_ghostLayer == 0)
		{
			s_ghostLayer = LayerMask.NameToLayer("ghost");
		}
		if (s_pieceRayMask == 0)
		{
			s_pieceRayMask = LayerMask.GetMask("piece", "piece_nonsolid");
		}
		if (s_harvestRayMask == 0)
		{
			s_harvestRayMask = LayerMask.GetMask("piece", "piece_nonsolid", "item");
		}
		if (m_harvest)
		{
			Transform transform = base.transform.Find("_GhostOnly");
			if ((object)transform != null)
			{
				float skillFactor = Player.m_localPlayer.GetSkillFactor(Skills.SkillType.Farming);
				float num = Mathf.Lerp(m_harvestRadius, m_harvestRadiusMaxLevel, skillFactor);
				transform.localScale = new Vector3(num, num, num);
			}
		}
	}

	public void OnPlaced()
	{
		if (!m_harvest)
		{
			return;
		}
		float skillFactor = Player.m_localPlayer.GetSkillFactor(Skills.SkillType.Farming);
		float radius = Mathf.Lerp(m_harvestRadius, m_harvestRadiusMaxLevel, skillFactor);
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, radius, s_pieceColliders, s_harvestRayMask);
		for (int i = 0; i < num; i++)
		{
			Pickable component = s_pieceColliders[i].gameObject.GetComponent<Pickable>();
			if ((object)component != null && component.m_harvestable && component.CanBePicked())
			{
				component.Interact(Player.m_localPlayer, repeat: false, alt: false);
			}
		}
		ZNetScene.instance.Destroy(base.gameObject);
	}

	private void OnDestroy()
	{
		if (m_myListIndex >= 0)
		{
			s_allPieces[m_myListIndex] = s_allPieces[s_allPieces.Count - 1];
			s_allPieces[m_myListIndex].m_myListIndex = m_myListIndex;
			s_allPieces.RemoveAt(s_allPieces.Count - 1);
			m_myListIndex = -1;
		}
		if (m_comfort > 0)
		{
			s_allComfortPieces.Remove(this);
		}
	}

	public bool CanBeRemoved()
	{
		Container componentInChildren = GetComponentInChildren<Container>();
		if (componentInChildren != null)
		{
			return componentInChildren.CanBeRemoved();
		}
		Ship componentInChildren2 = GetComponentInChildren<Ship>();
		if (componentInChildren2 != null)
		{
			return componentInChildren2.CanBeRemoved();
		}
		return true;
	}

	public void DropResources(HitData hitData = null)
	{
		if (ZoneSystem.instance.GetGlobalKey(FreeBuildKey()))
		{
			return;
		}
		Container container = null;
		Feast component = base.gameObject.GetComponent<Feast>();
		Requirement[] resources = m_resources;
		foreach (Requirement requirement in resources)
		{
			if (requirement.m_resItem == null || !requirement.m_recover)
			{
				continue;
			}
			GameObject itemPrefab = ObjectDB.instance.GetItemPrefab(Utils.GetPrefabName(requirement.m_resItem.name));
			int dropCount = requirement.m_amount;
			if ((bool)component)
			{
				dropCount = (int)Math.Floor((float)dropCount * component.GetStackPercentige());
			}
			if (dropCount <= 0)
			{
				continue;
			}
			itemPrefab = Game.instance.CheckDropConversion(hitData, requirement.m_resItem, itemPrefab, ref dropCount);
			if (!IsPlacedByPlayer())
			{
				dropCount = Mathf.Max(1, dropCount / 3);
			}
			if ((bool)m_destroyedLootPrefab)
			{
				while (dropCount > 0)
				{
					ItemDrop.ItemData itemData = itemPrefab.GetComponent<ItemDrop>().m_itemData.Clone();
					itemData.m_dropPrefab = itemPrefab;
					itemData.m_stack = Mathf.Min(dropCount, itemData.m_shared.m_maxStackSize);
					dropCount -= itemData.m_stack;
					if (container == null || !container.GetInventory().HaveEmptySlot())
					{
						container = UnityEngine.Object.Instantiate(m_destroyedLootPrefab, base.transform.position + Vector3.up * m_returnResourceHeightOffset, Quaternion.identity).GetComponent<Container>();
					}
					container.GetInventory().AddItem(itemData);
				}
			}
			else
			{
				while (dropCount > 0)
				{
					ItemDrop component2 = UnityEngine.Object.Instantiate(itemPrefab, base.transform.position + Vector3.up * m_returnResourceHeightOffset, Quaternion.identity).GetComponent<ItemDrop>();
					component2.SetStack(Mathf.Min(dropCount, component2.m_itemData.m_shared.m_maxStackSize));
					ItemDrop.OnCreateNew(component2);
					dropCount -= component2.m_itemData.m_stack;
				}
			}
		}
	}

	public override bool IsPriorityTarget()
	{
		if (!base.IsPriorityTarget())
		{
			return false;
		}
		if (!m_targetNonPlayerBuilt)
		{
			return IsPlacedByPlayer();
		}
		return true;
	}

	public override bool IsRandomTarget()
	{
		if (!base.IsRandomTarget())
		{
			return false;
		}
		if (!m_targetNonPlayerBuilt)
		{
			return IsPlacedByPlayer();
		}
		return true;
	}

	public void SetCreator(long uid)
	{
		if (!(m_nview == null) && m_nview.IsOwner() && GetCreator() == 0L)
		{
			m_creator = uid;
			m_nview.GetZDO().Set(ZDOVars.s_creator, uid);
		}
	}

	public long GetCreator()
	{
		return m_creator;
	}

	public bool IsCreator()
	{
		long creator = GetCreator();
		long playerID = Game.instance.GetPlayerProfile().GetPlayerID();
		return creator == playerID;
	}

	public bool IsPlacedByPlayer()
	{
		return GetCreator() != 0;
	}

	public void SetInvalidPlacementHeightlight(bool enabled)
	{
		if (enabled)
		{
			MaterialMan.instance.SetValue(base.gameObject, ShaderProps._Color, Color.red);
			MaterialMan.instance.SetValue(base.gameObject, ShaderProps._EmissionColor, Color.red * 0.7f);
		}
		else
		{
			MaterialMan.instance.ResetValue(base.gameObject, ShaderProps._Color);
			MaterialMan.instance.ResetValue(base.gameObject, ShaderProps._EmissionColor);
		}
	}

	public static void GetSnapPoints(Vector3 point, float radius, List<Transform> points, List<Piece> pieces)
	{
		int num = Physics.OverlapSphereNonAlloc(point, radius, s_pieceColliders, s_pieceRayMask);
		for (int i = 0; i < num; i++)
		{
			Piece componentInParent = s_pieceColliders[i].GetComponentInParent<Piece>();
			if (componentInParent != null)
			{
				componentInParent.GetSnapPoints(points);
				pieces.Add(componentInParent);
			}
		}
	}

	public static void GetAllPiecesInRadius(Vector3 p, float radius, List<Piece> pieces)
	{
		foreach (Piece s_allPiece in s_allPieces)
		{
			if (s_allPiece.gameObject.layer != s_ghostLayer && Vector3.Distance(p, s_allPiece.transform.position) < radius)
			{
				pieces.Add(s_allPiece);
			}
		}
	}

	public static void GetAllComfortPiecesInRadius(Vector3 p, float radius, List<Piece> pieces)
	{
		foreach (Piece s_allComfortPiece in s_allComfortPieces)
		{
			if (s_allComfortPiece.gameObject.layer != s_ghostLayer && Vector3.Distance(p, s_allComfortPiece.transform.position) < radius)
			{
				pieces.Add(s_allComfortPiece);
			}
		}
	}

	public void GetSnapPoints(List<Transform> points)
	{
		for (int i = 0; i < base.transform.childCount; i++)
		{
			Transform child = base.transform.GetChild(i);
			if (child.CompareTag("snappoint"))
			{
				points.Add(child);
			}
		}
	}

	public GlobalKeys FreeBuildKey()
	{
		if (GetComponent<ItemDrop>() != null || GetComponent<Feast>() != null)
		{
			return GlobalKeys.NoCraftCost;
		}
		return GlobalKeys.NoBuildCost;
	}

	public int GetComfort()
	{
		if (m_comfortObject != null && !m_comfortObject.activeInHierarchy)
		{
			return 0;
		}
		return m_comfort;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class PieceTable : MonoBehaviour
{
	public const int m_gridWidth = 15;

	public const int m_gridHeight = 6;

	public List<GameObject> m_pieces = new List<GameObject>();

	public List<Piece.PieceCategory> m_categories = new List<Piece.PieceCategory>();

	public List<string> m_categoryLabels = new List<string>();

	public bool m_canRemovePieces = true;

	public bool m_canRemoveFeasts;

	public Skills.SkillType m_skill;

	[NonSerialized]
	private List<List<Piece>> m_availablePieces = new List<List<Piece>>();

	private Piece.PieceCategory m_selectedCategory = Piece.PieceCategory.Max;

	[NonSerialized]
	public Vector2Int[] m_selectedPiece = new Vector2Int[8];

	[NonSerialized]
	public Vector2Int[] m_lastSelectedPiece = new Vector2Int[8];

	[HideInInspector]
	public List<Piece.PieceCategory> m_categoriesFolded = new List<Piece.PieceCategory>();

	public void UpdateAvailable(HashSet<string> knownRecipies, Player player, bool hideUnavailable, bool noPlacementCost)
	{
		if (m_availablePieces.Count == 0)
		{
			for (int i = 0; i < 8; i++)
			{
				m_availablePieces.Add(new List<Piece>());
			}
		}
		foreach (List<Piece> availablePiece in m_availablePieces)
		{
			availablePiece.Clear();
		}
		foreach (GameObject piece in m_pieces)
		{
			Piece component = piece.GetComponent<Piece>();
			bool flag = player.CurrentSeason != null && player.CurrentSeason.Pieces.Contains(piece);
			if ((!noPlacementCost || component.m_canRockJade) && (!knownRecipies.Contains(component.m_name) || !(component.m_enabled || flag) || (hideUnavailable && !player.HaveRequirements(component, Player.RequirementMode.CanAlmostBuild))))
			{
				continue;
			}
			if (component.m_category == Piece.PieceCategory.All)
			{
				for (int j = 0; j < 8; j++)
				{
					m_availablePieces[j].Add(component);
				}
			}
			else
			{
				m_availablePieces[(int)component.m_category].Add(component);
			}
		}
	}

	public GameObject GetSelectedPrefab()
	{
		Piece selectedPiece = GetSelectedPiece();
		if ((bool)selectedPiece)
		{
			return selectedPiece.gameObject;
		}
		return null;
	}

	public Piece GetPiece(Piece.PieceCategory category, Vector2Int p)
	{
		if (m_availablePieces.Count == 0)
		{
			return null;
		}
		int num = (int)category;
		if (num >= m_availablePieces.Count)
		{
			num = 0;
		}
		if (m_availablePieces[num].Count == 0)
		{
			return null;
		}
		int num2 = p.y * 15 + p.x;
		if (num2 < 0 || num2 >= m_availablePieces[num].Count)
		{
			return null;
		}
		return m_availablePieces[num][num2];
	}

	public Piece GetPiece(Vector2Int p)
	{
		return GetPiece(GetSelectedCategory(), p);
	}

	public bool IsPieceAvailable(Piece piece)
	{
		foreach (Piece item in m_availablePieces[(int)GetSelectedCategory()])
		{
			if (item == piece)
			{
				return true;
			}
		}
		return false;
	}

	public Piece.PieceCategory GetSelectedCategory()
	{
		if (m_selectedCategory == Piece.PieceCategory.Max)
		{
			if (m_categories.Count == 0)
			{
				return Piece.PieceCategory.Misc;
			}
			m_selectedCategory = m_categories[0];
		}
		return m_selectedCategory;
	}

	public Piece GetSelectedPiece()
	{
		Vector2Int selectedIndex = GetSelectedIndex();
		return GetPiece(GetSelectedCategory(), selectedIndex);
	}

	public int GetAvailablePiecesInCategory(Piece.PieceCategory cat)
	{
		return m_availablePieces[Mathf.Min(m_availablePieces.Count - 1, (int)cat)].Count;
	}

	public List<Piece> GetPiecesInSelectedCategory()
	{
		return m_availablePieces[(int)GetSelectedCategory()];
	}

	public int GetAvailablePiecesInSelectedCategory()
	{
		return GetAvailablePiecesInCategory(GetSelectedCategory());
	}

	public Vector2Int GetSelectedIndex()
	{
		return m_selectedPiece[Mathf.Min((int)GetSelectedCategory(), m_selectedPiece.Length - 1)];
	}

	public bool GetPieceIndex(Piece p, out Vector2Int index, out int category)
	{
		string prefabName = Utils.GetPrefabName(p.gameObject);
		for (int i = 0; i < m_availablePieces.Count; i++)
		{
			for (int j = 0; j < m_availablePieces[i].Count; j++)
			{
				Piece piece = m_availablePieces[i][j];
				if (!(Utils.GetPrefabName(piece.gameObject) == prefabName))
				{
					continue;
				}
				category = -1;
				for (int k = 0; k < m_categories.Count; k++)
				{
					if (piece.m_category == m_categories[k])
					{
						category = k;
						break;
					}
				}
				if (category >= 0)
				{
					index = new Vector2Int(j % 15, (j - j % 15) / 15);
					return true;
				}
				index = Vector2Int.zero;
				return false;
			}
		}
		index = Vector2Int.zero;
		category = -1;
		return false;
	}

	public void SetSelected(Vector2Int p)
	{
		m_selectedPiece[(int)GetSelectedCategory()] = p;
	}

	public void LeftPiece()
	{
		if (m_availablePieces[(int)GetSelectedCategory()].Count > 1)
		{
			Vector2Int vector2Int = m_selectedPiece[(int)GetSelectedCategory()];
			int x = vector2Int.x - 1;
			vector2Int.x = x;
			if (vector2Int.x < 0)
			{
				vector2Int.x = 14;
			}
			m_selectedPiece[(int)GetSelectedCategory()] = vector2Int;
		}
	}

	public void RightPiece()
	{
		if (m_availablePieces[(int)GetSelectedCategory()].Count > 1)
		{
			Vector2Int vector2Int = m_selectedPiece[(int)GetSelectedCategory()];
			int x = vector2Int.x + 1;
			vector2Int.x = x;
			if (vector2Int.x >= 15)
			{
				vector2Int.x = 0;
			}
			m_selectedPiece[(int)GetSelectedCategory()] = vector2Int;
		}
	}

	public void DownPiece()
	{
		if (m_availablePieces[(int)GetSelectedCategory()].Count > 1)
		{
			Vector2Int vector2Int = m_selectedPiece[(int)GetSelectedCategory()];
			int y = vector2Int.y + 1;
			vector2Int.y = y;
			if (vector2Int.y >= 6)
			{
				vector2Int.y = 0;
			}
			m_selectedPiece[(int)GetSelectedCategory()] = vector2Int;
		}
	}

	public void UpPiece()
	{
		if (m_availablePieces[(int)GetSelectedCategory()].Count > 1)
		{
			Vector2Int vector2Int = m_selectedPiece[(int)GetSelectedCategory()];
			int y = vector2Int.y - 1;
			vector2Int.y = y;
			if (vector2Int.y < 0)
			{
				vector2Int.y = 5;
			}
			m_selectedPiece[(int)GetSelectedCategory()] = vector2Int;
		}
	}

	public void NextCategory()
	{
		if (m_categories.Count == 0)
		{
			return;
		}
		for (int num = m_categories.Count - 1; num >= 0; num--)
		{
			if (m_categories[num] == GetSelectedCategory())
			{
				if (num + 1 == m_categories.Count)
				{
					m_selectedCategory = m_categories[0];
				}
				else
				{
					m_selectedCategory = m_categories[num + 1];
				}
				break;
			}
		}
	}

	public void PrevCategory()
	{
		if (m_categories.Count == 0)
		{
			return;
		}
		for (int i = 0; i < m_categories.Count; i++)
		{
			if (m_categories[i] == GetSelectedCategory())
			{
				if (i - 1 < 0)
				{
					m_selectedCategory = m_categories[m_categories.Count - 1];
				}
				else
				{
					m_selectedCategory = m_categories[i - 1];
				}
				break;
			}
		}
	}

	public void SetCategory(int index)
	{
		if (m_categories.Count != 0)
		{
			m_selectedCategory = m_categories[index];
		}
	}
}
using System;
using UnityEngine;

public class Plant : SlowUpdate, Hoverable
{
	public enum Status
	{
		Healthy,
		NoSun,
		NoSpace,
		WrongBiome,
		NotCultivated,
		NoAttachPiece,
		TooHot,
		TooCold
	}

	private static Collider[] s_colliders = new Collider[30];

	private static Collider[] s_hits = new Collider[10];

	public string m_name = "Plant";

	public float m_growTime = 10f;

	public float m_growTimeMax = 2000f;

	public GameObject[] m_grownPrefabs = new GameObject[0];

	public float m_minScale = 1f;

	public float m_maxScale = 1f;

	public float m_growRadius = 1f;

	public float m_growRadiusVines;

	public bool m_needCultivatedGround;

	public bool m_destroyIfCantGrow;

	public bool m_tolerateHeat;

	public bool m_tolerateCold;

	[SerializeField]
	private GameObject m_healthy;

	[SerializeField]
	private GameObject m_unhealthy;

	[SerializeField]
	private GameObject m_healthyGrown;

	[SerializeField]
	private GameObject m_unhealthyGrown;

	[BitMask(typeof(Heightmap.Biome))]
	public Heightmap.Biome m_biome;

	public EffectList m_growEffect = new EffectList();

	[Header("Attach to buildpiece (Vines)")]
	public float m_attachDistance;

	private Status m_status;

	private ZNetView m_nview;

	private float m_updateTime;

	private float m_spawnTime;

	private int m_seed;

	private Vector3 m_attachPos;

	private Vector3 m_attachNormal;

	private Quaternion m_attachRot;

	private Collider m_attachCollider;

	private static int m_spaceMask = 0;

	private static int m_roofMask = 0;

	private static int m_pieceMask = 0;

	public override void Awake()
	{
		base.Awake();
		m_nview = base.gameObject.GetComponent<ZNetView>();
		if (m_nview.GetZDO() != null)
		{
			m_seed = m_nview.GetZDO().GetInt(ZDOVars.s_seed);
			if (m_seed == 0)
			{
				m_seed = (int)(m_nview.GetZDO().m_uid.ID + m_nview.GetZDO().m_uid.UserID);
				m_nview.GetZDO().Set(ZDOVars.s_seed, m_seed, okForNotOwner: true);
			}
			if (m_nview.IsOwner() && m_nview.GetZDO().GetLong(ZDOVars.s_plantTime, 0L) == 0L)
			{
				m_nview.GetZDO().Set(ZDOVars.s_plantTime, ZNet.instance.GetTime().Ticks);
			}
			m_spawnTime = Time.time;
		}
	}

	private void Start()
	{
		m_updateTime = Time.time + 10f;
	}

	public string GetHoverText()
	{
		return m_status switch
		{
			Status.Healthy => Localization.instance.Localize(m_name + " ( $piece_plant_healthy )"), 
			Status.NoSpace => Localization.instance.Localize(m_name + " ( $piece_plant_nospace )"), 
			Status.NoSun => Localization.instance.Localize(m_name + " ( $piece_plant_nosun )"), 
			Status.WrongBiome => Localization.instance.Localize(m_name + " ( $piece_plant_wrongbiome )"), 
			Status.NotCultivated => Localization.instance.Localize(m_name + " ( $piece_plant_notcultivated )"), 
			Status.TooHot => Localization.instance.Localize(m_name + " ( $piece_plant_toohot )"), 
			Status.TooCold => Localization.instance.Localize(m_name + " ( $piece_plant_toocold )"), 
			Status.NoAttachPiece => Localization.instance.Localize(m_name + " ( $piece_plant_nowall )"), 
			_ => "", 
		};
	}

	public string GetHoverName()
	{
		return Localization.instance.Localize(m_name);
	}

	private double TimeSincePlanted()
	{
		DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_plantTime, ZNet.instance.GetTime().Ticks));
		return (ZNet.instance.GetTime() - dateTime).TotalSeconds;
	}

	public override void SUpdate(float time, Vector2i referenceZone)
	{
		if (m_nview.IsValid() && !(time > m_updateTime))
		{
			m_updateTime = time + 10f;
			double num = TimeSincePlanted();
			UpdateHealth(num);
			float growTime = GetGrowTime();
			if ((bool)m_healthyGrown)
			{
				bool flag = num > (double)(growTime * 0.5f);
				m_healthy.SetActive(!flag && m_status == Status.Healthy);
				m_unhealthy.SetActive(!flag && m_status != Status.Healthy);
				m_healthyGrown.SetActive(flag && m_status == Status.Healthy);
				m_unhealthyGrown.SetActive(flag && m_status != Status.Healthy);
			}
			else
			{
				m_healthy.SetActive(m_status == Status.Healthy);
				m_unhealthy.SetActive(m_status != Status.Healthy);
			}
			if (m_nview.IsOwner() && time - m_spawnTime > 10f && num > (double)growTime)
			{
				Grow();
			}
		}
	}

	private float GetGrowTime()
	{
		UnityEngine.Random.State state = UnityEngine.Random.state;
		UnityEngine.Random.InitState(m_seed);
		float value = UnityEngine.Random.value;
		UnityEngine.Random.state = state;
		return Mathf.Lerp(m_growTime, m_growTimeMax, value);
	}

	public GameObject Grow()
	{
		if (m_status != Status.Healthy)
		{
			if (m_destroyIfCantGrow)
			{
				Destroy();
			}
			return null;
		}
		float num = 11.25f;
		GameObject original = m_grownPrefabs[UnityEngine.Random.Range(0, m_grownPrefabs.Length)];
		GameObject gameObject = null;
		Vector3 position = ((m_attachDistance > 0f) ? m_attachPos : base.transform.position);
		Quaternion quaternion = ((m_attachDistance > 0f) ? m_attachRot : Quaternion.Euler(base.transform.rotation.eulerAngles.x, base.transform.rotation.eulerAngles.y + UnityEngine.Random.Range(0f - num, num), base.transform.rotation.eulerAngles.z));
		gameObject = UnityEngine.Object.Instantiate(original, position, quaternion);
		if (m_attachDistance > 0f)
		{
			PlaceAgainst(gameObject, m_attachRot, m_attachPos, m_attachNormal);
		}
		Quaternion quaternion2 = quaternion;
		ZLog.Log("Starting to grow plant with rotation: " + quaternion2.ToString());
		ZNetView component = gameObject.GetComponent<ZNetView>();
		float num2 = UnityEngine.Random.Range(m_minScale, m_maxScale);
		component.SetLocalScale(new Vector3(num2, num2, num2));
		gameObject.GetComponent<TreeBase>()?.Grow();
		if ((bool)m_nview)
		{
			m_nview.Destroy();
			m_growEffect.Create(base.transform.position, quaternion, null, num2);
		}
		return gameObject;
	}

	public void UpdateHealth(double timeSincePlanted)
	{
		if (timeSincePlanted < 10.0)
		{
			m_status = Status.Healthy;
			return;
		}
		Heightmap heightmap = Heightmap.FindHeightmap(base.transform.position);
		if ((bool)heightmap)
		{
			Heightmap.Biome biome = heightmap.GetBiome(base.transform.position);
			if ((biome & m_biome) == 0)
			{
				m_status = Status.WrongBiome;
				return;
			}
			if (m_needCultivatedGround && !heightmap.IsCultivated(base.transform.position))
			{
				m_status = Status.NotCultivated;
				return;
			}
			if (!m_tolerateHeat && biome == Heightmap.Biome.AshLands && !ShieldGenerator.IsInsideShield(base.transform.position))
			{
				m_status = Status.TooHot;
				return;
			}
			if (!m_tolerateCold && (biome == Heightmap.Biome.DeepNorth || biome == Heightmap.Biome.Mountain) && !ShieldGenerator.IsInsideShield(base.transform.position))
			{
				m_status = Status.TooCold;
				return;
			}
		}
		if (HaveRoof())
		{
			m_status = Status.NoSun;
		}
		else if (!HaveGrowSpace())
		{
			m_status = Status.NoSpace;
		}
		else if (m_attachDistance > 0f && !GetClosestAttachPosRot(out m_attachPos, out m_attachRot, out m_attachNormal))
		{
			m_status = Status.NoAttachPiece;
		}
		else
		{
			m_status = Status.Healthy;
		}
	}

	public Collider GetClosestAttachObject()
	{
		return GetClosestAttachObject(base.transform.position);
	}

	public Collider GetClosestAttachObject(Vector3 from)
	{
		if (m_pieceMask == 0)
		{
			m_pieceMask = LayerMask.GetMask("piece");
		}
		int num = Physics.OverlapSphereNonAlloc(from, m_attachDistance, s_hits, m_pieceMask);
		Collider result = null;
		float num2 = float.MaxValue;
		for (int i = 0; i < num; i++)
		{
			Collider collider = s_hits[i];
			float num3 = Vector3.Distance(from, collider.bounds.center);
			if (num3 < num2)
			{
				Piece componentInParent = collider.GetComponentInParent<Piece>();
				if ((object)componentInParent != null && !componentInParent.m_noVines)
				{
					result = collider;
					num2 = num3;
				}
			}
		}
		return result;
	}

	public bool GetClosestAttachPosRot(out Vector3 pos, out Quaternion rot, out Vector3 normal)
	{
		return GetClosestAttachPosRot(base.transform.position, out pos, out rot, out normal);
	}

	public bool GetClosestAttachPosRot(Vector3 from, out Vector3 pos, out Quaternion rot, out Vector3 normal)
	{
		Collider closestAttachObject = GetClosestAttachObject(from);
		if ((object)closestAttachObject != null)
		{
			if (m_pieceMask == 0)
			{
				m_pieceMask = LayerMask.GetMask("piece");
			}
			if (from.y < closestAttachObject.bounds.min.y)
			{
				from.y += closestAttachObject.bounds.min.y - from.y + 0.01f;
			}
			if (from.y > closestAttachObject.bounds.max.y)
			{
				from.y += closestAttachObject.bounds.max.y - from.y - 0.01f;
			}
			Vector3 vector = closestAttachObject.ClosestPoint(from);
			if (Physics.Raycast(from, vector - from, out var hitInfo, 50f, m_pieceMask) && (bool)hitInfo.collider && !hitInfo.collider.attachedRigidbody)
			{
				pos = hitInfo.point;
				rot = Quaternion.Euler(0f, 90f, 0f) * Quaternion.LookRotation(hitInfo.normal);
				normal = hitInfo.normal;
				Terminal.Log("Plant found grow normal: " + hitInfo.normal.ToString());
				return true;
			}
			Terminal.Log("Plant ray didn't hit any valid colliders");
		}
		pos = (normal = Vector3.zero);
		rot = Quaternion.identity;
		Terminal.Log("Plant found no attach obj.");
		return false;
	}

	public void PlaceAgainst(GameObject obj, Quaternion rot, Vector3 hitPos, Vector3 hitNormal)
	{
		obj.transform.position = hitPos + hitNormal * 50f;
		obj.transform.rotation = rot;
		Vector3 vector = Vector3.zero;
		float num = 999999f;
		Collider[] componentsInChildren = obj.GetComponentsInChildren<Collider>();
		foreach (Collider collider in componentsInChildren)
		{
			if (collider.isTrigger || !collider.enabled)
			{
				continue;
			}
			MeshCollider meshCollider = collider as MeshCollider;
			if (!(meshCollider != null) || meshCollider.convex)
			{
				Vector3 vector2 = collider.ClosestPoint(hitPos);
				float num2 = Vector3.Distance(vector2, hitPos);
				if (num2 < num)
				{
					vector = vector2;
					num = num2;
				}
			}
		}
		Vector3 vector3 = obj.transform.position - vector;
		obj.transform.position = hitPos + vector3;
		obj.transform.rotation = rot;
	}

	private void Destroy()
	{
		IDestructible component = GetComponent<IDestructible>();
		if (component != null)
		{
			HitData hitData = new HitData();
			hitData.m_damage.m_damage = 9999f;
			component.Damage(hitData);
		}
	}

	private bool HaveRoof()
	{
		if (m_roofMask == 0)
		{
			m_roofMask = LayerMask.GetMask("Default", "static_solid", "piece");
		}
		if (Physics.Raycast(base.transform.position, Vector3.up, 100f, m_roofMask))
		{
			return true;
		}
		return false;
	}

	private bool HaveGrowSpace()
	{
		if (m_spaceMask == 0)
		{
			m_spaceMask = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece", "piece_nonsolid");
		}
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, m_growRadius, s_colliders, m_spaceMask);
		for (int i = 0; i < num; i++)
		{
			Plant component = s_colliders[i].GetComponent<Plant>();
			if (!component || (!(component == this) && component.GetStatus() == Status.Healthy))
			{
				return false;
			}
		}
		if (m_growRadiusVines > 0f)
		{
			num = Physics.OverlapSphereNonAlloc(base.transform.position, m_growRadiusVines, s_colliders, m_spaceMask);
			for (int j = 0; j < num; j++)
			{
				if (s_colliders[j].GetComponentInParent<Vine>() != null)
				{
					return false;
				}
			}
		}
		return true;
	}

	public Status GetStatus()
	{
		return m_status;
	}
}
