			{
				num = !ZInput.GetButton("JoyAltKeys");
				goto IL_0289;
			}
			goto IL_02d6;
		}
		goto IL_0496;
		IL_028b:
		if (GetRightItem() != null || GetLeftItem() != null)
		{
			if (!InAttack() && !InDodge())
			{
