		else if (!m_knownTexts.ContainsKey(label.Replace("\u0016", "")))
		{
			m_knownTexts.Add(label, text);
			Message(MessageHud.MessageType.TopLeft, Localization.instance.Localize("$msg_newtext", label), 0, m_textIcon);
		}
