	protected override void DoDamageCameraShake(HitData hit)
	{
		float totalStaggerDamage = hit.m_damage.GetTotalStaggerDamage();
		if ((bool)GameCamera.instance && totalStaggerDamage > 0f)
		{
			float num = Mathf.Clamp01(totalStaggerDamage / GetMaxHealth());
			GameCamera.instance.AddShake(base.transform.position, 50f, m_baseCameraShake * num, continous: false);
		}
	}

	protected override void DamageArmorDurability(HitData hit)
	{
		List<ItemDrop.ItemData> list = new List<ItemDrop.ItemData>();
		if (m_chestItem != null)
		{
			list.Add(m_chestItem);
		}
		if (m_legItem != null)
		{
			list.Add(m_legItem);
		}
		if (m_helmetItem != null)
		{
			list.Add(m_helmetItem);
		}
		if (m_shoulderItem != null)
		{
			list.Add(m_shoulderItem);
		}
		if (list.Count != 0)
		{
			float num = hit.GetTotalPhysicalDamage() + hit.GetTotalElementalDamage();
			if (!(num <= 0f))
			{
				int index = UnityEngine.Random.Range(0, list.Count);
				ItemDrop.ItemData itemData = list[index];
				itemData.m_durability = Mathf.Max(0f, itemData.m_durability - num);
			}
		}
	}

	protected override bool ToggleEquipped(ItemDrop.ItemData item)
	{
		if (!item.IsEquipable())
		{
			return false;
		}
		if (InAttack())
		{
			return true;
		}
		if (item.m_shared.m_equipDuration <= 0f)
		{
			if (IsItemEquiped(item))
			{
				UnequipItem(item);
			}
			else
			{
				EquipItem(item);
			}
		}
		else if (IsItemEquiped(item))
		{
			QueueUnequipAction(item);
		}
		else
		{
			QueueEquipAction(item);
		}
		return true;
	}

	public void GetActionProgress(out string name, out float progress, out MinorActionData data)
	{
		if (TryGetFirstElementProgress(out var firstElement, out var progress2))
		{
			data = firstElement;
			name = firstElement.m_progressText;
			progress = progress2;
		}
		else
		{
			data = null;
			name = null;
			progress = 0f;
		}
	}

	public void GetActionProgress(out string name, out float progress)
	{
		GetActionProgress(out name, out progress, out var _);
	}

	private bool TryGetFirstElementProgress(out MinorActionData firstElement, out float progress)
	{
		firstElement = null;
		progress = 0f;
		if (m_actionQueue.Count > 0)
		{
			firstElement = m_actionQueue[0];
			if (firstElement.m_duration > 0f)
			{
				progress = Mathf.Clamp01(firstElement.m_time / firstElement.m_duration);
			}
			return true;
		}
		return false;
	}

	public int GetActionQueueCount()
	{
		return m_actionQueue.Count;
	}

	private void UpdateActionQueue(float dt)
	{
		if (m_actionQueuePause > 0f)
		{
			m_actionQueuePause -= dt;
			if (m_actionAnimation != null)
			{
				m_zanim.SetBool(m_actionAnimation, value: false);
				m_actionAnimation = null;
			}
			return;
		}
		if (InAttack())
		{
			if (m_actionAnimation != null)
			{
				m_zanim.SetBool(m_actionAnimation, value: false);
				m_actionAnimation = null;
			}
			return;
		}
		if (m_actionQueue.Count == 0)
		{
			if (m_actionAnimation != null)
			{
				m_zanim.SetBool(m_actionAnimation, value: false);
				m_actionAnimation = null;
			}
			return;
		}
		MinorActionData minorActionData = m_actionQueue[0];
		if (m_actionAnimation != null && m_actionAnimation != minorActionData.m_animation)
		{
			m_zanim.SetBool(m_actionAnimation, value: false);
			m_actionAnimation = null;
		}
		m_zanim.SetBool(minorActionData.m_animation, value: true);
		m_actionAnimation = minorActionData.m_animation;
		if (minorActionData.m_time == 0f && minorActionData.m_startEffect != null)
		{
			minorActionData.m_startEffect.Create(base.transform.position, Quaternion.identity);
		}
		if (minorActionData.m_staminaDrain > 0f)
		{
			UseStamina(minorActionData.m_staminaDrain * dt);
		}
		if (minorActionData.m_eitrDrain > 0f)
		{
			UseEitr(minorActionData.m_eitrDrain * dt);
		}
		minorActionData.m_time += dt;
		if (minorActionData.m_time > minorActionData.m_duration)
		{
			m_actionQueue.RemoveAt(0);
			m_zanim.SetBool(m_actionAnimation, value: false);
			m_actionAnimation = null;
			if (!string.IsNullOrEmpty(minorActionData.m_doneAnimation))
			{
				m_zanim.SetTrigger(minorActionData.m_doneAnimation);
			}
			switch (minorActionData.m_type)
			{
			case MinorActionData.ActionType.Equip:
				EquipItem(minorActionData.m_item);
				break;
			case MinorActionData.ActionType.Unequip:
				UnequipItem(minorActionData.m_item);
				break;
			case MinorActionData.ActionType.Reload:
				SetWeaponLoaded(minorActionData.m_item);
				break;
			}
			m_actionQueuePause = 0.3f;
		}
	}

	private void QueueEquipAction(ItemDrop.ItemData item)
	{
		if (item == null)
		{
			return;
		}
		if (IsEquipActionQueued(item))
		{
			RemoveEquipAction(item);
			return;
		}
		CancelReloadAction();
		MinorActionData minorActionData = new MinorActionData();
		minorActionData.m_item = item;
		minorActionData.m_type = MinorActionData.ActionType.Equip;
		minorActionData.m_duration = item.m_shared.m_equipDuration;
		minorActionData.m_progressText = "$hud_equipping " + item.m_shared.m_name;
		minorActionData.m_animation = "equipping";
		if (minorActionData.m_duration >= 1f)
		{
			minorActionData.m_startEffect = m_equipStartEffects;
		}
		m_actionQueue.Add(minorActionData);
	}

	private void QueueUnequipAction(ItemDrop.ItemData item)
	{
		if (item != null)
		{
			if (IsEquipActionQueued(item))
			{
				RemoveEquipAction(item);
				return;
			}
			CancelReloadAction();
			MinorActionData minorActionData = new MinorActionData();
			minorActionData.m_item = item;
			minorActionData.m_type = MinorActionData.ActionType.Unequip;
			minorActionData.m_duration = item.m_shared.m_equipDuration;
			minorActionData.m_progressText = "$hud_unequipping " + item.m_shared.m_name;
			minorActionData.m_animation = "equipping";
			m_actionQueue.Add(minorActionData);
		}
	}

	private void QueueReloadAction()
	{
		if (!IsReloadActionQueued())
		{
			ItemDrop.ItemData currentWeapon = GetCurrentWeapon();
			if (currentWeapon != null && currentWeapon.m_shared.m_attack.m_requiresReload)
			{
				MinorActionData minorActionData = new MinorActionData();
				minorActionData.m_item = currentWeapon;
				minorActionData.m_type = MinorActionData.ActionType.Reload;
				minorActionData.m_duration = currentWeapon.GetWeaponLoadingTime();
				minorActionData.m_progressText = "$hud_reloading " + currentWeapon.m_shared.m_name;
				minorActionData.m_animation = currentWeapon.m_shared.m_attack.m_reloadAnimation;
				minorActionData.m_doneAnimation = currentWeapon.m_shared.m_attack.m_reloadAnimation + "_done";
				minorActionData.m_staminaDrain = currentWeapon.m_shared.m_attack.m_reloadStaminaDrain;
				minorActionData.m_eitrDrain = currentWeapon.m_shared.m_attack.m_reloadEitrDrain;
				m_actionQueue.Add(minorActionData);
			}
		}
	}

	protected override void ClearActionQueue()
	{
		m_actionQueue.Clear();
	}

	public override void RemoveEquipAction(ItemDrop.ItemData item)
	{
		if (item == null)
		{
			return;
		}
		foreach (MinorActionData item2 in m_actionQueue)
		{
			if (item2.m_item == item)
			{
				m_actionQueue.Remove(item2);
				break;
			}
		}
	}

	public bool IsEquipActionQueued(ItemDrop.ItemData item)
	{
		if (item == null)
		{
			return false;
		}
		foreach (MinorActionData item2 in m_actionQueue)
		{
			if ((item2.m_type == MinorActionData.ActionType.Equip || item2.m_type == MinorActionData.ActionType.Unequip) && item2.m_item == item)
			{
				return true;
			}
		}
		return false;
	}

	private bool IsReloadActionQueued()
	{
		foreach (MinorActionData item in m_actionQueue)
		{
			if (item.m_type == MinorActionData.ActionType.Reload)
			{
				return true;
			}
		}
		return false;
	}

	public void ResetCharacter()
	{
		m_guardianPowerCooldown = 0f;
		ResetSeenTutorials();
		m_knownRecipes.Clear();
		m_knownStations.Clear();
		m_knownMaterial.Clear();
		m_uniques.Clear();
		m_trophies.Clear();
		m_skills.Clear();
		m_knownBiome.Clear();
		m_knownTexts.Clear();
	}

	public void ResetCharacterKnownItems()
	{
		m_knownRecipes.Clear();
		m_knownStations.Clear();
		m_knownMaterial.Clear();
		m_trophies.Clear();
	}

	public bool ToggleDebugFly()
	{
		m_debugFly = !m_debugFly;
		m_nview.GetZDO().Set(ZDOVars.s_debugFly, m_debugFly);
		Message(MessageHud.MessageType.TopLeft, "Debug fly:" + m_debugFly);
		return m_debugFly;
	}

	public void SetNoPlacementCost(bool value)
	{
		if (value != m_noPlacementCost)
		{
			ToggleNoPlacementCost();
		}
	}

	public bool ToggleNoPlacementCost()
	{
		m_noPlacementCost = !m_noPlacementCost;
		Message(MessageHud.MessageType.TopLeft, "No placement cost:" + m_noPlacementCost);
		UpdateAvailablePiecesList();
		return m_noPlacementCost;
	}

	public bool IsKnownMaterial(string name)
	{
		return m_knownMaterial.Contains(name);
	}
}
using UnityEngine;
using Valheim.SettingsGui;

public class PlayerController : MonoBehaviour
{
	private bool m_run;

	private bool m_runToggled;

	private bool m_lastRunPressed;

	private float m_lastMagnitude;

	private bool m_runPressedWhileStamina = true;

	private static float takeInputDelay = 0f;

	private Player m_character;

	private ZNetView m_nview;

	public static Vector2 cameraDirectionLock = Vector2.zero;

	public static float m_mouseSens = 1f;

	public static float m_gamepadSens = 1f;

	public static bool m_invertMouse = false;

	public static bool m_invertCameraY = false;

	public static bool m_invertCameraX = false;

	public float m_minDodgeTime = 0.2f;

	private bool m_attackWasPressed;

	private bool m_secondAttackWasPressed;

	private bool m_blockWasPressed;

	private bool m_lastJump;

	private bool m_lastCrouch;

	public static bool HasInputDelay => takeInputDelay > 0f;

	private void Awake()
	{
		m_character = GetComponent<Player>();
		m_nview = GetComponent<ZNetView>();
		if (m_nview.GetZDO() == null)
		{
			base.enabled = false;
			return;
		}
		if (!PlatformPrefs.HasKey("MouseSensitivity"))
		{
			KeyboardMouseSettings.SetPlatformSpecificFirstTimeSettings();
		}
		m_mouseSens = PlatformPrefs.GetFloat("MouseSensitivity", m_mouseSens);
		m_gamepadSens = PlatformPrefs.GetFloat("GamepadSensitivity", m_gamepadSens);
		m_invertMouse = PlatformPrefs.GetInt("InvertMouse") == 1;
		m_invertCameraY = PlatformPrefs.GetInt("InvertCameraY", m_invertMouse ? 1 : 0) == 1;
		m_invertCameraX = PlatformPrefs.GetInt("InvertCameraX") == 1;
	}

	private void FixedUpdate()
	{
		takeInputDelay = Mathf.Max(0f, takeInputDelay - Time.deltaTime);
		if ((bool)m_nview && !m_nview.IsOwner())
		{
			return;
		}
		if (!TakeInput())
		{
			m_character.SetControls(Vector3.zero, attack: false, attackHold: false, secondaryAttack: false, secondaryAttackHold: false, block: false, blockHold: false, jump: false, crouch: false, run: false, autoRun: false);
			return;
		}
		bool flag = InInventoryEtc();
		bool flag2 = Hud.IsPieceSelectionVisible();
		bool flag3 = (ZInput.GetButton("SecondaryAttack") || ZInput.GetButton("JoySecondaryAttack")) && !flag && !Hud.InRadial();
		Vector3 zero = Vector3.zero;
		if (ZInput.GetButton("Forward"))
		{
			zero.z += 1f;
		}
		if (ZInput.GetButton("Backward"))
		{
			zero.z -= 1f;
		}
		if (ZInput.GetButton("Left"))
		{
			zero.x -= 1f;
		}
		if (ZInput.GetButton("Right"))
		{
			zero.x += 1f;
		}
		zero.x += ZInput.GetJoyLeftStickX();
		zero.z += 0f - ZInput.GetJoyLeftStickY();
		if (zero.magnitude > 1f)
		{
			zero.Normalize();
		}
		bool flag4 = (ZInput.GetButton("Attack") || ZInput.GetButton("JoyAttack")) && !flag && !Hud.InRadial();
		bool attackHold = flag4;
		bool attack = flag4 && !m_attackWasPressed;
		m_attackWasPressed = flag4;
		bool secondaryAttackHold = flag3;
		bool secondaryAttack = flag3 && !m_secondAttackWasPressed;
		m_secondAttackWasPressed = flag3;
		bool flag5 = (ZInput.GetButton("Block") || ZInput.GetButton("JoyBlock")) && !flag && !Hud.InRadial();
		bool blockHold = flag5;
		bool block = flag5 && !m_blockWasPressed;
		m_blockWasPressed = flag5;
		bool button = ZInput.GetButton("Jump");
		bool jump = (button && !m_lastJump) || (ZInput.GetButtonDown("JoyJump") && !flag2 && !flag && !Hud.InRadial());
		m_lastJump = button;
		bool dodge = ZInput.IsNonClassicFunctionality() && ZInput.IsGamepadActive() && ZInput.GetButtonDown("JoyDodge") && !flag && !Hud.InRadial();
		bool flag6 = InventoryGui.IsVisible();
		bool flag7 = (ZInput.GetButton("Crouch") || ZInput.GetButton("JoyCrouch")) && !flag6 && !Hud.InRadial();
		bool crouch = flag7 && !m_lastCrouch;
		m_lastCrouch = flag7;
		bool flag8 = ZInput.GetButton("Run") || ZInput.GetButton("JoyRun");
		if (!m_lastRunPressed && flag8 && m_character.GetStamina() > 0f)
		{
			m_runPressedWhileStamina = true;
		}
		else if (m_character.GetStamina() <= 0f)
		{
			m_runPressedWhileStamina = false;
		}
		if (ZInput.ToggleRun)
		{
			if (!m_lastRunPressed && flag8)
			{
				m_run = !m_run;
			}
			if (m_character.GetStamina() <= 0f)
			{
				m_run = false;
			}
		}
		else
		{
			m_run = flag8 && m_runPressedWhileStamina;
		}
		float magnitude = zero.magnitude;
		if (magnitude < 0.05f && m_lastMagnitude < 0.05f && !m_character.m_autoRun)
		{
			m_run = false;
		}
		m_lastRunPressed = flag8;
		m_lastMagnitude = magnitude;
		m_lastRunPressed = flag8;
		bool button2 = ZInput.GetButton("AutoRun");
		if (takeInputDelay > 0f)
		{
			m_character.SetControls(zero, attack: false, attackHold: false, secondaryAttack: false, secondaryAttackHold: false, block: false, blockHold: false, jump: false, crouch: false, m_run, button2);
		}
		else
		{
			m_character.SetControls(zero, attack, attackHold, secondaryAttack, secondaryAttackHold, block, blockHold, jump, crouch, m_run, button2, dodge);
		}
	}

	private static bool DetectTap(bool pressed, float dt, float minPressTime, bool run, ref float pressTimer, ref float releasedTimer, ref bool tapPressed)
	{
		bool result = false;
		if (pressed)
		{
			if ((releasedTimer > 0f && releasedTimer < minPressTime) & tapPressed)
			{
				tapPressed = false;
				result = true;
			}
			pressTimer += dt;
			releasedTimer = 0f;
		}
		else
		{
			if (pressTimer > 0f)
			{
				tapPressed = pressTimer < minPressTime;
				if (run & tapPressed)
				{
					tapPressed = false;
					result = true;
				}
			}
			releasedTimer += dt;
			pressTimer = 0f;
		}
		return result;
	}

	private bool TakeInput(bool look = false)
	{
		if (GameCamera.InFreeFly())
		{
			return false;
		}
		if ((!Chat.instance || !Chat.instance.HasFocus()) && !Menu.IsVisible() && !Console.IsVisible() && !TextInput.IsVisible() && !Minimap.InTextInput() && (!ZInput.IsGamepadActive() || !Minimap.IsOpen()) && (!ZInput.IsGamepadActive() || !InventoryGui.IsVisible()) && (!ZInput.IsGamepadActive() || !StoreGui.IsVisible()) && (!ZInput.IsGamepadActive() || !Hud.IsPieceSelectionVisible()))
		{
			if (!PlayerCustomizaton.IsBarberGuiVisible() || look)
			{
				return !(PlayerCustomizaton.BarberBlocksLook() && look);
			}
			return false;
		}
		return false;
	}

	private bool InInventoryEtc()
	{
		if (!InventoryGui.IsVisible() && !Minimap.IsOpen() && !StoreGui.IsVisible())
		{
			return Hud.IsPieceSelectionVisible();
		}
		return true;
	}

	public static void SetTakeInputDelay(float delayInSeconds)
	{
		takeInputDelay = delayInSeconds;
	}

	private void LateUpdate()
	{
		if ((Hud.InRadial() && Hud.instance.m_radialMenu.IsBlockingInput) || (takeInputDelay > 0f && ZInput.IsGamepadActive()))
		{
			return;
		}
		if (!TakeInput(look: true) || InInventoryEtc())
		{
			m_character.SetMouseLook(Vector2.zero);
			return;
		}
		Vector2 mouseLook = Vector2.zero;
		if (ZInput.IsGamepadActive() && !Hud.InRadial())
		{
			if (!m_character.InPlaceMode() || !ZInput.GetButton("JoyRotate"))
			{
				if (!cameraDirectionLock.Equals(Vector2.zero))
				{
					if (!new Vector2(ZInput.GetJoyRightStickX(), 0f - ZInput.GetJoyRightStickY()).Equals(cameraDirectionLock))
					{
						cameraDirectionLock = Vector2.zero;
						mouseLook.x += ZInput.GetJoyRightStickX() * 110f * Time.deltaTime * m_gamepadSens;
						mouseLook.y += (0f - ZInput.GetJoyRightStickY()) * 110f * Time.deltaTime * m_gamepadSens;
					}
				}
				else
				{
					mouseLook.x += ZInput.GetJoyRightStickX() * 110f * Time.deltaTime * m_gamepadSens;
					mouseLook.y += (0f - ZInput.GetJoyRightStickY()) * 110f * Time.deltaTime * m_gamepadSens;
				}
			}
			if (m_invertCameraX)
			{
				mouseLook.x *= -1f;
			}
			if (m_invertCameraY)
			{
				mouseLook.y *= -1f;
			}
		}
		else if (!Hud.InRadial())
		{
			mouseLook = ZInput.GetMouseDelta() * m_mouseSens;
			if (m_invertMouse)
			{
				mouseLook.y *= -1f;
			}
		}
		m_character.SetMouseLook(mouseLook);
	}
}
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

public class PlayerCustomizaton : MonoBehaviour
{
	public static PlayerCustomizaton m_barberInstance;

	private static string m_lastHair;

	private static string m_lastBeard;

	private static Vector3 m_lastHairColor;

	public Color m_skinColor0 = Color.white;

	public Color m_skinColor1 = Color.white;

	public Color m_hairColor0 = Color.white;

	public Color m_hairColor1 = Color.white;

	public float m_hairMaxLevel = 1f;

	public float m_hairMinLevel = 0.1f;

	public TMP_Text m_selectedBeard;

	public TMP_Text m_selectedHair;

	public Slider m_skinHue;

	public Slider m_hairLevel;

	public Slider m_hairTone;

	public RectTransform m_beardPanel;

	public Toggle m_maleToggle;

	public Toggle m_femaleToggle;

	public ItemDrop m_noHair;

	public ItemDrop m_noBeard;

	public GameObject m_rootPanel;

	public Button m_apply;

	public Button m_cancel;

	public PlayerCustomizaton m_barberGui;

	public int m_hairToolTier;

	private List<ItemDrop> m_beards;

	private List<ItemDrop> m_hairs;

	private static bool m_barberWasHidden;

	private void OnEnable()
	{
		if ((bool)m_barberGui)
		{
			m_barberInstance = m_barberGui;
			m_rootPanel.gameObject.SetActive(value: false);
		}
		if ((bool)m_maleToggle)
		{
			m_maleToggle.isOn = true;
		}
		if ((bool)m_femaleToggle)
		{
			m_femaleToggle.isOn = false;
		}
		m_beardPanel.gameObject.SetActive(value: true);
	}

	private bool LoadHair()
	{
		if (m_hairs == null && (bool)ObjectDB.instance)
		{
			m_beards = ObjectDB.instance.GetAllItems(ItemDrop.ItemData.ItemType.Customization, "Beard");
			m_hairs = ObjectDB.instance.GetAllItems(ItemDrop.ItemData.ItemType.Customization, "Hair");
			m_beards.RemoveAll((ItemDrop x) => x.name.Contains("_"));
			m_hairs.RemoveAll((ItemDrop x) => x.name.Contains("_"));
			m_beards.Sort((ItemDrop x, ItemDrop y) => Localization.instance.Localize(x.m_itemData.m_shared.m_name).CompareTo(Localization.instance.Localize(y.m_itemData.m_shared.m_name)));
			m_hairs.Sort((ItemDrop x, ItemDrop y) => Localization.instance.Localize(x.m_itemData.m_shared.m_name).CompareTo(Localization.instance.Localize(y.m_itemData.m_shared.m_name)));
			m_beards.Remove(m_noBeard);
			m_beards.Insert(0, m_noBeard);
			m_hairs.Remove(m_noHair);
			m_hairs.Insert(0, m_noHair);
			return true;
		}
		return m_hairs != null;
	}

	private void Update()
	{
		if (!LoadHair() || ((bool)m_rootPanel && !m_rootPanel.activeInHierarchy) || GetPlayer() == null)
		{
			return;
		}
		m_selectedHair.text = Localization.instance.Localize(GetHair());
		m_selectedBeard.text = Localization.instance.Localize(GetBeard());
		if ((bool)m_skinHue)
		{
			Color c = Color.Lerp(m_skinColor0, m_skinColor1, m_skinHue.value);
			GetPlayer().SetSkinColor(Utils.ColorToVec3(c));
		}
		if ((bool)m_hairTone)
		{
			Color c2 = Color.Lerp(m_hairColor0, m_hairColor1, m_hairTone.value) * Mathf.Lerp(m_hairMinLevel, m_hairMaxLevel, m_hairLevel.value);
			GetPlayer().SetHairColor(Utils.ColorToVec3(c2));
		}
		if (IsBarberGuiVisible())
		{
			if (InventoryGui.IsVisible() || Minimap.IsOpen() || Game.IsPaused())
			{
				HideBarberGui();
			}
			if (ZInput.GetKeyDown(KeyCode.Escape) || Player.m_localPlayer.IsDead())
			{
				OnCancel();
			}
		}
	}

	private Player GetPlayer()
	{
		if ((bool)Player.m_localPlayer)
		{
			return Player.m_localPlayer;
		}
		return GetComponentInParent<FejdStartup>()?.GetPreviewPlayer();
	}

	public void OnHairHueChange(float v)
	{
	}

	public void OnSkinHueChange(float v)
	{
	}

	public void SetPlayerModel(int index)
	{
		Player player = GetPlayer();
		if (!(player == null))
		{
			player.SetPlayerModel(index);
			if (index == 1)
			{
				ResetBeard();
			}
		}
	}

	public void OnHairLeft()
	{
		int num = GetHairIndex();
		for (int num2 = num - 1; num2 >= 0; num2--)
		{
			if (m_hairs[num2].m_itemData.m_shared.m_toolTier <= m_hairToolTier)
			{
				num = num2;
				break;
			}
		}
		SetHair(num);
	}

	public void OnHairRight()
	{
		int num = GetHairIndex();
		for (int i = num + 1; i < m_hairs.Count; i++)
		{
			if (m_hairs[i].m_itemData.m_shared.m_toolTier <= m_hairToolTier)
			{
				num = i;
				break;
			}
		}
		SetHair(num);
	}

	public void OnBeardLeft()
	{
		if (GetPlayer().GetPlayerModel() == 1)
		{
			return;
		}
		int num = GetBeardIndex();
		for (int num2 = num - 1; num2 >= 0; num2--)
		{
			if (m_beards[num2].m_itemData.m_shared.m_toolTier <= m_hairToolTier)
			{
				num = num2;
				break;
			}
		}
		SetBeard(num);
	}

	public void OnBeardRight()
	{
		if (GetPlayer().GetPlayerModel() == 1)
		{
			return;
		}
		int num = GetBeardIndex();
		for (int i = num + 1; i < m_beards.Count; i++)
		{
			if (m_beards[i].m_itemData.m_shared.m_toolTier <= m_hairToolTier)
			{
				num = i;
				break;
			}
		}
		SetBeard(num);
	}

	public void OnApply()
	{
		m_barberInstance.m_rootPanel.gameObject.SetActive(value: false);
		Player.m_localPlayer.ResetAttachCameraPoint();
		Player.m_localPlayer.AttachStop();
		m_barberWasHidden = false;
	}

	public void OnCancel()
	{
		GetPlayer().SetHair(m_lastHair);
		GetPlayer().SetBeard(m_lastBeard);
		GetPlayer().SetHairColor(m_lastHairColor);
		m_barberInstance.m_rootPanel.gameObject.SetActive(value: false);
		Player.m_localPlayer.ResetAttachCameraPoint();
		Player.m_localPlayer.AttachStop();
		m_barberWasHidden = false;
	}

	private void ResetBeard()
	{
		GetPlayer().SetBeard(m_noBeard.gameObject.name);
	}

	private void SetBeard(int index)
	{
		if (index >= 0 && index < m_beards.Count)
		{
			GetPlayer().SetBeard(m_beards[index].gameObject.name);
		}
	}

	private void SetHair(int index)
	{
		ZLog.Log("Set hair " + index);
		if (index >= 0 && index < m_hairs.Count)
		{
			GetPlayer().SetHair(m_hairs[index].gameObject.name);
		}
	}

	private int GetBeardIndex()
	{
		string beard = GetPlayer().GetBeard();
		for (int i = 0; i < m_beards.Count; i++)
		{
			if (m_beards[i].gameObject.name == beard)
			{
				return i;
			}
		}
		return 0;
	}

	private int GetHairIndex()
	{
		string hair = GetPlayer().GetHair();
		for (int i = 0; i < m_hairs.Count; i++)
		{
			if (m_hairs[i].gameObject.name == hair)
			{
				return i;
			}
		}
		return 0;
	}

	private string GetHair()
	{
		return m_hairs[GetHairIndex()].m_itemData.m_shared.m_name;
	}

	private string GetBeard()
	{
		return m_beards[GetBeardIndex()].m_itemData.m_shared.m_name;
	}

	public static bool IsBarberGuiVisible()
	{
		if ((bool)m_barberInstance && (bool)m_barberInstance.m_rootPanel)
		{
			return m_barberInstance.m_rootPanel.gameObject.activeInHierarchy;
		}
		return false;
	}

	public static void ShowBarberGui()
	{
		if (!m_barberInstance)
		{
			return;
		}
		if (!m_barberWasHidden)
		{
			m_lastHair = m_barberInstance.GetPlayer().GetHair();
			m_lastBeard = m_barberInstance.GetPlayer().GetBeard();
			m_lastHairColor = m_barberInstance.GetPlayer().GetHairColor();
			Player.m_localPlayer.HideHandItems();
			Vector3 hairColor = m_barberInstance.GetPlayer().GetHairColor();
			float value = 0f;
			float value2 = 0f;
			float num = 100f;
			for (float num2 = 0f; num2 < 1f; num2 += 0.02f)
			{
				for (float num3 = m_barberInstance.m_hairMinLevel; num3 < m_barberInstance.m_hairMaxLevel; num3 += 0.02f)
				{
					Vector3 vector = Utils.ColorToVec3(Color.Lerp(m_barberInstance.m_hairColor0, m_barberInstance.m_hairColor1, num2) * Mathf.Lerp(m_barberInstance.m_hairMinLevel, m_barberInstance.m_hairMaxLevel, num3));
					float num4 = Mathf.Abs(vector.x - hairColor.x) + Mathf.Abs(vector.y - hairColor.y) + Mathf.Abs(vector.z - hairColor.z);
					if (num4 < num)
					{
						num = num4;
						value = num2;
						value2 = num3;
					}
				}
			}
			m_barberInstance.m_hairTone.value = value;
			m_barberInstance.m_hairLevel.value = value2;
		}
		m_barberInstance.m_rootPanel.gameObject.SetActive(value: true);
		m_barberInstance.m_apply.Select();
	}

	public static void HideBarberGui()
	{
		m_barberWasHidden = true;
		m_barberInstance.m_rootPanel.gameObject.SetActive(value: false);
	}

	public static bool BarberBlocksLook()
	{
		if (IsBarberGuiVisible() && !ZInput.GetKey(KeyCode.Mouse1))
		{
			return !ZInput.IsGamepadActive();
		}
		return false;
	}
}
