	private WorldPlayerData GetWorldData(long worldUID)
	{
		if (m_worldData.TryGetValue(worldUID, out var value))
		{
			return value;
		}
		value = new WorldPlayerData();
		m_worldData.Add(worldUID, value);
		return value;
	}
