using PlayFab;
using PlayFab.ClientModels;
using Splatform;

public static class PlayFabAuthWithGameCenter
{
	public static void Login()
	{
		if (!(PlayFabManager.instance == null))
		{
			PlayFabClientAPI.LoginWithGameCenter(new LoginWithGameCenterRequest
			{
				TitleId = "6E223",
				CreateAccount = true,
				PlayerId = PlatformManager.DistributionPlatform.LocalUser.PlatformUserID.m_userID
			}, OnLoginSuccess, OnLoginFailure);
		}
	}

	private static void OnLoginSuccess(LoginResult result)
	{
		ZLog.Log("PlayFab logged in via Game Center with ID " + result.PlayFabId);
		PlayFabManager.instance.OnLoginSuccess(result);
	}

	private static void OnLoginFailure(PlayFabError error)
	{
		ZLog.LogWarning($"PlayFab failed to login via Game Center with error code {error.Error}");
		PlayFabManager.instance.OnLoginFailure(error);
	}
}
using System.Text;
using PlayFab;
using PlayFab.ClientModels;
using Steamworks;

public static class PlayFabAuthWithSteam
{
	private static string m_steamTicket;

	public static void Login()
	{
		SteamNetworkingIdentity serverIdentity = default(SteamNetworkingIdentity);
		byte[] array = ZSteamMatchmaking.instance.RequestSessionTicket(ref serverIdentity);
		if (array == null)
		{
			PlayFabManager.instance.OnLoginFailure(null);
			return;
		}
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < array.Length; i++)
		{
			stringBuilder.AppendFormat("{0:x2}", array[i]);
		}
		m_steamTicket = stringBuilder.ToString();
		ZSteamMatchmaking.instance.AuthSessionTicketResponse += OnAuthSessionTicketResponse;
	}

	private static void OnAuthSessionTicketResponse()
	{
		ZSteamMatchmaking.instance.AuthSessionTicketResponse -= OnAuthSessionTicketResponse;
		LoginWithSteamRequest request = new LoginWithSteamRequest
		{
			CreateAccount = true,
			SteamTicket = m_steamTicket
		};
		m_steamTicket = null;
		PlayFabClientAPI.LoginWithSteam(request, OnSteamLoginSuccess, OnSteamLoginFailed);
	}

	private static void OnSteamLoginSuccess(LoginResult result)
	{
		ZLog.Log("Logged in PlayFab user via Steam auth session ticket");
		PlayFabManager.instance.OnLoginSuccess(result);
		ZSteamMatchmaking.instance.ReleaseSessionTicket();
	}

	private static void OnSteamLoginFailed(PlayFabError error)
	{
		ZLog.LogError("Failed to logged in PlayFab user via Steam auth session ticket: " + error.GenerateErrorReport());
		PlayFabManager.instance.OnLoginFailure(error);
		ZSteamMatchmaking.instance.ReleaseSessionTicket();
	}
}
using System;
using System.Collections;
using PlayFab;
using PlayFab.ClientModels;
using PlayFab.Party;
using Splatform;
using UnityEngine;

public class PlayFabManager : MonoBehaviour
{
	public const string TitleId = "6E223";

	private LoginState m_loginState;

	private string m_entityToken;

	private DateTime? m_tokenExpiration;

	private PlayFabAuthenticationContext m_authenticationContext;

	private float m_refreshThresh;

	private int m_loginAttempts;

	private bool m_shouldTryAutoLogin;

	private bool m_deletionRequestDoneOrTimedOut;

	private PlayFabMultiplayerManager m_playFabMultiplayerManager;

	private const float EntityTokenUpdateDurationMin = 420f;

	private const float EntityTokenUpdateDurationMax = 840f;

	private const float LoginRetryDelay = 1f;

	private const float LoginRetryDelayMax = 30f;

	private const float LoginRetryJitterFactor = 0.125f;

	public string PlayFabUniqueId = "";

	private static PlatformUserID m_customId;

	private GameObject m_multiplayerManager;

	private Coroutine m_updateEntityTokenCoroutine;

	public static bool IsLoggedIn
	{
		get
		{
			if (instance == null)
			{
				return false;
			}
			return instance.m_loginState == LoginState.LoggedIn;
		}
	}

	public static LoginState CurrentLoginState
	{
		get
		{
			if (instance == null)
			{
				return LoginState.NotLoggedIn;
			}
			return instance.m_loginState;
		}
	}

	public bool ShouldTryAutoLogin => instance.m_shouldTryAutoLogin;

	public static DateTime NextRetryUtc { get; private set; } = DateTime.MinValue;

	public EntityKey Entity { get; private set; }

	public static PlayFabManager instance { get; private set; }

	public event LoginFinishedCallback LoginFinished;

	public void SetShouldTryAutoLogin(bool value)
	{
		PlatformPrefs.SetInt("ShouldTryAutoLogin", value ? 1 : 0);
		if (PlatformPrefs.GetInt("ShouldTryAutoLogin") == 1)
		{
			instance.m_shouldTryAutoLogin = true;
			instance.Login();
		}
		else
		{
			instance.m_shouldTryAutoLogin = false;
		}
	}

	public static void SetCustomId(PlatformUserID id)
	{
		m_customId = id;
		ZLog.Log($"PlayFab custom ID set to \"{m_customId}\"");
		if (instance != null && CurrentLoginState == LoginState.NotLoggedIn)
		{
			instance.Login();
		}
	}

	public static void Initialize()
	{
		if (instance == null)
		{
			Application.logMessageReceived += HandleLog;
			new GameObject("PlayFabManager").AddComponent<PlayFabManager>();
		}
	}

	public void Awake()
	{
	}

	private void EnsureMultiplayerManagerCreated()
	{
		if (!(m_multiplayerManager != null))
		{
			m_multiplayerManager = new GameObject("PlayFabMultiplayerManager");
			m_multiplayerManager.AddComponent<PlayFabMultiplayerManager>();
		}
	}

	private void EnsureMultiplayerManagerDestroyed()
	{
		if (!(m_multiplayerManager == null))
		{
			UnityEngine.Object.Destroy(m_multiplayerManager);
			m_multiplayerManager = null;
		}
	}

	public void Start()
	{
		if (instance != null)
		{
			ZLog.LogError("Tried to create another PlayFabManager when one already exists! Ignoring and destroying the new one.");
			UnityEngine.Object.Destroy(this);
			return;
		}
		m_shouldTryAutoLogin = PlatformPrefs.GetInt("ShouldTryAutoLogin", 1) == 1;
		instance = this;
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		Login();
		Invoke("StopListeningToLogMsgs", 5f);
	}

	private void Login()
	{
		if (!m_shouldTryAutoLogin)
		{
			return;
		}
		if (m_loginState == LoginState.AttemptingLogin)
		{
			ZLog.LogError("Can't log in while in the " + m_loginState.ToString() + " state!");
			return;
		}
		m_loginAttempts++;
		ZLog.Log($"Sending PlayFab login request (attempt {m_loginAttempts})");
		EnsureMultiplayerManagerCreated();
		if (m_loginState != LoginState.LoggedIn)
		{
			m_loginState = LoginState.AttemptingLogin;
		}
		PlayFabAuthWithSteam.Login();
	}

	public void OnLoginSuccess(LoginResult result)
	{
		Entity = result.EntityToken.Entity;
		PlayFabUniqueId = result.PlayFabId;
		m_entityToken = result.EntityToken.EntityToken;
		m_tokenExpiration = result.EntityToken.TokenExpiration;
		m_authenticationContext = result.AuthenticationContext;
		if (!m_tokenExpiration.HasValue)
		{
			ZLog.LogError("Token expiration time was null!");
			m_loginState = LoginState.LoggedIn;
			return;
		}
		m_refreshThresh = (float)(m_tokenExpiration.Value - DateTime.UtcNow).TotalSeconds / 2f;
		if (IsLoggedIn)
		{
			ZLog.Log($"PlayFab local entity ID {Entity.Id} lifetime extended ");
			this.LoginFinished?.Invoke(LoginType.Refresh);
		}
		else
		{
			if (m_customId.IsValid)
			{
				ZLog.Log($"PlayFab logged in as \"{m_customId}\"");
			}
			ZLog.Log("PlayFab local entity ID is " + Entity.Id);
			m_loginState = LoginState.LoggedIn;
			this.LoginFinished?.Invoke(LoginType.Success);
		}
		if (m_updateEntityTokenCoroutine == null)
		{
			m_updateEntityTokenCoroutine = StartCoroutine(UpdateEntityTokenCoroutine());
		}
		ZPlayFabMatchmaking.OnLogin();
	}

	public void OnLoginFailure(PlayFabError error)
	{
		if (error == null)
		{
			ZLog.LogError("Unknown login error");
		}
		else
		{
			ZLog.LogError(error.GenerateErrorReport());
		}
		this.LoginFinished?.Invoke(LoginType.Failed);
		RetryLoginAfterDelay(GetRetryDelay(m_loginAttempts));
	}

	private float GetRetryDelay(int attemptCount)
	{
		return Mathf.Min(1f * Mathf.Pow(2f, attemptCount - 1), 30f) * UnityEngine.Random.Range(0.875f, 1.125f);
	}

	private void RetryLoginAfterDelay(float delay)
	{
		m_loginState = LoginState.WaitingForRetry;
		ZLog.Log($"Retrying login in {delay}s");
		StartCoroutine(DelayThenLoginCoroutine(delay));
		IEnumerator DelayThenLoginCoroutine(float num)
		{
			ZLog.Log($"PlayFab login failed! Retrying in {num}s, total attempts: {m_loginAttempts}");
			NextRetryUtc = DateTime.UtcNow + TimeSpan.FromSeconds(num);
			while (DateTime.UtcNow < NextRetryUtc)
			{
				yield return null;
			}
			Login();
		}
	}

	public static void CheckIfUserAuthenticated(string playfabID, PlatformUserID platformUserId, Action<bool> resultCallback)
	{
		resultCallback(obj: true);
	}

	private IEnumerator UpdateEntityTokenCoroutine()
	{
		while (true)
		{
			yield return new WaitForSecondsRealtime(420f);
			ZLog.Log("Update PlayFab entity token");
			PlayFabMultiplayerManager.Get().UpdateEntityToken(m_entityToken);
			if (!m_tokenExpiration.HasValue)
			{
				break;
			}
			if ((float)(m_tokenExpiration.Value - DateTime.UtcNow).TotalSeconds <= m_refreshThresh)
			{
				ZLog.Log("Renew PlayFab entity token");
				m_refreshThresh /= 1.5f;
				Login();
			}
			yield return new WaitForSecondsRealtime(UnityEngine.Random.Range(420f, 840f));
		}
		ZLog.LogError("Token expiration time was null!");
		m_updateEntityTokenCoroutine = null;
	}

	private static void HandleLog(string logString, string stackTrace, LogType type)
	{
		if (type == LogType.Exception && logString.ToLower().Contains("DllNotFoundException: Party", StringComparison.InvariantCultureIgnoreCase))
		{
			ZLog.LogError("DLL Not Found: This error usually occurs when you do not have the correct dependencies installed, and will prevent crossplay from working. The dependencies are different depending on which platform you play on.\n For windows: You need VC++ Redistributables. https://learn.microsoft.com/en-us/cpp/windows/latest-supported-vc-redist?view=msvc-170Linux: You need Pulse Audio. https://learn.microsoft.com/it-it/gaming/playfab/features/multiplayer/networking/linux-specific-requirementsSteam deck: Try using Proton Compatability Layer.Other platforms: If the issue persists, please report it as a bug.");
			UnityEngine.Object.FindObjectOfType<PlayFabManager>().WaitForPopupEnabled();
		}
	}

	private void StopListeningToLogMsgs()
	{
		Application.logMessageReceived -= HandleLog;
	}

	private void WaitForPopupEnabled()
	{
		if (UnifiedPopup.IsAvailable())
		{
			DelayedVCRedistWarningPopup();
		}
		else
		{
			UnifiedPopup.OnPopupEnabled += DelayedVCRedistWarningPopup;
		}
	}

	private void DelayedVCRedistWarningPopup()
	{
		string playFabErrorBodyText = GetPlayFabErrorBodyText();
		UnifiedPopup.Push(new WarningPopup("$playfab_couldnotloadplayfabparty_header", playFabErrorBodyText, delegate
		{
			UnifiedPopup.Pop();
		}));
		UnifiedPopup.OnPopupEnabled -= DelayedVCRedistWarningPopup;
		Application.logMessageReceived -= HandleLog;
	}

	private string GetPlayFabErrorBodyText()
	{
		if (Settings.IsSteamRunningOnSteamDeck())
		{
			return "$playfab_couldnotloadplayfabparty_text_linux_steamdeck";
		}
		if (!Settings.IsSteamRunningOnSteamDeck() && (Application.platform == RuntimePlatform.LinuxPlayer || Application.platform == RuntimePlatform.WindowsServer || Application.platform == RuntimePlatform.WindowsEditor))
		{
			return "$playfab_couldnotloadplayfabparty_text_linux";
		}
		if (Application.platform == RuntimePlatform.WindowsPlayer || Application.platform == RuntimePlatform.WindowsServer || Application.platform == RuntimePlatform.WindowsEditor)
		{
			return "$playfab_couldnotloadplayfabparty_text_windows";
		}
		return "$playfab_couldnotloadplayfabparty_text_otherplatforms";
	}

	public void LoginFailed()
	{
		OnPlayFabRespondRemoveUIBlock(LoginType.Refresh);
		RetryLoginAfterDelay(GetRetryDelay(m_loginAttempts));
	}

	private void Update()
	{
		ZPlayFabMatchmaking.instance?.Update(Time.unscaledDeltaTime);
	}

	public void DeletePlayerTitleAccount()
	{
		if (string.IsNullOrEmpty(PlayFabUniqueId))
		{
			ZLog.LogError("No associated PlayFab ID found. Cannot delete account.");
			return;
		}
		PlayFabClientAPI.ExecuteCloudScript(new ExecuteCloudScriptRequest
		{
			FunctionName = "deletePlayerAccount",
			FunctionParameter = new { PlayFabUniqueId },
			GeneratePlayStreamEvent = true
		}, OnCloudDeletePlayerResult, OnDeletePlayerFailed);
		UnifiedPopup.Push(new TaskPopup("$settings_deleteplayfab_task_header", ""));
	}

	public void OnPlayFabRespondRemoveUIBlock(LoginType loginType = LoginType.Success)
	{
		if (UnifiedPopup.IsAvailable())
		{
			if (!UnifiedPopup.IsVisible())
			{
				return;
			}
			UnifiedPopup.Pop();
		}
		if (loginType == LoginType.Failed || loginType == LoginType.Refresh)
		{
			ZLog.LogWarning("Could not log in to PlayFab. ");
			ResetMainMenuButtons();
			LoginFinished -= OnPlayFabRespondRemoveUIBlock;
			UnifiedPopup.Push(new WarningPopup("$menu_logging_in_playfab_failed_header", "", UnifiedPopup.Pop));
		}
	}

	public void ResetMainMenuButtons()
	{
		if (FejdStartup.instance == null)
		{
			return;
		}
		TabHandler[] componentsInChildren = FejdStartup.instance.transform.GetComponentsInChildren<TabHandler>(includeInactive: true);
		int num = 0;
		if (num < componentsInChildren.Length)
		{
			TabHandler tabHandler = componentsInChildren[num];
			if (tabHandler.m_tabs.Count == 2)
			{
				tabHandler.SetActiveTab(0);
			}
		}
		FejdStartup.instance.m_openServerToggle.isOn = false;
	}

	private void OnCloudDeletePlayerResult(ExecuteCloudScriptResult obj)
	{
		bool flag = false;
		string text = "";
		if (obj.FunctionResult != null)
		{
			string text2 = obj.FunctionResult.ToString();
			flag = text2.Contains("\"success\":true,\"");
			text = text2;
		}
		else
		{
			Debug.LogError("Result of PlayFab API is null or invalid.");
		}
		m_loginState = LoginState.NotLoggedIn;
		SetShouldTryAutoLogin(value: false);
		EnsureMultiplayerManagerDestroyed();
		OnPlayFabRespondRemoveUIBlock();
		ZLog.Log("Delete Player Result: " + obj.ToJson());
		ResetMainMenuButtons();
		string text3 = (flag ? "$settings_deleteplayfabaccount_success" : ("$settings_deleteplayfabaccount_failure" + text));
		UnifiedPopup.Push(new WarningPopup("", text3, UnifiedPopup.Pop));
	}

	private void OnDeletePlayerFailed(PlayFabError error)
	{
		OnPlayFabRespondRemoveUIBlock();
		string text = error.GenerateErrorReport();
		ZLog.LogError("Could not remove player account: " + text);
		UnifiedPopup.Push(new WarningPopup("", "$settings_deleteplayfabaccount_failure" + text, UnifiedPopup.Pop));
	}
}
using System;
using System.Collections.Generic;
using NetworkingUtils;
using Splatform;

public class PlayFabMatchmaking : IMatchmakingBackend, IDisposable
{
	private const float c_RequestDelay = 2f;

	private List<ServerData> m_publicServerList = new List<ServerData>();

	private Dictionary<ServerJoinDataPlayFabUser, ServerMatchmakingData> m_matchmakingDataCachePlayFabUser = new Dictionary<ServerJoinDataPlayFabUser, ServerMatchmakingData>();

	private Dictionary<IPEndPoint, ServerMatchmakingData> m_matchmakingDataCacheDedicated = new Dictionary<IPEndPoint, ServerMatchmakingData>();

	private string m_filterLowerInvariant = string.Empty;

	private List<ServerData> m_filteredPublicServerList = new List<ServerData>();

	private bool m_filteredListOutdated = true;

	private ZPlayFabLobbySearch m_currentLobbySearch;

	private RefreshPublicServerListFlags m_refreshPublicServerListFlags;

	private DateTime m_mostRecentRequestTimeUtc = DateTime.MinValue;

	private ServerJoinData m_currentServer = ServerJoinData.None;

	private PlatformUserID m_currentUser = PlatformUserID.None;

	private MatchmakingDataRetrievedHandler m_callback;

	private readonly HashSet<PlayFabMatchmakingServerData> m_playFabTemporarySearchServerList = new HashSet<PlayFabMatchmakingServerData>();

	private bool m_isSubscribedToLoginEvent;

	public bool IsAvailable => PlayFabManager.IsLoggedIn;

	public uint PublicServerCount => (uint)m_publicServerList.Count;

	public IReadOnlyList<ServerData> FilteredPublicServerList
	{
		get
		{
			if (m_filterLowerInvariant.Length == 0)
			{
				return m_publicServerList;
			}
			if (m_filteredListOutdated)
			{
				m_filteredPublicServerList.Clear();
				ServerListUtils.GetFilteredList(m_publicServerList, m_filterLowerInvariant, m_filteredPublicServerList);
				m_filteredListOutdated = false;
			}
			return m_filteredPublicServerList;
		}
	}

	public bool ServerSideFiltering => true;

	public bool IsRefreshingPublicServerList => m_currentLobbySearch != null;

	public event PublicServerListUpdatedHandler FilteredPublicServerListUpdated;

	public PlayFabMatchmaking()
	{
		if (!PlayFabManager.IsLoggedIn && PlayFabManager.instance != null)
		{
			PlayFabManager.instance.LoginFinished += OnPlayFabLoginFinished;
			m_isSubscribedToLoginEvent = true;
		}
	}

	public void Dispose()
	{
		if (m_isSubscribedToLoginEvent && PlayFabManager.instance != null)
		{
			PlayFabManager.instance.LoginFinished -= OnPlayFabLoginFinished;
			m_isSubscribedToLoginEvent = false;
		}
	}

	private void OnPlayFabLoginFinished(LoginType loginType)
	{
	}

	public void RefreshPublicServerList(RefreshPublicServerListFlags flags)
	{
		CancelPlayFabServerSearch();
		m_refreshPublicServerListFlags = flags;
		if (!m_refreshPublicServerListFlags.HasFlag(RefreshPublicServerListFlags.ServerSideFilterRefresh))
		{
			m_playFabTemporarySearchServerList.Clear();
			SetResultFromTemporaryListToPublicList();
		}
		this.FilteredPublicServerListUpdated?.Invoke();
		m_playFabTemporarySearchServerList.EnsureCapacity(200);
		m_mostRecentRequestTimeUtc = DateTime.UtcNow;
		m_currentLobbySearch = ZPlayFabMatchmaking.ListServers(m_filterLowerInvariant, PlayFabServersFound, PlayFabServerSearchDone);
		ZLog.DevLog("PlayFab server search started!");
	}

	public void SetPublicServerListFilter(string filter)
	{
		if (filter == null)
		{
			filter = string.Empty;
		}
		filter = filter.ToLowerInvariant();
		if (!(m_filterLowerInvariant == filter))
		{
			m_filterLowerInvariant = filter;
			m_filteredListOutdated = true;
			if (m_filterLowerInvariant.Length == 0)
			{
				m_filteredPublicServerList.Clear();
			}
			this.FilteredPublicServerListUpdated?.Invoke();
		}
	}

	public bool CanRefreshServerNow()
	{
		if (!IsAvailable)
		{
			return false;
		}
		if (m_currentServer.IsValid || m_currentUser.IsValid)
		{
			return false;
		}
		if ((DateTime.UtcNow - m_mostRecentRequestTimeUtc).TotalSeconds < 2.0)
		{
			return false;
		}
		return true;
	}

	public bool CanRefreshServerOfTypeNow(ServerJoinDataType type)
	{
		if (type - 2 <= ServerJoinDataType.SteamUser)
		{
			return CanRefreshServerNow();
		}
		return false;
	}

	public bool RefreshServer(ServerJoinData server, MatchmakingDataRetrievedHandler completedCallback)
	{
		if (!server.IsValid)
		{
			throw new ArgumentException("server was invalid!");
		}
		if (!CanRefreshServerOfTypeNow(server.m_type))
		{
			return false;
		}
		switch (server.m_type)
		{
		case ServerJoinDataType.PlayFabUser:
			m_currentServer = server;
			m_callback = completedCallback;
			ZPlayFabMatchmaking.CheckHostOnlineStatus(m_currentServer.PlayFabUser.m_remotePlayerId, PlayFabPingSuccess, PlayFabPingFailed);
			break;
		case ServerJoinDataType.Dedicated:
		{
			if (!MultiBackendMatchmaking.GetServerIPCached(server.Dedicated, out var address))
			{
				return false;
			}
			m_currentServer = server;
			m_callback = completedCallback;
			if (address.HasValue)
			{
				ZPlayFabMatchmaking.FindHostByIp(new IPEndPoint(address.Value, m_currentServer.Dedicated.m_port), PlayFabPingSuccess, PlayFabPingFailed);
			}
			else
			{
				PlayFabPingFailed(ZPLayFabMatchmakingFailReason.EndPointNotOnInternet);
			}
			break;
		}
		default:
			return false;
		}
		return true;
	}

	public bool ResolveServerFromHostUser(PlatformUserID hostUser, MatchmakingDataRetrievedHandler completedCallback)
	{
		if (!hostUser.IsValid)
		{
			throw new ArgumentException("hostUser was invalid!");
		}
		if (!CanRefreshServerOfTypeNow(ServerJoinDataType.PlayFabUser))
		{
			return false;
		}
		m_currentUser = hostUser;
		m_callback = completedCallback;
		ZPlayFabMatchmaking.FindServerByHostUser(hostUser, PlayFabPingSuccess, PlayFabPingFailed);
		return true;
	}

	public bool IsPending(ServerJoinData server)
	{
		return m_currentServer == server;
	}

	public bool IsPending(PlatformUserID server)
	{
		return m_currentUser == server;
	}

	public ServerMatchmakingData GetServerMatchmakingData(ServerJoinData server, DateTime newerThanUtc = default(DateTime))
	{
		if (!server.IsValid)
		{
			throw new ArgumentException("server was invalid");
		}
		ServerMatchmakingData value;
		switch (server.m_type)
		{
		case ServerJoinDataType.PlayFabUser:
			if (!m_matchmakingDataCachePlayFabUser.TryGetValue(server.PlayFabUser, out value))
			{
				return ServerMatchmakingData.None;
			}
			break;
		case ServerJoinDataType.Dedicated:
		{
			if (!MultiBackendMatchmaking.GetServerIPCached(server.Dedicated, out var address))
			{
				return ServerMatchmakingData.None;
			}
			if (!address.HasValue)
			{
				return new ServerMatchmakingData(newerThanUtc.AddTicks(1L));
			}
			if (!address.Value.IsPublic())
			{
				return new ServerMatchmakingData(newerThanUtc.AddTicks(1L));
			}
			if (!m_matchmakingDataCacheDedicated.TryGetValue(new IPEndPoint(address.Value, server.Dedicated.m_port), out value))
			{
				return ServerMatchmakingData.None;
			}
			break;
		}
		default:
			return new ServerMatchmakingData(newerThanUtc.AddTicks(1L));
		}
		if (value.m_timestampUtc <= newerThanUtc)
		{
			return ServerMatchmakingData.None;
		}
		return value;
	}

	public void Tick()
	{
	}

	private void PlayFabPingSuccess(PlayFabMatchmakingServerData serverData)
	{
		if (!m_currentServer.IsValid && !m_currentUser.IsValid)
		{
			ZLog.LogError("Current was invalid!");
		}
		else
		{
			SetResult(serverData.ToServerData(DateTime.UtcNow));
		}
	}

	private void PlayFabPingFailed(ZPLayFabMatchmakingFailReason failReason)
	{
		if (m_currentServer.IsValid)
		{
			ServerData result = new ServerData(m_currentServer, new ServerMatchmakingData(DateTime.UtcNow));
			SetResult(result);
		}
		else if (m_currentUser.IsValid)
		{
			SetResult(ServerData.None);
		}
		else
		{
			ZLog.LogError("Current was invalid!");
		}
	}

	private void SetResult(ServerData result)
	{
		if (result.m_joinData.IsValid)
		{
			SetMatchmakingDataCacheEntry(result.m_joinData, result.m_matchmakingData);
		}
		MatchmakingDataRetrievedHandler callback = m_callback;
		m_currentServer = ServerJoinData.None;
		m_currentUser = PlatformUserID.None;
		m_callback = null;
		callback?.Invoke(result);
	}

	private void PlayFabServersFound(PlayFabMatchmakingServerData[] serverDatas)
	{
		foreach (PlayFabMatchmakingServerData playFabMatchmakingServerData in serverDatas)
		{
			if (m_playFabTemporarySearchServerList.TryGetValue(playFabMatchmakingServerData, out var actualValue))
			{
				if (playFabMatchmakingServerData.tickCreated > actualValue.tickCreated)
				{
					m_playFabTemporarySearchServerList.Remove(playFabMatchmakingServerData);
					m_playFabTemporarySearchServerList.Add(playFabMatchmakingServerData);
				}
			}
			else
			{
				m_playFabTemporarySearchServerList.Add(playFabMatchmakingServerData);
			}
		}
		SetResultFromTemporaryListToPublicList();
	}

	private void PlayFabServerSearchDone(ZPLayFabMatchmakingFailReason failedReason)
	{
		ZLog.DevLog("PlayFab server search done!");
		if (m_playFabTemporarySearchServerList.Count <= 0)
		{
			SetResultFromTemporaryListToPublicList();
		}
		m_currentLobbySearch = null;
	}

	private void CancelPlayFabServerSearch()
	{
		if (m_currentLobbySearch != null)
		{
			m_currentLobbySearch.Cancel();
			m_currentLobbySearch = null;
		}
	}

	private void SetResultFromTemporaryListToPublicList()
	{
		m_publicServerList.Clear();
		foreach (PlayFabMatchmakingServerData playFabTemporarySearchServer in m_playFabTemporarySearchServerList)
		{
			ServerJoinData serverJoinData;
			if (playFabTemporarySearchServer.isDedicatedServer && !string.IsNullOrEmpty(playFabTemporarySearchServer.serverIp))
			{
				ServerJoinDataDedicated dedicated = new ServerJoinDataDedicated(playFabTemporarySearchServer.serverIp);
				if (dedicated.TryGetIPAddress(out var _))
				{
					serverJoinData = new ServerJoinData(dedicated);
				}
				else
				{
					ZLog.Log("Dedicated server with invalid IP address - fallback to PlayFab ID");
					serverJoinData = new ServerJoinData(new ServerJoinDataPlayFabUser(playFabTemporarySearchServer.remotePlayerId), playFabTemporarySearchServer.platformUserID);
				}
			}
			else
			{
				serverJoinData = new ServerJoinData(new ServerJoinDataPlayFabUser(playFabTemporarySearchServer.remotePlayerId), playFabTemporarySearchServer.platformUserID);
			}
			if (!playFabTemporarySearchServer.gameVersion.IsValid())
			{
				ZLog.LogWarning($"Failed to parse version string! Skipping server entry {serverJoinData}.");
				continue;
			}
			_ = Platform.Unknown;
			if (playFabTemporarySearchServer.gameVersion >= Version.FirstVersionWithPlatformRestriction)
			{
				_ = playFabTemporarySearchServer.platformRestriction;
			}
			ServerMatchmakingData matchmakingData = playFabTemporarySearchServer.ToServerMatchmakingData(DateTime.UtcNow);
			m_publicServerList.Add(new ServerData(serverJoinData, matchmakingData));
		}
		m_filteredListOutdated = true;
		this.FilteredPublicServerListUpdated?.Invoke();
	}

	public void ResolveJoinCode(string joinCode, MatchmakingDataRetrievedHandler successCallback, ZPlayFabMatchmakingFailedCallback failedCallback)
	{
		ZPlayFabMatchmaking.ResolveJoinCode(joinCode, OnResolveJoinCodeSuccess, failedCallback);
		void OnResolveJoinCodeSuccess(PlayFabMatchmakingServerData serverData)
		{
			ServerData serverData2 = serverData.ToServerData(DateTime.UtcNow);
			SetMatchmakingDataCacheEntry(serverData2.m_joinData, serverData2.m_matchmakingData);
			successCallback(serverData2);
		}
	}

	private void SetMatchmakingDataCacheEntry(ServerJoinData server, ServerMatchmakingData serverMatchmakingData)
	{
		switch (server.m_type)
		{
		case ServerJoinDataType.PlayFabUser:
			m_matchmakingDataCachePlayFabUser[server.PlayFabUser] = serverMatchmakingData;
			break;
		case ServerJoinDataType.Dedicated:
		{
			if (!server.Dedicated.TryGetIPEndPoint(out var endPoint))
			{
				if (!MultiBackendMatchmaking.Instance.m_dnsResolver.ResolveDomainName(server.Dedicated.m_host, out var address, DnsResolveFlags.CacheOnly))
				{
					throw new InvalidOperationException($"Can't set matchmaking data cache entry for server {server} - the address must either be part of the server data or must already be in the DNS resolve cache!");
				}
				if (!address.HasValue)
				{
					break;
				}
				endPoint = new IPEndPoint(address.Value, server.Dedicated.m_port);
			}
			m_matchmakingDataCacheDedicated[endPoint] = serverMatchmakingData;
			break;
		}
		default:
			throw new ArgumentException($"Can't set matchmaking data cache entry for server {server} of type {server.m_type}.");
		}
	}
}
using System;
using System.Collections.Generic;
using Splatform;

public class PlayFabMatchmakingServerData : IEquatable<PlayFabMatchmakingServerData>
{
	public string serverName;

	public string worldName;

	public GameVersion gameVersion;

	public string[] modifiers;

	public uint networkVersion;

	public string networkId = "";

	public string joinCode;

	public string remotePlayerId;

	public string lobbyId;

	public PlatformUserID platformUserID;

	public string serverIp = "";

	public Platform platformRestriction = Platform.Unknown;

	public bool isDedicatedServer;

	public bool isCommunityServer;

	public bool havePassword;

	public uint numPlayers;

	public uint maxNumPlayers;

	public long tickCreated;

	public override bool Equals(object obj)
	{
		if (obj is PlayFabMatchmakingServerData other)
		{
			return Equals(other);
		}
		return false;
	}

	public bool Equals(PlayFabMatchmakingServerData other)
	{
		if (remotePlayerId == other.remotePlayerId && serverIp == other.serverIp)
		{
			return isDedicatedServer == other.isDedicatedServer;
		}
		return false;
	}

	public override int GetHashCode()
	{
		return ((1416698207 * -1521134295 + EqualityComparer<string>.Default.GetHashCode(remotePlayerId)) * -1521134295 + EqualityComparer<string>.Default.GetHashCode(serverIp)) * -1521134295 + isDedicatedServer.GetHashCode();
	}

	public override string ToString()
	{
		return "Server Name : " + serverName + "\nServer IP : " + serverIp + "\n" + $"Game Version : {gameVersion}\n" + $"Network Version : {networkVersion}\n" + "Player ID : " + remotePlayerId + "\n" + $"Players : {numPlayers}\n" + $"Max players : {maxNumPlayers}\n" + "Lobby ID : " + lobbyId + "\nNetwork ID : " + networkId + "\nJoin Code : " + joinCode + "\n" + $"Platform Restriction : {platformRestriction}\n" + $"Dedicated : {isDedicatedServer}\n" + $"Community : {isCommunityServer}\n" + $"TickCreated : {tickCreated}\n" + $"Modifiers : {modifiers}\n";
	}

	public ServerData ToServerData(DateTime timestampUtc)
	{
		ServerJoinData joinData = ((!isDedicatedServer) ? new ServerJoinData(new ServerJoinDataPlayFabUser(remotePlayerId)) : new ServerJoinData(new ServerJoinDataDedicated(serverIp)));
		return new ServerData(joinData, ToServerMatchmakingData(timestampUtc));
	}

	public ServerMatchmakingData ToServerMatchmakingData(DateTime timestampUtc)
	{
		return new ServerMatchmakingData(timestampUtc, serverName, numPlayers, maxNumPlayers, platformUserID, gameVersion, networkVersion, joinCode, isPasswordProtected: true, platformRestriction, modifiers);
	}
}
using System;
using System.Collections.Generic;
using System.Threading;
using Ionic.Zlib;

public class PlayFabZLibWorkQueue : IDisposable
{
	private static Thread s_thread;

	private static bool s_moreWork;

	private static readonly List<PlayFabZLibWorkQueue> s_workers = new List<PlayFabZLibWorkQueue>();

	private readonly Queue<byte[]> m_inCompress = new Queue<byte[]>();

	private readonly Queue<byte[]> m_outCompress = new Queue<byte[]>();

	private readonly Queue<byte[]> m_inDecompress = new Queue<byte[]>();

	private readonly Queue<byte[]> m_outDecompress = new Queue<byte[]>();

	private static Mutex s_workersMutex = new Mutex();

	private Mutex m_buffersMutex = new Mutex();

	private static SemaphoreSlim s_workSemaphore = new SemaphoreSlim(0, 1);

	public PlayFabZLibWorkQueue()
	{
		s_workersMutex.WaitOne();
		if (s_thread == null)
		{
			ZLog.Log("Semaphore type: " + s_workSemaphore.GetType().Name);
			s_thread = new Thread(WorkerMain);
			s_thread.Name = "PlayfabZlibThread";
			s_thread.Start();
		}
		s_workers.Add(this);
		s_workersMutex.ReleaseMutex();
	}

	public void Compress(byte[] buffer)
	{
		m_buffersMutex.WaitOne();
		m_inCompress.Enqueue(buffer);
		m_buffersMutex.ReleaseMutex();
		if (s_workSemaphore.CurrentCount < 1)
		{
			s_workSemaphore.Release();
		}
	}

	public void Decompress(byte[] buffer)
	{
		m_buffersMutex.WaitOne();
		m_inDecompress.Enqueue(buffer);
		m_buffersMutex.ReleaseMutex();
		if (s_workSemaphore.CurrentCount < 1)
		{
			s_workSemaphore.Release();
		}
	}

	public void Poll(out List<byte[]> compressedBuffers, out List<byte[]> decompressedBuffers)
	{
		compressedBuffers = null;
		decompressedBuffers = null;
		m_buffersMutex.WaitOne();
		if (m_outCompress.Count > 0)
		{
			compressedBuffers = new List<byte[]>();
			while (m_outCompress.Count > 0)
			{
				compressedBuffers.Add(m_outCompress.Dequeue());
			}
		}
		if (m_outDecompress.Count > 0)
		{
			decompressedBuffers = new List<byte[]>();
			while (m_outDecompress.Count > 0)
			{
				decompressedBuffers.Add(m_outDecompress.Dequeue());
			}
		}
		m_buffersMutex.ReleaseMutex();
	}

	private void WorkerMain()
	{
		while (true)
		{
			s_workSemaphore.Wait();
			s_workersMutex.WaitOne();
			foreach (PlayFabZLibWorkQueue s_worker in s_workers)
			{
				s_worker.Execute();
			}
			s_workersMutex.ReleaseMutex();
		}
	}

	private void Execute()
	{
		m_buffersMutex.WaitOne();
		DoUncompress();
		m_buffersMutex.ReleaseMutex();
		m_buffersMutex.WaitOne();
		DoCompress();
		m_buffersMutex.ReleaseMutex();
	}

	private void DoUncompress()
	{
		while (m_inDecompress.Count > 0)
		{
			try
			{
				byte[] payload = m_inDecompress.Dequeue();
				byte[] item = UncompressOnThisThread(payload);
				m_outDecompress.Enqueue(item);
			}
			catch
			{
			}
		}
	}

	private void DoCompress()
	{
		while (m_inCompress.Count > 0)
		{
			try
			{
				byte[] payload = m_inCompress.Dequeue();
				byte[] item = CompressOnThisThread(payload);
				m_outCompress.Enqueue(item);
			}
			catch
			{
			}
		}
	}

	public void Dispose()
	{
		s_workersMutex.WaitOne();
		s_workers.Remove(this);
		s_workersMutex.ReleaseMutex();
	}

	internal byte[] CompressOnThisThread(byte[] payload)
	{
		return ZlibStream.CompressBuffer(payload);
	}

	internal byte[] UncompressOnThisThread(byte[] payload)
	{
		return ZlibStream.UncompressBuffer(payload);
	}
}
using System.Collections.Generic;
using UnityEngine;

public class PointGenerator
{
	private int m_amount;

	private float m_gridSize = 8f;

	private Vector2Int m_currentCenterGrid = new Vector2Int(99999, 99999);

	private int m_currentGridWith;

	private List<Vector3> m_points = new List<Vector3>();

	public PointGenerator(int amount, float gridSize)
	{
		m_amount = amount;
		m_gridSize = gridSize;
	}

	public void Update(Vector3 center, float radius, List<Vector3> newPoints, List<Vector3> removedPoints)
	{
		Vector2Int grid = GetGrid(center);
		if (m_currentCenterGrid == grid)
		{
			newPoints.Clear();
			removedPoints.Clear();
			return;
		}
		int num = Mathf.CeilToInt(radius / m_gridSize);
		if (m_currentCenterGrid != grid || m_currentGridWith != num)
		{
			RegeneratePoints(grid, num);
		}
	}

	private void RegeneratePoints(Vector2Int centerGrid, int gridWith)
	{
		m_currentCenterGrid = centerGrid;
		Random.State state = Random.state;
		m_points.Clear();
		for (int i = centerGrid.y - gridWith; i <= centerGrid.y + gridWith; i++)
		{
			for (int j = centerGrid.x - gridWith; j <= centerGrid.x + gridWith; j++)
			{
				Random.InitState(j + i * 100);
				Vector3 gridPos = GetGridPos(new Vector2Int(j, i));
				for (int k = 0; k < m_amount; k++)
				{
					Vector3 item = new Vector3(Random.Range(gridPos.x - m_gridSize, gridPos.x + m_gridSize), Random.Range(gridPos.z - m_gridSize, gridPos.z + m_gridSize));
					m_points.Add(item);
				}
			}
		}
		Random.state = state;
	}

	public Vector2Int GetGrid(Vector3 point)
	{
		int x = Mathf.FloorToInt((point.x + m_gridSize / 2f) / m_gridSize);
		int y = Mathf.FloorToInt((point.z + m_gridSize / 2f) / m_gridSize);
		return new Vector2Int(x, y);
	}

	public Vector3 GetGridPos(Vector2Int grid)
	{
		return new Vector3((float)grid.x * m_gridSize, 0f, (float)grid.y * m_gridSize);
	}
}
