		{
			WearNTear component = GetComponent<WearNTear>();
			component.m_onDamaged = (Action)Delegate.Combine(component.m_onDamaged, new Action(OnDamaged));
			m_piece = GetComponent<Piece>();
			if ((bool)m_areaMarker)
			{
				m_areaMarker.gameObject.SetActive(value: false);
			}
			if ((bool)m_inRangeEffect)
			{
				m_inRangeEffect.SetActive(value: false);
			}
			m_allAreas.Add(this);
			InvokeRepeating("UpdateStatus", 0f, 1f);
			m_nview.Register<long>("ToggleEnabled", RPC_ToggleEnabled);
			m_nview.Register<long, string>("TogglePermitted", RPC_TogglePermitted);
			m_nview.Register("FlashShield", RPC_FlashShield);
			if (m_enabledByDefault && m_nview.IsOwner())
			{
				m_nview.GetZDO().Set(ZDOVars.s_enabled, value: true);
			}
		}
	}

	private void OnDestroy()
	{
		m_allAreas.Remove(this);
	}

	private void UpdateStatus()
	{
		bool flag = IsEnabled();
		m_enabledEffect.SetActive(flag);
		m_flashAvailable = true;
		Material[] materials = m_model.materials;
		foreach (Material material in materials)
		{
			if (flag)
			{
				material.EnableKeyword("_EMISSION");
			}
			else
			{
				material.DisableKeyword("_EMISSION");
			}
		}
	}

	public string GetHoverText()
	{
		if (!m_nview.IsValid())
		{
			return "";
		}
		if (Player.m_localPlayer == null)
		{
			return "";
		}
		if (m_ownerFaction != Character.Faction.Players)
		{
			return Localization.instance.Localize(m_name);
		}
		ShowAreaMarker();
		StringBuilder stringBuilder = new StringBuilder(256);
		if (m_piece.IsCreator())
		{
			if (IsEnabled())
			{
				stringBuilder.Append(m_name + " ( $piece_guardstone_active )");
				stringBuilder.Append("\n$piece_guardstone_owner:" + GetCreatorName());
				stringBuilder.Append("\n[<color=yellow><b>$KEY_Use</b></color>] $piece_guardstone_deactivate");
			}
			else
			{
				stringBuilder.Append(m_name + " ($piece_guardstone_inactive )");
				stringBuilder.Append("\n$piece_guardstone_owner:" + GetCreatorName());
				stringBuilder.Append("\n[<color=yellow><b>$KEY_Use</b></color>] $piece_guardstone_activate");
			}
		}
		else if (IsEnabled())
		{
			stringBuilder.Append(m_name + " ( $piece_guardstone_active )");
			stringBuilder.Append("\n$piece_guardstone_owner:" + GetCreatorName());
		}
		else
		{
			stringBuilder.Append(m_name + " ( $piece_guardstone_inactive )");
			stringBuilder.Append("\n$piece_guardstone_owner:" + GetCreatorName());
			if (IsPermitted(Player.m_localPlayer.GetPlayerID()))
			{
				stringBuilder.Append("\n[<color=yellow><b>$KEY_Use</b></color>] $piece_guardstone_remove");
			}
			else
			{
				stringBuilder.Append("\n[<color=yellow><b>$KEY_Use</b></color>] $piece_guardstone_add");
			}
		}
		AddUserList(stringBuilder);
		return Localization.instance.Localize(stringBuilder.ToString());
	}

	private void AddUserList(StringBuilder text)
	{
		List<KeyValuePair<long, string>> permittedPlayers = GetPermittedPlayers();
		text.Append("\n$piece_guardstone_additional: ");
		for (int i = 0; i < permittedPlayers.Count; i++)
		{
			text.Append(CensorShittyWords.FilterUGC(permittedPlayers[i].Value, UGCType.CharacterName, m_piece.GetCreator()));
			if (i != permittedPlayers.Count - 1)
			{
				text.Append(", ");
			}
		}
	}

	private void RemovePermitted(long playerID)
	{
		List<KeyValuePair<long, string>> permittedPlayers = GetPermittedPlayers();
		if (permittedPlayers.RemoveAll((KeyValuePair<long, string> x) => x.Key == playerID) > 0)
		{
			SetPermittedPlayers(permittedPlayers);
			m_removedPermittedEffect.Create(base.transform.position, base.transform.rotation);
		}
	}

	private bool IsPermitted(long playerID)
	{
		foreach (KeyValuePair<long, string> permittedPlayer in GetPermittedPlayers())
		{
			if (permittedPlayer.Key == playerID)
			{
				return true;
			}
		}
		return false;
	}

	private void AddPermitted(long playerID, string playerName)
	{
		List<KeyValuePair<long, string>> permittedPlayers = GetPermittedPlayers();
		foreach (KeyValuePair<long, string> item in permittedPlayers)
		{
			if (item.Key == playerID)
			{
				return;
			}
		}
		permittedPlayers.Add(new KeyValuePair<long, string>(playerID, playerName));
		SetPermittedPlayers(permittedPlayers);
		m_addPermittedEffect.Create(base.transform.position, base.transform.rotation);
	}

	private void SetPermittedPlayers(List<KeyValuePair<long, string>> users)
	{
		m_nview.GetZDO().Set(ZDOVars.s_permitted, users.Count);
		for (int i = 0; i < users.Count; i++)
		{
			KeyValuePair<long, string> keyValuePair = users[i];
			m_nview.GetZDO().Set("pu_id" + i, keyValuePair.Key);
			m_nview.GetZDO().Set("pu_name" + i, keyValuePair.Value);
		}
	}

	private List<KeyValuePair<long, string>> GetPermittedPlayers()
	{
		List<KeyValuePair<long, string>> list = new List<KeyValuePair<long, string>>();
		int num = m_nview.GetZDO().GetInt(ZDOVars.s_permitted);
		for (int i = 0; i < num; i++)
		{
			long num2 = m_nview.GetZDO().GetLong("pu_id" + i, 0L);
			string value = m_nview.GetZDO().GetString("pu_name" + i);
			if (num2 != 0L)
			{
				list.Add(new KeyValuePair<long, string>(num2, value));
			}
		}
		return list;
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid human, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		if (m_ownerFaction != Character.Faction.Players)
		{
			return false;
		}
		Player player = human as Player;
		if (m_piece.IsCreator())
		{
			m_nview.InvokeRPC("ToggleEnabled", player.GetPlayerID());
			return true;
		}
		if (IsEnabled())
		{
			return false;
		}
		m_nview.InvokeRPC("TogglePermitted", player.GetPlayerID(), player.GetPlayerName());
		return true;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void RPC_TogglePermitted(long uid, long playerID, string name)
	{
		if (m_nview.IsOwner() && !IsEnabled())
		{
			if (IsPermitted(playerID))
			{
				RemovePermitted(playerID);
			}
			else
			{
				AddPermitted(playerID, name);
			}
		}
	}

	private void RPC_ToggleEnabled(long uid, long playerID)
	{
		ZLog.Log("Toggle enabled from " + playerID + "  creator is " + m_piece.GetCreator());
		if (m_nview.IsOwner() && m_piece.GetCreator() == playerID)
		{
			SetEnabled(!IsEnabled());
		}
	}

	private bool IsEnabled()
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		return m_nview.GetZDO().GetBool(ZDOVars.s_enabled);
	}

	private void SetEnabled(bool enabled)
	{
		m_nview.GetZDO().Set(ZDOVars.s_enabled, enabled);
		UpdateStatus();
		if (enabled)
		{
			m_activateEffect.Create(base.transform.position, base.transform.rotation);
		}
		else
		{
			m_deactivateEffect.Create(base.transform.position, base.transform.rotation);
		}
	}

	public void Setup(string name)
	{
		m_nview.GetZDO().Set(ZDOVars.s_creatorName, name);
	}

	public void PokeAllAreasInRange()
	{
		foreach (PrivateArea allArea in m_allAreas)
		{
			if (!(allArea == this) && IsInside(allArea.transform.position, 0f))
			{
				allArea.StartInRangeEffect();
			}
		}
	}

	private void StartInRangeEffect()
	{
		m_inRangeEffect.SetActive(value: true);
		CancelInvoke("StopInRangeEffect");
		Invoke("StopInRangeEffect", 0.2f);
	}

	private void StopInRangeEffect()
	{
		m_inRangeEffect.SetActive(value: false);
	}

	public void PokeConnectionEffects()
	{
		List<PrivateArea> connectedAreas = GetConnectedAreas();
		StartConnectionEffects();
		foreach (PrivateArea item in connectedAreas)
		{
			item.StartConnectionEffects();
		}
	}

	private void StartConnectionEffects()
	{
		List<PrivateArea> list = new List<PrivateArea>();
		foreach (PrivateArea allArea in m_allAreas)
		{
			if (!(allArea == this) && IsInside(allArea.transform.position, 0f))
			{
				list.Add(allArea);
			}
		}
		Vector3 vector = base.transform.position + Vector3.up * 1.4f;
		if (m_connectionInstances.Count != list.Count)
		{
			StopConnectionEffects();
			for (int i = 0; i < list.Count; i++)
			{
				GameObject item = UnityEngine.Object.Instantiate(m_connectEffect, vector, Quaternion.identity, base.transform);
				m_connectionInstances.Add(item);
			}
		}
		if (m_connectionInstances.Count != 0)
		{
			for (int j = 0; j < list.Count; j++)
			{
				Vector3 vector2 = list[j].transform.position + Vector3.up * 1.4f - vector;
				Quaternion rotation = Quaternion.LookRotation(vector2.normalized);
				GameObject obj = m_connectionInstances[j];
				obj.transform.position = vector;
				obj.transform.rotation = rotation;
				obj.transform.localScale = new Vector3(1f, 1f, vector2.magnitude);
			}
			CancelInvoke("StopConnectionEffects");
			Invoke("StopConnectionEffects", 0.3f);
		}
	}

	private void StopConnectionEffects()
	{
		foreach (GameObject connectionInstance in m_connectionInstances)
		{
			UnityEngine.Object.Destroy(connectionInstance);
		}
		m_connectionInstances.Clear();
	}

	private string GetCreatorName()
	{
		return CensorShittyWords.FilterUGC(m_nview.GetZDO().GetString(ZDOVars.s_creatorName), UGCType.CharacterName, m_piece.GetCreator());
	}

	public static bool OnObjectDamaged(Vector3 point, Character attacker, bool destroyed)
	{
		foreach (PrivateArea allArea in m_allAreas)
		{
			if (allArea.IsEnabled() && allArea.IsInside(point, 0f))
			{
				allArea.OnObjectDamaged(attacker, destroyed);
				return true;
			}
		}
		return false;
	}

	public static bool CheckAccess(Vector3 point, float radius = 0f, bool flash = true, bool wardCheck = false)
	{
		List<PrivateArea> list = new List<PrivateArea>();
		bool flag = true;
		if (wardCheck)
		{
			flag = true;
			foreach (PrivateArea allArea in m_allAreas)
			{
				if (allArea.IsEnabled() && allArea.IsInside(point, radius) && !allArea.HaveLocalAccess())
				{
					flag = false;
					list.Add(allArea);
				}
			}
		}
		else
		{
			flag = false;
			foreach (PrivateArea allArea2 in m_allAreas)
			{
				if (allArea2.IsEnabled() && allArea2.IsInside(point, radius))
				{
					if (allArea2.HaveLocalAccess())
					{
						flag = true;
					}
					else
					{
						list.Add(allArea2);
					}
				}
			}
		}
		if (!flag && list.Count > 0)
		{
			if (flash)
			{
				foreach (PrivateArea item in list)
				{
					item.FlashShield(flashConnected: false);
				}
			}
			return false;
		}
		return true;
	}

	private bool HaveLocalAccess()
	{
		if (m_piece.IsCreator())
		{
			return true;
		}
		if (IsPermitted(Player.m_localPlayer.GetPlayerID()))
		{
			return true;
		}
		return false;
	}

	private List<PrivateArea> GetConnectedAreas(bool forceUpdate = false)
	{
		if (Time.time - m_connectionUpdateTime > m_updateConnectionsInterval || forceUpdate)
		{
			GetAllConnectedAreas(m_connectedAreas);
			m_connectionUpdateTime = Time.time;
		}
		return m_connectedAreas;
	}

	private void GetAllConnectedAreas(List<PrivateArea> areas)
	{
		Queue<PrivateArea> queue = new Queue<PrivateArea>();
		queue.Enqueue(this);
		foreach (PrivateArea allArea in m_allAreas)
		{
			allArea.m_tempChecked = false;
		}
		m_tempChecked = true;
		while (queue.Count > 0)
		{
			PrivateArea privateArea = queue.Dequeue();
			foreach (PrivateArea allArea2 in m_allAreas)
			{
				if (!allArea2.m_tempChecked && allArea2.IsEnabled() && allArea2.IsInside(privateArea.transform.position, 0f))
				{
					allArea2.m_tempChecked = true;
					queue.Enqueue(allArea2);
					areas.Add(allArea2);
				}
			}
		}
	}

	private void OnObjectDamaged(Character attacker, bool destroyed)
	{
		FlashShield(flashConnected: false);
		if (m_ownerFaction == Character.Faction.Players)
		{
			return;
		}
		List<Character> list = new List<Character>();
		Character.GetCharactersInRange(base.transform.position, m_radius * 2f, list);
		foreach (Character item in list)
		{
			if (item.GetFaction() == m_ownerFaction)
			{
				MonsterAI component = item.GetComponent<MonsterAI>();
				if ((bool)component)
				{
					component.OnPrivateAreaAttacked(attacker, destroyed);
				}
				NpcTalk component2 = item.GetComponent<NpcTalk>();
				if ((bool)component2)
				{
					component2.OnPrivateAreaAttacked(attacker);
				}
			}
		}
	}

	private void FlashShield(bool flashConnected)
	{
		if (!m_flashAvailable)
		{
			return;
		}
		m_flashAvailable = false;
		m_nview.InvokeRPC(ZNetView.Everybody, "FlashShield");
		if (!flashConnected)
		{
			return;
		}
		foreach (PrivateArea connectedArea in GetConnectedAreas())
		{
			if (connectedArea.m_nview.IsValid())
			{
				connectedArea.m_nview.InvokeRPC(ZNetView.Everybody, "FlashShield");
			}
		}
	}

	private void RPC_FlashShield(long uid)
	{
		m_flashEffect.Create(base.transform.position, Quaternion.identity);
	}

	public static bool InsideFactionArea(Vector3 point, Character.Faction faction)
	{
		foreach (PrivateArea allArea in m_allAreas)
		{
			if (allArea.m_ownerFaction == faction && allArea.IsInside(point, 0f))
			{
				return true;
			}
		}
		return false;
	}

	private bool IsInside(Vector3 point, float radius)
	{
		return Utils.DistanceXZ(base.transform.position, point) < m_radius + radius;
	}

	public void ShowAreaMarker()
	{
		if ((bool)m_areaMarker)
		{
			m_areaMarker.gameObject.SetActive(value: true);
			CancelInvoke("HideMarker");
			Invoke("HideMarker", 0.5f);
		}
	}

	private void HideMarker()
	{
		m_areaMarker.gameObject.SetActive(value: false);
	}

	private void OnDamaged()
	{
		if (IsEnabled())
		{
			FlashShield(flashConnected: false);
		}
	}

	private void OnDrawGizmosSelected()
	{
	}
}
using System;
using UnityEngine;

public class Procreation : MonoBehaviour
{
	public float m_updateInterval = 10f;

	public float m_totalCheckRange = 10f;

	public int m_maxCreatures = 4;

	public float m_partnerCheckRange = 3f;

	public float m_pregnancyChance = 0.5f;

	public float m_pregnancyDuration = 10f;

	public int m_requiredLovePoints = 4;

	public GameObject m_offspring;

	public int m_minOffspringLevel;

	public float m_spawnOffset = 2f;

	public float m_spawnOffsetMax;

	public bool m_spawnRandomDirection;

	public GameObject m_seperatePartner;

	public GameObject m_noPartnerOffspring;

	public EffectList m_birthEffects = new EffectList();

	public EffectList m_loveEffects = new EffectList();

	private GameObject m_myPrefab;

	private GameObject m_offspringPrefab;

	private ZNetView m_nview;

	private BaseAI m_baseAI;

	private Character m_character;

	private Tameable m_tameable;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_baseAI = GetComponent<BaseAI>();
		m_character = GetComponent<Character>();
		m_tameable = GetComponent<Tameable>();
		InvokeRepeating("Procreate", UnityEngine.Random.Range(m_updateInterval, m_updateInterval + m_updateInterval * 0.5f), m_updateInterval);
	}

	private void Procreate()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner() || !m_tameable.IsTamed())
		{
			return;
		}
		if (m_offspringPrefab == null)
		{
			string prefabName = Utils.GetPrefabName(m_offspring);
			m_offspringPrefab = ZNetScene.instance.GetPrefab(prefabName);
			int prefab = m_nview.GetZDO().GetPrefab();
			m_myPrefab = ZNetScene.instance.GetPrefab(prefab);
		}
		if (IsPregnant())
		{
			if (!IsDue())
			{
				return;
			}
			ResetPregnancy();
			GameObject original = m_offspringPrefab;
			if ((bool)m_noPartnerOffspring)
			{
				int nrOfInstances = SpawnSystem.GetNrOfInstances(m_seperatePartner ? m_seperatePartner : m_myPrefab, base.transform.position, m_partnerCheckRange, eventCreaturesOnly: false, procreationOnly: true);
				if ((!m_seperatePartner && nrOfInstances < 2) || ((bool)m_seperatePartner && nrOfInstances < 1))
				{
					original = m_noPartnerOffspring;
				}
			}
			Vector3 vector = base.transform.forward;
			if (m_spawnRandomDirection)
			{
				float f = UnityEngine.Random.Range(0f, MathF.PI * 2f);
				vector = new Vector3(Mathf.Cos(f), 0f, Mathf.Sin(f));
			}
			float num = ((m_spawnOffsetMax > 0f) ? UnityEngine.Random.Range(m_spawnOffset, m_spawnOffsetMax) : m_spawnOffset);
			GameObject gameObject = UnityEngine.Object.Instantiate(original, base.transform.position - vector * num, Quaternion.LookRotation(-base.transform.forward, Vector3.up));
			Character component = gameObject.GetComponent<Character>();
			if ((bool)component)
			{
				component.SetTamed(m_tameable.IsTamed());
				component.SetLevel(Mathf.Max(m_minOffspringLevel, m_character ? m_character.GetLevel() : m_minOffspringLevel));
			}
			else
			{
				gameObject.GetComponent<ItemDrop>()?.SetQuality(Mathf.Max(m_minOffspringLevel, m_character ? m_character.GetLevel() : m_minOffspringLevel));
			}
			m_birthEffects.Create(gameObject.transform.position, Quaternion.identity);
		}
		else
		{
			if (UnityEngine.Random.value <= m_pregnancyChance || ((bool)m_baseAI && m_baseAI.IsAlerted()) || m_tameable.IsHungry())
			{
				return;
			}
			int nrOfInstances2 = SpawnSystem.GetNrOfInstances(m_myPrefab, base.transform.position, m_totalCheckRange);
			int nrOfInstances3 = SpawnSystem.GetNrOfInstances(m_offspringPrefab, base.transform.position, m_totalCheckRange);
			if (nrOfInstances2 + nrOfInstances3 >= m_maxCreatures)
			{
				return;
			}
			int nrOfInstances4 = SpawnSystem.GetNrOfInstances(m_seperatePartner ? m_seperatePartner : m_myPrefab, base.transform.position, m_partnerCheckRange, eventCreaturesOnly: false, procreationOnly: true);
			if ((bool)m_noPartnerOffspring || (((bool)m_seperatePartner || nrOfInstances4 >= 2) && (!m_seperatePartner || nrOfInstances4 >= 1)))
			{
				if (nrOfInstances4 > 0)
				{
					m_loveEffects.Create(base.transform.position, base.transform.rotation);
				}
				int lovePoints = GetLovePoints();
				lovePoints++;
				m_nview.GetZDO().Set(ZDOVars.s_lovePoints, lovePoints);
				if (lovePoints >= m_requiredLovePoints)
				{
					m_nview.GetZDO().Set(ZDOVars.s_lovePoints, 0);
					MakePregnant();
				}
			}
		}
	}

	public int GetLovePoints()
	{
		return m_nview.GetZDO().GetInt(ZDOVars.s_lovePoints);
	}

	public bool ReadyForProcreation()
	{
		if (m_tameable.IsTamed() && !IsPregnant())
		{
			return !m_tameable.IsHungry();
		}
		return false;
	}

	private void MakePregnant()
	{
		m_nview.GetZDO().Set(ZDOVars.s_pregnant, ZNet.instance.GetTime().Ticks);
	}

	private void ResetPregnancy()
	{
		m_nview.GetZDO().Set(ZDOVars.s_pregnant, 0L);
	}

	private bool IsDue()
	{
		long num = m_nview.GetZDO().GetLong(ZDOVars.s_pregnant, 0L);
		if (num == 0L)
		{
			return false;
		}
		DateTime dateTime = new DateTime(num);
		return (ZNet.instance.GetTime() - dateTime).TotalSeconds > (double)m_pregnancyDuration;
	}

	private bool IsPregnant()
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		return m_nview.GetZDO().GetLong(ZDOVars.s_pregnant, 0L) != 0;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Projectile : MonoBehaviour, IProjectile
{
	public ProjectileType m_type;

	public HitData.DamageTypes m_damage;

	public float m_aoe;

	public bool m_dodgeable;

	public bool m_blockable;

	public float m_adrenaline = 2f;

	public float m_attackForce;

	public float m_backstabBonus = 4f;

	public string m_statusEffect = "";

	private int m_statusEffectHash;

	public float m_healthReturn;

	public bool m_canHitWater;

	public float m_ttl = 4f;

	public float m_gravity;

	public float m_drag;

	public float m_rayRadius;

	public float m_hitNoise = 50f;

	public bool m_doOwnerRaytest;

	public bool m_stayAfterHitStatic;

	public bool m_stayAfterHitDynamic;

	public float m_stayTTL = 1f;

	public bool m_attachToRigidBody;

	public bool m_attachToClosestBone;

	public float m_attachPenetration;

	public float m_attachBoneNearify = 0.25f;

	public GameObject m_hideOnHit;

	public bool m_stopEmittersOnHit = true;

	public EffectList m_hitEffects = new EffectList();

	public EffectList m_hitWaterEffects = new EffectList();

	[Header("Bounce")]
	public bool m_bounce;

	public bool m_bounceOnWater;

	[Range(0f, 1f)]
	public float m_bouncePower = 0.85f;

	[Range(0f, 1f)]
	public float m_bounceRoughness = 0.3f;

	[Min(1f)]
	public int m_maxBounces = 99;

	[Min(0.01f)]
	public float m_minBounceVel = 0.25f;

	[Header("Spawn on hit")]
	public bool m_respawnItemOnHit;

	public bool m_spawnOnTtl;

	public GameObject m_spawnOnHit;

	[Range(0f, 1f)]
	public float m_spawnOnHitChance = 1f;

	public int m_spawnCount = 1;

	public List<GameObject> m_randomSpawnOnHit = new List<GameObject>();

	public int m_randomSpawnOnHitCount = 1;

	public bool m_randomSpawnSkipLava;

	public bool m_showBreakMessage;

	public bool m_staticHitOnly;

	public bool m_groundHitOnly;

	public Vector3 m_spawnOffset = Vector3.zero;

	public bool m_copyProjectileRotation = true;

	public bool m_spawnRandomRotation;

	public bool m_spawnFacingRotation;

	public EffectList m_spawnOnHitEffects = new EffectList();

	public OnProjectileHit m_onHit;

	[Header("Projectile Spawning")]
	public bool m_spawnProjectileNewVelocity;

	public float m_spawnProjectileMinVel = 1f;

	public float m_spawnProjectileMaxVel = 5f;

	[Range(0f, 1f)]
	public float m_spawnProjectileRandomDir;

	public bool m_spawnProjectileHemisphereDir;

	public bool m_projectilesInheritHitData;

	public bool m_onlySpawnedProjectilesDealDamage;

	public bool m_divideDamageBetweenProjectiles;

	[Header("Rotate projectile")]
	public float m_rotateVisual;

	public float m_rotateVisualY;

	public float m_rotateVisualZ;

	public GameObject m_visual;

	public bool m_canChangeVisuals;

	private ZNetView m_nview;

	private GameObject m_attachParent;

	private Vector3 m_attachParentOffset;

	private Quaternion m_attachParentOffsetRot;

	private bool m_hasLeftShields = true;

	private Vector3 m_vel = Vector3.zero;

	private Character m_owner;

	[NonSerialized]
	public Skills.SkillType m_skill;

	[NonSerialized]
	public float m_raiseSkillAmount = 1f;

	private ItemDrop.ItemData m_weapon;

	private ItemDrop.ItemData m_ammo;

	[NonSerialized]
	public ItemDrop.ItemData m_spawnItem;

	private HitData m_originalHitData;

	private bool m_didHit;

	private int m_bounceCount;

	private bool m_didBounce;

	private bool m_changedVisual;

	[HideInInspector]
	public Vector3 m_startPoint;

	private bool m_haveStartPoint;

	private static int s_rayMaskSolids;

	public bool HasBeenOutsideShields => m_hasLeftShields;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		if (s_rayMaskSolids == 0)
		{
			s_rayMaskSolids = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece", "piece_nonsolid", "terrain", "character", "character_net", "character_ghost", "hitbox", "character_noenv", "vehicle");
		}
		if (!string.IsNullOrEmpty(m_statusEffect))
		{
			m_statusEffectHash = m_statusEffect.GetStableHashCode();
		}
		m_nview.Register<float>("RPC_SetStayTTL", RPC_SetStayTTL);
		m_nview.Register("RPC_OnHit", RPC_OnHit);
		m_nview.Register<ZDOID>("RPC_Attach", RPC_Attach);
		UpdateVisual();
	}

	public string GetTooltipString(int itemQuality)
	{
		return "";
	}

	private void FixedUpdate()
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		UpdateRotation(Time.fixedDeltaTime);
		if (!m_nview.IsOwner())
		{
			return;
		}
		if (!m_didHit)
		{
			Vector3 vector = base.transform.position;
			if (m_haveStartPoint)
			{
				vector = m_startPoint;
			}
			m_vel += Vector3.down * (m_gravity * Time.fixedDeltaTime);
			float num = Mathf.Pow(m_vel.magnitude, 2f) * m_drag * Time.fixedDeltaTime;
			m_vel += num * -m_vel.normalized;
			base.transform.position += m_vel * Time.fixedDeltaTime;
			if (m_rotateVisual == 0f)
			{
				base.transform.rotation = Quaternion.LookRotation(m_vel);
			}
			if (m_canHitWater)
			{
				float liquidLevel = Floating.GetLiquidLevel(base.transform.position);
				if (base.transform.position.y < liquidLevel)
				{
					OnHit(null, base.transform.position, water: true, Vector3.up);
				}
			}
			m_didBounce = false;
			if (!m_didHit)
			{
				Vector3 vector2 = base.transform.position - vector;
				if (!m_haveStartPoint)
				{
					vector -= vector2.normalized * (vector2.magnitude * 0.5f);
				}
				RaycastHit[] array = ((m_rayRadius != 0f) ? Physics.SphereCastAll(vector, m_rayRadius, vector2.normalized, vector2.magnitude, s_rayMaskSolids) : Physics.RaycastAll(vector, vector2.normalized, vector2.magnitude * 1.5f, s_rayMaskSolids));
				Debug.DrawLine(vector, base.transform.position, (array.Length != 0) ? Color.red : Color.yellow, 5f);
				if (array.Length != 0)
				{
					Array.Sort(array, (RaycastHit x, RaycastHit y) => x.distance.CompareTo(y.distance));
					RaycastHit[] array2 = array;
					for (int num2 = 0; num2 < array2.Length; num2++)
					{
						RaycastHit raycastHit = array2[num2];
						Vector3 hitPoint = ((raycastHit.distance == 0f) ? vector : raycastHit.point);
						OnHit(raycastHit.collider, hitPoint, water: false, raycastHit.normal);
						if (m_didHit || m_didBounce)
						{
							break;
						}
					}
				}
			}
			if (m_haveStartPoint)
			{
				m_haveStartPoint = false;
			}
		}
		if (m_ttl > 0f)
		{
			m_ttl -= Time.fixedDeltaTime;
			if (m_ttl <= 0f)
			{
				if (m_spawnOnTtl)
				{
					SpawnOnHit(null, null, -m_vel.normalized);
				}
				ZNetScene.instance.Destroy(base.gameObject);
			}
		}
		if (m_nview.IsValid())
		{
			ShieldGenerator.CheckProjectile(this);
		}
	}

	private void Update()
	{
		UpdateVisual();
	}

	private void LateUpdate()
	{
		if ((bool)m_attachParent)
		{
			Vector3 point = m_attachParent.transform.position - m_attachParentOffset;
			Quaternion quaternion = m_attachParent.transform.rotation * m_attachParentOffsetRot;
			base.transform.position = Utils.RotatePointAroundPivot(point, m_attachParent.transform.position, quaternion);
			base.transform.localRotation = quaternion;
		}
	}

	private void UpdateVisual()
	{
		if (!m_canChangeVisuals || (object)m_nview == null || !m_nview.IsValid() || m_changedVisual || !m_nview.GetZDO().GetString(ZDOVars.s_visual, out var value))
		{
			return;
		}
		ZLog.Log("Visual prefab is " + value);
		GameObject itemPrefab = ObjectDB.instance.GetItemPrefab(value);
		if ((object)itemPrefab.GetComponent<ItemDrop>() != null)
		{
			GameObject attachPrefab = ItemStand.GetAttachPrefab(itemPrefab);
			if (!(attachPrefab == null))
			{
				attachPrefab = ItemStand.GetAttachGameObject(attachPrefab);
				m_visual.gameObject.SetActive(value: false);
				m_visual = UnityEngine.Object.Instantiate(attachPrefab, base.transform);
				m_visual.transform.localPosition = Vector3.zero;
				m_changedVisual = true;
			}
		}
	}

	public Vector3 GetVelocity()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner())
		{
			return Vector3.zero;
		}
		if (m_didHit)
		{
			return Vector3.zero;
		}
		return m_vel;
	}

	private void UpdateRotation(float dt)
	{
		if (!(m_visual == null) && ((double)m_rotateVisual != 0.0 || (double)m_rotateVisualY != 0.0 || (double)m_rotateVisualZ != 0.0))
		{
			m_visual.transform.Rotate(new Vector3(m_rotateVisual * dt, m_rotateVisualY * dt, m_rotateVisualZ * dt));
		}
	}

	public void Setup(Character owner, Vector3 velocity, float hitNoise, HitData hitData, ItemDrop.ItemData item, ItemDrop.ItemData ammo)
	{
		m_owner = owner;
		m_vel = velocity;
		m_ammo = ammo;
		m_weapon = item;
		if (hitNoise >= 0f)
		{
			m_hitNoise = hitNoise;
		}
		if (hitData != null)
		{
			m_originalHitData = hitData;
			m_damage = hitData.m_damage;
			m_blockable = hitData.m_blockable;
			m_dodgeable = hitData.m_dodgeable;
			m_attackForce = hitData.m_pushForce;
			m_backstabBonus = hitData.m_backstabBonus;
			m_healthReturn = hitData.m_healthReturn;
			if (m_statusEffectHash != hitData.m_statusEffectHash)
			{
				m_statusEffectHash = hitData.m_statusEffectHash;
				m_statusEffect = "";
			}
			m_skill = hitData.m_skill;
			m_raiseSkillAmount = hitData.m_skillRaiseAmount;
		}
		if (m_spawnOnHit != null && m_onlySpawnedProjectilesDealDamage)
		{
			m_damage.Modify(0f);
		}
		if (m_respawnItemOnHit)
		{
			m_spawnItem = item;
		}
		if (m_doOwnerRaytest && (bool)owner)
		{
			m_startPoint = owner.GetCenterPoint();
			m_startPoint.y = base.transform.position.y;
			m_haveStartPoint = true;
		}
		else
		{
			m_startPoint = base.transform.position;
		}
		LineConnect component = GetComponent<LineConnect>();
		if ((bool)component && (bool)owner)
		{
			component.SetPeer(owner.GetZDOID());
		}
		m_hasLeftShields = !ShieldGenerator.IsInsideShield(base.transform.position);
	}

	private void DoAOE(Vector3 hitPoint, ref bool hitCharacter, ref bool didDamage)
	{
		Collider[] array = Physics.OverlapSphere(hitPoint, m_aoe, s_rayMaskSolids, QueryTriggerInteraction.UseGlobal);
		HashSet<GameObject> hashSet = new HashSet<GameObject>();
		Collider[] array2 = array;
		foreach (Collider collider in array2)
		{
			GameObject gameObject = FindHitObject(collider);
			IDestructible component = gameObject.GetComponent<IDestructible>();
			if (component == null || hashSet.Contains(gameObject))
			{
				continue;
			}
			hashSet.Add(gameObject);
			if (IsValidTarget(component))
			{
				if (component is Character)
				{
					hitCharacter = true;
				}
				Vector3 vector = collider.ClosestPointOnBounds(hitPoint);
				Vector3 vector2 = ((Vector3.Distance(vector, hitPoint) > 0.1f) ? (vector - hitPoint) : m_vel);
				vector2.y = 0f;
				vector2.Normalize();
				HitData hitData = new HitData();
				hitData.m_hitCollider = collider;
				hitData.m_damage = m_damage;
				hitData.m_pushForce = m_attackForce;
				hitData.m_backstabBonus = m_backstabBonus;
				hitData.m_ranged = true;
				hitData.m_point = vector;
				hitData.m_dir = vector2.normalized;
				hitData.m_statusEffectHash = m_statusEffectHash;
				hitData.m_skillLevel = (m_owner ? m_owner.GetSkillLevel(m_skill) : 1f);
				hitData.m_dodgeable = m_dodgeable;
				hitData.m_blockable = m_blockable;
				hitData.m_skill = m_skill;
				hitData.m_skillRaiseAmount = m_raiseSkillAmount;
				hitData.SetAttacker(m_owner);
				hitData.m_hitType = ((!(hitData.GetAttacker() is Player)) ? HitData.HitType.EnemyHit : HitData.HitType.PlayerHit);
				hitData.m_healthReturn = m_healthReturn;
				component.Damage(hitData);
				didDamage = true;
			}
		}
	}

	private bool IsValidTarget(IDestructible destr)
	{
		Character character = destr as Character;
		if ((bool)character)
		{
			if (character == m_owner)
			{
				return false;
			}
			if (m_owner != null)
			{
				bool flag = BaseAI.IsEnemy(m_owner, character) || ((bool)character.GetBaseAI() && character.GetBaseAI().IsAggravatable() && m_owner.IsPlayer());
				if (!m_owner.IsPlayer() && !flag)
				{
					return false;
				}
				if (m_owner.IsPlayer() && !m_owner.IsPVPEnabled() && !flag)
				{
					return false;
				}
			}
			if (m_dodgeable && character.IsDodgeInvincible())
			{
				if (character.IsPlayer())
				{
					(character as Player).HitWhileDodging();
				}
				return false;
			}
		}
		return true;
	}

	public void OnHit(Collider collider, Vector3 hitPoint, bool water, Vector3 normal)
	{
		GameObject gameObject = (collider ? FindHitObject(collider) : null);
		bool didDamage = false;
		bool hitCharacter = false;
		bool flag = m_bounce && normal != Vector3.zero;
		if (water)
		{
			flag = flag && m_bounceOnWater;
		}
		IDestructible destructible = (gameObject ? gameObject.GetComponent<IDestructible>() : null);
		if (destructible != null)
		{
			hitCharacter = destructible is Character;
			flag = flag && !hitCharacter;
			if (!IsValidTarget(destructible))
			{
				return;
			}
		}
		if ((bool)collider)
		{
			IHitProjectile component = collider.GetComponent<IHitProjectile>();
			if (component != null && !component.OnProjectileHit(m_owner, m_weapon, this, collider, hitPoint, water, normal))
			{
				return;
			}
		}
		if (flag && m_bounceCount < m_maxBounces && m_vel.magnitude > m_minBounceVel)
		{
			Vector3 normalized = m_vel.normalized;
			if (m_bounceRoughness > 0f)
			{
				Vector3 onUnitSphere = UnityEngine.Random.onUnitSphere;
				float f = Vector3.Dot(normal, onUnitSphere);
				onUnitSphere *= Mathf.Sign(f);
				normal = Vector3.Lerp(normal, onUnitSphere, m_bounceRoughness).normalized;
			}
			m_vel = Vector3.Reflect(normalized, normal) * (m_vel.magnitude * m_bouncePower);
			m_bounceCount++;
			m_didBounce = true;
			return;
		}
		if (m_aoe > 0f)
		{
			DoAOE(hitPoint, ref hitCharacter, ref didDamage);
		}
		else if (destructible != null)
		{
			HitData hitData = new HitData();
			hitData.m_hitCollider = collider;
			hitData.m_damage = m_damage;
			hitData.m_pushForce = m_attackForce;
			hitData.m_backstabBonus = m_backstabBonus;
			hitData.m_point = hitPoint;
			hitData.m_dir = base.transform.forward;
			hitData.m_statusEffectHash = m_statusEffectHash;
			hitData.m_dodgeable = m_dodgeable;
			hitData.m_blockable = m_blockable;
			hitData.m_ranged = true;
			hitData.m_skill = m_skill;
			hitData.m_skillRaiseAmount = m_raiseSkillAmount;
			hitData.SetAttacker(m_owner);
			hitData.m_hitType = ((!(hitData.GetAttacker() is Player)) ? HitData.HitType.EnemyHit : HitData.HitType.PlayerHit);
			hitData.m_healthReturn = m_healthReturn;
			destructible.Damage(hitData);
			if (m_healthReturn > 0f && (bool)m_owner)
			{
				m_owner.Heal(m_healthReturn);
			}
			didDamage = true;
		}
		if (water)
		{
			m_hitWaterEffects.Create(hitPoint, Quaternion.identity);
		}
		else
		{
			m_hitEffects.Create(hitPoint, Quaternion.identity);
		}
		if (m_spawnOnHit != null || m_spawnItem != null || m_randomSpawnOnHit.Count > 0)
		{
			SpawnOnHit(gameObject, collider, normal);
		}
		m_onHit?.Invoke(collider, hitPoint, water);
		if (m_hitNoise > 0f)
		{
			BaseAI.DoProjectileHitNoise(base.transform.position, m_hitNoise, m_owner);
		}
		if (didDamage && m_owner != null && hitCharacter)
		{
			m_owner.RaiseSkill(m_skill, m_raiseSkillAmount);
			m_owner.AddAdrenaline(m_adrenaline);
		}
		m_didHit = true;
		base.transform.position = hitPoint;
		m_nview.InvokeRPC("RPC_OnHit");
		m_ttl = m_stayTTL;
		if ((bool)collider && collider.attachedRigidbody != null)
		{
			ZNetView componentInParent = collider.gameObject.GetComponentInParent<ZNetView>();
			if ((bool)componentInParent && (m_attachToClosestBone || m_attachToRigidBody))
			{
				m_nview.InvokeRPC("RPC_Attach", componentInParent.GetZDO().m_uid);
			}
			else if (!m_stayAfterHitDynamic)
			{
				ZNetScene.instance.Destroy(base.gameObject);
			}
		}
		else if (!m_stayAfterHitStatic)
		{
			ZNetScene.instance.Destroy(base.gameObject);
		}
	}

	private void RPC_OnHit(long sender)
	{
		if ((bool)m_hideOnHit)
		{
			m_hideOnHit.SetActive(value: false);
		}
		if (m_stopEmittersOnHit)
		{
			ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				ParticleSystem.EmissionModule emission = componentsInChildren[i].emission;
				emission.enabled = false;
			}
		}
	}

	private void RPC_Attach(long sender, ZDOID parent)
	{
		m_attachParent = ZNetScene.instance.FindInstance(parent);
		if (!m_attachParent)
		{
			return;
		}
		if (m_attachToClosestBone)
		{
			float dist = float.MaxValue;
			Animator componentInChildren = m_attachParent.gameObject.GetComponentInChildren<Animator>();
			if ((object)componentInChildren != null)
			{
				Utils.IterateHierarchy(componentInChildren.gameObject, delegate(GameObject obj)
				{
					float num = Vector3.Distance(base.transform.position, obj.transform.position);
					if (num < dist)
					{
						dist = num;
						m_attachParent = obj;
					}
				});
			}
		}
		base.transform.position += base.transform.forward * m_attachPenetration;
		base.transform.position += (m_attachParent.transform.position - base.transform.position) * m_attachBoneNearify;
		m_attachParentOffset = m_attachParent.transform.position - base.transform.position;
		m_attachParentOffsetRot = Quaternion.Inverse(m_attachParent.transform.localRotation * base.transform.localRotation);
	}

	private void SpawnOnHit(GameObject go, Collider collider, Vector3 normal)
	{
		if ((m_groundHitOnly && ((object)go == null || go.GetComponent<Heightmap>() == null)) || (m_staticHitOnly && (((bool)collider && collider.attachedRigidbody != null) || ((bool)go && go.GetComponent<IDestructible>() != null))))
		{
			return;
		}
		Vector3 vector = base.transform.position + base.transform.TransformDirection(m_spawnOffset);
		Quaternion rotation = Quaternion.identity;
		if (m_copyProjectileRotation)
		{
			rotation = base.transform.rotation;
		}
		if (m_spawnRandomRotation)
		{
			rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
		}
		if (m_spawnFacingRotation)
		{
			rotation = Quaternion.Euler(0f, base.transform.rotation.eulerAngles.y, 0f);
		}
		if (m_spawnOnHit != null && (m_spawnOnHitChance >= 1f || UnityEngine.Random.value < m_spawnOnHitChance))
		{
			for (int i = 0; i < m_spawnCount; i++)
			{
				GameObject gameObject = UnityEngine.Object.Instantiate(m_spawnOnHit, vector, rotation);
				Vector3 normalized = m_vel.normalized;
				Vector3 onUnitSphere = UnityEngine.Random.onUnitSphere;
				if (m_spawnProjectileHemisphereDir)
				{
					onUnitSphere *= Mathf.Sign(Vector3.Dot(normal, onUnitSphere));
				}
				normalized = Vector3.Lerp(normalized, onUnitSphere, m_spawnProjectileRandomDir).normalized;
				float num = m_vel.magnitude;
				if (m_spawnProjectileNewVelocity)
				{
					num = UnityEngine.Random.Range(m_spawnProjectileMinVel, m_spawnProjectileMaxVel);
				}
				IProjectile componentInChildren = gameObject.GetComponentInChildren<IProjectile>();
				if (componentInChildren == null)
				{
					continue;
				}
				gameObject.transform.position += normal * 0.25f;
				HitData hitData = null;
				if (m_projectilesInheritHitData)
				{
					hitData = m_originalHitData;
					if (m_divideDamageBetweenProjectiles)
					{
						hitData.m_damage.Modify(1f / (float)m_spawnCount);
					}
				}
				componentInChildren.Setup(m_owner, normalized * num, m_hitNoise, hitData, m_weapon, m_ammo);
			}
		}
		if (m_spawnItem != null)
		{
			ItemDrop.DropItem(m_spawnItem, 1, vector, base.transform.rotation);
		}
		if (m_randomSpawnOnHit.Count > 0 && (!m_randomSpawnSkipLava || !ZoneSystem.instance.IsLava(base.transform.position)))
		{
			for (int j = 0; j < m_randomSpawnOnHitCount; j++)
			{
				GameObject gameObject2 = m_randomSpawnOnHit[UnityEngine.Random.Range(0, m_randomSpawnOnHit.Count)];
				if ((bool)gameObject2)
				{
					UnityEngine.Object.Instantiate(gameObject2, vector, rotation).GetComponent<IProjectile>()?.Setup(m_owner, m_vel, m_hitNoise, null, null, m_ammo);
				}
			}
		}
		m_spawnOnHitEffects.Create(vector, Quaternion.identity);
	}

	public void SetStayTTL(float seconds)
	{
		if (seconds <= 0f)
		{
			seconds = 0.001f;
		}
		if ((bool)m_nview)
		{
			if (m_nview.IsOwner())
			{
				m_stayTTL = (m_ttl = seconds);
				return;
			}
			m_nview.InvokeRPC(m_nview.GetZDO().GetOwner(), "RPC_SetStayTTL", seconds);
		}
	}

	public void RPC_SetStayTTL(long sender, float sec)
	{
		m_stayTTL = (m_ttl = sec);
	}

	public static GameObject FindHitObject(Collider collider)
	{
		IDestructible componentInParent = collider.gameObject.GetComponentInParent<IDestructible>();
		if (componentInParent != null)
		{
			return (componentInParent as MonoBehaviour).gameObject;
		}
		if ((bool)collider.attachedRigidbody)
		{
			return collider.attachedRigidbody.gameObject;
		}
		return collider.gameObject;
	}

	public void TriggerShieldsLeftFlag()
	{
		m_hasLeftShields = true;
	}
}
using System;

[Flags]
public enum ProjectileType
{
	None = 0,
	Arrow = 1,
	Magic = 2,
	Bomb = 4,
	Physical = 8,
	Bolt = 0x10,
	Missile = 0x20,
	Spear = 0x40,
	Tar = 0x80,
	Fire = 0x100,
	Lava = 0x200,
