public class RadialOverlapPreventer : MonoBehaviour
{
	[SerializeField]
	private RectTransform m_elementInfoElement;

	[SerializeField]
	private RectTransform m_tooltipElement;

	[SerializeField]
	private RectTransform m_parentElement;

	private void Start()
	{
		PreventOverlap();
	}

	private void OnEnable()
	{
		PreventOverlap();
	}

	private void PreventOverlap()
	{
		float num = m_parentElement.rect.width * 0.5f;
		float num2 = AnchoredPositionAt(m_tooltipElement.anchoredPosition, m_tooltipElement.anchorMin, new Vector2(0.5f, 0.5f)).x + m_tooltipElement.rect.width * (1f - m_tooltipElement.pivot.x);
		float num3 = ((RadialData.SO.RadialSize == RadialSizeSetting.Big) ? RadialData.SO.RadialBigScale : RadialData.SO.RadialSmallScale);
		float num4 = RadialData.SO.RadialReferenceWidth * num3;
		float num5 = num - num2;
		int num6 = ((RadialData.SO.RadialSize == RadialSizeSetting.SmallEdge) ? 1 : 0);
		float num7 = Mathf.Clamp(Vector2.right.x * (float)num6 * num, num2, num);
		Vector2 anchoredPosition = AnchoredPositionAt(m_elementInfoElement.anchoredPosition, m_elementInfoElement.anchorMin, new Vector2(0.5f, 0.5f)) + m_elementInfoElement.rect.size * (new Vector2(0.5f, 0.5f) - m_elementInfoElement.pivot);
		m_elementInfoElement.localScale = Vector3.one * num3;
		if (num4 <= num5)
		{
			float num8 = num4 * 0.5f;
			float min = num2 + num8;
			float max = num - num8;
			anchoredPosition.x = Mathf.Clamp(num7, min, max);
		}
		else
		{
			float a = (num7 - num2) * 2f / RadialData.SO.RadialReferenceWidth;
			float b = (num - num7) * 2f / RadialData.SO.RadialReferenceWidth;
			float b2 = Mathf.Min(a, b);
			float num9 = Mathf.Min(num3, b2);
			m_elementInfoElement.localScale = new Vector3(num9, num9, num9);
			float num10 = RadialData.SO.RadialReferenceWidth * num9 * 0.5f;
			anchoredPosition.x = Mathf.Clamp(num7, num2 + num10, num - num10);
		}
		m_elementInfoElement.anchoredPosition = anchoredPosition;
	}

	private Vector2 AnchoredPositionAt(Vector2 currentPosition, Vector2 currentAnchor, Vector2 targetAnchor)
	{
		Vector2 size = m_parentElement.rect.size;
		Vector2 vector = targetAnchor - currentAnchor;
		Vector2 vector2 = new Vector2(size.x * vector.x, size.y * vector.y);
		return currentPosition - vector2;
	}
}
using System.Collections;
using UnityEngine;

public class Radiator : MonoBehaviour
{
	public GameObject m_projectile;

	public Collider m_emitFrom;

	public float m_rateMin = 2f;

	public float m_rateMax = 5f;

	public float m_velocity = 10f;

	public float m_offset = 0.1f;

	private ZNetView m_nview;

	private void Start()
	{
		m_nview = GetComponentInParent<ZNetView>();
	}

	private void OnEnable()
	{
		StartCoroutine("UpdateLoop");
	}

	private IEnumerator UpdateLoop()
	{
		while (true)
		{
			yield return new WaitForSeconds(Random.Range(m_rateMin, m_rateMax));
			if (m_nview.IsValid() && m_nview.IsOwner())
			{
				Vector3 onUnitSphere = Random.onUnitSphere;
				Vector3 position = base.transform.position;
				if (onUnitSphere.y < 0f)
				{
					onUnitSphere.y = 0f - onUnitSphere.y;
				}
				if ((bool)m_emitFrom)
				{
					position = m_emitFrom.ClosestPoint(m_emitFrom.transform.position + onUnitSphere * 1000f) + onUnitSphere * m_offset;
				}
				Object.Instantiate(m_projectile, position, Quaternion.LookRotation(onUnitSphere, Vector3.up)).GetComponent<Projectile>().Setup(null, onUnitSphere * m_velocity, 0f, null, null, null);
			}
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Ragdoll : MonoBehaviour
{
	public float m_velMultiplier = 1f;

	public float m_ttl;

	public Renderer m_mainModel;

	public EffectList m_removeEffect = new EffectList();

	public Action<Vector3> m_onDestroyed;

	public bool m_float;

	public float m_floatOffset = -0.1f;

	public bool m_dropItems = true;

	public GameObject m_lootSpawnJoint;

	private const float m_floatForce = 20f;

	private const float m_damping = 0.05f;

	private ZNetView m_nview;

	private Rigidbody[] m_bodies;

	private const float m_dropOffset = 0.75f;

	private const float m_dropArea = 0.5f;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_bodies = GetComponentsInChildren<Rigidbody>();
		Invoke("RemoveInitVel", 2f);
		if ((bool)m_mainModel)
		{
			float value = m_nview.GetZDO().GetFloat(ZDOVars.s_hue);
			float value2 = m_nview.GetZDO().GetFloat(ZDOVars.s_saturation);
			float value3 = m_nview.GetZDO().GetFloat(ZDOVars.s_value);
			m_mainModel.material.SetFloat("_Hue", value);
			m_mainModel.material.SetFloat("_Saturation", value2);
			m_mainModel.material.SetFloat("_Value", value3);
		}
		InvokeRepeating("DestroyNow", m_ttl, 1f);
	}

	public Vector3 GetAverageBodyPosition()
	{
		if (m_bodies.Length == 0)
		{
			return base.transform.position;
		}
		Vector3 zero = Vector3.zero;
		Rigidbody[] bodies = m_bodies;
		foreach (Rigidbody rigidbody in bodies)
		{
			zero += rigidbody.position;
		}
		return zero / m_bodies.Length;
	}

	private void DestroyNow()
	{
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			Vector3 vector = GetAverageBodyPosition();
			_ = Quaternion.identity;
			m_removeEffect.Create(vector, Quaternion.identity);
			if (m_lootSpawnJoint != null)
			{
				vector = m_lootSpawnJoint.transform.position;
			}
			SpawnLoot(vector);
			ZNetScene.instance.Destroy(base.gameObject);
		}
	}

	private void RemoveInitVel()
	{
		if (m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_initVel, Vector3.zero);
		}
	}

	private void Start()
	{
		Vector3 vec = m_nview.GetZDO().GetVec3(ZDOVars.s_initVel, Vector3.zero);
		if (vec != Vector3.zero)
		{
			vec.y = Mathf.Min(vec.y, 4f);
			Rigidbody[] bodies = m_bodies;
			for (int i = 0; i < bodies.Length; i++)
			{
				bodies[i].linearVelocity = vec * UnityEngine.Random.value;
			}
		}
	}

	public void Setup(Vector3 velocity, float hue, float saturation, float value, CharacterDrop characterDrop)
	{
		velocity.x *= m_velMultiplier;
		velocity.z *= m_velMultiplier;
		m_nview.GetZDO().Set(ZDOVars.s_initVel, velocity);
		m_nview.GetZDO().Set(ZDOVars.s_hue, hue);
		m_nview.GetZDO().Set(ZDOVars.s_saturation, saturation);
		m_nview.GetZDO().Set(ZDOVars.s_value, value);
		if ((bool)m_mainModel)
		{
			m_mainModel.material.SetFloat("_Hue", hue);
			m_mainModel.material.SetFloat("_Saturation", saturation);
			m_mainModel.material.SetFloat("_Value", value);
		}
		if ((bool)characterDrop && m_dropItems)
		{
			SaveLootList(characterDrop);
		}
	}

	private void SaveLootList(CharacterDrop characterDrop)
	{
		List<KeyValuePair<GameObject, int>> list = characterDrop.GenerateDropList();
		if (list.Count > 0)
		{
			ZDO zDO = m_nview.GetZDO();
			zDO.Set(ZDOVars.s_drops, list.Count);
			for (int i = 0; i < list.Count; i++)
			{
				KeyValuePair<GameObject, int> keyValuePair = list[i];
				int prefabHash = ZNetScene.instance.GetPrefabHash(keyValuePair.Key);
				zDO.Set("drop_hash" + i, prefabHash);
				zDO.Set("drop_amount" + i, keyValuePair.Value);
			}
		}
	}

	private void SpawnLoot(Vector3 center)
	{
		ZDO zDO = m_nview.GetZDO();
		int num = zDO.GetInt(ZDOVars.s_drops);
		if (num <= 0)
		{
			return;
		}
		List<KeyValuePair<GameObject, int>> list = new List<KeyValuePair<GameObject, int>>();
		for (int i = 0; i < num; i++)
		{
			int hash = zDO.GetInt("drop_hash" + i);
			int value = zDO.GetInt("drop_amount" + i);
			GameObject prefab = ZNetScene.instance.GetPrefab(hash);
			if (prefab == null)
			{
				ZLog.LogWarning("Ragdoll: Missing prefab:" + hash + " when dropping loot");
			}
			else
			{
				list.Add(new KeyValuePair<GameObject, int>(prefab, value));
			}
		}
		CharacterDrop.DropItems(list, center + Vector3.up * 0.75f, 0.5f);
	}

	private void FixedUpdate()
	{
		if (m_float)
		{
			UpdateFloating(Time.fixedDeltaTime);
		}
	}

	private void UpdateFloating(float dt)
	{
		Rigidbody[] bodies = m_bodies;
		foreach (Rigidbody rigidbody in bodies)
		{
			Vector3 worldCenterOfMass = rigidbody.worldCenterOfMass;
			worldCenterOfMass.y += m_floatOffset;
			float liquidLevel = Floating.GetLiquidLevel(worldCenterOfMass);
			if (worldCenterOfMass.y < liquidLevel)
			{
				float num = (liquidLevel - worldCenterOfMass.y) / 0.5f;
				Vector3 vector = Vector3.up * 20f * num;
				rigidbody.AddForce(vector * dt, ForceMode.VelocityChange);
				rigidbody.linearVelocity -= rigidbody.linearVelocity * 0.05f * num;
			}
		}
	}
}
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.Rendering;

public class RandEventSystem : MonoBehaviour
{
	public struct PlayerEventData
	{
		public Vector3 position;

		public HashSet<string> possibleEvents;

		public int baseValue;
	}

	private List<Vector3> points = new List<Vector3>();

	private static RandEventSystem m_instance;

	private List<KeyValuePair<RandomEvent, Vector3>> m_lastPossibleEvents = new List<KeyValuePair<RandomEvent, Vector3>>();

	private static List<PlayerEventData> s_playerEventDatas = new List<PlayerEventData>();

	private static bool s_randomEventNeedsRefresh = true;

	public float m_eventIntervalMin = 1f;

	public float m_eventChance = 25f;

	private float m_eventTimer;

	private float m_sendTimer;

	public List<RandomEvent> m_events = new List<RandomEvent>();

	private RandomEvent m_randomEvent;

	private float m_forcedEventUpdateTimer;

	private RandomEvent m_forcedEvent;

	private RandomEvent m_activeEvent;

	private float m_tempSaveEventTimer;

	private string m_tempSaveRandomEvent;

	private float m_tempSaveRandomEventTime;

	private Vector3 m_tempSaveRandomEventPos;

	public const string PossibleEventsKey = "possibleEvents";

	public static RandEventSystem instance => m_instance;

	private void Awake()
	{
		m_instance = this;
	}

	private void OnDestroy()
	{
		m_instance = null;
	}

	private void Start()
	{
		ZRoutedRpc.instance.Register<string, float, Vector3>("SetEvent", RPC_SetEvent);
	}

	private void FixedUpdate()
	{
		float fixedDeltaTime = Time.fixedDeltaTime;
		UpdateForcedEvents(fixedDeltaTime);
		UpdateRandomEvent(fixedDeltaTime);
		if (m_forcedEvent != null)
		{
			m_forcedEvent.Update(ZNet.instance.IsServer(), m_forcedEvent == m_activeEvent, playerInArea: true, fixedDeltaTime);
		}
		if (m_randomEvent != null && ZNet.instance.IsServer())
		{
			if (ZNet.instance.IsServer())
			{
				bool playerInArea = IsAnyPlayerInEventArea(m_randomEvent);
				if (m_randomEvent.Update(server: true, m_randomEvent == m_activeEvent, playerInArea, fixedDeltaTime))
				{
					SetRandomEvent(null, Vector3.zero);
				}
			}
			else
			{
				m_randomEvent.Update(ZNet.instance.IsServer(), m_randomEvent == m_activeEvent, playerInArea: true, fixedDeltaTime);
			}
		}
		if (m_forcedEvent != null)
		{
			SetActiveEvent(m_forcedEvent);
		}
		else if (m_randomEvent != null && (bool)Player.m_localPlayer)
		{
			if (IsInsideRandomEventArea(m_randomEvent, Player.m_localPlayer.transform.position))
			{
				SetActiveEvent(m_randomEvent);
			}
			else
			{
				SetActiveEvent(null);
			}
		}
		else
		{
			SetActiveEvent(null);
		}
	}

	private bool IsInsideRandomEventArea(RandomEvent re, Vector3 position)
	{
		if (position.y > 3000f)
		{
			return false;
		}
		return Utils.DistanceXZ(position, re.m_pos) < re.m_eventRange;
	}

	private void UpdateRandomEvent(float dt)
	{
		if (!ZNet.instance.IsServer())
		{
			return;
		}
		m_eventTimer += dt;
		if (Game.m_eventRate > 0f && m_eventTimer > m_eventIntervalMin * 60f * Game.m_eventRate)
		{
			m_eventTimer = 0f;
			if (Random.Range(0f, 100f) <= m_eventChance / Game.m_eventRate)
			{
				StartRandomEvent();
			}
		}
		if (s_randomEventNeedsRefresh)
		{
			RefreshPlayerEventData();
		}
		Player.GetAllPlayers();
		foreach (RandomEvent @event in m_events)
		{
			if (!@event.m_enabled || !(@event.m_standaloneInterval > 0f) || m_activeEvent == @event)
			{
				continue;
			}
			@event.m_time += dt;
			if (!(@event.m_time > @event.m_standaloneInterval * Game.m_eventRate))
			{
				continue;
			}
			if (HaveGlobalKeys(@event, s_playerEventDatas))
			{
				List<Vector3> validEventPoints = GetValidEventPoints(@event, s_playerEventDatas);
				if (validEventPoints.Count > 0 && Random.Range(0f, 100f) <= @event.m_standaloneChance / Game.m_eventRate)
				{
					SetRandomEvent(@event, validEventPoints[Random.Range(0, validEventPoints.Count)]);
				}
			}
			@event.m_time = 0f;
		}
		m_sendTimer += dt;
		if (m_sendTimer > 2f)
		{
			m_sendTimer = 0f;
			SendCurrentRandomEvent();
		}
	}

	private void UpdateForcedEvents(float dt)
	{
		m_forcedEventUpdateTimer += dt;
		if (m_forcedEventUpdateTimer > 2f)
		{
			m_forcedEventUpdateTimer = 0f;
			string forcedEvent = GetForcedEvent();
			SetForcedEvent(forcedEvent);
		}
	}

	private void SetForcedEvent(string name)
	{
		if (m_forcedEvent != null && name != null && m_forcedEvent.m_name == name)
		{
			return;
		}
		if (m_forcedEvent != null)
		{
			if (m_forcedEvent == m_activeEvent)
			{
				SetActiveEvent(null, end: true);
			}
			m_forcedEvent.OnStop();
			m_forcedEvent = null;
		}
		RandomEvent randomEvent = GetEvent(name);
		if (randomEvent != null)
		{
			m_forcedEvent = randomEvent.Clone();
			m_forcedEvent.OnStart();
		}
	}

	private string GetForcedEvent()
	{
		if (EnemyHud.instance != null)
		{
			Character activeBoss = EnemyHud.instance.GetActiveBoss();
			if (activeBoss != null && activeBoss.m_bossEvent.Length > 0)
			{
				return activeBoss.m_bossEvent;
			}
			string text = EventZone.GetEvent();
			if (text != null)
			{
				return text;
			}
		}
		return null;
	}

	public string GetBossEvent()
	{
		if (EnemyHud.instance != null)
		{
			Character activeBoss = EnemyHud.instance.GetActiveBoss();
			if ((object)activeBoss != null && activeBoss.m_bossEvent.Length > 0)
			{
				return activeBoss.m_bossEvent;
			}
		}
		return null;
	}

	private void SendCurrentRandomEvent()
	{
		if (m_randomEvent != null)
		{
			ZRoutedRpc.instance.InvokeRoutedRPC(ZRoutedRpc.Everybody, "SetEvent", m_randomEvent.m_name, m_randomEvent.m_time, m_randomEvent.m_pos);
		}
		else
		{
			ZRoutedRpc.instance.InvokeRoutedRPC(ZRoutedRpc.Everybody, "SetEvent", "", 0f, Vector3.zero);
		}
	}

	private void RPC_SetEvent(long sender, string eventName, float time, Vector3 pos)
	{
		if (!ZNet.instance.IsServer())
		{
			if (m_randomEvent == null || m_randomEvent.m_name != eventName)
			{
				SetRandomEventByName(eventName, pos);
			}
			if (m_randomEvent != null)
			{
				m_randomEvent.m_time = time;
				m_randomEvent.m_pos = pos;
			}
		}
	}

	public void ConsoleStartRandomEvent()
	{
		if (ZNet.instance.IsServer())
		{
			StartRandomEvent();
		}
		else
		{
			ZRoutedRpc.instance.InvokeRoutedRPC("startrandomevent");
		}
	}

	private void RPC_ConsoleStartRandomEvent(long sender)
	{
		ZNetPeer peer = ZNet.instance.GetPeer(sender);
		if (!ZNet.instance.IsAdmin(peer.m_socket.GetHostName()))
		{
			ZNet.instance.RemotePrint(peer.m_rpc, "You are not admin");
		}
		else
		{
			StartRandomEvent();
		}
	}

	public void ConsoleResetRandomEvent()
	{
		if (ZNet.instance.IsServer())
		{
			ResetRandomEvent();
		}
		else
		{
			ZRoutedRpc.instance.InvokeRoutedRPC("resetrandomevent");
		}
	}

	private void RPC_ConsoleResetRandomEvent(long sender)
	{
		ZNetPeer peer = ZNet.instance.GetPeer(sender);
		if (!ZNet.instance.IsAdmin(peer.m_socket.GetHostName()))
		{
			ZNet.instance.RemotePrint(peer.m_rpc, "You are not admin");
		}
		else
		{
			ResetRandomEvent();
		}
	}

	public void StartRandomEvent()
	{
		if (!ZNet.instance.IsServer())
		{
			return;
		}
		List<KeyValuePair<RandomEvent, Vector3>> possibleRandomEvents = GetPossibleRandomEvents();
		Terminal.Log($"Possible events: {possibleRandomEvents.Count}");
		if (possibleRandomEvents.Count == 0)
		{
			return;
		}
		foreach (KeyValuePair<RandomEvent, Vector3> item in possibleRandomEvents)
		{
			Terminal.Log("  " + item.Key.m_name);
		}
		KeyValuePair<RandomEvent, Vector3> keyValuePair = possibleRandomEvents[Random.Range(0, possibleRandomEvents.Count)];
		SetRandomEvent(keyValuePair.Key, keyValuePair.Value);
		Terminal.Log("Starting event: " + keyValuePair.Key.m_name);
	}

	private RandomEvent GetEvent(string name)
	{
		if (string.IsNullOrEmpty(name))
		{
			return null;
		}
		foreach (RandomEvent @event in m_events)
		{
			if (@event.m_name == name && @event.m_enabled)
			{
				return @event;
			}
		}
		return null;
	}

	public void SetRandomEventByName(string name, Vector3 pos)
	{
		RandomEvent ev = GetEvent(name);
		SetRandomEvent(ev, pos);
	}

	public void ResetRandomEvent()
	{
		SetRandomEvent(null, Vector3.zero);
	}

	public bool HaveEvent(string name)
	{
		return GetEvent(name) != null;
	}

	private void SetRandomEvent(RandomEvent ev, Vector3 pos)
	{
		if (m_randomEvent != null)
		{
			if (m_randomEvent == m_activeEvent)
			{
				SetActiveEvent(null, end: true);
			}
			m_randomEvent.OnStop();
			m_randomEvent = null;
		}
		if (ev != null)
		{
			m_randomEvent = ev.Clone();
			m_randomEvent.m_pos = pos;
			m_randomEvent.OnStart();
			ZLog.Log("Random event set:" + ev.m_name);
			if ((bool)Player.m_localPlayer)
			{
				Player.m_localPlayer.ShowTutorial("randomevent");
			}
		}
		if (ZNet.instance.IsServer())
		{
			SendCurrentRandomEvent();
		}
	}

	private bool IsAnyPlayerInEventArea(RandomEvent re)
	{
		foreach (ZDO allCharacterZDO in ZNet.instance.GetAllCharacterZDOS())
		{
			if (IsInsideRandomEventArea(re, allCharacterZDO.GetPosition()))
			{
				return true;
			}
		}
		return false;
	}

	private List<KeyValuePair<RandomEvent, Vector3>> GetPossibleRandomEvents()
	{
		m_lastPossibleEvents.Clear();
		RefreshPlayerEventData();
		foreach (RandomEvent @event in m_events)
		{
			if (@event.m_enabled && @event.m_random && HaveGlobalKeys(@event, s_playerEventDatas))
			{
				List<Vector3> validEventPoints = GetValidEventPoints(@event, s_playerEventDatas);
				if (validEventPoints.Count != 0)
				{
					Vector3 value = validEventPoints[Random.Range(0, validEventPoints.Count)];
					m_lastPossibleEvents.Add(new KeyValuePair<RandomEvent, Vector3>(@event, value));
				}
			}
		}
		return m_lastPossibleEvents;
	}

	private List<Vector3> GetValidEventPoints(RandomEvent ev, List<PlayerEventData> characters)
	{
		points.Clear();
		bool globalKey = ZoneSystem.instance.GetGlobalKey(GlobalKeys.PlayerEvents);
		foreach (PlayerEventData character in characters)
		{
			if (InValidBiome(ev, character.position) && CheckBase(ev, character) && !(character.position.y > 3000f) && (!globalKey || character.possibleEvents.Contains(ev.m_name)))
			{
				points.Add(character.position);
			}
		}
		return points;
	}

	private static void RefreshPlayerEventData()
	{
		s_randomEventNeedsRefresh = false;
		s_playerEventDatas.Clear();
		if (SystemInfo.graphicsDeviceType != GraphicsDeviceType.Null && RetrievePlayerEventData(ZNet.instance.m_serverSyncedPlayerData, ZNet.instance.GetReferencePosition(), out var eventData))
		{
			s_playerEventDatas.Add(eventData);
		}
		foreach (ZNetPeer peer in ZNet.instance.GetPeers())
		{
			if (peer.IsReady() && RetrievePlayerEventData(peer.m_serverSyncedPlayerData, peer.m_refPos, out var eventData2))
			{
				s_playerEventDatas.Add(eventData2);
			}
		}
	}

	public static void SetRandomEventsNeedsRefresh()
	{
		s_randomEventNeedsRefresh = true;
	}

	private static bool RetrievePlayerEventData(Dictionary<string, string> playerData, Vector3 position, out PlayerEventData eventData)
	{
		eventData = default(PlayerEventData);
		if (!playerData.TryGetValue("possibleEvents", out var value))
		{
			return false;
		}
		if (!playerData.TryGetValue("baseValue", out var value2) || !int.TryParse(value2, out eventData.baseValue))
		{
			return false;
		}
		eventData.position = position;
		eventData.possibleEvents = new HashSet<string>();
		string[] array = value.Split(',');
		for (int i = 0; i < array.Length; i++)
		{
			eventData.possibleEvents.Add(array[i]);
		}
		return true;
	}

	private bool InValidBiome(RandomEvent ev, Vector3 point)
	{
		if (ev.m_biome == Heightmap.Biome.None)
		{
			return true;
		}
		if ((WorldGenerator.instance.GetBiome(point) & ev.m_biome) != Heightmap.Biome.None)
		{
			return true;
		}
		return false;
	}

	private bool CheckBase(RandomEvent ev, PlayerEventData player)
	{
		if (!ev.m_nearBaseOnly)
		{
			return true;
		}
		if (player.baseValue >= 3)
		{
			return true;
		}
		return false;
	}

	private bool HaveGlobalKeys(RandomEvent ev, List<PlayerEventData> players)
	{
		if (ZoneSystem.instance.GetGlobalKey(GlobalKeys.PlayerEvents) && (ev.m_altRequiredKnownItems.Count > 0 || ev.m_altRequiredNotKnownItems.Count > 0 || ev.m_altNotRequiredPlayerKeys.Count > 0 || ev.m_altRequiredPlayerKeysAny.Count > 0 || ev.m_altRequiredPlayerKeysAll.Count > 0))
		{
			foreach (PlayerEventData player in players)
			{
				if (player.possibleEvents.Contains(ev.m_name))
				{
					return true;
				}
			}
			return false;
		}
		foreach (string requiredGlobalKey in ev.m_requiredGlobalKeys)
		{
			if (!ZoneSystem.instance.GetGlobalKey(requiredGlobalKey))
			{
				return false;
			}
		}
		foreach (string notRequiredGlobalKey in ev.m_notRequiredGlobalKeys)
		{
			if (ZoneSystem.instance.GetGlobalKey(notRequiredGlobalKey))
			{
				return false;
			}
		}
		return true;
	}

	public bool PlayerIsReadyForEvent(Player player, RandomEvent ev)
	{
		foreach (ItemDrop altRequiredNotKnownItem in ev.m_altRequiredNotKnownItems)
		{
			if (player.IsMaterialKnown(altRequiredNotKnownItem.m_itemData.m_shared.m_name))
			{
				return false;
			}
		}
		foreach (string altNotRequiredPlayerKey in ev.m_altNotRequiredPlayerKeys)
		{
			if (player.HaveUniqueKey(altNotRequiredPlayerKey))
			{
				return false;
			}
		}
		foreach (ItemDrop altRequiredKnownItem in ev.m_altRequiredKnownItems)
		{
			if (player.IsMaterialKnown(altRequiredKnownItem.m_itemData.m_shared.m_name))
			{
				return true;
			}
		}
		foreach (string item in ev.m_altRequiredPlayerKeysAny)
		{
			if (player.HaveUniqueKey(item))
			{
				return true;
			}
		}
		foreach (string item2 in ev.m_altRequiredPlayerKeysAll)
		{
			if (!player.HaveUniqueKey(item2))
			{
				return false;
			}
		}
		if (ev.m_altRequiredKnownItems.Count <= 0 && ev.m_altRequiredPlayerKeysAny.Count <= 0)
		{
			return true;
		}
		return false;
	}

	public List<SpawnSystem.SpawnData> GetCurrentSpawners()
	{
		if (m_activeEvent != null && m_activeEvent.m_time > m_activeEvent.m_spawnerDelay)
		{
			return m_activeEvent.m_spawn;
		}
		return null;
	}

	public string GetEnvOverride()
	{
		if (m_activeEvent != null && !string.IsNullOrEmpty(m_activeEvent.m_forceEnvironment) && m_activeEvent.InEventBiome())
		{
			return m_activeEvent.m_forceEnvironment;
		}
		return null;
	}

	public string GetMusicOverride()
	{
		if (m_activeEvent != null && !string.IsNullOrEmpty(m_activeEvent.m_forceMusic))
		{
			return m_activeEvent.m_forceMusic;
		}
		return null;
	}

	private void SetActiveEvent(RandomEvent ev, bool end = false)
	{
		if (ev != null && m_activeEvent != null && ev.m_name == m_activeEvent.m_name)
		{
			return;
		}
		if (m_activeEvent != null)
		{
			m_activeEvent.OnDeactivate(end);
			m_activeEvent = null;
		}
		if (ev != null)
		{
			m_activeEvent = ev;
			if (m_activeEvent != null)
			{
				m_activeEvent.OnActivate();
			}
		}
	}

	public static bool InEvent()
	{
		if (m_instance == null)
		{
			return false;
		}
		return m_instance.m_activeEvent != null;
	}

	public static bool HaveActiveEvent()
	{
		if (m_instance == null)
		{
			return false;
		}
		if (m_instance.m_activeEvent != null)
		{
			return true;
		}
		if (m_instance.m_randomEvent == null)
		{
			return m_instance.m_activeEvent != null;
		}
		return true;
	}

	public RandomEvent GetCurrentRandomEvent()
	{
		return m_randomEvent;
	}

	public RandomEvent GetActiveEvent()
	{
		return m_activeEvent;
	}

	public void PrepareSave()
	{
		m_tempSaveEventTimer = m_eventTimer;
		if (m_randomEvent != null)
		{
			m_tempSaveRandomEvent = m_randomEvent.m_name;
			m_tempSaveRandomEventTime = m_randomEvent.m_time;
			m_tempSaveRandomEventPos = m_randomEvent.m_pos;
		}
		else
		{
			m_tempSaveRandomEvent = "";
			m_tempSaveRandomEventTime = 0f;
			m_tempSaveRandomEventPos = Vector3.zero;
		}
	}

	public void SaveAsync(BinaryWriter writer)
	{
		writer.Write(m_tempSaveEventTimer);
		writer.Write(m_tempSaveRandomEvent);
		writer.Write(m_tempSaveRandomEventTime);
		writer.Write(m_tempSaveRandomEventPos.x);
		writer.Write(m_tempSaveRandomEventPos.y);
		writer.Write(m_tempSaveRandomEventPos.z);
	}

	public void Load(BinaryReader reader, int version)
	{
		m_eventTimer = reader.ReadSingle();
		if (version < 25)
		{
			return;
		}
		string value = reader.ReadString();
		float time = reader.ReadSingle();
		Vector3 pos = default(Vector3);
		pos.x = reader.ReadSingle();
		pos.y = reader.ReadSingle();
		pos.z = reader.ReadSingle();
		if (!string.IsNullOrEmpty(value))
		{
			SetRandomEventByName(value, pos);
			if (m_randomEvent != null)
			{
				m_randomEvent.m_time = time;
				m_randomEvent.m_pos = pos;
			}
		}
	}
}
using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

public class RandomAnimation : MonoBehaviour
{
	[Serializable]
	public class RandomValue
	{
		public string m_name;

		public int m_values;

		public float m_interval;

		public bool m_floatValue;

		public float m_floatTransition = 1f;

		[NonSerialized]
		public float m_timer;

		[NonSerialized]
		public int m_value;

		[NonSerialized]
		public List<int> m_hashValues = new List<int>();
	}

	public List<RandomValue> m_values = new List<RandomValue>();

	private Animator m_anim;

	private ZNetView m_nview;

	private readonly StringBuilder m_sb = new StringBuilder();

	private void Start()
	{
		m_anim = GetComponentInChildren<Animator>();
		m_nview = GetComponent<ZNetView>();
	}

	private void FixedUpdate()
	{
		if (m_nview != null && !m_nview.IsValid())
		{
			return;
		}
		float fixedDeltaTime = Time.fixedDeltaTime;
		foreach (RandomValue value in m_values)
		{
			m_sb.Clear();
			m_sb.Append("RA_");
			m_sb.Append(value.m_name);
			if (m_nview == null || m_nview.IsOwner())
			{
				value.m_timer += fixedDeltaTime;
				if (value.m_timer > value.m_interval)
				{
					value.m_timer = 0f;
					value.m_value = UnityEngine.Random.Range(0, value.m_values);
					if ((bool)m_nview)
					{
						m_nview.GetZDO().Set(m_sb.ToString(), value.m_value);
					}
					if (!value.m_floatValue)
					{
						m_anim.SetInteger(value.m_name, value.m_value);
					}
				}
			}
			if ((bool)m_nview && !m_nview.IsOwner())
			{
				int num = m_nview.GetZDO().GetInt(m_sb.ToString());
				if (num != value.m_value)
				{
					value.m_value = num;
					if (!value.m_floatValue)
					{
						m_anim.SetInteger(value.m_name, value.m_value);
					}
				}
			}
			if (!value.m_floatValue)
			{
				continue;
			}
			if (value.m_hashValues.Count != value.m_values)
			{
				value.m_hashValues.Resize(value.m_values);
				for (int i = 0; i < value.m_values; i++)
				{
					m_sb.Clear();
					m_sb.Append(value.m_name);
					m_sb.Append(i.ToString());
					value.m_hashValues[i] = ZSyncAnimation.GetHash(m_sb.ToString());
				}
			}
			for (int j = 0; j < value.m_values; j++)
			{
				float current2 = m_anim.GetFloat(value.m_hashValues[j]);
				current2 = ((j != value.m_value) ? Mathf.MoveTowards(current2, 0f, fixedDeltaTime / value.m_floatTransition) : Mathf.MoveTowards(current2, 1f, fixedDeltaTime / value.m_floatTransition));
				m_anim.SetFloat(value.m_hashValues[j], current2);
			}
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public class RandomEvent
{
	public string m_name = "";

	public bool m_enabled = true;

	public bool m_devDisabled;

	public bool m_random = true;

	public float m_duration = 60f;

	public bool m_nearBaseOnly = true;

	public bool m_pauseIfNoPlayerInArea = true;

	public float m_eventRange = 96f;

	public float m_standaloneInterval;

	public float m_standaloneChance = 100f;

	public float m_spawnerDelay;

	public AnimationCurve m_cameraShakeCurve = new AnimationCurve
	{
		postWrapMode = WrapMode.Once,
		preWrapMode = WrapMode.Once
	};

	[BitMask(typeof(Heightmap.Biome))]
	public Heightmap.Biome m_biome;

	[Header("( Keys required to be TRUE )")]
	public List<string> m_requiredGlobalKeys = new List<string>();

	[Tooltip("If PlayerEvents is set, instead only spawn this event at players know who at least one of each item on each list (or player key below).")]
	public List<ItemDrop> m_altRequiredKnownItems = new List<ItemDrop>();

	[Tooltip("If PlayerEvents is set, instead only spawn this event at players know who have ANY of these keys set (or any known items above).")]
	public List<string> m_altRequiredPlayerKeysAny = new List<string>();

	[Tooltip("If PlayerEvents is set, instead only spawn this event at players know who have ALL of these keys set (or any known items above).")]
	public List<string> m_altRequiredPlayerKeysAll = new List<string>();

	[Header("( Keys required to be FALSE )")]
	public List<string> m_notRequiredGlobalKeys = new List<string>();

	[Tooltip("If PlayerEvents is set, instead require ALL of the items to be unknown on this list for a player to be able to get that event. (And below not known player keys)")]
	public List<ItemDrop> m_altRequiredNotKnownItems = new List<ItemDrop>();

	[Tooltip("If PlayerEvents is set, instead require ALL of the playerkeys to be unknown on this list for a player to be able to get that event. (And above not known items)")]
	public List<string> m_altNotRequiredPlayerKeys = new List<string>();

	[Space(20f)]
	public string m_startMessage = "";

	public string m_endMessage = "";

	public string m_forceMusic = "";

	public string m_forceEnvironment = "";

	public List<SpawnSystem.SpawnData> m_spawn = new List<SpawnSystem.SpawnData>();

	private bool m_firstActivation = true;

	private bool m_active;

	[NonSerialized]
	public float m_time;

	[NonSerialized]
	public Vector3 m_pos = Vector3.zero;

	public RandomEvent Clone()
	{
		RandomEvent randomEvent = MemberwiseClone() as RandomEvent;
		randomEvent.m_spawn = new List<SpawnSystem.SpawnData>();
		foreach (SpawnSystem.SpawnData item in m_spawn)
		{
			randomEvent.m_spawn.Add(item.Clone());
		}
		return randomEvent;
	}

	public bool Update(bool server, bool active, bool playerInArea, float dt)
	{
		if (m_pauseIfNoPlayerInArea && !playerInArea)
		{
			return false;
		}
		m_time += dt;
		if (m_duration > 0f && m_time > m_duration)
		{
			return true;
		}
		if (m_cameraShakeCurve.length > 0)
		{
			GameCamera.instance.AddShake(m_pos, m_eventRange, m_cameraShakeCurve.Evaluate(m_time), continous: false);
		}
		return false;
	}

	public void OnActivate()
	{
		m_active = true;
		if (m_firstActivation)
		{
			m_firstActivation = false;
			if (m_startMessage != "")
			{
				MessageHud.instance.ShowMessage(MessageHud.MessageType.Center, m_startMessage);
			}
		}
	}

	public void OnDeactivate(bool end)
	{
		m_active = false;
		if (end && m_endMessage != "")
		{
			MessageHud.instance.ShowMessage(MessageHud.MessageType.Center, m_endMessage);
		}
	}

	public string GetHudText()
	{
		return m_startMessage;
	}

	public void OnStart()
	{
		m_time = 0f;
	}

	public void OnStop()
	{
	}

	public bool InEventBiome()
	{
		return (EnvMan.instance.GetCurrentBiome() & m_biome) != 0;
	}

	public float GetTime()
	{
		return m_time;
	}

	public override string ToString()
	{
		return string.Format("{0} {1}, enabled: {2}, random: {3}", "RandomEvent", m_name, m_enabled, m_random);
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class RandomFlyingBird : MonoBehaviour, IMonoUpdater
{
	public float m_flyRange = 20f;

	public float m_minAlt = 5f;

	public float m_maxAlt = 20f;

	public float m_speed = 10f;

	public float m_turnRate = 10f;

	public float m_wpDuration = 4f;

	public float m_flapDuration = 2f;

	public float m_sailDuration = 4f;

	public float m_landChance = 0.5f;

	public float m_landDuration = 2f;

	public float m_avoidDangerDistance = 4f;

	public bool m_noRandomFlightAtNight = true;

	public float m_randomNoiseIntervalMin = 3f;

	public float m_randomNoiseIntervalMax = 6f;

	public bool m_noNoiseAtNight = true;

	public EffectList m_randomNoise = new EffectList();

	public int m_randomIdles;

	public float m_randomIdleTimeMin = 1f;

	public float m_randomIdleTimeMax = 4f;

	public bool m_singleModel;

	public GameObject m_flyingModel;

	public GameObject m_landedModel;

	private Vector3 m_spawnPoint;

	private Vector3 m_waypoint;

	private bool m_groundwp;

	private float m_flyTimer;

	private float m_modeTimer;

	private float m_idleTimer;

	private float m_idleTargetTime = 1f;

	private float m_randomNoiseTimer;

	private ZSyncAnimation m_anim;

	private bool m_flapping = true;

	private float m_landedTimer;

	private static readonly int s_flapping = ZSyncAnimation.GetHash("flapping");

	private static readonly int s_flying = ZSyncAnimation.GetHash("flying");

	private static readonly int s_idle = ZSyncAnimation.GetHash("idle");

	private ZNetView m_nview;

	protected LODGroup m_lodGroup;

	private Vector3 m_originalLocalRef;

	private bool m_lodVisible = true;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_anim = GetComponentInChildren<ZSyncAnimation>();
		m_lodGroup = GetComponent<LODGroup>();
		if (!m_singleModel)
		{
			m_landedModel.SetActive(value: true);
			m_flyingModel.SetActive(value: true);
		}
		else
		{
			m_flyingModel.SetActive(value: true);
		}
		m_idleTargetTime = UnityEngine.Random.Range(m_randomIdleTimeMin, m_randomIdleTimeMax);
		m_spawnPoint = m_nview.GetZDO().GetVec3(ZDOVars.s_spawnPoint, base.transform.position);
		if (m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_spawnPoint, m_spawnPoint);
		}
		m_randomNoiseTimer = UnityEngine.Random.Range(m_randomNoiseIntervalMin, m_randomNoiseIntervalMax);
		if (m_nview.IsOwner())
		{
			RandomizeWaypoint(ground: false);
		}
		if ((bool)m_lodGroup)
		{
			m_originalLocalRef = m_lodGroup.localReferencePoint;
		}
	}

	private void OnEnable()
	{
		if (m_nview != null)
		{
			Instances.Add(this);
		}
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public void CustomFixedUpdate(float dt)
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		bool flag = EnvMan.IsDaylight();
		m_randomNoiseTimer -= dt;
		if (m_randomNoiseTimer <= 0f)
		{
			if (flag || !m_noNoiseAtNight)
			{
				m_randomNoise.Create(base.transform.position, Quaternion.identity, base.transform);
			}
			m_randomNoiseTimer = UnityEngine.Random.Range(m_randomNoiseIntervalMin, m_randomNoiseIntervalMax);
		}
		bool flag2 = m_nview.GetZDO().GetBool(ZDOVars.s_landed);
		if (!m_singleModel)
		{
			m_landedModel.SetActive(flag2);
			m_flyingModel.SetActive(!flag2);
		}
		SetVisible(m_nview.HasOwner());
		if (!m_nview.IsOwner())
		{
			return;
		}
		m_flyTimer += dt;
		m_modeTimer += dt;
		if (m_singleModel)
		{
			m_anim.SetBool(s_flying, !flag2);
		}
		if (flag2)
		{
			Vector3 forward = base.transform.forward;
			forward.y = 0f;
			forward.Normalize();
			base.transform.rotation = Quaternion.LookRotation(forward, Vector3.up);
			if (m_randomIdles > 0)
			{
				m_idleTimer += Time.fixedDeltaTime;
				if (m_idleTimer > m_idleTargetTime)
				{
					m_idleTargetTime = UnityEngine.Random.Range(m_randomIdleTimeMin, m_randomIdleTimeMax);
					m_idleTimer = 0f;
					m_anim.SetFloat(s_idle, UnityEngine.Random.Range(0, m_randomIdles));
				}
			}
			m_landedTimer += dt;
			if (((flag || !m_noRandomFlightAtNight) && m_landedTimer > m_landDuration) || DangerNearby(base.transform.position))
			{
				m_nview.GetZDO().Set(ZDOVars.s_landed, value: false);
				RandomizeWaypoint(ground: false);
			}
			return;
		}
		if (m_flapping)
		{
			if (m_modeTimer > m_flapDuration)
			{
				m_modeTimer = 0f;
				m_flapping = false;
			}
		}
		else if (m_modeTimer > m_sailDuration)
		{
			m_flapping = true;
			m_modeTimer = 0f;
		}
		m_anim.SetBool(s_flapping, m_flapping);
		Vector3 vector = Vector3.Normalize(m_waypoint - base.transform.position);
		float num = (m_groundwp ? (m_turnRate * 4f) : m_turnRate);
		Vector3 vector2 = Vector3.RotateTowards(base.transform.forward, vector, num * (MathF.PI / 180f) * dt, 1f);
		float num2 = Vector3.SignedAngle(base.transform.forward, vector, Vector3.up);
		Vector3 vector3 = Vector3.Cross(vector2, Vector3.up);
		Vector3 up = Vector3.up;
		if (num2 > 0f)
		{
			up += -vector3 * 1.5f * Utils.LerpStep(0f, 45f, num2);
		}
		else
		{
			up += vector3 * 1.5f * Utils.LerpStep(0f, 45f, 0f - num2);
		}
		float num3 = m_speed;
		bool flag3 = false;
		if (m_groundwp)
		{
			float num4 = Vector3.Distance(base.transform.position, m_waypoint);
			if (num4 < 5f)
			{
				num3 *= Mathf.Clamp(num4 / 5f, 0.2f, 1f);
				vector2.y = 0f;
				vector2.Normalize();
				up = Vector3.up;
				flag3 = true;
			}
			if (num4 < 0.2f)
			{
				base.transform.position = m_waypoint;
				m_nview.GetZDO().Set(ZDOVars.s_landed, value: true);
				m_landedTimer = 0f;
				m_flapping = true;
				m_modeTimer = 0f;
			}
		}
		else if (m_flyTimer >= m_wpDuration)
		{
			bool ground = UnityEngine.Random.value < m_landChance;
			RandomizeWaypoint(ground);
		}
		Quaternion to = Quaternion.LookRotation(vector2, up.normalized);
		base.transform.rotation = Quaternion.RotateTowards(base.transform.rotation, to, 200f * dt);
		if (flag3)
		{
			base.transform.position += vector * num3 * dt;
		}
		else
		{
			base.transform.position += base.transform.forward * num3 * dt;
		}
	}

	private void RandomizeWaypoint(bool ground)
	{
		m_flyTimer = 0f;
		if (ground && FindLandingPoint(out var waypoint))
		{
			m_waypoint = waypoint;
			m_groundwp = true;
			return;
		}
		Vector2 vector = UnityEngine.Random.insideUnitCircle * m_flyRange;
		m_waypoint = m_spawnPoint + new Vector3(vector.x, 0f, vector.y);
		if (ZoneSystem.instance.GetSolidHeight(m_waypoint, out var height))
		{
			float num = 32f;
			if (height < num)
			{
				height = num;
			}
			m_waypoint.y = height + UnityEngine.Random.Range(m_minAlt, m_maxAlt);
		}
		m_groundwp = false;
	}

	private bool FindLandingPoint(out Vector3 waypoint)
	{
		waypoint = new Vector3(0f, -999f, 0f);
		bool result = false;
		for (int i = 0; i < 10; i++)
		{
			Vector2 vector = UnityEngine.Random.insideUnitCircle * m_flyRange;
			Vector3 vector2 = m_spawnPoint + new Vector3(vector.x, 0f, vector.y);
			if (ZoneSystem.instance.GetSolidHeight(vector2, out var height) && height > 30f && height > waypoint.y)
			{
				vector2.y = height;
				if (!DangerNearby(vector2))
				{
					waypoint = vector2;
					result = true;
				}
			}
		}
		return result;
	}

	private bool DangerNearby(Vector3 p)
	{
		return Player.IsPlayerInRange(p, m_avoidDangerDistance);
	}

	private void SetVisible(bool visible)
	{
		if (!(m_lodGroup == null) && m_lodVisible != visible)
		{
			m_lodVisible = visible;
			if (m_lodVisible)
			{
				m_lodGroup.localReferencePoint = m_originalLocalRef;
			}
			else
			{
				m_lodGroup.localReferencePoint = new Vector3(999999f, 999999f, 999999f);
			}
		}
	}
}
using UnityEngine;

public class RandomIdle : StateMachineBehaviour
{
	public int m_animations = 4;

	public int m_animationsWhenTamed;

	public string m_valueName = "";

	public int m_alertedIdle = -1;

	private float m_last;

	private bool m_haveSetup;

	private BaseAI m_baseAI;

	private Character m_character;

	public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
	{
		int randomIdle = GetRandomIdle(animator);
		animator.SetFloat(m_valueName, randomIdle);
		m_last = stateInfo.normalizedTime % 1f;
	}

	public override void OnStateUpdate(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
	{
		float num = stateInfo.normalizedTime % 1f;
		if (num < m_last)
		{
			int randomIdle = GetRandomIdle(animator);
			animator.SetFloat(m_valueName, randomIdle);
		}
		m_last = num;
	}

	private int GetRandomIdle(Animator animator)
	{
		if (!m_haveSetup)
		{
			m_haveSetup = true;
			m_baseAI = animator.GetComponentInParent<BaseAI>();
			m_character = animator.GetComponentInParent<Character>();
		}
		if ((bool)m_baseAI && m_alertedIdle >= 0 && m_baseAI.IsAlerted())
		{
			return m_alertedIdle;
		}
		return Random.Range(0, (m_animationsWhenTamed > 0 && m_character != null && m_character.IsTamed()) ? m_animationsWhenTamed : m_animations);
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class RandomMaterialValues : MonoBehaviour
{
	[Serializable]
	public abstract class MaterialVariationProperty<T>
	{
		public List<string> m_propertyNames;

		protected System.Random m_random;

		public abstract T GetValue(int seed);
	}

	[Serializable]
	public class VectorVariationProperty : MaterialVariationProperty<Vector4>
	{
		public Vector4 m_minimum;

		public Vector4 m_maximum;

		public override Vector4 GetValue(int seed)
		{
			m_random = new System.Random(seed);
			return new Vector4
			{
				x = Mathf.Lerp(m_minimum.x, m_maximum.x, (float)m_random.NextDouble()),
				y = Mathf.Lerp(m_minimum.y, m_maximum.y, (float)m_random.NextDouble()),
				z = Mathf.Lerp(m_minimum.z, m_maximum.z, (float)m_random.NextDouble()),
				w = Mathf.Lerp(m_minimum.w, m_maximum.w, (float)m_random.NextDouble())
			};
		}
	}

	public List<VectorVariationProperty> m_vectorProperties = new List<VectorVariationProperty>();

	private ZNetView m_nview;

	private int m_randomSeed = -1;

	private string m_matName;

	private bool m_isSet;

	private Piece m_piece;

	private int m_checks;

	private static readonly string s_randSeedString = "RandMatSeed";

	private void Start()
	{
		m_nview = GetComponentInParent<ZNetView>();
		m_piece = GetComponentInParent<Piece>();
		if (!m_nview)
		{
			ZLog.LogError("Missing nview on '" + base.transform.gameObject.name + "'");
		}
		InvokeRepeating("CheckMaterial", 0f, 0.2f);
	}

	private void CheckMaterial()
	{
		if (((!m_isSet && m_randomSeed < 0) || (m_isSet && (!m_piece || !Player.IsPlacementGhost(m_piece.gameObject)))) && (bool)m_nview && m_nview.GetZDO() != null)
		{
			m_randomSeed = m_nview.GetZDO().GetInt(s_randSeedString, -1);
			if (m_randomSeed < 0 && m_nview.IsOwner())
			{
				m_nview.GetZDO().Set(s_randSeedString, UnityEngine.Random.Range(0, 12345));
			}
			if (m_randomSeed >= 0)
			{
				for (int i = 0; i < m_vectorProperties.Count; i++)
				{
					VectorVariationProperty vectorVariationProperty = m_vectorProperties[i];
					foreach (string propertyName in vectorVariationProperty.m_propertyNames)
					{
						MaterialMan.instance.SetValue(base.gameObject, Shader.PropertyToID(propertyName), vectorVariationProperty.GetValue(m_randomSeed + i));
					}
				}
				m_isSet = true;
			}
		}
		m_checks++;
		if (m_checks >= 5)
		{
			CancelInvoke("CheckMaterial");
		}
	}
}
using UnityEngine;

public class RandomMovement : MonoBehaviour
{
	public float m_frequency = 10f;

	public float m_movement = 0.1f;

	private Vector3 m_basePosition = Vector3.zero;

	private void Start()
	{
		m_basePosition = base.transform.localPosition;
	}

	private void Update()
	{
		float num = Time.time * m_frequency;
		Vector3 vector = new Vector3(Mathf.Sin(num) * Mathf.Sin(num * 0.56436f), Mathf.Sin(num * 0.56436f) * Mathf.Sin(num * 0.688742f), Mathf.Cos(num * 0.758348f) * Mathf.Cos(num * 0.4563696f)) * m_movement;
		base.transform.localPosition = m_basePosition + vector;
	}
}
using UnityEngine;

public class RandomPieceRotation : MonoBehaviour
{
	public bool m_rotateX;

	public bool m_rotateY;

	public bool m_rotateZ;

	public int m_stepsX = 4;

	public int m_stepsY = 4;

	public int m_stepsZ = 4;

	private void Awake()
	{
		Vector3 position = base.transform.position;
		int seed = (int)position.x * (int)(position.y * 10f) * (int)(position.z * 100f);
		Random.State state = Random.state;
		Random.InitState(seed);
		float x = (m_rotateX ? ((float)Random.Range(0, m_stepsX) * 360f / (float)m_stepsX) : 0f);
		float y = (m_rotateY ? ((float)Random.Range(0, m_stepsY) * 360f / (float)m_stepsY) : 0f);
		float z = (m_rotateZ ? ((float)Random.Range(0, m_stepsZ) * 360f / (float)m_stepsZ) : 0f);
		base.transform.localRotation = Quaternion.Euler(x, y, z);
		Random.state = state;
	}
}
using System.Collections.Generic;
using UnityEngine;

public class RandomSpawn : MonoBehaviour
{
	public GameObject m_OffObject;

	[Range(0f, 100f)]
	public float m_chanceToSpawn = 50f;

	public Room.Theme m_dungeonRequireTheme;

	public Heightmap.Biome m_requireBiome;

	public bool m_notInLava;

	[Header("Elevation span (water is 30)")]
	public int m_minElevation = -10000;

	public int m_maxElevation = 10000;

	private List<ZNetView> m_childNetViews;

	private ZNetView m_nview;

	public void Randomize(Vector3 pos, Location loc = null, DungeonGenerator dg = null)
	{
		bool spawned = Random.Range(0f, 100f) <= m_chanceToSpawn;
		if (dg != null && m_dungeonRequireTheme != Room.Theme.None && !dg.m_themes.HasFlag(m_dungeonRequireTheme))
		{
			spawned = false;
		}
		if (loc != null && m_requireBiome != Heightmap.Biome.None)
		{
			if (loc.m_biome == Heightmap.Biome.None)
			{
				loc.m_biome = WorldGenerator.instance.GetBiome(pos);
			}
			if (!m_requireBiome.HasFlag(loc.m_biome))
			{
				spawned = false;
			}
		}
		if (m_notInLava && (bool)ZoneSystem.instance && ZoneSystem.IsLavaPreHeightmap(pos))
		{
			spawned = false;
		}
		if (pos.y < (float)m_minElevation || pos.y > (float)m_maxElevation)
		{
			spawned = false;
		}
		SetSpawned(spawned);
	}

	public void Reset()
	{
		SetSpawned(doSpawn: true);
	}

	private void SetSpawned(bool doSpawn)
	{
		if (!doSpawn)
		{
			base.gameObject.SetActive(value: false);
			foreach (ZNetView childNetView in m_childNetViews)
			{
				childNetView.gameObject.SetActive(value: false);
			}
		}
		else if (m_nview == null)
		{
			base.gameObject.SetActive(value: true);
		}
		if (m_OffObject != null)
		{
			m_OffObject.SetActive(!doSpawn);
		}
	}

	public void Prepare()
	{
		m_nview = GetComponent<ZNetView>();
		m_childNetViews = new List<ZNetView>();
		ZNetView[] componentsInChildren = base.gameObject.GetComponentsInChildren<ZNetView>(includeInactive: true);
		foreach (ZNetView zNetView in componentsInChildren)
		{
			if (Utils.IsEnabledInheirarcy(zNetView.gameObject, base.gameObject))
			{
				m_childNetViews.Add(zNetView);
			}
		}
	}
}
using UnityEngine;

public class RandomSpeak : MonoBehaviour
{
	public float m_interval = 5f;

	public float m_chance = 0.5f;

	public float m_triggerDistance = 5f;

	public float m_cullDistance = 10f;

	public float m_ttl = 10f;

	public Vector3 m_offset = new Vector3(0f, 0f, 0f);

	public EffectList m_speakEffects = new EffectList();

	public bool m_useLargeDialog;

	public bool m_onlyOnce;

	public bool m_onlyOnItemStand;

	public float m_minTOD;

	public float m_maxTOD = 1f;

	public bool m_invertTod;

	public bool m_indexFromDay;

	public string m_topic = "";

	public string[] m_texts = new string[0];

	private void Start()
	{
		InvokeRepeating("Speak", Random.Range(0f, m_interval), m_interval);
	}

	private void Speak()
	{
		if (Random.value > m_chance || m_texts.Length == 0 || Player.m_localPlayer == null || Vector3.Distance(base.transform.position, Player.m_localPlayer.transform.position) > m_triggerDistance || (m_onlyOnItemStand && !base.gameObject.GetComponentInParent<ItemStand>()))
		{
			return;
		}
		float dayFraction = EnvMan.instance.GetDayFraction();
		if ((m_invertTod || (!(dayFraction < m_minTOD) && !(dayFraction > m_maxTOD))) && (!m_invertTod || !(dayFraction > m_minTOD) || !(dayFraction < m_maxTOD)))
		{
			m_speakEffects.Create(base.transform.position, base.transform.rotation);
			int num = (m_indexFromDay ? (EnvMan.instance.GetDay() % m_texts.Length) : Random.Range(0, m_texts.Length));
			string text = m_texts[num];
			Chat.instance.SetNpcText(base.gameObject, m_offset, m_cullDistance, m_ttl, m_topic, text, m_useLargeDialog);
			if (m_onlyOnce)
			{
				CancelInvoke("Speak");
			}
		}
	}
}
public struct RangeIntInclusive
{
	public readonly int m_minValue;

	public readonly int m_maxValue;

	public static RangeIntInclusive Positive => new RangeIntInclusive(0, int.MaxValue);

	public static RangeIntInclusive Full => new RangeIntInclusive(int.MinValue, int.MaxValue);

	public RangeIntInclusive(int maxValue)
	{
		m_minValue = 0;
		m_maxValue = maxValue;
	}

	public RangeIntInclusive(int minValue, int maxValue)
	{
		m_minValue = minValue;
		m_maxValue = maxValue;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Raven : MonoBehaviour, Hoverable, Interactable, IDestructible
{
	[Serializable]
	public class RavenText
	{
		public bool m_alwaysSpawn = true;

		public bool m_munin;

		public int m_priority;

		public string m_key = "";

		public string m_topic = "";

		public string m_label = "";

		[TextArea]
		public string m_text = "";

		[NonSerialized]
		public bool m_static;

		[NonSerialized]
		public GuidePoint m_guidePoint;
	}

	public GameObject m_visual;

	public GameObject m_exclamation;

	public string m_name = "Name";

	public bool m_isMunin;

	public bool m_autoTalk = true;

	public float m_idleEffectIntervalMin = 10f;

	public float m_idleEffectIntervalMax = 20f;

	public float m_spawnDistance = 15f;

	public float m_despawnDistance = 20f;

	public float m_autoTalkDistance = 3f;

	public float m_enemyCheckDistance = 10f;

	public float m_rotateSpeed = 10f;

	public float m_minRotationAngle = 15f;

	public float m_dialogVisibleTime = 10f;

	public float m_longDialogVisibleTime = 10f;

	public float m_dontFlyDistance = 3f;

	public float m_textOffset = 1.5f;

	public float m_textCullDistance = 20f;

	public float m_randomTextInterval = 30f;

	public float m_randomTextIntervalImportant = 10f;

	public List<string> m_randomTextsImportant = new List<string>();

	public List<string> m_randomTexts = new List<string>();

	public EffectList m_idleEffect = new EffectList();

	public EffectList m_despawnEffect = new EffectList();

	private RavenText m_currentText;

	private GameObject m_groundObject;

	private Animator m_animator;

	private Collider m_collider;

	private bool m_hasTalked;

	private float m_randomTextTimer = 9999f;

	private float m_timeSinceTeleport = 9999f;

	private static List<RavenText> m_tempTexts = new List<RavenText>();

	private static List<RavenText> m_staticTexts = new List<RavenText>();

	private static Raven m_instance = null;

	public static bool m_tutorialsEnabled = true;

	public static bool IsInstantiated()
	{
		return m_instance != null;
	}

	private void Awake()
	{
		base.transform.position = new Vector3(0f, 100000f, 0f);
		m_instance = this;
		m_animator = m_visual.GetComponentInChildren<Animator>();
		m_collider = GetComponent<Collider>();
		InvokeRepeating("IdleEffect", UnityEngine.Random.Range(m_idleEffectIntervalMin, m_idleEffectIntervalMax), UnityEngine.Random.Range(m_idleEffectIntervalMin, m_idleEffectIntervalMax));
		InvokeRepeating("CheckSpawn", 1f, 1f);
	}

	private void OnDestroy()
	{
		if (m_instance == this)
		{
			m_instance = null;
		}
	}

	public string GetHoverText()
	{
		if (IsSpawned())
		{
			return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $raven_interact");
		}
		return "";
	}

	public string GetHoverName()
	{
		return Localization.instance.Localize(m_name);
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		if (m_hasTalked && Chat.instance.IsDialogVisible(base.gameObject))
		{
			Chat.instance.ClearNpcText(base.gameObject);
		}
		else
		{
			Talk();
		}
		return false;
	}

	private void Talk()
	{
		if ((bool)Player.m_localPlayer && m_currentText != null)
		{
			if (m_currentText.m_key.Length > 0)
			{
				Player.m_localPlayer.SetSeenTutorial(m_currentText.m_key);
				Gogan.LogEvent("Game", "Raven", m_currentText.m_key, 0L);
			}
			else
			{
				Gogan.LogEvent("Game", "Raven", m_currentText.m_topic, 0L);
			}
			m_hasTalked = true;
			if (m_currentText.m_label.Length > 0)
			{
				Player.m_localPlayer.AddKnownText(m_currentText.m_label, m_currentText.m_text);
			}
			Say(m_currentText.m_topic, m_currentText.m_text, showName: false, longTimeout: true, large: true);
			Game.instance.IncrementPlayerStat(PlayerStatType.RavenTalk);
		}
	}

	private void Say(string topic, string text, bool showName, bool longTimeout, bool large)
	{
		if (topic.Length > 0)
		{
			text = "<color=orange>" + topic + "</color>\n" + text;
		}
		Chat.instance.SetNpcText(base.gameObject, Vector3.up * m_textOffset, m_textCullDistance, longTimeout ? m_longDialogVisibleTime : m_dialogVisibleTime, showName ? m_name : "", text, large);
		m_animator.SetTrigger("talk");
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void IdleEffect()
	{
		if (IsSpawned())
		{
			m_idleEffect.Create(base.transform.position, base.transform.rotation);
			CancelInvoke("IdleEffect");
			InvokeRepeating("IdleEffect", UnityEngine.Random.Range(m_idleEffectIntervalMin, m_idleEffectIntervalMax), UnityEngine.Random.Range(m_idleEffectIntervalMin, m_idleEffectIntervalMax));
		}
	}

	private bool CanHide()
	{
		if (Player.m_localPlayer == null)
		{
			return true;
		}
		if (Chat.instance.IsDialogVisible(base.gameObject))
		{
			return false;
		}
		return true;
	}

	private void Update()
	{
		m_timeSinceTeleport += Time.deltaTime;
		if (!IsAway() && !IsFlying() && (bool)Player.m_localPlayer)
		{
			Vector3 vector = Player.m_localPlayer.transform.position - base.transform.position;
			vector.y = 0f;
			vector.Normalize();
			float f = Vector3.SignedAngle(base.transform.forward, vector, Vector3.up);
			if (Mathf.Abs(f) > m_minRotationAngle)
			{
				m_animator.SetFloat("anglevel", m_rotateSpeed * Mathf.Sign(f), 0.4f, Time.deltaTime);
				base.transform.rotation = Quaternion.RotateTowards(base.transform.rotation, Quaternion.LookRotation(vector), Time.deltaTime * m_rotateSpeed);
			}
			else
			{
				m_animator.SetFloat("anglevel", 0f, 0.4f, Time.deltaTime);
			}
		}
		if (IsSpawned())
		{
			if (Player.m_localPlayer != null && !Chat.instance.IsDialogVisible(base.gameObject) && Vector3.Distance(Player.m_localPlayer.transform.position, base.transform.position) < m_autoTalkDistance)
			{
				m_randomTextTimer += Time.deltaTime;
				float num = (m_hasTalked ? m_randomTextInterval : m_randomTextIntervalImportant);
				if (m_randomTextTimer >= num)
				{
					m_randomTextTimer = 0f;
					if (m_hasTalked)
					{
						Say("", m_randomTexts[UnityEngine.Random.Range(0, m_randomTexts.Count)], showName: false, longTimeout: false, large: false);
					}
					else
					{
						Say("", m_randomTextsImportant[UnityEngine.Random.Range(0, m_randomTextsImportant.Count)], showName: false, longTimeout: false, large: false);
					}
				}
			}
			if ((Player.m_localPlayer == null || Vector3.Distance(Player.m_localPlayer.transform.position, base.transform.position) > m_despawnDistance || EnemyNearby(base.transform.position) || RandEventSystem.InEvent() || m_currentText == null || m_groundObject == null || m_hasTalked) && CanHide())
			{
				bool forceTeleport = GetBestText() != null || m_groundObject == null;
				FlyAway(forceTeleport);
				RestartSpawnCheck(3f);
			}
			m_exclamation.SetActive(!m_hasTalked);
		}
		else
		{
			m_exclamation.SetActive(value: false);
		}
	}

	private bool FindSpawnPoint(out Vector3 point, out GameObject landOn)
	{
		Vector3 position = Player.m_localPlayer.transform.position;
		Vector3 forward = Utils.GetMainCamera().transform.forward;
		forward.y = 0f;
		forward.Normalize();
		point = new Vector3(0f, -999f, 0f);
		landOn = null;
		bool result = false;
		for (int i = 0; i < 20; i++)
		{
			Vector3 vector = Quaternion.Euler(0f, UnityEngine.Random.Range(-30, 30), 0f) * forward;
			Vector3 vector2 = position + vector * UnityEngine.Random.Range(m_spawnDistance - 5f, m_spawnDistance);
			if (ZoneSystem.instance.GetSolidHeight(vector2, out var height, out var normal, out var go) && height > 30f && height > point.y && height < 2000f && normal.y > 0.5f && Mathf.Abs(height - position.y) < 2f)
			{
				vector2.y = height;
				point = vector2;
				landOn = go;
				result = true;
			}
		}
		return result;
	}

	private bool EnemyNearby(Vector3 point)
	{
		return LootSpawner.IsMonsterInRange(point, m_enemyCheckDistance);
	}

	private bool InState(string name)
	{
		if (!m_animator.isInitialized)
		{
			return false;
		}
		if (m_animator.GetCurrentAnimatorStateInfo(0).IsTag(name))
		{
			return true;
		}
		if (m_animator.GetNextAnimatorStateInfo(0).IsTag(name))
		{
			return true;
		}
		return false;
	}

	private RavenText GetBestText()
	{
		RavenText ravenText = GetTempText();
		RavenText closestStaticText = GetClosestStaticText(m_spawnDistance);
		if (closestStaticText != null && (ravenText == null || closestStaticText.m_priority >= ravenText.m_priority))
		{
			ravenText = closestStaticText;
		}
		return ravenText;
	}

	private RavenText GetTempText()
	{
		foreach (RavenText tempText in m_tempTexts)
		{
			if (tempText.m_munin == m_isMunin)
			{
				return tempText;
			}
		}
		return null;
	}

	private RavenText GetClosestStaticText(float maxDistance)
	{
		if (Player.m_localPlayer == null)
		{
			return null;
		}
		RavenText ravenText = null;
		float num = 9999f;
		bool flag = false;
		Vector3 position = Player.m_localPlayer.transform.position;
		foreach (RavenText staticText in m_staticTexts)
		{
			if (staticText.m_munin != m_isMunin || !staticText.m_guidePoint)
			{
				continue;
			}
			float num2 = Vector3.Distance(position, staticText.m_guidePoint.transform.position);
			if (!(num2 < maxDistance))
			{
				continue;
			}
			bool flag2 = staticText.m_key.Length > 0 && Player.m_localPlayer.HaveSeenTutorial(staticText.m_key);
			if (!staticText.m_alwaysSpawn && flag2)
			{
				continue;
			}
			if (ravenText == null)
			{
				ravenText = staticText;
				num = num2;
				flag = flag2;
			}
			else if (flag2 == flag)
			{
				if (staticText.m_priority == ravenText.m_priority || flag2)
				{
					if (num2 < num)
					{
						ravenText = staticText;
						num = num2;
						flag = flag2;
					}
				}
				else if (staticText.m_priority > ravenText.m_priority)
				{
					ravenText = staticText;
					num = num2;
					flag = flag2;
				}
			}
			else if (!flag2 && flag)
			{
				ravenText = staticText;
				num = num2;
				flag = flag2;
			}
		}
		return ravenText;
	}

	private void RemoveSeendTempTexts()
	{
		for (int i = 0; i < m_tempTexts.Count; i++)
		{
			if (Player.m_localPlayer.HaveSeenTutorial(m_tempTexts[i].m_key))
			{
				m_tempTexts.RemoveAt(i);
				break;
			}
		}
	}

	private void FlyAway(bool forceTeleport = false)
	{
		Chat.instance.ClearNpcText(base.gameObject);
		if (forceTeleport || IsUnderRoof())
		{
			m_animator.SetTrigger("poff");
			m_timeSinceTeleport = 0f;
		}
		else
		{
			m_animator.SetTrigger("flyaway");
		}
	}

	private void CheckSpawn()
	{
		if (!(Player.m_localPlayer == null))
		{
			RemoveSeendTempTexts();
			RavenText bestText = GetBestText();
			if (IsSpawned() && CanHide() && bestText != null && bestText != m_currentText)
			{
				FlyAway(forceTeleport: true);
				m_currentText = null;
			}
			if (IsAway() && bestText != null && !EnemyNearby(base.transform.position) && !RandEventSystem.InEvent())
			{
				bool forceTeleport = m_timeSinceTeleport < 6f;
				Spawn(bestText, forceTeleport);
			}
		}
	}

	public DestructibleType GetDestructibleType()
	{
		return DestructibleType.Character;
	}

	public void Damage(HitData hit)
	{
		if (IsSpawned())
		{
			FlyAway(forceTeleport: true);
			RestartSpawnCheck(4f);
			Game.instance.IncrementPlayerStat(PlayerStatType.RavenHits);
		}
	}

	private void RestartSpawnCheck(float delay)
	{
		CancelInvoke("CheckSpawn");
		InvokeRepeating("CheckSpawn", delay, 1f);
	}

	private bool IsSpawned()
	{
		return InState("visible");
	}

	public bool IsAway()
	{
		return InState("away");
	}

	public bool IsFlying()
	{
		return InState("flying");
	}

	private void Spawn(RavenText text, bool forceTeleport)
	{
		if (Utils.GetMainCamera() == null || !m_tutorialsEnabled)
		{
			return;
		}
		if (text.m_static)
		{
			m_groundObject = text.m_guidePoint.gameObject;
			base.transform.position = text.m_guidePoint.transform.position;
		}
		else
		{
			if (!FindSpawnPoint(out var point, out var landOn))
			{
				return;
			}
			base.transform.position = point;
			m_groundObject = landOn;
		}
		m_currentText = text;
		m_hasTalked = false;
		m_randomTextTimer = 99999f;
		if (m_currentText.m_key.Length > 0 && Player.m_localPlayer.HaveSeenTutorial(m_currentText.m_key))
		{
			m_hasTalked = true;
		}
		Vector3 forward = Player.m_localPlayer.transform.position - base.transform.position;
		forward.y = 0f;
		forward.Normalize();
		base.transform.rotation = Quaternion.LookRotation(forward);
		if (forceTeleport)
		{
			m_animator.SetTrigger("teleportin");
		}
		else if (text.m_static)
		{
			if (IsUnderRoof())
			{
				m_animator.SetTrigger("teleportin");
			}
			else
			{
				m_animator.SetTrigger("flyin");
			}
		}
		else
		{
			m_animator.SetTrigger("flyin");
		}
		Game.instance.IncrementPlayerStat(PlayerStatType.RavenAppear);
	}

	private bool IsUnderRoof()
	{
		return Physics.Raycast(base.transform.position + Vector3.up * 0.2f, Vector3.up, 20f, LayerMask.GetMask("Default", "static_solid", "piece"));
	}

	public static void RegisterStaticText(RavenText text)
	{
		m_staticTexts.Add(text);
	}

	public static void UnregisterStaticText(RavenText text)
	{
		m_staticTexts.Remove(text);
	}

	public static void AddTempText(string key, string topic, string text, string label, bool munin)
	{
		if (key.Length > 0)
		{
			foreach (RavenText tempText in m_tempTexts)
			{
				if (tempText.m_key == key)
				{
					return;
				}
			}
		}
		RavenText ravenText = new RavenText();
		ravenText.m_key = key;
		ravenText.m_topic = topic;
		ravenText.m_label = label;
		ravenText.m_text = text;
		ravenText.m_static = false;
		ravenText.m_munin = munin;
		m_tempTexts.Add(ravenText);
	}
}
using UnityEngine;

public class Recipe : ScriptableObject
{
	public ItemDrop m_item;

	public int m_amount = 1;

	public bool m_enabled = true;

	[Tooltip("Only supported when using m_requireOnlyOneIngredient")]
	public float m_qualityResultAmountMultiplier = 1f;

	public int m_listSortWeight = 100;

	[Header("Requirements")]
	public CraftingStation m_craftingStation;

	public CraftingStation m_repairStation;

	public int m_minStationLevel = 1;

	public bool m_requireOnlyOneIngredient;

	public Piece.Requirement[] m_resources = new Piece.Requirement[0];

	public int GetRequiredStationLevel(int quality)
	{
		return Mathf.Max(1, m_minStationLevel) + (quality - 1);
	}

	public CraftingStation GetRequiredStation(int quality)
	{
		if ((bool)m_craftingStation)
		{
			return m_craftingStation;
		}
		if (quality > 1)
		{
			return m_repairStation;
		}
		return null;
	}

	public int GetAmount(int quality, out int need, out ItemDrop.ItemData singleReqItem, int craftMultiplier = 1)
	{
		int num = m_amount;
		need = 0;
		singleReqItem = null;
		if (m_requireOnlyOneIngredient)
		{
			singleReqItem = Player.m_localPlayer.GetFirstRequiredItem(Player.m_localPlayer.GetInventory(), this, quality, out need, out var extraAmount, craftMultiplier);
			num += (int)Mathf.Ceil((float)((singleReqItem.m_quality - 1) * m_amount) * m_qualityResultAmountMultiplier) + extraAmount;
		}
		return num * craftMultiplier;
	}
}
using UnityEngine;

public class ReflectionUpdate : MonoBehaviour
{
	private static ReflectionUpdate m_instance;

	public ReflectionProbe m_probe1;

	public ReflectionProbe m_probe2;

	public float m_interval = 3f;

	public float m_reflectionHeight = 5f;

	public float m_transitionDuration = 3f;

	public float m_power = 1f;

	private ReflectionProbe m_current;

	private int m_renderID;

	private float m_updateTimer;

	public static ReflectionUpdate instance => m_instance;

	private void Start()
	{
		m_instance = this;
		m_current = m_probe1;
	}

	private void OnDestroy()
	{
		m_instance = null;
	}

	public void UpdateReflection()
	{
		Vector3 referencePosition = ZNet.instance.GetReferencePosition();
		referencePosition += Vector3.up * m_reflectionHeight;
		m_current = ((m_current == m_probe1) ? m_probe2 : m_probe1);
		m_current.transform.position = referencePosition;
		m_renderID = m_current.RenderProbe();
	}

	private void Update()
	{
		float deltaTime = Time.deltaTime;
		m_updateTimer += deltaTime;
		if (m_updateTimer > m_interval)
		{
			m_updateTimer = 0f;
			UpdateReflection();
		}
		if (m_current.IsFinishedRendering(m_renderID))
		{
			float f = Mathf.Clamp01(m_updateTimer / m_transitionDuration);
			f = Mathf.Pow(f, m_power);
			if (m_probe1 == m_current)
			{
				m_probe1.importance = 1;
				m_probe2.importance = 0;
				Vector3 size = m_probe1.size;
				size.x = 2000f * f;
				size.y = 1000f * f;
				size.z = 2000f * f;
				m_probe1.size = size;
				m_probe2.size = new Vector3(2001f, 1001f, 2001f);
			}
			else
			{
				m_probe1.importance = 0;
				m_probe2.importance = 1;
				Vector3 size2 = m_probe2.size;
				size2.x = 2000f * f;
				size2.y = 1000f * f;
				size2.z = 2000f * f;
				m_probe2.size = size2;
				m_probe1.size = new Vector3(2001f, 1001f, 2001f);
			}
		}
	}
}
