public class RuneStone : MonoBehaviour, Hoverable, Interactable
{
	[Serializable]
	public class RandomRuneText
	{
		public string m_topic = "";

		public string m_label = "";

		public string m_text = "";
	}

	public string m_name = "Rune stone";

	public string m_topic = "";

	public string m_label = "";

	[TextArea]
	public string m_text = "";

	public List<RandomRuneText> m_randomTexts;

	public string m_locationName = "";

	public string m_pinName = "Pin";

	public Minimap.PinType m_pinType = Minimap.PinType.Boss;

	public bool m_showMap;

	public string GetHoverText()
	{
		return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_rune_read");
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		Player player = character as Player;
		if (!string.IsNullOrEmpty(m_locationName))
		{
			Game.instance.DiscoverClosestLocation(m_locationName, base.transform.position, m_pinName, (int)m_pinType, m_showMap);
		}
		RandomRuneText randomText = GetRandomText();
		if (randomText != null)
		{
			if (randomText.m_label.Length > 0)
			{
				player.AddKnownText(randomText.m_label, randomText.m_text);
			}
			TextViewer.instance.ShowText(TextViewer.Style.Rune, randomText.m_topic, randomText.m_text, autoHide: true);
		}
		else
		{
			if (m_label.Length > 0)
			{
				player.AddKnownText(m_label, m_text);
			}
			TextViewer.instance.ShowText(TextViewer.Style.Rune, m_topic, m_text, autoHide: true);
		}
		return false;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private RandomRuneText GetRandomText()
	{
		if (m_randomTexts.Count == 0)
		{
			return null;
		}
		Vector3 position = base.transform.position;
		int seed = (int)position.x * (int)position.z;
		UnityEngine.Random.State state = UnityEngine.Random.state;
		UnityEngine.Random.InitState(seed);
		RandomRuneText result = m_randomTexts[UnityEngine.Random.Range(0, m_randomTexts.Count)];
		UnityEngine.Random.state = state;
		return result;
	}
}
using UnityEngine;

public class Sadle : MonoBehaviour, Interactable, Hoverable, IDoodadController
{
	private enum Speed
	{
		Stop,
		Walk,
		Run,
		Turn,
		NoChange
	}

	public string m_hoverText = "";

	public float m_maxUseRange = 10f;

	public Transform m_attachPoint;

	public Vector3 m_detachOffset = new Vector3(0f, 0.5f, 0f);

	public string m_attachAnimation = "attach_chair";

	public float m_maxStamina = 100f;

	public float m_runStaminaDrain = 10f;

	public float m_swimStaminaDrain = 10f;

	public float m_staminaRegen = 10f;

	public float m_staminaRegenHungry = 10f;

	public EffectList m_drownEffects = new EffectList();

	public Sprite m_mountIcon;

	private const float m_staminaRegenDelay = 1f;

	private Vector3 m_controlDir;

	private Speed m_speed;

	private float m_rideSkill;

	private float m_staminaRegenTimer;

	private float m_drownDamageTimer;

	private float m_raiseSkillTimer;

	private Character m_character;

	private ZNetView m_nview;

	private Tameable m_tambable;

	private MonsterAI m_monsterAI;

	private bool m_haveValidUser;

	private void Awake()
	{
		m_character = base.gameObject.GetComponentInParent<Character>();
		m_nview = m_character.GetComponent<ZNetView>();
		m_tambable = m_character.GetComponent<Tameable>();
		m_monsterAI = m_character.GetComponent<MonsterAI>();
		m_nview.Register<long>("RequestControl", RPC_RequestControl);
		m_nview.Register<long>("ReleaseControl", RPC_ReleaseControl);
		m_nview.Register<bool>("RequestRespons", RPC_RequestRespons);
		m_nview.Register<Vector3>("RemoveSaddle", RPC_RemoveSaddle);
		m_nview.Register<Vector3, int, float>("Controls", RPC_Controls);
	}

	public bool IsValid()
	{
		return this;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void FixedUpdate()
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		CalculateHaveValidUser();
		if (m_character.IsTamed())
		{
			if (IsLocalUser())
			{
				UpdateRidingSkill(Time.fixedDeltaTime);
			}
			if (m_nview.IsOwner())
			{
				float fixedDeltaTime = Time.fixedDeltaTime;
				UpdateStamina(fixedDeltaTime);
				UpdateDrown(fixedDeltaTime);
			}
		}
	}

	private void UpdateDrown(float dt)
	{
		if (m_character.IsSwimming() && !m_character.IsOnGround() && !HaveStamina())
		{
			m_drownDamageTimer += dt;
			if (m_drownDamageTimer > 1f)
			{
				m_drownDamageTimer = 0f;
				float damage = Mathf.Ceil(m_character.GetMaxHealth() / 20f);
				HitData hitData = new HitData();
				hitData.m_damage.m_damage = damage;
				hitData.m_point = m_character.GetCenterPoint();
				hitData.m_dir = Vector3.down;
				hitData.m_pushForce = 10f;
				hitData.m_hitType = HitData.HitType.Drowning;
				m_character.Damage(hitData);
				Vector3 position = base.transform.position;
				position.y = m_character.GetLiquidLevel();
				m_drownEffects.Create(position, base.transform.rotation);
			}
		}
	}

	public bool UpdateRiding(float dt)
	{
		if (!base.isActiveAndEnabled)
		{
			return false;
		}
		if (!m_character.IsTamed())
		{
			return false;
		}
		if (!HaveValidUser())
		{
			return false;
		}
		if (m_speed == Speed.Stop || m_controlDir.magnitude == 0f)
		{
			return false;
		}
		if (m_speed == Speed.Walk || m_speed == Speed.Run)
		{
			if (m_speed == Speed.Run && !HaveStamina())
			{
				m_speed = Speed.Walk;
			}
			m_monsterAI.MoveTowards(m_controlDir, m_speed == Speed.Run);
			float riderSkill = GetRiderSkill();
			float num = Mathf.Lerp(1f, 0.5f, riderSkill);
			if (m_character.IsSwimming())
			{
				UseStamina(m_swimStaminaDrain * num * dt);
			}
			else if (m_speed == Speed.Run)
			{
				UseStamina(m_runStaminaDrain * num * dt);
			}
		}
		else if (m_speed == Speed.Turn)
		{
			m_monsterAI.StopMoving();
			m_character.SetRun(run: false);
			m_monsterAI.LookTowards(m_controlDir);
		}
		m_monsterAI.ResetRandomMovement();
		return true;
	}

	public string GetHoverText()
	{
		if (!InUseDistance(Player.m_localPlayer))
		{
			return Localization.instance.Localize("<color=#888888>$piece_toofar</color>");
		}
		string text = Localization.instance.Localize(m_hoverText);
		text += Localization.instance.Localize("\n[<color=yellow><b>$KEY_Use</b></color>] $piece_use");
		if (ZInput.IsNonClassicFunctionality() && ZInput.IsGamepadActive())
		{
			return text + Localization.instance.Localize("\n[<color=yellow><b>$KEY_AltKeys + $KEY_Use</b></color>] $hud_saddle_remove");
		}
		return text + Localization.instance.Localize("\n[<color=yellow><b>$KEY_AltPlace + $KEY_Use</b></color>] $hud_saddle_remove");
	}

	public string GetHoverName()
	{
		return Localization.instance.Localize(m_hoverText);
	}

	public bool Interact(Humanoid character, bool repeat, bool alt)
	{
		if (repeat)
		{
			return false;
		}
		if (!m_nview.IsValid())
		{
			return false;
		}
		if (!InUseDistance(character))
		{
			return false;
		}
		if (!m_character.IsTamed())
		{
			return false;
		}
		Player player = character as Player;
		if (player == null)
		{
			return false;
		}
		if (alt)
		{
			m_nview.InvokeRPC("RemoveSaddle", character.transform.position);
			return true;
		}
		m_nview.InvokeRPC("RequestControl", player.GetZDOID().UserID);
		return false;
	}

	public Character GetCharacter()
	{
		return m_character;
	}

	public Tameable GetTameable()
	{
		return m_tambable;
	}

	public void ApplyControlls(Vector3 moveDir, Vector3 lookDir, bool run, bool autoRun, bool block)
	{
		if (!(Player.m_localPlayer == null))
		{
			float skillFactor = Player.m_localPlayer.GetSkills().GetSkillFactor(Skills.SkillType.Ride);
			Speed speed = Speed.NoChange;
			Vector3 vector = Vector3.zero;
			if (block || (double)moveDir.z > 0.5 || run)
			{
				Vector3 vector2 = lookDir;
				vector2.y = 0f;
				vector2.Normalize();
				vector = vector2;
			}
			if (run)
			{
				speed = Speed.Run;
			}
			else if ((double)moveDir.z > 0.5)
			{
				speed = Speed.Walk;
			}
			else if ((double)moveDir.z < -0.5)
			{
				speed = Speed.Stop;
			}
			else if (block)
			{
				speed = Speed.Turn;
			}
			m_nview.InvokeRPC("Controls", vector, (int)speed, skillFactor);
		}
	}

	private void RPC_Controls(long sender, Vector3 rideDir, int rideSpeed, float skill)
	{
		if (!m_nview.IsOwner())
		{
			return;
		}
		m_rideSkill = skill;
		if (rideDir != Vector3.zero)
		{
			m_controlDir = rideDir;
		}
		switch (rideSpeed)
		{
		case 4:
			if (m_speed == Speed.Turn)
			{
				m_speed = Speed.Stop;
			}
			return;
		case 3:
			if (m_speed == Speed.Walk || m_speed == Speed.Run)
			{
				return;
			}
			break;
		}
		m_speed = (Speed)rideSpeed;
	}

	private void UpdateRidingSkill(float dt)
	{
		m_raiseSkillTimer += dt;
		if (m_raiseSkillTimer > 1f)
		{
			m_raiseSkillTimer = 0f;
			if (m_speed == Speed.Run)
			{
				Player.m_localPlayer.RaiseSkill(Skills.SkillType.Ride);
			}
		}
	}

	private void ResetControlls()
	{
		m_controlDir = Vector3.zero;
		m_speed = Speed.Stop;
		m_rideSkill = 0f;
	}

	public Component GetControlledComponent()
	{
		return m_character;
	}

	public Vector3 GetPosition()
	{
		return base.transform.position;
	}

	private void RPC_RemoveSaddle(long sender, Vector3 userPoint)
	{
		if (m_nview.IsOwner() && !HaveValidUser())
		{
			m_tambable.DropSaddle(userPoint);
		}
	}

	private void RPC_RequestControl(long sender, long playerID)
	{
		if (m_nview.IsOwner())
		{
			CalculateHaveValidUser();
			if (GetUser() == playerID || !HaveValidUser())
			{
				m_nview.GetZDO().Set(ZDOVars.s_user, playerID);
				ResetControlls();
				m_nview.InvokeRPC(sender, "RequestRespons", true);
				m_nview.GetZDO().SetOwner(sender);
			}
			else
			{
				m_nview.InvokeRPC(sender, "RequestRespons", false);
			}
		}
	}

	public bool HaveValidUser()
	{
		return m_haveValidUser;
	}

	private void CalculateHaveValidUser()
	{
		m_haveValidUser = false;
		long user = GetUser();
		if (user == 0L)
		{
			return;
		}
		foreach (ZDO allCharacterZDO in ZNet.instance.GetAllCharacterZDOS())
		{
			if (allCharacterZDO.m_uid.UserID == user)
			{
				m_haveValidUser = Vector3.Distance(allCharacterZDO.GetPosition(), base.transform.position) < m_maxUseRange;
				break;
			}
		}
	}

	private void RPC_ReleaseControl(long sender, long playerID)
	{
		if (m_nview.IsOwner() && GetUser() == playerID)
		{
			m_nview.GetZDO().Set(ZDOVars.s_user, 0L);
			ResetControlls();
		}
	}

	private void RPC_RequestRespons(long sender, bool granted)
	{
		if (!Player.m_localPlayer)
		{
			return;
		}
		if (granted)
		{
			Player.m_localPlayer.StartDoodadControl(this);
			if (m_attachPoint != null)
			{
				Player.m_localPlayer.AttachStart(m_attachPoint, m_character.gameObject, hideWeapons: false, isBed: false, onShip: false, m_attachAnimation, m_detachOffset);
			}
		}
		else
		{
			Player.m_localPlayer.Message(MessageHud.MessageType.Center, "$msg_inuse");
		}
	}

	public void OnUseStop(Player player)
	{
		if (m_nview.IsValid())
		{
			m_nview.InvokeRPC("ReleaseControl", player.GetZDOID().UserID);
			if (m_attachPoint != null)
			{
				player.AttachStop();
			}
		}
	}

	private bool IsLocalUser()
	{
		if (!Player.m_localPlayer)
		{
			return false;
		}
		long user = GetUser();
		if (user == 0L)
		{
			return false;
		}
		return user == Player.m_localPlayer.GetZDOID().UserID;
	}

	private long GetUser()
	{
		if (m_nview == null || !m_nview.IsValid())
		{
			return 0L;
		}
		return m_nview.GetZDO().GetLong(ZDOVars.s_user, 0L);
	}

	private bool InUseDistance(Humanoid human)
	{
		return Vector3.Distance(human.transform.position, m_attachPoint.position) < m_maxUseRange;
	}

	private void UseStamina(float v)
	{
		if (v != 0f && m_nview.IsValid() && m_nview.IsOwner())
		{
			float stamina = GetStamina();
			stamina -= v;
			if (stamina < 0f)
			{
				stamina = 0f;
			}
			SetStamina(stamina);
			m_staminaRegenTimer = 1f;
		}
	}

	private bool HaveStamina(float amount = 0f)
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		return GetStamina() > amount;
	}

	public float GetStamina()
	{
		if (m_nview == null)
		{
			return 0f;
		}
		if (m_nview.GetZDO() == null)
		{
			return 0f;
		}
		return m_nview.GetZDO().GetFloat(ZDOVars.s_stamina, GetMaxStamina());
	}

	private void SetStamina(float stamina)
	{
		m_nview.GetZDO().Set(ZDOVars.s_stamina, stamina);
	}

	public float GetMaxStamina()
	{
		return m_maxStamina;
	}

	private void UpdateStamina(float dt)
	{
		m_staminaRegenTimer -= dt;
		if (m_staminaRegenTimer > 0f || m_character.InAttack() || m_character.IsSwimming())
		{
			return;
		}
		float stamina = GetStamina();
		float maxStamina = GetMaxStamina();
		if (stamina < maxStamina || stamina > maxStamina)
		{
			float num = (m_tambable.IsHungry() ? m_staminaRegenHungry : m_staminaRegen);
			float num2 = num + (1f - stamina / maxStamina) * num;
			stamina += num2 * dt;
			if (stamina > maxStamina)
			{
				stamina = maxStamina;
			}
			SetStamina(stamina);
		}
	}

	public float GetRiderSkill()
	{
		return m_rideSkill;
	}
}
using System;
using UnityEngine;

public class SapCollector : MonoBehaviour, Hoverable, Interactable
{
	public string m_name = "";

	public Transform m_spawnPoint;

	public GameObject m_workingEffect;

	public GameObject m_notEmptyEffect;

	public float m_secPerUnit = 10f;

	public int m_maxLevel = 4;

	public ItemDrop m_spawnItem;

	public EffectList m_spawnEffect = new EffectList();

	public ZNetView m_mustConnectTo;

	public bool m_rayCheckConnectedBelow;

	[Header("Texts")]
	public string m_extractText = "$piece_sapcollector_extract";

	public string m_drainingText = "$piece_sapcollector_draining";

	public string m_drainingSlowText = "$piece_sapcollector_drainingslow";

	public string m_notConnectedText = "$piece_sapcollector_notconnected";

	public string m_fullText = "$piece_sapcollector_isfull";

	private ZNetView m_nview;

	private Collider m_collider;

	private Piece m_piece;

	private ZNetView m_connectedObject;

	private ResourceRoot m_root;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_collider = GetComponentInChildren<Collider>();
		m_piece = GetComponent<Piece>();
		if (m_nview.GetZDO() != null)
		{
			if (m_nview.IsOwner() && m_nview.GetZDO().GetLong(ZDOVars.s_lastTime, 0L) == 0L)
			{
				m_nview.GetZDO().Set(ZDOVars.s_lastTime, ZNet.instance.GetTime().Ticks);
			}
			m_nview.Register("RPC_Extract", RPC_Extract);
			m_nview.Register("RPC_UpdateEffects", RPC_UpdateEffects);
			InvokeRepeating("UpdateTick", UnityEngine.Random.Range(0f, 2f), 5f);
		}
	}

	public string GetHoverText()
	{
		int level = GetLevel();
		string statusText = GetStatusText();
		string text = m_name + " ( " + statusText + ", " + level + " / " + m_maxLevel + " )";
		if (level > 0)
		{
			text = text + "\n[<color=yellow><b>$KEY_Use</b></color>] " + m_extractText;
		}
		return Localization.instance.Localize(text);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool repeat, bool alt)
	{
		if (repeat)
		{
			return false;
		}
		if (!PrivateArea.CheckAccess(base.transform.position))
		{
			return true;
		}
		if (GetLevel() > 0)
		{
			Extract();
			Game.instance.IncrementPlayerStat(PlayerStatType.SapHarvested);
			return true;
		}
		return false;
	}

	private string GetStatusText()
	{
		if (GetLevel() >= m_maxLevel)
		{
			return m_fullText;
		}
		if (!m_root)
		{
			return m_notConnectedText;
		}
		if (m_root.IsLevelLow())
		{
			return m_drainingSlowText;
		}
		return m_drainingText;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void Extract()
	{
		m_nview.InvokeRPC("RPC_Extract");
	}

	private void RPC_Extract(long caller)
	{
		int level = GetLevel();
		if (level > 0)
		{
			m_spawnEffect.Create(m_spawnPoint.position, Quaternion.identity);
			for (int i = 0; i < level; i++)
			{
				Vector3 insideUnitSphere = UnityEngine.Random.insideUnitSphere;
				Vector3 position = m_spawnPoint.position + insideUnitSphere * 0.2f;
				UnityEngine.Object.Instantiate(m_spawnItem, position, Quaternion.identity).GetComponent<ItemDrop>()?.SetStack(Game.instance.ScaleDrops(m_spawnItem.m_itemData, 1));
			}
			ResetLevel();
			m_nview.InvokeRPC(ZNetView.Everybody, "RPC_UpdateEffects");
		}
	}

	private float GetTimeSinceLastUpdate()
	{
		DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_lastTime, ZNet.instance.GetTime().Ticks));
		DateTime time = ZNet.instance.GetTime();
		TimeSpan timeSpan = time - dateTime;
		m_nview.GetZDO().Set(ZDOVars.s_lastTime, time.Ticks);
		double num = timeSpan.TotalSeconds;
		if (num < 0.0)
		{
			num = 0.0;
		}
		return (float)num;
	}

	private void ResetLevel()
	{
		m_nview.GetZDO().Set(ZDOVars.s_level, 0);
	}

	private void IncreseLevel(int i)
	{
		int level = GetLevel();
		level += i;
		level = Mathf.Clamp(level, 0, m_maxLevel);
		m_nview.GetZDO().Set(ZDOVars.s_level, level);
	}

	private int GetLevel()
	{
		if (m_nview.GetZDO() == null)
		{
			return 0;
		}
		return m_nview.GetZDO().GetInt(ZDOVars.s_level);
	}

	private void UpdateTick()
	{
		if ((bool)m_mustConnectTo && !m_root)
		{
			Collider[] array = Physics.OverlapSphere(base.transform.position, 0.2f);
			for (int i = 0; i < array.Length; i++)
			{
				ResourceRoot componentInParent = array[i].GetComponentInParent<ResourceRoot>();
				if ((object)componentInParent != null)
				{
					m_root = componentInParent;
					break;
				}
			}
		}
		if (m_nview.IsOwner())
		{
			float timeSinceLastUpdate = GetTimeSinceLastUpdate();
			if (GetLevel() < m_maxLevel && (bool)m_root && m_root.CanDrain(1f))
			{
				float num = m_nview.GetZDO().GetFloat(ZDOVars.s_product);
				num += timeSinceLastUpdate;
				if (num > m_secPerUnit)
				{
					int num2 = (int)(num / m_secPerUnit);
					if ((bool)m_root)
					{
						num2 = Mathf.Min((int)m_root.GetLevel(), num2);
					}
					if (num2 > 0)
					{
						IncreseLevel(num2);
						if ((bool)m_root)
						{
							m_root.Drain(num2);
						}
					}
					num = 0f;
				}
				m_nview.GetZDO().Set(ZDOVars.s_product, num);
			}
		}
		UpdateEffects();
	}

	private void RPC_UpdateEffects(long caller)
	{
		UpdateEffects();
	}

	private void UpdateEffects()
	{
		int level = GetLevel();
		bool active = level < m_maxLevel && (bool)m_root && m_root.CanDrain(1f);
		m_notEmptyEffect.SetActive(level > 0);
		m_workingEffect.SetActive(active);
	}
}
using System;
using System.Collections.Generic;
using System.IO;

public class SaveCollection
{
	public readonly SaveDataType m_dataType;

	private List<SaveWithBackups> m_saves = new List<SaveWithBackups>();

	private Dictionary<string, SaveWithBackups> m_savesByName = new Dictionary<string, SaveWithBackups>(StringComparer.OrdinalIgnoreCase);

	private bool m_needsSort;

	private bool m_needsReload = true;

	public SaveWithBackups[] Saves
	{
		get
		{
			EnsureLoadedAndSorted();
			return m_saves.ToArray();
		}
	}

	public SaveCollection(SaveDataType dataType)
	{
		m_dataType = dataType;
	}

	public void Add(SaveWithBackups save)
	{
		m_saves.Add(save);
		SetNeedsSort();
	}

	public void Remove(SaveWithBackups save)
	{
		m_saves.Remove(save);
		SetNeedsSort();
	}

	public void EnsureLoadedAndSorted()
	{
		EnsureLoaded();
		if (m_needsSort)
		{
			Sort();
		}
	}

	private void EnsureLoaded()
	{
		if (m_needsReload)
		{
			Reload();
		}
	}

	public void InvalidateCache()
	{
		m_needsReload = true;
	}

	public bool TryGetSaveByName(string name, out SaveWithBackups save)
	{
		EnsureLoaded();
		return m_savesByName.TryGetValue(name, out save);
	}

	private void Reload()
	{
		m_saves.Clear();
		m_savesByName.Clear();
		List<string> listToAddTo = new List<string>();
		if (FileHelpers.CloudStorageEnabled)
		{
			GetAllFilesInSource(m_dataType, FileHelpers.FileSource.Cloud, ref listToAddTo);
		}
		int count = listToAddTo.Count;
		if (Directory.Exists(SaveSystem.GetSavePath(m_dataType, FileHelpers.FileSource.Local)))
		{
			GetAllFilesInSource(m_dataType, FileHelpers.FileSource.Local, ref listToAddTo);
		}
		int count2 = listToAddTo.Count;
		if (Directory.Exists(SaveSystem.GetSavePath(m_dataType, FileHelpers.FileSource.Legacy)))
		{
			GetAllFilesInSource(m_dataType, FileHelpers.FileSource.Legacy, ref listToAddTo);
		}
		for (int i = 0; i < listToAddTo.Count; i++)
		{
			string text = listToAddTo[i];
			if (!SaveSystem.GetSaveInfo(text, out var saveName, out var _, out var actualFileEnding, out var _))
			{
				continue;
			}
			FileHelpers.FileSource fileSource = SourceByIndexAndEntryCount(count, count2, i);
			if (fileSource != FileHelpers.FileSource.Cloud)
			{
				switch (m_dataType)
				{
				case SaveDataType.World:
					if (actualFileEnding != ".fwl" && actualFileEnding != ".db")
					{
						continue;
					}
					break;
				case SaveDataType.Character:
					if (actualFileEnding != ".fch")
					{
						continue;
					}
					break;
				default:
					ZLog.LogError($"File type filter not implemented for data type {m_dataType}!");
					break;
				}
			}
			if (!m_savesByName.TryGetValue(saveName, out var value))
			{
				value = new SaveWithBackups(saveName, this, SetNeedsSort);
				m_saves.Add(value);
				m_savesByName.Add(saveName, value);
			}
			value.AddSaveFile(text, fileSource);
		}
		m_needsReload = false;
		SetNeedsSort();
		static bool GetAllFilesInSource(SaveDataType dataType, FileHelpers.FileSource source, ref List<string> reference)
		{
			string savePath = SaveSystem.GetSavePath(dataType, source);
			string[] files = FileHelpers.GetFiles(source, savePath);
			if (files == null)
			{
				return false;
			}
			reference.AddRange(files);
			return true;
		}
		static FileHelpers.FileSource SourceByIndexAndEntryCount(int cloudEntries, int localEntries, int num)
		{
			if (num < cloudEntries)
			{
				return FileHelpers.FileSource.Cloud;
			}
			if (num < localEntries)
			{
				return FileHelpers.FileSource.Local;
			}
			return FileHelpers.FileSource.Legacy;
		}
	}

	private void Sort()
	{
		m_saves.Sort(new SaveWithBackupsComparer());
		m_needsSort = false;
	}

	private void SetNeedsSort()
	{
		m_needsSort = true;
	}
}
public enum SaveDataType
{
	World,
	Character
}
using System;
using System.Collections.Generic;

public class SaveFile
{
	private List<string> m_paths;

	public readonly FileHelpers.FileSource m_source;

	private Action m_modifiedCallback;

	private bool m_isDirty;

	private string m_fileName;

	public string PathPrimary
	{
		get
		{
			EnsureSorted();
			return m_paths[0];
		}
	}

	public string[] PathsAssociated
	{
		get
		{
			EnsureSorted();
			string[] array = new string[m_paths.Count - 1];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = m_paths[i + 1];
			}
			return array;
		}
	}

	public string[] AllPaths
	{
		get
		{
			EnsureSorted();
			return m_paths.ToArray();
		}
	}

	public string FileName
	{
		get
		{
			if (m_fileName == null)
			{
				string pathPrimary = PathPrimary;
				if (!SaveSystem.GetSaveInfo(pathPrimary, out var _, out var _, out var actualFileEnding, out var _))
				{
					m_fileName = SaveSystem.RemoveDirectoryPart(pathPrimary);
					return m_fileName;
				}
				switch (ParentSaveWithBackups.ParentSaveCollection.m_dataType)
				{
				case SaveDataType.World:
					if (actualFileEnding != ".fwl" && actualFileEnding != ".db")
					{
						m_fileName = SaveSystem.RemoveDirectoryPart(pathPrimary);
						return m_fileName;
					}
					break;
				case SaveDataType.Character:
					if (actualFileEnding != ".fch")
					{
						m_fileName = SaveSystem.RemoveDirectoryPart(pathPrimary);
						return m_fileName;
					}
					break;
				}
				string text = SaveSystem.RemoveDirectoryPart(pathPrimary);
				int num = text.LastIndexOf(actualFileEnding);
				if (num < 0)
				{
					m_fileName = text;
				}
				else
				{
					m_fileName = text.Remove(num, actualFileEnding.Length);
				}
			}
			return m_fileName;
		}
	}

	public DateTime LastModified { get; private set; } = DateTime.MinValue;

	public ulong Size { get; private set; }

	public SaveWithBackups ParentSaveWithBackups { get; private set; }

	public SaveFile(string path, FileHelpers.FileSource source, SaveWithBackups parentSaveWithBackups, Action modifiedCallback)
	{
		m_paths = new List<string>();
		m_source = source;
		ParentSaveWithBackups = parentSaveWithBackups;
		m_modifiedCallback = modifiedCallback;
		AddAssociatedFile(path);
	}

	public SaveFile(string[] paths, FileHelpers.FileSource source, SaveWithBackups parentSaveWithBackups, Action modifiedCallback)
	{
		m_paths = new List<string>();
		m_source = source;
		ParentSaveWithBackups = parentSaveWithBackups;
		m_modifiedCallback = modifiedCallback;
		AddAssociatedFiles(paths);
	}

	public SaveFile(FilePathAndSource pathAndSource, SaveWithBackups inSaveFile, Action modifiedCallback)
	{
		m_paths = new List<string>();
		m_source = pathAndSource.source;
		Size = 0uL;
		ParentSaveWithBackups = inSaveFile;
		m_modifiedCallback = modifiedCallback;
		AddAssociatedFile(pathAndSource.path);
	}

	public void AddAssociatedFile(string path)
	{
		m_paths.Add(path);
		Size += FileHelpers.GetFileSize(path, m_source);
		if (!SaveSystem.GetSaveInfo(path, out var _, out var _, out var _, out var timestamp) || !timestamp.HasValue)
		{
			timestamp = FileHelpers.GetLastWriteTime(path, m_source);
		}
		if (timestamp.Value > LastModified)
		{
			LastModified = timestamp.Value;
		}
		OnModified();
	}

	public void AddAssociatedFiles(string[] paths)
	{
		m_paths.AddRange(paths);
		for (int i = 0; i < paths.Length; i++)
		{
			Size += FileHelpers.GetFileSize(paths[i], m_source);
			if (!SaveSystem.GetSaveInfo(paths[i], out var _, out var _, out var _, out var timestamp) || !timestamp.HasValue)
			{
				timestamp = FileHelpers.GetLastWriteTime(paths[i], m_source);
			}
			if (timestamp.Value > LastModified)
			{
				LastModified = timestamp.Value;
			}
		}
		OnModified();
	}

	public override bool Equals(object obj)
	{
		if (!(obj is SaveFile saveFile))
		{
			return false;
		}
		if (m_source != saveFile.m_source)
		{
			return false;
		}
		string[] allPaths = AllPaths;
		string[] allPaths2 = saveFile.AllPaths;
		if (allPaths.Length != allPaths2.Length)
		{
			return false;
		}
		for (int i = 0; i < allPaths.Length; i++)
		{
			if (allPaths[i] != allPaths2[i])
			{
				return false;
			}
		}
		return true;
	}

	public override int GetHashCode()
	{
		string[] allPaths = AllPaths;
		int num = 878520832;
		num = num * -1521134295 + allPaths.Length.GetHashCode();
		for (int i = 0; i < allPaths.Length; i++)
		{
			num = num * -1521134295 + EqualityComparer<string>.Default.GetHashCode(allPaths[i]);
		}
		return num * -1521134295 + m_source.GetHashCode();
	}

	private void EnsureSorted()
	{
		if (m_isDirty)
		{
			m_paths.Sort(SaveSystem.GetComparerByDataType(ParentSaveWithBackups.ParentSaveCollection.m_dataType));
			m_isDirty = false;
		}
	}

	private void OnModified()
	{
		SetDirty();
		m_modifiedCallback?.Invoke();
	}

	private void SetDirty()
	{
		m_isDirty = m_paths.Count > 1;
		m_fileName = null;
	}
}
using System;
using System.Collections.Generic;

public class SaveFileComparer : IComparer<SaveFile>
{
	public int Compare(SaveFile x, SaveFile y)
	{
		return DateTime.Compare(y.LastModified, x.LastModified);
	}
}
