using System;
using System.Collections.Generic;

public static class ServerListUtils
{
	public static uint[] FairSplit(uint[] entryCounts, uint maxEntries)
	{
		uint num = 0u;
		uint num2 = 0u;
		for (int i = 0; i < entryCounts.Length; i++)
		{
			num += entryCounts[i];
			if (entryCounts[i] != 0)
			{
				num2++;
			}
		}
		if (num <= maxEntries)
		{
			return entryCounts;
		}
		uint[] array = new uint[entryCounts.Length];
		while (num2 != 0)
		{
			uint num3 = maxEntries / num2;
			if (num3 != 0)
			{
				for (int j = 0; j < entryCounts.Length; j++)
				{
					if (entryCounts[j] != 0)
					{
						if (entryCounts[j] > num3)
						{
							array[j] += num3;
							maxEntries -= num3;
							entryCounts[j] -= num3;
						}
						else
						{
							array[j] += entryCounts[j];
							maxEntries -= entryCounts[j];
							entryCounts[j] = 0u;
							num2--;
						}
					}
				}
				continue;
			}
			uint num4 = 0u;
			for (int k = 0; k < maxEntries; k++)
			{
				if (entryCounts[num4] != 0)
				{
					array[num4]++;
				}
				else
				{
					k--;
				}
				num4++;
			}
			maxEntries = 0u;
			break;
		}
		return array;
	}

	public static void GetFilteredList(IReadOnlyList<ServerJoinData> unfilteredList, string filter, List<ServerJoinData> resultOutput)
	{
		if (filter.Length <= 0)
		{
			resultOutput.AddRange(unfilteredList);
			return;
		}
		string value = filter.ToLowerInvariant();
		for (int i = 0; i < unfilteredList.Count; i++)
		{
			if (MultiBackendMatchmaking.TryGetServerName(unfilteredList[i], out var serverName) && serverName.ToLowerInvariant().Contains(value))
			{
				resultOutput.Add(unfilteredList[i]);
			}
		}
	}

	public static void GetFilteredList(IReadOnlyList<ServerData> unfilteredList, string filterLowerInvariant, List<ServerData> resultOutput)
	{
		for (int i = 0; i < unfilteredList.Count; i++)
		{
			if (unfilteredList[i].m_matchmakingData.m_serverName.ToLowerInvariant().Contains(filterLowerInvariant))
			{
				resultOutput.Add(unfilteredList[i]);
			}
		}
	}

	public static void UpdateServerOnlineStatus(IReadOnlyList<ServerJoinData> servers, DateTime newerThanUtc, MatchmakingDataRetrievedHandler matchmakingDataRetrievedHandler)
	{
		if (servers.Count <= 0)
		{
			return;
		}
		IReadOnlyList<IMatchmakingBackend> backends = MultiBackendMatchmaking.Instance.Backends;
		for (int i = 0; i < backends.Count; i++)
		{
			IMatchmakingBackend matchmakingBackend = backends[i];
			if (!matchmakingBackend.IsAvailable || !matchmakingBackend.CanRefreshServerNow())
			{
				continue;
			}
			for (int j = 0; j < servers.Count; j++)
			{
				ServerJoinData server = servers[j];
				if (!server.IsValid || !matchmakingBackend.CanRefreshServerOfTypeNow(server.m_type) || (server.m_type == ServerJoinDataType.Dedicated && !MultiBackendMatchmaking.ServerIPAddressIsKnown(server.Dedicated)) || matchmakingBackend.IsPending(server))
				{
					continue;
				}
				ServerMatchmakingData serverMatchmakingData = matchmakingBackend.GetServerMatchmakingData(server, newerThanUtc);
				if (serverMatchmakingData.IsValid && serverMatchmakingData.m_timestampUtc > newerThanUtc)
				{
					continue;
				}
				bool flag = false;
				for (int k = 0; k < backends.Count; k++)
				{
					if (i == k)
					{
						continue;
					}
					IMatchmakingBackend matchmakingBackend2 = backends[k];
					if (matchmakingBackend2.IsAvailable)
					{
						if (matchmakingBackend2.IsPending(server))
						{
							flag = true;
							break;
						}
						ServerMatchmakingData serverMatchmakingData2 = matchmakingBackend2.GetServerMatchmakingData(server, newerThanUtc);
						if (serverMatchmakingData2.m_onlineStatus.IsOnline() && serverMatchmakingData2.m_timestampUtc >= newerThanUtc)
						{
							flag = true;
							break;
						}
					}
				}
				if (!flag && matchmakingBackend.RefreshServer(server, matchmakingDataRetrievedHandler) && !matchmakingBackend.CanRefreshServerNow())
				{
					break;
				}
			}
		}
	}
}
using System;
using System.Text;
using Splatform;

public struct ServerMatchmakingData
{
	public readonly DateTime m_timestampUtc;

	public readonly string m_serverName;

	public readonly uint m_playerCount;

	public readonly uint m_playerLimit;

	public readonly PlatformUserID m_hostUser;

	public readonly GameVersion m_gameVersion;

	public readonly uint m_networkVersion;

	public readonly string m_joinCode;

	public readonly bool m_isPasswordProtected;

	public readonly Platform m_platformRestriction;

	public readonly string[] m_modifiers;

	public readonly OnlineStatus m_onlineStatus;

	public static ServerMatchmakingData None => default(ServerMatchmakingData);

	public bool IsCrossplay => !m_platformRestriction.IsValid;

	public bool IsRestrictedToOwnPlatform => m_platformRestriction == PlatformManager.DistributionPlatform.Platform;

	public bool IsUnjoinable
	{
		get
		{
			if (!m_onlineStatus.IsOnline())
			{
				return false;
			}
			if (IsRestrictedToOwnPlatform)
			{
				return false;
			}
			if (!IsCrossplay)
			{
				return true;
			}
			return PlatformManager.DistributionPlatform.PrivilegeProvider.CheckPrivilege(Privilege.CrossPlatformMultiplayer) != PrivilegeResult.Granted;
		}
	}

	public bool IsValid => m_timestampUtc != default(DateTime);

	public ServerMatchmakingData(DateTime timestampUtc, bool couldCheck = true)
	{
		m_timestampUtc = timestampUtc;
		m_serverName = null;
		m_playerCount = 0u;
		m_playerLimit = 0u;
		m_hostUser = default(PlatformUserID);
		m_gameVersion = default(GameVersion);
		m_networkVersion = 0u;
		m_joinCode = null;
		m_isPasswordProtected = false;
		m_platformRestriction = default(Platform);
		m_modifiers = null;
		m_onlineStatus = ((!couldCheck) ? OnlineStatus.NotAvailable : OnlineStatus.Offline);
	}

	public ServerMatchmakingData(DateTime timestampUtc, string serverName)
	{
		m_timestampUtc = timestampUtc;
		m_serverName = serverName;
		m_playerCount = 0u;
		m_playerLimit = 0u;
		m_hostUser = default(PlatformUserID);
		m_gameVersion = default(GameVersion);
		m_networkVersion = 0u;
		m_joinCode = null;
		m_isPasswordProtected = false;
		m_platformRestriction = default(Platform);
		m_modifiers = null;
		m_onlineStatus = OnlineStatus.Offline;
	}

	public ServerMatchmakingData(DateTime timestampUtc, string serverName, uint playerCount, uint playerLimit, PlatformUserID serverOwner, GameVersion gameVersion, uint networkVersion, string joinCode, bool isPasswordProtected, Platform platformRestriction, string[] modifiers)
	{
		m_timestampUtc = timestampUtc;
		m_serverName = serverName ?? throw new ArgumentNullException("serverName");
		m_playerCount = playerCount;
		m_playerLimit = playerLimit;
		m_hostUser = serverOwner;
		m_gameVersion = gameVersion;
		m_networkVersion = networkVersion;
		m_joinCode = joinCode;
		m_isPasswordProtected = isPasswordProtected;
		m_platformRestriction = platformRestriction;
		m_modifiers = modifiers;
		m_onlineStatus = OnlineStatus.Online;
	}

	public override string ToString()
	{
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_timestampUtc", m_timestampUtc));
		stringBuilder.AppendLine("m_serverName: " + m_serverName);
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_playerCount", m_playerCount));
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_playerLimit", m_playerLimit));
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_hostUser", m_hostUser));
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_gameVersion", m_gameVersion));
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_networkVersion", m_networkVersion));
		stringBuilder.AppendLine("m_joinCode: " + m_joinCode);
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_isPasswordProtected", m_isPasswordProtected));
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_platformRestriction", m_platformRestriction));
		stringBuilder.AppendLine("m_modifiers:");
		for (int i = 0; i < m_modifiers.Length; i++)
		{
			stringBuilder.AppendLine("\t" + m_modifiers[i]);
		}
		stringBuilder.AppendLine(string.Format("{0}: {1}", "m_onlineStatus", m_onlineStatus));
		return stringBuilder.ToString();
	}
}
