using UnityEngine;

public class SE_Demister : StatusEffect
{
	[Header("SE_Demister")]
	public GameObject m_ballPrefab;

	public Vector3 m_offset = new Vector3(0f, 2f, 0f);

	public Vector3 m_offsetInterior = new Vector3(0.5f, 1.8f, 0f);

	public float m_maxDistance = 50f;

	public float m_ballAcceleration = 4f;

	public float m_ballMaxSpeed = 10f;

	public float m_ballFriction = 0.1f;

	public float m_noiseDistance = 1f;

	public float m_noiseDistanceInterior = 0.2f;

	public float m_noiseDistanceYScale = 1f;

	public float m_noiseSpeed = 1f;

	public float m_characterVelocityFactor = 1f;

	public float m_rotationSpeed = 1f;

	private int m_coverRayMask;

	private GameObject m_ballInstance;

	private Vector3 m_ballVel = new Vector3(0f, 0f, 0f);

	public override void Setup(Character character)
	{
		base.Setup(character);
		if (m_coverRayMask == 0)
		{
			m_coverRayMask = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece", "terrain");
		}
	}

	private bool IsUnderRoof()
	{
		if (Physics.Raycast(m_character.GetCenterPoint(), Vector3.up, out var _, 4f, m_coverRayMask))
		{
			return true;
		}
		return false;
	}

	public override void UpdateStatusEffect(float dt)
	{
		base.UpdateStatusEffect(dt);
		if (!m_ballInstance)
		{
			Vector3 position = m_character.GetCenterPoint() + m_character.transform.forward * 0.5f;
			m_ballInstance = Object.Instantiate(m_ballPrefab, position, Quaternion.identity);
			return;
		}
		_ = m_character;
		bool num = IsUnderRoof();
		Vector3 position2 = m_character.transform.position;
		Vector3 vector = m_ballInstance.transform.position;
		Vector3 vector2 = (num ? m_offsetInterior : m_offset);
		float num2 = (num ? m_noiseDistanceInterior : m_noiseDistance);
		Vector3 vector3 = position2 + m_character.transform.TransformVector(vector2);
		float num3 = Time.time * m_noiseSpeed;
		vector3 += new Vector3(Mathf.Sin(num3 * 4f), Mathf.Sin(num3 * 2f) * m_noiseDistanceYScale, Mathf.Cos(num3 * 5f)) * num2;
		float num4 = Vector3.Distance(vector3, vector);
		if (num4 > m_maxDistance * 2f)
		{
			vector = vector3;
		}
		else if (num4 > m_maxDistance)
		{
			Vector3 normalized = (vector - vector3).normalized;
			vector = vector3 + normalized * m_maxDistance;
		}
		Vector3 normalized2 = (vector3 - vector).normalized;
		m_ballVel += normalized2 * m_ballAcceleration * dt;
		if (m_ballVel.magnitude > m_ballMaxSpeed)
		{
			m_ballVel = m_ballVel.normalized * m_ballMaxSpeed;
		}
		if (!num)
		{
			Vector3 velocity = m_character.GetVelocity();
			m_ballVel += velocity * m_characterVelocityFactor * dt;
		}
		m_ballVel -= m_ballVel * m_ballFriction;
		Vector3 position3 = vector + m_ballVel * dt;
		m_ballInstance.transform.position = position3;
		Quaternion rotation = m_ballInstance.transform.rotation;
		rotation *= Quaternion.Euler(m_rotationSpeed, 0f, m_rotationSpeed * 0.5321f);
		m_ballInstance.transform.rotation = rotation;
	}

	private void RemoveEffects()
	{
		if (m_ballInstance != null)
		{
			ZNetView component = m_ballInstance.GetComponent<ZNetView>();
			if (component.IsValid())
			{
				component.ClaimOwnership();
				component.Destroy();
			}
		}
	}

	protected override void OnApplicationQuit()
	{
		base.OnApplicationQuit();
		m_ballInstance = null;
	}

	public override void Stop()
	{
		base.Stop();
		RemoveEffects();
	}

	public override void OnDestroy()
	{
		base.OnDestroy();
		RemoveEffects();
	}
}
using UnityEngine;

public class SE_Finder : StatusEffect
{
	[Header("SE_Finder")]
	public EffectList m_pingEffectNear = new EffectList();

	public EffectList m_pingEffectMed = new EffectList();

	public EffectList m_pingEffectFar = new EffectList();

	public float m_closerTriggerDistance = 2f;

	public float m_furtherTriggerDistance = 4f;

	public float m_closeFrequency = 1f;

	public float m_distantFrequency = 5f;

	private float m_updateBeaconTimer;

	private float m_pingTimer;

	private Beacon m_beacon;

	private float m_lastDistance;

	public override void UpdateStatusEffect(float dt)
	{
		m_updateBeaconTimer += dt;
		if (m_updateBeaconTimer > 1f)
		{
			m_updateBeaconTimer = 0f;
			Beacon beacon = Beacon.FindClosestBeaconInRange(m_character.transform.position);
			if (beacon != m_beacon)
			{
				m_beacon = beacon;
				if ((bool)m_beacon)
				{
					m_lastDistance = Utils.DistanceXZ(m_character.transform.position, m_beacon.transform.position);
					m_pingTimer = 0f;
				}
			}
		}
		if (!(m_beacon != null))
		{
			return;
		}
		float num = Utils.DistanceXZ(m_character.transform.position, m_beacon.transform.position);
		float num2 = Mathf.Clamp01(num / m_beacon.m_range);
		float num3 = Mathf.Lerp(m_closeFrequency, m_distantFrequency, num2);
		m_pingTimer += dt;
		if (m_pingTimer > num3)
		{
			m_pingTimer = 0f;
			if (num2 < 0.2f)
			{
				m_pingEffectNear.Create(m_character.transform.position, m_character.transform.rotation, m_character.transform);
			}
			else if (num2 < 0.6f)
			{
				m_pingEffectMed.Create(m_character.transform.position, m_character.transform.rotation, m_character.transform);
			}
			else
			{
				m_pingEffectFar.Create(m_character.transform.position, m_character.transform.rotation, m_character.transform);
			}
			m_lastDistance = num;
		}
	}
}
using UnityEngine;

public class SE_Frost : StatusEffect
{
	[Header("SE_Frost")]
	public float m_freezeTimeEnemy = 10f;

	public float m_freezeTimePlayer = 10f;

	public float m_minSpeedFactor = 0.1f;

	public override void UpdateStatusEffect(float dt)
	{
		base.UpdateStatusEffect(dt);
	}

	public void AddDamage(float damage)
	{
		float num = (m_character.IsPlayer() ? m_freezeTimePlayer : m_freezeTimeEnemy);
		float num2 = Mathf.Clamp01(damage / m_character.GetMaxHealth()) * num;
		float num3 = m_ttl - m_time;
		if (num2 > num3)
		{
			m_ttl = num2;
			ResetTime();
			TriggerStartEffects();
		}
	}

	public override void ModifySpeed(float baseSpeed, ref float speed, Character character, Vector3 dir)
	{
		HitData.DamageModifiers damageModifiers = character.GetDamageModifiers();
		if (damageModifiers.m_frost != HitData.DamageModifier.Resistant && damageModifiers.m_frost != HitData.DamageModifier.VeryResistant && damageModifiers.m_frost != HitData.DamageModifier.SlightlyResistant && damageModifiers.m_frost != HitData.DamageModifier.Immune)
		{
			float f = Mathf.Clamp01(m_time / m_ttl);
			f = Mathf.Pow(f, 2f);
			speed -= baseSpeed * Mathf.Lerp(1f - m_minSpeedFactor, 0f, f);
			if (speed < 0f)
			{
				speed = 0f;
			}
		}
	}
}
using UnityEngine;

public class SE_Harpooned : StatusEffect
{
	[Header("SE_Harpooned")]
	public float m_pullForce;

	public float m_forcePower = 2f;

	public float m_pullSpeed = 5f;

	public float m_smoothDistance = 2f;

	public float m_maxLineSlack = 0.3f;

	public float m_breakDistance = 4f;

	public float m_maxDistance = 30f;

	public float m_staminaDrain = 10f;

	public float m_staminaDrainInterval = 0.1f;

	private bool m_broken;

	private Character m_attacker;

	private float m_baseDistance = 999999f;

	private LineConnect m_line;

	private float m_drainStaminaTimer;

	public override void Setup(Character character)
	{
		base.Setup(character);
	}

	public override void SetAttacker(Character attacker)
	{
		ZLog.Log("Setting attacker " + attacker.m_name);
		m_attacker = attacker;
		m_time = 0f;
		if (m_character.IsBoss())
		{
			m_broken = true;
			return;
		}
		float num = Vector3.Distance(m_attacker.transform.position, m_character.transform.position);
		if (num > m_maxDistance)
		{
			m_attacker.Message(MessageHud.MessageType.Center, "$msg_harpoon_targettoofar");
			m_broken = true;
			return;
		}
		m_baseDistance = num;
		m_attacker.Message(MessageHud.MessageType.Center, m_character.m_name + " $msg_harpoon_harpooned");
		GameObject[] startEffectInstances = m_startEffectInstances;
		foreach (GameObject gameObject in startEffectInstances)
		{
			if ((bool)gameObject)
			{
				LineConnect component = gameObject.GetComponent<LineConnect>();
				if ((bool)component)
				{
					component.SetPeer(m_attacker.GetComponent<ZNetView>());
					m_line = component;
				}
			}
		}
	}

	public override void UpdateStatusEffect(float dt)
	{
		base.UpdateStatusEffect(dt);
		if (!m_attacker)
		{
			return;
		}
		Rigidbody component = m_character.GetComponent<Rigidbody>();
		if (!component)
		{
			return;
		}
		float num = Vector3.Distance(m_attacker.transform.position, m_character.transform.position);
		if (m_character.GetStandingOnShip() == null && !m_character.IsAttached())
		{
			float num2 = Utils.Pull(component, m_attacker.transform.position, m_baseDistance, m_pullSpeed, m_pullForce, m_smoothDistance, noUpForce: true, useForce: true, m_forcePower);
			m_drainStaminaTimer += dt;
			if (m_drainStaminaTimer > m_staminaDrainInterval && num2 > 0f)
			{
				m_drainStaminaTimer = 0f;
				float stamina = m_staminaDrain * num2 * m_character.GetMass();
				m_attacker.UseStamina(stamina);
			}
		}
		if ((bool)m_line)
		{
			m_line.SetSlack((1f - Utils.LerpStep(m_baseDistance / 2f, m_baseDistance, num)) * m_maxLineSlack);
		}
		if (num - m_baseDistance > m_breakDistance)
		{
			m_broken = true;
			m_attacker.Message(MessageHud.MessageType.Center, "$msg_harpoon_linebroke");
		}
		if (!m_attacker.HaveStamina())
		{
			m_broken = true;
			m_attacker.Message(MessageHud.MessageType.Center, m_character.m_name + " $msg_harpoon_released");
		}
	}

	public override bool IsDone()
	{
		if (base.IsDone())
		{
			return true;
		}
		if (m_broken)
		{
			return true;
		}
		if (!m_attacker)
		{
			return true;
		}
		if (m_time > 2f && (m_attacker.IsBlocking() || m_attacker.InAttack()))
		{
			m_attacker.Message(MessageHud.MessageType.Center, m_character.m_name + " released");
			return true;
		}
		return false;
	}
}
