}
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using UnityEngine;

public class ShieldGenerator : MonoBehaviour, Hoverable, Interactable, IHasHoverMenu
{
	private static bool s_cleanShields = false;

	private static List<ShieldGenerator> m_instances = new List<ShieldGenerator>();

	private static int m_instanceChangeID = 0;

	private static ShieldDomeImageEffect m_shieldDomeEffect;

	public string m_name = "$piece_shieldgenerator";

	public string m_add = "$piece_shieldgenerator_add";

	public Switch m_addFuelSwitch;

	public GameObject m_enabledObject;

	public GameObject m_disabledObject;

	[Header("Fuel")]
	public List<ItemDrop> m_fuelItems = new List<ItemDrop>();

	public int m_maxFuel = 10;

	public int m_defaultFuel;

	public float m_fuelPerDamage = 0.01f;

	public EffectList m_fuelAddedEffects = new EffectList();

	[Header("Shield")]
	public GameObject m_shieldDome;

	public float m_minShieldRadius = 10f;

	public float m_maxShieldRadius = 30f;

	public float m_decreaseInertia = 0.98f;

	public float m_startStopSpeed = 0.5f;

	public bool m_offWhenNoFuel = true;

	[Header("Attack")]
	public bool m_enableAttack = true;

	public float m_attackChargeTime = 900f;

	public bool m_damagePlayers = true;

	public GameObject m_attackObject;

	public EffectList m_attackEffects = new EffectList();

	[Header("Effects")]
	public EffectList m_shieldHitEffects = new EffectList();

	public EffectList m_shieldStart = new EffectList();

	public EffectList m_shieldStop = new EffectList();

	public EffectList m_shieldLowLoop = new EffectList();

	public float m_shieldLowLoopFuelStart;

	public ParticleSystem[] m_energyParticles;

	public ParticleSystem m_energyParticlesFlare;

	public Light[] m_coloredLights;

	private static readonly int s_emissiveProperty = Shader.PropertyToID("_EmissionColor");

	private ZNetView m_nview;

	private StringBuilder m_sb = new StringBuilder();

	private bool m_firstCheck;

	private int m_projectileMask;

	private float m_radius;

	private float m_radiusTarget;

	private float m_radiusSent;

	private float m_lastFuel;

	private float m_lastFuelSent;

	private float m_lastHitTime;

	private float m_lastHitTimeSent;

	private float m_attackCharge;

	private bool m_isPlacementGhost;

	private GameObject[] m_lowLoopInstances;

	private Gradient m_particleFlareGradient;

	private MeshRenderer[] m_meshRenderers;

	private MaterialPropertyBlock m_propertyBlock;

	private void Start()
	{
		if (Player.IsPlacementGhost(base.gameObject))
		{
			base.enabled = false;
			m_isPlacementGhost = true;
			return;
		}
		m_instances.Add(this);
		m_instanceChangeID++;
		m_nview = GetComponent<ZNetView>();
		if (m_nview == null)
		{
			m_nview = GetComponentInParent<ZNetView>();
		}
		if (!(m_nview == null) && m_nview.GetZDO() != null)
		{
			if ((bool)m_addFuelSwitch)
			{
				Switch addFuelSwitch = m_addFuelSwitch;
				addFuelSwitch.m_onUse = (Switch.Callback)Delegate.Combine(addFuelSwitch.m_onUse, new Switch.Callback(OnAddFuel));
				m_addFuelSwitch.m_onHover = OnHoverAddFuel;
			}
			m_nview.Register("RPC_AddFuel", RPC_AddFuel);
			m_nview.Register<float>("RPC_SetFuel", RPC_SetFuel);
			m_nview.Register("RPC_Attack", RPC_Attack);
			m_nview.Register("RPC_HitNow", RPC_HitNow);
			m_projectileMask = LayerMask.GetMask();
			if (!m_shieldDomeEffect)
			{
				m_shieldDomeEffect = UnityEngine.Object.FindFirstObjectByType<ShieldDomeImageEffect>();
			}
			if (!m_enableAttack && m_fuelItems.Count == 0)
			{
				m_addFuelSwitch.gameObject.SetActive(value: false);
			}
			m_particleFlareGradient = new Gradient();
			m_particleFlareGradient.colorKeys = new GradientColorKey[1]
			{
				new GradientColorKey(Color.white, 0f)
			};
			m_particleFlareGradient.alphaKeys = new GradientAlphaKey[1]
			{
				new GradientAlphaKey(0f, 0f)
			};
			m_propertyBlock = new MaterialPropertyBlock();
			m_meshRenderers = m_enabledObject.GetComponentsInChildren<MeshRenderer>();
			InvokeRepeating("UpdateShield", 0f, 0.22f);
		}
	}

	public string GetHoverText()
	{
		if (!m_enableAttack)
		{
			return "";
		}
		if (m_attackCharge <= 0f)
		{
			return Localization.instance.Localize(m_name + "\n$piece_shieldgenerator_waiting");
		}
		if (m_attackCharge >= 1f)
		{
			return Localization.instance.Localize(m_name + "\n$piece_shieldgenerator_ready \n[<color=yellow><b>$KEY_Use</b></color>] $piece_shieldgenerator_use");
		}
		return Localization.instance.Localize(m_name + "\n$piece_shieldgenerator_charging " + (Terminal.m_showTests ? m_attackCharge.ToString("0.00") : ""));
	}

	public string GetHoverName()
	{
		return "";
	}

	public bool Interact(Humanoid user, bool repeat, bool alt)
	{
		if (!m_enableAttack)
		{
			return false;
		}
		if (repeat)
		{
			return false;
		}
		if (user == Player.m_localPlayer && m_attackCharge >= 1f)
		{
			m_nview.InvokeRPC("RPC_Attack");
		}
		return false;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void RPC_Attack(long sender)
	{
		m_attackCharge = 0f;
		if (!m_nview.IsOwner())
		{
			return;
		}
		SetFuel(0f);
		m_nview.GetZDO().Set(ZDOVars.s_startTime, 0L);
		UpdateAttackCharge();
		if ((bool)m_attackObject)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(m_attackObject, base.transform.position, base.transform.rotation);
			if (!m_damagePlayers)
			{
				gameObject.GetComponentInChildren<Aoe>()?.Setup(Player.m_localPlayer, Vector3.zero, 1f, null, null, null);
			}
		}
		m_attackEffects.Create(base.transform.position, base.transform.rotation);
		m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation, base.transform);
	}

	private void RPC_HitNow(long sender)
	{
		m_lastHitTime = Time.time;
	}

	private void UpdateAttackCharge()
	{
		m_attackCharge = GetAttackCharge();
	}

	private float GetAttackCharge()
	{
		long num = m_nview.GetZDO().GetLong(ZDOVars.s_startTime, 0L);
		if (num <= 0)
		{
			return 0f;
		}
		DateTime time = ZNet.instance.GetTime();
		DateTime dateTime = new DateTime(num);
		return (float)((time - dateTime).TotalSeconds / (double)m_attackChargeTime);
	}

	private void OnDestroy()
	{
		if (!m_isPlacementGhost)
		{
			m_shieldDomeEffect.RemoveShield(this);
			m_instances.Remove(this);
			m_instanceChangeID++;
			Character.SetupContinuousEffect(base.transform, base.transform.position, enabledEffect: false, m_shieldLowLoop, ref m_lowLoopInstances);
		}
	}

	private float GetFuel()
	{
		if (!m_nview.IsValid())
		{
			return 0f;
		}
		return m_nview.GetZDO().GetFloat(ZDOVars.s_fuel, m_defaultFuel);
	}

	private void SetFuel(float fuel)
	{
		m_nview.InvokeRPC("RPC_SetFuel", fuel);
	}

	private void RPC_SetFuel(long sender, float fuel)
	{
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_fuel, Mathf.Max(fuel, 0f));
		}
	}

	private bool OnAddFuel(Switch sw, Humanoid user, ItemDrop.ItemData item)
	{
		if (GetFuel() > (float)(m_maxFuel - 1))
		{
			user.Message(MessageHud.MessageType.Center, "$msg_itsfull");
			return false;
		}
		if (item != null)
		{
			bool flag = false;
			foreach (ItemDrop fuelItem in m_fuelItems)
			{
				if (item.m_shared.m_name == fuelItem.m_itemData.m_shared.m_name)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				user.Message(MessageHud.MessageType.Center, "$msg_wrongitem");
				return false;
			}
		}
		else
		{
			bool flag2 = false;
			foreach (ItemDrop fuelItem2 in m_fuelItems)
			{
				if (user.GetInventory().HaveItem(fuelItem2.m_itemData.m_shared.m_name))
				{
					item = fuelItem2.m_itemData;
					flag2 = true;
					break;
				}
			}
			if (!flag2)
			{
				user.Message(MessageHud.MessageType.Center, "$msg_donthaveany $piece_shieldgenerator_fuelname");
				return false;
			}
		}
		user.Message(MessageHud.MessageType.Center, "$msg_added " + item.m_shared.m_name);
		user.GetInventory().RemoveItem(item.m_shared.m_name, 1);
		m_nview.InvokeRPC("RPC_AddFuel");
		return true;
	}

	private void RPC_AddFuel(long sender)
	{
		if (m_nview.IsOwner())
		{
			float fuel = GetFuel();
			SetFuel(fuel + 1f);
			m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation, base.transform);
		}
	}

	private void Update()
	{
		if ((bool)m_shieldDome)
		{
			float num = m_shieldDome.transform.localScale.x + (m_radius - m_shieldDome.transform.localScale.x) * m_decreaseInertia;
			m_shieldDome.transform.localScale = new Vector3(num, num, num);
		}
		if (m_radiusTarget != m_radius)
		{
			if (!m_firstCheck)
			{
				m_firstCheck = true;
				m_radius = m_radiusTarget;
			}
			float num2 = m_radiusTarget - m_radius;
			m_radius += Mathf.Min(m_startStopSpeed * Time.deltaTime, Mathf.Abs(num2)) * (float)((num2 > 0f) ? 1 : (-1));
		}
		if (m_lastFuel != m_lastFuelSent || m_radius != m_radiusSent || m_lastHitTime != m_lastHitTimeSent)
		{
			m_shieldDomeEffect.SetShieldData(this, m_shieldDome.transform.position, m_radius, m_lastFuel, m_lastHitTime);
			m_lastFuelSent = m_lastFuel;
			m_radiusSent = m_radius;
			m_lastHitTimeSent = m_lastHitTime;
		}
	}

	private void UpdateShield()
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		float fuel = GetFuel();
		m_enabledObject?.SetActive(fuel > 0f);
		m_disabledObject?.SetActive(fuel <= 0f);
		_ = m_radius;
		m_lastFuel = fuel / (float)m_maxFuel;
		float radiusTarget = m_radiusTarget;
		m_radiusTarget = m_minShieldRadius + m_lastFuel * (m_maxShieldRadius - m_minShieldRadius);
		Color domeColor = ShieldDomeImageEffect.GetDomeColor(m_lastFuel);
		ParticleSystem[] energyParticles = m_energyParticles;
		foreach (ParticleSystem obj in energyParticles)
		{
			ParticleSystem.MainModule main = obj.main;
			main.startColor = domeColor;
			ParticleSystem.EmissionModule emission = obj.emission;
			emission.rateOverTime = m_lastFuel * 5f;
		}
		m_energyParticlesFlare.customData.SetColor(ParticleSystemCustomData.Custom1, domeColor * Mathf.Pow(m_lastFuel, 0.5f));
		Light[] coloredLights = m_coloredLights;
		for (int i = 0; i < coloredLights.Length; i++)
		{
			coloredLights[i].color = domeColor;
		}
		m_propertyBlock.SetColor(s_emissiveProperty, domeColor * 2f);
		MeshRenderer[] meshRenderers = m_meshRenderers;
		for (int i = 0; i < meshRenderers.Length; i++)
		{
			meshRenderers[i].SetPropertyBlock(m_propertyBlock);
		}
		if (m_offWhenNoFuel)
		{
			if (fuel <= 0f)
			{
				m_radiusTarget = 0f;
				if (radiusTarget > 0f && m_nview.IsOwner())
				{
					m_shieldStop.Create(m_shieldDome.transform.position, m_shieldDome.transform.rotation);
				}
			}
			if (fuel > 0f && radiusTarget <= 0f && m_nview.IsOwner())
			{
				m_shieldStart.Create(m_shieldDome.transform.position, m_shieldDome.transform.rotation);
			}
		}
		if (m_shieldLowLoopFuelStart > 0f && m_nview.IsOwner())
		{
			Character.SetupContinuousEffect(base.transform, base.transform.position, m_lastFuel > 0f && m_lastFuel < m_shieldLowLoopFuelStart, m_shieldLowLoop, ref m_lowLoopInstances);
		}
		if (m_nview.IsOwner() && fuel >= (float)m_maxFuel && m_nview.GetZDO().GetLong(ZDOVars.s_startTime, 0L) <= 0)
		{
			DateTime time = ZNet.instance.GetTime();
			m_nview.GetZDO().Set(ZDOVars.s_startTime, time.Ticks);
		}
		UpdateAttackCharge();
	}

	public static void CheckProjectile(Projectile projectile)
	{
		if (!projectile.HasBeenOutsideShields)
		{
			int num = m_instances.Count;
			foreach (ShieldGenerator instance in m_instances)
			{
				if (Vector3.Distance(instance.m_shieldDome.transform.position, projectile.transform.position) < instance.m_radius || !CheckShield(instance))
				{
					num--;
				}
			}
			if (num == 0)
			{
				projectile.TriggerShieldsLeftFlag();
			}
		}
		else
		{
			foreach (ShieldGenerator instance2 in m_instances)
			{
				if (CheckShield(instance2) && Vector3.Distance(instance2.m_shieldDome.transform.position, projectile.m_startPoint) > instance2.m_radius && Vector3.Distance(instance2.m_shieldDome.transform.position, projectile.transform.position) < instance2.m_radius)
				{
					instance2.OnProjectileHit(projectile.gameObject);
				}
			}
		}
		ShieldCleanup();
	}

	public float GetFuelRatio()
	{
		return Mathf.Clamp01(m_lastFuel);
	}

	public static void CheckObjectInsideShield(Cinder zinder)
	{
		foreach (ShieldGenerator instance in m_instances)
		{
			if (CheckShield(instance) && Vector3.Distance(instance.m_shieldDome.transform.position, zinder.transform.position) < instance.m_radius)
			{
				instance.OnProjectileHit(zinder.gameObject);
			}
		}
		ShieldCleanup();
	}

	public static bool IsInsideShield(Vector3 point)
	{
		foreach (ShieldGenerator instance in m_instances)
		{
			if (CheckShield(instance) && (bool)instance && (bool)instance.m_shieldDome && Vector3.Distance(instance.m_shieldDome.transform.position, point) < instance.m_radius)
			{
				return true;
			}
		}
		ShieldCleanup();
		return false;
	}

	public static bool IsInsideMaxShield(Vector3 point)
	{
		foreach (ShieldGenerator instance in m_instances)
		{
			if (CheckShield(instance) && (bool)instance && (bool)instance.m_shieldDome && Vector3.Distance(instance.m_shieldDome.transform.position, point) < instance.m_maxShieldRadius)
			{
				return true;
			}
		}
		ShieldCleanup();
		return false;
	}

	public static bool IsInsideShieldCached(Vector3 point, ref int changeID)
	{
		if (Mathf.Abs(changeID) <= m_instanceChangeID)
		{
			if (!IsInsideMaxShield(point))
			{
				changeID = -m_instanceChangeID;
				return false;
			}
			changeID = m_instanceChangeID;
			if (IsInsideShield(point))
			{
				return true;
			}
		}
		if (changeID > 0 && IsInsideShield(point))
		{
			return true;
		}
		return false;
	}

	private static bool CheckShield(ShieldGenerator shield)
	{
		if (!shield || !shield.m_shieldDome)
		{
			s_cleanShields = true;
			return false;
		}
		return true;
	}

	private static void ShieldCleanup()
	{
		if (s_cleanShields)
		{
			int num = m_instances.RemoveAll((ShieldGenerator x) => x == null || x.m_shieldDome == null);
			if (num > 0)
			{
				ZLog.LogWarning($"Removed {num} invalid shield instances. Some shields may be broken?");
			}
			s_cleanShields = false;
		}
	}

	public void OnProjectileHit(GameObject obj)
	{
		Vector3 position = obj.transform.position;
		Projectile component = obj.GetComponent<Projectile>();
		component?.OnHit(null, position, water: false, -obj.transform.forward);
		ZNetScene.instance.Destroy(obj.gameObject);
		if (m_fuelPerDamage > 0f)
		{
			float num = m_fuelPerDamage * (component ? component.m_damage.GetTotalDamage() : 10f);
			SetFuel(GetFuel() - num);
		}
		m_nview.InvokeRPC(ZNetView.Everybody, "RPC_HitNow");
		m_shieldHitEffects.Create(position, Quaternion.LookRotation(base.transform.position.DirTo(position)));
		UpdateShield();
	}

	private string OnHoverAddFuel()
	{
		float fuel = GetFuel();
		return Localization.instance.Localize($"{m_name} ({Mathf.Ceil(fuel)}/{m_maxFuel})\n[<color=yellow><b>$KEY_Use</b></color>] {m_add}");
	}

	public static bool HasShields()
	{
		if (m_instances == null)
		{
			return false;
		}
		foreach (ShieldGenerator instance in m_instances)
		{
			if (instance.m_lastFuel > 0f)
			{
				return true;
			}
		}
		return false;
	}

	private static float SDFSmoothMin(float a, float b, float k)
	{
		k *= 6f;
		float num = Mathf.Max(k - Mathf.Abs(a - b), 0f) / k;
		return Mathf.Min(a, b) - num * num * num * k * (1f / 6f);
	}

	public static Vector3 DirectionToShieldWall(Vector3 pos)
	{
		float num = 0.001f;
		return -Vector3.Normalize(new Vector3(DistanceToShieldWall(pos + new Vector3(0f, num, 0f)), DistanceToShieldWall(pos + new Vector3(0f, 0f, num)), DistanceToShieldWall(pos + new Vector3(num, 0f, 0f))));
	}

	public static float DistanceToShieldWall(Vector3 pos)
	{
		float num = float.PositiveInfinity;
		foreach (ShieldGenerator instance in m_instances)
		{
			if (instance.m_lastFuel != 0f)
			{
				float b = Vector3.Distance(instance.transform.position, pos) - instance.m_radius;
				num = SDFSmoothMin(num, b, ShieldDomeImageEffect.Smoothing);
			}
		}
		return num;
	}

	public static Vector3 GetClosestShieldPoint(Vector3 pos)
	{
		float num = DistanceToShieldWall(pos);
		Vector3 vector = DirectionToShieldWall(pos);
		return pos + vector * num;
	}

	public static ShieldGenerator GetClosestShieldGenerator(Vector3 pos, bool ignoreRadius = false)
	{
		ShieldGenerator result = null;
		float num = float.PositiveInfinity;
		foreach (ShieldGenerator instance in m_instances)
		{
			float num2 = (ignoreRadius ? 0f : instance.m_radius);
			float num3 = Mathf.Abs(Vector3.Distance(instance.transform.position, pos) - num2);
			if (num3 < num)
			{
				num = num3;
				result = instance;
			}
		}
		return result;
	}

	public bool TryGetItems(Player player, out List<string> items)
	{
		items = new List<string>();
		if (!CanUseItems(player))
		{
			return true;
		}
		items = m_fuelItems.Select((ItemDrop item) => item.m_itemData.m_shared.m_name).ToList();
		return true;
	}

	public bool CanUseItems(Player player, bool sendErrorMessage = true)
	{
		if (GetFuel() > (float)(m_maxFuel - 1))
		{
			player.Message(MessageHud.MessageType.Center, "$msg_itsfull");
			return false;
		}
		if (m_fuelItems.Any((ItemDrop obj) => player.GetInventory().HaveItem(obj.m_itemData.m_shared.m_name)))
		{
			return true;
		}
		player.Message(MessageHud.MessageType.Center, "$msg_donthaveany $piece_shieldgenerator_fuelname");
		return false;
	}
}
using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class Ship : MonoBehaviour, IMonoUpdater
{
	public enum Speed
	{
		Stop,
		Back,
		Slow,
		Half,
		Full
	}

	private bool m_forwardPressed;

	private bool m_backwardPressed;

	private float m_sendRudderTime;

	private float m_ashDamageMsgTimer;

	public float m_ashDamageMsgTime = 10f;

	[Header("Objects")]
	public GameObject m_sailObject;

	public GameObject m_mastObject;

	public GameObject m_rudderObject;

	public ShipControlls m_shipControlls;

	public Transform m_controlGuiPos;

	public GameObject m_ashdamageEffects;

	[Header("Misc")]
	public BoxCollider m_floatCollider;

	public float m_waterLevelOffset;

	public float m_forceDistance = 1f;

	public float m_force = 0.5f;

	public float m_damping = 0.05f;

	public float m_dampingSideway = 0.05f;

	public float m_dampingForward = 0.01f;

	public float m_angularDamping = 0.01f;

	public float m_disableLevel = -0.5f;

	public float m_sailForceOffset;

	public float m_sailForceFactor = 0.1f;

	public float m_rudderSpeed = 0.5f;

	public float m_stearForceOffset = -10f;

	public float m_stearForce = 0.5f;

	public float m_stearVelForceFactor = 0.1f;

	public float m_backwardForce = 50f;

	public float m_rudderRotationMax = 30f;

	public float m_minWaterImpactForce = 2.5f;

	public float m_minWaterImpactInterval = 2f;

	public float m_waterImpactDamage = 10f;

	public float m_upsideDownDmgInterval = 1f;

	public float m_upsideDownDmg = 20f;

	public EffectList m_waterImpactEffect = new EffectList();

	public bool m_ashlandsReady;

	private bool m_sailWasInPosition;

	private Vector3 m_windChangeVelocity = Vector3.zero;

	private Speed m_speed;

	private float m_rudder;

	private float m_rudderValue;

	private Vector3 m_sailForce = Vector3.zero;

	private readonly List<Player> m_players = new List<Player>();

	private List<AudioSource> m_ashlandsFxAudio;

	private WaterVolume m_previousCenter;

	private WaterVolume m_previousLeft;

	private WaterVolume m_previousRight;

	private WaterVolume m_previousForward;

	private WaterVolume m_previousBack;

	private static readonly List<Ship> s_currentShips = new List<Ship>();

	private GlobalWind m_globalWind;

	private Rigidbody m_body;

	private ZNetView m_nview;

	private IDestructible m_destructible;

	private Cloth m_sailCloth;

	private float m_lastDepth = -9999f;

	private float m_lastWaterImpactTime;

	private float m_upsideDownDmgTimer;

	private float m_ashlandsDmgTimer;

	private float m_rudderPaddleTimer;

	private float m_lastUpdateWaterForceTime;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_body = GetComponent<Rigidbody>();
		m_destructible = GetComponent<IDestructible>();
		WearNTear component = GetComponent<WearNTear>();
		if ((bool)component)
		{
			component.m_onDestroyed = (Action)Delegate.Combine(component.m_onDestroyed, new Action(OnDestroyed));
		}
		if (m_nview.GetZDO() == null)
		{
			base.enabled = false;
		}
		m_body.maxDepenetrationVelocity = 2f;
		Heightmap.ForceGenerateAll();
		m_sailCloth = m_sailObject.GetComponentInChildren<Cloth>();
		if ((bool)m_sailCloth)
		{
			m_globalWind = m_sailCloth.gameObject.GetComponent<GlobalWind>();
		}
		if ((bool)m_ashdamageEffects)
		{
			m_ashdamageEffects.SetActive(value: false);
			m_ashlandsFxAudio = m_ashdamageEffects.GetComponentsInChildren<AudioSource>().ToList();
		}
	}

	private void OnEnable()
	{
		Instances.Add(this);
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public bool CanBeRemoved()
	{
		return m_players.Count == 0;
	}

	private void Start()
	{
		m_nview.Register("Stop", RPC_Stop);
		m_nview.Register("Forward", RPC_Forward);
		m_nview.Register("Backward", RPC_Backward);
		m_nview.Register<float>("Rudder", RPC_Rudder);
		InvokeRepeating("UpdateOwner", 2f, 2f);
	}

	private void PrintStats()
	{
		if (m_players.Count != 0)
		{
			ZLog.Log("Vel:" + m_body.linearVelocity.magnitude.ToString("0.0"));
		}
	}

	public void ApplyControlls(Vector3 dir)
	{
		bool flag = (double)dir.z > 0.5;
		bool flag2 = (double)dir.z < -0.5;
		if (flag && !m_forwardPressed)
		{
			Forward();
		}
		if (flag2 && !m_backwardPressed)
		{
			Backward();
		}
		float fixedDeltaTime = Time.fixedDeltaTime;
		float num = Mathf.Lerp(0.5f, 1f, Mathf.Abs(m_rudderValue));
		m_rudder = dir.x * num;
		m_rudderValue += m_rudder * m_rudderSpeed * fixedDeltaTime;
		m_rudderValue = Utils.Clamp(m_rudderValue, -1f, 1f);
		if (Time.time - m_sendRudderTime > 0.2f)
		{
			m_sendRudderTime = Time.time;
			m_nview.InvokeRPC("Rudder", m_rudderValue);
		}
		m_forwardPressed = flag;
		m_backwardPressed = flag2;
	}

	public void Forward()
	{
		m_nview.InvokeRPC("Forward");
	}

	public void Backward()
	{
		m_nview.InvokeRPC("Backward");
	}

	public void Rudder(float rudder)
	{
		m_nview.Invoke("Rudder", rudder);
	}

	private void RPC_Rudder(long sender, float value)
	{
		m_rudderValue = value;
	}

	public void Stop()
	{
		m_nview.InvokeRPC("Stop");
	}

	private void RPC_Stop(long sender)
	{
		m_speed = Speed.Stop;
	}

	private void RPC_Forward(long sender)
	{
		switch (m_speed)
		{
		case Speed.Stop:
			m_speed = Speed.Slow;
			break;
		case Speed.Slow:
			m_speed = Speed.Half;
			break;
		case Speed.Half:
			m_speed = Speed.Full;
			break;
		case Speed.Back:
			m_speed = Speed.Stop;
			break;
		case Speed.Full:
			break;
		}
	}

	private void RPC_Backward(long sender)
	{
		switch (m_speed)
		{
		case Speed.Stop:
			m_speed = Speed.Back;
			break;
		case Speed.Slow:
			m_speed = Speed.Stop;
			break;
		case Speed.Half:
			m_speed = Speed.Slow;
			break;
		case Speed.Full:
			m_speed = Speed.Half;
			break;
		case Speed.Back:
			break;
		}
	}

	public void CustomFixedUpdate(float fixedDeltaTime)
	{
		bool flag = HaveControllingPlayer();
		UpdateControlls(fixedDeltaTime);
		UpdateSail(fixedDeltaTime);
		UpdateRudder(fixedDeltaTime, flag);
		if ((bool)m_nview && !m_nview.IsOwner())
		{
			return;
		}
		UpdateUpsideDmg(fixedDeltaTime);
		TakeAshlandsDamage(fixedDeltaTime);
		if (m_players.Count == 0)
		{
			m_speed = Speed.Stop;
			m_rudderValue = 0f;
		}
		if (!flag && (m_speed == Speed.Slow || m_speed == Speed.Back))
		{
			m_speed = Speed.Stop;
		}
		Vector3 worldCenterOfMass = m_body.worldCenterOfMass;
		Transform obj = m_floatCollider.transform;
		Vector3 size = m_floatCollider.size;
		Vector3 position = obj.position;
		Vector3 forward = obj.forward;
		Vector3 right = obj.right;
		Vector3 vector = position + forward * size.z / 2f;
		Vector3 vector2 = position - forward * size.z / 2f;
		Vector3 vector3 = position - right * size.x / 2f;
		Vector3 vector4 = position + right * size.x / 2f;
		Transform obj2 = base.transform;
		Vector3 forward2 = obj2.forward;
		Vector3 right2 = obj2.right;
		float waterLevel = Floating.GetWaterLevel(worldCenterOfMass, ref m_previousCenter);
		float waterLevel2 = Floating.GetWaterLevel(vector3, ref m_previousLeft);
		float waterLevel3 = Floating.GetWaterLevel(vector4, ref m_previousRight);
		float waterLevel4 = Floating.GetWaterLevel(vector, ref m_previousForward);
		float waterLevel5 = Floating.GetWaterLevel(vector2, ref m_previousBack);
		float num = (waterLevel + waterLevel2 + waterLevel3 + waterLevel4 + waterLevel5) / 5f;
		float num2 = worldCenterOfMass.y - num - m_waterLevelOffset;
		if (!(num2 > m_disableLevel))
		{
			m_body.WakeUp();
			UpdateWaterForce(num2, Time.time);
			Vector3 vector5 = new Vector3(vector3.x, waterLevel2, vector3.z);
			Vector3 vector6 = new Vector3(vector4.x, waterLevel3, vector4.z);
			Vector3 vector7 = new Vector3(vector.x, waterLevel4, vector.z);
			Vector3 vector8 = new Vector3(vector2.x, waterLevel5, vector2.z);
			float num3 = fixedDeltaTime * 50f;
			Vector3 vector9 = m_body.linearVelocity;
			_ = vector9.magnitude;
			float num4 = Utils.Clamp01(Utils.Abs(num2) / m_forceDistance);
			Vector3 vector10 = m_force * num4 * Vector3.up;
			m_body.AddForceAtPosition(vector10 * (m_body.mass * num3), worldCenterOfMass, ForceMode.Impulse);
			float num5 = Vector3.Dot(vector9, forward2);
			float num6 = Vector3.Dot(vector9, right2);
			float num7 = vector9.y * vector9.y * Utils.Sign(vector9.y) * m_damping * num4;
			float num8 = num5 * num5 * Utils.Sign(num5) * m_dampingForward * num4;
			float num9 = num6 * num6 * Utils.Sign(num6) * m_dampingSideway * num4;
			vector9.y -= Utils.Clamp(num7, -1f, 1f);
			vector9 -= base.transform.forward * Utils.Clamp(num8, -1f, 1f);
			vector9 -= base.transform.right * Utils.Clamp(num9, -1f, 1f);
			if (vector9.magnitude > m_body.linearVelocity.magnitude)
			{
				vector9 = vector9.normalized * m_body.linearVelocity.magnitude;
			}
			if (m_players.Count == 0)
			{
				vector9.x *= 0.1f;
				vector9.z *= 0.1f;
			}
			m_body.linearVelocity = vector9;
			m_body.angularVelocity -= m_body.angularVelocity * (m_angularDamping * num4);
			float num10 = 0.15f;
			float num11 = 0.5f;
			float num12 = Utils.Clamp((vector7.y - vector.y) * num10, 0f - num11, num11);
			float num13 = Utils.Clamp((vector8.y - vector2.y) * num10, 0f - num11, num11);
			float num14 = Utils.Clamp((vector5.y - vector3.y) * num10, 0f - num11, num11);
			float num15 = Utils.Clamp((vector6.y - vector4.y) * num10, 0f - num11, num11);
			num12 = Utils.Sign(num12) * Utils.Abs(num12 * num12);
			num13 = Utils.Sign(num13) * Utils.Abs(num13 * num13);
			num14 = Utils.Sign(num14) * Utils.Abs(num14 * num14);
			num15 = Utils.Sign(num15) * Utils.Abs(num15 * num15);
			m_body.AddForceAtPosition(m_body.mass * num12 * num3 * Vector3.up, vector, ForceMode.Impulse);
			m_body.AddForceAtPosition(m_body.mass * num13 * num3 * Vector3.up, vector2, ForceMode.Impulse);
			m_body.AddForceAtPosition(m_body.mass * num14 * num3 * Vector3.up, vector3, ForceMode.Impulse);
			m_body.AddForceAtPosition(m_body.mass * num15 * num3 * Vector3.up, vector4, ForceMode.Impulse);
			float sailSize = 0f;
			if (m_speed == Speed.Full)
			{
				sailSize = 1f;
			}
			else if (m_speed == Speed.Half)
			{
				sailSize = 0.5f;
			}
			Vector3 sailForce = GetSailForce(sailSize, fixedDeltaTime);
			Vector3 position2 = worldCenterOfMass + base.transform.up * m_sailForceOffset;
			m_body.AddForceAtPosition(sailForce * m_body.mass, position2, ForceMode.Impulse);
			Vector3 position3 = base.transform.position + forward2 * m_stearForceOffset;
			float num16 = num5 * m_stearVelForceFactor;
			m_body.AddForceAtPosition(m_body.mass * num16 * (0f - m_rudderValue) * fixedDeltaTime * right2, position3, ForceMode.Impulse);
			Vector3 zero = Vector3.zero;
			switch (m_speed)
			{
			case Speed.Slow:
				zero += forward2 * (m_backwardForce * (1f - Utils.Abs(m_rudderValue)));
				break;
			case Speed.Back:
				zero += -forward2 * (m_backwardForce * (1f - Utils.Abs(m_rudderValue)));
				break;
			}
			if (m_speed == Speed.Back || m_speed == Speed.Slow)
			{
				float num17 = ((m_speed != Speed.Back) ? 1 : (-1));
				zero += base.transform.right * (m_stearForce * (0f - m_rudderValue) * num17);
			}
			m_body.AddForceAtPosition(zero * (m_body.mass * fixedDeltaTime), position3, ForceMode.Impulse);
			ApplyEdgeForce(fixedDeltaTime);
		}
	}

	private void UpdateUpsideDmg(float dt)
	{
		if (!(base.transform.up.y >= 0f))
		{
			m_upsideDownDmgTimer += dt;
			if (!(m_upsideDownDmgTimer <= m_upsideDownDmgInterval))
			{
				m_upsideDownDmgTimer = 0f;
				HitData hitData = new HitData();
				hitData.m_damage.m_blunt = m_upsideDownDmg;
				hitData.m_point = base.transform.position;
				hitData.m_dir = Vector3.up;
				m_destructible.Damage(hitData);
			}
		}
	}

	private void TakeAshlandsDamage(float dt)
	{
		if (m_ashlandsReady)
		{
			return;
		}
		float ashlandsOceanGradient = WorldGenerator.GetAshlandsOceanGradient(base.transform.position);
		if ((bool)m_ashdamageEffects)
		{
			if (ashlandsOceanGradient < 0f)
			{
				m_ashdamageEffects.SetActive(value: false);
				{
					foreach (AudioSource item in m_ashlandsFxAudio)
					{
						item.Stop();
					}
					return;
				}
			}
			m_ashdamageEffects.SetActive(value: true);
		}
		if (m_ashDamageMsgTimer <= 0f && (bool)ZoneSystem.instance && (bool)Player.m_localPlayer)
		{
			ZoneSystem.instance.SetGlobalKey(GlobalKeys.AshlandsOcean);
			m_ashDamageMsgTimer = m_ashDamageMsgTime;
		}
		else
		{
			m_ashDamageMsgTimer -= Time.fixedDeltaTime;
		}
		m_ashlandsDmgTimer += dt;
		if (!((double)m_ashlandsDmgTimer <= 1.0))
		{
			m_ashlandsDmgTimer = 0f;
			ashlandsOceanGradient = Utils.Clamp(ashlandsOceanGradient, 0f, 3f);
			HitData hitData = new HitData();
			hitData.m_damage.m_blunt = Mathf.Floor(Mathf.Lerp(1f, 30f, ashlandsOceanGradient));
			hitData.m_hitType = HitData.HitType.AshlandsOcean;
			hitData.m_point = base.transform.position;
			hitData.m_dir = Vector3.up;
			m_destructible.Damage(hitData);
		}
	}

	private Vector3 GetSailForce(float sailSize, float dt)
	{
		Vector3 windDir = EnvMan.instance.GetWindDir();
		float windIntensity = EnvMan.instance.GetWindIntensity();
		float num = Mathf.Lerp(0.25f, 1f, windIntensity);
		float windAngleFactor = GetWindAngleFactor();
		windAngleFactor *= num;
		Vector3 target = Vector3.Normalize(windDir + base.transform.forward) * (windAngleFactor * m_sailForceFactor * sailSize);
		m_sailForce = Vector3.SmoothDamp(m_sailForce, target, ref m_windChangeVelocity, 1f, 99f);
		return m_sailForce;
	}

	public float GetWindAngleFactor()
	{
		float num = Vector3.Dot(EnvMan.instance.GetWindDir(), -base.transform.forward);
		float num2 = Mathf.Lerp(0.7f, 1f, 1f - Utils.Abs(num));
		float num3 = 1f - Utils.LerpStep(0.75f, 0.8f, num);
		return num2 * num3;
	}

	private void UpdateWaterForce(float depth, float time)
	{
		float num = depth - m_lastDepth;
		float num2 = time - m_lastUpdateWaterForceTime;
		m_lastDepth = depth;
		m_lastUpdateWaterForceTime = time;
		float num3 = num / num2;
		if (!(num3 > 0f) && Utils.Abs(num3) > m_minWaterImpactForce && time - m_lastWaterImpactTime > m_minWaterImpactInterval)
		{
			m_lastWaterImpactTime = time;
			m_waterImpactEffect.Create(base.transform.position, base.transform.rotation);
			if (m_players.Count > 0)
			{
				HitData hitData = new HitData();
				hitData.m_damage.m_blunt = m_waterImpactDamage;
				hitData.m_point = base.transform.position;
				hitData.m_dir = Vector3.up;
				m_destructible.Damage(hitData);
			}
		}
	}

	private void ApplyEdgeForce(float dt)
	{
		float magnitude = base.transform.position.magnitude;
		float num = 10420f;
		if (magnitude > num)
		{
			Vector3 vector = Vector3.Normalize(base.transform.position);
			float num2 = Utils.LerpStep(num, 10500f, magnitude) * 8f;
			Vector3 vector2 = vector * num2;
			m_body.AddForce(vector2 * dt, ForceMode.VelocityChange);
		}
	}

	private void FixTilt()
	{
		float num = Mathf.Asin(base.transform.right.y);
		float num2 = Mathf.Asin(base.transform.forward.y);
		if (Utils.Abs(num) > MathF.PI / 6f)
		{
			if (num > 0f)
			{
				base.transform.RotateAround(base.transform.position, base.transform.forward, (0f - Time.fixedDeltaTime) * 20f);
			}
			else
			{
				base.transform.RotateAround(base.transform.position, base.transform.forward, Time.fixedDeltaTime * 20f);
			}
		}
		if (Utils.Abs(num2) > MathF.PI / 6f)
		{
			if (num2 > 0f)
			{
				base.transform.RotateAround(base.transform.position, base.transform.right, (0f - Time.fixedDeltaTime) * 20f);
			}
			else
			{
				base.transform.RotateAround(base.transform.position, base.transform.right, Time.fixedDeltaTime * 20f);
			}
		}
	}

	private void UpdateControlls(float dt)
	{
		if (m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_forward, (int)m_speed);
			m_nview.GetZDO().Set(ZDOVars.s_rudder, m_rudderValue);
			return;
		}
		m_speed = (Speed)m_nview.GetZDO().GetInt(ZDOVars.s_forward);
		if (Time.time - m_sendRudderTime > 1f)
		{
			m_rudderValue = m_nview.GetZDO().GetFloat(ZDOVars.s_rudder);
		}
	}

	public bool IsSailUp()
	{
		if (m_speed != Speed.Half)
		{
			return m_speed == Speed.Full;
		}
		return true;
	}

	private void UpdateSail(float dt)
	{
		UpdateSailSize(dt);
		Vector3 windDir = EnvMan.instance.GetWindDir();
		windDir = Vector3.Cross(Vector3.Cross(windDir, base.transform.up), base.transform.up);
		if (m_speed == Speed.Full || m_speed == Speed.Half)
		{
			float t = 0.5f + Vector3.Dot(base.transform.forward, windDir) * 0.5f;
			Quaternion to = Quaternion.LookRotation(-Vector3.Lerp(windDir, Vector3.Normalize(windDir - base.transform.forward), t), base.transform.up);
			m_mastObject.transform.rotation = Quaternion.RotateTowards(m_mastObject.transform.rotation, to, 30f * dt);
		}
		else if (m_speed == Speed.Back)
		{
			Quaternion quaternion = Quaternion.LookRotation(-base.transform.forward, base.transform.up);
			Quaternion to2 = Quaternion.LookRotation(-windDir, base.transform.up);
			to2 = Quaternion.RotateTowards(quaternion, to2, 80f);
			m_mastObject.transform.rotation = Quaternion.RotateTowards(m_mastObject.transform.rotation, to2, 30f * dt);
		}
	}

	private void UpdateRudder(float dt, bool haveControllingPlayer)
	{
		if (!m_rudderObject)
		{
			return;
		}
		Quaternion b = Quaternion.Euler(0f, m_rudderRotationMax * (0f - m_rudderValue), 0f);
		if (haveControllingPlayer)
		{
			if (m_speed == Speed.Slow)
			{
				m_rudderPaddleTimer += dt;
				b *= Quaternion.Euler(0f, Mathf.Sin(m_rudderPaddleTimer * 6f) * 20f, 0f);
			}
			else if (m_speed == Speed.Back)
			{
				m_rudderPaddleTimer += dt;
				b *= Quaternion.Euler(0f, Mathf.Sin(m_rudderPaddleTimer * -3f) * 40f, 0f);
			}
		}
		m_rudderObject.transform.localRotation = Quaternion.Slerp(m_rudderObject.transform.localRotation, b, 0.5f);
	}

	private void UpdateSailSize(float dt)
	{
		float num = 0f;
		switch (m_speed)
		{
		case Speed.Back:
			num = 0.1f;
			break;
		case Speed.Half:
			num = 0.5f;
			break;
		case Speed.Full:
			num = 1f;
			break;
		case Speed.Slow:
			num = 0.1f;
			break;
		case Speed.Stop:
			num = 0.1f;
			break;
		}
		Vector3 localScale = m_sailObject.transform.localScale;
		bool flag = Utils.Abs(localScale.y - num) < 0.01f;
		if (!flag)
		{
			localScale.y = Mathf.MoveTowards(localScale.y, num, dt);
			m_sailObject.transform.localScale = localScale;
		}
		if ((bool)m_sailCloth)
		{
			if (m_speed == Speed.Stop || m_speed == Speed.Slow || m_speed == Speed.Back)
			{
				if (flag && m_sailCloth.enabled)
				{
					m_sailCloth.enabled = false;
				}
			}
			else if (flag)
			{
				if (!m_sailWasInPosition)
				{
					Utils.RecreateComponent(ref m_sailCloth);
					if ((bool)m_globalWind)
					{
						m_globalWind.UpdateClothReference(m_sailCloth);
					}
				}
			}
			else
			{
				m_sailCloth.enabled = true;
			}
		}
		m_sailWasInPosition = flag;
	}

	private void UpdateOwner()
	{
		if (m_nview.IsValid() && m_nview.IsOwner() && !(Player.m_localPlayer == null) && m_players.Count > 0 && !IsPlayerInBoat(Player.m_localPlayer))
		{
			RefreshPlayerList();
			long newOwnerID = GetNewOwnerID();
			m_nview.GetZDO().SetOwner(newOwnerID);
			ZLog.Log("Changing ship owner to " + newOwnerID);
		}
	}

	private long GetNewOwnerID()
	{
		long num = 0L;
		for (int i = 0; i < m_players.Count; i++)
		{
			num = m_players[i].GetOwner();
			if (num != 0L)
			{
				break;
			}
		}
		if (num == 0L)
		{
			num = ZDOMan.GetSessionID();
		}
		return num;
	}

	private void RefreshPlayerList()
	{
		for (int i = 0; i < m_players.Count; i++)
		{
			if (m_players[i].GetOwner() == 0L)
			{
				m_players.RemoveAt(i);
			}
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		Player component = collider.GetComponent<Player>();
		if ((bool)component)
		{
			m_players.Add(component);
			ZLog.Log("Player onboard, total onboard " + m_players.Count);
			if (component == Player.m_localPlayer)
			{
				s_currentShips.Add(this);
			}
		}
		Character component2 = collider.GetComponent<Character>();
		if ((bool)component2)
		{
			component2.InNumShipVolumes++;
		}
	}

	private void OnTriggerExit(Collider collider)
	{
		Player component = collider.GetComponent<Player>();
		if ((bool)component)
		{
			m_players.Remove(component);
			ZLog.Log("Player over board, players left " + m_players.Count);
			if (component == Player.m_localPlayer)
			{
				s_currentShips.Remove(this);
			}
		}
		Character component2 = collider.GetComponent<Character>();
		if ((bool)component2)
		{
			component2.InNumShipVolumes--;
		}
	}

	public bool IsPlayerInBoat(ZDOID zdoid)
	{
		foreach (Player player in m_players)
		{
			if (player.GetZDOID() == zdoid)
			{
				return true;
			}
		}
		return false;
	}

	public bool IsPlayerInBoat(Player player)
	{
		return m_players.Contains(player);
	}

	public bool IsPlayerInBoat(long playerID)
	{
		foreach (Player player in m_players)
		{
			if (player.GetPlayerID() == playerID)
			{
				return true;
			}
		}
		return false;
	}

	public bool HasPlayerOnboard()
	{
		return m_players.Count > 0;
	}

	private void OnDestroyed()
	{
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			Gogan.LogEvent("Game", "ShipDestroyed", base.gameObject.name, 0L);
		}
		s_currentShips.Remove(this);
	}

	public bool IsWindControllActive()
	{
		foreach (Player player in m_players)
		{
			if (player.GetSEMan().HaveStatusAttribute(StatusEffect.StatusAttribute.SailingPower))
			{
				return true;
			}
		}
		return false;
	}

	public static Ship GetLocalShip()
	{
		if (s_currentShips.Count != 0)
		{
			return s_currentShips[s_currentShips.Count - 1];
		}
		return null;
	}

	private bool HaveControllingPlayer()
	{
		if (m_players.Count != 0)
		{
			return m_shipControlls.HaveValidUser();
		}
		return false;
	}

	public bool IsOwner()
	{
		if (m_nview.IsValid())
		{
			return m_nview.IsOwner();
		}
		return false;
	}

	public float GetSpeed()
	{
		return Vector3.Dot(m_body.linearVelocity, base.transform.forward);
	}

	public Speed GetSpeedSetting()
	{
		return m_speed;
	}

	public float GetRudder()
	{
		return m_rudder;
	}

	public float GetRudderValue()
	{
		return m_rudderValue;
	}

	public float GetShipYawAngle()
	{
		Camera mainCamera = Utils.GetMainCamera();
		if (mainCamera == null)
		{
			return 0f;
		}
		return 0f - Utils.YawFromDirection(mainCamera.transform.InverseTransformDirection(base.transform.forward));
	}

	public float GetWindAngle()
	{
		Vector3 windDir = EnvMan.instance.GetWindDir();
		return 0f - Utils.YawFromDirection(base.transform.InverseTransformDirection(windDir));
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.red;
		Gizmos.DrawWireSphere(base.transform.position + base.transform.forward * m_stearForceOffset, 0.25f);
		Gizmos.color = Color.yellow;
		Gizmos.DrawWireSphere(base.transform.position + base.transform.up * m_sailForceOffset, 0.25f);
	}
}
using System;
using UnityEngine;

public class ShipConstructor : MonoBehaviour
{
	public GameObject m_shipPrefab;

	public GameObject m_hideWhenConstructed;

	public Transform m_spawnPoint;

	public long m_constructionTimeMinutes = 1L;

	private ZNetView m_nview;

	private void Start()
	{
		m_nview = GetComponent<ZNetView>();
		if (!(m_nview == null) && m_nview.GetZDO() != null)
		{
			if (m_nview.IsOwner() && m_nview.GetZDO().GetLong(ZDOVars.s_spawnTime, 0L) == 0L)
			{
				m_nview.GetZDO().Set(ZDOVars.s_spawnTime, ZNet.instance.GetTime().Ticks);
			}
			InvokeRepeating("UpdateConstruction", 5f, 1f);
			if (IsBuilt())
			{
				m_hideWhenConstructed.SetActive(value: false);
			}
		}
	}

	private bool IsBuilt()
	{
		return m_nview.GetZDO().GetBool(ZDOVars.s_done);
	}

	private void UpdateConstruction()
	{
		if (!m_nview.IsOwner())
		{
			return;
		}
		if (IsBuilt())
		{
			m_hideWhenConstructed.SetActive(value: false);
			return;
		}
		DateTime time = ZNet.instance.GetTime();
		DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_spawnTime, 0L));
		if ((time - dateTime).TotalMinutes > (double)m_constructionTimeMinutes)
		{
			m_hideWhenConstructed.SetActive(value: false);
			UnityEngine.Object.Instantiate(m_shipPrefab, m_spawnPoint.position, m_spawnPoint.rotation);
			m_nview.GetZDO().Set(ZDOVars.s_done, value: true);
		}
	}
}
using UnityEngine;

public class ShipControlls : MonoBehaviour, Interactable, Hoverable, IDoodadController
{
	public string m_hoverText = "";

	public Ship m_ship;

	public float m_maxUseRange = 10f;

	public Transform m_attachPoint;

	public Vector3 m_detachOffset = new Vector3(0f, 0.5f, 0f);

	public string m_attachAnimation = "attach_chair";

	private ZNetView m_nview;

	private void Awake()
	{
		m_nview = m_ship.GetComponent<ZNetView>();
		m_nview.Register<long>("RequestControl", RPC_RequestControl);
		m_nview.Register<long>("ReleaseControl", RPC_ReleaseControl);
		m_nview.Register<bool>("RequestRespons", RPC_RequestRespons);
	}

	public bool IsValid()
	{
		return this;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	public bool Interact(Humanoid character, bool repeat, bool alt)
	{
		if (repeat)
		{
			return false;
		}
		if (!m_nview.IsValid())
		{
			return false;
		}
		if (!InUseDistance(character))
		{
			return false;
		}
		Player player = character as Player;
		if (player == null || player.IsEncumbered())
		{
			return false;
		}
		if (player.GetStandingOnShip() != m_ship)
		{
			return false;
		}
		m_nview.InvokeRPC("RequestControl", player.GetPlayerID());
		return false;
	}

	public Component GetControlledComponent()
	{
		return m_ship;
	}

	public Vector3 GetPosition()
	{
		return base.transform.position;
	}

	public void ApplyControlls(Vector3 moveDir, Vector3 lookDir, bool run, bool autoRun, bool block)
	{
		m_ship.ApplyControlls(moveDir);
	}

	public string GetHoverText()
	{
		if (!InUseDistance(Player.m_localPlayer))
		{
			return Localization.instance.Localize("<color=#888888>$piece_toofar</color>");
		}
		return Localization.instance.Localize("[<color=yellow><b>$KEY_Use</b></color>] " + m_hoverText);
	}

	public string GetHoverName()
	{
		return Localization.instance.Localize(m_hoverText);
	}

	private void RPC_RequestControl(long sender, long playerID)
	{
		if (m_nview.IsOwner() && m_ship.IsPlayerInBoat(playerID))
		{
			if (GetUser() == playerID || !HaveValidUser())
			{
				m_nview.GetZDO().Set(ZDOVars.s_user, playerID);
				m_nview.InvokeRPC(sender, "RequestRespons", true);
			}
			else
			{
				m_nview.InvokeRPC(sender, "RequestRespons", false);
			}
		}
	}

	private void RPC_ReleaseControl(long sender, long playerID)
	{
		if (m_nview.IsOwner() && GetUser() == playerID)
		{
			m_nview.GetZDO().Set(ZDOVars.s_user, 0L);
		}
	}

	private void RPC_RequestRespons(long sender, bool granted)
	{
		if (!Player.m_localPlayer)
		{
			return;
		}
		if (granted)
		{
			Player.m_localPlayer.StartDoodadControl(this);
			if (m_attachPoint != null)
			{
				Player.m_localPlayer.AttachStart(m_attachPoint, null, hideWeapons: false, isBed: false, onShip: true, m_attachAnimation, m_detachOffset);
			}
		}
		else
		{
			Player.m_localPlayer.Message(MessageHud.MessageType.Center, "$msg_inuse");
		}
	}

	public void OnUseStop(Player player)
	{
		if (m_nview.IsValid())
		{
			m_nview.InvokeRPC("ReleaseControl", player.GetPlayerID());
			if (m_attachPoint != null)
			{
				player.AttachStop();
			}
		}
	}

	public bool HaveValidUser()
	{
		long user = GetUser();
		if (user != 0L)
		{
			return m_ship.IsPlayerInBoat(user);
		}
		return false;
	}

	private long GetUser()
	{
		if (!m_nview.IsValid())
		{
			return 0L;
		}
		return m_nview.GetZDO().GetLong(ZDOVars.s_user, 0L);
	}

	private bool InUseDistance(Humanoid human)
	{
		return Vector3.Distance(human.transform.position, m_attachPoint.position) < m_maxUseRange;
	}
}
using System.Collections.Generic;
using UnityEngine;

public class ShipEffects : MonoBehaviour, IMonoUpdater
{
	public Transform m_shadow;

	public float m_offset = 0.01f;

	public float m_minimumWakeVel = 5f;

	public GameObject m_speedWakeRoot;

	public GameObject m_wakeSoundRoot;

	public GameObject m_inWaterSoundRoot;

	public float m_audioFadeDuration = 2f;

	public AudioSource m_sailSound;

	public float m_sailFadeDuration = 1f;

	public GameObject m_splashEffects;

	private ParticleSystem[] m_wakeParticles;

	private float m_sailBaseVol = 1f;

	private readonly List<KeyValuePair<AudioSource, float>> m_wakeSounds = new List<KeyValuePair<AudioSource, float>>();

	private readonly List<KeyValuePair<AudioSource, float>> m_inWaterSounds = new List<KeyValuePair<AudioSource, float>>();

	private WaterVolume m_previousWaterVolume;

	private Rigidbody m_body;

	private Ship m_ship;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		ZNetView componentInParent = GetComponentInParent<ZNetView>();
		if ((bool)componentInParent && componentInParent.GetZDO() == null)
		{
			base.enabled = false;
			return;
		}
		m_body = GetComponentInParent<Rigidbody>();
		m_ship = GetComponentInParent<Ship>();
		if ((bool)m_speedWakeRoot)
		{
			m_wakeParticles = m_speedWakeRoot.GetComponentsInChildren<ParticleSystem>();
		}
		if ((bool)m_wakeSoundRoot)
		{
			AudioSource[] componentsInChildren = m_wakeSoundRoot.GetComponentsInChildren<AudioSource>();
			foreach (AudioSource audioSource in componentsInChildren)
			{
				audioSource.pitch = Random.Range(0.9f, 1.1f);
				m_wakeSounds.Add(new KeyValuePair<AudioSource, float>(audioSource, audioSource.volume));
			}
		}
		if ((bool)m_inWaterSoundRoot)
		{
			AudioSource[] componentsInChildren = m_inWaterSoundRoot.GetComponentsInChildren<AudioSource>();
			foreach (AudioSource audioSource2 in componentsInChildren)
			{
				audioSource2.pitch = Random.Range(0.9f, 1.1f);
				m_inWaterSounds.Add(new KeyValuePair<AudioSource, float>(audioSource2, audioSource2.volume));
			}
		}
		if ((bool)m_sailSound)
		{
			m_sailBaseVol = m_sailSound.volume;
			m_sailSound.pitch = Random.Range(0.9f, 1.1f);
		}
	}

	private void OnEnable()
	{
		Instances.Add(this);
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public void CustomLateUpdate(float deltaTime)
	{
		if (!Floating.IsUnderWater(base.transform.position, ref m_previousWaterVolume))
		{
			m_shadow.gameObject.SetActive(value: false);
			SetWake(enabled: false, deltaTime);
			FadeSounds(m_inWaterSounds, enabled: false, deltaTime);
			return;
		}
		m_shadow.gameObject.SetActive(value: true);
		bool flag = m_body.linearVelocity.magnitude > m_minimumWakeVel;
		FadeSounds(m_inWaterSounds, enabled: true, deltaTime);
		SetWake(flag, deltaTime);
		if ((bool)m_sailSound)
		{
			float target = (m_ship.IsSailUp() ? m_sailBaseVol : 0f);
			FadeSound(m_sailSound, target, m_sailFadeDuration, deltaTime);
		}
		if (m_splashEffects != null)
		{
			m_splashEffects.SetActive(m_ship.HasPlayerOnboard());
		}
	}

	private void SetWake(bool enabled, float dt)
	{
		ParticleSystem[] wakeParticles = m_wakeParticles;
		for (int i = 0; i < wakeParticles.Length; i++)
		{
			ParticleSystem.EmissionModule emission = wakeParticles[i].emission;
			emission.enabled = enabled;
		}
		FadeSounds(m_wakeSounds, enabled, dt);
	}

	private void FadeSounds(List<KeyValuePair<AudioSource, float>> sources, bool enabled, float dt)
	{
		foreach (KeyValuePair<AudioSource, float> source in sources)
		{
			if (enabled)
			{
				FadeSound(source.Key, source.Value, m_audioFadeDuration, dt);
			}
			else
			{
				FadeSound(source.Key, 0f, m_audioFadeDuration, dt);
			}
		}
	}

	private static void FadeSound(AudioSource source, float target, float fadeDuration, float dt)
	{
		float maxDelta = dt / fadeDuration;
		if (target > 0f)
		{
			if (!source.isPlaying)
			{
				source.Play();
			}
			source.volume = Mathf.MoveTowards(source.volume, target, maxDelta);
		}
		else if (source.isPlaying)
		{
			source.volume = Mathf.MoveTowards(source.volume, 0f, maxDelta);
			if (source.volume <= 0f)
			{
				source.Stop();
			}
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

internal static class ShuffleClass
{
	private static System.Random rng = new System.Random();

	public static void Shuffle<T>(this IList<T> list, bool useUnityRandom = false)
	{
		int num = list.Count;
		while (num > 1)
		{
			num--;
			int index = (useUnityRandom ? UnityEngine.Random.Range(0, num) : rng.Next(num + 1));
			T value = list[index];
			list[index] = list[num];
			list[num] = value;
		}
	}
}
using System;
using System.Collections.Generic;
using Dynamics;
using UnityEngine;

public class SiegeMachine : MonoBehaviour
{
	[Serializable]
	public class SiegePart
	{
		public GameObject m_gameobject;

		public Transform m_effectPoint;

		[NonSerialized]
		public float m_position;

		[NonSerialized]
		public FloatDynamics m_floatDynamics;

		[NonSerialized]
		public float m_dynamicsPosition;

		[NonSerialized]
		public Vector3 m_originalPosition;
	}

	private enum AnimPhase
	{
		Charging,
		Firing
	}

	public Smelter m_engine;

	public Vagon m_wagon;

	public bool m_enabledWhenAttached = true;

	public List<SiegePart> m_movingParts = new List<SiegePart>();

	public DynamicsParameters m_dynamicsParameters;

	private ZNetView m_nview;

	private bool m_wasDisabledLastUpdate = true;

	public float m_chargeTime = 4f;

	public float m_hitDelay = 2f;

	public float m_chargeOffsetDistance = 2f;

	public AnimationCurve m_armAnimCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);

	public GameObject m_aoe;

	public EffectList m_punchEffect;

	public EffectList m_chargeEffect;

	private int m_currentPart;

	private float m_firingTimer;

	private float m_aoeActiveTimer;

	private AnimPhase m_animPhase;

	private void Awake()
	{
		foreach (SiegePart movingPart in m_movingParts)
		{
			movingPart.m_position = 0f;
			movingPart.m_originalPosition = movingPart.m_gameobject.transform.localPosition;
			movingPart.m_dynamicsPosition = 0f;
			movingPart.m_floatDynamics = new FloatDynamics(m_dynamicsParameters, movingPart.m_dynamicsPosition);
		}
		m_aoe.gameObject.SetActive(value: false);
		m_nview = GetComponent<ZNetView>();
		if (m_nview.GetZDO() == null)
		{
			base.enabled = false;
		}
	}

	private void Update()
	{
		if (m_nview.IsValid())
		{
			UpdateSiege(Time.deltaTime);
		}
	}

	private void UpdateAnimPhase()
	{
		m_currentPart = (m_currentPart + 1) % m_movingParts.Count;
		if (m_currentPart == 0)
		{
			m_animPhase = ((m_animPhase == AnimPhase.Charging) ? AnimPhase.Firing : AnimPhase.Charging);
		}
	}

	private void UpdateSiege(float dt)
	{
		bool flag = (object)m_nview != null && m_nview.IsValid() && m_nview.IsOwner();
		foreach (SiegePart movingPart in m_movingParts)
		{
			movingPart.m_dynamicsPosition = movingPart.m_floatDynamics.Update(dt, m_armAnimCurve.Evaluate(movingPart.m_position / m_chargeTime));
			movingPart.m_gameobject.transform.localPosition = Vector3.Lerp(movingPart.m_originalPosition, movingPart.m_originalPosition + Vector3.back * m_chargeOffsetDistance, movingPart.m_dynamicsPosition);
		}
		if (((bool)m_engine && !m_engine.IsActive()) || ((bool)m_wagon && (m_enabledWhenAttached ^ m_wagon.IsAttached())))
		{
			m_aoe.gameObject.SetActive(value: false);
			m_animPhase = AnimPhase.Charging;
			m_currentPart = 0;
			foreach (SiegePart movingPart2 in m_movingParts)
			{
				movingPart2.m_position = Mathf.MoveTowards(movingPart2.m_position, 0f, dt / 0.5f);
				if ((double)movingPart2.m_position < 0.02)
				{
					movingPart2.m_position = 0f;
				}
			}
			m_wasDisabledLastUpdate = true;
			return;
		}
		if (m_wasDisabledLastUpdate)
		{
			foreach (SiegePart movingPart3 in m_movingParts)
			{
				movingPart3.m_position = 0f;
			}
		}
		if (flag)
		{
			if (m_aoeActiveTimer > 0f)
			{
				m_aoeActiveTimer -= dt;
			}
			m_aoe.gameObject.SetActive(m_aoeActiveTimer >= 0f);
		}
		SiegePart siegePart = m_movingParts[m_currentPart];
		AnimPhase animPhase = m_animPhase;
		if (animPhase == AnimPhase.Charging || animPhase != AnimPhase.Firing)
		{
			if (siegePart.m_position == 0f && flag)
			{
				m_chargeEffect.Create(siegePart.m_gameobject.transform.position, Quaternion.identity);
			}
			siegePart.m_position += dt;
			if (siegePart.m_position >= m_chargeTime)
			{
				UpdateAnimPhase();
			}
		}
		else
		{
			m_firingTimer += dt;
			if (m_firingTimer > m_hitDelay)
			{
				m_firingTimer = 0f;
				Terminal.Log("Firing!");
				siegePart.m_position = 0f;
				if (flag)
				{
					m_punchEffect.Create(siegePart.m_effectPoint.position, siegePart.m_effectPoint.rotation);
					m_aoeActiveTimer = 0.05f;
					m_aoe.gameObject.SetActive(value: true);
				}
				UpdateAnimPhase();
			}
		}
		m_wasDisabledLastUpdate = false;
	}
}
using Splatform;
using TMPro;
using UnityEngine;
using UserManagement;

public class Sign : MonoBehaviour, Hoverable, Interactable, TextReceiver
{
	public TextMeshProUGUI m_textWidget;

	public string m_name = "Sign";

	public string m_defaultText = "Sign";

	public string m_writtenBy = "Written by";

	public int m_characterLimit = 50;

	private ZNetView m_nview;

	private bool m_isViewable = true;

	private string m_authorDisplayName = "";

	private PlatformUserID? m_author;

	private string m_currentText;

	private uint m_lastRevision = uint.MaxValue;

	private void Awake()
	{
		m_currentText = m_defaultText;
		m_nview = GetComponent<ZNetView>();
		if (m_nview.GetZDO() != null)
		{
			UpdateText();
			InvokeRepeating("UpdateText", 2f, 2f);
		}
	}

	public string GetHoverText()
	{
		string text = (m_isViewable ? ("\"" + GetText().RemoveRichTextTags() + "\"") : ((!m_author.HasValue || !MuteList.Contains(m_author.Value)) ? ("[" + Localization.instance.Localize("$text_hidden_notification_ugc_settings") + "]") : ("[" + Localization.instance.Localize("$text_hidden_notification_muted") + "]")));
		if (!PrivateArea.CheckAccess(base.transform.position, 0f, flash: false))
		{
			return text;
		}
		string text2 = "";
		return text + text2 + "\n" + Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_use");
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		if (!PrivateArea.CheckAccess(base.transform.position))
		{
			return false;
		}
		PrivilegeResult privilegeResult = PlatformManager.DistributionPlatform.PrivilegeProvider.CheckPrivilege(Privilege.ViewUserGeneratedContent);
		if (!privilegeResult.IsGranted())
		{
			if (PlatformManager.DistributionPlatform.UIProvider.ResolvePrivilege != null)
			{
				PlatformManager.DistributionPlatform.UIProvider.ResolvePrivilege.Open(Privilege.ViewUserGeneratedContent);
				if (!PlatformManager.DistributionPlatform.UIProvider.ResolvePrivilege.IsOpen)
				{
					ZLog.LogError(string.Format("{0} can't resolve the {1} privilege on this platform, which was denied with result {2}. Modifying sign text was blocked without meaningful feedback to the user!", "ResolvePrivilegeUI", Privilege.ViewUserGeneratedContent, privilegeResult));
				}
			}
			else
			{
				ZLog.LogError(string.Format("{0} is not available on this platform to resolve the {1} privilege, which was denied with result {2}. Modifying sign text was blocked without meaningful feedback to the user!", "ResolvePrivilegeUI", Privilege.ViewUserGeneratedContent, privilegeResult));
			}
			return false;
		}
		TextInput.instance.RequestText(this, "$piece_sign_input", m_characterLimit);
		return true;
	}

	private void UpdateText()
	{
		uint dataRevision = m_nview.GetZDO().DataRevision;
		if (m_lastRevision == dataRevision)
		{
			UpdateViewPermission();
			return;
		}
		m_lastRevision = dataRevision;
		string currentText = m_nview.GetZDO().GetString(ZDOVars.s_text, m_defaultText);
		m_currentText = currentText;
		m_authorDisplayName = m_nview.GetZDO().GetString(ZDOVars.s_authorDisplayName);
		string resolvedAuthor = m_nview.GetZDO().GetString(ZDOVars.s_author);
		if (m_nview.IsOwner() && RelationsManager.UpdateAuthorIfHost(resolvedAuthor, ref resolvedAuthor))
		{
			m_nview.GetZDO().Set(ZDOVars.s_author, resolvedAuthor);
		}
		if (string.IsNullOrEmpty(resolvedAuthor))
		{
			m_author = PlatformUserID.None;
		}
		else if (resolvedAuthor == "host")
		{
			m_author = null;
		}
		else
		{
			m_author = new PlatformUserID(resolvedAuthor);
		}
		UpdateViewPermission();
	}

	private void UpdateViewPermission()
	{
		if (!m_author.HasValue)
		{
			OnCheckPermissionCompleted(RelationsManagerPermissionResult.Denied);
		}
		if (m_author.Value.IsValid)
		{
			RelationsManager.CheckPermissionAsync(m_author.Value, Permission.ViewUserGeneratedContent, isSender: false, OnCheckPermissionCompleted);
		}
		else
		{
			OnCheckPermissionCompleted(RelationsManagerPermissionResult.Granted);
		}
	}

	private void OnCheckPermissionCompleted(RelationsManagerPermissionResult result)
	{
		if (result.IsGranted())
		{
			m_isViewable = true;
			if (result == RelationsManagerPermissionResult.GrantedRequiresFiltering)
			{
				CensorShittyWords.Filter(m_currentText, out var output);
				m_textWidget.text = output;
			}
			else
			{
				m_textWidget.text = m_currentText;
			}
		}
		else
		{
			m_isViewable = false;
			m_textWidget.text = "ᚬᛏᛁᛚᛚᚴᛅᚾᚴᛚᛁᚴ";
		}
	}

	public string GetText()
	{
		return m_textWidget.text;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	public void SetText(string text)
	{
		if (PrivateArea.CheckAccess(base.transform.position))
		{
			m_nview.ClaimOwnership();
			m_nview.GetZDO().Set(ZDOVars.s_text, text);
			PlatformUserID platformUserID = PlatformManager.DistributionPlatform.LocalUser.PlatformUserID;
			m_nview.GetZDO().Set(ZDOVars.s_author, PlatformManager.DistributionPlatform.LocalUser.IsSignedIn ? platformUserID.ToString() : "host");
			if (ZNet.TryGetServerAssignedDisplayName(platformUserID, out var displayName))
			{
				m_nview.GetZDO().Set(ZDOVars.s_authorDisplayName, displayName);
			}
			UpdateText();
		}
	}
}
