using System;
using System.Collections.Generic;
using UnityEngine;

public class Skills : MonoBehaviour
{
	public enum SkillType
	{
		None = 0,
		Swords = 1,
		Knives = 2,
		Clubs = 3,
		Polearms = 4,
		Spears = 5,
		Blocking = 6,
		Axes = 7,
		Bows = 8,
		ElementalMagic = 9,
		BloodMagic = 10,
		Unarmed = 11,
		Pickaxes = 12,
		WoodCutting = 13,
		Crossbows = 14,
		Jump = 100,
		Sneak = 101,
		Run = 102,
		Swim = 103,
		Fishing = 104,
		Cooking = 105,
		Farming = 106,
		Crafting = 107,
		Dodge = 108,
		Ride = 110,
		All = 999
	}

	[Serializable]
	public class SkillDef
	{
		public SkillType m_skill = SkillType.Swords;

		public Sprite m_icon;

		public string m_description = "";

		public float m_increseStep = 1f;
	}

	public class Skill
	{
		public SkillDef m_info;

		public float m_level;

		public float m_accumulator;

		public Skill(SkillDef info)
		{
			m_info = info;
		}

		public bool Raise(float factor)
		{
			if (m_level >= 100f)
			{
				return false;
			}
			float num = m_info.m_increseStep * factor * Game.m_skillGainRate;
			m_accumulator += num;
			float nextLevelRequirement = GetNextLevelRequirement();
			if (m_accumulator >= nextLevelRequirement)
			{
				m_level += 1f;
				m_level = Mathf.Clamp(m_level, 0f, 100f);
				m_accumulator = 0f;
				return true;
			}
			return false;
		}

		private float GetNextLevelRequirement()
		{
			return Mathf.Pow(Mathf.Floor(m_level + 1f), 1.5f) * 0.5f + 0.5f;
		}

		public float GetLevelPercentage()
		{
			if (m_level >= 100f)
			{
				return 0f;
			}
			float nextLevelRequirement = GetNextLevelRequirement();
			return Mathf.Clamp01(m_accumulator / nextLevelRequirement);
		}
	}

	private const int c_SaveFileDataVersion = 2;

	private const float c_RandomSkillRange = 0.15f;

	private const float c_RandomSkillMin = 0.4f;

	public const float c_MaxSkillLevel = 100f;

	public float m_DeathLowerFactor = 0.25f;

	public bool m_useSkillCap;

	public float m_totalSkillCap = 600f;

	public List<SkillDef> m_skills = new List<SkillDef>();

	private readonly Dictionary<SkillType, Skill> m_skillData = new Dictionary<SkillType, Skill>();

	private Player m_player;

	private static readonly SkillType[] s_allSkills = (SkillType[])Enum.GetValues(typeof(SkillType));

	public void Awake()
	{
		m_player = GetComponent<Player>();
	}

	public void Save(ZPackage pkg)
	{
		pkg.Write(2);
		pkg.Write(m_skillData.Count);
		foreach (KeyValuePair<SkillType, Skill> skillDatum in m_skillData)
		{
			pkg.Write((int)skillDatum.Value.m_info.m_skill);
			pkg.Write(skillDatum.Value.m_level);
			pkg.Write(skillDatum.Value.m_accumulator);
		}
	}

	public void Load(ZPackage pkg)
	{
		int num = pkg.ReadInt();
		m_skillData.Clear();
		int num2 = pkg.ReadInt();
		for (int i = 0; i < num2; i++)
		{
			SkillType skillType = (SkillType)pkg.ReadInt();
			float level = pkg.ReadSingle();
			float accumulator = ((num >= 2) ? pkg.ReadSingle() : 0f);
			if (IsSkillValid(skillType))
			{
				Skill skill = GetSkill(skillType);
				skill.m_level = level;
				skill.m_accumulator = accumulator;
			}
		}
	}

	private static bool IsSkillValid(SkillType type)
	{
		return Enum.IsDefined(typeof(SkillType), type);
	}

	public float GetSkillFactor(SkillType skillType)
	{
		if (skillType == SkillType.None)
		{
			return 0f;
		}
		return Mathf.Clamp01(GetSkillLevel(skillType) / 100f);
	}

	public float GetSkillLevel(SkillType skillType)
	{
		if (skillType == SkillType.None)
		{
			return 0f;
		}
		float level = GetSkill(skillType).m_level;
		m_player.GetSEMan().ModifySkillLevel(skillType, ref level);
		return Mathf.Floor(level);
	}

	public void GetRandomSkillRange(out float min, out float max, SkillType skillType)
	{
		float skillFactor = GetSkillFactor(skillType);
		float num = Mathf.Lerp(0.4f, 1f, skillFactor);
		min = Mathf.Clamp01(num - 0.15f);
		max = Mathf.Clamp01(num + 0.15f);
	}

	public float GetRandomSkillFactor(SkillType skillType)
	{
		float skillFactor = GetSkillFactor(skillType);
		float num = Mathf.Lerp(0.4f, 1f, skillFactor);
		float a = Mathf.Clamp01(num - 0.15f);
		float b = Mathf.Clamp01(num + 0.15f);
		return Mathf.Lerp(a, b, UnityEngine.Random.value);
	}

	public void CheatRaiseSkill(string name, float value, bool showMessage = true)
	{
		SkillType[] array;
		if (name.ToLower() == "all")
		{
			array = s_allSkills;
			for (int i = 0; i < array.Length; i++)
			{
				SkillType skillType = array[i];
				if (skillType != SkillType.All)
				{
					CheatRaiseSkill(skillType.ToString(), value, showMessage: false);
				}
			}
			if (showMessage)
			{
				m_player.Message(MessageHud.MessageType.TopLeft, $"All skills increased by {value}");
				Console.instance.Print($"All skills increased by {value}");
			}
			return;
		}
		array = s_allSkills;
		for (int i = 0; i < array.Length; i++)
		{
			SkillType skillType2 = array[i];
			if (skillType2.ToString().ToLower() == name.ToLower() && skillType2 != SkillType.All && skillType2 != SkillType.None)
			{
				Skill skill = GetSkill(skillType2);
				skill.m_level += value;
				skill.m_level = Mathf.Clamp(skill.m_level, 0f, 100f);
				if (m_useSkillCap)
				{
					RebalanceSkills(skillType2);
				}
				if (skill.m_info != null && showMessage)
				{
					m_player.Message(MessageHud.MessageType.TopLeft, $"Skill increased {skill.m_info.m_skill}: {(int)skill.m_level}", 0, skill.m_info.m_icon);
					Console.instance.Print($"Skill {skillType2} = {skill.m_level}");
				}
				return;
			}
		}
		Console.instance.Print("Skill not found " + name);
	}

	public void CheatResetSkill(string name)
	{
		SkillType[] array;
		if (name.ToLower() == "all")
		{
			array = s_allSkills;
			foreach (SkillType skillType in array)
			{
				if (skillType != SkillType.All)
				{
					ResetSkill(skillType);
				}
			}
			m_player.Message(MessageHud.MessageType.TopLeft, "All skills reset");
			Console.instance.Print("All skills reset");
			return;
		}
		array = s_allSkills;
		for (int i = 0; i < array.Length; i++)
		{
			SkillType skillType2 = array[i];
			if (skillType2.ToString().ToLower() == name.ToLower())
			{
				ResetSkill(skillType2);
				Console.instance.Print($"Skill {skillType2} reset");
				return;
			}
		}
		Console.instance.Print("Skill not found " + name);
	}

	public void ResetSkill(SkillType skillType)
	{
		m_skillData.Remove(skillType);
	}

	public void RaiseSkill(SkillType skillType, float factor = 1f)
	{
		if (skillType == SkillType.None)
		{
			return;
		}
		Skill skill = GetSkill(skillType);
		float level = skill.m_level;
		if (skill.Raise(factor))
		{
			if (m_useSkillCap)
			{
				RebalanceSkills(skillType);
			}
			m_player.OnSkillLevelup(skillType, skill.m_level);
			MessageHud.MessageType type = (((int)level != 0) ? MessageHud.MessageType.TopLeft : MessageHud.MessageType.Center);
			m_player.Message(type, "$msg_skillup $skill_" + skill.m_info.m_skill.ToString().ToLower() + ": " + (int)skill.m_level, 0, skill.m_info.m_icon);
			Gogan.LogEvent("Game", "Levelup", skillType.ToString(), (int)skill.m_level);
		}
	}

	private void RebalanceSkills(SkillType skillType)
	{
		if (GetTotalSkill() < m_totalSkillCap)
		{
			return;
		}
		float level = GetSkill(skillType).m_level;
		float num = m_totalSkillCap - level;
		float num2 = 0f;
		foreach (KeyValuePair<SkillType, Skill> skillDatum in m_skillData)
		{
			if (skillDatum.Key != skillType)
			{
				num2 += skillDatum.Value.m_level;
			}
		}
		foreach (KeyValuePair<SkillType, Skill> skillDatum2 in m_skillData)
		{
			if (skillDatum2.Key != skillType)
			{
				skillDatum2.Value.m_level = skillDatum2.Value.m_level / num2 * num;
			}
		}
	}

	public void Clear()
	{
		m_skillData.Clear();
	}

	public void OnDeath()
	{
		LowerAllSkills(m_DeathLowerFactor * Game.m_skillReductionRate);
	}

	public void LowerAllSkills(float factor)
	{
		foreach (KeyValuePair<SkillType, Skill> skillDatum in m_skillData)
		{
			float num = skillDatum.Value.m_level * factor;
			skillDatum.Value.m_level -= num;
			skillDatum.Value.m_accumulator = 0f;
		}
		m_player.Message(MessageHud.MessageType.TopLeft, "$msg_skills_lowered");
	}

	private Skill GetSkill(SkillType skillType)
	{
		if (m_skillData.TryGetValue(skillType, out var value))
		{
			return value;
		}
		value = new Skill(GetSkillDef(skillType));
		m_skillData.Add(skillType, value);
		return value;
	}

	private SkillDef GetSkillDef(SkillType type)
	{
		foreach (SkillDef skill in m_skills)
		{
			if (skill.m_skill == type)
			{
				return skill;
			}
		}
		return null;
	}

	public List<Skill> GetSkillList()
	{
		List<Skill> list = new List<Skill>();
		foreach (KeyValuePair<SkillType, Skill> skillDatum in m_skillData)
		{
			list.Add(skillDatum.Value);
		}
		return list;
	}

	public float GetTotalSkill()
	{
		float num = 0f;
		foreach (KeyValuePair<SkillType, Skill> skillDatum in m_skillData)
		{
			num += skillDatum.Value.m_level;
		}
		return num;
	}

	public float GetTotalSkillCap()
	{
		return m_totalSkillCap;
	}
}
using System;
using System.Collections;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public class SkillsDialog : MonoBehaviour
{
	public RectTransform m_listRoot;

	[SerializeField]
	private ScrollRect skillListScrollRect;

	[SerializeField]
	private Scrollbar scrollbar;

	public RectTransform m_tooltipAnchor;

	public GameObject m_elementPrefab;

	public TMP_Text m_totalSkillText;

	public float m_spacing = 80f;

	public float m_inputDelay = 0.1f;

	private int m_selectionIndex;

	private float m_inputDelayTimer;

	private float m_baseListSize;

	private readonly List<GameObject> m_elements = new List<GameObject>();

	private void Awake()
	{
		m_baseListSize = m_listRoot.rect.height;
	}

	private IEnumerator SelectFirstEntry()
	{
		yield return null;
		yield return null;
		if (m_elements.Count > 0)
		{
			m_selectionIndex = 0;
			EventSystem.current.SetSelectedGameObject(m_elements[m_selectionIndex]);
			StartCoroutine(FocusOnCurrentLevel(m_elements[m_selectionIndex].transform as RectTransform));
			skillListScrollRect.verticalNormalizedPosition = 1f;
		}
		yield return null;
	}

	private IEnumerator FocusOnCurrentLevel(RectTransform element)
	{
		yield return null;
		yield return null;
		Canvas.ForceUpdateCanvases();
		SnapTo(element);
	}

	private void SnapTo(RectTransform target)
	{
		Canvas.ForceUpdateCanvases();
		m_listRoot.anchoredPosition = (Vector2)skillListScrollRect.transform.InverseTransformPoint(m_listRoot.position) - (Vector2)skillListScrollRect.transform.InverseTransformPoint(target.position) - new Vector2(target.sizeDelta.x / 2f, 0f);
	}

	private void Update()
	{
		if (m_inputDelayTimer > 0f)
		{
			m_inputDelayTimer -= Time.unscaledDeltaTime;
			return;
		}
		if (ZInput.IsGamepadActive() && m_elements.Count > 0)
		{
			float joyRightStickY = ZInput.GetJoyRightStickY();
			float joyLeftStickY = ZInput.GetJoyLeftStickY();
			bool buttonDown = ZInput.GetButtonDown("JoyDPadUp");
			bool flag = joyLeftStickY < -0.1f || joyRightStickY < -0.1f;
			bool buttonDown2 = ZInput.GetButtonDown("JoyDPadDown");
			bool flag2 = joyLeftStickY > 0.1f || joyRightStickY > 0.1f;
			if ((flag || buttonDown) && m_selectionIndex > 0)
			{
				m_selectionIndex--;
			}
			if ((buttonDown2 || flag2) && m_selectionIndex < m_elements.Count - 1)
			{
				m_selectionIndex++;
			}
			GameObject gameObject = m_elements[m_selectionIndex];
			EventSystem.current.SetSelectedGameObject(gameObject);
			StartCoroutine(FocusOnCurrentLevel(gameObject.transform as RectTransform));
			gameObject.GetComponentInChildren<UITooltip>().OnHoverStart(gameObject);
			if (flag || flag2)
			{
				m_inputDelayTimer = m_inputDelay;
			}
		}
		if (m_elements.Count > 0)
		{
			RectTransform rectTransform = skillListScrollRect.transform as RectTransform;
			RectTransform listRoot = m_listRoot;
			scrollbar.size = rectTransform.rect.height / listRoot.rect.height;
		}
	}

	public void Setup(Player player)
	{
		base.gameObject.SetActive(value: true);
		List<Skills.Skill> skillList = player.GetSkills().GetSkillList();
		int num = skillList.Count - m_elements.Count;
		for (int i = 0; i < num; i++)
		{
			GameObject item = UnityEngine.Object.Instantiate(m_elementPrefab, Vector3.zero, Quaternion.identity, m_listRoot);
			m_elements.Add(item);
		}
		for (int j = 0; j < skillList.Count; j++)
		{
			Skills.Skill skill = skillList[j];
			GameObject obj = m_elements[j];
			obj.SetActive(value: true);
			RectTransform rectTransform = obj.transform as RectTransform;
			rectTransform.anchoredPosition = new Vector2(0f, (float)(-j) * m_spacing);
			obj.GetComponentInChildren<UITooltip>().Set("", skill.m_info.m_description, m_tooltipAnchor, new Vector2(0f, Math.Min(255f, rectTransform.localPosition.y + 10f)));
			Utils.FindChild(obj.transform, "icon").GetComponent<Image>().sprite = skill.m_info.m_icon;
			Utils.FindChild(obj.transform, "name").GetComponent<TMP_Text>().text = Localization.instance.Localize("$skill_" + skill.m_info.m_skill.ToString().ToLower());
			float skillLevel = player.GetSkills().GetSkillLevel(skill.m_info.m_skill);
			Utils.FindChild(obj.transform, "leveltext").GetComponent<TMP_Text>().text = ((int)skill.m_level).ToString();
			TMP_Text component = Utils.FindChild(obj.transform, "bonustext").GetComponent<TMP_Text>();
			bool flag = skillLevel != Mathf.Floor(skill.m_level);
			component.gameObject.SetActive(flag);
			if (flag)
			{
				component.text = (skillLevel - skill.m_level).ToString("+0");
			}
			Utils.FindChild(obj.transform, "levelbar_total").GetComponent<GuiBar>().SetValue(skillLevel / 100f);
			Utils.FindChild(obj.transform, "levelbar").GetComponent<GuiBar>().SetValue(skill.m_level / 100f);
			Utils.FindChild(obj.transform, "currentlevel").GetComponent<GuiBar>().SetValue(skill.GetLevelPercentage());
		}
		for (int k = skillList.Count; k < m_elements.Count; k++)
		{
			m_elements[k].SetActive(value: false);
		}
		float size = Mathf.Max(m_baseListSize, (float)skillList.Count * m_spacing);
		m_listRoot.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, size);
		m_totalSkillText.text = "<color=orange>" + player.GetSkills().GetTotalSkill().ToString("0") + "</color><color=white> / </color><color=orange>" + player.GetSkills().GetTotalSkillCap().ToString("0") + "</color>";
		StartCoroutine(SelectFirstEntry());
	}

	public void OnClose()
	{
		base.gameObject.SetActive(value: false);
	}

	public void SkillClicked(GameObject selectedObject)
	{
		m_selectionIndex = m_elements.IndexOf(selectedObject);
	}
}
using TMPro;
using UnityEngine;

public class SleepText : MonoBehaviour
{
	public TMP_Text m_textField;

	public TMP_Text m_dreamField;

	public DreamTexts m_dreamTexts;

	private void OnEnable()
	{
		m_textField.CrossFadeAlpha(0f, 0f, ignoreTimeScale: true);
		m_textField.CrossFadeAlpha(1f, 1f, ignoreTimeScale: true);
		m_dreamField.enabled = false;
		Invoke("CollectResources", 5f);
		Invoke("HideZZZ", 2f);
		Invoke("ShowDreamText", 4f);
	}

	private void HideZZZ()
	{
		m_textField.CrossFadeAlpha(0f, 2f, ignoreTimeScale: true);
	}

	private void CollectResources()
	{
		Game.instance.CollectResourcesCheck();
	}

	private void ShowDreamText()
	{
		DreamTexts.DreamText randomDreamText = m_dreamTexts.GetRandomDreamText();
		if (randomDreamText != null)
		{
			m_dreamField.text = Localization.instance.Localize(randomDreamText.m_text);
			m_dreamField.enabled = true;
			Invoke("DelayedCrossFadeStart", 0.1f);
			Invoke("HideDreamText", 6.5f);
		}
	}

	private void DelayedCrossFadeStart()
	{
		m_dreamField.CrossFadeAlpha(0f, 0f, ignoreTimeScale: true);
		m_dreamField.CrossFadeAlpha(1f, 1.5f, ignoreTimeScale: true);
	}

	private void HideDreamText()
	{
		m_dreamField.CrossFadeAlpha(0f, 1.5f, ignoreTimeScale: true);
	}
}
using System.Collections.Generic;
using UnityEngine;

public class SlowUpdate : MonoBehaviour
{
	private static List<SlowUpdate> m_allInstances = new List<SlowUpdate>();

	private int m_myIndex = -1;

	public virtual void Awake()
	{
		m_allInstances.Add(this);
		m_myIndex = m_allInstances.Count - 1;
	}

	public virtual void OnDestroy()
	{
		if (m_myIndex != -1)
		{
			m_allInstances[m_myIndex] = m_allInstances[m_allInstances.Count - 1];
			m_allInstances[m_myIndex].m_myIndex = m_myIndex;
			m_allInstances.RemoveAt(m_allInstances.Count - 1);
		}
	}

	public virtual void SUpdate(float time, Vector2i referenceZone)
	{
	}

	public static List<SlowUpdate> GetAllInstaces()
	{
		return m_allInstances;
	}
}
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class SlowUpdater : MonoBehaviour
{
	private const int m_updatesPerFrame = 100;

	private void Awake()
	{
		StartCoroutine("UpdateLoop");
	}

	private IEnumerator UpdateLoop()
	{
		while (true)
		{
			List<SlowUpdate> instances = SlowUpdate.GetAllInstaces();
			int index = 0;
			while (index < instances.Count)
			{
				float time = Time.time;
				Vector2i zone = ZoneSystem.GetZone(ZNet.instance.GetReferencePosition());
				for (int i = 0; i < 100; i++)
				{
					if (instances.Count == 0)
					{
						break;
					}
					if (index >= instances.Count)
					{
						break;
					}
					instances[index].SUpdate(time, zone);
					int num = index + 1;
					index = num;
				}
				yield return null;
			}
			yield return new WaitForSeconds(0.1f);
		}
	}
}
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using UnityEngine;

public class Smelter : MonoBehaviour, IHasHoverMenuExtended
{
	[Serializable]
	public class ItemConversion
	{
		public ItemDrop m_from;

		public ItemDrop m_to;
	}

	public string m_name = "Smelter";

	public string m_addOreTooltip = "$piece_smelter_additem";

	public string m_emptyOreTooltip = "$piece_smelter_empty";

	public Switch m_addWoodSwitch;

	public Switch m_addOreSwitch;

	public Switch m_emptyOreSwitch;

	public Transform m_outputPoint;

	public Transform m_roofCheckPoint;

	public GameObject m_enabledObject;

	public GameObject m_disabledObject;

	public GameObject m_haveFuelObject;

	public GameObject m_haveOreObject;

	public GameObject m_noOreObject;

	public Animator[] m_animators;

	public ItemDrop m_fuelItem;

	public int m_maxOre = 10;

	public int m_maxFuel = 10;

	public int m_fuelPerProduct = 4;

	public float m_secPerProduct = 10f;

	public bool m_spawnStack;

	public bool m_requiresRoof;

	public Windmill m_windmill;

	public SmokeSpawner m_smokeSpawner;

	public float m_addOreAnimationDuration;

	public List<ItemConversion> m_conversion = new List<ItemConversion>();

	public EffectList m_oreAddedEffects = new EffectList();

	public EffectList m_fuelAddedEffects = new EffectList();

	public EffectList m_produceEffects = new EffectList();

	private ZNetView m_nview;

	private bool m_haveRoof;

	private bool m_blockedSmoke;

	private float m_addedOreTime = -1000f;

	private StringBuilder m_sb = new StringBuilder();

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		if (m_nview == null)
		{
			m_nview = GetComponentInParent<ZNetView>();
		}
		if (!(m_nview == null) && m_nview.GetZDO() != null)
		{
			if ((bool)m_addOreSwitch)
			{
				Switch addOreSwitch = m_addOreSwitch;
				addOreSwitch.m_onUse = (Switch.Callback)Delegate.Combine(addOreSwitch.m_onUse, new Switch.Callback(OnAddOre));
				m_addOreSwitch.m_onHover = OnHoverAddOre;
			}
			if ((bool)m_addWoodSwitch)
			{
				Switch addWoodSwitch = m_addWoodSwitch;
				addWoodSwitch.m_onUse = (Switch.Callback)Delegate.Combine(addWoodSwitch.m_onUse, new Switch.Callback(OnAddFuel));
				m_addWoodSwitch.m_onHover = OnHoverAddFuel;
			}
			if ((bool)m_emptyOreSwitch)
			{
				Switch emptyOreSwitch = m_emptyOreSwitch;
				emptyOreSwitch.m_onUse = (Switch.Callback)Delegate.Combine(emptyOreSwitch.m_onUse, new Switch.Callback(OnEmpty));
				Switch emptyOreSwitch2 = m_emptyOreSwitch;
				emptyOreSwitch2.m_onHover = (Switch.TooltipCallback)Delegate.Combine(emptyOreSwitch2.m_onHover, new Switch.TooltipCallback(OnHoverEmptyOre));
			}
			m_nview.Register<string>("RPC_AddOre", RPC_AddOre);
			m_nview.Register("RPC_AddFuel", RPC_AddFuel);
			m_nview.Register("RPC_EmptyProcessed", RPC_EmptyProcessed);
			WearNTear component = GetComponent<WearNTear>();
			if ((bool)component)
			{
				component.m_onDestroyed = (Action)Delegate.Combine(component.m_onDestroyed, new Action(OnDestroyed));
			}
			InvokeRepeating("UpdateSmelter", 1f, 1f);
		}
	}

	private void DropAllItems()
	{
		SpawnProcessed();
		if (m_fuelItem != null)
		{
			float num = ((m_nview.GetZDO() == null) ? 0f : m_nview.GetZDO().GetFloat(ZDOVars.s_fuel));
			for (int i = 0; i < (int)num; i++)
			{
				Vector3 position = base.transform.position + Vector3.up + UnityEngine.Random.insideUnitSphere * 0.3f;
				Quaternion rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
				ItemDrop.OnCreateNew(UnityEngine.Object.Instantiate(m_fuelItem.gameObject, position, rotation));
			}
		}
		while (GetQueueSize() > 0)
		{
			string queuedOre = GetQueuedOre();
			RemoveOneOre();
			ItemConversion itemConversion = GetItemConversion(queuedOre);
			if (itemConversion != null)
			{
				Vector3 position2 = base.transform.position + Vector3.up + UnityEngine.Random.insideUnitSphere * 0.3f;
				Quaternion rotation2 = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
				ItemDrop.OnCreateNew(UnityEngine.Object.Instantiate(itemConversion.m_from.gameObject, position2, rotation2));
			}
		}
	}

	private void OnDestroyed()
	{
		if (m_nview.IsOwner())
		{
			DropAllItems();
		}
	}

	private bool IsItemAllowed(ItemDrop.ItemData item)
	{
		return IsItemAllowed(item.m_dropPrefab.name);
	}

	private bool IsItemAllowed(string itemName)
	{
		foreach (ItemConversion item in m_conversion)
		{
			if (item.m_from.gameObject.name == itemName)
			{
				return true;
			}
		}
		return false;
	}

	private ItemDrop.ItemData FindCookableItem(Inventory inventory)
	{
		foreach (ItemConversion item2 in m_conversion)
		{
			ItemDrop.ItemData item = inventory.GetItem(item2.m_from.m_itemData.m_shared.m_name);
			if (item != null)
			{
				return item;
			}
		}
		return null;
	}

	private bool OnAddOre(Switch sw, Humanoid user, ItemDrop.ItemData item)
	{
		if (item == null)
		{
			item = FindCookableItem(user.GetInventory());
			if (item == null)
			{
				user.Message(MessageHud.MessageType.Center, "$msg_noprocessableitems");
				return false;
			}
		}
		if (!IsItemAllowed(item.m_dropPrefab.name))
		{
			user.Message(MessageHud.MessageType.Center, "$msg_wontwork");
			return false;
		}
		ZLog.Log("trying to add " + item.m_shared.m_name);
		if (GetQueueSize() >= m_maxOre)
		{
			user.Message(MessageHud.MessageType.Center, "$msg_itsfull");
			return false;
		}
		user.Message(MessageHud.MessageType.Center, "$msg_added " + item.m_shared.m_name);
		user.GetInventory().RemoveItem(item, 1);
		m_nview.InvokeRPC("RPC_AddOre", item.m_dropPrefab.name);
		m_addedOreTime = Time.time;
		if (m_addOreAnimationDuration > 0f)
		{
			SetAnimation(active: true);
		}
		return true;
	}

	private float GetBakeTimer()
	{
		if (!m_nview.IsValid())
		{
			return 0f;
		}
		return m_nview.GetZDO().GetFloat(ZDOVars.s_bakeTimer);
	}

	private void SetBakeTimer(float t)
	{
		if (m_nview.IsValid())
		{
			m_nview.GetZDO().Set(ZDOVars.s_bakeTimer, t);
		}
	}

	private float GetFuel()
	{
		if (!m_nview.IsValid())
		{
			return 0f;
		}
		return m_nview.GetZDO().GetFloat(ZDOVars.s_fuel);
	}

	private void SetFuel(float fuel)
	{
		if (m_nview.IsValid())
		{
			m_nview.GetZDO().Set(ZDOVars.s_fuel, fuel);
		}
	}

	private int GetQueueSize()
	{
		if (!m_nview.IsValid())
		{
			return 0;
		}
		return m_nview.GetZDO().GetInt(ZDOVars.s_queued);
	}

	private void RPC_AddOre(long sender, string name)
	{
		if (m_nview.IsOwner())
		{
			if (!IsItemAllowed(name))
			{
				ZLog.Log("Item not allowed " + name);
				return;
			}
			QueueOre(name);
			m_oreAddedEffects.Create(base.transform.position, base.transform.rotation);
			ZLog.Log("Added ore " + name);
		}
	}

	private void QueueOre(string name)
	{
		int queueSize = GetQueueSize();
		m_nview.GetZDO().Set("item" + queueSize, name);
		m_nview.GetZDO().Set(ZDOVars.s_queued, queueSize + 1);
	}

	private string GetQueuedOre()
	{
		if (GetQueueSize() == 0)
		{
			return "";
		}
		return m_nview.GetZDO().GetString(ZDOVars.s_item0);
	}

	private void RemoveOneOre()
	{
		int queueSize = GetQueueSize();
		if (queueSize != 0)
		{
			for (int i = 0; i < queueSize; i++)
			{
				string value = m_nview.GetZDO().GetString("item" + (i + 1));
				m_nview.GetZDO().Set("item" + i, value);
			}
			m_nview.GetZDO().Set(ZDOVars.s_queued, queueSize - 1);
		}
	}

	private bool OnEmpty(Switch sw, Humanoid user, ItemDrop.ItemData item)
	{
		if (GetProcessedQueueSize() <= 0)
		{
			return false;
		}
		m_nview.InvokeRPC("RPC_EmptyProcessed");
		return true;
	}

	private void RPC_EmptyProcessed(long sender)
	{
		if (m_nview.IsOwner())
		{
			SpawnProcessed();
		}
	}

	private bool OnAddFuel(Switch sw, Humanoid user, ItemDrop.ItemData item)
	{
		if (item != null && item.m_shared.m_name != m_fuelItem.m_itemData.m_shared.m_name)
		{
			user.Message(MessageHud.MessageType.Center, "$msg_wrongitem");
			return false;
		}
		if (GetFuel() > (float)(m_maxFuel - 1))
		{
			user.Message(MessageHud.MessageType.Center, "$msg_itsfull");
			return false;
		}
		if (!user.GetInventory().HaveItem(m_fuelItem.m_itemData.m_shared.m_name))
		{
			user.Message(MessageHud.MessageType.Center, "$msg_donthaveany " + m_fuelItem.m_itemData.m_shared.m_name);
			return false;
		}
		user.Message(MessageHud.MessageType.Center, "$msg_added " + m_fuelItem.m_itemData.m_shared.m_name);
		user.GetInventory().RemoveItem(m_fuelItem.m_itemData.m_shared.m_name, 1);
		m_nview.InvokeRPC("RPC_AddFuel");
		return true;
	}

	private void RPC_AddFuel(long sender)
	{
		if (m_nview.IsOwner())
		{
			float fuel = GetFuel();
			SetFuel(fuel + 1f);
			m_fuelAddedEffects.Create(base.transform.position, base.transform.rotation, base.transform);
		}
	}

	private double GetDeltaTime()
	{
		DateTime time = ZNet.instance.GetTime();
		DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_startTime, time.Ticks));
		double totalSeconds = (time - dateTime).TotalSeconds;
		m_nview.GetZDO().Set(ZDOVars.s_startTime, time.Ticks);
		return totalSeconds;
	}

	private float GetAccumulator()
	{
		if (!m_nview.IsValid())
		{
			return 0f;
		}
		return m_nview.GetZDO().GetFloat(ZDOVars.s_accTime);
	}

	private void SetAccumulator(float t)
	{
		if (m_nview.IsValid())
		{
			m_nview.GetZDO().Set(ZDOVars.s_accTime, t);
		}
	}

	private void UpdateRoof()
	{
		if (m_requiresRoof)
		{
			m_haveRoof = Cover.IsUnderRoof(m_roofCheckPoint.position);
		}
	}

	private void UpdateSmoke()
	{
		if (m_smokeSpawner != null)
		{
			m_blockedSmoke = m_smokeSpawner.IsBlocked();
		}
		else
		{
			m_blockedSmoke = false;
		}
	}

	private void UpdateSmelter()
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		UpdateRoof();
		UpdateSmoke();
		UpdateState();
		if (!m_nview.IsOwner())
		{
			return;
		}
		double deltaTime = GetDeltaTime();
		float accumulator = GetAccumulator();
		accumulator += (float)deltaTime;
		if (accumulator > 3600f)
		{
			accumulator = 3600f;
		}
		float num = (m_windmill ? m_windmill.GetPowerOutput() : 1f);
		while (accumulator >= 1f)
		{
			accumulator -= 1f;
			float fuel = GetFuel();
			string queuedOre = GetQueuedOre();
			if ((m_maxFuel != 0 && !(fuel > 0f)) || (m_maxOre != 0 && !(queuedOre != "")) || !(m_secPerProduct > 0f) || (m_requiresRoof && !m_haveRoof) || m_blockedSmoke)
			{
				continue;
			}
			float num2 = 1f * num;
			if (m_maxFuel > 0)
			{
				float num3 = m_secPerProduct / (float)m_fuelPerProduct;
				fuel -= num2 / num3;
				if (fuel < 0.0001f)
				{
					fuel = 0f;
				}
				SetFuel(fuel);
			}
			if (queuedOre != "")
			{
				float bakeTimer = GetBakeTimer();
				bakeTimer += num2;
				SetBakeTimer(bakeTimer);
				if (bakeTimer >= m_secPerProduct)
				{
					SetBakeTimer(0f);
					RemoveOneOre();
					QueueProcessed(queuedOre);
				}
			}
		}
		if (GetQueuedOre() == "" || ((float)m_maxFuel > 0f && GetFuel() == 0f))
		{
			SpawnProcessed();
		}
		SetAccumulator(accumulator);
	}

	private void QueueProcessed(string ore)
	{
		if (!m_spawnStack)
		{
			Spawn(ore, 1);
		}
		else
		{
			if (!m_nview.IsValid())
			{
				return;
			}
			string text = m_nview.GetZDO().GetString(ZDOVars.s_spawnOre);
			int num = m_nview.GetZDO().GetInt(ZDOVars.s_spawnAmount);
			if (text.Length > 0)
			{
				if (text != ore)
				{
					SpawnProcessed();
					m_nview.GetZDO().Set(ZDOVars.s_spawnOre, ore);
					m_nview.GetZDO().Set(ZDOVars.s_spawnAmount, 1);
					return;
				}
				num++;
				ItemConversion itemConversion = GetItemConversion(ore);
				if (itemConversion == null || num >= itemConversion.m_to.m_itemData.m_shared.m_maxStackSize)
				{
					Spawn(ore, num);
					m_nview.GetZDO().Set(ZDOVars.s_spawnOre, "");
					m_nview.GetZDO().Set(ZDOVars.s_spawnAmount, 0);
				}
				else
				{
					m_nview.GetZDO().Set(ZDOVars.s_spawnAmount, num);
				}
			}
			else
			{
				m_nview.GetZDO().Set(ZDOVars.s_spawnOre, ore);
				m_nview.GetZDO().Set(ZDOVars.s_spawnAmount, 1);
			}
		}
	}

	private void SpawnProcessed()
	{
		if (m_nview.IsValid())
		{
			int num = m_nview.GetZDO().GetInt(ZDOVars.s_spawnAmount);
			if (num > 0)
			{
				string ore = m_nview.GetZDO().GetString(ZDOVars.s_spawnOre);
				Spawn(ore, num);
				m_nview.GetZDO().Set(ZDOVars.s_spawnOre, "");
				m_nview.GetZDO().Set(ZDOVars.s_spawnAmount, 0);
			}
		}
	}

	private int GetProcessedQueueSize()
	{
		if (!m_nview.IsValid())
		{
			return 0;
		}
		return m_nview.GetZDO().GetInt(ZDOVars.s_spawnAmount);
	}

	private void Spawn(string ore, int stack)
	{
		ItemConversion itemConversion = GetItemConversion(ore);
		if (itemConversion != null && itemConversion.m_to != null)
		{
			m_produceEffects.Create(base.transform.position, base.transform.rotation);
			ItemDrop component = UnityEngine.Object.Instantiate(itemConversion.m_to.gameObject, m_outputPoint.position, m_outputPoint.rotation).GetComponent<ItemDrop>();
			component.m_itemData.m_stack = stack;
			ItemDrop.OnCreateNew(component);
		}
	}

	private ItemConversion GetItemConversion(string itemName)
	{
		foreach (ItemConversion item in m_conversion)
		{
			if (item.m_from.gameObject.name == itemName)
			{
				return item;
			}
		}
		return null;
	}

	private void UpdateState()
	{
		bool flag = IsActive();
		m_enabledObject.SetActive(flag);
		if ((bool)m_disabledObject)
		{
			m_disabledObject.SetActive(!flag);
		}
		if ((bool)m_haveFuelObject)
		{
			m_haveFuelObject.SetActive(GetFuel() > 0f);
		}
		if ((bool)m_haveOreObject)
		{
			m_haveOreObject.SetActive(GetQueueSize() > 0);
		}
		if ((bool)m_noOreObject)
		{
			m_noOreObject.SetActive(GetQueueSize() == 0);
		}
		if (m_addOreAnimationDuration > 0f && Time.time - m_addedOreTime < m_addOreAnimationDuration)
		{
			flag = true;
		}
		SetAnimation(flag);
	}

	private void SetAnimation(bool active)
	{
		Animator[] animators = m_animators;
		foreach (Animator animator in animators)
		{
			if (animator.gameObject.activeInHierarchy)
			{
				animator.SetBool("active", active);
				animator.SetFloat("activef", active ? 1f : 0f);
			}
		}
	}

	public bool IsActive()
	{
		if ((m_maxFuel == 0 || GetFuel() > 0f) && (m_maxOre == 0 || GetQueueSize() > 0) && (!m_requiresRoof || m_haveRoof))
		{
			return !m_blockedSmoke;
		}
		return false;
	}

	private string OnHoverAddFuel()
	{
		float fuel = GetFuel();
		return Localization.instance.Localize($"{m_name} ({m_fuelItem.m_itemData.m_shared.m_name} {Mathf.Ceil(fuel)}/{m_maxFuel})\n[<color=yellow><b>$KEY_Use</b></color>] $piece_smelter_add {m_fuelItem.m_itemData.m_shared.m_name}");
	}

	private string OnHoverEmptyOre()
	{
		int processedQueueSize = GetProcessedQueueSize();
		return Localization.instance.Localize($"{m_name} ({processedQueueSize} $piece_smelter_ready) \n[<color=yellow><b>$KEY_Use</b></color>] {m_emptyOreTooltip}");
	}

	private string OnHoverAddOre()
	{
		m_sb.Clear();
		int queueSize = GetQueueSize();
		m_sb.Append($"{m_name} ({queueSize}/{m_maxOre}) ");
		if (m_requiresRoof && !m_haveRoof && Mathf.Sin(Time.time * 10f) > 0f)
		{
			m_sb.Append(" <color=yellow>$piece_smelter_reqroof</color>");
		}
		m_sb.Append("\n[<color=yellow><b>$KEY_Use</b></color>] " + m_addOreTooltip);
		return Localization.instance.Localize(m_sb.ToString());
	}

	public bool TryGetItems(Player player, Switch switchRef, out List<string> items)
	{
		items = new List<string>();
		if (!CanUseItems(player, switchRef))
		{
			return true;
		}
		if (switchRef == m_addOreSwitch)
		{
			items = m_conversion.Select((ItemConversion conversion) => conversion.m_from.m_itemData.m_shared.m_name).ToList();
		}
		else if (switchRef == m_addWoodSwitch)
		{
			items.Add(m_fuelItem.m_itemData.m_shared.m_name);
		}
		return true;
	}

	public bool CanUseItems(Player player, Switch switchRef, bool sendErrorMessage = true)
	{
		if (switchRef == m_emptyOreSwitch)
		{
			return false;
		}
		if (switchRef == m_addOreSwitch)
		{
			if (GetQueueSize() >= m_maxOre)
			{
				if (sendErrorMessage)
				{
					player.Message(MessageHud.MessageType.Center, "$msg_itsfull");
				}
				return false;
			}
			if (player.GetInventory().CountItemsByName(m_conversion.Select((ItemConversion conversion) => conversion.m_from.m_itemData.m_shared.m_name).ToArray()) > 0)
			{
				return true;
			}
			if (sendErrorMessage)
			{
				player.Message(MessageHud.MessageType.Center, "$msg_noprocessableitems");
			}
			return false;
		}
		if (switchRef != m_addWoodSwitch)
		{
			return false;
		}
		if (GetFuel() > (float)(m_maxFuel - 1))
		{
			if (sendErrorMessage)
			{
				player.Message(MessageHud.MessageType.Center, "$msg_itsfull");
			}
			return false;
		}
		if (player.GetInventory().HaveItem(m_fuelItem.m_itemData.m_shared.m_name))
		{
			return true;
		}
		if (sendErrorMessage)
		{
			player.Message(MessageHud.MessageType.Center, "$msg_donthaveany " + m_fuelItem.m_itemData.m_shared.m_name);
		}
		return false;
	}
}
using System.Collections.Generic;
using UnityEngine;

public class Smoke : MonoBehaviour, IMonoUpdater
{
	public Vector3 m_vel = Vector3.up;

	public float m_randomVel = 0.1f;

	public float m_force = 0.1f;

	public float m_ttl = 10f;

	public float m_fadetime = 3f;

	private Rigidbody m_body;

	private float m_time;

	private float m_fadeTimer = -1f;

	private bool m_added;

	private ParticleSystem.Particle m_renderParticle;

	private static readonly List<Smoke> s_smoke = new List<Smoke>();

	public Vector3Int RenderChunk { get; set; } = Vector3Int.zero;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		s_smoke.Add(this);
		m_added = true;
		m_body = GetComponent<Rigidbody>();
		m_body.maxDepenetrationVelocity = 1f;
		m_vel = Vector3.up + Quaternion.Euler(0f, Random.Range(0, 360), 0f) * Vector3.forward * m_randomVel;
		SetupParticle();
	}

	private void SetupParticle()
	{
		float num = Random.Range(0f, 360f);
		m_renderParticle = new ParticleSystem.Particle
		{
			angularVelocity = 0f,
			angularVelocity3D = Vector3.zero,
			axisOfRotation = new Vector3(0f, 0f, 1f),
			position = base.transform.position,
			randomSeed = (uint)Random.Range(int.MinValue, int.MaxValue),
			remainingLifetime = m_ttl + m_fadetime,
			startLifetime = m_ttl,
			rotation = num,
			rotation3D = new Vector3(0f, 0f, num),
			velocity = Vector3.zero
		};
	}

	public ParticleSystem.Particle GetParticleValues()
	{
		if (m_fadeTimer < 0f)
		{
			m_renderParticle.remainingLifetime = m_ttl - m_time;
		}
		else
		{
			m_renderParticle.remainingLifetime = m_fadetime - m_fadeTimer;
		}
		m_renderParticle.position = base.transform.position;
		return m_renderParticle;
	}

	public float GetAlpha()
	{
		float a = Utils.SmoothStep(0f, 1f, Mathf.Clamp01(m_time / 2f));
		float b = Utils.SmoothStep(0f, 1f, 1f - Mathf.Clamp01(m_fadeTimer / m_fadetime));
		return Mathf.Min(a, b);
	}

	private void OnEnable()
	{
		Instances.Add(this);
		SmokeRenderer.Instance.RegisterSmoke(this);
	}

	private void OnDisable()
	{
		SmokeRenderer.Instance.UnregisterSmoke(this);
		Instances.Remove(this);
	}

	private void OnDestroy()
	{
		if (m_added)
		{
			s_smoke.Remove(this);
			m_added = false;
		}
	}

	public void StartFadeOut()
	{
		if (!(m_fadeTimer >= 0f))
		{
			if (m_added)
			{
				s_smoke.Remove(this);
				m_added = false;
			}
			m_renderParticle.startLifetime = m_time + m_fadetime;
			m_fadeTimer = 0f;
		}
	}

	public static int GetTotalSmoke()
	{
		return s_smoke.Count;
	}

	public static void FadeOldest()
	{
		if (s_smoke.Count != 0)
		{
			s_smoke[0].StartFadeOut();
		}
	}

	public static void FadeMostDistant()
	{
		if (s_smoke.Count == 0)
		{
			return;
		}
		Camera mainCamera = Utils.GetMainCamera();
		if (mainCamera == null)
		{
			return;
		}
		Vector3 position = mainCamera.transform.position;
		int num = -1;
		float num2 = 0f;
		for (int i = 0; i < s_smoke.Count; i++)
		{
			float num3 = Vector3.Distance(s_smoke[i].transform.position, position);
			if (num3 > num2)
			{
				num = i;
				num2 = num3;
			}
		}
		if (num != -1)
		{
			s_smoke[num].StartFadeOut();
		}
	}

	public void CustomUpdate(float deltaTime, float time)
	{
		m_time += deltaTime;
		if (m_time > m_ttl && m_fadeTimer < 0f)
		{
			StartFadeOut();
		}
		float num = 1f - Mathf.Clamp01(m_time / m_ttl);
		m_body.mass = num * num;
		Vector3 linearVelocity = m_body.linearVelocity;
		Vector3 vel = m_vel;
		vel.y *= num;
		Vector3 vector = vel - linearVelocity;
		m_body.AddForce(vector * (m_force * deltaTime), ForceMode.VelocityChange);
		if (m_fadeTimer >= 0f)
		{
			m_fadeTimer += deltaTime;
			Mathf.Clamp01(m_fadeTimer / m_fadetime);
			if (m_fadeTimer >= m_fadetime)
			{
				Object.Destroy(base.gameObject);
			}
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class SmokeRenderer : MonoBehaviour
{
	[SerializeField]
	private ParticleSystem _particleSystemPrefab;

	[SerializeField]
	private Color m_smokeColor;

	[SerializeField]
	private float m_smokeBallSize = 4f;

	[Header("Chunking")]
	[SerializeField]
	private float m_chunkSize = 10f;

	private Dictionary<Vector3Int, ParticleSystem> m_chunkedParticleSystems = new Dictionary<Vector3Int, ParticleSystem>();

	private Dictionary<Vector3Int, List<Smoke>> m_chunkedSmoke = new Dictionary<Vector3Int, List<Smoke>>();

	private Dictionary<Vector3Int, ParticleSystem.Particle[]> m_chunkedParticles = new Dictionary<Vector3Int, ParticleSystem.Particle[]>();

	private List<Tuple<Vector3Int, Vector3Int, Smoke>> m_chunkedSmokeToMove = new List<Tuple<Vector3Int, Vector3Int, Smoke>>();

	public static SmokeRenderer Instance;

	private const int c_MaxChunkParticleCount = 100;

	private void Awake()
	{
		if (Instance == null)
		{
			Instance = this;
		}
		else
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	public void RegisterSmoke(Smoke smoke)
	{
		AddSmokeToChunk(PositionToChunk(smoke.transform.position), smoke);
	}

	public void UnregisterSmoke(Smoke smoke)
	{
		RemoveSmokeFromChunk(smoke.RenderChunk, smoke);
	}

	private Vector3Int PositionToChunk(Vector3 pos)
	{
		int x = Mathf.FloorToInt(pos.x / m_chunkSize);
		int y = Mathf.FloorToInt(pos.y / m_chunkSize);
		int z = Mathf.FloorToInt(pos.z / m_chunkSize);
		return new Vector3Int(x, y, z);
	}

	private Vector3 ChunkToWorld(Vector3Int chunk)
	{
		return new Vector3((float)chunk.x * m_chunkSize, (float)chunk.y * m_chunkSize, (float)chunk.z * m_chunkSize);
	}

	private void AddSmokeToChunk(Vector3Int chunk, Smoke smoke)
	{
		if (!m_chunkedSmoke.ContainsKey(chunk))
		{
			m_chunkedSmoke.Add(chunk, new List<Smoke>());
			m_chunkedParticleSystems.Add(chunk, UnityEngine.Object.Instantiate(_particleSystemPrefab, ChunkToWorld(chunk), Quaternion.identity));
			m_chunkedParticles.Add(chunk, new ParticleSystem.Particle[100]);
		}
		if (!m_chunkedSmoke[chunk].Contains(smoke))
		{
			m_chunkedSmoke[chunk].Add(smoke);
		}
		smoke.RenderChunk = chunk;
	}

	private void RemoveSmokeFromChunk(Vector3Int chunk, Smoke smoke)
	{
		if (m_chunkedSmoke.ContainsKey(chunk))
		{
			m_chunkedSmoke[chunk].Remove(smoke);
			if (m_chunkedSmoke[chunk].Count == 0)
			{
				CleanupChunk(chunk);
			}
		}
	}

	private void CleanupChunk(Vector3Int chunk)
	{
		m_chunkedParticles.Remove(chunk);
		m_chunkedSmoke.Remove(chunk);
		m_chunkedParticleSystems.Remove(chunk, out var value);
		if (value != null)
		{
			UnityEngine.Object.Destroy(value.gameObject);
		}
	}

	private void TransferSmokeBetweenChunks()
	{
		m_chunkedSmokeToMove.Clear();
		foreach (Vector3Int key in m_chunkedSmoke.Keys)
		{
			foreach (Smoke item in m_chunkedSmoke[key])
			{
				Vector3Int vector3Int = PositionToChunk(item.transform.position);
				if (vector3Int != key)
				{
					m_chunkedSmokeToMove.Add(new Tuple<Vector3Int, Vector3Int, Smoke>(key, vector3Int, item));
				}
			}
		}
		foreach (Tuple<Vector3Int, Vector3Int, Smoke> item2 in m_chunkedSmokeToMove)
		{
			RemoveSmokeFromChunk(item2.Item1, item2.Item3);
			AddSmokeToChunk(item2.Item2, item2.Item3);
		}
	}

	private void LateUpdate()
	{
		TransferSmokeBetweenChunks();
		foreach (Vector3Int key in m_chunkedParticleSystems.Keys)
		{
			ParticleSystem particleSystem = m_chunkedParticleSystems[key];
			List<Smoke> list = m_chunkedSmoke[key];
			ParticleSystem.Particle[] array = m_chunkedParticles[key];
			if (list.Count > particleSystem.particleCount)
			{
				particleSystem.Emit(list.Count - particleSystem.particleCount);
			}
			for (int i = 0; i < list.Count; i++)
			{
				Smoke smoke = list[i];
				array[i] = smoke.GetParticleValues();
				array[i].startColor = m_smokeColor * new Color(1f, 1f, 1f, smoke.GetAlpha());
				array[i].startSize = m_smokeBallSize;
			}
			for (int j = list.Count; j < particleSystem.particleCount; j++)
			{
				array[j].remainingLifetime = -1f;
			}
			particleSystem.SetParticles(array, particleSystem.particleCount);
		}
	}

	private void OnDrawGizmosSelected()
	{
		foreach (Vector3Int key in m_chunkedSmoke.Keys)
		{
			Vector3 vector = ChunkToWorld(key);
			Color a = new Color(0.43f, 1f, 0f, 0.26f);
			Color red = Color.red;
			Gizmos.color = Color.Lerp(a, red, (float)m_chunkedSmoke[key].Count / 100f * 0.33f);
			Gizmos.DrawWireCube(vector + Vector3.one * m_chunkSize * 0.5f, m_chunkSize * Vector3.one);
		}
	}
}
using System.Collections.Generic;
using UnityEngine;

public class SmokeSpawner : MonoBehaviour, IMonoUpdater
{
	private static Collider[] s_colliders = new Collider[30];

	private const float m_minPlayerDistance = 64f;

	private const int m_maxGlobalSmoke = 100;

	private const float m_blockedMinTime = 4f;

	public GameObject m_smokePrefab;

	public float m_interval = 0.5f;

	public LayerMask m_testMask;

	public float m_testRadius = 0.5f;

	public float m_spawnRadius;

	public bool m_stopFireOnStart;

	private float m_lastSpawnTime;

	private float m_time;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		m_time = Random.Range(0f, m_interval);
		if (!m_stopFireOnStart)
		{
			return;
		}
		foreach (Fire s_fire in Fire.s_fires)
		{
			if ((bool)s_fire && Vector3.Distance(s_fire.transform.position, base.transform.position) < m_spawnRadius)
			{
				ZNetScene.instance.Destroy(s_fire.gameObject);
			}
		}
	}

	private void OnEnable()
	{
		Instances.Add(this);
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public void CustomUpdate(float deltaTime, float time)
	{
		m_time += deltaTime;
		if (m_time > m_interval)
		{
			m_time = 0f;
			Spawn(time);
		}
	}

	private void Spawn(float time)
	{
		Player localPlayer = Player.m_localPlayer;
		if (localPlayer == null || Vector3.Distance(localPlayer.transform.position, base.transform.position) > 64f)
		{
			m_lastSpawnTime = time;
		}
		else if (!TestBlocked())
		{
			if (Smoke.GetTotalSmoke() > 100)
			{
				Smoke.FadeOldest();
			}
			Vector3 position = base.transform.position;
			if (m_spawnRadius > 0f)
			{
				Vector2 vector = Random.insideUnitCircle.normalized * Random.Range(m_spawnRadius / 2f, m_spawnRadius);
				position += new Vector3(vector.x, 0f, vector.y);
			}
			Object.Instantiate(m_smokePrefab, position, Random.rotation);
			m_lastSpawnTime = time;
		}
	}

	private bool TestBlocked()
	{
		if (Physics.CheckSphere(base.transform.position, m_testRadius, m_testMask.value))
		{
			return true;
		}
		return false;
	}

	public bool IsBlocked()
	{
		if (!base.gameObject.activeInHierarchy)
		{
			return TestBlocked();
		}
		return Time.time - m_lastSpawnTime > 4f;
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.yellow;
		Utils.DrawGizmoCircle(base.transform.position, m_spawnRadius, 16);
	}
}
using System.Collections.Generic;
using UnityEngine;

[ExecuteInEditMode]
public class SnapToGround : MonoBehaviour
{
	public float m_offset;

	private static List<SnapToGround> m_allSnappers = new List<SnapToGround>();

	private bool m_inList;

	private void Awake()
	{
		m_allSnappers.Add(this);
		m_inList = true;
	}

	private void OnDestroy()
	{
		if (m_inList)
		{
			m_allSnappers.Remove(this);
			m_inList = false;
		}
	}

	public void Snap()
	{
		if (!(ZoneSystem.instance == null))
		{
			float groundHeight = ZoneSystem.instance.GetGroundHeight(base.transform.position);
			Vector3 position = base.transform.position;
			position.y = groundHeight + m_offset;
			base.transform.position = position;
			ZNetView component = GetComponent<ZNetView>();
			if (component != null && component.IsOwner())
			{
				component.GetZDO().SetPosition(position);
			}
		}
	}

	public bool HaveUnsnapped()
	{
		return m_allSnappers.Count > 0;
	}

	public static void SnappAll()
	{
		if (m_allSnappers.Count == 0)
		{
			return;
		}
		Heightmap.ForceGenerateAll();
		foreach (SnapToGround allSnapper in m_allSnappers)
		{
			allSnapper.Snap();
			allSnapper.m_inList = false;
		}
		m_allSnappers.Clear();
	}
}
using SoftReferenceableAssets;
using UnityEngine;

public class SoftReferencePrefabSpawner : MonoBehaviour
{
	[SerializeField]
	private SoftReference<GameObject> m_prefab;

	[SerializeField]
	private bool m_spawnAsynchronously;

	private bool m_currentlyLoading;

	private void Awake()
	{
		if (m_spawnAsynchronously)
		{
			m_currentlyLoading = true;
			m_prefab.LoadAsync(delegate(AssetID assetID, LoadResult result)
			{
				m_currentlyLoading = false;
				if (result == LoadResult.Succeeded)
				{
					SpawnPrefab();
				}
				m_prefab.Release();
				Object.Destroy(base.gameObject);
			});
		}
		else
		{
			SpawnPrefab();
			Object.Destroy(base.gameObject);
		}
	}

	private void OnDestroy()
	{
		if (m_currentlyLoading)
		{
			m_prefab.Load();
			m_prefab.Release();
		}
	}

	private void SpawnPrefab()
	{
		SoftReferenceableAssets.Utils.Instantiate(m_prefab, base.transform.parent).name = m_prefab.Name;
	}
}
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class SpawnAbility : MonoBehaviour, IProjectile
{
	public enum TargetType
	{
		ClosestEnemy,
		RandomEnemy,
		Caster,
		Position,
		RandomPathfindablePosition
	}

	[Serializable]
	public class LevelUpSettings
	{
		public Skills.SkillType m_skill;

		public int m_skillLevel;

		public int m_setLevel;

		public int m_maxSpawns;
	}

	[Header("Spawn")]
	public GameObject[] m_spawnPrefab;

	public string m_maxSummonReached = "$hud_maxsummonsreached";

	public bool m_spawnOnAwake;

	public bool m_alertSpawnedCreature = true;

	public bool m_passiveAggressive;

	public bool m_spawnAtTarget = true;

	public int m_minToSpawn = 1;

	public int m_maxToSpawn = 1;

	public int m_maxSpawned = 3;

	public float m_spawnRadius = 3f;

	public bool m_circleSpawn;

	public bool m_snapToTerrain = true;

	[Tooltip("Used to give random Y rotations to things like AOEs that aren't circular")]
	public bool m_randomYRotation;

	public float m_spawnGroundOffset;

	public int m_getSolidHeightMargin = 1000;

	public float m_initialSpawnDelay;

	public float m_spawnDelay;

	public float m_preSpawnDelay;

	public bool m_commandOnSpawn;

	public bool m_wakeUpAnimation;

	public Skills.SkillType m_copySkill;

	public float m_copySkillToRandomFactor;

	public bool m_setMaxInstancesFromWeaponLevel;

	public List<LevelUpSettings> m_levelUpSettings;

	public TargetType m_targetType;

	public Pathfinding.AgentType m_targetWhenPathfindingType = Pathfinding.AgentType.Humanoid;

	public float m_maxTargetRange = 40f;

	public EffectList m_spawnEffects = new EffectList();

	public EffectList m_preSpawnEffects = new EffectList();

	[Tooltip("Used for the troll summoning staff, to spawn an AOE that's friendly to the spawned creature.")]
	public GameObject m_aoePrefab;

	[Header("Projectile")]
	public float m_projectileVelocity = 10f;

	public float m_projectileVelocityMax;

	public float m_projectileAccuracy = 10f;

	public bool m_randomDirection;

	public float m_randomAngleMin;

	public float m_randomAngleMax;

	private Character m_owner;

	private ItemDrop.ItemData m_weapon;

	public void Awake()
	{
		if (m_spawnOnAwake)
		{
			StartCoroutine("Spawn");
		}
	}

	public void Setup(Character owner, Vector3 velocity, float hitNoise, HitData hitData, ItemDrop.ItemData item, ItemDrop.ItemData ammo)
	{
		m_owner = owner;
		m_weapon = item;
		StartCoroutine("Spawn");
	}

	public string GetTooltipString(int itemQuality)
	{
		return "";
	}

	private IEnumerator Spawn()
	{
		if (m_initialSpawnDelay > 0f)
		{
			yield return new WaitForSeconds(m_initialSpawnDelay);
		}
		int toSpawn = UnityEngine.Random.Range(m_minToSpawn, m_maxToSpawn);
		Skills skills = (m_owner ? m_owner.GetSkills() : null);
		int num3;
		for (int i = 0; i < toSpawn; num3 = i + 1, i = num3)
		{
			Vector3 targetPosition = base.transform.position;
			bool foundSpawnPoint = false;
			int tries = ((m_targetType != TargetType.RandomPathfindablePosition) ? 1 : 5);
			for (int k = 0; k < tries; k++)
			{
				bool flag;
				foundSpawnPoint = (flag = FindTarget(out targetPosition, i, toSpawn));
				if (flag)
				{
					break;
				}
				if (m_targetType == TargetType.RandomPathfindablePosition)
				{
					if (k == tries - 1)
					{
						Terminal.LogWarning($"SpawnAbility failed to pathfindable target after {tries} tries, defaulting to transform position.");
						targetPosition = base.transform.position;
						foundSpawnPoint = true;
					}
					else
					{
						Terminal.Log("SpawnAbility failed to pathfindable target, waiting before retry.");
						yield return new WaitForSeconds(0.2f);
					}
				}
			}
			if (!foundSpawnPoint)
			{
				Terminal.LogWarning("SpawnAbility failed to find spawn point, aborting spawn.");
				continue;
			}
			Vector3 spawnPoint = targetPosition;
			if (m_targetType != TargetType.RandomPathfindablePosition)
			{
				Vector3 vector = (m_spawnAtTarget ? targetPosition : base.transform.position);
				Vector2 vector2 = UnityEngine.Random.insideUnitCircle * m_spawnRadius;
				if (m_circleSpawn)
				{
					vector2 = GetCirclePoint(i, toSpawn) * m_spawnRadius;
				}
				spawnPoint = vector + new Vector3(vector2.x, 0f, vector2.y);
				if (m_snapToTerrain)
				{
					ZoneSystem.instance.GetSolidHeight(spawnPoint, out var height, m_getSolidHeightMargin);
					spawnPoint.y = height;
				}
				spawnPoint.y += m_spawnGroundOffset;
				if (Mathf.Abs(spawnPoint.y - vector.y) > 100f)
				{
					continue;
				}
			}
			GameObject prefab = m_spawnPrefab[UnityEngine.Random.Range(0, m_spawnPrefab.Length)];
			if (m_maxSpawned > 0 && SpawnSystem.GetNrOfInstances(prefab) >= m_maxSpawned)
			{
				if (m_owner is Player player)
				{
					player.Message(MessageHud.MessageType.Center, m_maxSummonReached);
				}
				continue;
			}
			m_preSpawnEffects.Create(spawnPoint, Quaternion.identity);
			if (m_preSpawnDelay > 0f)
			{
				yield return new WaitForSeconds(m_preSpawnDelay);
			}
			Terminal.Log("SpawnAbility spawning a " + prefab.name);
			GameObject gameObject = UnityEngine.Object.Instantiate(prefab, spawnPoint, Quaternion.Euler(0f, UnityEngine.Random.value * MathF.PI * 2f, 0f));
			ZNetView component = gameObject.GetComponent<ZNetView>();
			Projectile component2 = gameObject.GetComponent<Projectile>();
			if ((bool)component2)
			{
				SetupProjectile(component2, targetPosition);
			}
			if (m_randomYRotation)
			{
				gameObject.transform.Rotate(Vector3.up, UnityEngine.Random.Range(-180, 180));
			}
			if ((bool)skills)
			{
				if (m_copySkill != Skills.SkillType.None && m_copySkillToRandomFactor > 0f)
				{
					component.GetZDO().Set(ZDOVars.s_randomSkillFactor, 1f + skills.GetSkillLevel(m_copySkill) * m_copySkillToRandomFactor);
				}
				if (m_levelUpSettings.Count > 0)
				{
					Character component3 = gameObject.GetComponent<Character>();
					if ((object)component3 != null)
					{
						for (int num = m_levelUpSettings.Count - 1; num >= 0; num--)
						{
							LevelUpSettings levelUpSettings = m_levelUpSettings[num];
							if (skills.GetSkillLevel(levelUpSettings.m_skill) >= (float)levelUpSettings.m_skillLevel)
							{
								component3.SetLevel(levelUpSettings.m_setLevel);
								int num2 = (m_setMaxInstancesFromWeaponLevel ? m_weapon.m_quality : levelUpSettings.m_maxSpawns);
								if (num2 > 0)
								{
									component.GetZDO().Set(ZDOVars.s_maxInstances, num2);
								}
								break;
							}
						}
					}
				}
			}
			if (m_commandOnSpawn)
			{
				Tameable component4 = gameObject.GetComponent<Tameable>();
				if ((object)component4 != null && m_owner is Humanoid humanoid)
				{
					component4.Command(humanoid, message: false);
					if (humanoid == Player.m_localPlayer)
					{
						Game.instance.IncrementPlayerStat(PlayerStatType.SkeletonSummons);
					}
				}
			}
			if (m_wakeUpAnimation)
			{
				gameObject.GetComponent<ZSyncAnimation>()?.SetBool("wakeup", value: true);
			}
			BaseAI component5 = gameObject.GetComponent<BaseAI>();
			if (component5 != null)
			{
				if (m_alertSpawnedCreature)
				{
					component5.Alert();
				}
				BaseAI baseAI = m_owner.GetBaseAI();
				if (component5.m_aggravatable && (bool)baseAI && baseAI.m_aggravatable)
				{
					component5.SetAggravated(baseAI.IsAggravated(), BaseAI.AggravatedReason.Damage);
				}
				if (m_passiveAggressive)
				{
					component5.m_passiveAggresive = true;
				}
			}
			SetupAoe(gameObject.GetComponent<Character>(), spawnPoint);
			m_spawnEffects.Create(spawnPoint, Quaternion.identity);
			if (m_spawnDelay > 0f)
			{
				yield return new WaitForSeconds(m_spawnDelay);
			}
		}
		if (!m_spawnOnAwake)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private Vector3 GetRandomConeDirection()
	{
		int num = UnityEngine.Random.Range(0, 360);
		float f = UnityEngine.Random.Range(m_randomAngleMin, m_randomAngleMax);
		return Quaternion.AngleAxis(num, Vector3.up) * new Vector3(Mathf.Sin(f), Mathf.Cos(f), 0f);
	}

	private void SetupProjectile(Projectile projectile, Vector3 targetPoint)
	{
		Vector3 vector = (m_randomDirection ? GetRandomConeDirection() : (targetPoint - projectile.transform.position).normalized);
		Vector3 axis = Vector3.Cross(vector, Vector3.up);
		Quaternion quaternion = Quaternion.AngleAxis(UnityEngine.Random.Range(0f - m_projectileAccuracy, m_projectileAccuracy), Vector3.up);
		vector = Quaternion.AngleAxis(UnityEngine.Random.Range(0f - m_projectileAccuracy, m_projectileAccuracy), axis) * vector;
		vector = quaternion * vector;
		float num = ((m_projectileVelocityMax > 0f) ? UnityEngine.Random.Range(m_projectileVelocity, m_projectileVelocityMax) : m_projectileVelocity);
		projectile.Setup(m_owner, vector * num, -1f, null, null, null);
	}

	private void SetupAoe(Character owner, Vector3 targetPoint)
	{
		if (!(m_aoePrefab == null) && !(owner == null))
		{
			Aoe component = UnityEngine.Object.Instantiate(m_aoePrefab, targetPoint, Quaternion.identity).GetComponent<Aoe>();
			if (!(component == null))
			{
				component.Setup(owner, Vector3.zero, -1f, null, null, null);
			}
		}
	}

	private bool FindTarget(out Vector3 point, int i, int spawnCount)
	{
		point = Vector3.zero;
		switch (m_targetType)
		{
		case TargetType.ClosestEnemy:
		{
			if (m_owner == null)
			{
				return false;
			}
			Character character2 = BaseAI.FindClosestEnemy(m_owner, base.transform.position, m_maxTargetRange);
			if (character2 != null)
			{
				point = character2.transform.position;
				return true;
			}
			return false;
		}
		case TargetType.RandomEnemy:
		{
			if (m_owner == null)
			{
				return false;
			}
			Character character = BaseAI.FindRandomEnemy(m_owner, base.transform.position, m_maxTargetRange);
			if (character != null)
			{
				point = character.transform.position;
				return true;
			}
			return false;
		}
		case TargetType.Position:
			point = base.transform.position;
			return true;
		case TargetType.Caster:
			if (m_owner == null)
			{
				return false;
			}
			point = m_owner.transform.position;
			return true;
		case TargetType.RandomPathfindablePosition:
		{
			if (m_owner == null)
			{
				return false;
			}
			List<Vector3> list = new List<Vector3>();
			Vector2 vector = UnityEngine.Random.insideUnitCircle.normalized * UnityEngine.Random.Range(m_spawnRadius / 2f, m_spawnRadius);
			point = base.transform.position + new Vector3(vector.x, 2f, vector.y);
			ZoneSystem.instance.GetSolidHeight(point, out var height, 2);
			point.y = height;
			if (Pathfinding.instance.GetPath(m_owner.transform.position, point, list, m_targetWhenPathfindingType, requireFullPath: true, cleanup: false, havePath: true))
			{
				Terminal.Log($"SpawnAbility found path target, distance: {Vector3.Distance(base.transform.position, list[0])}");
				point = list[list.Count - 1];
				return true;
			}
			return false;
		}
		default:
			return false;
		}
	}

	private Vector2 GetCirclePoint(int i, int spawnCount)
	{
		float num = (float)i / (float)spawnCount;
		float x = Mathf.Sin(num * MathF.PI * 2f);
		float y = Mathf.Cos(num * MathF.PI * 2f);
		return new Vector2(x, y);
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class SpawnArea : MonoBehaviour
{
	[Serializable]
	public class SpawnData
	{
		public GameObject m_prefab;

		public float m_weight;

		[Header("Level")]
		public int m_maxLevel = 1;

		public int m_minLevel = 1;
	}

	private const float dt = 2f;

	public List<SpawnData> m_prefabs = new List<SpawnData>();

	public float m_levelupChance = 15f;

	public float m_spawnIntervalSec = 30f;

	public float m_triggerDistance = 256f;

	public bool m_setPatrolSpawnPoint = true;

	public float m_spawnRadius = 2f;

	public float m_nearRadius = 10f;

	public float m_farRadius = 1000f;

	public int m_maxNear = 3;

	public int m_maxTotal = 20;

	public bool m_onGroundOnly;

	public EffectList m_spawnEffects = new EffectList();

	private ZNetView m_nview;

	private float m_spawnTimer;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		InvokeRepeating("UpdateSpawn", 2f, 2f);
	}

	private void UpdateSpawn()
	{
		if (m_nview.IsOwner() && !ZNetScene.instance.OutsideActiveArea(base.transform.position) && Player.IsPlayerInRange(base.transform.position, m_triggerDistance))
		{
			m_spawnTimer += 2f;
			if (m_spawnTimer > m_spawnIntervalSec)
			{
				m_spawnTimer = 0f;
				SpawnOne();
			}
		}
	}

	private bool SpawnOne()
	{
		if (SpawnSystem.m_nospawn)
		{
			return false;
		}
		GetInstances(out var near, out var total);
		if (near >= m_maxNear || total >= m_maxTotal)
		{
			return false;
		}
		SpawnData spawnData = SelectWeightedPrefab();
		if (spawnData == null)
		{
			return false;
		}
		if (!FindSpawnPoint(spawnData.m_prefab, out var point))
		{
			return false;
		}
		GameObject gameObject = UnityEngine.Object.Instantiate(spawnData.m_prefab, point, Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f));
		if (m_setPatrolSpawnPoint)
		{
			BaseAI component = gameObject.GetComponent<BaseAI>();
			if (component != null)
			{
				component.SetPatrolPoint();
			}
		}
		Character component2 = gameObject.GetComponent<Character>();
		if (spawnData.m_maxLevel > 1)
		{
			int i;
			for (i = spawnData.m_minLevel; i < spawnData.m_maxLevel; i++)
			{
				if (!(UnityEngine.Random.Range(0f, 100f) <= GetLevelUpChance()))
				{
					break;
				}
			}
			if (i > 1)
			{
				component2.SetLevel(i);
			}
		}
		Vector3 centerPoint = component2.GetCenterPoint();
		m_spawnEffects.Create(centerPoint, Quaternion.identity);
		return true;
	}

	private bool FindSpawnPoint(GameObject prefab, out Vector3 point)
	{
		prefab.GetComponent<BaseAI>();
		for (int i = 0; i < 10; i++)
		{
			Vector3 vector = base.transform.position + Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f) * Vector3.forward * UnityEngine.Random.Range(0f, m_spawnRadius);
			if (ZoneSystem.instance.FindFloor(vector, out var height) && (!m_onGroundOnly || !ZoneSystem.instance.IsBlocked(vector)))
			{
				vector.y = height + 0.1f;
				point = vector;
				return true;
			}
		}
		point = Vector3.zero;
		return false;
	}

	private SpawnData SelectWeightedPrefab()
	{
		if (m_prefabs.Count == 0)
		{
			return null;
		}
		float num = 0f;
		foreach (SpawnData prefab in m_prefabs)
		{
			num += prefab.m_weight;
		}
		float num2 = UnityEngine.Random.Range(0f, num);
		float num3 = 0f;
		foreach (SpawnData prefab2 in m_prefabs)
		{
			num3 += prefab2.m_weight;
			if (num2 <= num3)
			{
				return prefab2;
			}
		}
		return m_prefabs[m_prefabs.Count - 1];
	}

	private void GetInstances(out int near, out int total)
	{
		near = 0;
		total = 0;
		Vector3 position = base.transform.position;
		foreach (BaseAI baseAIInstance in BaseAI.BaseAIInstances)
		{
			if (IsSpawnPrefab(baseAIInstance.gameObject))
			{
				float num = Utils.DistanceXZ(baseAIInstance.transform.position, position);
				if (num < m_nearRadius)
				{
					near++;
				}
				if (num < m_farRadius)
				{
					total++;
				}
			}
		}
	}

	private bool IsSpawnPrefab(GameObject go)
	{
		string a = go.name;
		Character component = go.GetComponent<Character>();
		foreach (SpawnData prefab in m_prefabs)
		{
			if (a.CustomStartsWith(prefab.m_prefab.name) && (!component || !component.IsTamed()))
			{
				return true;
			}
		}
		return false;
	}

	public float GetLevelUpChance()
	{
		if (Game.m_worldLevel > 0 && Game.instance.m_worldLevelEnemyLevelUpExponent > 0f)
		{
			return Mathf.Min(70f, Mathf.Pow(m_levelupChance, (float)Game.m_worldLevel * Game.instance.m_worldLevelEnemyLevelUpExponent));
		}
		return m_levelupChance * Game.m_enemyLevelUpRate;
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.red;
		Gizmos.DrawWireSphere(base.transform.position, m_spawnRadius);
		Gizmos.color = Color.yellow;
		Gizmos.DrawWireSphere(base.transform.position, m_nearRadius);
	}
}
