		m_nview = GetComponentInParent<ZNetView>();
		if (m_nview == null)
		{
			ZLog.LogWarning("SpawnerPrefab cant find netview " + base.gameObject.name);
		}
		else
		{
			InvokeRepeating("TrySpawn", 1f, 1f);
