public class StartupMessages : MonoBehaviour
{
	private static StartupMessages s_instance;

	private uint m_shownMessages;

	public static StartupMessages Instance => s_instance;

	public bool StartupMessageDisplayed => m_shownMessages != 0;

	private void Awake()
	{
		if ((object)s_instance != null)
		{
			ZLog.LogError("StartupMessages already had instance!");
			Object.DestroyImmediate(this);
		}
		else
		{
			s_instance = this;
		}
	}

	private void OnDestroy()
	{
		if ((object)s_instance == null)
		{
			ZLog.LogWarning("StartupMessages had no instance!");
		}
		else if (s_instance != this)
		{
			ZLog.LogWarning("StartupMessages had a different instance!");
		}
		else
		{
			s_instance = null;
		}
	}

	public void DisplayStartupMessages()
	{
		PrintGPUInfo();
		DisplayWindowsVulkanAMDCrashMessage();
	}

	private void DisplayWindowsVulkanAMDCrashMessage()
	{
		if (GetGPUVendor() == GPUVendor.AMD && SystemInfo.operatingSystemFamily == OperatingSystemFamily.Windows && SystemInfo.graphicsDeviceType == GraphicsDeviceType.Vulkan)
		{
			m_shownMessages++;
			UnifiedPopup.Push(new WarningPopup("$menu_vulkancrashwarning_header", "$menu_vulkancrashwarning_text", delegate
			{
				UnifiedPopup.Pop();
				m_shownMessages--;
			}));
		}
	}

	private GPUVendor GetGPUVendor()
	{
		switch (SystemInfo.graphicsDeviceVendorID)
		{
		case 4318:
			return GPUVendor.NVIDIA;
		case 4098:
		case 4130:
			return GPUVendor.AMD;
		case 32902:
			return GPUVendor.Intel;
		default:
			return GPUVendor.Unknown;
		}
	}

	private void PrintGPUInfo()
	{
		string text = null;
		string text2;
		switch (SystemInfo.graphicsDeviceVendorID)
		{
		case 4318:
			text2 = "NVIDIA";
			break;
		case 4098:
		case 4130:
			switch (SystemInfo.graphicsDeviceID)
			{
			case 30032:
			case 30033:
			case 30096:
				text = "RDNA4";
				break;
			case 28639:
				text = "GCN4";
				break;
			}
			text2 = "AMD";
			break;
		case 32902:
			text2 = "Intel";
			break;
		default:
			text2 = "Unknown";
			break;
		}
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.Append("GPU Device: " + SystemInfo.graphicsDeviceVendorID.ToString("X4") + ":" + SystemInfo.graphicsDeviceID.ToString("X4") + " (" + text2);
		if (text != null)
		{
			stringBuilder.Append(", " + text);
		}
		stringBuilder.Append(")");
		ZLog.Log(stringBuilder.ToString());
	}
}
using UnityEngine;

public class StateController : StateMachineBehaviour
{
	public string m_effectJoint = "";

	public EffectList m_enterEffect = new EffectList();

	public bool m_enterDisableChildren;

	public bool m_enterEnableChildren;

	public GameObject[] m_enterDisable = new GameObject[0];

	public GameObject[] m_enterEnable = new GameObject[0];

	private Transform m_effectJoinT;

	public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
	{
		if (m_enterEffect.HasEffects())
		{
			m_enterEffect.Create(GetEffectPos(animator), animator.transform.rotation);
		}
		if (m_enterDisableChildren)
		{
			for (int i = 0; i < animator.transform.childCount; i++)
			{
				animator.transform.GetChild(i).gameObject.SetActive(value: false);
			}
		}
		if (m_enterEnableChildren)
		{
			for (int j = 0; j < animator.transform.childCount; j++)
			{
				animator.transform.GetChild(j).gameObject.SetActive(value: true);
			}
		}
	}

	private Vector3 GetEffectPos(Animator animator)
	{
		if (m_effectJoint.Length == 0)
		{
			return animator.transform.position;
		}
		if (m_effectJoinT == null)
		{
			m_effectJoinT = Utils.FindChild(animator.transform, m_effectJoint);
		}
		return m_effectJoinT.position;
	}
}
using UnityEngine;

public class StaticPhysics : SlowUpdate
{
	public bool m_pushUp = true;

	public bool m_fall = true;

	public bool m_checkSolids;

	public float m_fallCheckRadius;

	private ZNetView m_nview;

	private const float m_fallSpeed = 4f;

	private const float m_fallStep = 0.05f;

	private float m_updateTime;

	private bool m_falling;

	private int m_activeArea;

	public bool IsFalling => m_falling;

	public override void Awake()
	{
		base.Awake();
		m_nview = GetComponent<ZNetView>();
		m_updateTime = Time.time + 20f;
		m_activeArea = ZoneSystem.instance.m_activeArea;
	}

	private bool ShouldUpdate(float time)
	{
		return time > m_updateTime;
	}

	public override void SUpdate(float time, Vector2i referenceZone)
	{
		if (!m_falling && ShouldUpdate(time) && !ZNetScene.OutsideActiveArea(base.transform.position, referenceZone, m_activeArea))
		{
			if (m_fall)
			{
				CheckFall();
			}
			if (m_pushUp)
			{
				PushUp();
			}
		}
	}

	private void CheckFall()
	{
		float fallHeight = GetFallHeight();
		if (base.transform.position.y > fallHeight + 0.05f)
		{
			Fall();
		}
	}

	private float GetFallHeight()
	{
		if (m_checkSolids)
		{
			if (ZoneSystem.instance.GetSolidHeight(base.transform.position, m_fallCheckRadius, out var height, base.transform))
			{
				return height;
			}
			return base.transform.position.y;
		}
		if (ZoneSystem.instance.GetGroundHeight(base.transform.position, out var height2))
		{
			return height2;
		}
		return base.transform.position.y;
	}

	private void Fall()
	{
		m_falling = true;
		base.gameObject.isStatic = false;
		InvokeRepeating("FallUpdate", 0.05f, 0.05f);
	}

	private void FallUpdate()
	{
		float fallHeight = GetFallHeight();
		Vector3 position = base.transform.position;
		position.y -= 0.2f;
		if (position.y <= fallHeight)
		{
			position.y = fallHeight;
			StopFalling();
		}
		base.transform.position = position;
		if ((bool)m_nview && m_nview.IsValid() && m_nview.IsOwner())
		{
			m_nview.GetZDO().SetPosition(base.transform.position);
		}
	}

	private void StopFalling()
	{
		base.gameObject.isStatic = true;
		m_falling = false;
		CancelInvoke("FallUpdate");
	}

	private void PushUp()
	{
		if (ZoneSystem.instance.GetGroundHeight(base.transform.position, out var height) && base.transform.position.y < height - 0.05f)
		{
			base.gameObject.isStatic = false;
			Vector3 position = base.transform.position;
			position.y = height;
			base.transform.position = position;
			base.gameObject.isStatic = true;
			if ((bool)m_nview && m_nview.IsValid() && m_nview.IsOwner())
			{
				m_nview.GetZDO().SetPosition(base.transform.position);
			}
		}
	}
}
using UnityEngine;

public class StaticRotation : MonoBehaviour
{
	public bool m_NotIfBuildGhost = true;

	private ZNetView m_nview;

	private float m_rotation;

	private bool m_disabled;

	private void Start()
	{
		int disabled;
		if (m_NotIfBuildGhost)
		{
			Piece componentInParent = GetComponentInParent<Piece>();
			if ((object)componentInParent != null)
			{
				disabled = (Player.IsPlacementGhost(componentInParent.gameObject) ? 1 : 0);
				goto IL_0021;
			}
		}
		disabled = 0;
		goto IL_0021;
		IL_0021:
		m_disabled = (byte)disabled != 0;
		m_nview = GetComponentInParent<ZNetView>();
		if (!m_nview)
		{
			return;
		}
		ZDO zDO = m_nview.GetZDO();
		if (zDO != null && zDO.IsValid())
		{
			m_rotation = zDO.GetFloat(ZDOVars.s_tiltrot);
			if (m_rotation == 0f)
			{
				m_rotation = base.transform.rotation.eulerAngles.y;
				zDO.Set(ZDOVars.s_tiltrot, m_rotation);
			}
		}
	}

	private void Update()
	{
		if (!m_disabled)
		{
			Vector3 eulerAngles = base.transform.rotation.eulerAngles;
			base.transform.rotation = Quaternion.Euler(eulerAngles.x, m_rotation, eulerAngles.z);
		}
	}
}
using System.Collections.Generic;
using UnityEngine;

public class StaticTarget : MonoBehaviour
{
	[Header("Static target")]
	public bool m_primaryTarget;

	public bool m_randomTarget = true;

	private List<Collider> m_colliders;

	private Vector3 m_localCenter;

	private bool m_haveCenter;

	public virtual bool IsPriorityTarget()
	{
		return m_primaryTarget;
	}

	public virtual bool IsRandomTarget()
	{
		return m_randomTarget;
	}

	public Vector3 GetCenter()
	{
		if (!m_haveCenter)
		{
			List<Collider> allColliders = GetAllColliders();
			m_localCenter = Vector3.zero;
			foreach (Collider item in allColliders)
			{
				if ((bool)item)
				{
					m_localCenter += item.bounds.center;
				}
			}
			m_localCenter /= (float)m_colliders.Count;
			m_localCenter = base.transform.InverseTransformPoint(m_localCenter);
			m_haveCenter = true;
		}
		return base.transform.TransformPoint(m_localCenter);
	}

	public List<Collider> GetAllColliders()
	{
		if (m_colliders == null)
		{
			Collider[] componentsInChildren = GetComponentsInChildren<Collider>();
			m_colliders = new List<Collider>();
			m_colliders.Capacity = componentsInChildren.Length;
			Collider[] array = componentsInChildren;
			foreach (Collider collider in array)
			{
				if (collider.enabled && collider.gameObject.activeInHierarchy && !collider.isTrigger)
				{
					m_colliders.Add(collider);
				}
			}
		}
		return m_colliders;
	}

	public Vector3 FindClosestPoint(Vector3 point)
	{
		List<Collider> allColliders = GetAllColliders();
		if (allColliders.Count == 0)
		{
			return base.transform.position;
		}
		float num = 9999999f;
		Vector3 result = Vector3.zero;
		foreach (Collider item in allColliders)
		{
			if ((bool)item)
			{
				MeshCollider meshCollider = item as MeshCollider;
				Vector3 vector = (((bool)meshCollider && !meshCollider.convex) ? item.ClosestPointOnBounds(point) : item.ClosestPoint(point));
				float num2 = Vector3.Distance(point, vector);
				if (num2 < num)
				{
					result = vector;
					num = num2;
				}
			}
		}
		return result;
	}
}
