using System;
using System.Collections.Generic;
using NetworkingUtils;
using Splatform;
using Steamworks;

public class SteamworksMatchmaking : IMatchmakingBackend, IDisposable
{
	private const double c_timeoutSeconds = 5.0;

	private Dictionary<ServerJoinDataSteamUser, ServerMatchmakingData> m_matchmakingDataCacheSteamUser = new Dictionary<ServerJoinDataSteamUser, ServerMatchmakingData>();

	private Dictionary<IPEndPoint, ServerMatchmakingData> m_matchmakingDataCacheDedicated = new Dictionary<IPEndPoint, ServerMatchmakingData>();

	private int m_retrievedServerListRevision;

	private int m_eventServerListRevision;

	private List<ServerData> m_publicServerList = new List<ServerData>();

	private bool m_isRefreshingPublicServerList;

	private Dictionary<CSteamID, MatchmakingDataRetrievedHandler> m_activeUserHostedSearches = new Dictionary<CSteamID, MatchmakingDataRetrievedHandler>();

	private List<SteamworksUserHostedSearchTimeout> m_activeUserHostedSearchTimeouts = new List<SteamworksUserHostedSearchTimeout>();

	private ServerJoinData m_activeDedicatedSearch = ServerJoinData.None;

	private MatchmakingDataRetrievedHandler m_activeDedicatedSearchCallback;

	public bool IsAvailable => true;

	public uint PublicServerCount => (uint)ZSteamMatchmaking.instance.GetTotalNrOfServers();

	public IReadOnlyList<ServerData> FilteredPublicServerList
	{
		get
		{
			ZSteamMatchmaking.instance.SetFriendFilter(enabled: false);
			if (ZSteamMatchmaking.instance.GetServerListRevision(ref m_retrievedServerListRevision))
			{
				m_publicServerList.Clear();
				ZSteamMatchmaking.instance.GetServers(m_publicServerList);
			}
			return m_publicServerList;
		}
	}

	public bool ServerSideFiltering => false;

	public bool IsRefreshingPublicServerList => m_isRefreshingPublicServerList;

	public event PublicServerListUpdatedHandler FilteredPublicServerListUpdated;

	public void Dispose()
	{
		for (int i = 0; i < m_activeUserHostedSearchTimeouts.Count; i++)
		{
			if (m_activeUserHostedSearches.ContainsKey(m_activeUserHostedSearchTimeouts[i].m_server.m_joinUserID))
			{
				ZSteamMatchmaking.instance.AbortCheckIfOnlineAsync(m_activeUserHostedSearchTimeouts[i].m_server);
			}
		}
		m_activeUserHostedSearchTimeouts.Clear();
	}

	public void RefreshPublicServerList(RefreshPublicServerListFlags flags)
	{
		m_publicServerList.Clear();
		m_retrievedServerListRevision = 0;
		m_eventServerListRevision = 0;
		ZSteamMatchmaking.instance.RequestServerlist();
		this.FilteredPublicServerListUpdated?.Invoke();
	}

	public void SetPublicServerListFilter(string filter)
	{
		ZSteamMatchmaking.instance.SetNameFilter(filter);
	}

	public bool CanRefreshServerNow()
	{
		return IsAvailable;
	}

	public bool CanRefreshServerOfTypeNow(ServerJoinDataType type)
	{
		return type switch
		{
			ServerJoinDataType.SteamUser => true, 
			ServerJoinDataType.Dedicated => !m_activeDedicatedSearch.IsValid, 
			_ => false, 
		};
	}

	public bool RefreshServer(ServerJoinData server, MatchmakingDataRetrievedHandler completedCallback)
	{
		if (!server.IsValid)
		{
			throw new ArgumentException("server was invalid!");
		}
		if (!CanRefreshServerOfTypeNow(server.m_type))
		{
			return false;
		}
		switch (server.m_type)
		{
		case ServerJoinDataType.SteamUser:
		{
			if (m_activeUserHostedSearches.TryGetValue(server.SteamUser.m_joinUserID, out var value))
			{
				value = (MatchmakingDataRetrievedHandler)Delegate.Combine(value, completedCallback);
				break;
			}
			m_activeUserHostedSearches.Add(server.SteamUser.m_joinUserID, completedCallback);
			m_activeUserHostedSearchTimeouts.Add(new SteamworksUserHostedSearchTimeout(server.SteamUser, DateTime.UtcNow));
			ZSteamMatchmaking.instance.CheckIfOnlineAsync(server.SteamUser, OnServerPingCompleted);
			break;
		}
		case ServerJoinDataType.Dedicated:
		{
			if (!MultiBackendMatchmaking.GetServerIPCached(server.Dedicated, out var address))
			{
				return false;
			}
			m_activeDedicatedSearch = server;
			m_activeDedicatedSearchCallback = completedCallback;
			if (address.HasValue)
			{
				ZSteamMatchmaking.instance.CheckIfOnlineAsync(new IPEndPoint(address.Value, m_activeDedicatedSearch.Dedicated.m_port), OnServerPingCompleted);
			}
			else
			{
				OnServerPingCompleted(new ServerData(m_activeDedicatedSearch, new ServerMatchmakingData(DateTime.UtcNow)));
			}
			break;
		}
		default:
			return false;
		}
		return true;
	}

	public bool IsPending(ServerJoinData server)
	{
		return server.m_type switch
		{
			ServerJoinDataType.SteamUser => m_activeUserHostedSearches.ContainsKey(server.SteamUser.m_joinUserID), 
			ServerJoinDataType.Dedicated => m_activeDedicatedSearch == server, 
			_ => false, 
		};
	}

	public ServerMatchmakingData GetServerMatchmakingData(ServerJoinData server, DateTime newerThanUtc = default(DateTime))
	{
		if (!server.IsValid)
		{
			throw new ArgumentException("server was invalid");
		}
		ServerMatchmakingData value;
		switch (server.m_type)
		{
		case ServerJoinDataType.SteamUser:
			if (!m_matchmakingDataCacheSteamUser.TryGetValue(server.SteamUser, out value))
			{
				return ServerMatchmakingData.None;
			}
			break;
		case ServerJoinDataType.Dedicated:
		{
			if (!MultiBackendMatchmaking.GetServerIPCached(server.Dedicated, out var address))
			{
				return ServerMatchmakingData.None;
			}
			if (!address.HasValue)
			{
				return new ServerMatchmakingData(newerThanUtc.AddTicks(1L));
			}
			if (!address.Value.IsPublic())
			{
				return new ServerMatchmakingData(newerThanUtc.AddTicks(1L));
			}
			if (!m_matchmakingDataCacheDedicated.TryGetValue(new IPEndPoint(address.Value, server.Dedicated.m_port), out value))
			{
				return ServerMatchmakingData.None;
			}
			break;
		}
		default:
			return new ServerMatchmakingData(newerThanUtc.AddTicks(1L));
		}
		if (value.m_timestampUtc <= newerThanUtc)
		{
			return ServerMatchmakingData.None;
		}
		return value;
	}

	public void Tick()
	{
		if (ZSteamMatchmaking.instance.GetServerListRevision(ref m_eventServerListRevision))
		{
			this.FilteredPublicServerListUpdated?.Invoke();
		}
		CheckServerSearchTimeouts();
	}

	private void CheckServerSearchTimeouts()
	{
		DateTime dateTime = DateTime.UtcNow.AddSeconds(-5.0);
		int num = 0;
		while (num < m_activeUserHostedSearchTimeouts.Count)
		{
			SteamworksUserHostedSearchTimeout steamworksUserHostedSearchTimeout = m_activeUserHostedSearchTimeouts[num];
			if (!(steamworksUserHostedSearchTimeout.m_refreshStartTimeUtc >= dateTime))
			{
				m_activeUserHostedSearchTimeouts.RemoveAt(num);
				num--;
				if (m_activeUserHostedSearches.ContainsKey(steamworksUserHostedSearchTimeout.m_server.m_joinUserID))
				{
					ZSteamMatchmaking.instance.AbortCheckIfOnlineAsync(steamworksUserHostedSearchTimeout.m_server);
				}
				num++;
				continue;
			}
			break;
		}
	}

	private void OnServerPingCompleted(ServerData serverData)
	{
		switch (serverData.m_joinData.m_type)
		{
		case ServerJoinDataType.SteamUser:
		{
			if (!m_activeUserHostedSearches.TryGetValue(serverData.m_joinData.SteamUser.m_joinUserID, out var value))
			{
				ZLog.LogError($"Got ping completed callback for user {serverData.m_joinData.SteamUser} which wasn't currently an active search!");
				break;
			}
			m_activeUserHostedSearches.Remove(serverData.m_joinData.SteamUser.m_joinUserID);
			RemoveTimeout(serverData.m_joinData.SteamUser);
			m_matchmakingDataCacheSteamUser[serverData.m_joinData.SteamUser] = serverData.m_matchmakingData;
			value?.Invoke(serverData);
			break;
		}
		case ServerJoinDataType.Dedicated:
		{
			if (!m_activeDedicatedSearch.IsValid)
			{
				ZLog.LogError("Current was invalid!");
				break;
			}
			if (m_activeDedicatedSearch != serverData.m_joinData)
			{
				ZLog.LogError("Current did not match!");
				break;
			}
			if (!serverData.m_joinData.Dedicated.TryGetIPEndPoint(out var endPoint))
			{
				ZLog.LogError("Failed to get IP endpoint!");
				break;
			}
			m_matchmakingDataCacheDedicated[endPoint] = serverData.m_matchmakingData;
			MatchmakingDataRetrievedHandler activeDedicatedSearchCallback = m_activeDedicatedSearchCallback;
			m_activeDedicatedSearch = ServerJoinData.None;
			m_activeDedicatedSearchCallback = null;
			activeDedicatedSearchCallback?.Invoke(serverData);
			break;
		}
		default:
		{
			ZLog.LogWarning($"Got back unexpected join data type {serverData.m_joinData.m_type}");
			if (serverData.m_matchmakingData.m_hostUser.m_platform != PlatformManager.DistributionPlatform.Platform)
			{
				ZLog.LogError($"User {serverData.m_matchmakingData.m_hostUser} was from unexpected platform {serverData.m_matchmakingData.m_hostUser.m_platform}");
				break;
			}
			if (!serverData.m_matchmakingData.m_hostUser.TryParseAsUInt64(out var result))
			{
				ZLog.LogError($"User {serverData.m_matchmakingData.m_hostUser} couldn't be parsed as a Steam ID!");
				break;
			}
			CSteamID cSteamID = new CSteamID(result);
			if (!m_activeUserHostedSearches.Remove(cSteamID))
			{
				ZLog.LogError("Failed to remove invalid entry from user hosted servers!");
				break;
			}
			ServerJoinDataSteamUser serverJoinDataSteamUser = new ServerJoinDataSteamUser(cSteamID);
			RemoveTimeout(serverJoinDataSteamUser);
			m_matchmakingDataCacheSteamUser[serverJoinDataSteamUser] = new ServerMatchmakingData(DateTime.UtcNow);
			break;
		}
		}
	}

	private void RemoveTimeout(ServerJoinDataSteamUser joinData)
	{
		for (int i = 0; i < m_activeUserHostedSearchTimeouts.Count; i++)
		{
			if (m_activeUserHostedSearchTimeouts[i].m_server == joinData)
			{
				m_activeUserHostedSearchTimeouts.RemoveAt(i);
				break;
			}
		}
	}
}
using System;

public struct SteamworksUserHostedSearchTimeout(ServerJoinDataSteamUser server, DateTime refreshStartTimeUtc)
{
	public ServerJoinDataSteamUser m_server = server;

	public DateTime m_refreshStartTimeUtc = refreshStartTimeUtc;
}
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

public class StoreGui : MonoBehaviour
{
	private static StoreGui m_instance;

	public GameObject m_rootPanel;

	public Button m_buyButton;

	public Button m_sellButton;

	public RectTransform m_listRoot;

	public GameObject m_listElement;

	public Scrollbar m_listScroll;

	public ScrollRectEnsureVisible m_itemEnsureVisible;

	public TMP_Text m_coinText;

	public EffectList m_buyEffects = new EffectList();

	public EffectList m_sellEffects = new EffectList();

	public float m_hideDistance = 5f;

	public float m_itemSpacing = 64f;

	public ItemDrop m_coinPrefab;

	private List<GameObject> m_itemList = new List<GameObject>();

	private Trader.TradeItem m_selectedItem;

	private Trader m_trader;

	private float m_itemlistBaseSize;

	private int m_hiddenFrames;

	private List<ItemDrop.ItemData> m_tempItems = new List<ItemDrop.ItemData>();

	public RectTransform m_tooltipAnchor;

	public static StoreGui instance => m_instance;

	private void Awake()
	{
		m_instance = this;
		m_rootPanel.SetActive(value: false);
		m_itemlistBaseSize = m_listRoot.rect.height;
	}

	private void OnDestroy()
	{
		if (m_instance == this)
		{
			m_instance = null;
		}
	}

	private void Update()
	{
		if (!m_rootPanel.activeSelf)
		{
			m_hiddenFrames++;
			return;
		}
		m_hiddenFrames = 0;
		if (!m_trader)
		{
			Hide();
			return;
		}
		Player localPlayer = Player.m_localPlayer;
		if (localPlayer == null || localPlayer.IsDead() || localPlayer.InCutscene())
		{
			Hide();
			return;
		}
		if (Vector3.Distance(m_trader.transform.position, Player.m_localPlayer.transform.position) > m_hideDistance)
		{
			Hide();
			return;
		}
		if (InventoryGui.IsVisible() || Minimap.IsOpen())
		{
			Hide();
			return;
		}
		if ((Chat.instance == null || !Chat.instance.HasFocus()) && !Console.IsVisible() && !Menu.IsVisible() && (bool)TextViewer.instance && !TextViewer.instance.IsVisible() && !localPlayer.InCutscene() && (ZInput.GetButtonDown("JoyButtonB") || ZInput.GetKeyDown(KeyCode.Escape) || ZInput.GetButtonDown("Use")))
		{
			ZInput.ResetButtonStatus("JoyButtonB");
			Hide();
		}
		UpdateBuyButton();
		UpdateSellButton();
		UpdateRecipeGamepadInput();
		m_coinText.text = GetPlayerCoins().ToString();
	}

	public void Show(Trader trader)
	{
		if (!(m_trader == trader) || !IsVisible())
		{
			m_trader = trader;
			m_rootPanel.SetActive(value: true);
			FillList();
		}
	}

	public void Hide()
	{
		m_trader = null;
		m_rootPanel.SetActive(value: false);
	}

	public static bool IsVisible()
	{
		if ((bool)m_instance)
		{
			return m_instance.m_hiddenFrames <= 1;
		}
		return false;
	}

	public void OnBuyItem()
	{
		BuySelectedItem();
	}

	private void BuySelectedItem()
	{
		if (m_selectedItem != null && CanAfford(m_selectedItem))
		{
			int stack = Mathf.Min(m_selectedItem.m_stack, m_selectedItem.m_prefab.m_itemData.m_shared.m_maxStackSize);
			int quality = m_selectedItem.m_prefab.m_itemData.m_quality;
			int variant = m_selectedItem.m_prefab.m_itemData.m_variant;
			if (Player.m_localPlayer.GetInventory().AddItem(m_selectedItem.m_prefab.name, stack, quality, variant, 0L, "") != null)
			{
				Player.m_localPlayer.GetInventory().RemoveItem(m_coinPrefab.m_itemData.m_shared.m_name, m_selectedItem.m_price);
				m_trader.OnBought(m_selectedItem);
				m_buyEffects.Create(base.transform.position, Quaternion.identity);
				Player.m_localPlayer.ShowPickupMessage(m_selectedItem.m_prefab.m_itemData, m_selectedItem.m_prefab.m_itemData.m_stack);
				FillList();
				Gogan.LogEvent("Game", "BoughtItem", m_selectedItem.m_prefab.name, 0L);
			}
		}
	}

	public void OnSellItem()
	{
		SellItem();
	}

	private void SellItem()
	{
		ItemDrop.ItemData sellableItem = GetSellableItem();
		if (sellableItem != null)
		{
			int stack = sellableItem.m_shared.m_value * sellableItem.m_stack;
			Player.m_localPlayer.GetInventory().RemoveItem(sellableItem);
			Player.m_localPlayer.GetInventory().AddItem(m_coinPrefab.gameObject.name, stack, m_coinPrefab.m_itemData.m_quality, m_coinPrefab.m_itemData.m_variant, 0L, "");
			string text = "";
			text = ((sellableItem.m_stack <= 1) ? sellableItem.m_shared.m_name : (sellableItem.m_stack + "x" + sellableItem.m_shared.m_name));
			m_sellEffects.Create(base.transform.position, Quaternion.identity);
			Player.m_localPlayer.Message(MessageHud.MessageType.TopLeft, Localization.instance.Localize("$msg_sold", text, stack.ToString()), 0, sellableItem.m_shared.m_icons[0]);
			m_trader.OnSold();
			FillList();
			Gogan.LogEvent("Game", "SoldItem", text, 0L);
		}
	}

	private int GetPlayerCoins()
	{
		return Player.m_localPlayer.GetInventory().CountItems(m_coinPrefab.m_itemData.m_shared.m_name);
	}

	private bool CanAfford(Trader.TradeItem item)
	{
		int playerCoins = GetPlayerCoins();
		return item.m_price <= playerCoins;
	}

	private void FillList()
	{
		int playerCoins = GetPlayerCoins();
		int num = GetSelectedItemIndex();
		List<Trader.TradeItem> availableItems = m_trader.GetAvailableItems();
		foreach (GameObject item in m_itemList)
		{
			Object.Destroy(item);
		}
		m_itemList.Clear();
		float b = (float)availableItems.Count * m_itemSpacing;
		b = Mathf.Max(m_itemlistBaseSize, b);
		m_listRoot.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, b);
		for (int i = 0; i < availableItems.Count; i++)
		{
			Trader.TradeItem tradeItem = availableItems[i];
			GameObject element = Object.Instantiate(m_listElement, m_listRoot);
			element.SetActive(value: true);
			RectTransform rectTransform = element.transform as RectTransform;
			float num2 = (m_listRoot.rect.width - rectTransform.rect.width) / 2f;
			rectTransform.anchoredPosition = new Vector2(num2, (float)i * (0f - m_itemSpacing) - num2);
			bool flag = tradeItem.m_price <= playerCoins;
			Image component = element.transform.Find("icon").GetComponent<Image>();
			component.sprite = tradeItem.m_prefab.m_itemData.m_shared.m_icons[0];
			component.color = (flag ? Color.white : new Color(1f, 0f, 1f, 0f));
			string text = Localization.instance.Localize(tradeItem.m_prefab.m_itemData.m_shared.m_name);
			if (tradeItem.m_stack > 1)
			{
				text = text + " x" + tradeItem.m_stack;
			}
			TMP_Text component2 = element.transform.Find("name").GetComponent<TMP_Text>();
			component2.text = text;
			component2.color = (flag ? Color.white : Color.grey);
			element.GetComponent<UITooltip>().Set(tradeItem.m_prefab.m_itemData.m_shared.m_name, tradeItem.m_prefab.m_itemData.GetTooltip(tradeItem.m_stack), m_tooltipAnchor);
			TMP_Text component3 = Utils.FindChild(element.transform, "price").GetComponent<TMP_Text>();
			component3.text = tradeItem.m_price.ToString();
			if (!flag)
			{
				component3.color = Color.grey;
			}
			element.GetComponent<Button>().onClick.AddListener(delegate
			{
				OnSelectedItem(element);
			});
			m_itemList.Add(element);
		}
		if (num < 0)
		{
			num = 0;
		}
		SelectItem(num, center: false);
	}

	private void OnSelectedItem(GameObject button)
	{
		int index = FindSelectedRecipe(button);
		SelectItem(index, center: false);
	}

	private int FindSelectedRecipe(GameObject button)
	{
		for (int i = 0; i < m_itemList.Count; i++)
		{
			if (m_itemList[i] == button)
			{
				return i;
			}
		}
		return -1;
	}

	private void SelectItem(int index, bool center)
	{
		ZLog.Log("Setting selected recipe " + index);
		for (int i = 0; i < m_itemList.Count; i++)
		{
			bool active = i == index;
			m_itemList[i].transform.Find("selected").gameObject.SetActive(active);
		}
		if (center && index >= 0)
		{
			m_itemEnsureVisible.CenterOnItem(m_itemList[index].transform as RectTransform);
		}
		if (index < 0)
		{
			m_selectedItem = null;
		}
		else
		{
			m_selectedItem = m_trader.GetAvailableItems()[index];
		}
	}

	private void UpdateSellButton()
	{
		m_sellButton.interactable = GetSellableItem() != null;
	}

	private ItemDrop.ItemData GetSellableItem()
	{
		m_tempItems.Clear();
		Player.m_localPlayer.GetInventory().GetValuableItems(m_tempItems);
		foreach (ItemDrop.ItemData tempItem in m_tempItems)
		{
			if (tempItem.m_shared.m_name != m_coinPrefab.m_itemData.m_shared.m_name)
			{
				return tempItem;
			}
		}
		return null;
	}

	private int GetSelectedItemIndex()
	{
		int result = 0;
		List<Trader.TradeItem> availableItems = m_trader.GetAvailableItems();
		for (int i = 0; i < availableItems.Count; i++)
		{
			if (availableItems[i] == m_selectedItem)
			{
				result = i;
			}
		}
		return result;
	}

	private void UpdateBuyButton()
	{
		UITooltip component = m_buyButton.GetComponent<UITooltip>();
		if (m_selectedItem != null)
		{
			bool flag = CanAfford(m_selectedItem);
			bool flag2 = Player.m_localPlayer.GetInventory().HaveEmptySlot();
			m_buyButton.interactable = flag && flag2;
			if (!flag)
			{
				component.m_text = Localization.instance.Localize("$msg_missingrequirement");
			}
			else if (!flag2)
			{
				component.m_text = Localization.instance.Localize("$inventory_full");
			}
			else
			{
				component.m_text = "";
			}
		}
		else
		{
			m_buyButton.interactable = false;
			component.m_text = "";
		}
	}

	private void UpdateRecipeGamepadInput()
	{
		if (m_itemList.Count > 0)
		{
			if (ZInput.GetButtonDown("JoyLStickDown") || ZInput.GetButtonDown("JoyDPadDown"))
			{
				SelectItem(Mathf.Min(m_itemList.Count - 1, GetSelectedItemIndex() + 1), center: true);
			}
			if (ZInput.GetButtonDown("JoyLStickUp") || ZInput.GetButtonDown("JoyDPadUp"))
			{
				SelectItem(Mathf.Max(0, GetSelectedItemIndex() - 1), center: true);
			}
		}
	}
}
using System;
using PlayFab.Party;
using Splatform;
using UnityEngine.SceneManagement;

public class SuspendManager
{
	private static SuspendManager s_instance;

	public static void Initialize()
	{
		if (s_instance != null)
		{
			ZLog.LogError("SuspendManager already initialized!");
		}
		else
		{
			s_instance = new SuspendManager();
		}
	}

	private SuspendManager()
	{
		IPLMProvider pLMProvider = PlatformManager.DistributionPlatform.PLMProvider;
		if (pLMProvider == null)
		{
			ZLog.Log("Platform doesn't implement Process Lifetime Management! Don't initialize suspend manager.");
			s_instance = null;
			return;
		}
		pLMProvider.EnteringSuspend += OnEnteringSuspend;
		pLMProvider.LeavingSuspend += OnLeavingSuspend;
		pLMProvider.ResumedFromSuspend += OnResumedFromSuspend;
		pLMProvider.IsRunningInBackgroundChanged += OnIsRunningInBackgroundChanged;
	}

	private void OnEnteringSuspend(DateTime deadlineUtc)
	{
		if (Game.instance != null && !ZNet.IsSinglePlayer)
		{
			ZNetScene.instance.Shutdown();
			ZNet.instance.ShutdownWithoutSave(suspending: true);
		}
		PlayFabMultiplayerManager.Get().Suspend();
	}

	private void OnLeavingSuspend()
	{
		if (!(Game.instance == null))
		{
			bool num = ZNet.instance != null && ZNet.instance.IsServer();
			bool flag = ZNet.IsOpenServer();
			if (num == flag)
			{
				SceneManager.sceneLoaded += OnMainMenuAfterResume;
				Game.instance.Logout();
			}
		}
	}

	private void OnResumedFromSuspend()
	{
		if (PlatformManager.DistributionPlatform.PLMProvider.SupportedSuspendEvents.HasFlag(SuspendEvents.EnteringSuspend))
		{
			PlayFabMultiplayerManager.Get().Resume();
		}
	}

	private void OnMainMenuAfterResume(Scene scene, LoadSceneMode mode)
	{
		SceneManager.sceneLoaded -= OnMainMenuAfterResume;
		if (UnifiedPopup.IsAvailable() && !UnifiedPopup.IsVisible())
		{
			string text = "$online_kickedfromsession_suspendresume_xbox_text";
			UnifiedPopup.Push(new WarningPopup("$online_kickedfromsession_header", text, delegate
			{
				UnifiedPopup.Pop();
			}));
		}
	}

	private void OnIsRunningInBackgroundChanged(bool isRunningInBackground)
	{
		if (Minimap.instance != null)
		{
			Minimap.instance.PauseUpdateTemporarily();
		}
	}
}
using UnityEngine;

public class Switch : MonoBehaviour, Interactable, Hoverable
{
	public delegate bool Callback(Switch caller, Humanoid user, ItemDrop.ItemData item);

	public delegate string TooltipCallback();

	public Callback m_onUse;

	public TooltipCallback m_onHover;

	[TextArea(3, 20)]
	public string m_hoverText = "";

	public string m_name = "";

	public float m_holdRepeatInterval = -1f;

	private float m_lastUseTime;

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			if (m_holdRepeatInterval <= 0f)
			{
				return false;
			}
			if (Time.time - m_lastUseTime < m_holdRepeatInterval)
			{
				return false;
			}
		}
		m_lastUseTime = Time.time;
		if (m_onUse != null)
		{
			return m_onUse(this, character, null);
		}
		return false;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		if (m_onUse != null)
		{
			return m_onUse(this, user, item);
		}
		return false;
	}

	public string GetHoverText()
	{
		if (m_onHover != null)
		{
			return m_onHover();
		}
		return Localization.instance.Localize(m_hoverText);
	}

	public string GetHoverName()
	{
		return Localization.instance.Localize(m_name);
	}
}
using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

public class TabHandler : MonoBehaviour
{
	[Serializable]
	public class Tab
	{
		public Button m_button;

		public RectTransform m_page;

		public bool m_default;

		public UnityEvent m_onClick;
	}

	public bool m_cycling = true;

	public bool m_tabKeyInput = true;

	public bool m_keybaordInput;

	public string m_keyboardNavigateLeft = "TabLeft";

	public string m_keyboardNavigateRight = "TabRight";

	public bool m_gamepadInput;

	public string m_gamepadNavigateLeft = "JoyTabLeft";

	public string m_gamepadNavigateRight = "JoyTabRight";

	private bool m_activeTabEverSet;

	public List<Tab> m_tabs = new List<Tab>();

	public List<GameObject> m_blockingElements = new List<GameObject>();

	[Header("Effects")]
	public EffectList m_setActiveTabEffects = new EffectList();

	private int m_selected;

	private UIGamePad gamePad;

	public event Action<int> ActiveTabChanged;

	private void Start()
	{
		Init(forceSelect: true);
	}

	public void Init(bool forceSelect = false)
	{
		int num = -1;
		for (int i = 0; i < m_tabs.Count; i++)
		{
			Tab tab = m_tabs[i];
			if (!tab.m_button)
			{
				continue;
			}
			tab.m_button.onClick.AddListener(delegate
			{
				OnClick(tab.m_button);
			});
			Transform transform = tab.m_button.gameObject.transform.Find("Selected");
			if ((bool)transform)
			{
				TMP_Text componentInChildren = transform.GetComponentInChildren<TMP_Text>();
				TMP_Text componentInChildren2 = tab.m_button.GetComponentInChildren<TMP_Text>();
				string text = null;
				if (componentInChildren2 != null)
				{
					text = componentInChildren2.text;
				}
				else
				{
					TextMeshProUGUI componentInChildren3 = tab.m_button.GetComponentInChildren<TextMeshProUGUI>();
					if (componentInChildren3 != null)
					{
						text = componentInChildren3.text;
					}
				}
				if (componentInChildren != null)
				{
					componentInChildren.text = text;
				}
				else
				{
					TextMeshProUGUI componentInChildren4 = transform.GetComponentInChildren<TextMeshProUGUI>();
					if (componentInChildren4 != null)
					{
						componentInChildren4.text = text;
					}
				}
			}
			if (tab.m_default)
			{
				num = i;
			}
		}
		if (!m_activeTabEverSet && num >= 0)
		{
			SetActiveTab(num, forceSelect);
		}
		gamePad = GetComponent<UIGamePad>();
	}

	private void Update()
	{
		if (UnifiedPopup.IsVisible())
		{
			return;
		}
		if (m_blockingElements.Count > 0)
		{
			foreach (GameObject blockingElement in m_blockingElements)
			{
				if (blockingElement.activeSelf)
				{
					return;
				}
			}
		}
		int num = 0;
		if (m_gamepadInput && (gamePad == null || !gamePad.IsBlocked()))
		{
			if (!string.IsNullOrEmpty(m_gamepadNavigateLeft) && ZInput.GetButtonDown(m_gamepadNavigateLeft))
			{
				num = -1;
			}
			else if (!string.IsNullOrEmpty(m_gamepadNavigateRight) && ZInput.GetButtonDown(m_gamepadNavigateRight))
			{
				num = 1;
			}
		}
		if (m_keybaordInput)
		{
			if (!string.IsNullOrEmpty(m_keyboardNavigateLeft) && ZInput.GetButtonDown(m_keyboardNavigateLeft))
			{
				num = -1;
			}
			else if (!string.IsNullOrEmpty(m_keyboardNavigateRight) && ZInput.GetButtonDown(m_keyboardNavigateRight))
			{
				num = 1;
			}
		}
		if (m_tabKeyInput && ZInput.GetKeyDown(KeyCode.Tab))
		{
			num = 1;
		}
		if (num == 0)
		{
			return;
		}
		int num2 = m_selected + num;
		if (m_cycling)
		{
			if (num2 < 0)
			{
				num2 = m_tabs.Count - 1;
			}
			else if (num2 > m_tabs.Count - 1)
			{
				num2 = 0;
			}
			if (!m_tabs[num2].m_button)
			{
				for (int i = num2 + num; i <= m_tabs.Count && i != num2; i += num)
				{
					if (i >= m_tabs.Count)
					{
						i = 0;
					}
					if ((bool)m_tabs[i].m_button)
					{
						SetActiveTab(i);
						break;
					}
				}
			}
			else
			{
				SetActiveTab(num2);
			}
		}
		else
		{
			SetActiveTab(Math.Max(0, Math.Min(m_tabs.Count - 1, num2)));
		}
	}

	private void OnClick(Button button)
	{
		SetActiveTab(button);
	}

	private void SetActiveTab(Button button)
	{
		for (int i = 0; i < m_tabs.Count; i++)
		{
			if (!(m_tabs[i].m_button == null) && !(m_tabs[i].m_button != button))
			{
				SetActiveTab(i);
				break;
			}
		}
	}

	public void SetActiveTab(int index, bool forceSelect = false, bool invokeOnClick = true)
	{
		m_activeTabEverSet = true;
		if (!forceSelect && m_selected == index)
		{
			return;
		}
		m_selected = (m_tabs[index].m_button ? index : m_selected);
		for (int i = 0; i < m_tabs.Count; i++)
		{
			Tab tab = m_tabs[i];
			bool flag = i == index;
			if (tab.m_page != null)
			{
				tab.m_page.gameObject.SetActive(flag);
			}
			if ((bool)tab.m_button)
			{
				tab.m_button.interactable = !flag;
				Transform transform = tab.m_button.gameObject.transform.Find("Selected");
				if ((bool)transform)
				{
					transform.gameObject.SetActive(i == m_selected);
				}
				if (flag && invokeOnClick)
				{
					tab.m_onClick?.Invoke();
				}
			}
		}
		if (ZInput.IsGamepadActive())
		{
			m_setActiveTabEffects?.Create((Player.m_localPlayer != null) ? Player.m_localPlayer.transform.position : Vector3.zero, Quaternion.identity);
		}
		this.ActiveTabChanged?.Invoke(index);
	}

	public void SetActiveTabWithoutInvokingOnClick(int index)
	{
		m_selected = (m_tabs[index].m_button ? index : m_selected);
		for (int i = 0; i < m_tabs.Count; i++)
		{
			Tab tab = m_tabs[i];
			bool flag = i == index;
			if (tab.m_page != null)
			{
				tab.m_page.gameObject.SetActive(flag);
			}
			if ((bool)tab.m_button)
			{
				tab.m_button.interactable = !flag;
				Transform transform = tab.m_button.gameObject.transform.Find("Selected");
				if ((bool)transform)
				{
					transform.gameObject.SetActive(i == m_selected);
				}
			}
		}
		this.ActiveTabChanged?.Invoke(index);
	}

	public int GetActiveTab()
	{
		return m_selected;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Tail : MonoBehaviour, IMonoUpdater
{
	private class TailSegment
	{
		public Transform transform;

		public Vector3 pos;

		public Quaternion rot;

		public float distance;
	}

	public List<Transform> m_tailJoints = new List<Transform>();

	public float m_maxAngle = 80f;

	public float m_gravity = 2f;

	public float m_gravityInWater = 0.1f;

	public bool m_waterSurfaceCheck;

	public bool m_groundCheck;

	public float m_smoothness = 0.1f;

	public float m_tailRadius;

	public Character m_character;

	public Rigidbody m_characterBody;

	public Rigidbody m_tailBody;

	private readonly List<TailSegment> m_positions = new List<TailSegment>();

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	private void Awake()
	{
		foreach (Transform tailJoint in m_tailJoints)
		{
			float distance = Vector3.Distance(tailJoint.parent.position, tailJoint.position);
			Vector3 position = tailJoint.position;
			TailSegment tailSegment = new TailSegment();
			tailSegment.transform = tailJoint;
			tailSegment.pos = position;
			tailSegment.rot = tailJoint.rotation;
			tailSegment.distance = distance;
			m_positions.Add(tailSegment);
		}
	}

	private void OnEnable()
	{
		Instances.Add(this);
	}

	private void OnDisable()
	{
		Instances.Remove(this);
	}

	public void CustomLateUpdate(float dt)
	{
		for (int i = 0; i < m_positions.Count; i++)
		{
			TailSegment tailSegment = m_positions[i];
			if (m_waterSurfaceCheck)
			{
				float liquidLevel = Floating.GetLiquidLevel(tailSegment.pos);
				if (tailSegment.pos.y + m_tailRadius > liquidLevel)
				{
					tailSegment.pos.y -= m_gravity * dt;
				}
				else
				{
					tailSegment.pos.y -= m_gravityInWater * dt;
				}
			}
			else
			{
				tailSegment.pos.y -= m_gravity * dt;
			}
			Vector3 vector = tailSegment.transform.parent.position + tailSegment.transform.parent.up * tailSegment.distance * 0.5f;
			Vector3 target = Vector3.Normalize(vector - tailSegment.pos);
			target = Vector3.RotateTowards(-tailSegment.transform.parent.up, target, MathF.PI / 180f * m_maxAngle, 1f);
			Vector3 vector2 = vector - target * tailSegment.distance * 0.5f;
			if (m_groundCheck)
			{
				float groundHeight = ZoneSystem.instance.GetGroundHeight(vector2);
				if (vector2.y - m_tailRadius < groundHeight)
				{
					vector2.y = groundHeight + m_tailRadius;
				}
			}
			vector2 = Vector3.Lerp(tailSegment.pos, vector2, m_smoothness);
			if (vector == vector2)
			{
				break;
			}
			Vector3 normalized = (vector - vector2).normalized;
			Vector3 rhs = Vector3.Cross(Vector3.up, -normalized);
			Quaternion b = Quaternion.LookRotation(Vector3.Cross(-normalized, rhs), -normalized);
			b = Quaternion.Slerp(tailSegment.rot, b, m_smoothness);
			tailSegment.transform.position = vector2;
			tailSegment.transform.rotation = b;
			tailSegment.pos = vector2;
			tailSegment.rot = b;
		}
	}
}
using UnityEngine;

public class Talker : MonoBehaviour
{
	public enum Type
	{
		Whisper,
		Normal,
		Shout,
		Ping
	}

	public float m_visperDistance = 4f;

	public float m_normalDistance = 15f;

	public float m_shoutDistance = 70f;

	private ZNetView m_nview;

	private Character m_character;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_character = GetComponent<Character>();
		m_nview.Register<int, UserInfo, string>("Say", RPC_Say);
	}

	public void Say(Type type, string text)
	{
		ZLog.Log("Saying " + type.ToString() + "  " + text);
		Chat.CheckPermissionsAndSendChatMessageRPCsAsync(delegate(long user, bool filterText)
		{
			Chat.GetChatMessageData(text, filterText, out var userInfoToSend, out var textToSend);
			m_nview.InvokeRPC(user, "Say", (int)type, userInfoToSend, textToSend);
		});
	}

	private void RPC_Say(long sender, int ctype, UserInfo user, string text)
	{
		if (!(Player.m_localPlayer == null))
		{
			float num = 0f;
			switch (ctype)
			{
			case 0:
				num = m_visperDistance;
				break;
			case 1:
				num = m_normalDistance;
				break;
			case 2:
				num = m_shoutDistance;
				break;
			}
			if (Vector3.Distance(base.transform.position, Player.m_localPlayer.transform.position) < num && (bool)Chat.instance)
			{
				Vector3 headPoint = m_character.GetHeadPoint();
				Chat.instance.OnNewChatMessage(base.gameObject, sender, headPoint, (Type)ctype, user, text);
			}
		}
	}
}
using System;
using System.Collections.Generic;
using Splatform;
using UnityEngine;

public class Tameable : MonoBehaviour, Interactable, TextReceiver
{
	public delegate string TextGetter();

	private const float m_playerMaxDistance = 15f;

	private const float m_tameDeltaTime = 3f;

	private static List<Player> s_nearbyPlayers = new List<Player>();

	public float m_fedDuration = 30f;

	public float m_tamingTime = 1800f;

	public bool m_startsTamed;

	public EffectList m_tamedEffect = new EffectList();

	public EffectList m_sootheEffect = new EffectList();

	public EffectList m_petEffect = new EffectList();

	public bool m_commandable;

	public float m_unsummonDistance;

	public float m_unsummonOnOwnerLogoutSeconds;

	public EffectList m_unSummonEffect = new EffectList();

	public Skills.SkillType m_levelUpOwnerSkill;

	public float m_levelUpFactor = 1f;

	public ItemDrop m_saddleItem;

	public Sadle m_saddle;

	public bool m_dropSaddleOnDeath = true;

	public Vector3 m_dropSaddleOffset = new Vector3(0f, 1f, 0f);

	public float m_dropItemVel = 5f;

	public List<string> m_randomStartingName = new List<string>();

	public float m_tamingSpeedMultiplierRange = 60f;

	public float m_tamingBoostMultiplier = 2f;

	public bool m_nameBeforeText = true;

	public string m_tameText = "$hud_tamelove";

	public TextGetter m_tameTextGetter;

	private Character m_character;

	private MonsterAI m_monsterAI;

	private Piece m_piece;

	private ZNetView m_nview;

	private float m_lastPetTime;

	private float m_unsummonTime;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_character = GetComponent<Character>();
		m_monsterAI = GetComponent<MonsterAI>();
		m_piece = GetComponent<Piece>();
		if ((bool)m_character)
		{
			Character character = m_character;
			character.m_onDeath = (Action)Delegate.Combine(character.m_onDeath, new Action(OnDeath));
		}
		if ((bool)m_monsterAI)
		{
			MonsterAI monsterAI = m_monsterAI;
			monsterAI.m_onConsumedItem = (Action<ItemDrop>)Delegate.Combine(monsterAI.m_onConsumedItem, new Action<ItemDrop>(OnConsumedItem));
		}
		if (m_nview.IsValid())
		{
			m_nview.Register<ZDOID, bool>("Command", RPC_Command);
			m_nview.Register<string, string>("SetName", RPC_SetName);
			m_nview.Register("RPC_UnSummon", RPC_UnSummon);
			if (m_saddle != null)
			{
				m_nview.Register("AddSaddle", RPC_AddSaddle);
				m_nview.Register<bool>("SetSaddle", RPC_SetSaddle);
				SetSaddle(HaveSaddle());
			}
			InvokeRepeating("TamingUpdate", 3f, 3f);
		}
		if (m_startsTamed && (bool)m_character)
		{
			m_character.SetTamed(tamed: true);
		}
		if (m_randomStartingName.Count > 0 && m_nview.IsValid() && m_nview.GetZDO().GetString(ZDOVars.s_tamedName).Length == 0)
		{
			SetText(Localization.instance.Localize(m_randomStartingName[UnityEngine.Random.Range(0, m_randomStartingName.Count)]));
		}
	}

	public void Update()
	{
		UpdateSummon();
		UpdateSavedFollowTarget();
	}

	public string GetHoverText()
	{
		if (!m_nview.IsValid())
		{
			return "";
		}
		string text = GetName();
		if (IsTamed())
		{
			if ((bool)m_character)
			{
				text += Localization.instance.Localize(" ( $hud_tame, " + GetStatusString() + " )");
			}
			text += Localization.instance.Localize("\n[<color=yellow><b>$KEY_Use</b></color>] $hud_pet");
			if (ZInput.IsNonClassicFunctionality() && ZInput.IsGamepadActive())
			{
				return text + Localization.instance.Localize("\n[<color=yellow><b>$KEY_AltKeys + $KEY_Use</b></color>] $hud_rename");
			}
			return text + Localization.instance.Localize("\n[<color=yellow><b>$KEY_AltPlace + $KEY_Use</b></color>] $hud_rename");
		}
		int tameness = GetTameness();
		if (tameness <= 0)
		{
			return text + Localization.instance.Localize(" ( $hud_wild, " + GetStatusString() + " )");
		}
		return text + Localization.instance.Localize(" ( $hud_tameness  " + tameness + "%, " + GetStatusString() + " )");
	}

	public string GetStatusString()
	{
		if ((bool)m_monsterAI && m_monsterAI.IsAlerted())
		{
			return "$hud_tamefrightened";
		}
		if (IsHungry())
		{
			return "$hud_tamehungry";
		}
		if (!m_character || m_character.IsTamed())
		{
			return "$hud_tamehappy";
		}
		return "$hud_tameinprogress";
	}

	public bool IsTamed()
	{
		if (!m_character || !m_character.IsTamed())
		{
			return m_startsTamed;
		}
		return true;
	}

	public string GetName()
	{
		return Localization.instance.Localize(m_character ? m_character.m_name : (((bool)m_nview && m_nview.IsValid()) ? m_nview.GetZDO().GetString(ZDOVars.s_tamedName, m_piece.m_name) : m_piece.m_name));
	}

	public bool Interact(Humanoid user, bool hold, bool alt)
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		if (hold)
		{
			return false;
		}
		if (alt)
		{
			SetName();
			return true;
		}
		string hoverName = GetHoverName();
		object msg;
		if (IsTamed())
		{
			if (Time.time - m_lastPetTime > 1f)
			{
				m_lastPetTime = Time.time;
				m_petEffect.Create(base.transform.position, base.transform.rotation);
				if (m_commandable)
				{
					Command(user);
					goto IL_00da;
				}
				if (m_tameTextGetter != null)
				{
					string text = m_tameTextGetter();
					if (text != null && text.Length > 0)
					{
						msg = text;
						goto IL_00d3;
					}
				}
				msg = (m_nameBeforeText ? (hoverName + " " + m_tameText) : m_tameText);
				goto IL_00d3;
			}
			return false;
		}
		return false;
		IL_00da:
		return true;
		IL_00d3:
		user.Message(MessageHud.MessageType.Center, (string)msg);
		goto IL_00da;
	}

	public string GetHoverName()
	{
		if (IsTamed())
		{
			string text = GetText().RemoveRichTextTags();
			if (text.Length > 0)
			{
				return text;
			}
			return GetName();
		}
		return GetName();
	}

	private void SetName()
	{
		if (!IsTamed())
		{
			return;
		}
		PrivilegeResult privilegeResult = PlatformManager.DistributionPlatform.PrivilegeProvider.CheckPrivilege(Privilege.ViewUserGeneratedContent);
		if (!privilegeResult.IsGranted())
		{
			if (PlatformManager.DistributionPlatform.UIProvider.ResolvePrivilege != null)
			{
				PlatformManager.DistributionPlatform.UIProvider.ResolvePrivilege.Open(Privilege.ViewUserGeneratedContent);
				if (!PlatformManager.DistributionPlatform.UIProvider.ResolvePrivilege.IsOpen)
				{
					ZLog.LogError(string.Format("{0} can't resolve the {1} privilege on this platform, which was denied with result {2}. Tameable rename was blocked without meaningful feedback to the user!", "ResolvePrivilegeUI", Privilege.ViewUserGeneratedContent, privilegeResult));
				}
			}
			else
			{
				ZLog.LogError(string.Format("{0} is not available on this platform to resolve the {1} privilege, which was denied with result {2}. Tameable rename was blocked without meaningful feedback to the user!", "ResolvePrivilegeUI", Privilege.ViewUserGeneratedContent, privilegeResult));
			}
		}
		else
		{
			TextInput.instance.RequestText(this, "$hud_rename", 10);
		}
	}

	public string GetText()
	{
		if (!m_nview.IsValid())
		{
			return "";
		}
		string text = m_nview.GetZDO().GetString(ZDOVars.s_tamedName);
		string resolvedAuthor = m_nview.GetZDO().GetString(ZDOVars.s_tamedNameAuthor, null);
		if (m_nview.IsOwner() && RelationsManager.UpdateAuthorIfHost(resolvedAuthor, ref resolvedAuthor))
		{
			m_nview.GetZDO().Set(ZDOVars.s_tamedNameAuthor, resolvedAuthor);
		}
		if (string.IsNullOrEmpty(resolvedAuthor) || resolvedAuthor == "host")
		{
			return CensorShittyWords.FilterUGC(text, UGCType.Text, default(PlatformUserID), 0L);
		}
		return CensorShittyWords.FilterUGC(text, UGCType.Text, new PlatformUserID(resolvedAuthor), 0L);
	}

	public void SetText(string text)
	{
		if (m_nview.IsValid())
		{
			PlatformUserID platformUserID = PlatformManager.DistributionPlatform.LocalUser.PlatformUserID;
			m_nview.InvokeRPC("SetName", text, PlatformManager.DistributionPlatform.LocalUser.IsSignedIn ? platformUserID.ToString() : "host");
		}
	}

	private void RPC_SetName(long sender, string name, string authorId)
	{
		if (m_nview.IsValid() && m_nview.IsOwner() && IsTamed())
		{
			m_nview.GetZDO().Set(ZDOVars.s_tamedName, name);
			m_nview.GetZDO().Set(ZDOVars.s_tamedNameAuthor, authorId);
		}
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		if (m_saddleItem != null && IsTamed() && item.m_shared.m_name == m_saddleItem.m_itemData.m_shared.m_name)
		{
			if (HaveSaddle())
			{
				user.Message(MessageHud.MessageType.Center, GetHoverName() + " $hud_saddle_already");
				return true;
			}
			m_nview.InvokeRPC("AddSaddle");
			user.GetInventory().RemoveOneItem(item);
			user.Message(MessageHud.MessageType.Center, GetHoverName() + " $hud_saddle_ready");
			return true;
		}
		return false;
	}

	private void RPC_AddSaddle(long sender)
	{
		if (m_nview.IsOwner() && !HaveSaddle())
		{
			m_nview.GetZDO().Set(ZDOVars.s_haveSaddleHash, value: true);
			m_nview.InvokeRPC(ZNetView.Everybody, "SetSaddle", true);
		}
	}

	public bool DropSaddle(Vector3 userPoint)
	{
		if (!HaveSaddle())
		{
			return false;
		}
		m_nview.GetZDO().Set(ZDOVars.s_haveSaddleHash, value: false);
		m_nview.InvokeRPC(ZNetView.Everybody, "SetSaddle", false);
		Vector3 flyDirection = userPoint - base.transform.position;
		SpawnSaddle(flyDirection);
		return true;
	}

	private void SpawnSaddle(Vector3 flyDirection)
	{
		Rigidbody component = UnityEngine.Object.Instantiate(m_saddleItem.gameObject, base.transform.TransformPoint(m_dropSaddleOffset), Quaternion.identity).GetComponent<Rigidbody>();
		if ((bool)component)
		{
			Vector3 up = Vector3.up;
			if (flyDirection.magnitude > 0.1f)
			{
				flyDirection.y = 0f;
				flyDirection.Normalize();
				up += flyDirection;
			}
			component.AddForce(up * m_dropItemVel, ForceMode.VelocityChange);
		}
	}

	private bool HaveSaddle()
	{
		if (m_saddle == null)
		{
			return false;
		}
		if (!m_nview.IsValid())
		{
			return false;
		}
		return m_nview.GetZDO().GetBool(ZDOVars.s_haveSaddleHash);
	}

	private void RPC_SetSaddle(long sender, bool enabled)
	{
		SetSaddle(enabled);
	}

	private void SetSaddle(bool enabled)
	{
		ZLog.Log("Setting saddle:" + enabled);
		if (m_saddle != null)
		{
			m_saddle.gameObject.SetActive(enabled);
		}
	}

	private void TamingUpdate()
	{
		if (m_nview.IsValid() && m_nview.IsOwner() && !IsTamed() && !IsHungry() && (bool)m_monsterAI && !m_monsterAI.IsAlerted())
		{
			m_monsterAI.SetDespawnInDay(despawn: false);
			m_monsterAI.SetEventCreature(despawn: false);
			DecreaseRemainingTime(3f);
			if (GetRemainingTime() <= 0f)
			{
				Tame();
			}
			else
			{
				m_sootheEffect.Create(base.transform.position, base.transform.rotation);
			}
		}
	}

	private void Tame()
	{
		Game.instance.IncrementPlayerStat(PlayerStatType.CreatureTamed);
		if (m_nview.IsValid() && m_nview.IsOwner() && (bool)m_monsterAI && (bool)m_character && !IsTamed())
		{
			m_monsterAI.MakeTame();
			m_tamedEffect.Create(base.transform.position, base.transform.rotation);
			Player closestPlayer = Player.GetClosestPlayer(base.transform.position, 30f);
			if ((bool)closestPlayer)
			{
				closestPlayer.Message(MessageHud.MessageType.Center, m_character.m_name + " $hud_tamedone");
			}
		}
	}

	public static void TameAllInArea(Vector3 point, float radius)
	{
		foreach (Character allCharacter in Character.GetAllCharacters())
		{
			if (!allCharacter.IsPlayer())
			{
				Tameable component = allCharacter.GetComponent<Tameable>();
				if ((bool)component)
				{
					component.Tame();
				}
			}
		}
	}

	public void Command(Humanoid user, bool message = true)
	{
		m_nview.InvokeRPC("Command", user.GetZDOID(), message);
	}

	private Player GetPlayer(ZDOID characterID)
	{
		GameObject gameObject = ZNetScene.instance.FindInstance(characterID);
		if ((bool)gameObject)
		{
			return gameObject.GetComponent<Player>();
		}
		return null;
	}

	private void RPC_Command(long sender, ZDOID characterID, bool message)
	{
		Player player = GetPlayer(characterID);
		if (player == null || !m_monsterAI)
		{
			return;
		}
		if ((bool)m_monsterAI.GetFollowTarget())
		{
			m_monsterAI.SetFollowTarget(null);
			m_monsterAI.SetPatrolPoint();
			if (m_nview.IsOwner())
			{
				m_nview.GetZDO().Set(ZDOVars.s_follow, "");
			}
			if (message)
			{
				player.Message(MessageHud.MessageType.Center, GetHoverName() + " $hud_tamestay");
			}
		}
		else
		{
			m_monsterAI.ResetPatrolPoint();
			m_monsterAI.SetFollowTarget(player.gameObject);
			if (m_nview.IsOwner())
			{
				m_nview.GetZDO().Set(ZDOVars.s_follow, player.GetPlayerName());
			}
			if (message)
			{
				player.Message(MessageHud.MessageType.Center, GetHoverName() + " $hud_tamefollow");
			}
			int num = m_nview.GetZDO().GetInt(ZDOVars.s_maxInstances);
			if (num > 0)
			{
				UnsummonMaxInstances(num);
			}
		}
		m_unsummonTime = 0f;
	}

	private void UpdateSavedFollowTarget()
	{
		if (!m_monsterAI || m_monsterAI.GetFollowTarget() != null || !m_nview.IsOwner())
		{
			return;
		}
		string text = m_nview.GetZDO().GetString(ZDOVars.s_follow);
		if (string.IsNullOrEmpty(text))
		{
			return;
		}
		foreach (Player allPlayer in Player.GetAllPlayers())
		{
			if (allPlayer.GetPlayerName() == text)
			{
				Command(allPlayer, message: false);
				return;
			}
		}
		if (m_unsummonOnOwnerLogoutSeconds > 0f)
		{
			m_unsummonTime += Time.fixedDeltaTime;
			if (m_unsummonTime > m_unsummonOnOwnerLogoutSeconds)
			{
				UnSummon();
			}
		}
	}

	public bool IsHungry()
	{
		if (!m_character)
		{
			return false;
		}
		if (m_nview == null)
		{
			return false;
		}
		ZDO zDO = m_nview.GetZDO();
		if (zDO == null)
		{
			return false;
		}
		DateTime dateTime = new DateTime(zDO.GetLong(ZDOVars.s_tameLastFeeding, 0L));
		return (ZNet.instance.GetTime() - dateTime).TotalSeconds > (double)m_fedDuration;
	}

	private void ResetFeedingTimer()
	{
		m_nview.GetZDO().Set(ZDOVars.s_tameLastFeeding, ZNet.instance.GetTime().Ticks);
	}

	private void OnDeath()
	{
		ZLog.Log("Valid " + m_nview.IsValid());
		ZLog.Log("On death " + HaveSaddle());
		if (HaveSaddle() && m_dropSaddleOnDeath)
		{
			ZLog.Log("Spawning saddle ");
			SpawnSaddle(Vector3.zero);
		}
	}

	private int GetTameness()
	{
		float remainingTime = GetRemainingTime();
		return (int)((1f - Mathf.Clamp01(remainingTime / m_tamingTime)) * 100f);
	}

	private void OnConsumedItem(ItemDrop item)
	{
		if (IsHungry())
		{
			m_sootheEffect.Create(m_character ? m_character.GetCenterPoint() : base.transform.position, Quaternion.identity);
		}
		ResetFeedingTimer();
	}

	private void DecreaseRemainingTime(float time)
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		float remainingTime = GetRemainingTime();
		s_nearbyPlayers.Clear();
		Player.GetPlayersInRange(base.transform.position, m_tamingSpeedMultiplierRange, s_nearbyPlayers);
		foreach (Player s_nearbyPlayer in s_nearbyPlayers)
		{
			if (s_nearbyPlayer.GetSEMan().HaveStatusAttribute(StatusEffect.StatusAttribute.TamingBoost))
			{
				time *= m_tamingBoostMultiplier;
			}
		}
		remainingTime -= time;
		if (remainingTime < 0f)
		{
			remainingTime = 0f;
		}
		m_nview.GetZDO().Set(ZDOVars.s_tameTimeLeft, remainingTime);
	}

	private float GetRemainingTime()
	{
		if (!m_nview.IsValid())
		{
			return 0f;
		}
		return m_nview.GetZDO().GetFloat(ZDOVars.s_tameTimeLeft, m_tamingTime);
	}

	public bool HaveRider()
	{
		if ((bool)m_saddle)
		{
			return m_saddle.HaveValidUser();
		}
		return false;
	}

	public float GetRiderSkill()
	{
		if ((bool)m_saddle)
		{
			return m_saddle.GetRiderSkill();
		}
		return 0f;
	}

	private void UpdateSummon()
	{
		if (m_nview.IsValid() && m_nview.IsOwner() && m_unsummonDistance > 0f && (bool)m_monsterAI)
		{
			GameObject followTarget = m_monsterAI.GetFollowTarget();
			if ((bool)followTarget && Vector3.Distance(followTarget.transform.position, base.gameObject.transform.position) > m_unsummonDistance)
			{
				UnSummon();
			}
		}
	}

	private void UnsummonMaxInstances(int maxInstances)
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner() || !m_character)
		{
			return;
		}
		GameObject followTarget = m_monsterAI.GetFollowTarget();
		object obj;
		if ((object)followTarget != null)
		{
			Player component = followTarget.GetComponent<Player>();
			if ((object)component != null)
			{
				obj = component.GetPlayerName();
				goto IL_004a;
			}
		}
		obj = null;
		goto IL_004a;
		IL_004a:
		string text = (string)obj;
		if (text == null)
		{
			return;
		}
		List<Character> allCharacters = Character.GetAllCharacters();
		List<BaseAI> list = new List<BaseAI>();
		foreach (Character item in allCharacters)
		{
			if (!(item.m_name == m_character.m_name))
			{
				continue;
			}
			ZNetView component2 = item.GetComponent<ZNetView>();
			object obj2;
			if ((object)component2 != null)
			{
				ZDO zDO = component2.GetZDO();
				if (zDO != null)
				{
					obj2 = zDO.GetString(ZDOVars.s_follow);
					goto IL_00b7;
				}
			}
			obj2 = "";
			goto IL_00b7;
			IL_00b7:
			if ((string)obj2 == text)
			{
				MonsterAI component3 = item.GetComponent<MonsterAI>();
				if ((object)component3 != null)
				{
					list.Add(component3);
				}
			}
		}
		list.Sort((BaseAI a, BaseAI b) => b.GetTimeSinceSpawned().CompareTo(a.GetTimeSinceSpawned()));
		int num = list.Count - maxInstances;
		for (int num2 = 0; num2 < num; num2++)
		{
			list[num2].GetComponent<Tameable>()?.UnSummon();
		}
		if (num > 0 && (bool)Player.m_localPlayer)
		{
			Player.m_localPlayer.Message(MessageHud.MessageType.Center, "$hud_maxsummonsreached");
		}
	}

	private void UnSummon()
	{
		if (m_nview.IsValid())
		{
			m_nview.InvokeRPC(ZNetView.Everybody, "RPC_UnSummon");
		}
	}

	private void RPC_UnSummon(long sender)
	{
		m_unSummonEffect.Create(base.gameObject.transform.position, base.gameObject.transform.rotation);
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			ZNetScene.instance.Destroy(base.gameObject);
		}
	}
}
