using System;
using System.Collections.Generic;
using UnityEngine;

public class Trader : MonoBehaviour, Hoverable, Interactable
{
	[Serializable]
	public class TradeItem
	{
		public ItemDrop m_prefab;

		public int m_stack = 1;

		public int m_price = 100;

		public string m_requiredGlobalKey;
	}

	[Serializable]
	public class TraderUseItem
	{
		public ItemDrop m_prefab;

		public string m_setsGlobalKey;

		public bool m_removesItem;

		public string m_dialog;
	}

	[Serializable]
	public class ConditionalDialog
	{
		public List<string> m_keyConditions = new List<string>();

		[Tooltip("Default unchecked will run when they keys are set in the world, check this to run when keys are NOT set.")]
		public bool m_whenKeyNotSet;

		[Tooltip("Which places this text will be used.")]
		public TalkPlacement m_textPlacement;

		public KeySetType m_keyCheck;

		public GameKeyType m_keyType;

		public List<string> m_dialog;
	}

	public enum TalkPlacement
	{
		ReplaceRandomTalk,
		ReplaceGreetAndRandomTalk,
		ReplaceGreet
	}

	public string m_name = "Haldor";

	public float m_standRange = 15f;

	public float m_greetRange = 5f;

	public float m_byeRange = 5f;

	public List<TradeItem> m_items = new List<TradeItem>();

	public List<TraderUseItem> m_useItems = new List<TraderUseItem>();

	[Header("Dialog")]
	public float m_hideDialogDelay = 5f;

	public float m_randomTalkInterval = 30f;

	public float m_dialogHeight = 1.5f;

	public List<string> m_randomTalk = new List<string>();

	public List<string> m_randomGreets = new List<string>();

	public List<string> m_randomGoodbye = new List<string>();

	public List<string> m_randomStartTrade = new List<string>();

	public List<string> m_randomBuy = new List<string>();

	public List<string> m_randomSell = new List<string>();

	public List<string> m_randomGiveItemNo = new List<string>();

	public List<string> m_randomUseItemAlreadyRecieved = new List<string>();

	[Tooltip("These will be used instead of random talk if any of the conditions are met")]
	public List<ConditionalDialog> m_randomTalkConditionals = new List<ConditionalDialog>();

	public EffectList m_randomTalkFX = new EffectList();

	public EffectList m_randomGreetFX = new EffectList();

	public EffectList m_randomGoodbyeFX = new EffectList();

	public EffectList m_randomStartTradeFX = new EffectList();

	public EffectList m_randomBuyFX = new EffectList();

	public EffectList m_randomSellFX = new EffectList();

	private bool m_didGreet;

	private bool m_didGoodbye;

	private Animator m_animator;

	private LookAt m_lookAt;

	private void Start()
	{
		m_animator = GetComponentInChildren<Animator>();
		m_lookAt = GetComponentInChildren<LookAt>();
		SnapToGround component = GetComponent<SnapToGround>();
		if ((bool)component)
		{
			component.Snap();
		}
		InvokeRepeating("RandomTalk", m_randomTalkInterval, m_randomTalkInterval);
	}

	private void Update()
	{
		Player closestPlayer = Player.GetClosestPlayer(base.transform.position, Mathf.Max(m_byeRange + 3f, m_standRange));
		if ((bool)closestPlayer)
		{
			float num = Vector3.Distance(closestPlayer.transform.position, base.transform.position);
			if (num < m_standRange)
			{
				m_animator.SetBool("Stand", value: true);
				m_lookAt.SetLoockAtTarget(closestPlayer.GetHeadPoint());
			}
			if (!m_didGreet && num < m_greetRange)
			{
				m_didGreet = true;
				List<string> texts = CheckConditionals(m_randomGreets, isGreet: true);
				Say(texts, "Greet");
				m_randomGreetFX.Create(base.transform.position, Quaternion.identity);
			}
			if (m_didGreet && !m_didGoodbye && num > m_byeRange)
			{
				m_didGoodbye = true;
				Say(m_randomGoodbye, "Greet");
				m_randomGoodbyeFX.Create(base.transform.position, Quaternion.identity);
			}
		}
		else
		{
			m_animator.SetBool("Stand", value: false);
			m_lookAt.ResetTarget();
		}
	}

	private void RandomTalk()
	{
		if (m_animator.GetBool("Stand") && !StoreGui.IsVisible() && Player.IsPlayerInRange(base.transform.position, m_greetRange))
		{
			List<string> texts = CheckConditionals(m_randomTalk, isGreet: false);
			Say(texts, "Talk");
			m_randomTalkFX.Create(base.transform.position, Quaternion.identity);
		}
	}

	private List<string> CheckConditionals(List<string> defaultList, bool isGreet)
	{
		foreach (ConditionalDialog randomTalkConditional in m_randomTalkConditionals)
		{
			if ((isGreet && randomTalkConditional.m_textPlacement == TalkPlacement.ReplaceRandomTalk) || (!isGreet && randomTalkConditional.m_textPlacement == TalkPlacement.ReplaceGreet))
			{
				continue;
			}
			if (randomTalkConditional.m_keyCheck == KeySetType.All)
			{
				bool flag = true;
				foreach (string keyCondition in randomTalkConditional.m_keyConditions)
				{
					if (!ZoneSystem.instance.CheckKey(keyCondition, randomTalkConditional.m_keyType, !randomTalkConditional.m_whenKeyNotSet))
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					return randomTalkConditional.m_dialog;
				}
				continue;
			}
			if (randomTalkConditional.m_keyCheck == KeySetType.Exlusive)
			{
				bool flag2 = false;
				bool flag3 = false;
				foreach (string keyCondition2 in randomTalkConditional.m_keyConditions)
				{
					if (ZoneSystem.instance.CheckKey(keyCondition2, randomTalkConditional.m_keyType, !randomTalkConditional.m_whenKeyNotSet))
					{
						flag2 = true;
					}
					else
					{
						flag3 = true;
					}
				}
				if (flag2 && flag3)
				{
					return randomTalkConditional.m_dialog;
				}
				continue;
			}
			bool flag4 = false;
			foreach (string keyCondition3 in randomTalkConditional.m_keyConditions)
			{
				if (ZoneSystem.instance.CheckKey(keyCondition3, randomTalkConditional.m_keyType, !randomTalkConditional.m_whenKeyNotSet))
				{
					flag4 = true;
					break;
				}
			}
			if ((flag4 && randomTalkConditional.m_keyCheck == KeySetType.Any) || (!flag4 && randomTalkConditional.m_keyCheck == KeySetType.None))
			{
				return randomTalkConditional.m_dialog;
			}
		}
		return defaultList;
	}

	public string GetHoverText()
	{
		string text = m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $raven_interact";
		if (m_useItems.Count > 0)
		{
			text += "\n[<color=yellow><b>1-8</b></color>] $npc_giveitem";
		}
		return Localization.instance.Localize(text);
	}

	public string GetHoverName()
	{
		return Localization.instance.Localize(m_name);
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		StoreGui.instance.Show(this);
		Say(m_randomStartTrade, "Talk");
		m_randomStartTradeFX.Create(base.transform.position, Quaternion.identity);
		return false;
	}

	private void DiscoverItems(Player player)
	{
		foreach (TradeItem availableItem in GetAvailableItems())
		{
			player.AddKnownItem(availableItem.m_prefab.m_itemData);
		}
	}

	private void Say(List<string> texts, string trigger)
	{
		Say(texts[UnityEngine.Random.Range(0, texts.Count)], trigger);
	}

	private void Say(string text, string trigger)
	{
		Chat.instance.SetNpcText(base.gameObject, Vector3.up * m_dialogHeight, 20f, m_hideDialogDelay, "", text, large: false);
		if (trigger.Length > 0)
		{
			m_animator.SetTrigger(trigger);
		}
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		if (m_useItems.Count > 0)
		{
			foreach (TraderUseItem useItem in m_useItems)
			{
				if (item.m_shared.m_name == useItem.m_prefab.m_itemData.m_shared.m_name)
				{
					if (!string.IsNullOrEmpty(useItem.m_setsGlobalKey) && ZoneSystem.instance.GetGlobalKey(useItem.m_setsGlobalKey))
					{
						Say(m_randomUseItemAlreadyRecieved, "Talk");
						return true;
					}
					if (!string.IsNullOrEmpty(useItem.m_dialog))
					{
						Say(useItem.m_dialog, "Talk");
					}
					if (!string.IsNullOrEmpty(useItem.m_setsGlobalKey))
					{
						ZoneSystem.instance.SetGlobalKey(useItem.m_setsGlobalKey);
					}
					if (useItem.m_removesItem)
					{
						user.GetInventory().RemoveItem(item, 1);
						user.ShowRemovedMessage(item, 1);
					}
					return true;
				}
			}
			Say(m_randomGiveItemNo, "Talk");
			return true;
		}
		return false;
	}

	public void OnBought(TradeItem item)
	{
		Say(m_randomBuy, "Buy");
		m_randomBuyFX.Create(base.transform.position, Quaternion.identity);
	}

	public void OnSold()
	{
		Say(m_randomSell, "Sell");
		m_randomSellFX.Create(base.transform.position, Quaternion.identity);
	}

	public List<TradeItem> GetAvailableItems()
	{
		List<TradeItem> list = new List<TradeItem>();
		foreach (TradeItem item in m_items)
		{
			if (string.IsNullOrEmpty(item.m_requiredGlobalKey) || ZoneSystem.instance.GetGlobalKey(item.m_requiredGlobalKey))
			{
				list.Add(item);
			}
		}
		return list;
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Trap : MonoBehaviour, Hoverable, Interactable
{
	private enum TrapState
	{
		Unarmed,
		Armed,
		Active
	}

	public string m_name = "Trap";

	public GameObject m_AOE;

	public Collider m_trigger;

	public int m_rearmCooldown = 60;

	public GameObject m_visualArmed;

	public GameObject m_visualUnarmed;

	public bool m_triggeredByEnemies;

	public bool m_triggeredByPlayers;

	public bool m_forceStagger = true;

	public EffectList m_triggerEffects;

	public EffectList m_armEffects;

	public bool m_startsArmed;

	private ZNetView m_nview;

	private Aoe m_aoe;

	private Piece m_piece;

	private Humanoid m_tempTriggeringHumanoid;

	private Vector3 m_tempTriggeredPosition = Vector3.zero;

	private List<Action> m_onReceiveOwnershipActions = new List<Action>();

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_aoe = m_AOE.GetComponent<Aoe>();
		m_piece = GetComponent<Piece>();
		if (!m_aoe)
		{
			ZLog.LogError("Trap '" + base.gameObject.name + "' is missing AOE!");
		}
		m_aoe.gameObject.SetActive(value: false);
		if ((bool)m_nview)
		{
			m_nview.Register<int>("RPC_RequestStateChange", RPC_RequestStateChange);
			m_nview.Register<int, long>("RPC_OnStateChanged", RPC_OnStateChanged);
			if (m_startsArmed && m_nview.IsValid() && m_nview.GetZDO().GetInt(ZDOVars.s_state, -1) == -1)
			{
				m_nview.GetZDO().Set(ZDOVars.s_state, 1);
			}
			UpdateState();
		}
	}

	private void Update()
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner())
		{
			return;
		}
		if (IsActive() && !IsCoolingDown())
		{
			RequestStateChange(TrapState.Unarmed);
		}
		if (m_onReceiveOwnershipActions.Count > 0)
		{
			for (int i = 0; i < m_onReceiveOwnershipActions.Count; i++)
			{
				m_onReceiveOwnershipActions[i]?.Invoke();
			}
			m_onReceiveOwnershipActions.Clear();
		}
	}

	public bool IsArmed()
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		return m_nview.GetZDO().GetInt(ZDOVars.s_state) == 1;
	}

	public bool IsActive()
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		return m_nview.GetZDO().GetInt(ZDOVars.s_state) == 2;
	}

	public bool IsCoolingDown()
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		return (double)(m_nview.GetZDO().GetFloat(ZDOVars.s_triggered) + (float)m_rearmCooldown) > ZNet.instance.GetTimeSeconds();
	}

	public string GetHoverText()
	{
		if (!m_nview.IsValid())
		{
			return "";
		}
		if (!PrivateArea.CheckAccess(base.transform.position, 0f, flash: false))
		{
			return Localization.instance.Localize(m_name + "\n$piece_noaccess");
		}
		if (IsArmed())
		{
			return Localization.instance.Localize(m_name + " ($piece_trap_armed)");
		}
		if (IsCoolingDown())
		{
			return Localization.instance.Localize(m_name);
		}
		return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_trap_arm");
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		if (!PrivateArea.CheckAccess(base.transform.position))
		{
			return true;
		}
		if (IsArmed())
		{
			return false;
		}
		if (IsCoolingDown())
		{
			Player.m_localPlayer.Message(MessageHud.MessageType.Center, Localization.instance.Localize("$piece_trap_cooldown"));
			return true;
		}
		RequestStateChange(TrapState.Armed);
		return true;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void RequestStateChange(TrapState newState)
	{
		if (m_nview.IsValid())
		{
			if (m_nview.IsOwner())
			{
				RPC_RequestStateChange(ZNet.GetUID(), (int)newState);
				return;
			}
			m_nview.InvokeRPC("RPC_RequestStateChange", (int)newState);
		}
	}

	private void RPC_OnStateChanged(long uid, int value, long idOfClientModifyingState)
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		m_onReceiveOwnershipActions.Clear();
		switch (value)
		{
		case 1:
			if (idOfClientModifyingState == ZNet.GetUID())
			{
				m_armEffects.Create(base.transform.position, base.transform.rotation);
				Game.instance.IncrementPlayerStat(PlayerStatType.TrapArmed);
			}
			m_tempTriggeringHumanoid = null;
			break;
		case 2:
			if (idOfClientModifyingState != ZNet.GetUID())
			{
				break;
			}
			if (m_nview.IsOwner())
			{
				TriggerTrap();
			}
			else
			{
				m_onReceiveOwnershipActions.Add(TriggerTrap);
			}
			if (!(m_tempTriggeringHumanoid != null) || m_tempTriggeringHumanoid.GetZDOID().ID != Player.m_localPlayer.GetZDOID().ID)
			{
				break;
			}
			if (m_nview.IsOwner())
			{
				Game.instance.IncrementPlayerStat(PlayerStatType.TrapTriggered);
				break;
			}
			m_onReceiveOwnershipActions.Add(delegate
			{
				Game.instance.IncrementPlayerStat(PlayerStatType.TrapTriggered);
			});
			break;
		default:
			m_tempTriggeringHumanoid = null;
			break;
		}
		UpdateState((TrapState)value);
	}

	private void TriggerTrap()
	{
		if (m_tempTriggeringHumanoid != null)
		{
			m_tempTriggeringHumanoid.transform.position = m_tempTriggeredPosition;
			Physics.SyncTransforms();
			if (m_forceStagger)
			{
				m_tempTriggeringHumanoid.Stagger(Vector3.zero);
			}
		}
		m_nview.GetZDO().Set(ZDOVars.s_state, 2);
		m_nview.GetZDO().Set(ZDOVars.s_triggered, (float)ZNet.instance.GetTimeSeconds());
		UnityEngine.Object.Instantiate(m_aoe.gameObject, base.transform).SetActive(value: true);
		m_triggerEffects.Create(base.transform.position, base.transform.rotation);
	}

	private void RPC_RequestStateChange(long senderID, int value)
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner())
		{
			return;
		}
		if (m_nview.GetZDO().GetInt(ZDOVars.s_state) != value)
		{
			if (value != 2)
			{
				m_nview.GetZDO().Set(ZDOVars.s_state, value);
			}
			else if (senderID != ZNet.GetUID())
			{
				m_nview.GetZDO().SetOwner(senderID);
			}
			m_nview.InvokeRPC(ZNetView.Everybody, "RPC_OnStateChanged", value, senderID);
		}
	}

	private void UpdateState(TrapState state)
	{
		m_piece.m_randomTarget = state == TrapState.Unarmed;
		m_visualArmed.SetActive(state == TrapState.Armed);
		m_visualUnarmed.SetActive(state != TrapState.Armed);
	}

	private void UpdateState()
	{
		if ((bool)m_nview && m_nview.IsValid())
		{
			TrapState state = (TrapState)m_nview.GetZDO().GetInt(ZDOVars.s_state);
			UpdateState(state);
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		Humanoid humanoid = null;
		Player componentInParent = collider.GetComponentInParent<Player>();
		if (componentInParent != null)
		{
			if (!m_triggeredByPlayers || componentInParent != Player.m_localPlayer)
			{
				return;
			}
		}
		else if (collider.GetComponentInParent<MonsterAI>() != null)
		{
			if (!m_triggeredByEnemies)
			{
				return;
			}
			humanoid = collider.GetComponentInParent<Humanoid>();
			if (humanoid != null && !humanoid.IsOwner())
			{
				return;
			}
		}
		if (IsArmed())
		{
			if (humanoid == null)
			{
				humanoid = collider.GetComponentInParent<Humanoid>();
			}
			if (humanoid != null)
			{
				m_tempTriggeringHumanoid = humanoid;
				m_tempTriggeredPosition = humanoid.transform.position;
			}
			RequestStateChange(TrapState.Active);
		}
	}
}
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class TreeBase : MonoBehaviour, IDestructible
{
	private ZNetView m_nview;

	public float m_health = 1f;

	public HitData.DamageModifiers m_damageModifiers;

	public int m_minToolTier;

	public EffectList m_destroyedEffect = new EffectList();

	public EffectList m_hitEffect = new EffectList();

	public EffectList m_respawnEffect = new EffectList();

	public GameObject m_trunk;

	public GameObject m_stubPrefab;

	public GameObject m_logPrefab;

	public Transform m_logSpawnPoint;

	[Header("Drops")]
	public DropTable m_dropWhenDestroyed = new DropTable();

	public float m_spawnYOffset = 0.5f;

	public float m_spawnYStep = 0.3f;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		m_nview.Register<HitData>("RPC_Damage", RPC_Damage);
		m_nview.Register("RPC_Grow", RPC_Grow);
		m_nview.Register("RPC_Shake", RPC_Shake);
		if (m_nview.IsOwner() && m_nview.GetZDO().GetFloat(ZDOVars.s_health, m_health + (float)Game.m_worldLevel * m_health * Game.instance.m_worldLevelMineHPMultiplier) <= 0f)
		{
			m_nview.Destroy();
		}
	}

	public DestructibleType GetDestructibleType()
	{
		return DestructibleType.Tree;
	}

	public void Damage(HitData hit)
	{
		m_nview.InvokeRPC("RPC_Damage", hit);
	}

	public void Grow()
	{
		m_nview.InvokeRPC(ZNetView.Everybody, "RPC_Grow");
	}

	private void RPC_Grow(long uid)
	{
		StartCoroutine("GrowAnimation");
	}

	private IEnumerator GrowAnimation()
	{
		GameObject animatedTrunk = Object.Instantiate(m_trunk, m_trunk.transform.position, m_trunk.transform.rotation, base.transform);
		animatedTrunk.isStatic = false;
		LODGroup component = base.transform.GetComponent<LODGroup>();
		if ((bool)component)
		{
			component.fadeMode = LODFadeMode.None;
		}
		m_trunk.SetActive(value: false);
		for (float t = 0f; t < 0.3f; t += Time.deltaTime)
		{
			float num = Mathf.Clamp01(t / 0.3f);
			animatedTrunk.transform.localScale = m_trunk.transform.localScale * num;
			yield return null;
		}
		Object.Destroy(animatedTrunk);
		m_trunk.SetActive(value: true);
		if (m_nview.IsOwner())
		{
			m_respawnEffect.Create(base.transform.position, base.transform.rotation, base.transform);
		}
	}

	private void RPC_Damage(long sender, HitData hit)
	{
		if (!m_nview.IsOwner())
		{
			return;
		}
		float num = m_nview.GetZDO().GetFloat(ZDOVars.s_health, m_health);
		if (num <= 0f)
		{
			m_nview.Destroy();
			return;
		}
		bool flag = hit.m_damage.GetMajorityDamageType() == HitData.DamageType.Fire;
		bool flag2 = hit.m_hitType == HitData.HitType.CinderFire;
		hit.ApplyResistance(m_damageModifiers, out var significantModifier);
		float totalDamage = hit.GetTotalDamage();
		if (!hit.CheckToolTier(m_minToolTier, alwaysAllowTierZero: true))
		{
			DamageText.instance.ShowText(DamageText.TextType.TooHard, hit.m_point, 0f);
			return;
		}
		DamageText.instance.ShowText(significantModifier, hit.m_point, totalDamage);
		if (totalDamage <= 0f)
		{
			return;
		}
		num -= totalDamage;
		m_nview.GetZDO().Set(ZDOVars.s_health, num);
		if (!flag && !flag2)
		{
			Shake();
		}
		if (!flag2)
		{
			m_hitEffect.Create(hit.m_point, Quaternion.identity, base.transform);
			Player closestPlayer = Player.GetClosestPlayer(base.transform.position, 10f);
			if ((bool)closestPlayer)
			{
				closestPlayer.AddNoise(100f);
			}
		}
		if (hit.GetAttacker() == Player.m_localPlayer)
		{
			Game.instance.IncrementPlayerStat(PlayerStatType.TreeChops);
		}
		if (!(num <= 0f))
		{
			return;
		}
		m_destroyedEffect.Create(base.transform.position, base.transform.rotation, base.transform);
		SpawnLog(hit.m_dir);
		List<GameObject> dropList = m_dropWhenDestroyed.GetDropList();
		for (int i = 0; i < dropList.Count; i++)
		{
			Vector2 vector = Random.insideUnitCircle * 0.5f;
			Vector3 position = base.transform.position + Vector3.up * m_spawnYOffset + new Vector3(vector.x, m_spawnYStep * (float)i, vector.y);
			Quaternion rotation = Quaternion.Euler(0f, Random.Range(0, 360), 0f);
			Object.Instantiate(dropList[i], position, rotation);
		}
		base.gameObject.SetActive(value: false);
		m_nview.Destroy();
		if (hit.GetAttacker() == Player.m_localPlayer)
		{
			Game.instance.IncrementPlayerStat(PlayerStatType.Tree);
			switch (m_minToolTier)
			{
			case 0:
				Game.instance.IncrementPlayerStat(PlayerStatType.TreeTier0);
				break;
			case 1:
				Game.instance.IncrementPlayerStat(PlayerStatType.TreeTier1);
				break;
			case 2:
				Game.instance.IncrementPlayerStat(PlayerStatType.TreeTier2);
				break;
			case 3:
				Game.instance.IncrementPlayerStat(PlayerStatType.TreeTier3);
				break;
			case 4:
				Game.instance.IncrementPlayerStat(PlayerStatType.TreeTier4);
				break;
			case 5:
				Game.instance.IncrementPlayerStat(PlayerStatType.TreeTier5);
				break;
			default:
				ZLog.LogWarning("No stat for tree tier: " + m_minToolTier);
				break;
			}
		}
	}

	private void Shake()
	{
		m_nview.InvokeRPC(ZNetView.Everybody, "RPC_Shake");
	}

	private void RPC_Shake(long uid)
	{
		StopCoroutine("ShakeAnimation");
		StartCoroutine("ShakeAnimation");
	}

	private IEnumerator ShakeAnimation()
	{
		m_trunk.gameObject.isStatic = false;
		float t = Time.time;
		while (Time.time - t < 1f)
		{
			float time = Time.time;
			float num = 1f - Mathf.Clamp01((time - t) / 1f);
			float num2 = num * num * num * 1.5f;
			Quaternion localRotation = Quaternion.Euler(Mathf.Sin(time * 40f) * num2, 0f, Mathf.Cos(time * 0.9f * 40f) * num2);
			m_trunk.transform.localRotation = localRotation;
			yield return null;
		}
		m_trunk.transform.localRotation = Quaternion.identity;
		m_trunk.gameObject.isStatic = true;
	}

	private void SpawnLog(Vector3 hitDir)
	{
		GameObject gameObject = Object.Instantiate(m_logPrefab, m_logSpawnPoint.position, m_logSpawnPoint.rotation);
		gameObject.GetComponent<ZNetView>().SetLocalScale(base.transform.localScale);
		Rigidbody component = gameObject.GetComponent<Rigidbody>();
		component.mass *= base.transform.localScale.x;
		component.ResetInertiaTensor();
		component.AddForceAtPosition(hitDir * 0.2f * component.mass, gameObject.transform.position + Vector3.up * 4f * base.transform.localScale.y, ForceMode.Impulse);
		if ((bool)m_stubPrefab)
		{
			Object.Instantiate(m_stubPrefab, base.transform.position, base.transform.rotation).GetComponent<ZNetView>().SetLocalScale(base.transform.localScale);
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class TreeLog : MonoBehaviour, IDestructible
{
	public float m_health = 60f;

	public HitData.DamageModifiers m_damages;

	public int m_minToolTier;

	public EffectList m_destroyedEffect = new EffectList();

	public EffectList m_hitEffect = new EffectList();

	public DropTable m_dropWhenDestroyed = new DropTable();

	public GameObject m_subLogPrefab;

	public Transform[] m_subLogPoints = Array.Empty<Transform>();

	public bool m_useSubLogPointRotation;

	public float m_spawnDistance = 2f;

	public float m_hitNoise = 100f;

	private Rigidbody m_body;

	private ZNetView m_nview;

	private bool m_firstFrame = true;

	private void Awake()
	{
		m_body = GetComponent<Rigidbody>();
		m_body.maxDepenetrationVelocity = 1f;
		m_nview = GetComponent<ZNetView>();
		m_nview.Register<HitData>("RPC_Damage", RPC_Damage);
		if (m_nview.IsOwner())
		{
			float num = m_nview.GetZDO().GetFloat(ZDOVars.s_health, -1f);
			if (num == -1f)
			{
				m_nview.GetZDO().Set(ZDOVars.s_health, m_health + (float)Game.m_worldLevel * m_health * Game.instance.m_worldLevelMineHPMultiplier);
			}
			else if (num <= 0f)
			{
				m_nview.Destroy();
			}
		}
		Invoke("EnableDamage", 0.2f);
	}

	private void EnableDamage()
	{
		m_firstFrame = false;
	}

	public DestructibleType GetDestructibleType()
	{
		return DestructibleType.Tree;
	}

	public void Damage(HitData hit)
	{
		if (!m_firstFrame && m_nview.IsValid())
		{
			m_nview.InvokeRPC("RPC_Damage", hit);
		}
	}

	private void RPC_Damage(long sender, HitData hit)
	{
		if (!m_nview.IsOwner())
		{
			return;
		}
		float num = m_nview.GetZDO().GetFloat(ZDOVars.s_health);
		if (num <= 0f)
		{
			return;
		}
		HitData hitData = hit.Clone();
		hit.ApplyResistance(m_damages, out var significantModifier);
		float totalDamage = hit.GetTotalDamage();
		if (!hit.CheckToolTier(m_minToolTier, alwaysAllowTierZero: true))
		{
			DamageText.instance.ShowText(DamageText.TextType.TooHard, hit.m_point, 0f);
			return;
		}
		if ((bool)m_body)
		{
			m_body.AddForceAtPosition(hit.m_dir * hit.m_pushForce * 2f, hit.m_point, ForceMode.Impulse);
		}
		DamageText.instance.ShowText(significantModifier, hit.m_point, totalDamage);
		if (totalDamage <= 0f)
		{
			return;
		}
		num -= totalDamage;
		if (num < 0f)
		{
			num = 0f;
		}
		m_nview.GetZDO().Set(ZDOVars.s_health, num);
		if (hit.m_hitType != HitData.HitType.CinderFire)
		{
			m_hitEffect.Create(hit.m_point, Quaternion.identity, base.transform);
			if (m_hitNoise > 0f)
			{
				Player closestPlayer = Player.GetClosestPlayer(base.transform.position, 10f);
				if ((bool)closestPlayer)
				{
					closestPlayer.AddNoise(m_hitNoise);
				}
			}
		}
		if (hit.GetAttacker() == Player.m_localPlayer)
		{
			Game.instance.IncrementPlayerStat(PlayerStatType.LogChops);
		}
		if (num <= 0f)
		{
			Destroy(hitData);
			if (hit.GetAttacker() == Player.m_localPlayer)
			{
				Game.instance.IncrementPlayerStat(PlayerStatType.Logs);
			}
		}
	}

	private void Destroy(HitData hitData = null)
	{
		ZNetScene.instance.Destroy(base.gameObject);
		m_destroyedEffect.Create(base.transform.position, base.transform.rotation, base.transform);
		List<GameObject> dropList = m_dropWhenDestroyed.GetDropList();
		for (int i = 0; i < dropList.Count; i++)
		{
			Vector3 position = base.transform.position + base.transform.up * UnityEngine.Random.Range(0f - m_spawnDistance, m_spawnDistance) + Vector3.up * 0.3f * i;
			Quaternion rotation = Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f);
			GameObject gameObject = dropList[i];
			ItemDrop component = gameObject.GetComponent<ItemDrop>();
			int dropCount = 1;
			if ((bool)component)
			{
				gameObject = Game.instance.CheckDropConversion(hitData, component, gameObject, ref dropCount);
			}
			for (int j = 0; j < dropCount; j++)
			{
				ItemDrop.OnCreateNew(UnityEngine.Object.Instantiate(gameObject, position, rotation));
			}
		}
		if (m_subLogPrefab != null)
		{
			Transform[] subLogPoints = m_subLogPoints;
			foreach (Transform transform in subLogPoints)
			{
				Quaternion rotation2 = (m_useSubLogPointRotation ? transform.rotation : base.transform.rotation);
				UnityEngine.Object.Instantiate(m_subLogPrefab, transform.position, rotation2).GetComponent<ZNetView>().SetLocalScale(base.transform.localScale);
			}
		}
	}
}
using UnityEngine;

public class TriggerSpawnAbility : MonoBehaviour, IProjectile
{
	[Header("Spawn")]
	public float m_range = 10f;

	private Character m_owner;

