using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Experimental.Rendering;

[RequireComponent(typeof(Camera))]
public class UpscaledFrameBuffer : MonoBehaviour
{
	public static bool m_autoTargetResolution = false;

	public static uint m_targetResolutionVertical = uint.MaxValue;

	public static UpscalingAlgorithm m_upscalingAlgorithm = UpscalingAlgorithm.Bilinear;

	private Camera m_camera;

	private Camera m_clearCamera;

	private RenderTexture m_renderTexture;

	private bool m_isUsingScaledRendering;

	private List<FrameBufferScaler> m_subscribers = new List<FrameBufferScaler>();

	public static bool AutomaticRenderScaleSupported()
	{
		return true;
	}

	public void Subscribe(FrameBufferScaler subscriber)
	{
		m_subscribers.Add(subscriber);
		if (m_renderTexture != null)
		{
			subscriber.OnBufferCreated(this, m_renderTexture);
		}
		UpdateCameraTarget();
	}

	public void Unsubscribe(FrameBufferScaler subscriber)
	{
		m_subscribers.Remove(subscriber);
		if (m_renderTexture != null)
		{
			subscriber.OnBufferDestroyed(this);
		}
		UpdateCameraTarget();
	}

	private void Update()
	{
		UpdateCameraTarget();
	}

	private void CreateClearCamera()
	{
		GameObject gameObject = new GameObject();
		gameObject.transform.parent = base.transform;
		m_clearCamera = gameObject.AddComponent<Camera>();
		m_clearCamera.cullingMask = 0;
		m_clearCamera.allowHDR = false;
		m_clearCamera.allowMSAA = false;
		m_clearCamera.renderingPath = RenderingPath.Forward;
		m_clearCamera.clearFlags = CameraClearFlags.Color;
		m_clearCamera.backgroundColor = Color.black;
	}

	private void DestroyClearCameraIfExists()
	{
		if (!(m_clearCamera == null))
		{
			Object.Destroy(m_clearCamera.gameObject);
		}
	}

	private void UpdateCurrentRenderScale()
	{
		if (m_autoTargetResolution)
		{
			uint num = 96u;
			if (Screen.dpi <= (float)num)
			{
				m_targetResolutionVertical = uint.MaxValue;
			}
			else
			{
				m_targetResolutionVertical = (uint)(Screen.height * (int)num) / (uint)Screen.dpi;
			}
		}
	}

	private static Resolution GetHighestSupportedResolution()
	{
		Resolution[] resolutions = Screen.resolutions;
		int num = 0;
		int num2 = resolutions[num].width * resolutions[num].height;
		for (int i = 1; i < resolutions.Length; i++)
		{
			int num3 = resolutions[i].width * resolutions[i].height;
			if (num3 > num2)
			{
				num = i;
				num2 = num3;
			}
		}
		return resolutions[num];
	}

	private void UpdateCameraTarget()
	{
		if (m_camera == null)
		{
			m_camera = GetComponent<Camera>();
		}
		UpdateCurrentRenderScale();
		bool flag = m_targetResolutionVertical < Screen.height && m_subscribers.Count > 0;
		if (flag)
		{
			if (!m_isUsingScaledRendering)
			{
				CreateClearCamera();
			}
			ReassignTextureIfNeeded();
		}
		else if (m_isUsingScaledRendering)
		{
			ReleaseTextureIfExists();
			DestroyClearCameraIfExists();
		}
		m_isUsingScaledRendering = flag;
	}

	private FilterMode GetFilterModeFromUpscalingMode()
	{
		UpscalingAlgorithm upscalingAlgorithm = m_upscalingAlgorithm;
		if (upscalingAlgorithm != UpscalingAlgorithm.Bilinear && upscalingAlgorithm == UpscalingAlgorithm.NearestNeighbor)
		{
			return FilterMode.Point;
		}
		return FilterMode.Bilinear;
	}

	private void ReassignTextureIfNeeded()
	{
		Vector2Int vector2Int = new Vector2Int((int)((uint)((int)m_targetResolutionVertical * Screen.width) / (uint)Screen.height), (int)m_targetResolutionVertical);
		if (vector2Int.x < 8 || vector2Int.y < 8)
		{
			vector2Int = ((vector2Int.y >= vector2Int.x) ? new Vector2Int(8, (int)((uint)(8 * Screen.height) / (uint)Screen.width)) : new Vector2Int((int)((uint)(8 * Screen.width) / (uint)Screen.height), 8));
		}
		if (m_renderTexture == null || vector2Int != new Vector2Int(m_renderTexture.width, m_renderTexture.height) || m_renderTexture.filterMode != GetFilterModeFromUpscalingMode())
		{
			RecreateAndAssignRenderTexture(vector2Int);
		}
	}

	private void RecreateAndAssignRenderTexture(Vector2Int viewportResolution)
	{
		ReleaseTextureIfExists();
		m_renderTexture = new RenderTexture(viewportResolution.x, viewportResolution.y, 24, DefaultFormat.HDR);
		m_renderTexture.Create();
		m_renderTexture.filterMode = GetFilterModeFromUpscalingMode();
		m_camera.targetTexture = m_renderTexture;
		for (int i = 0; i < m_subscribers.Count; i++)
		{
			m_subscribers[i].OnBufferCreated(this, m_renderTexture);
		}
	}

	private void ReleaseTextureIfExists()
	{
		if (!(m_renderTexture == null))
		{
			for (int i = 0; i < m_subscribers.Count; i++)
			{
				m_subscribers[i].OnBufferDestroyed(this);
			}
			m_camera.targetTexture = null;
			m_renderTexture.Release();
			m_renderTexture = null;
		}
	}

	private void OnDestroy()
	{
		ReleaseTextureIfExists();
		DestroyClearCameraIfExists();
	}
}
public enum UpscalingAlgorithm
{
	Bilinear,
	NearestNeighbor
}
public static class UpscalingAlgorithmExtentions
{
	public static string ToDisplayName(this UpscalingAlgorithm _enum)
	{
		return _enum switch
		{
			UpscalingAlgorithm.Bilinear => Localization.instance.Localize("$settings_bilinear"), 
			UpscalingAlgorithm.NearestNeighbor => Localization.instance.Localize("$settings_nearestneighbor"), 
			_ => EnumUtils.GetDisplayName(_enum).ToString(), 
		};
	}
}
using Splatform;

public class UserInfo : ISerializableParameter
{
	public string Name;

	public PlatformUserID UserId;

	public static UserInfo GetLocalUser()
	{
		return new UserInfo
		{
			Name = Game.instance.GetPlayerProfile().GetName(),
			UserId = PlatformManager.DistributionPlatform.LocalUser.PlatformUserID
		};
	}

	public void Deserialize(ref ZPackage pkg)
	{
		Name = pkg.ReadString();
		UserId = new PlatformUserID(pkg.ReadString());
	}

	public void Serialize(ref ZPackage pkg)
	{
		pkg.Write(Name);
		pkg.Write(UserId.ToString());
	}

	public string GetDisplayName()
	{
		return CensorShittyWords.FilterUGC(Name, UGCType.CharacterName, UserId, 0L);
	}
}
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using Splatform;
using UnityEngine;

namespace UserManagement;

public static class MuteList
{
	private static readonly HashSet<PlatformUserID> _mutedUsers = new HashSet<PlatformUserID>();

	private static bool _hasBeenLoaded;

	private static bool _isLoading;

	private static readonly string _block_list_file_name = "blocked_players";

	private static readonly string _block_list_file_name_noncloud = Path.Combine(Application.persistentDataPath, _block_list_file_name) + ".txt";

	public static bool Contains(PlatformUserID user)
	{
		return _mutedUsers.Contains(user);
	}

	public static void Block(PlatformUserID user)
	{
		if (PlatformManager.DistributionPlatform != null)
		{
			if (!user.IsValid)
			{
				Debug.LogError("User was invalid!");
			}
			else if (user == PlatformManager.DistributionPlatform.LocalUser.PlatformUserID)
			{
				Debug.LogError("Local user was added to the block list! This should never happen! Ignoring.");
			}
			else if (!_mutedUsers.Contains(user))
			{
				_mutedUsers.Add(user);
			}
		}
	}

	public static void Unblock(PlatformUserID user)
	{
		if (_mutedUsers.Contains(user))
		{
			_mutedUsers.Remove(user);
		}
	}

	public static string GetBlockListFileName()
	{
		if (!FileHelpers.CloudStorageEnabled)
		{
			return _block_list_file_name_noncloud;
		}
		return _block_list_file_name;
	}

	public static void Persist()
	{
		if (_mutedUsers.Count > 0)
		{
			byte[] buffer = Encode();
			if (FileHelpers.LocalStorageSupported)
			{
				FileWriter fileWriter = new FileWriter(_block_list_file_name_noncloud, FileHelpers.FileHelperType.Binary, FileHelpers.FileSource.Local);
				Debug.Log("writing banned users to local file storage");
				fileWriter.m_binary.Write(buffer);
				fileWriter.Finish();
			}
			if (FileHelpers.CloudStorageEnabled)
			{
				FileWriter fileWriter2 = new FileWriter(_block_list_file_name, FileHelpers.FileHelperType.Binary, FileHelpers.FileSource.Cloud);
				Debug.Log("Writing banned users to cloud file storage.");
				fileWriter2.m_binary.Write(buffer);
				fileWriter2.Finish();
			}
		}
	}

	public static void Load(Action onLoaded)
	{
		if (_isLoading)
		{
			return;
		}
		if (!_hasBeenLoaded)
		{
			string users = "";
			DateTime lastWriteTime = DateTime.UnixEpoch;
			string users2 = "";
			DateTime lastWriteTime2 = DateTime.UnixEpoch;
			if (FileHelpers.Exists(_block_list_file_name, FileHelpers.FileSource.Cloud) && TryCreateFileReader(onLoaded, _block_list_file_name, FileHelpers.FileSource.Cloud, out var file, out lastWriteTime2))
			{
				TryReadBlockListFromFile(file, _block_list_file_name, out users2);
			}
			if (FileHelpers.Exists(_block_list_file_name_noncloud, FileHelpers.FileSource.Local) && TryCreateFileReader(onLoaded, _block_list_file_name_noncloud, FileHelpers.FileSource.Local, out var file2, out lastWriteTime))
			{
				TryReadBlockListFromFile(file2, _block_list_file_name_noncloud, out users);
			}
			if (!string.IsNullOrEmpty(users) && !string.IsNullOrEmpty(users2))
			{
				Debug.Log($"DateTime for cloudWrite: {lastWriteTime2.ToString()}, for local: {lastWriteTime.ToString()}. DateTime.Compare: {DateTime.Compare(lastWriteTime2, lastWriteTime)}");
				if (DateTime.Compare(lastWriteTime2, lastWriteTime) >= 0)
				{
					BlockUsers(users2);
				}
				else
				{
					BlockUsers(users);
				}
			}
			else if (!string.IsNullOrEmpty(users))
			{
				Debug.Log("there was no cloud users, instead using localusers! " + users);
				BlockUsers(users);
			}
			else if (!string.IsNullOrEmpty(users2))
			{
				Debug.Log("there was no local user, instead using cloud users! " + users2);
				BlockUsers(users2);
			}
			_hasBeenLoaded = true;
			onLoaded?.Invoke();
		}
		else
		{
			onLoaded?.Invoke();
		}
	}

	private static bool TryCreateFileReader(Action onLoaded, string path, FileHelpers.FileSource fileSource, out FileReader file, out DateTime lastWriteTime)
	{
		_isLoading = true;
		try
		{
			file = new FileReader(path, fileSource, FileHelpers.FileHelperType.Stream);
			lastWriteTime = FileHelpers.GetLastWriteTime(path, fileSource);
		}
		catch (Exception ex)
		{
			ZLog.Log("Failed to load: " + path + " (" + ex.Message + ")");
			_isLoading = false;
			_hasBeenLoaded = true;
			onLoaded?.Invoke();
			file = null;
			lastWriteTime = DateTime.UnixEpoch;
			return false;
		}
		return true;
	}

	private static void TryReadBlockListFromFile(FileReader file, string fileName, out string users)
	{
		try
		{
			StreamReader stream = file.m_stream;
			users = stream.ReadToEnd();
			Debug.Log("now getting block list from file " + fileName + ". got these users: " + users);
		}
		catch (Exception ex)
		{
			ZLog.LogError("error loading blocked_players. FileName: " + fileName + ", Error: " + ex.Message);
			file.Dispose();
			users = null;
		}
		file.Dispose();
		_isLoading = false;
	}

	private static byte[] Encode()
	{
		StringBuilder stringBuilder = new StringBuilder();
		foreach (PlatformUserID mutedUser in _mutedUsers)
		{
			stringBuilder.Append(mutedUser).Append('\n');
		}
		return Encoding.UTF8.GetBytes(stringBuilder.ToString());
	}

	private static void BlockUsers(string textUsers)
	{
		_mutedUsers.Clear();
		string[] array = textUsers.Split(new string[3] { "\r\n", "\r", "\n" }, StringSplitOptions.None);
		for (int i = 0; i < array.Length; i++)
		{
			Block(new PlatformUserID(array[i]));
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Vagon : MonoBehaviour, Hoverable, Interactable
{
	[Serializable]
	public class LoadData
	{
		public GameObject m_gameobject;

		public float m_minPercentage;
	}

	private static List<Vagon> m_instances = new List<Vagon>();

	public Transform m_attachPoint;

	public string m_name = "Wagon";

	public float m_detachDistance = 2f;

	public Vector3 m_attachOffset = new Vector3(0f, 0.8f, 0f);

	public Container m_container;

	public Transform m_lineAttachPoints0;

	public Transform m_lineAttachPoints1;

	public Vector3 m_lineAttachOffset = new Vector3(0f, 1f, 0f);

	public float m_breakForce = 10000f;

	public float m_spring = 5000f;

	public float m_springDamping = 1000f;

	public float m_baseMass = 20f;

	public float m_itemWeightMassFactor = 1f;

	public float m_playerExtraPullMass;

	public ZSFX[] m_wheelLoops;

	public float m_minPitch = 1f;

	public float m_maxPitch = 1.5f;

	public float m_maxPitchVel = 10f;

	public float m_maxVol = 1f;

	public float m_maxVolVel = 10f;

	public float m_audioChangeSpeed = 2f;

	public Rigidbody[] m_wheels = new Rigidbody[0];

	public List<LoadData> m_loadVis = new List<LoadData>();

	private ZNetView m_nview;

	private ConfigurableJoint m_attachJoin;

	private GameObject m_attachedObject;

	private Rigidbody m_body;

	private LineRenderer m_lineRenderer;

	private Rigidbody[] m_bodies;

	private Humanoid m_useRequester;

	private void Awake()
	{
		m_nview = GetComponent<ZNetView>();
		if (m_nview.GetZDO() == null)
		{
			base.enabled = false;
			return;
		}
		m_instances.Add(this);
		Heightmap.ForceGenerateAll();
		m_body = GetComponent<Rigidbody>();
		m_bodies = GetComponentsInChildren<Rigidbody>();
		m_lineRenderer = GetComponent<LineRenderer>();
		Rigidbody[] bodies = m_bodies;
		for (int i = 0; i < bodies.Length; i++)
		{
			bodies[i].maxDepenetrationVelocity = 2f;
		}
		m_nview.Register("RPC_RequestOwn", RPC_RequestOwn);
		m_nview.Register("RPC_RequestDenied", RPC_RequestDenied);
		InvokeRepeating("UpdateMass", 0f, 5f);
		InvokeRepeating("UpdateLoadVisualization", 0f, 3f);
	}

	private void OnDestroy()
	{
		m_instances.Remove(this);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public string GetHoverText()
	{
		return Localization.instance.Localize(m_name + "\n[<color=yellow><b>$KEY_Use</b></color>] $piece_use");
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		m_useRequester = character;
		if (!m_nview.IsOwner())
		{
			m_nview.InvokeRPC("RPC_RequestOwn");
		}
		return false;
	}

	public void RPC_RequestOwn(long sender)
	{
		if (m_nview.IsOwner())
		{
			if (InUse())
			{
				ZLog.Log("Requested use, but is already in use");
				m_nview.InvokeRPC(sender, "RPC_RequestDenied");
			}
			else
			{
				m_nview.GetZDO().SetOwner(sender);
			}
		}
	}

	private void RPC_RequestDenied(long sender)
	{
		ZLog.Log("Got request denied");
		if ((bool)m_useRequester)
		{
			m_useRequester.Message(MessageHud.MessageType.Center, m_name + " is in use by someone else");
			m_useRequester = null;
		}
	}

	private void FixedUpdate()
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		UpdateAudio(Time.fixedDeltaTime);
		if (m_nview.IsOwner())
		{
			if ((bool)m_useRequester)
			{
				if (IsAttached())
				{
					Detach();
				}
				else if (CanAttach(m_useRequester.gameObject))
				{
					AttachTo(m_useRequester.gameObject);
				}
				else
				{
					m_useRequester.Message(MessageHud.MessageType.Center, "$msg_cart_incorrectposition");
				}
				m_useRequester = null;
			}
			if (IsAttached() && (!m_attachJoin || !CanAttach(m_attachJoin.connectedBody.gameObject)))
			{
				Detach();
			}
		}
		else if (IsAttached())
		{
			Detach();
		}
	}

	private void LateUpdate()
	{
		if (IsAttached() && m_attachJoin != null)
		{
			m_lineRenderer.enabled = true;
			m_lineRenderer.SetPosition(0, m_lineAttachPoints0.position);
			m_lineRenderer.SetPosition(1, m_attachJoin.connectedBody.transform.position + m_lineAttachOffset);
			m_lineRenderer.SetPosition(2, m_lineAttachPoints1.position);
		}
		else
		{
			m_lineRenderer.enabled = false;
		}
	}

	public bool IsAttached(Character character)
	{
		if ((bool)m_attachJoin && m_attachJoin.connectedBody.gameObject == character.gameObject)
		{
			return true;
		}
		return false;
	}

	public bool InUse()
	{
		if ((bool)m_container && m_container.IsInUse())
		{
			return true;
		}
		return IsAttached();
	}

	public bool IsAttached()
	{
		if (!(m_attachJoin != null))
		{
			if (m_nview.IsValid())
			{
				return m_nview.GetZDO().GetBool(ZDOVars.s_attachJointHash);
			}
			return false;
		}
		return true;
	}

	private bool CanAttach(GameObject go)
	{
		if (base.transform.up.y < 0.1f)
		{
			return false;
		}
		Humanoid component = go.GetComponent<Humanoid>();
		if ((bool)component && (component.InDodge() || component.IsTeleporting()))
		{
			return false;
		}
		return Vector3.Distance(go.transform.position + m_attachOffset, m_attachPoint.position) < m_detachDistance;
	}

	private void AttachTo(GameObject go)
	{
		DetachAll();
		m_attachJoin = base.gameObject.AddComponent<ConfigurableJoint>();
		m_attachJoin.autoConfigureConnectedAnchor = false;
		m_attachJoin.anchor = m_attachPoint.localPosition;
		m_attachJoin.connectedAnchor = m_attachOffset;
		m_attachJoin.breakForce = m_breakForce;
		m_attachJoin.xMotion = ConfigurableJointMotion.Limited;
		m_attachJoin.yMotion = ConfigurableJointMotion.Limited;
		m_attachJoin.zMotion = ConfigurableJointMotion.Limited;
		SoftJointLimit linearLimit = new SoftJointLimit
		{
			limit = 0.001f
		};
		m_attachJoin.linearLimit = linearLimit;
		SoftJointLimitSpring linearLimitSpring = new SoftJointLimitSpring
		{
			spring = m_spring,
			damper = m_springDamping
		};
		m_attachJoin.linearLimitSpring = linearLimitSpring;
		m_attachJoin.zMotion = ConfigurableJointMotion.Locked;
		m_attachJoin.connectedBody = go.GetComponent<Rigidbody>();
		m_attachedObject = go;
		if (m_nview.IsValid())
		{
			m_nview.GetZDO().Set(ZDOVars.s_attachJointHash, value: true);
		}
		if (m_playerExtraPullMass != 0f)
		{
			m_attachedObject.GetComponent<Character>()?.SetExtraMass(m_playerExtraPullMass);
		}
	}

	private static void DetachAll()
	{
		foreach (Vagon instance in m_instances)
		{
			instance.Detach();
		}
	}

	private void Detach()
	{
		if ((bool)m_attachJoin)
		{
			UnityEngine.Object.Destroy(m_attachJoin);
		}
		m_attachJoin = null;
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_attachJointHash, value: false);
		}
		m_body.WakeUp();
		m_body.AddForce(0f, 1f, 0f);
		if (m_playerExtraPullMass != 0f && (bool)m_attachedObject)
		{
			m_attachedObject.GetComponent<Character>()?.SetExtraMass(0f);
		}
		m_attachedObject = null;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}

	private void UpdateMass()
	{
		if (m_nview.IsOwner() && !(m_container == null))
		{
			float totalWeight = m_container.GetInventory().GetTotalWeight();
			float mass = m_baseMass + totalWeight * m_itemWeightMassFactor;
			SetMass(mass);
		}
	}

	private void SetMass(float mass)
	{
		float mass2 = mass / (float)m_bodies.Length;
		Rigidbody[] bodies = m_bodies;
		for (int i = 0; i < bodies.Length; i++)
		{
			bodies[i].mass = mass2;
		}
	}

	private void UpdateLoadVisualization()
	{
		if (m_container == null)
		{
			return;
		}
		float num = m_container.GetInventory().SlotsUsedPercentage();
		foreach (LoadData loadVi in m_loadVis)
		{
			loadVi.m_gameobject.SetActive(num >= loadVi.m_minPercentage);
		}
	}

	private void UpdateAudio(float dt)
	{
		float num = 0f;
		Rigidbody[] wheels = m_wheels;
		foreach (Rigidbody rigidbody in wheels)
		{
			num += rigidbody.angularVelocity.magnitude;
		}
		num /= (float)m_wheels.Length;
		float target = Mathf.Lerp(m_minPitch, m_maxPitch, Mathf.Clamp01(num / m_maxPitchVel));
		float target2 = m_maxVol * Mathf.Clamp01(num / m_maxVolVel);
		ZSFX[] wheelLoops = m_wheelLoops;
		foreach (ZSFX obj in wheelLoops)
		{
			obj.SetVolumeModifier(Mathf.MoveTowards(obj.GetVolumeModifier(), target2, m_audioChangeSpeed * dt));
			obj.SetPitchModifier(Mathf.MoveTowards(obj.GetPitchModifier(), target, m_audioChangeSpeed * dt));
		}
	}
}
