			case SpiralEffectIntensitySetting.Normal:
				return NormalElementNudgeFactor;
			default:
			{
				global::_003CPrivateImplementationDetails_003E.ThrowSwitchExpressionException(spiralEffectInsensity);
				float result = default(float);
				return result;
			}
			}
