using System.Collections.Generic;
using Splatform;
using Steamworks;
using UnityEngine;
using UnityEngine.UI;
using UserManagement;

namespace Valheim.UI;

public class SessionPlayerList : MonoBehaviour
{
	[SerializeField]
	protected SessionPlayerListEntry _ownPlayer;

	[SerializeField]
	protected ScrollRect _scrollRect;

	[SerializeField]
	protected Button _backButton;

	private List<ZNet.PlayerInfo> _players;

	private readonly List<SessionPlayerListEntry> _remotePlayers = new List<SessionPlayerListEntry>();

	private readonly List<SessionPlayerListEntry> _allPlayers = new List<SessionPlayerListEntry>();

	protected void Awake()
	{
		MuteList.Load(Init);
	}

	private void Init()
	{
		SetEntries();
		foreach (SessionPlayerListEntry allPlayer in _allPlayers)
		{
			allPlayer.OnKicked += OnPlayerWasKicked;
		}
		_ownPlayer.FocusObject.Select();
		UpdateBlockButtons();
	}

	private void UpdateBlockButtons()
	{
		if (this == null)
		{
			return;
		}
		foreach (SessionPlayerListEntry allPlayer in _allPlayers)
		{
			allPlayer.UpdateBlockButton();
		}
	}

	private void OnPlayerWasKicked(SessionPlayerListEntry player)
	{
		player.OnKicked -= OnPlayerWasKicked;
		_allPlayers.Remove(player);
		_remotePlayers.Remove(player);
		Object.Destroy(player.gameObject);
		UpdateNavigation();
	}

	private void SetEntries()
	{
		_allPlayers.Add(_ownPlayer);
		PlatformUserID platformUserID = PlatformManager.DistributionPlatform.LocalUser.PlatformUserID;
		_players = ZNet.instance.GetPlayerList();
		ZNetPeer serverPeer = ZNet.instance.GetServerPeer();
		if (!ZNet.instance.IsServer() && _players.TryFindPlayerByPlayername(serverPeer.m_playerName, out var playerInfo))
		{
			if (ZNet.m_onlineBackend == OnlineBackendType.Steamworks)
			{
				PlatformUserID user = new PlatformUserID(PlatformManager.DistributionPlatform.Platform, serverPeer.m_socket.GetEndPointString());
				CreatePlayerEntry(user, serverPeer.m_playerName, isHost: true);
			}
			else
			{
				CreatePlayerEntry(playerInfo.Value.m_userInfo.m_id, playerInfo.Value.m_name, isHost: true);
			}
		}
		for (int i = 0; i < _players.Count; i++)
		{
			ZNet.PlayerInfo playerInfo2 = _players[i];
			if (playerInfo2.m_userInfo.m_id == platformUserID)
			{
				PlatformUserID user2 = new PlatformUserID(PlatformManager.DistributionPlatform.Platform, (ulong)SteamUser.GetSteamID());
				SetOwnPlayer(user2, ZNet.instance.IsServer());
			}
			else if (serverPeer == null || playerInfo2.m_name != serverPeer.m_playerName)
			{
				CreatePlayerEntry(playerInfo2.m_userInfo.m_id, playerInfo2.m_name);
			}
		}
		UpdateNavigation();
	}

	private void UpdateNavigation()
	{
		Navigation navigation = new Navigation
		{
			mode = Navigation.Mode.Explicit
		};
		int count = _allPlayers.Count;
		for (int i = 0; i < count; i++)
		{
			SessionPlayerListEntry sessionPlayerListEntry = _allPlayers[i];
			SessionPlayerListEntry sessionPlayerListEntry2 = ((i < count - 1) ? _allPlayers[i + 1] : null);
			Navigation navigation2 = sessionPlayerListEntry.BlockButton.navigation;
			navigation2.mode = (sessionPlayerListEntry.HasBlock ? Navigation.Mode.Explicit : Navigation.Mode.None);
			Navigation navigation3 = sessionPlayerListEntry.KickButton.navigation;
			navigation3.mode = (sessionPlayerListEntry.HasKick ? Navigation.Mode.Explicit : Navigation.Mode.None);
			Navigation navigation4 = sessionPlayerListEntry.FocusObject.navigation;
			navigation4.mode = (sessionPlayerListEntry.HasFocusObject ? Navigation.Mode.Explicit : Navigation.Mode.None);
			if (sessionPlayerListEntry2 != null)
			{
				if (!sessionPlayerListEntry.HasActivatedButtons && !sessionPlayerListEntry2.HasActivatedButtons)
				{
					navigation4.selectOnDown = sessionPlayerListEntry2.FocusObject;
				}
				else if (!sessionPlayerListEntry.HasActivatedButtons && sessionPlayerListEntry2.HasActivatedButtons)
				{
					if (sessionPlayerListEntry2.HasBlock)
					{
						navigation4.selectOnDown = sessionPlayerListEntry2.BlockButton;
					}
					else if (sessionPlayerListEntry2.HasKick)
					{
						navigation4.selectOnDown = sessionPlayerListEntry2.KickButton;
					}
				}
				else if (sessionPlayerListEntry.HasActivatedButtons && !sessionPlayerListEntry2.HasActivatedButtons)
				{
					if (sessionPlayerListEntry.HasBlock)
					{
						navigation2.selectOnDown = sessionPlayerListEntry2.FocusObject;
					}
					if (sessionPlayerListEntry.HasKick)
					{
						navigation3.selectOnDown = sessionPlayerListEntry2.FocusObject;
					}
				}
				else
				{
					if (sessionPlayerListEntry.HasBlock)
					{
						if (sessionPlayerListEntry2.HasBlock)
						{
							navigation2.selectOnDown = sessionPlayerListEntry2.BlockButton;
						}
						else if (sessionPlayerListEntry2.HasKick)
						{
							navigation2.selectOnDown = sessionPlayerListEntry2.KickButton;
						}
					}
					if (sessionPlayerListEntry.HasKick)
					{
						if (sessionPlayerListEntry2.HasKick)
						{
							navigation3.selectOnDown = sessionPlayerListEntry2.KickButton;
						}
						else if (sessionPlayerListEntry2.HasBlock)
						{
							navigation3.selectOnDown = sessionPlayerListEntry2.BlockButton;
						}
					}
				}
			}
			else if (sessionPlayerListEntry.HasActivatedButtons)
			{
				if (sessionPlayerListEntry.HasBlock)
				{
					navigation.selectOnUp = sessionPlayerListEntry.BlockButton;
				}
				else if (sessionPlayerListEntry.HasKick)
				{
					navigation.selectOnUp = sessionPlayerListEntry.KickButton;
				}
				if (sessionPlayerListEntry.HasBlock)
				{
					navigation2.selectOnDown = _backButton;
				}
				if (sessionPlayerListEntry.HasKick)
				{
					navigation3.selectOnDown = _backButton;
				}
			}
			else
			{
				navigation4.selectOnDown = _backButton;
				navigation.selectOnUp = sessionPlayerListEntry.FocusObject;
			}
			sessionPlayerListEntry.BlockButton.navigation = navigation2;
			sessionPlayerListEntry.KickButton.navigation = navigation3;
			sessionPlayerListEntry.FocusObject.navigation = navigation4;
		}
		for (int num = count - 1; num >= 0; num--)
		{
			SessionPlayerListEntry sessionPlayerListEntry3 = _allPlayers[num];
			SessionPlayerListEntry sessionPlayerListEntry4 = ((num > 0) ? _allPlayers[num - 1] : null);
			Navigation navigation5 = sessionPlayerListEntry3.BlockButton.navigation;
			Navigation navigation6 = sessionPlayerListEntry3.KickButton.navigation;
			Navigation navigation7 = sessionPlayerListEntry3.FocusObject.navigation;
			if (sessionPlayerListEntry4 != null)
			{
				if (!sessionPlayerListEntry3.HasActivatedButtons && !sessionPlayerListEntry4.HasActivatedButtons)
				{
					navigation7.selectOnUp = sessionPlayerListEntry4.FocusObject;
				}
				else if (!sessionPlayerListEntry3.HasActivatedButtons && sessionPlayerListEntry4.HasActivatedButtons)
				{
					if (sessionPlayerListEntry4.HasBlock)
					{
						navigation7.selectOnUp = sessionPlayerListEntry4.BlockButton;
					}
					else if (sessionPlayerListEntry4.HasKick)
					{
						navigation7.selectOnUp = sessionPlayerListEntry4.KickButton;
					}
				}
				else if (sessionPlayerListEntry3.HasActivatedButtons && !sessionPlayerListEntry4.HasActivatedButtons)
				{
					if (sessionPlayerListEntry3.HasBlock)
					{
						navigation5.selectOnUp = sessionPlayerListEntry4.FocusObject;
					}
					if (sessionPlayerListEntry3.HasKick)
					{
						navigation6.selectOnUp = sessionPlayerListEntry4.FocusObject;
					}
				}
				else
				{
					if (sessionPlayerListEntry3.HasBlock)
					{
						if (sessionPlayerListEntry4.HasBlock)
						{
							navigation5.selectOnUp = sessionPlayerListEntry4.BlockButton;
						}
						else if (sessionPlayerListEntry4.HasKick)
						{
							navigation5.selectOnUp = sessionPlayerListEntry4.KickButton;
						}
					}
					if (sessionPlayerListEntry3.HasKick)
					{
						if (sessionPlayerListEntry4.HasKick)
						{
							navigation6.selectOnUp = sessionPlayerListEntry4.KickButton;
						}
						else if (sessionPlayerListEntry4.HasBlock)
						{
							navigation6.selectOnUp = sessionPlayerListEntry4.BlockButton;
						}
					}
				}
			}
			sessionPlayerListEntry3.BlockButton.navigation = navigation5;
			sessionPlayerListEntry3.KickButton.navigation = navigation6;
			sessionPlayerListEntry3.FocusObject.navigation = navigation7;
		}
		_backButton.navigation = navigation;
	}

	private void SetOwnPlayer(PlatformUserID user, bool isHost)
	{
		UserInfo localUser = UserInfo.GetLocalUser();
		_ownPlayer.IsOwnPlayer = true;
		_ownPlayer.SetValues(localUser.Name, user, isHost, canBeBlocked: false, canBeKicked: false);
	}

	private void CreatePlayerEntry(PlatformUserID user, string name, bool isHost = false)
	{
		SessionPlayerListEntry sessionPlayerListEntry = Object.Instantiate(_ownPlayer, _scrollRect.content);
		sessionPlayerListEntry.IsOwnPlayer = false;
		sessionPlayerListEntry.SetValues(name, user, isHost, canBeBlocked: true, !isHost && ZNet.instance.LocalPlayerIsAdminOrHost());
		if (!isHost)
		{
			_remotePlayers.Add(sessionPlayerListEntry);
		}
		_allPlayers.Add(sessionPlayerListEntry);
	}

	public void OnBack()
	{
		foreach (SessionPlayerListEntry allPlayer in _allPlayers)
		{
			allPlayer.RemoveCallbacks();
		}
		MuteList.Persist();
		Object.Destroy(base.gameObject);
	}

	private void Update()
	{
		UpdateScrollPosition();
		if (ZInput.GetKeyDown(KeyCode.Escape))
		{
			OnBack();
		}
	}

	private void UpdateScrollPosition()
	{
		if (!_scrollRect.verticalScrollbar.gameObject.activeSelf)
		{
			return;
		}
		foreach (SessionPlayerListEntry allPlayer in _allPlayers)
		{
			if (allPlayer.IsSelected && !_scrollRect.IsVisible(allPlayer.transform as RectTransform))
			{
				_scrollRect.SnapToChild(allPlayer.transform as RectTransform);
				break;
			}
		}
	}
}
using System;
using Splatform;
using TMPro;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UserManagement;

namespace Valheim.UI;

public class SessionPlayerListEntry : MonoBehaviour
{
	[SerializeField]
	private Button _button;

	[SerializeField]
	private Selectable _focusPoint;

	[SerializeField]
	private Image _selection;

	[SerializeField]
	private GameObject _viewPlayerCard;

	[SerializeField]
	private Image _outline;

	[Header("Player")]
	[SerializeField]
	private Image _hostIcon;

	[SerializeField]
	private Image _gamerpic;

	[SerializeField]
	private Sprite otherPlatformPlayerPic;

	[SerializeField]
	private TextMeshProUGUI _gamertagText;

	[SerializeField]
	private TextMeshProUGUI _characterNameText;

	[Header("Block")]
	[SerializeField]
	private Button _blockButton;

	[SerializeField]
	private Image _blockButtonImage;

	[SerializeField]
	private Sprite _blockSprite;

	[SerializeField]
	private Sprite _unblockSprite;

	[Header("Kick")]
	[SerializeField]
	private Button _kickButton;

	[SerializeField]
	private Image _kickButtonImage;

	private PlatformUserID _user;

	private IUserProfile _userProfile;

	private string _gamertag;

	private string _characterName;

	public bool IsSelected => _selection.enabled;

	public Selectable FocusObject => _focusPoint;

	public Selectable BlockButton => _blockButton;

	public Selectable KickButton => _kickButton;

	public PlatformUserID User => _user;

	public bool HasFocusObject => _focusPoint.gameObject.activeSelf;

	public bool HasBlock => _blockButtonImage.gameObject.activeSelf;

	public bool HasKick => _kickButtonImage.gameObject.activeSelf;

	public bool HasActivatedButtons
	{
		get
		{
			if (!_blockButtonImage.gameObject.activeSelf)
			{
				return _kickButtonImage.gameObject.activeSelf;
			}
			return true;
		}
	}

	public bool IsSamePlatform => _user.m_platform == PlatformManager.DistributionPlatform.Platform;

	public bool IsOwnPlayer
	{
		get
		{
			return _outline.gameObject.activeSelf;
		}
		set
		{
			_outline.gameObject.SetActive(value);
		}
	}

	public bool IsHost
	{
		get
		{
			return _hostIcon.gameObject.activeSelf;
		}
		set
		{
			_hostIcon.gameObject.SetActive(value);
		}
	}

	private bool CanBeKicked
	{
		get
		{
			return _kickButtonImage.gameObject.activeSelf;
		}
		set
		{
			_kickButtonImage.gameObject.SetActive(value && !IsHost);
		}
	}

	private bool CanBeBlocked
	{
		get
		{
			return _blockButtonImage.gameObject.activeSelf;
		}
		set
		{
			_blockButtonImage.gameObject.SetActive(value);
		}
	}

	private bool CanBeMuted
	{
		get
		{
			return false;
		}
		set
		{
			throw new NotImplementedException();
		}
	}

	public string Gamertag
	{
		get
		{
			return _gamertag;
		}
		set
		{
			string text = "";
			if (value != null)
			{
				text += value;
			}
			_gamertag = text;
			if (IsHost)
			{
				text += " (Host)";
			}
			_gamertagText.text = text;
		}
	}

	public string CharacterName
	{
		get
		{
			return _characterName;
		}
		set
		{
			string text = value;
			if (!IsOwnPlayer)
			{
				text = CensorShittyWords.FilterUGC(text, UGCType.CharacterName, _user, 0L);
			}
			_characterName = text;
			_characterNameText.text = text;
		}
	}

	public event Action<SessionPlayerListEntry> OnKicked;

	private void Awake()
	{
		_selection.enabled = false;
		_viewPlayerCard.SetActive(value: false);
		if (_button != null)
		{
			_button.enabled = true;
		}
	}

	private void Update()
	{
		if (EventSystem.current != null && (EventSystem.current.currentSelectedGameObject == _focusPoint.gameObject || EventSystem.current.currentSelectedGameObject == _blockButton.gameObject || EventSystem.current.currentSelectedGameObject == _kickButton.gameObject || EventSystem.current.currentSelectedGameObject == _button.gameObject))
		{
			SelectEntry();
		}
		else
		{
			Deselect();
		}
		UpdateFocusPoint();
	}

	public void SelectEntry()
	{
		_selection.enabled = true;
		_viewPlayerCard.SetActive(IsSamePlatform);
	}

	public void Deselect()
	{
		_selection.enabled = false;
		_viewPlayerCard.SetActive(value: false);
	}

	public void OnBlock()
	{
		if (RelationsManager.IsBlocked(_user))
		{
			OnViewCard();
			return;
		}
		if (MuteList.Contains(_user))
		{
			MuteList.Unblock(_user);
		}
		else
		{
			MuteList.Block(_user);
		}
		UpdateBlockButton();
	}

	private void UpdateButtons()
	{
		UpdateBlockButton();
		UpdateFocusPoint();
	}

	private void UpdateFocusPoint()
	{
		_focusPoint.gameObject.SetActive(!HasActivatedButtons);
	}

	public void UpdateBlockButton()
	{
		_blockButtonImage.sprite = ((MuteList.Contains(_user) || RelationsManager.IsBlocked(_user)) ? _unblockSprite : _blockSprite);
	}

	public void OnKick()
	{
		if (ZNet.instance != null)
		{
			UnifiedPopup.Push(new YesNoPopup("$menu_kick_player_title", Localization.instance.Localize("$menu_kick_player", CharacterName), delegate
			{
				ZNet.instance.Kick(CharacterName);
				this.OnKicked?.Invoke(this);
				UnifiedPopup.Pop();
			}, delegate
			{
				UnifiedPopup.Pop();
			}));
		}
	}

	public void SetValues(string characterName, PlatformUserID user, bool isHost, bool canBeBlocked, bool canBeKicked)
	{
		_user = user;
		IsHost = isHost;
		CharacterName = characterName;
		Gamertag = "";
		_gamerpic.sprite = otherPlatformPlayerPic;
		if (IsSamePlatform && PlatformManager.DistributionPlatform.RelationsProvider != null)
		{
			PlatformManager.DistributionPlatform.RelationsProvider.GetUserProfileAsync(user, GetUserProfileCompleted, GetUserProfileFailed);
		}
		else
		{
			UpdateProfile();
		}
		CanBeKicked = !isHost && canBeKicked;
		CanBeBlocked = canBeBlocked;
		UpdateButtons();
	}

	private void GetUserProfileCompleted(IUserProfile profile)
	{
		if (!(this == null))
		{
			_ = DateTime.UtcNow;
			_userProfile = profile;
			_userProfile.RequestProfilePictureAsync(GetProfilePictureResolution());
			UpdateProfile();
			_userProfile.ProfileDataUpdated += UpdateProfile;
			UpdateProfilePicture();
			_userProfile.ProfilePictureUpdated += UpdateProfilePicture;
		}
	}

	private static uint GetProfilePictureResolution()
	{
		if (PlatformManager.DistributionPlatform.HardwareInfoProvider == null)
		{
			return 128u;
		}
		HardwareInfo hardwareInfo = PlatformManager.DistributionPlatform.HardwareInfoProvider.HardwareInfo;
		if (hardwareInfo.m_category == HardwareCategory.Unknown)
		{
			return 128u;
		}
		if (hardwareInfo.m_category < HardwareCategory.Console)
		{
			return 50u;
		}
		if (hardwareInfo.m_category == HardwareCategory.Console && hardwareInfo.m_generation <= 8)
		{
			return 50u;
		}
		return 128u;
	}

	private void GetUserProfileFailed(PlatformUserID userId, GetUserProfileFailReason failReason)
	{
		switch (failReason)
		{
		case GetUserProfileFailReason.DifferentPlatformsNotAvailable:
		case GetUserProfileFailReason.SamePlatformNotAvailable:
			return;
		}
		Debug.LogError($"Failed to get user profile for user {userId}: {failReason}");
	}

	private void UpdateProfile()
	{
		string displayName;
		if (IsSamePlatform)
		{
			Gamertag = _userProfile.DisplayName;
		}
		else if (ZNet.TryGetServerAssignedDisplayName(_user, out displayName))
		{
			Gamertag = displayName;
		}
		UpdateButtons();
	}

	private void UpdateProfilePicture()
	{
		if (IsSamePlatform && _userProfile.ProfilePicture != null)
		{
			_gamerpic.SetSpriteFromTexture(_userProfile.ProfilePicture);
		}
		else
		{
			_gamerpic.sprite = otherPlatformPlayerPic;
		}
	}

	public void OnViewCard()
	{
		if (PlatformManager.DistributionPlatform.UIProvider.ShowUserProfile != null && IsSamePlatform)
		{
			PlatformManager.DistributionPlatform.UIProvider.ShowUserProfile.Open(_user);
		}
	}

	public void RemoveCallbacks()
	{
		if (_userProfile != null)
		{
			_userProfile.ProfileDataUpdated -= UpdateProfile;
			_userProfile.ProfilePictureUpdated -= UpdateProfilePicture;
		}
	}
}
using System.Collections;
using System.Collections.Generic;
using Steamworks;
using UnityEngine;
using UnityEngine.Networking;
using UnityEngine.UI;

namespace Valheim.UI;

public static class SessionPlayerListHelper
{
	public static IEnumerator SetSpriteFromUri(this Image image, string uri)
	{
		UnityWebRequest www = UnityWebRequestTexture.GetTexture(uri);
		yield return www.SendWebRequest();
		if (www.result != UnityWebRequest.Result.Success)
		{
			Debug.Log(www.error);
			yield break;
		}
		Texture2D content = DownloadHandlerTexture.GetContent(www);
		image.sprite = Sprite.Create(content, new Rect(0f, 0f, content.width, content.height), new Vector2(0.5f, 0.5f));
		image.transform.localScale = new Vector3(1f, 1f, 1f);
	}

	public static void SetSpriteFromTexture(this Image image, Texture2D texture)
	{
		image.sprite = Sprite.Create(texture, new Rect(0f, 0f, texture.width, texture.height), new Vector2(0.5f, 0.5f));
		image.transform.localScale = new Vector3(1f, 1f, 1f);
	}

	public static void SetSpriteFromSteamImageId(this Image image, int imageId)
	{
		uint pnWidth;
		uint pnHeight;
		if (imageId <= 0)
		{
			image.SetTransparent();
		}
		else if (SteamUtils.GetImageSize(imageId, out pnWidth, out pnHeight))
		{
			uint num = pnWidth * pnHeight * 4;
			byte[] array = new byte[num];
			Texture2D texture2D = new Texture2D((int)pnWidth, (int)pnHeight, TextureFormat.RGBA32, mipChain: false, linear: true);
			if (SteamUtils.GetImageRGBA(imageId, array, (int)num))
			{
				texture2D.LoadRawTextureData(array);
				texture2D.FlipInYDirection();
				image.sprite = Sprite.Create(texture2D, new Rect(0f, 0f, texture2D.width, texture2D.height), new Vector2(0.5f, 0.5f));
			}
		}
	}

	private static void SetTransparent(this Image image)
	{
		Texture2D texture2D = new Texture2D(1, 1, TextureFormat.RGBA32, mipChain: false);
		texture2D.SetPixels(new Color[1]
		{
			new Color(0f, 0f, 0f, 0f)
		});
		image.sprite = Sprite.Create(texture2D, new Rect(0f, 0f, texture2D.width, texture2D.height), new Vector2(0.5f, 0.5f));
	}

	private static void FlipInYDirection(this Texture2D texture)
	{
		Color[] pixels = texture.GetPixels();
		Color[] array = new Color[pixels.Length];
		int num = 0;
		for (int num2 = texture.height - 1; num2 >= 0; num2--)
		{
			for (int i = 0; i < texture.width; i++)
			{
				array[num] = pixels[num2 * texture.height + i];
				num++;
			}
		}
		texture.SetPixels(array);
		texture.Apply();
	}

	public static bool TryFindPlayerByZDOID(this List<ZNet.PlayerInfo> players, ZDOID playerID, out ZNet.PlayerInfo? playerInfo)
	{
		playerInfo = null;
		for (int i = 0; i < players.Count; i++)
		{
			ZNet.PlayerInfo value = players[i];
			if (value.m_characterID == playerID)
			{
				playerInfo = value;
				return true;
			}
		}
		return false;
	}

	public static bool TryFindPlayerByPlayername(this List<ZNet.PlayerInfo> players, string name, out ZNet.PlayerInfo? playerInfo)
	{
		playerInfo = null;
		for (int i = 0; i < players.Count; i++)
		{
			ZNet.PlayerInfo value = players[i];
			if (value.m_name == name)
			{
				playerInfo = value;
				return true;
			}
		}
		return false;
	}

	public static bool IsBanned(string characterName)
	{
		return ZNet.instance.Banned.Contains(characterName);
	}
}
