namespace Valheim.UI;

[CreateAssetMenu(fileName = "ValheimRadialConfig", menuName = "Valheim/Radial/Group Config/Main Group Config")]
public class ValheimRadialConfig : ScriptableObject, IRadialConfig
{
	public string LocalizedName => "Main";

	public Sprite Sprite => null;

	public void InitRadialConfig(RadialBase radial)
	{
		List<RadialMenuElement> list = new List<RadialMenuElement>();
		AddHotbarGroup(radial, list);
		AddItemGroup(radial, list, "consumables");
		AddItemGroup(radial, list, "weaponstools");
		AddItemGroup(radial, list, "armor_utility");
		AddEmoteGroup(radial, list);
		AddItemGroup(radial, list, "allitems");
		if (Player.m_localPlayer != null && Player.m_localPlayer.GetInventory().ContainsItemByName("$item_hammer"))
		{
			AddHammer(list);
		}
		else
		{
			AddEmpty(list);
		}
		if (radial.LastUsed != null)
		{
			list.Add(radial.LastUsed);
			radial.LastUsed.Hovering = 0f;
		}
		else
		{
			AddEmpty(list);
		}
		radial.ConstructRadial(list);
	}

	private void AddEmoteGroup(RadialBase radial, List<RadialMenuElement> elements)
	{
		GroupElement groupElement = Object.Instantiate(RadialData.SO.GroupElement);
		EmoteGroupConfig config = Object.Instantiate(RadialData.SO.EmoteGroupConfig);
		groupElement.Init(config, this, radial);
		elements.Add(groupElement);
	}

	private void AddHotbarGroup(RadialBase radial, List<RadialMenuElement> elements)
	{
		GroupElement groupElement = Object.Instantiate(RadialData.SO.GroupElement);
		HotbarGroupConfig config = Object.Instantiate(RadialData.SO.HotbarGroupConfig);
		groupElement.Init(config, this, radial);
		elements.Add(groupElement);
	}

	private void AddItemGroup(RadialBase radial, List<RadialMenuElement> elements, string groupName)
	{
		GroupElement groupElement = Object.Instantiate(RadialData.SO.GroupElement);
		ItemGroupConfig itemGroupConfig = Object.Instantiate(RadialData.SO.ItemGroupConfig);
		itemGroupConfig.GroupName = groupName;
		groupElement.Init(itemGroupConfig, this, radial);
		elements.Add(groupElement);
	}

	private void AddEmpty(List<RadialMenuElement> elements)
	{
		EmptyElement emptyElement = Object.Instantiate(RadialData.SO.EmptyElement);
		emptyElement.Init();
		elements.Add(emptyElement);
	}

	private void AddHammer(List<RadialMenuElement> elements)
	{
		HammerItemElement hammerItemElement = Object.Instantiate(RadialData.SO.HammerItemElement);
		hammerItemElement.Init();
		elements.Add(hammerItemElement);
	}
}
using System;
using UnityEngine;

public class Valkyrie : MonoBehaviour
{
	public static Valkyrie m_instance;

	public float m_speed = 10f;

	public float m_turnRate = 5f;

	public float m_dropHeight = 10f;

	public float m_startAltitude = 500f;

	public float m_descentAltitude = 100f;

	public float m_startDistance = 500f;

	public float m_startDescentDistance = 200f;

	public Vector3 m_attachOffset = new Vector3(0f, 0f, 1f);

	public float m_textDuration = 5f;

	public Transform m_attachPoint;

	private Vector3 m_targetPoint;

	private Vector3 m_descentStart;

	private Vector3 m_flyAwayPoint;

	private bool m_descent;

	private bool m_droppedPlayer;

	private Animator m_animator;

	private ZNetView m_nview;

	private float m_timer;

	private void Awake()
	{
		m_instance = this;
		m_nview = GetComponent<ZNetView>();
		m_animator = GetComponentInChildren<Animator>();
		if (!m_nview.IsOwner())
		{
			base.enabled = false;
			return;
		}
		ZLog.Log("Setting up valkyrie ");
		float f = UnityEngine.Random.value * MathF.PI * 2f;
		Vector3 vector = new Vector3(Mathf.Sin(f), 0f, Mathf.Cos(f));
		Vector3 vector2 = Vector3.Cross(vector, Vector3.up);
		m_targetPoint = Player.m_localPlayer.transform.position + new Vector3(0f, m_dropHeight, 0f);
		Vector3 position = m_targetPoint + vector * m_startDistance;
		position.y = m_startAltitude;
		base.transform.position = position;
		m_descentStart = m_targetPoint + vector * m_startDescentDistance + vector2 * 200f;
		m_descentStart.y = m_descentAltitude;
		Vector3 vector3 = m_targetPoint - m_descentStart;
		vector3.y = 0f;
		vector3.Normalize();
		m_flyAwayPoint = m_targetPoint + vector3 * m_startDescentDistance;
		m_flyAwayPoint.y = m_startAltitude;
		SyncPlayer(doNetworkSync: true);
		ZLog.Log("World pos " + base.transform.position.ToString() + "   " + ZNet.instance.GetReferencePosition().ToString());
	}

	private void HideText()
	{
	}

	private void OnDestroy()
	{
		ZLog.Log("Destroying valkyrie");
	}

	private void FixedUpdate()
	{
		UpdateValkyrie(Time.fixedDeltaTime);
		if (!m_droppedPlayer)
		{
			SyncPlayer(doNetworkSync: true);
		}
	}

	private void LateUpdate()
	{
		if (!m_droppedPlayer)
		{
			SyncPlayer(doNetworkSync: false);
		}
	}

	private void UpdateValkyrie(float dt)
	{
		m_timer += dt;
		if (TextViewer.IsShowingIntro())
		{
			return;
		}
		Vector3 vector = (m_droppedPlayer ? m_flyAwayPoint : ((!m_descent) ? m_descentStart : m_targetPoint));
		if (Utils.DistanceXZ(vector, base.transform.position) < 0.5f)
		{
			if (!m_descent)
			{
				m_descent = true;
				ZLog.Log("Starting descent");
			}
			else if (!m_droppedPlayer)
			{
				ZLog.Log("We are here");
				DropPlayer();
			}
			else
			{
				m_nview.Destroy();
			}
		}
		Vector3 normalized = (vector - base.transform.position).normalized;
		Vector3 vector2 = base.transform.position + normalized * 25f;
		if (ZoneSystem.instance.GetGroundHeight(vector2, out var height))
		{
			vector2.y = Mathf.Max(vector2.y, height + m_dropHeight);
		}
		Vector3 normalized2 = (vector2 - base.transform.position).normalized;
		Quaternion quaternion = Quaternion.LookRotation(normalized2);
		Vector3 to = normalized2;
		to.y = 0f;
		to.Normalize();
		Vector3 forward = base.transform.forward;
		forward.y = 0f;
		forward.Normalize();
		float num = Mathf.Clamp(Vector3.SignedAngle(forward, to, Vector3.up), -30f, 30f) / 30f;
		quaternion = Quaternion.Euler(0f, 0f, num * 45f) * quaternion;
		float num2 = (m_droppedPlayer ? (m_turnRate * 4f) : m_turnRate);
		base.transform.rotation = Quaternion.RotateTowards(base.transform.rotation, quaternion, num2 * dt);
		Vector3 vector3 = base.transform.forward * m_speed;
		Vector3 vector4 = base.transform.position + vector3 * dt;
		if (ZoneSystem.instance.GetGroundHeight(vector4, out var height2))
		{
			vector4.y = Mathf.Max(vector4.y, height2 + m_dropHeight);
		}
		base.transform.position = vector4;
	}

	public void DropPlayer(bool destroy = false)
	{
		ZLog.Log("We are here");
		m_droppedPlayer = true;
		Vector3 forward = base.transform.forward;
		forward.y = 0f;
		forward.Normalize();
		Player.m_localPlayer.transform.rotation = Quaternion.LookRotation(forward);
		Player.m_localPlayer.SetIntro(intro: false);
		m_animator.SetBool("dropped", value: true);
		if (destroy)
		{
			m_nview.Destroy();
		}
	}

	private void SyncPlayer(bool doNetworkSync)
	{
		Player localPlayer = Player.m_localPlayer;
		if (localPlayer == null)
		{
			ZLog.LogWarning("No local player");
			return;
		}
		localPlayer.transform.rotation = m_attachPoint.rotation;
		localPlayer.transform.position = m_attachPoint.position - localPlayer.transform.TransformVector(m_attachOffset);
		localPlayer.GetComponent<Rigidbody>().position = localPlayer.transform.position;
		if (doNetworkSync)
		{
			ZNet.instance.SetReferencePosition(localPlayer.transform.position);
			localPlayer.GetComponent<ZSyncTransform>().SyncNow();
			GetComponent<ZSyncTransform>().SyncNow();
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class VariantDialog : MonoBehaviour
{
	public Transform m_listRoot;

	public GameObject m_elementPrefab;

	public float m_spacing = 70f;

	public int m_gridWidth = 5;

	private List<GameObject> m_elements = new List<GameObject>();

	public Action<int> m_selected;

	public void Setup(ItemDrop.ItemData item)
	{
		base.gameObject.SetActive(value: true);
		foreach (GameObject element in m_elements)
		{
			UnityEngine.Object.Destroy(element);
		}
		m_elements.Clear();
		for (int i = 0; i < item.m_shared.m_variants; i++)
		{
			Sprite sprite = item.m_shared.m_icons[i];
			int num = i / m_gridWidth;
			int num2 = i % m_gridWidth;
			GameObject gameObject = UnityEngine.Object.Instantiate(m_elementPrefab, Vector3.zero, Quaternion.identity, m_listRoot);
			gameObject.SetActive(value: true);
			(gameObject.transform as RectTransform).anchoredPosition = new Vector2((float)num2 * m_spacing, (float)(-num) * m_spacing);
			Button component = gameObject.transform.Find("Button").GetComponent<Button>();
			int buttonIndex = i;
			component.onClick.AddListener(delegate
			{
				OnClicked(buttonIndex);
			});
			component.GetComponent<Image>().sprite = sprite;
			m_elements.Add(gameObject);
		}
	}

	public void OnClose()
	{
		base.gameObject.SetActive(value: false);
	}

	private void OnClicked(int index)
	{
		ZLog.Log("Clicked button " + index);
		base.gameObject.SetActive(value: false);
		m_selected(index);
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class Vegvisir : MonoBehaviour, Hoverable, Interactable
{
	[Serializable]
	public class VegvisrLocation
	{
		public string m_locationName = "";

		public string m_pinName = "Pin";

		public Minimap.PinType m_pinType;

		[Tooltip("Discovers all locations of given name, rather than just the closest one.")]
		public bool m_discoverAll;

		public bool m_showMap = true;
	}

	public string m_name = "$piece_vegvisir";

	public string m_useText = "$piece_register_location";

	public string m_hoverName = "Pin";

	public string m_setsGlobalKey = "";

	public string m_setsPlayerKey = "";

	public List<VegvisrLocation> m_locations = new List<VegvisrLocation>();

	public string GetHoverText()
	{
		return Localization.instance.Localize(m_name + " " + m_hoverName + "\n[<color=yellow><b>$KEY_Use</b></color>] " + m_useText);
	}

	public string GetHoverName()
	{
		return m_name;
	}

	public bool Interact(Humanoid character, bool hold, bool alt)
	{
		if (hold)
		{
			return false;
		}
		foreach (VegvisrLocation location in m_locations)
		{
			Game.instance.DiscoverClosestLocation(location.m_locationName, base.transform.position, location.m_pinName, (int)location.m_pinType, location.m_showMap, location.m_discoverAll);
			Gogan.LogEvent("Game", "Vegvisir", location.m_locationName, 0L);
		}
		if (!string.IsNullOrEmpty(m_setsGlobalKey))
		{
			ZoneSystem.instance.SetGlobalKey(m_setsGlobalKey);
		}
		if (!string.IsNullOrEmpty(m_setsPlayerKey) && character is Player player)
		{
			player.AddUniqueKey(m_setsPlayerKey);
		}
		return true;
	}

	public bool UseItem(Humanoid user, ItemDrop.ItemData item)
	{
		return false;
	}
}
using UnityEngine;

internal class Version
{
	public const uint m_networkVersion = 36u;

	public const int m_playerVersion = 43;

	public const int m_oldestForwardCompatiblePlayerVersion = 27;

	public const int m_worldVersion = 37;

	public const int m_oldestForwardCompatibleWorldVersion = 9;

	public const int c_WorldVersionNewSaveFormat = 31;

	public const int c_WorldVersionGlobalKeys = 32;

	public const int c_WorldVersionNumItems = 33;

	public const int c_PlayerVersionMovedFirstSpawn = 40;

	public const int c_PlayerDataVersionMovedFirstSpawn = 28;

	public const int c_NetworkVersionMaxPlayerCount = 35;

	public const int m_worldGenVersion = 2;

	public const int m_itemDataVersion = 106;

	public const int m_playerDataVersion = 29;

	public static readonly GameVersion FirstVersionWithNetworkVersion = new GameVersion(0, 214, 301);

	public static readonly GameVersion FirstVersionWithPlatformRestriction = new GameVersion(0, 213, 3);

	public static readonly GameVersion FirstVersionWithModifiers = new GameVersion(0, 217, 8);

	public static GameVersion CurrentVersion { get; } = new GameVersion(0, 221, 12);

	public static string GetVersionString(bool includeMercurialHash = false)
	{
		string text = CurrentVersion.ToString();
		string platformPrefix = GetPlatformPrefix();
		if (platformPrefix.Length > 0)
		{
			text = $"{platformPrefix}-{CurrentVersion}";
		}
		if (includeMercurialHash)
		{
			TextAsset textAsset = Resources.Load<TextAsset>("clientVersion");
			if (textAsset != null)
			{
				text = text + "\n" + textAsset.text;
			}
		}
		return text;
	}

	public static bool IsWorldVersionCompatible(int version)
	{
		if (version <= 37)
		{
			return version >= 9;
		}
		return false;
	}

	public static bool IsPlayerVersionCompatible(int version)
	{
		if (version <= 43)
		{
			return version >= 27;
		}
		return false;
	}

	public static Platforms GetPlatform()
	{
		if (Settings.IsSteamRunningOnSteamDeck())
		{
			return Platforms.SteamDeckProton;
		}
		return Platforms.SteamWindows;
	}

	public static string GetPlatformPrefix(string Default = "")
	{
		return GetPlatform() switch
		{
			Platforms.SteamLinux => "l", 
			Platforms.SteamDeckProton => "dw", 
			Platforms.SteamDeckNative => "dl", 
			Platforms.MicrosoftStore => "ms", 
			_ => Default, 
		};
	}

	public static string GetHardwarePrefix()
	{
		return "";
	}
}
