	public float m_maxGrowWidth = 3f;

	[Tooltip("Extra grow width limitation per height")]
	public float m_extraGrowWidthPerHeight = 0.5f;

	[Tooltip("Chance to ignore width limitaion.")]
	[Range(0f, 1f)]
