	private int m_myIndex = -1;

	private float m_rainTimer;

	private float m_lastRepair;

	private Piece m_piece;

	private GameObject m_roof;

	private float m_healthPercentage = 100f;

	private bool m_clearCachedSupport;

	private Heightmap m_connectedHeightMap;

	private float m_burnDamageTime;

	private float m_ashDamageTime;

	private float m_ashMaterialValue;

	private float m_lastBurnDamageTime;

	private float m_lastMaterialValueTimeCheck;

	private readonly List<Collider> m_supportColliders = new List<Collider>();

	private readonly List<Vector3> m_supportPositions = new List<Vector3>();

	private readonly List<float> m_supportValue = new List<float>();

	private WaterVolume m_previousWaterVolume;

	private GameObject m_ashroof;

	private Heightmap.Biome m_biome;

	private Heightmap m_heightmap;

	private float m_groundDist;

	private float m_ashTimer;

	private bool m_inAshlands;

	private int m_shieldChangeID;

	private float m_lavaTimer;

	private float m_lavaValue;

	private bool m_rainWet;

	private List<BoundData> m_bounds;

	private List<OldMeshData> m_oldMaterials;

	private float m_updateCoverTimer;

	private bool m_haveRoof = true;

	private bool m_haveAshRoof = true;

	private const float c_UpdateCoverFrequency = 4f;

	private static int? s_terrainLayer = -1;

	private void Awake()
	{
		if (s_terrainLayer < 0)
		{
			s_terrainLayer = LayerMask.NameToLayer("terrain");
		}
		m_nview = GetComponent<ZNetView>();
		m_piece = GetComponent<Piece>();
		if (m_nview.GetZDO() != null)
		{
			m_nview.Register<HitData>("RPC_Damage", RPC_Damage);
			m_nview.Register<bool>("RPC_Remove", RPC_Remove);
			m_nview.Register("RPC_Repair", RPC_Repair);
			m_nview.Register<float>("RPC_HealthChanged", RPC_HealthChanged);
			m_nview.Register("RPC_ClearCachedSupport", RPC_ClearCachedSupport);
			if (m_autoCreateFragments)
			{
				m_nview.Register("RPC_CreateFragments", RPC_CreateFragments);
			}
			if (s_rayMask == 0)
			{
				s_rayMask = LayerMask.GetMask("piece", "Default", "static_solid", "Default_small", "terrain");
			}
			s_allInstances.Add(this);
			m_myIndex = s_allInstances.Count - 1;
			m_createTime = Time.time;
			m_support = GetMaxSupport();
			float num = m_nview.GetZDO().GetFloat(ZDOVars.s_health, m_health);
			if (num.Equals(m_health) && m_randomInitialDamage)
			{
				num = UnityEngine.Random.Range(0.1f * m_health, m_health * 0.6f);
				m_nview.GetZDO().Set(ZDOVars.s_health, num);
			}
			if (Game.m_worldLevel > 0)
			{
				m_health += (float)Game.m_worldLevel * Game.instance.m_worldLevelPieceHPMultiplier * m_health;
			}
			m_updateCoverTimer = UnityEngine.Random.Range(0f, 4f);
			m_healthPercentage = Mathf.Clamp01(num / m_health);
			m_propertyBlock = new MaterialPropertyBlock();
			m_renderers = GetHighlightRenderers();
			SetAshlandsMaterialValue(0f);
			UpdateVisual(triggerEffects: false);
		}
	}

	private void Start()
	{
		m_connectedHeightMap = Heightmap.FindHeightmap(base.transform.position);
		if (m_connectedHeightMap != null)
		{
			m_connectedHeightMap.m_clearConnectedWearNTearCache += ClearCachedSupport;
		}
	}

	public void UpdateAshlandsMaterialValues(float time)
	{
		SetAshlandsMaterialValue(Mathf.Max(m_lavaTimer, Mathf.Max(m_ashDamageTime, m_burnDamageTime)));
		float num = time - m_lastMaterialValueTimeCheck;
		m_lastMaterialValueTimeCheck = time;
		if (m_ashDamageTime > 0f)
		{
			m_ashDamageTime -= num;
		}
		if (m_burnDamageTime > 0f)
		{
			m_burnDamageTime -= num;
		}
	}

	private void OnDestroy()
	{
		if (m_myIndex != -1)
		{
			s_allInstances[m_myIndex] = s_allInstances[s_allInstances.Count - 1];
			s_allInstances[m_myIndex].m_myIndex = m_myIndex;
			s_allInstances.RemoveAt(s_allInstances.Count - 1);
		}
		if (m_connectedHeightMap != null)
		{
			m_connectedHeightMap.m_clearConnectedWearNTearCache -= ClearCachedSupport;
		}
	}

	private void SetAshlandsMaterialValue(float v)
	{
		if (m_ashMaterialValue != v)
		{
			m_ashMaterialValue = v;
			MaterialMan.instance.SetValue(base.gameObject, s_AshlandsDamageShaderID, v);
		}
	}

	public bool Repair()
	{
		if (!m_nview.IsValid())
		{
			return false;
		}
		if (m_nview.GetZDO().GetFloat(ZDOVars.s_health, m_health) >= m_health)
		{
			return false;
		}
		if (Time.time - m_lastRepair < 1f)
		{
			return false;
		}
		m_lastRepair = Time.time;
		m_nview.InvokeRPC("RPC_Repair");
		return true;
	}

	private void RPC_Repair(long sender)
	{
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			m_nview.GetZDO().Set(ZDOVars.s_health, m_health);
			m_nview.InvokeRPC(ZNetView.Everybody, "RPC_HealthChanged", m_health);
		}
	}

	private float GetSupport()
	{
		if (!m_nview.IsValid())
		{
			return GetMaxSupport();
		}
		if (!m_nview.HasOwner())
		{
			return GetMaxSupport();
		}
		if (m_nview.IsOwner())
		{
			return m_support;
		}
		return m_nview.GetZDO().GetFloat(ZDOVars.s_support, GetMaxSupport());
	}

	private float GetSupportColorValue()
	{
		float support = GetSupport();
		GetMaterialProperties(out var maxSupport, out var minSupport, out var _, out var _);
		if (support >= maxSupport)
		{
			return -1f;
		}
		support -= minSupport;
		return Mathf.Clamp01(support / (maxSupport * 0.5f - minSupport));
	}

	public void OnPlaced()
	{
		m_createTime = -1f;
		m_clearCachedSupport = true;
	}

	private List<Renderer> GetHighlightRenderers()
	{
		MeshRenderer[] componentsInChildren = GetComponentsInChildren<MeshRenderer>(includeInactive: true);
		SkinnedMeshRenderer[] componentsInChildren2 = GetComponentsInChildren<SkinnedMeshRenderer>(includeInactive: true);
		List<Renderer> list = new List<Renderer>();
		list.AddRange(componentsInChildren);
		list.AddRange(componentsInChildren2);
		return list;
	}

	public void Highlight()
	{
		float supportColorValue = GetSupportColorValue();
		Color color = new Color(0.6f, 0.8f, 1f);
		if (supportColorValue >= 0f)
		{
			color = Color.Lerp(new Color(1f, 0f, 0f), new Color(0f, 1f, 0f), supportColorValue);
			Color.RGBToHSV(color, out var H, out var S, out var V);
			S = Mathf.Lerp(1f, 0.5f, supportColorValue);
			V = Mathf.Lerp(1.2f, 0.9f, supportColorValue);
			color = Color.HSVToRGB(H, S, V);
		}
		MaterialMan.instance.SetValue(base.gameObject, ShaderProps._EmissionColor, color * 0.4f);
		MaterialMan.instance.SetValue(base.gameObject, ShaderProps._Color, color);
		CancelInvoke("ResetHighlight");
		Invoke("ResetHighlight", 0.2f);
	}

	private void ResetHighlight()
	{
		MaterialMan.instance.ResetValue(base.gameObject, ShaderProps._Color);
		MaterialMan.instance.ResetValue(base.gameObject, ShaderProps._EmissionColor);
	}

	private void SetupColliders()
	{
		m_colliders = GetComponentsInChildren<Collider>(includeInactive: true);
		m_bounds = new List<BoundData>();
		Collider[] colliders = m_colliders;
		foreach (Collider collider in colliders)
		{
			if (!collider.isTrigger && !(collider.attachedRigidbody != null))
			{
				BoundData item = default(BoundData);
				if (collider is BoxCollider)
				{
					BoxCollider boxCollider = collider as BoxCollider;
					item.m_rot = boxCollider.transform.rotation;
					item.m_pos = boxCollider.transform.position + boxCollider.transform.TransformVector(boxCollider.center);
					item.m_size = new Vector3(boxCollider.transform.lossyScale.x * boxCollider.size.x, boxCollider.transform.lossyScale.y * boxCollider.size.y, boxCollider.transform.lossyScale.z * boxCollider.size.z);
				}
				else
				{
					item.m_rot = Quaternion.identity;
					item.m_pos = collider.bounds.center;
					item.m_size = collider.bounds.size;
				}
				item.m_size.x += 0.3f;
				item.m_size.y += 0.3f;
				item.m_size.z += 0.3f;
				item.m_size *= 0.5f;
				m_bounds.Add(item);
			}
		}
	}

	private bool ShouldUpdate(float time)
	{
		if (!(m_createTime < 0f))
		{
			return time - m_createTime > 30f;
		}
		return true;
	}

	public void UpdateWear(float time)
	{
		if (!m_nview.IsValid())
		{
			return;
		}
		if (m_nview.IsOwner() && ShouldUpdate(time))
		{
			if (ZNetScene.instance.OutsideActiveArea(base.transform.position))
			{
				m_support = GetMaxSupport();
				m_nview.GetZDO().Set(ZDOVars.s_support, m_support);
				return;
			}
			bool flag = ShieldGenerator.IsInsideShieldCached(base.transform.position, ref m_shieldChangeID);
			float num = 0f;
			m_rainWet = !flag && !m_haveRoof && EnvMan.IsWet();
			if ((bool)m_wet)
			{
				m_wet.SetActive(m_rainWet);
			}
			if (m_noRoofWear && !flag && GetHealthPercentage() > 0.5f)
			{
				if (IsWet())
				{
					if (m_rainTimer == 0f)
					{
						m_rainTimer = time;
					}
					else if (time - m_rainTimer > 60f)
					{
						m_rainTimer = time;
						num += 5f;
					}
				}
				else
				{
					m_rainTimer = 0f;
				}
			}
			if (m_noSupportWear)
			{
				UpdateSupport();
				if (!HaveSupport())
				{
					num = 100f;
				}
			}
			bool flag2 = false;
			if (m_biome == Heightmap.Biome.None || !m_heightmap)
			{
				Vector3 p = base.transform.position;
				ZoneSystem.instance.GetGroundData(ref p, out var _, out var _, out var _, out m_heightmap);
				if (m_heightmap != null)
				{
					m_biome = m_heightmap.GetBiome(base.transform.position);
					float num2 = 9999f;
					foreach (Renderer renderer in m_renderers)
					{
						if (!m_nonSolidRenderers.Contains(renderer))
						{
							float y = renderer.bounds.min.y;
							if (y < num2)
							{
								num2 = y;
							}
						}
					}
					m_groundDist = num2 - p.y;
					if (m_staticPosition)
					{
						m_lavaValue = m_heightmap.GetLava(base.transform.position);
					}
				}
			}
			if (m_biome == Heightmap.Biome.AshLands)
			{
				m_inAshlands = true;
				if (Game.instance.m_ashDamage > 0f && !flag && !m_ashDamageImmune)
				{
					flag2 = !m_haveAshRoof && (!m_ashDamageResist || GetHealthPercentage() > 0.1f);
					if (flag2)
					{
						if (m_ashTimer == 0f)
						{
							m_ashTimer = time;
						}
						else if (time - m_ashTimer > 5f)
						{
							m_ashTimer = time;
							num += Game.instance.m_ashDamage;
						}
					}
					else
					{
						m_ashTimer = 0f;
					}
				}
				if (!m_staticPosition)
				{
					m_lavaValue = m_heightmap.GetLava(base.transform.position);
				}
				if (m_lavaValue > 0.2f && m_groundDist < 1.5f && !m_ashDamageImmune)
				{
					if (m_lavaTimer == 0f)
					{
						m_lavaTimer = time;
					}
					else if (time - m_lavaTimer > 2f)
					{
						m_lavaTimer = time;
						float num3 = (flag ? 30f : 70f) * m_lavaValue;
						num += num3 * (m_ashDamageResist ? 0.33f : 1f);
					}
				}
				else
				{
					m_lavaTimer = 0f;
				}
			}
			m_ashDamageTime = (flag2 ? 5 : 0);
			if (num > 0f && !CanBeRemoved())
			{
				num = 0f;
			}
			if (num > 0f)
			{
				float damage = num / 100f * m_health;
				ApplyDamage(damage);
			}
		}
		UpdateVisual(triggerEffects: true);
	}

	private Vector3 GetCOM()
	{
		return base.transform.position + base.transform.rotation * m_comOffset;
	}

	public bool IsWet()
	{
		if (!m_rainWet)
		{
			return IsUnderWater();
		}
		return true;
	}

	private void ClearCachedSupport()
	{
		m_supportColliders.Clear();
		m_supportPositions.Clear();
		m_supportValue.Clear();
	}

	private void RPC_ClearCachedSupport(long sender)
	{
		ClearCachedSupport();
	}

	private void UpdateSupport()
	{
		int count = m_supportColliders.Count;
		if (count > 0)
		{
			int num = 0;
			float num2 = 0f;
			for (int i = 0; i < count; i++)
			{
				Collider collider = m_supportColliders[i];
				if (collider == null)
				{
					break;
				}
				WearNTear componentInParent = collider.GetComponentInParent<WearNTear>();
				if (componentInParent == null || !componentInParent.m_supports)
				{
					break;
				}
				if (collider != null && collider.transform.position == m_supportPositions[i])
				{
					float support = componentInParent.GetSupport();
					if (support > num2)
					{
						num2 = support;
					}
					if (support.Equals(m_supportValue[i]))
					{
						num++;
					}
				}
			}
			if (num == m_supportPositions.Count && num2 > m_support)
			{
				return;
			}
			ClearCachedSupport();
		}
		if (m_colliders == null)
		{
			SetupColliders();
		}
		GetMaterialProperties(out var maxSupport, out var _, out var horizontalLoss, out var verticalLoss);
		s_tempSupportPoints.Clear();
		s_tempSupportPointValues.Clear();
		Vector3 cOM = GetCOM();
		bool flag = false;
		float num3 = 0f;
		foreach (BoundData bound in m_bounds)
		{
			int num4 = Physics.OverlapBoxNonAlloc(bound.m_pos, bound.m_size, s_tempColliders, bound.m_rot, s_rayMask);
			if (m_clearCachedSupport)
			{
				for (int j = 0; j < num4; j++)
				{
					Collider collider2 = s_tempColliders[j];
					if (collider2.attachedRigidbody != null || collider2.isTrigger || m_colliders.Contains(collider2))
					{
						continue;
					}
					WearNTear componentInParent2 = collider2.GetComponentInParent<WearNTear>();
					if (!(componentInParent2 == null))
					{
						if (componentInParent2.m_nview.IsOwner())
						{
							componentInParent2.ClearCachedSupport();
						}
						else if (componentInParent2.m_nview.IsValid())
						{
							componentInParent2.m_nview.InvokeRPC(componentInParent2.m_nview.GetZDO().GetOwner(), "RPC_ClearCachedSupport");
						}
					}
				}
				m_clearCachedSupport = false;
			}
			for (int k = 0; k < num4; k++)
			{
				Collider collider3 = s_tempColliders[k];
				if (collider3.attachedRigidbody != null || collider3.isTrigger || m_colliders.Contains(collider3))
				{
					continue;
				}
				if (collider3.gameObject.layer == s_terrainLayer)
				{
					flag = true;
					continue;
				}
				WearNTear componentInParent3 = collider3.GetComponentInParent<WearNTear>();
				if (componentInParent3 == null)
				{
					m_support = maxSupport;
					ClearCachedSupport();
					m_nview.GetZDO().Set(ZDOVars.s_support, m_support);
					return;
				}
				if (!componentInParent3.m_supports)
				{
					continue;
				}
				float num5 = Vector3.Distance(cOM, componentInParent3.GetCOM()) + 0.1f;
				float num6 = Vector3.Distance(cOM, componentInParent3.transform.position) + 0.1f;
				if (num6 < num5 && !m_forceCorrectCOMCalculation)
				{
					num5 = num6;
				}
				float support2 = componentInParent3.GetSupport();
				num3 = Mathf.Max(num3, support2 - horizontalLoss * num5 * support2);
				Vector3 vector = FindSupportPoint(cOM, componentInParent3, collider3);
				if (vector.y < cOM.y + 0.05f)
				{
					Vector3 normalized = (vector - cOM).normalized;
					if (normalized.y < 0f)
					{
						float t = Mathf.Acos(1f - Mathf.Abs(normalized.y)) / (MathF.PI / 2f);
						float num7 = Mathf.Lerp(horizontalLoss, verticalLoss, t);
						float b = support2 - num7 * num5 * support2;
						num3 = Mathf.Max(num3, b);
					}
					float item = support2 - verticalLoss * num5 * support2;
					s_tempSupportPoints.Add(vector);
					s_tempSupportPointValues.Add(item);
					m_supportColliders.Add(collider3);
					m_supportPositions.Add(collider3.transform.position);
					m_supportValue.Add(componentInParent3.GetSupport());
				}
			}
		}
		if (flag)
		{
			m_support = maxSupport;
			m_nview.GetZDO().Set(ZDOVars.s_support, m_support);
			return;
		}
		if (s_tempSupportPoints.Count > 0)
		{
			int count2 = s_tempSupportPoints.Count;
			for (int l = 0; l < count2 - 1; l++)
			{
				Vector3 vector2 = s_tempSupportPoints[l] - cOM;
				vector2.y = 0f;
				for (int m = l + 1; m < count2; m++)
				{
					float num8 = (s_tempSupportPointValues[l] + s_tempSupportPointValues[m]) * 0.5f;
					if (!(num8 <= num3))
					{
						Vector3 to = s_tempSupportPoints[m] - cOM;
						to.y = 0f;
						if (Vector3.Angle(vector2, to) >= 100f)
						{
							num3 = num8;
						}
					}
				}
			}
		}
		m_support = Mathf.Min(num3, maxSupport);
		m_nview.GetZDO().Set(ZDOVars.s_support, m_support);
		if (!HaveSupport())
		{
			ClearCachedSupport();
		}
	}

	private static Vector3 FindSupportPoint(Vector3 com, WearNTear wnt, Collider otherCollider)
	{
		MeshCollider meshCollider = otherCollider as MeshCollider;
		if (meshCollider != null && !meshCollider.convex)
		{
			if (meshCollider.Raycast(new Ray(com, Vector3.down), out var hitInfo, 10f))
			{
				return hitInfo.point;
			}
			return (com + wnt.GetCOM()) * 0.5f;
		}
		return otherCollider.ClosestPoint(com);
	}

	private bool HaveSupport()
	{
		return m_support >= GetMinSupport();
	}

	private bool IsUnderWater()
	{
		return Floating.IsUnderWater(base.transform.position, ref m_previousWaterVolume);
	}

	public void UpdateCover(float dt)
	{
		m_updateCoverTimer += dt;
		if (!(m_updateCoverTimer <= 4f))
		{
			if (EnvMan.IsWet())
			{
				m_haveRoof = HaveRoof();
			}
			if (m_inAshlands)
			{
				m_haveAshRoof = HaveAshRoof();
			}
			m_updateCoverTimer = 0f;
		}
	}

	private bool HaveRoof()
	{
		if ((bool)m_roof)
		{
			return true;
		}
		return RoofCheck(base.transform.position, out m_roof);
	}

	public static bool RoofCheck(Vector3 position, out GameObject roofObject)
	{
		int num = Physics.SphereCastNonAlloc(position, 0.1f, Vector3.up, s_raycastHits, 100f, s_rayMask);
		for (int i = 0; i < num; i++)
		{
			RaycastHit raycastHit = s_raycastHits[i];
			if (!raycastHit.collider.gameObject.CompareTag("leaky"))
			{
				roofObject = raycastHit.collider.gameObject;
				return true;
			}
		}
		roofObject = null;
		return false;
	}

	private bool HaveAshRoof()
	{
		if ((bool)m_ashroof)
		{
			return true;
		}
		int num = Physics.SphereCastNonAlloc(base.transform.position, 0.1f, Vector3.up, s_raycastHits, 100f, s_rayMask);
		for (int i = 0; i < num; i++)
		{
			RaycastHit raycastHit = s_raycastHits[i];
			if (raycastHit.collider.gameObject != base.gameObject && (raycastHit.collider.transform.parent == null || raycastHit.collider.transform.parent.gameObject != base.gameObject))
			{
				m_ashroof = raycastHit.collider.gameObject;
				return true;
			}
		}
		return false;
	}

	private void RPC_HealthChanged(long peer, float health)
	{
		float health2 = health / m_health;
		m_healthPercentage = Mathf.Clamp01(health / m_health);
		ClearCachedSupport();
		SetHealthVisual(health2, triggerEffects: true);
	}

	private void UpdateVisual(bool triggerEffects)
	{
		if (m_nview.IsValid())
		{
			SetHealthVisual(GetHealthPercentage(), triggerEffects);
		}
	}

	private void SetHealthVisual(float health, bool triggerEffects)
	{
		if (m_worn == null && m_broken == null && m_new == null)
		{
			return;
		}
		if (health > 0.75f)
		{
			if (m_worn != m_new)
			{
				m_worn.SetActive(value: false);
			}
			if (m_broken != m_new)
			{
				m_broken.SetActive(value: false);
			}
			m_new.SetActive(value: true);
		}
		else if (health > 0.25f)
		{
			if (triggerEffects && !m_worn.activeSelf)
			{
				m_switchEffect.Create(base.transform.position, base.transform.rotation, base.transform);
			}
			if (m_new != m_worn)
			{
				m_new.SetActive(value: false);
			}
			if (m_broken != m_worn)
			{
				m_broken.SetActive(value: false);
			}
			m_worn.SetActive(value: true);
		}
		else
		{
			if (triggerEffects && !m_broken.activeSelf)
			{
				m_switchEffect.Create(base.transform.position, base.transform.rotation, base.transform);
			}
			if (m_new != m_broken)
			{
				m_new.SetActive(value: false);
			}
			if (m_worn != m_broken)
			{
				m_worn.SetActive(value: false);
			}
			m_broken.SetActive(value: true);
		}
	}

	public float GetHealthPercentage()
	{
		if (!m_nview.IsValid())
		{
			return 1f;
		}
		return m_healthPercentage;
	}

	public DestructibleType GetDestructibleType()
	{
		return DestructibleType.Default;
	}

	public void Damage(HitData hit)
	{
		if (m_nview.IsValid())
		{
			m_nview.InvokeRPC("RPC_Damage", hit);
		}
	}

	private bool CanBeRemoved()
	{
		if ((bool)m_piece)
		{
			return m_piece.CanBeRemoved();
		}
		return true;
	}

	private void RPC_Damage(long sender, HitData hit)
	{
		if (!m_nview.IsValid() || !m_nview.IsOwner() || m_nview.GetZDO().GetFloat(ZDOVars.s_health, m_health) <= 0f)
		{
			return;
		}
		hit.ApplyResistance(m_damages, out var significantModifier);
		float totalDamage = hit.GetTotalDamage();
		DamageText.instance.ShowText(significantModifier, hit.m_point, totalDamage);
		if (totalDamage <= 0f)
		{
			return;
		}
		if (m_triggerPrivateArea)
		{
			Character attacker = hit.GetAttacker();
			if ((bool)attacker)
			{
				bool destroyed = totalDamage >= m_nview.GetZDO().GetFloat(ZDOVars.s_health, m_health);
				PrivateArea.OnObjectDamaged(base.transform.position, attacker, destroyed);
			}
		}
		if (!hit.CheckToolTier(m_minToolTier, alwaysAllowTierZero: true))
		{
			DamageText.instance.ShowText(DamageText.TextType.TooHard, hit.m_point, 0f);
			return;
		}
		ApplyDamage(totalDamage, hit);
		if (hit.m_hitType != HitData.HitType.CinderFire && hit.m_hitType != HitData.HitType.AshlandsOcean)
		{
			m_hitEffect.Create(hit.m_point, Quaternion.identity, base.transform);
			if (hit.GetTotalPhysicalDamage() > 0f)
			{
				m_hitEffect.Create(hit.m_point, Quaternion.identity, base.transform);
			}
		}
		if (m_hitNoise > 0f && hit.m_hitType != HitData.HitType.CinderFire)
		{
			Player closestPlayer = Player.GetClosestPlayer(hit.m_point, 10f);
			if ((bool)closestPlayer)
			{
				closestPlayer.AddNoise(m_hitNoise);
			}
		}
		if (m_onDamaged != null)
		{
			m_onDamaged();
		}
		if (hit.m_damage.m_fire > 3f && !IsWet())
		{
			m_burnDamageTime = 3f;
		}
	}

	public bool ApplyDamage(float damage, HitData hitData = null)
	{
		float num = m_nview.GetZDO().GetFloat(ZDOVars.s_health, m_health);
		if (num <= 0f)
		{
			return false;
		}
		num -= damage;
		m_nview.GetZDO().Set(ZDOVars.s_health, num);
		if (Terminal.m_showTests && Terminal.m_testList.ContainsKey("damage"))
		{
			Terminal.Log(string.Format("Damage WNT: {0} took {1} damage from {2}", base.gameObject.name, damage, (hitData == null) ? ((object)"UNKNOWN") : ((object)hitData)));
		}
		if (num <= 0f)
		{
			Destroy(hitData);
		}
		else
		{
			m_nview.InvokeRPC(ZNetView.Everybody, "RPC_HealthChanged", num);
		}
		return true;
	}

	public void Remove(bool blockDrop = false)
	{
		if (m_nview.IsValid())
		{
			m_nview.InvokeRPC("RPC_Remove", blockDrop);
		}
	}

	private void RPC_Remove(long sender, bool blockDrop)
	{
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			Destroy(null, blockDrop);
		}
	}

	private void Destroy(HitData hitData = null, bool blockDrop = false)
	{
		Bed component = GetComponent<Bed>();
		if (component != null && m_nview.IsOwner() && Game.instance != null)
		{
			Game.instance.RemoveCustomSpawnPoint(component.GetSpawnPoint());
		}
		m_nview.GetZDO().Set(ZDOVars.s_health, 0f);
		m_nview.GetZDO().Set(ZDOVars.s_support, 0f);
		m_support = 0f;
		m_health = 0f;
		ClearCachedSupport();
		if ((bool)m_piece && !blockDrop)
		{
			m_piece.DropResources(hitData);
		}
		if (m_onDestroyed != null)
		{
			m_onDestroyed();
		}
		if (m_destroyNoise > 0f && (hitData == null || hitData.m_hitType != HitData.HitType.CinderFire))
		{
			Player closestPlayer = Player.GetClosestPlayer(base.transform.position, 10f);
			if ((bool)closestPlayer)
			{
				closestPlayer.AddNoise(m_destroyNoise);
			}
		}
		m_destroyedEffect.Create(base.transform.position, base.transform.rotation, base.transform);
		if (m_autoCreateFragments)
		{
			m_nview.InvokeRPC(ZNetView.Everybody, "RPC_CreateFragments");
		}
		ZNetScene.instance.Destroy(base.gameObject);
	}

	private void RPC_CreateFragments(long peer)
	{
		ResetHighlight();
		if (m_fragmentRoots != null && m_fragmentRoots.Length != 0)
		{
			GameObject[] fragmentRoots = m_fragmentRoots;
			foreach (GameObject obj in fragmentRoots)
			{
				obj.SetActive(value: true);
				Destructible.CreateFragments(obj, visibleOnly: false);
			}
		}
		else
		{
			Destructible.CreateFragments(base.gameObject);
		}
	}

	private float GetMaxSupport()
	{
		GetMaterialProperties(out var maxSupport, out var _, out var _, out var _);
		return maxSupport;
	}

	private float GetMinSupport()
	{
		GetMaterialProperties(out var _, out var minSupport, out var _, out var _);
		return minSupport;
	}

	private void GetMaterialProperties(out float maxSupport, out float minSupport, out float horizontalLoss, out float verticalLoss)
	{
		switch (m_materialType)
		{
		case MaterialType.Wood:
			maxSupport = 100f;
			minSupport = 10f;
			verticalLoss = 0.125f;
			horizontalLoss = 0.2f;
			break;
		case MaterialType.HardWood:
			maxSupport = 140f;
			minSupport = 10f;
			verticalLoss = 0.1f;
			horizontalLoss = 1f / 6f;
			break;
		case MaterialType.Stone:
			maxSupport = 1000f;
			minSupport = 100f;
			verticalLoss = 0.125f;
			horizontalLoss = 1f;
			break;
		case MaterialType.Iron:
			maxSupport = 1500f;
			minSupport = 20f;
			verticalLoss = 1f / 13f;
			horizontalLoss = 1f / 13f;
			break;
		case MaterialType.Marble:
			maxSupport = 1500f;
			minSupport = 100f;
			verticalLoss = 0.125f;
			horizontalLoss = 0.5f;
			break;
		case MaterialType.Ashstone:
			maxSupport = 2000f;
			minSupport = 100f;
			verticalLoss = 0.1f;
			horizontalLoss = 1f / 3f;
			break;
		case MaterialType.Ancient:
			maxSupport = 5000f;
			minSupport = 100f;
			verticalLoss = 1f / 15f;
			horizontalLoss = 0.25f;
			break;
		default:
			maxSupport = 0f;
			minSupport = 0f;
			verticalLoss = 0f;
			horizontalLoss = 0f;
			break;
		}
	}

	public static List<WearNTear> GetAllInstances()
	{
		return s_allInstances;
	}
}
using System.Collections.Generic;
using UnityEngine;

public class WearNTearUpdater : MonoBehaviour
{
	private static readonly int s_ashlandsWearTexture = Shader.PropertyToID("_AshlandsWearTexture");

	private int m_index;

	private float m_sleepUntil;

	private float m_sleepUntilNext;

	public Texture3D m_ashlandsWearTexture;

	private int m_updatesPerFrame = 50;

	private const int c_UpdatesPerFrame = 50;

	private const float c_WearNTearTime = 1f;

	private void Start()
	{
		m_sleepUntilNext = (m_sleepUntil = Time.time + 1f);
	}

	private void Update()
	{
		float time = Time.time;
		float deltaTime = Time.deltaTime;
		if (!(time < m_sleepUntil))
		{
			UpdateWearNTear(deltaTime, time);
		}
	}

	private void UpdateWearNTear(float deltaTime, float time)
	{
		List<WearNTear> allInstances = WearNTear.GetAllInstances();
		if (m_sleepUntilNext.Equals(m_sleepUntil))
		{
			m_sleepUntilNext = time + 1f;
			Shader.SetGlobalTexture(s_ashlandsWearTexture, m_ashlandsWearTexture);
			foreach (WearNTear item in allInstances)
			{
				if (item.enabled)
				{
					item.UpdateCover(deltaTime);
				}
			}
			{
				foreach (WearNTear item2 in allInstances)
				{
					item2.UpdateAshlandsMaterialValues(time);
				}
				return;
			}
		}
		int num = m_index;
		for (int i = 0; i < m_updatesPerFrame; i++)
		{
			if (allInstances.Count == 0)
			{
				break;
			}
			if (num >= allInstances.Count)
			{
				break;
			}
			WearNTear wearNTear = allInstances[num];
			if (wearNTear.enabled)
			{
				wearNTear.UpdateWear(time);
			}
			num++;
		}
		m_index = ((num < allInstances.Count) ? num : 0);
		if (m_index != 0)
		{
			return;
		}
		float num2 = m_sleepUntilNext - time;
		if (!(Utils.Abs(num2) < 0.1f))
		{
			if (num2 < -0.8f)
			{
				m_updatesPerFrame += 20;
			}
			else if (num2 < -0.4f)
			{
				m_updatesPerFrame += 15;
			}
			else if (num2 < -0.2f)
			{
				m_updatesPerFrame += 10;
			}
			else if (num2 < 0f)
			{
				m_updatesPerFrame += 5;
			}
			else if (num2 > 0.8f)
			{
				m_updatesPerFrame -= 20;
			}
			else if (num2 > 0.6f)
			{
				m_updatesPerFrame -= 15;
			}
			else if (num2 > 0.3f)
			{
				m_updatesPerFrame -= 10;
			}
			else if (num2 > 0.2f)
			{
				m_updatesPerFrame -= 5;
			}
		}
		m_sleepUntil = m_sleepUntilNext;
		m_updatesPerFrame = Mathf.Max(m_updatesPerFrame, 5);
		m_updatesPerFrame = Mathf.Min(m_updatesPerFrame, 100);
	}
}
using UnityEngine;

public class Windmill : MonoBehaviour
{
	public Transform m_propeller;

	public Transform m_grindstone;

	public Transform m_bom;

	public AudioSource[] m_sfxLoops;

	public GameObject m_propellerAOE;

	public float m_minAOEPropellerSpeed = 5f;

	public float m_bomRotationSpeed = 10f;

	public float m_propellerRotationSpeed = 10f;

	public float m_grindstoneRotationSpeed = 10f;

	public float m_minWindSpeed = 0.1f;

	public float m_minPitch = 1f;

	public float m_maxPitch = 1.5f;

	public float m_maxPitchVel = 10f;

	public float m_maxVol = 1f;

	public float m_maxVolVel = 10f;

	public float m_audioChangeSpeed = 2f;

	private float m_cover;

	private float m_propAngle;

	private float m_grindStoneAngle;

	private Smelter m_smelter;

	private void Start()
	{
		m_smelter = GetComponent<Smelter>();
		InvokeRepeating("CheckCover", 0.1f, 5f);
	}

	private void Update()
	{
		Quaternion to = Quaternion.LookRotation(-EnvMan.instance.GetWindDir());
		float powerOutput = GetPowerOutput();
		m_bom.rotation = Quaternion.RotateTowards(m_bom.rotation, to, m_bomRotationSpeed * powerOutput * Time.deltaTime);
		float num = powerOutput * m_propellerRotationSpeed;
		m_propAngle += num * Time.deltaTime;
		m_propeller.localRotation = Quaternion.Euler(0f, 0f, m_propAngle);
		if (m_smelter == null || m_smelter.IsActive())
		{
			m_grindStoneAngle += powerOutput * m_grindstoneRotationSpeed * Time.deltaTime;
		}
		m_grindstone.localRotation = Quaternion.Euler(0f, m_grindStoneAngle, 0f);
		m_propellerAOE.SetActive(Mathf.Abs(num) > m_minAOEPropellerSpeed);
		UpdateAudio(Time.deltaTime);
	}

	public float GetPowerOutput()
	{
		float num = Utils.LerpStep(m_minWindSpeed, 1f, EnvMan.instance.GetWindIntensity());
		return (1f - m_cover) * num;
	}

	private void CheckCover()
	{
		Cover.GetCoverForPoint(m_propeller.transform.position, out m_cover, out var _);
	}

	private void UpdateAudio(float dt)
	{
		float powerOutput = GetPowerOutput();
		float target = Mathf.Lerp(m_minPitch, m_maxPitch, Mathf.Clamp01(powerOutput / m_maxPitchVel));
		float target2 = m_maxVol * Mathf.Clamp01(powerOutput / m_maxVolVel);
		AudioSource[] sfxLoops = m_sfxLoops;
		foreach (AudioSource obj in sfxLoops)
		{
			obj.volume = Mathf.MoveTowards(obj.volume, target2, m_audioChangeSpeed * dt);
			obj.pitch = Mathf.MoveTowards(obj.pitch, target, m_audioChangeSpeed * dt);
		}
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class WispSpawner : MonoBehaviour, Hoverable
{
	public enum Status
	{
		NoSpace,
		TooBright,
		Full,
		Ok
	}

	public string m_name = "$pieces_wisplure";

	public float m_spawnInterval = 5f;

	[Range(0f, 1f)]
	public float m_spawnChance = 0.5f;

	public int m_maxSpawned = 3;

	public bool m_onlySpawnAtNight = true;

	public bool m_dontSpawnInCover = true;

	[Range(0f, 1f)]
	public float m_maxCover = 0.6f;

	public GameObject m_wispPrefab;

	public GameObject m_wispsNearbyObject;

	public float m_nearbyTreshold = 5f;

	public Transform m_spawnPoint;

	public Transform m_coverPoint;

	public float m_spawnDistance = 20f;

	public float m_maxSpawnedArea = 10f;

	private ZNetView m_nview;

	private Status m_status = Status.Ok;

	private float m_lastStatusUpdate = -1000f;

	private static readonly List<WispSpawner> s_spawners = new List<WispSpawner>();

	private void Start()
	{
		s_spawners.Add(this);
		m_nview = GetComponentInParent<ZNetView>();
		InvokeRepeating("TrySpawn", 10f, 10f);
		InvokeRepeating("UpdateDemister", UnityEngine.Random.Range(0f, 2f), 2f);
	}

	private void OnDestroy()
	{
		s_spawners.Remove(this);
	}

	public string GetHoverText()
	{
		return GetStatus() switch
		{
			Status.NoSpace => Localization.instance.Localize(m_name + " ( $piece_wisplure_nospace )"), 
			Status.Full => Localization.instance.Localize(m_name + " ( $piece_wisplure_full )"), 
			Status.TooBright => Localization.instance.Localize(m_name + " ( $piece_wisplure_light )"), 
			Status.Ok => Localization.instance.Localize(m_name + " ( $piece_wisplure_ok )"), 
			_ => "", 
		};
	}

	public string GetHoverName()
	{
		return m_name;
	}

	private void UpdateDemister()
	{
		if ((bool)m_wispsNearbyObject)
		{
			int wispsInArea = LuredWisp.GetWispsInArea(m_spawnPoint.position, m_nearbyTreshold);
			m_wispsNearbyObject.SetActive(wispsInArea > 0);
		}
	}

	private Status GetStatus()
	{
		if (Time.time - m_lastStatusUpdate < 4f)
		{
			return m_status;
		}
		m_lastStatusUpdate = Time.time;
		m_status = Status.Ok;
		if (!HaveFreeSpace())
		{
			m_status = Status.NoSpace;
		}
		else if (m_onlySpawnAtNight && EnvMan.IsDaylight())
		{
			m_status = Status.TooBright;
		}
		else if (LuredWisp.GetWispsInArea(m_spawnPoint.position, m_maxSpawnedArea) >= m_maxSpawned)
		{
			m_status = Status.Full;
		}
		return m_status;
	}

	private void TrySpawn()
	{
		if (m_nview.IsValid() && m_nview.IsOwner())
		{
			DateTime time = ZNet.instance.GetTime();
			DateTime dateTime = new DateTime(m_nview.GetZDO().GetLong(ZDOVars.s_lastSpawn, 0L));
			if (!((time - dateTime).TotalSeconds < (double)m_spawnInterval) && !(UnityEngine.Random.value > m_spawnChance) && GetStatus() == Status.Ok)
			{
				Vector3 position = m_spawnPoint.position + Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360), 0f) * Vector3.forward * m_spawnDistance;
				UnityEngine.Object.Instantiate(m_wispPrefab, position, Quaternion.identity);
				m_nview.GetZDO().Set(ZDOVars.s_lastSpawn, ZNet.instance.GetTime().Ticks);
			}
		}
	}

	private bool HaveFreeSpace()
	{
		if (m_maxCover <= 0f)
		{
			return true;
		}
		Cover.GetCoverForPoint(m_coverPoint.position, out var coverPercentage, out var _);
		return coverPercentage < m_maxCover;
	}

	private void OnDrawGizmos()
	{
	}

	public static WispSpawner GetBestSpawner(Vector3 p, float maxRange)
	{
		WispSpawner wispSpawner = null;
		float num = 0f;
		foreach (WispSpawner s_spawner in s_spawners)
		{
			float num2 = Vector3.Distance(s_spawner.m_spawnPoint.position, p);
			if (!(num2 > maxRange))
			{
				Status status = s_spawner.GetStatus();
				if (status != Status.NoSpace && status != Status.TooBright && (status != Status.Full || !(num2 > s_spawner.m_maxSpawnedArea)) && (num2 < num || wispSpawner == null))
				{
					num = num2;
					wispSpawner = s_spawner;
				}
			}
		}
		return wispSpawner;
	}
}
using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

public class World
{
	public enum SaveDataError
	{
		None,
		BadVersion,
		LoadError,
		Corrupt,
		MissingMeta,
		MissingDB
	}

	public string m_fileName = "";

	public string m_name = "";

	public string m_seedName = "";

	public int m_seed;

	public long m_uid;

	public List<string> m_startingGlobalKeys = new List<string>();

	public bool m_startingKeysChanged;

	public int m_worldGenVersion;

	public int m_worldVersion;

	public bool m_menu;

	public bool m_needsDB;

	public bool m_createBackupBeforeSaving;

	public SaveWithBackups saves;

	public SaveDataError m_dataError;

	public FileHelpers.FileSource m_fileSource = FileHelpers.FileSource.Local;

	public World()
	{
	}

	public World(SaveWithBackups save, SaveDataError dataError)
	{
		m_fileName = (m_name = save.m_name);
		m_dataError = dataError;
		m_fileSource = save.PrimaryFile.m_source;
	}

	public World(string name, string seed)
	{
		m_fileName = (m_name = name);
		m_seedName = seed;
		m_seed = ((!(m_seedName == "")) ? m_seedName.GetStableHashCode() : 0);
		m_uid = name.GetStableHashCode() + Utils.GenerateUID();
		m_worldGenVersion = 2;
	}

	public static string GetWorldSavePath(FileHelpers.FileSource fileSource = FileHelpers.FileSource.Auto)
	{
		return Utils.GetSaveDataPath(fileSource) + ((fileSource == FileHelpers.FileSource.Local) ? "/worlds_local" : "/worlds");
	}

	public static void RemoveWorld(string name, FileHelpers.FileSource fileSource)
	{
		if (SaveSystem.TryGetSaveByName(name, SaveDataType.World, out var save) && !save.IsDeleted)
		{
			SaveSystem.Delete(save.PrimaryFile);
		}
	}

	public string GetRootPath(FileHelpers.FileSource fileSource)
	{
		return GetWorldSavePath(fileSource) + "/" + m_fileName;
	}

	public string GetDBPath()
	{
		return GetDBPath(m_fileSource);
	}

	public string GetDBPath(FileHelpers.FileSource fileSource)
	{
		return GetWorldSavePath(fileSource) + "/" + m_fileName + ".db";
	}

	public static string GetDBPath(string name, FileHelpers.FileSource fileSource = FileHelpers.FileSource.Auto)
	{
		return GetWorldSavePath(fileSource) + "/" + name + ".db";
	}

	public string GetMetaPath()
	{
		return GetMetaPath(m_fileSource);
	}

	public string GetMetaPath(FileHelpers.FileSource fileSource)
	{
		return GetWorldSavePath(fileSource) + "/" + m_fileName + ".fwl";
	}

	public static string GetMetaPath(string name, FileHelpers.FileSource fileSource = FileHelpers.FileSource.Auto)
	{
		return GetWorldSavePath(fileSource) + "/" + name + ".fwl";
	}

	public static bool HaveWorld(string name)
	{
		if (SaveSystem.TryGetSaveByName(name, SaveDataType.World, out var save))
		{
			return !save.IsDeleted;
		}
		return false;
	}

	public static World GetMenuWorld()
	{
		return new World("menu", "")
		{
			m_menu = true
		};
	}

	public static World GetEditorWorld()
	{
		return new World("editor", "");
	}

	public static string GenerateSeed()
	{
		string text = "";
		for (int i = 0; i < 10; i++)
		{
			text += "abcdefghijklmnpqrstuvwxyzABCDEFGHIJKLMNPQRSTUVWXYZ023456789"[UnityEngine.Random.Range(0, "abcdefghijklmnpqrstuvwxyzABCDEFGHIJKLMNPQRSTUVWXYZ023456789".Length)];
		}
		return text;
	}

	public static World GetCreateWorld(string name, FileHelpers.FileSource source)
	{
		ZLog.Log("Get create world " + name);
		World world;
		if (SaveSystem.TryGetSaveByName(name, SaveDataType.World, out var save) && !save.IsDeleted)
		{
			world = LoadWorld(save);
			if (world.m_dataError == SaveDataError.None)
			{
				return world;
			}
			ZLog.LogError($"Failed to load world with name \"{name}\", data error {world.m_dataError}.");
		}
		ZLog.Log(" creating");
		world = new World(name, GenerateSeed());
		world.m_fileSource = source;
		world.SaveWorldMetaData(DateTime.Now);
		return world;
	}

	public static World GetDevWorld()
	{
		World world;
		if (SaveSystem.TryGetSaveByName(Game.instance.m_devWorldName, SaveDataType.World, out var save) && !save.IsDeleted)
		{
			world = LoadWorld(save);
			if (world.m_dataError == SaveDataError.None)
			{
				return world;
			}
			ZLog.Log($"Failed to load dev world, data error {world.m_dataError}. Creating...");
		}
		world = new World(Game.instance.m_devWorldName, Game.instance.m_devWorldSeed);
		world.m_fileSource = FileHelpers.FileSource.Local;
		world.SaveWorldMetaData(DateTime.Now);
		return world;
	}

	public void SaveWorldMetaData(DateTime backupTimestamp)
	{
		SaveWorldMetaData(backupTimestamp, considerBackup: true, out var _, out var _);
	}

	public void SaveWorldMetaData(DateTime now, bool considerBackup, out bool cloudSaveFailed, out FileWriter metaWriter)
	{
		GetDBPath();
		SaveSystem.CheckMove(m_fileName, SaveDataType.World, ref m_fileSource, now, 0uL);
		ZPackage zPackage = new ZPackage();
		zPackage.Write(37);
		zPackage.Write(m_name);
		zPackage.Write(m_seedName);
		zPackage.Write(m_seed);
		zPackage.Write(m_uid);
		zPackage.Write(m_worldGenVersion);
		zPackage.Write(m_needsDB);
		zPackage.Write(m_startingGlobalKeys.Count);
		for (int i = 0; i < m_startingGlobalKeys.Count; i++)
		{
			zPackage.Write(m_startingGlobalKeys[i]);
		}
		if (m_fileSource != FileHelpers.FileSource.Cloud)
		{
			Directory.CreateDirectory(GetWorldSavePath(m_fileSource));
		}
		string metaPath = GetMetaPath();
		string text = metaPath + ".new";
		string oldFile = metaPath + ".old";
		byte[] array = zPackage.GetArray();
		bool flag = m_fileSource == FileHelpers.FileSource.Cloud;
		FileWriter fileWriter = new FileWriter(flag ? metaPath : text, FileHelpers.FileHelperType.Binary, m_fileSource);
		fileWriter.m_binary.Write(array.Length);
		fileWriter.m_binary.Write(array);
		fileWriter.Finish();
		SaveSystem.InvalidateCache();
		cloudSaveFailed = fileWriter.Status != FileWriter.WriterStatus.CloseSucceeded && m_fileSource == FileHelpers.FileSource.Cloud;
		if (!cloudSaveFailed)
		{
			if (!flag)
			{
				FileHelpers.ReplaceOldFile(metaPath, text, oldFile, m_fileSource);
				SaveSystem.InvalidateCache();
			}
			if (considerBackup)
			{
				ZNet.ConsiderAutoBackup(m_fileName, SaveDataType.World, now);
			}
		}
		metaWriter = fileWriter;
	}

	public static World LoadWorld(SaveWithBackups saveFile)
	{
		FileReader fileReader = null;
		if (saveFile.IsDeleted)
		{
			ZLog.Log("save deleted " + saveFile.m_name);
			return new World(saveFile, SaveDataError.LoadError);
		}
		FileHelpers.FileSource source = saveFile.PrimaryFile.m_source;
		string pathPrimary = saveFile.PrimaryFile.PathPrimary;
		string text = ((saveFile.PrimaryFile.PathsAssociated.Length != 0) ? saveFile.PrimaryFile.PathsAssociated[0] : null);
		if (FileHelpers.IsFileCorrupt(pathPrimary, source) || (text != null && FileHelpers.IsFileCorrupt(text, source)))
		{
			ZLog.Log("  corrupt save " + saveFile.m_name);
			return new World(saveFile, SaveDataError.Corrupt);
		}
		try
		{
			fileReader = new FileReader(pathPrimary, source);
		}
		catch (Exception ex)
		{
			fileReader?.Dispose();
			ZLog.Log("  failed to load " + saveFile.m_name + " Exception: " + ex);
			return new World(saveFile, SaveDataError.LoadError);
		}
		try
		{
			BinaryReader binary = fileReader.m_binary;
			int count = binary.ReadInt32();
			ZPackage zPackage = new ZPackage(binary.ReadBytes(count));
			int num = zPackage.ReadInt();
			if (!Version.IsWorldVersionCompatible(num))
			{
				ZLog.Log("incompatible world version " + num);
				return new World(saveFile, SaveDataError.BadVersion);
			}
			World world = new World();
			world.m_fileSource = source;
			world.m_fileName = saveFile.m_name;
			world.m_name = zPackage.ReadString();
			world.m_seedName = zPackage.ReadString();
			world.m_seed = zPackage.ReadInt();
			world.m_uid = zPackage.ReadLong();
			world.m_worldVersion = num;
			if (num >= 26)
			{
				world.m_worldGenVersion = zPackage.ReadInt();
			}
			world.m_needsDB = num >= 30 && zPackage.ReadBool();
			if (num != 37)
			{
				world.m_createBackupBeforeSaving = true;
			}
			if (world.CheckDbFile())
			{
				world.m_dataError = SaveDataError.MissingDB;
			}
			if (num >= 32)
			{
				int num2 = zPackage.ReadInt();
				for (int i = 0; i < num2; i++)
				{
					world.m_startingGlobalKeys.Add(zPackage.ReadString());
				}
			}
			return world;
		}
		catch
		{
			ZLog.LogWarning("  error loading world " + saveFile.m_name);
			return new World(saveFile, SaveDataError.LoadError);
		}
		finally
		{
			fileReader?.Dispose();
		}
	}

	private bool CheckDbFile()
	{
		if (m_needsDB)
		{
			return !FileHelpers.Exists(GetDBPath(), m_fileSource);
		}
		return false;
	}
}
