	public void Initialize(ZDOID id, Vector3 position)
	{
		m_uid = id;
		m_position = position;
		Vector2i zone = ZoneSystem.GetZone(m_position);
		m_sector = zone.ClampToShort();
		ZDOMan.instance.AddToSector(this, zone);
		m_dataFlags = DataFlags.None;
		Valid = true;
	}

	public void Init()
	{
		m_dataFlags = DataFlags.None;
