	{
		return this == other;
	}

	public void Reset()
	{
		if (!SaveClone)
		{
			ZDOExtraData.Release(this, m_uid);
		}
		m_uid = ZDOID.None;
		m_dataFlags = DataFlags.None;
		OwnerRevision = 0;
		DataRevision = 0u;
		m_tempSortValue = 0f;
		m_prefab = 0;
		m_sector = Vector2s.zero;
		m_position = Vector3.zero;
		m_rotation = Quaternion.identity.eulerAngles;
	}

