using System;
using System.Collections.Generic;
using UnityEngine;

public class ZNetScene : MonoBehaviour
{
	private static ZNetScene s_instance;

	private const int m_maxCreatedPerFrame = 10;

	private const float m_createDestroyFps = 30f;

	public List<GameObject> m_prefabs = new List<GameObject>();

	public List<GameObject> m_nonNetViewPrefabs = new List<GameObject>();

	private readonly Dictionary<int, GameObject> m_namedPrefabs = new Dictionary<int, GameObject>();

	private readonly Dictionary<ZDO, ZNetView> m_instances = new Dictionary<ZDO, ZNetView>();

	private readonly List<ZDO> m_tempCurrentObjects = new List<ZDO>();

	private readonly List<ZDO> m_tempCurrentObjects2 = new List<ZDO>();

	private readonly List<ZDO> m_tempCurrentDistantObjects = new List<ZDO>();

	private readonly List<ZNetView> m_tempRemoved = new List<ZNetView>();

	private float m_createDestroyTimer;

	public static ZNetScene instance => s_instance;

	private void Awake()
	{
		s_instance = this;
		foreach (GameObject prefab in m_prefabs)
		{
			m_namedPrefabs.Add(prefab.name.GetStableHashCode(), prefab);
		}
		foreach (GameObject nonNetViewPrefab in m_nonNetViewPrefabs)
		{
			m_namedPrefabs.Add(nonNetViewPrefab.name.GetStableHashCode(), nonNetViewPrefab);
		}
		ZDOMan zDOMan = ZDOMan.instance;
		zDOMan.m_onZDODestroyed = (Action<ZDO>)Delegate.Combine(zDOMan.m_onZDODestroyed, new Action<ZDO>(OnZDODestroyed));
		ZRoutedRpc.instance.Register<Vector3, Quaternion, int>("SpawnObject", RPC_SpawnObject);
	}

	private void OnDestroy()
	{
		ZLog.Log("Net scene destroyed");
		if (s_instance == this)
		{
			s_instance = null;
		}
	}

	public void Shutdown()
	{
		foreach (KeyValuePair<ZDO, ZNetView> instance in m_instances)
		{
			if ((bool)instance.Value)
			{
				instance.Value.ResetZDO();
				UnityEngine.Object.Destroy(instance.Value.gameObject);
			}
		}
		m_instances.Clear();
		base.enabled = false;
	}

	public void AddInstance(ZDO zdo, ZNetView nview)
	{
		zdo.Created = true;
		m_instances[zdo] = nview;
	}

	private bool IsPrefabZDOValid(ZDO zdo)
	{
		int prefab = zdo.GetPrefab();
		if (prefab == 0)
		{
			return false;
		}
		return GetPrefab(prefab) != null;
	}

	private GameObject CreateObject(ZDO zdo)
	{
		int prefab = zdo.GetPrefab();
		if (prefab == 0)
		{
			return null;
		}
		GameObject prefab2 = GetPrefab(prefab);
		if (prefab2 == null)
		{
			return null;
		}
		Vector3 position = zdo.GetPosition();
		Quaternion rotation = zdo.GetRotation();
		ZNetView.m_useInitZDO = true;
		ZNetView.m_initZDO = zdo;
		GameObject result = UnityEngine.Object.Instantiate(prefab2, position, rotation);
		if (ZNetView.m_initZDO != null)
		{
			ZDOID uid = zdo.m_uid;
			ZLog.LogWarning("ZDO " + uid.ToString() + " not used when creating object " + prefab2.name);
			ZNetView.m_initZDO = null;
		}
		ZNetView.m_useInitZDO = false;
		return result;
	}

	public void Destroy(GameObject go)
	{
		ZNetView component = go.GetComponent<ZNetView>();
		if ((bool)component && component.GetZDO() != null)
		{
			ZDO zDO = component.GetZDO();
			component.ResetZDO();
			m_instances.Remove(zDO);
			if (zDO.IsOwner())
			{
				ZDOMan.instance.DestroyZDO(zDO);
			}
		}
		UnityEngine.Object.Destroy(go);
	}

	public bool HasPrefab(int hash)
	{
		return m_namedPrefabs.ContainsKey(hash);
	}

	public GameObject GetPrefab(int hash)
	{
		if (m_namedPrefabs.TryGetValue(hash, out var value))
		{
			return value;
		}
		return null;
	}

	public GameObject GetPrefab(string name)
	{
		return GetPrefab(name.GetStableHashCode());
	}

	public int GetPrefabHash(GameObject go)
	{
		return go.name.GetStableHashCode();
	}

	public bool IsAreaReady(Vector3 point)
	{
		Vector2i zone = ZoneSystem.GetZone(point);
		if (!ZoneSystem.instance.IsZoneLoaded(zone))
		{
			return false;
		}
		m_tempCurrentObjects.Clear();
		ZDOMan.instance.FindSectorObjects(zone, 1, 0, m_tempCurrentObjects);
		foreach (ZDO tempCurrentObject in m_tempCurrentObjects)
		{
			if (IsPrefabZDOValid(tempCurrentObject) && !FindInstance(tempCurrentObject))
			{
				return false;
			}
		}
		return true;
	}

	private bool InLoadingScreen()
	{
		if (!(Player.m_localPlayer == null))
		{
			return Player.m_localPlayer.IsTeleporting();
		}
		return true;
	}

	private void CreateObjects(List<ZDO> currentNearObjects, List<ZDO> currentDistantObjects)
	{
		int maxCreatedPerFrame = 10;
		if (InLoadingScreen())
		{
			maxCreatedPerFrame = 100;
		}
		int created = 0;
		CreateObjectsSorted(currentNearObjects, maxCreatedPerFrame, ref created);
		CreateDistantObjects(currentDistantObjects, maxCreatedPerFrame, ref created);
	}

	private void CreateObjectsSorted(List<ZDO> currentNearObjects, int maxCreatedPerFrame, ref int created)
	{
		if (!ZoneSystem.instance.IsActiveAreaLoaded())
		{
			return;
		}
		m_tempCurrentObjects2.Clear();
		Vector3 referencePosition = ZNet.instance.GetReferencePosition();
		foreach (ZDO currentNearObject in currentNearObjects)
		{
			if (!currentNearObject.Created)
			{
				currentNearObject.m_tempSortValue = Utils.DistanceSqr(referencePosition, currentNearObject.GetPosition());
				m_tempCurrentObjects2.Add(currentNearObject);
			}
		}
		int num = Mathf.Max(m_tempCurrentObjects2.Count / 100, maxCreatedPerFrame);
		m_tempCurrentObjects2.Sort(ZDOCompare);
		foreach (ZDO item in m_tempCurrentObjects2)
		{
			if (!ZoneSystem.instance.IsZoneReadyForType(item.GetSector(), item.Type))
			{
				continue;
			}
			if (CreateObject(item) != null)
			{
				created++;
				if (created > num)
				{
					break;
				}
			}
			else if (ZNet.instance.IsServer())
			{
				item.SetOwner(ZDOMan.GetSessionID());
				ZDOID uid = item.m_uid;
				ZLog.Log("Destroyed invalid predab ZDO:" + uid.ToString());
				ZDOMan.instance.DestroyZDO(item);
			}
		}
	}

	private static int ZDOCompare(ZDO x, ZDO y)
	{
		if (x.Type == y.Type)
		{
			return Utils.CompareFloats(x.m_tempSortValue, y.m_tempSortValue);
		}
		return ((int)y.Type).CompareTo((int)x.Type);
	}

	private void CreateDistantObjects(List<ZDO> objects, int maxCreatedPerFrame, ref int created)
	{
		if (created > maxCreatedPerFrame)
		{
			return;
		}
		foreach (ZDO @object in objects)
		{
			if (@object.Created)
			{
				continue;
			}
			if (CreateObject(@object) != null)
			{
				created++;
				if (created > maxCreatedPerFrame)
				{
					break;
				}
			}
			else if (ZNet.instance.IsServer())
			{
				@object.SetOwner(ZDOMan.GetSessionID());
				ZDOID uid = @object.m_uid;
				ZLog.Log("Destroyed invalid predab ZDO:" + uid.ToString() + "  prefab hash:" + @object.GetPrefab());
				ZDOMan.instance.DestroyZDO(@object);
			}
		}
	}

	private void OnZDODestroyed(ZDO zdo)
	{
		if (m_instances.TryGetValue(zdo, out var value))
		{
			value.ResetZDO();
			UnityEngine.Object.Destroy(value.gameObject);
			m_instances.Remove(zdo);
		}
	}

	private void RemoveObjects(List<ZDO> currentNearObjects, List<ZDO> currentDistantObjects)
	{
		byte b = (byte)(Time.frameCount & 0xFF);
		foreach (ZDO currentNearObject in currentNearObjects)
		{
			currentNearObject.TempRemoveEarmark = b;
		}
		foreach (ZDO currentDistantObject in currentDistantObjects)
		{
			currentDistantObject.TempRemoveEarmark = b;
		}
		m_tempRemoved.Clear();
		foreach (ZNetView value in m_instances.Values)
		{
			if (value.GetZDO().TempRemoveEarmark != b)
			{
				m_tempRemoved.Add(value);
			}
		}
		for (int i = 0; i < m_tempRemoved.Count; i++)
		{
			ZNetView zNetView = m_tempRemoved[i];
			ZDO zDO = zNetView.GetZDO();
			zNetView.ResetZDO();
			UnityEngine.Object.Destroy(zNetView.gameObject);
			if (!zDO.Persistent && zDO.IsOwner())
			{
				ZDOMan.instance.DestroyZDO(zDO);
			}
			m_instances.Remove(zDO);
		}
	}

	public ZNetView FindInstance(ZDO zdo)
	{
		if (m_instances.TryGetValue(zdo, out var value))
		{
			return value;
		}
		return null;
	}

	public bool HaveInstance(ZDO zdo)
	{
		return m_instances.ContainsKey(zdo);
	}

	public GameObject FindInstance(ZDOID id)
	{
		ZDO zDO = ZDOMan.instance.GetZDO(id);
		if (zDO != null)
		{
			ZNetView zNetView = FindInstance(zDO);
			if ((bool)zNetView)
			{
				return zNetView.gameObject;
			}
		}
		return null;
	}

	private void Update()
	{
		float deltaTime = Time.deltaTime;
		m_createDestroyTimer += deltaTime;
		if (m_createDestroyTimer >= 1f / 30f)
		{
			m_createDestroyTimer = 0f;
			CreateDestroyObjects();
		}
	}

	private void CreateDestroyObjects()
	{
		Vector2i zone = ZoneSystem.GetZone(ZNet.instance.GetReferencePosition());
		m_tempCurrentObjects.Clear();
		m_tempCurrentDistantObjects.Clear();
		ZDOMan.instance.FindSectorObjects(zone, ZoneSystem.instance.m_activeArea, ZoneSystem.instance.m_activeDistantArea, m_tempCurrentObjects, m_tempCurrentDistantObjects);
		CreateObjects(m_tempCurrentObjects, m_tempCurrentDistantObjects);
		RemoveObjects(m_tempCurrentObjects, m_tempCurrentDistantObjects);
	}

	public static bool InActiveArea(Vector2i zone, Vector3 refPoint)
	{
		Vector2i zone2 = ZoneSystem.GetZone(refPoint);
		return InActiveArea(zone, zone2);
	}

	public static bool InActiveArea(Vector2i zone, Vector2i refCenterZone)
	{
		int num = ZoneSystem.instance.m_activeArea - 1;
		if (zone.x >= refCenterZone.x - num && zone.x <= refCenterZone.x + num && zone.y <= refCenterZone.y + num)
		{
			return zone.y >= refCenterZone.y - num;
		}
		return false;
	}

	public static bool InActiveArea(Vector2i zone, Vector2i refCenterZone, int activatedArea)
	{
		if (zone.x >= refCenterZone.x - activatedArea && zone.x <= refCenterZone.x + activatedArea && zone.y <= refCenterZone.y + activatedArea)
		{
			return zone.y >= refCenterZone.y - activatedArea;
		}
		return false;
	}

	public bool OutsideActiveArea(Vector3 point)
	{
		return OutsideActiveArea(point, ZNet.instance.GetReferencePosition());
	}

	private static bool OutsideActiveArea(Vector3 point, Vector3 refPoint)
	{
		Vector2i zone = ZoneSystem.GetZone(refPoint);
		Vector2i zone2 = ZoneSystem.GetZone(point);
		if (zone2.x > zone.x - ZoneSystem.instance.m_activeArea && zone2.x < zone.x + ZoneSystem.instance.m_activeArea && zone2.y < zone.y + ZoneSystem.instance.m_activeArea)
		{
			return zone2.y <= zone.y - ZoneSystem.instance.m_activeArea;
		}
		return true;
	}

	public static bool OutsideActiveArea(Vector3 point, Vector2i centerZone, int activeArea)
	{
		Vector2i zone = ZoneSystem.GetZone(point);
		if (zone.x > centerZone.x - activeArea && zone.x < centerZone.x + activeArea && zone.y < centerZone.y + activeArea)
		{
			return zone.y <= centerZone.y - activeArea;
		}
		return true;
	}

	public bool HaveInstanceInSector(Vector2i sector)
	{
		foreach (KeyValuePair<ZDO, ZNetView> instance in m_instances)
		{
			if ((bool)instance.Value && !instance.Value.m_distant && ZoneSystem.GetZone(instance.Value.transform.position) == sector)
			{
				return true;
			}
		}
		return false;
	}

	public int NrOfInstances()
	{
		return m_instances.Count;
	}

	public void SpawnObject(Vector3 pos, Quaternion rot, GameObject prefab)
	{
		int prefabHash = GetPrefabHash(prefab);
		ZRoutedRpc.instance.InvokeRoutedRPC(ZRoutedRpc.Everybody, "SpawnObject", pos, rot, prefabHash);
	}

	public List<string> GetPrefabNames()
	{
		List<string> list = new List<string>();
		foreach (KeyValuePair<int, GameObject> namedPrefab in m_namedPrefabs)
		{
			list.Add(namedPrefab.Value.name);
		}
		return list;
	}

	private void RPC_SpawnObject(long spawner, Vector3 pos, Quaternion rot, int prefabHash)
	{
		GameObject prefab = GetPrefab(prefabHash);
		if (prefab == null)
		{
			ZLog.Log("Missing prefab " + prefabHash);
		}
		else
		{
			UnityEngine.Object.Instantiate(prefab, pos, rot);
		}
	}
}
using UnityEngine;

public class ZNetStats
{
	private int m_recvBytes;

	private int m_statRecvBytes;

	private int m_sentBytes;

	private int m_statSentBytes;

	private float m_recvRate;

	private float m_sendRate;

	private float m_statStart = Time.time;

	internal void IncRecvBytes(int count)
	{
		m_recvBytes += count;
	}

	internal void IncSentBytes(int count)
	{
		m_sentBytes += count;
	}

	public void GetAndResetStats(out int totalSent, out int totalRecv)
	{
		totalSent = m_sentBytes;
		totalRecv = m_recvBytes;
		m_sentBytes = 0;
		m_statSentBytes = 0;
		m_recvBytes = 0;
		m_statRecvBytes = 0;
		m_statStart = Time.time;
	}

	public void GetConnectionQuality(out float localQuality, out float remoteQuality, out int ping, out float outByteSec, out float inByteSec)
	{
		float num = Time.time - m_statStart;
		if (num >= 1f)
		{
			m_sendRate = ((float)(m_sentBytes - m_statSentBytes) / num * 2f + m_sendRate) / 3f;
			m_recvRate = ((float)(m_recvBytes - m_statRecvBytes) / num * 2f + m_recvRate) / 3f;
			m_statSentBytes = m_sentBytes;
			m_statRecvBytes = m_recvBytes;
			m_statStart = Time.time;
		}
		localQuality = 0f;
		remoteQuality = 0f;
		ping = 0;
		outByteSec = m_sendRate;
		inByteSec = m_recvRate;
	}
}
using System;
using System.Collections.Generic;
using System.Reflection;
using SoftReferenceableAssets;
using UnityEngine;

public class ZNetView : MonoBehaviour, IReferenceHolder
{
	public const string CustomFieldsStr = "HasFields";

	public static long Everybody = 0L;

	public bool m_persistent;

	public bool m_distant;

	public ZDO.ObjectType m_type;

	public bool m_syncInitialScale;

	public static bool m_useInitZDO = false;

	public static ZDO m_initZDO = null;

	public static bool m_forceDisableInit = false;

	private ZDO m_zdo;

	private Rigidbody m_body;

	private Dictionary<int, RoutedMethodBase> m_functions = new Dictionary<int, RoutedMethodBase>();

	private bool m_ghost;

	private static List<MonoBehaviour> m_tempComponents = new List<MonoBehaviour>();

	private static bool m_ghostInit = false;

	private List<IReferenceCounted> m_heldReferences;

	private void Awake()
	{
		if (m_forceDisableInit || ZDOMan.instance == null)
		{
			UnityEngine.Object.Destroy(this);
			return;
		}
		m_body = GetComponent<Rigidbody>();
		if (m_useInitZDO && m_initZDO == null)
		{
			ZLog.LogWarning("Double ZNetview when initializing object " + base.gameObject.name);
		}
		if (m_initZDO != null)
		{
			m_zdo = m_initZDO;
			m_initZDO = null;
			if (m_zdo.Type != m_type && m_zdo.IsOwner())
			{
				m_zdo.SetType(m_type);
			}
			if (m_zdo.Distant != m_distant && m_zdo.IsOwner())
			{
				m_zdo.SetDistant(m_distant);
			}
			if (m_syncInitialScale)
			{
				Vector3 vec = m_zdo.GetVec3(ZDOVars.s_scaleHash, Vector3.zero);
				if (vec != Vector3.zero)
				{
					base.transform.localScale = vec;
				}
				else
				{
					float num = m_zdo.GetFloat(ZDOVars.s_scaleScalarHash, base.transform.localScale.x);
					if (!base.transform.localScale.x.Equals(num))
					{
						base.transform.localScale = new Vector3(num, num, num);
					}
				}
			}
			if ((bool)m_body)
			{
				m_body.Sleep();
			}
		}
		else
		{
			string prefabName = GetPrefabName();
			m_zdo = ZDOMan.instance.CreateNewZDO(base.transform.position, prefabName.GetStableHashCode());
			m_zdo.Persistent = m_persistent;
			m_zdo.Type = m_type;
			m_zdo.Distant = m_distant;
			m_zdo.SetPrefab(prefabName.GetStableHashCode());
			m_zdo.SetRotation(base.transform.rotation);
			if (m_syncInitialScale)
			{
				SyncScale(skipOne: true);
			}
			if (m_ghostInit)
			{
				m_ghost = true;
				return;
			}
		}
		LoadFields();
		ZNetScene.instance.AddInstance(m_zdo, this);
	}

	public void SetLocalScale(Vector3 scale)
	{
		if (!(base.transform.localScale == scale))
		{
			base.transform.localScale = scale;
			if (m_zdo != null && m_syncInitialScale && IsOwner())
			{
				SyncScale();
			}
		}
	}

	private void SyncScale(bool skipOne = false)
	{
		if (Mathf.Approximately(base.transform.localScale.x, base.transform.localScale.y) && Mathf.Approximately(base.transform.localScale.x, base.transform.localScale.z))
		{
			if (!skipOne || !Mathf.Approximately(base.transform.localScale.x, 1f))
			{
				m_zdo.Set(ZDOVars.s_scaleScalarHash, base.transform.localScale.x);
			}
		}
		else
		{
			m_zdo.Set(ZDOVars.s_scaleHash, base.transform.localScale);
		}
	}

	private void OnDestroy()
	{
		_ = (bool)ZNetScene.instance;
		if (m_heldReferences != null)
		{
			for (int i = 0; i < m_heldReferences.Count; i++)
			{
				m_heldReferences[i].Release();
			}
			m_heldReferences.Clear();
		}
	}

	public void LoadFields()
	{
		ZDO zDO = GetZDO();
		if (!zDO.GetBool("HasFields"))
		{
			return;
		}
		base.gameObject.GetComponentsInChildren(m_tempComponents);
		foreach (MonoBehaviour tempComponent in m_tempComponents)
		{
			string text = tempComponent.GetType().Name;
			("HasFields" + text).GetStableHashCode();
			if (!zDO.GetBool("HasFields" + text))
			{
				continue;
			}
			FieldInfo[] fields = tempComponent.GetType().GetFields(BindingFlags.Instance | BindingFlags.Public);
			foreach (FieldInfo fieldInfo in fields)
			{
				text = tempComponent.GetType().Name + "." + fieldInfo.Name;
				float value2;
				bool value3;
				Vector3 value4;
				string value5;
				string value6;
				if (fieldInfo.FieldType == typeof(int) && zDO.GetInt(text, out var value))
				{
					fieldInfo.SetValue(tempComponent, value);
				}
				else if (fieldInfo.FieldType == typeof(float) && zDO.GetFloat(text, out value2))
				{
					fieldInfo.SetValue(tempComponent, value2);
				}
				else if (fieldInfo.FieldType == typeof(bool) && zDO.GetBool(text, out value3))
				{
					fieldInfo.SetValue(tempComponent, value3);
				}
				else if (fieldInfo.FieldType == typeof(Vector3) && zDO.GetVec3(text, out value4))
				{
					fieldInfo.SetValue(tempComponent, value4);
				}
				else if (fieldInfo.FieldType == typeof(string) && zDO.GetString(text, out value5))
				{
					fieldInfo.SetValue(tempComponent, value5);
				}
				else if (fieldInfo.FieldType == typeof(GameObject) && zDO.GetString(text, out value6))
				{
					GameObject prefab = ZNetScene.instance.GetPrefab(value6);
					if ((object)prefab != null)
					{
						fieldInfo.SetValue(tempComponent, prefab);
					}
				}
				else
				{
					if (!(fieldInfo.FieldType == typeof(ItemDrop)) || !zDO.GetString(text, out var value7))
					{
						continue;
					}
					GameObject prefab2 = ZNetScene.instance.GetPrefab(value7);
					if ((object)prefab2 != null)
					{
						ItemDrop component = prefab2.GetComponent<ItemDrop>();
						if ((object)component != null)
						{
							fieldInfo.SetValue(tempComponent, component);
						}
					}
				}
			}
		}
	}

	private string GetPrefabName()
	{
		return Utils.GetPrefabName(base.gameObject);
	}

	public void Destroy()
	{
		ZNetScene.instance.Destroy(base.gameObject);
	}

	public bool IsOwner()
	{
		if (!IsValid())
		{
			return false;
		}
		return m_zdo.IsOwner();
	}

	public bool HasOwner()
	{
		if (!IsValid())
		{
			return false;
		}
		return m_zdo.HasOwner();
	}

	public void ClaimOwnership()
	{
		if (!IsOwner())
		{
			m_zdo.SetOwner(ZDOMan.GetSessionID());
		}
	}

	public ZDO GetZDO()
	{
		return m_zdo;
	}

	public bool IsValid()
	{
		if (m_zdo != null)
		{
			return m_zdo.IsValid();
		}
		return false;
	}

	public void ResetZDO()
	{
		m_zdo.Created = false;
		m_zdo = null;
	}

	public void Register(string name, Action<long> f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod(f));
	}

	public void Register<T>(string name, Action<long, T> f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T>(f));
	}

	public void Register<T, U>(string name, Action<long, T, U> f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T, U>(f));
	}

	public void Register<T, U, V>(string name, Action<long, T, U, V> f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T, U, V>(f));
	}

	public void Register<T, U, V, B>(string name, RoutedMethod<T, U, V, B>.Method f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T, U, V, B>(f));
	}

	public void Unregister(string name)
	{
		int stableHashCode = name.GetStableHashCode();
		m_functions.Remove(stableHashCode);
	}

	public void HandleRoutedRPC(ZRoutedRpc.RoutedRPCData rpcData)
	{
		if (m_functions.TryGetValue(rpcData.m_methodHash, out var value))
		{
			value.Invoke(rpcData.m_senderPeerID, rpcData.m_parameters);
		}
		else
		{
			ZLog.LogWarning("Failed to find rpc method " + rpcData.m_methodHash);
		}
	}

	public void InvokeRPC(long targetID, string method, params object[] parameters)
	{
		ZRoutedRpc.instance.InvokeRoutedRPC(targetID, m_zdo.m_uid, method, parameters);
	}

	public void InvokeRPC(string method, params object[] parameters)
	{
		ZRoutedRpc.instance.InvokeRoutedRPC(m_zdo.GetOwner(), m_zdo.m_uid, method, parameters);
	}

	public static object[] Deserialize(long callerID, ParameterInfo[] paramInfo, ZPackage pkg)
	{
		List<object> parameters = new List<object>();
		parameters.Add(callerID);
		ZRpc.Deserialize(paramInfo, pkg, ref parameters);
		return parameters.ToArray();
	}

	public static void StartGhostInit()
	{
		m_ghostInit = true;
	}

	public static void FinishGhostInit()
	{
		m_ghostInit = false;
	}

	public void HoldReferenceTo(IReferenceCounted reference)
	{
		if (m_heldReferences == null)
		{
			m_heldReferences = new List<IReferenceCounted>(1);
		}
		reference.HoldReference();
		m_heldReferences.Add(reference);
	}

	public void ReleaseReferenceTo(IReferenceCounted reference)
	{
		if (m_heldReferences != null && m_heldReferences.Remove(reference))
		{
			reference.Release();
		}
	}
}
using System;
using System.Net;
using System.Net.Sockets;
using System.Threading;

public class ZNtp : IDisposable
{
	private static ZNtp m_instance;

	private DateTime m_ntpTime;

	private bool m_status;

	private bool m_stop;

	private Thread m_ntpThread;

	private Mutex m_lock = new Mutex();

	public static ZNtp instance => m_instance;

	public ZNtp()
	{
		m_instance = this;
		m_ntpTime = DateTime.UtcNow;
		m_ntpThread = new Thread(NtpThread);
		m_ntpThread.Start();
	}

	public void Dispose()
	{
		if (m_ntpThread != null)
		{
			ZLog.Log("Stoping ntp thread");
			m_lock.WaitOne();
			m_stop = true;
			m_ntpThread.Abort();
			m_lock.ReleaseMutex();
			m_ntpThread = null;
		}
		if (m_lock != null)
		{
			m_lock.Close();
			m_lock = null;
		}
	}

	public bool GetStatus()
	{
		return m_status;
	}

	public void Update(float dt)
	{
		m_lock.WaitOne();
		m_ntpTime = m_ntpTime.AddSeconds(dt);
		m_lock.ReleaseMutex();
	}

	private void NtpThread()
	{
		while (!m_stop)
		{
			if (GetNetworkTime("pool.ntp.org", out var time))
			{
				m_status = true;
				m_lock.WaitOne();
				m_ntpTime = time;
				m_lock.ReleaseMutex();
			}
			else
			{
				m_status = false;
			}
			Thread.Sleep(60000);
		}
	}

	public DateTime GetTime()
	{
		return m_ntpTime;
	}

	private bool GetNetworkTime(string ntpServer, out DateTime time)
	{
		byte[] array = new byte[48];
		array[0] = 27;
		IPAddress[] addressList;
		try
		{
			addressList = Dns.GetHostEntry(ntpServer).AddressList;
			if (addressList.Length == 0)
			{
				ZLog.Log("Dns lookup failed");
				time = DateTime.UtcNow;
				return false;
			}
		}
		catch
		{
			ZLog.Log("Failed ntp dns lookup");
			time = DateTime.UtcNow;
			return false;
		}
		IPEndPoint remoteEP = new IPEndPoint(addressList[0], 123);
		Socket socket = null;
		try
		{
			socket = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp);
			socket.ReceiveTimeout = 3000;
			socket.SendTimeout = 3000;
			socket.Connect(remoteEP);
			if (!socket.Connected)
			{
				ZLog.Log("Failed to connect to ntp");
				time = DateTime.UtcNow;
				socket.Close();
				return false;
			}
			socket.Send(array);
			socket.Receive(array);
			socket.Shutdown(SocketShutdown.Both);
			socket.Close();
		}
		catch
		{
			socket?.Close();
			time = DateTime.UtcNow;
			return false;
		}
		ulong num = ((ulong)array[40] << 24) | ((ulong)array[41] << 16) | ((ulong)array[42] << 8) | array[43];
		ulong num2 = ((ulong)array[44] << 24) | ((ulong)array[45] << 16) | ((ulong)array[46] << 8) | array[47];
		ulong num3 = num * 1000 + num2 * 1000 / 4294967296L;
		time = new DateTime(1900, 1, 1).AddMilliseconds((long)num3);
		return true;
	}
}
