	public static ZoneSystem instance => m_instance;

	public bool LocationsGenerated
	{
		get
		{
			return m_locationsGenerated;
		}
		private set
		{
			m_locationsGenerated = value;
			if (m_locationsGenerated)
			{
				m_generateLocationsCompleted?.Invoke();
				m_generateLocationsCompleted = null;
			}
		}
	}

	public float GenerateLocationsProgress => m_generateLocationsProgress;

	public event Action GenerateLocationsCompleted
	{
		add
		{
			if (m_locationsGenerated)
			{
				value?.Invoke();
			}
			else
			{
				m_generateLocationsCompleted = (Action)Delegate.Combine(m_generateLocationsCompleted, value);
			}
		}
		remove
		{
			m_generateLocationsCompleted = (Action)Delegate.Remove(m_generateLocationsCompleted, value);
		}
	}

	private ZoneSystem()
	{
	}

	private void Awake()
	{
		m_instance = this;
		m_terrainRayMask = LayerMask.GetMask("terrain");
		m_blockRayMask = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece");
		m_solidRayMask = LayerMask.GetMask("Default", "static_solid", "Default_small", "piece", "terrain");
		m_staticSolidRayMask = LayerMask.GetMask("static_solid", "terrain");
		foreach (GameObject locationList in m_locationLists)
		{
			UnityEngine.Object.Instantiate(locationList);
		}
		ZLog.Log("Zonesystem Awake " + Time.frameCount);
	}

	private void Start()
	{
		ZLog.Log("Zonesystem Start " + Time.frameCount);
		UpdateWorldRates();
		SetupLocations();
		ValidateVegetation();
		ZRoutedRpc zRoutedRpc = ZRoutedRpc.instance;
		zRoutedRpc.m_onNewPeer = (Action<long>)Delegate.Combine(zRoutedRpc.m_onNewPeer, new Action<long>(OnNewPeer));
		if (ZNet.instance.IsServer())
		{
			ZRoutedRpc.instance.Register<string>("SetGlobalKey", RPC_SetGlobalKey);
			ZRoutedRpc.instance.Register<string>("RemoveGlobalKey", RPC_RemoveGlobalKey);
		}
		else
		{
			ZRoutedRpc.instance.Register<List<string>>("GlobalKeys", RPC_GlobalKeys);
			ZRoutedRpc.instance.Register<ZPackage>("LocationIcons", RPC_LocationIcons);
		}
		m_startTime = (m_lastFixedTime = Time.fixedTime);
	}

	public void GenerateLocationsIfNeeded()
	{
		if (!LocationsGenerated)
		{
			GenerateLocations();
		}
	}

	private void SendGlobalKeys(long peer)
	{
		List<string> list = new List<string>(m_globalKeys);
		ZRoutedRpc.instance.InvokeRoutedRPC(peer, "GlobalKeys", list);
		Player.m_localPlayer?.UpdateEvents();
	}

	private void RPC_GlobalKeys(long sender, List<string> keys)
	{
		ZLog.Log("client got keys " + keys.Count);
		ClearGlobalKeys();
		foreach (string key in keys)
		{
			GlobalKeyAdd(key);
		}
	}

	private void GlobalKeyAdd(string keyStr, bool canSaveToServerOptionKeys = true)
	{
		string value;
		GlobalKeys gk;
		string keyValue = GetKeyValue(keyStr.ToLower(), out value, out gk);
		bool flag = canSaveToServerOptionKeys && ZNet.World != null && gk < GlobalKeys.NonServerOption;
		if (m_globalKeysValues.TryGetValue(keyValue, out var value2))
		{
			string item = (keyValue + " " + value2).TrimEnd();
			m_globalKeys.Remove(item);
			if (flag)
			{
				ZNet.World.m_startingGlobalKeys.Remove(item);
			}
		}
		string text = (keyValue + " " + value).TrimEnd();
		m_globalKeys.Add(text);
		m_globalKeysValues[keyValue] = value;
		if (gk != GlobalKeys.NonServerOption)
		{
			m_globalKeysEnums.Add(gk);
		}
		Game.instance.GetPlayerProfile().m_knownWorldKeys.IncrementOrSet(text);
		if (flag)
		{
			ZNet.World.m_startingGlobalKeys.Add(keyStr.ToLower());
		}
		UpdateWorldRates();
	}

	private bool GlobalKeyRemove(string keyStr, bool canSaveToServerOptionKeys = true)
	{
		string value;
		GlobalKeys gk;
		string keyValue = GetKeyValue(keyStr, out value, out gk);
		if (m_globalKeysValues.TryGetValue(keyValue, out var value2))
		{
			string item = (keyValue + " " + value2).TrimEnd();
			if (canSaveToServerOptionKeys && ZNet.World != null && gk < GlobalKeys.NonServerOption)
			{
				ZNet.World.m_startingGlobalKeys.Remove(item);
			}
			m_globalKeys.Remove(item);
			m_globalKeysValues.Remove(keyValue);
			if (gk != GlobalKeys.NonServerOption)
			{
				m_globalKeysEnums.Remove(gk);
			}
			UpdateWorldRates();
			return true;
		}
		return false;
	}

	public void UpdateWorldRates()
	{
		Game.UpdateWorldRates(m_globalKeys, m_globalKeysValues);
	}

	public void Reset()
	{
		ClearGlobalKeys();
		UpdateWorldRates();
	}

	private void ClearGlobalKeys()
	{
		m_globalKeys.Clear();
		m_globalKeysEnums.Clear();
		m_globalKeysValues.Clear();
	}

	public static string GetKeyValue(string key, out string value, out GlobalKeys gk)
	{
		int num = key.IndexOf(' ');
		value = "";
		string text;
		if (num > 0)
		{
			value = key.Substring(num + 1);
			text = key.Substring(0, num).ToLower();
		}
		else
		{
			text = key.ToLower();
		}
		if (!Enum.TryParse<GlobalKeys>(text, ignoreCase: true, out gk))
		{
			gk = GlobalKeys.NonServerOption;
		}
		return text;
	}

	private void SendLocationIcons(long peer)
	{
		ZPackage zPackage = new ZPackage();
		tempIconList.Clear();
		GetLocationIcons(tempIconList);
		zPackage.Write(tempIconList.Count);
		foreach (KeyValuePair<Vector3, string> tempIcon in tempIconList)
		{
			zPackage.Write(tempIcon.Key);
			zPackage.Write(tempIcon.Value);
		}
		ZRoutedRpc.instance.InvokeRoutedRPC(peer, "LocationIcons", zPackage);
	}

	private void RPC_LocationIcons(long sender, ZPackage pkg)
	{
		ZLog.Log("client got location icons");
		m_locationIcons.Clear();
		int num = pkg.ReadInt();
		for (int i = 0; i < num; i++)
		{
			Vector3 key = pkg.ReadVector3();
			string value = pkg.ReadString();
			m_locationIcons[key] = value;
		}
		ZLog.Log("Icons:" + num);
	}

	private void OnNewPeer(long peerID)
	{
		if (ZNet.instance.IsServer())
		{
			ZLog.Log("Server: New peer connected,sending global keys");
			SendGlobalKeys(peerID);
			SendLocationIcons(peerID);
		}
	}

	private void SetupLocations()
	{
		List<LocationList> allLocationLists = LocationList.GetAllLocationLists();
		allLocationLists.Sort((LocationList a, LocationList b) => a.m_sortOrder.CompareTo(b.m_sortOrder));
		foreach (LocationList item in allLocationLists)
		{
			m_locations.AddRange(item.m_locations);
			m_vegetation.AddRange(item.m_vegetation);
			foreach (EnvSetup environment in item.m_environments)
			{
				EnvMan.instance.AppendEnvironment(environment);
			}
			foreach (BiomeEnvSetup biomeEnvironment in item.m_biomeEnvironments)
			{
				EnvMan.instance.AppendBiomeSetup(biomeEnvironment);
			}
			ClutterSystem.instance.m_clutter.AddRange(item.m_clutter);
			ZLog.Log($"Added {item.m_locations.Count} locations, {item.m_vegetation.Count} vegetations, {item.m_environments.Count} environments, {item.m_biomeEnvironments.Count} biome env-setups, {item.m_clutter.Count} clutter  from " + item.gameObject.scene.name);
			RandEventSystem.instance.m_events.AddRange(item.m_events);
		}
		foreach (ZoneLocation location in m_locations)
		{
			if ((location.m_enable || location.m_prefab.IsValid) && Application.isPlaying)
			{
				location.m_prefabName = location.m_prefab.Name;
				int hash = location.Hash;
				if (!m_locationsByHash.ContainsKey(hash))
				{
					m_locationsByHash.Add(hash, location);
				}
			}
		}
		if (!Settings.AssetMemoryUsagePolicy.HasFlag(AssetMemoryUsagePolicy.KeepAsynchronousLoadedBit))
		{
			return;
		}
		ReferenceHolder referenceHolder = base.gameObject.AddComponent<ReferenceHolder>();
		foreach (ZoneLocation location2 in m_locations)
		{
			if (location2.m_enable)
			{
				location2.m_prefab.Load();
				referenceHolder.HoldReferenceTo(location2.m_prefab);
				location2.m_prefab.Release();
			}
		}
	}

	public static void PrepareNetViews(GameObject root, List<ZNetView> views)
	{
		views.Clear();
		ZNetView[] componentsInChildren = root.GetComponentsInChildren<ZNetView>(includeInactive: true);
		foreach (ZNetView zNetView in componentsInChildren)
		{
			if (Utils.IsEnabledInheirarcy(zNetView.gameObject, root))
			{
				views.Add(zNetView);
			}
		}
	}

	public static void PrepareRandomSpawns(GameObject root, List<RandomSpawn> randomSpawns)
	{
		randomSpawns.Clear();
		RandomSpawn[] componentsInChildren = root.GetComponentsInChildren<RandomSpawn>(includeInactive: true);
		foreach (RandomSpawn randomSpawn in componentsInChildren)
		{
			if (Utils.IsEnabledInheirarcy(randomSpawn.gameObject, root))
			{
				randomSpawns.Add(randomSpawn);
				randomSpawn.Prepare();
			}
		}
	}

	private void OnDestroy()
	{
		ForceReleaseLoadedPrefabs();
		m_instance = null;
	}

	private void ValidateVegetation()
	{
		foreach (ZoneVegetation item in m_vegetation)
		{
			if (item.m_enable && (bool)item.m_prefab && item.m_prefab.GetComponent<ZNetView>() == null)
			{
				ZLog.LogError("Vegetation " + item.m_prefab.name + " [ " + item.m_name + "] is missing ZNetView");
			}
		}
	}

	public void PrepareSave()
	{
		m_tempGeneratedZonesSaveClone = new HashSet<Vector2i>(m_generatedZones);
		m_tempGlobalKeysSaveClone = new HashSet<string>(m_globalKeys);
		m_tempLocationsSaveClone = new List<LocationInstance>(m_locationInstances.Values);
		m_tempLocationsGeneratedSaveClone = LocationsGenerated;
	}

	public void SaveASync(BinaryWriter writer)
	{
		writer.Write(m_tempGeneratedZonesSaveClone.Count);
		foreach (Vector2i item in m_tempGeneratedZonesSaveClone)
		{
			writer.Write(item.x);
			writer.Write(item.y);
		}
		writer.Write(0);
		writer.Write(m_locationVersion);
		m_tempGlobalKeysSaveClone.RemoveWhere(delegate(string x)
		{
			GetKeyValue(x, out var _, out var gk);
			return gk < GlobalKeys.NonServerOption;
		});
		writer.Write(m_tempGlobalKeysSaveClone.Count);
		foreach (string item2 in m_tempGlobalKeysSaveClone)
		{
			writer.Write(item2);
		}
		writer.Write(m_tempLocationsGeneratedSaveClone);
		writer.Write(m_tempLocationsSaveClone.Count);
		foreach (LocationInstance item3 in m_tempLocationsSaveClone)
		{
			writer.Write(item3.m_location.m_prefabName);
			writer.Write(item3.m_position.x);
			writer.Write(item3.m_position.y);
			writer.Write(item3.m_position.z);
			writer.Write(item3.m_placed);
		}
		m_tempGeneratedZonesSaveClone.Clear();
		m_tempGeneratedZonesSaveClone = null;
		m_tempGlobalKeysSaveClone.Clear();
		m_tempGlobalKeysSaveClone = null;
		m_tempLocationsSaveClone.Clear();
		m_tempLocationsSaveClone = null;
	}

	public void Load(BinaryReader reader, int version)
	{
		m_generatedZones.Clear();
		int num = reader.ReadInt32();
		for (int i = 0; i < num; i++)
		{
			Vector2i item = new Vector2i
			{
				x = reader.ReadInt32(),
				y = reader.ReadInt32()
			};
			m_generatedZones.Add(item);
		}
		if (version < 13)
		{
			return;
		}
		reader.ReadInt32();
		int num2 = ((version >= 21) ? reader.ReadInt32() : 0);
		if (version >= 14)
		{
			ClearGlobalKeys();
			int num3 = reader.ReadInt32();
			for (int j = 0; j < num3; j++)
			{
				string keyStr = reader.ReadString();
				GlobalKeyAdd(keyStr);
			}
		}
		if (version < 18)
		{
			return;
		}
		if (version >= 20)
		{
			LocationsGenerated = reader.ReadBoolean();
		}
		m_locationInstances.Clear();
		int num4 = reader.ReadInt32();
		for (int k = 0; k < num4; k++)
		{
			string text = reader.ReadString();
			Vector3 zero = Vector3.zero;
			zero.x = reader.ReadSingle();
			zero.y = reader.ReadSingle();
			zero.z = reader.ReadSingle();
			bool generated = false;
			if (version >= 19)
			{
				generated = reader.ReadBoolean();
			}
			ZoneLocation location = GetLocation(text);
			if (location != null)
			{
				RegisterLocation(location, zero, generated);
			}
			else
			{
				ZLog.DevLog("Failed to find location " + text);
			}
		}
		ZLog.Log("Loaded " + num4 + " locations");
		if (num2 != m_locationVersion)
		{
			LocationsGenerated = false;
		}
	}

	private void Update()
	{
		m_lastFixedTime = Time.fixedTime;
		if (ZNet.GetConnectionStatus() != ZNet.ConnectionStatus.Connected)
		{
			return;
		}
		if (ZNet.instance.IsServer() && !LocationsGenerated)
		{
			if (TextViewer.IsShowingIntro())
			{
				m_timeSlicedGenerationTimeBudget = GetGenerationTimeBudgetForTargetFrameRate(out var _);
			}
			else
			{
				m_timeSlicedGenerationTimeBudget = 0.1f;
			}
			return;
		}
		if (Terminal.m_showTests)
		{
			Terminal.m_testList["Time"] = Time.fixedTime.ToString("0.00") + " / " + TimeSinceStart().ToString("0.00");
		}
		m_updateTimer += Time.deltaTime;
		if (!(m_updateTimer > 0.1f))
		{
			return;
		}
		m_updateTimer = 0f;
		bool flag = CreateLocalZones(ZNet.instance.GetReferencePosition());
		UpdateTTL(0.1f);
		if (ZNet.instance.IsServer() && !flag)
		{
			CreateGhostZones(ZNet.instance.GetReferencePosition());
			foreach (ZNetPeer peer in ZNet.instance.GetPeers())
			{
				CreateGhostZones(peer.GetRefPos());
			}
		}
		UpdatePrefabLifetimes();
	}

	private void UpdatePrefabLifetimes()
	{
		for (int i = 0; i < m_locationPrefabs.Count; i++)
		{
			m_locationPrefabs[i].m_iterationLifetime--;
			if (m_locationPrefabs[i].m_iterationLifetime <= 0)
			{
				m_tempLocationPrefabsToRelease.Add(i);
			}
		}
		for (int num = m_tempLocationPrefabsToRelease.Count - 1; num >= 0; num--)
		{
			int index = m_tempLocationPrefabsToRelease[num];
			m_locationPrefabs[index].Release();
			m_locationPrefabs.RemoveAt(index);
		}
		m_tempLocationPrefabsToRelease.Clear();
	}

	private void ForceReleaseLoadedPrefabs()
	{
		foreach (LocationPrefabLoadData locationPrefab in m_locationPrefabs)
		{
			locationPrefab.Release();
		}
		m_locationPrefabs.Clear();
	}

	private bool CreateGhostZones(Vector3 refPoint)
	{
		Vector2i zone = GetZone(refPoint);
		if (!IsZoneGenerated(zone) && SpawnZone(zone, SpawnMode.Ghost, out var _))
		{
			return true;
		}
		int num = m_activeArea + m_activeDistantArea;
		for (int i = zone.y - num; i <= zone.y + num; i++)
		{
			for (int j = zone.x - num; j <= zone.x + num; j++)
			{
				Vector2i zoneID = new Vector2i(j, i);
				if (!IsZoneGenerated(zoneID) && SpawnZone(zoneID, SpawnMode.Ghost, out var _))
				{
					return true;
				}
			}
		}
		return false;
	}

	private bool CreateLocalZones(Vector3 refPoint)
	{
		Vector2i zone = GetZone(refPoint);
		if (PokeLocalZone(zone))
		{
			return true;
		}
		for (int i = zone.y - m_activeArea; i <= zone.y + m_activeArea; i++)
		{
			for (int j = zone.x - m_activeArea; j <= zone.x + m_activeArea; j++)
			{
				Vector2i vector2i = new Vector2i(j, i);
				if (!(vector2i == zone) && PokeLocalZone(vector2i))
				{
					return true;
				}
			}
		}
		return false;
	}

	private bool PokeLocalZone(Vector2i zoneID)
	{
		if (m_zones.TryGetValue(zoneID, out var value))
		{
			value.m_ttl = 0f;
			return false;
		}
		SpawnMode mode = ((!ZNet.instance.IsServer() || IsZoneGenerated(zoneID)) ? SpawnMode.Client : SpawnMode.Full);
		if (SpawnZone(zoneID, mode, out var root))
		{
			ZoneData zoneData = new ZoneData();
			zoneData.m_root = root;
			m_zones.Add(zoneID, zoneData);
			return true;
		}
		return false;
	}

	public bool IsZoneLoaded(Vector3 point)
	{
		Vector2i zone = GetZone(point);
		return IsZoneLoaded(zone);
	}

	public bool IsZoneLoaded(Vector2i zoneID)
	{
		if (m_zones.ContainsKey(zoneID))
		{
			return !m_loadingObjectsInZones.ContainsKey(zoneID);
		}
		return false;
	}

	public bool IsActiveAreaLoaded()
	{
		Vector2i zone = GetZone(ZNet.instance.GetReferencePosition());
		for (int i = zone.y - m_activeArea; i <= zone.y + m_activeArea; i++)
		{
			for (int j = zone.x - m_activeArea; j <= zone.x + m_activeArea; j++)
			{
				if (!m_zones.ContainsKey(new Vector2i(j, i)))
				{
					return false;
				}
			}
		}
		return true;
	}

	private bool SpawnZone(Vector2i zoneID, SpawnMode mode, out GameObject root)
	{
		Vector3 zonePos = GetZonePos(zoneID);
		Heightmap componentInChildren = m_zonePrefab.GetComponentInChildren<Heightmap>();
		if (!HeightmapBuilder.instance.IsTerrainReady(zonePos, componentInChildren.m_width, componentInChildren.m_scale, componentInChildren.IsDistantLod, WorldGenerator.instance))
		{
			root = null;
			return false;
		}
		if (m_locationInstances.TryGetValue(zoneID, out var value) && !value.m_placed && !PokeCanSpawnLocation(value.m_location, isFirstSpawn: true))
		{
			root = null;
			return false;
		}
		root = UnityEngine.Object.Instantiate(m_zonePrefab, zonePos, Quaternion.identity);
		if ((mode == SpawnMode.Ghost || mode == SpawnMode.Full) && !IsZoneGenerated(zoneID))
		{
			Heightmap componentInChildren2 = root.GetComponentInChildren<Heightmap>();
			m_tempClearAreas.Clear();
			m_tempSpawnedObjects.Clear();
			PlaceLocations(zoneID, zonePos, root.transform, componentInChildren2, m_tempClearAreas, mode, m_tempSpawnedObjects);
			PlaceVegetation(zoneID, zonePos, root.transform, componentInChildren2, m_tempClearAreas, mode, m_tempSpawnedObjects);
			PlaceZoneCtrl(zoneID, zonePos, mode, m_tempSpawnedObjects);
			if (mode == SpawnMode.Ghost)
			{
				foreach (GameObject tempSpawnedObject in m_tempSpawnedObjects)
				{
					UnityEngine.Object.Destroy(tempSpawnedObject);
				}
				m_tempSpawnedObjects.Clear();
				UnityEngine.Object.Destroy(root);
				root = null;
			}
			SetZoneGenerated(zoneID);
		}
		return true;
	}

	private void PlaceZoneCtrl(Vector2i zoneID, Vector3 zoneCenterPos, SpawnMode mode, List<GameObject> spawnedObjects)
	{
		if (mode == SpawnMode.Full || mode == SpawnMode.Ghost)
		{
			if (mode == SpawnMode.Ghost)
			{
				ZNetView.StartGhostInit();
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(m_zoneCtrlPrefab, zoneCenterPos, Quaternion.identity);
			gameObject.GetComponent<ZNetView>();
			if (mode == SpawnMode.Ghost)
			{
				spawnedObjects.Add(gameObject);
				ZNetView.FinishGhostInit();
			}
		}
	}

	private Vector3 GetRandomPointInRadius(Vector3 center, float radius)
	{
		float f = UnityEngine.Random.value * MathF.PI * 2f;
		float num = UnityEngine.Random.Range(0f, radius);
		return center + new Vector3(Mathf.Sin(f) * num, 0f, Mathf.Cos(f) * num);
	}

	private void PlaceVegetation(Vector2i zoneID, Vector3 zoneCenterPos, Transform parent, Heightmap hmap, List<ClearArea> clearAreas, SpawnMode mode, List<GameObject> spawnedObjects)
	{
		UnityEngine.Random.State state = UnityEngine.Random.state;
		int seed = WorldGenerator.instance.GetSeed();
		int num = 1;
		foreach (ZoneVegetation item in m_vegetation)
		{
			num++;
			if (!item.m_enable || !hmap.HaveBiome(item.m_biome))
			{
				continue;
			}
			UnityEngine.Random.InitState(seed + zoneID.x * 4271 + zoneID.y * 9187 + item.m_prefab.name.GetStableHashCode());
			int num2 = 1;
			if (item.m_max < 1f)
			{
				if (UnityEngine.Random.value > item.m_max)
				{
					continue;
				}
			}
			else
			{
				num2 = UnityEngine.Random.Range((int)item.m_min, (int)item.m_max + 1);
			}
			bool flag = item.m_prefab.GetComponent<ZNetView>() != null;
			float num3 = Mathf.Cos(MathF.PI / 180f * item.m_maxTilt);
			float num4 = Mathf.Cos(MathF.PI / 180f * item.m_minTilt);
			float num5 = 32f - item.m_groupRadius;
			s_tempVeg.Clear();
			int num6 = (item.m_forcePlacement ? (num2 * 50) : num2);
			int num7 = 0;
			for (int i = 0; i < num6; i++)
			{
				Vector3 vector = new Vector3(UnityEngine.Random.Range(zoneCenterPos.x - num5, zoneCenterPos.x + num5), 0f, UnityEngine.Random.Range(zoneCenterPos.z - num5, zoneCenterPos.z + num5));
				int num8 = UnityEngine.Random.Range(item.m_groupSizeMin, item.m_groupSizeMax + 1);
				bool flag2 = false;
				for (int j = 0; j < num8; j++)
				{
					Vector3 p = ((j == 0) ? vector : GetRandomPointInRadius(vector, item.m_groupRadius));
					float y = UnityEngine.Random.Range(0, 360);
					float num9 = UnityEngine.Random.Range(item.m_scaleMin, item.m_scaleMax);
					float x = UnityEngine.Random.Range(0f - item.m_randTilt, item.m_randTilt);
					float z = UnityEngine.Random.Range(0f - item.m_randTilt, item.m_randTilt);
					if (item.m_blockCheck && IsBlocked(p))
					{
						continue;
					}
					GetGroundData(ref p, out var normal, out var biome, out var biomeArea, out var hmap2);
					if ((item.m_biome & biome) == 0 || (item.m_biomeArea & biomeArea) == 0)
					{
						continue;
					}
					if (item.m_snapToStaticSolid && GetStaticSolidHeight(p, out var height, out var normal2))
					{
						p.y = height;
						normal = normal2;
					}
					float num10 = p.y - 30f;
					if (num10 < item.m_minAltitude || num10 > item.m_maxAltitude)
					{
						continue;
					}
					if (item.m_minVegetation != item.m_maxVegetation)
					{
						float vegetationMask = hmap2.GetVegetationMask(p);
						if (vegetationMask > item.m_maxVegetation || vegetationMask < item.m_minVegetation)
						{
							continue;
						}
					}
					if (item.m_minOceanDepth != item.m_maxOceanDepth)
					{
						float oceanDepth = hmap2.GetOceanDepth(p);
						if (oceanDepth < item.m_minOceanDepth || oceanDepth > item.m_maxOceanDepth)
						{
							continue;
						}
					}
					if (normal.y < num3 || normal.y > num4)
					{
						continue;
					}
					if (item.m_terrainDeltaRadius > 0f)
					{
						GetTerrainDelta(p, item.m_terrainDeltaRadius, out var delta, out var _);
						if (delta > item.m_maxTerrainDelta || delta < item.m_minTerrainDelta)
						{
							continue;
						}
					}
					if (item.m_minDistanceFromCenter > 0f || item.m_maxDistanceFromCenter > 0f)
					{
						float num11 = Utils.LengthXZ(p);
						if ((item.m_minDistanceFromCenter > 0f && num11 < item.m_minDistanceFromCenter) || (item.m_maxDistanceFromCenter > 0f && num11 > item.m_maxDistanceFromCenter))
						{
							continue;
						}
					}
					if (item.m_inForest)
					{
						float forestFactor = WorldGenerator.GetForestFactor(p);
						if (forestFactor < item.m_forestTresholdMin || forestFactor > item.m_forestTresholdMax)
						{
							continue;
						}
					}
					if (item.m_surroundCheckVegetation)
					{
						float num12 = 0f;
						for (int k = 0; k < item.m_surroundCheckLayers; k++)
						{
							float num13 = (float)(k + 1) / (float)item.m_surroundCheckLayers * item.m_surroundCheckDistance;
							for (int l = 0; l < 6; l++)
							{
								float f = (float)l / 6f * MathF.PI * 2f;
								float vegetationMask2 = hmap2.GetVegetationMask(p + new Vector3(Mathf.Sin(f) * num13, 0f, Mathf.Cos(f) * num13));
								float num14 = (1f - num13) / (item.m_surroundCheckDistance * 2f);
								num12 += vegetationMask2 * num14;
							}
						}
						s_tempVeg.Add(num12);
						if (s_tempVeg.Count < 10)
						{
							continue;
						}
						float num15 = s_tempVeg.Max();
						float num16 = s_tempVeg.Average();
						float num17 = num16 + (num15 - num16) * item.m_surroundBetterThanAverage;
						if (num12 < num17)
						{
							continue;
						}
					}
					if (InsideClearArea(clearAreas, p))
					{
						continue;
					}
					if (item.m_snapToWater)
					{
						p.y = 30f;
					}
					p.y += item.m_groundOffset;
					Quaternion identity = Quaternion.identity;
					if (item.m_chanceToUseGroundTilt > 0f && UnityEngine.Random.value <= item.m_chanceToUseGroundTilt)
					{
						Quaternion quaternion = Quaternion.Euler(0f, y, 0f);
						identity = Quaternion.LookRotation(Vector3.Cross(normal, quaternion * Vector3.forward), normal);
					}
					else
					{
						identity = Quaternion.Euler(x, y, z);
					}
					if (flag)
					{
						if (mode == SpawnMode.Full || mode == SpawnMode.Ghost)
						{
							if (mode == SpawnMode.Ghost)
							{
								ZNetView.StartGhostInit();
							}
							GameObject gameObject = UnityEngine.Object.Instantiate(item.m_prefab, p, identity);
							ZNetView component = gameObject.GetComponent<ZNetView>();
							if (num9 != gameObject.transform.localScale.x)
							{
								component.SetLocalScale(new Vector3(num9, num9, num9));
								Collider[] componentsInChildren = gameObject.GetComponentsInChildren<Collider>();
								foreach (Collider obj in componentsInChildren)
								{
									obj.enabled = false;
									obj.enabled = true;
								}
							}
							if (mode == SpawnMode.Ghost)
							{
								spawnedObjects.Add(gameObject);
								ZNetView.FinishGhostInit();
							}
						}
					}
					else
					{
						GameObject obj2 = UnityEngine.Object.Instantiate(item.m_prefab, p, identity);
						obj2.transform.localScale = new Vector3(num9, num9, num9);
						obj2.transform.SetParent(parent, worldPositionStays: true);
					}
					flag2 = true;
				}
				if (flag2)
				{
					num7++;
				}
				if (num7 >= num2)
				{
					break;
				}
			}
		}
		UnityEngine.Random.state = state;
	}

	private bool InsideClearArea(List<ClearArea> areas, Vector3 point)
	{
		foreach (ClearArea area in areas)
		{
			if (point.x > area.m_center.x - area.m_radius && point.x < area.m_center.x + area.m_radius && point.z > area.m_center.z - area.m_radius && point.z < area.m_center.z + area.m_radius)
			{
				return true;
			}
		}
		return false;
	}

	private ZoneLocation GetLocation(int hash)
	{
		if (m_locationsByHash.TryGetValue(hash, out var value))
		{
			return value;
		}
		return null;
	}

	private ZoneLocation GetLocation(string name)
	{
		foreach (ZoneLocation location in m_locations)
		{
			if (!location.m_prefab.IsValid)
			{
				if (location.m_enable)
				{
					throw new NullReferenceException($"Location in list of locations was invalid! Asset: {location.m_prefab.m_assetID}");
				}
			}
			else if (location.m_prefab.Name == name)
			{
				return location;
			}
		}
		return null;
	}

	private void ClearNonPlacedLocations()
	{
		Dictionary<Vector2i, LocationInstance> dictionary = new Dictionary<Vector2i, LocationInstance>();
		foreach (KeyValuePair<Vector2i, LocationInstance> locationInstance in m_locationInstances)
		{
			if (locationInstance.Value.m_placed)
			{
				dictionary.Add(locationInstance.Key, locationInstance.Value);
			}
		}
		m_locationInstances = dictionary;
	}

	private void CheckLocationDuplicates()
	{
		ZLog.Log("Checking for location duplicates");
		Stopwatch stopwatch = new Stopwatch();
		stopwatch.Start();
		for (int i = 0; i < m_locations.Count; i++)
		{
			ZoneLocation zoneLocation = m_locations[i];
			if (!zoneLocation.m_enable)
			{
				continue;
			}
			for (int j = i + 1; j < m_locations.Count; j++)
			{
				ZoneLocation zoneLocation2 = m_locations[j];
				if (zoneLocation2.m_enable)
				{
					if (zoneLocation.m_prefab.Name == zoneLocation2.m_prefab.Name)
					{
						SoftReference<GameObject> prefab = zoneLocation.m_prefab;
						ZLog.LogWarning("Two locations have the same location prefab name " + prefab.ToString());
					}
					if (zoneLocation.m_prefab == zoneLocation2.m_prefab)
					{
						ZLog.LogWarning($"Locations {zoneLocation.m_prefab} and {zoneLocation2.m_prefab} point to the same location prefab");
					}
				}
			}
		}
		stopwatch.Stop();
		ZLog.Log($"Location duplicate check took {stopwatch.Elapsed.TotalMilliseconds} ms");
	}

	public void GenerateLocations()
	{
		if (m_generateLocationsCoroutine == null)
		{
			if (!Application.isPlaying)
			{
				ZLog.Log("Setting up locations");
				SetupLocations();
			}
			m_generateLocationsCoroutine = StartCoroutine(GenerateLocationsTimeSliced());
		}
	}

	private IEnumerator GenerateLocationsTimeSliced()
	{
		m_estimatedGenerateLocationsCompletionTime = DateTime.MaxValue;
		yield return null;
		Stopwatch timeSliceStopwatch = Stopwatch.StartNew();
		ZLog.Log("Generating locations");
		DateTime startTime = DateTime.UtcNow;
		ClearNonPlacedLocations();
		List<ZoneLocation> ordered = m_locations.OrderByDescending((ZoneLocation a) => a.m_prioritized).ToList();
		int totalEstimatedIterationsLeft = 0;
		for (int num = ordered.Count - 1; num >= 0; num--)
		{
			ZoneLocation zoneLocation = ordered[num];
			if (!zoneLocation.m_enable || zoneLocation.m_quantity == 0)
			{
				ordered.RemoveAt(num);
			}
			else
			{
				totalEstimatedIterationsLeft += (zoneLocation.m_prioritized ? 200000 : 100000) * 20 / 2;
			}
		}
		int runIterations = 0;
		for (int i = 0; i < ordered.Count; i++)
		{
			ZoneLocation location = ordered[i];
			if (timeSliceStopwatch.Elapsed.TotalSeconds >= (double)m_timeSlicedGenerationTimeBudget)
			{
				yield return null;
				timeSliceStopwatch.Restart();
			}
			ZPackage iterationsPkg = new ZPackage();
			yield return GenerateLocationsTimeSliced(location, timeSliceStopwatch, iterationsPkg);
			runIterations += iterationsPkg.ReadInt();
			totalEstimatedIterationsLeft -= (location.m_prioritized ? 200000 : 100000) * 20 / 2;
			DateTime utcNow = DateTime.UtcNow;
			double totalSeconds = (utcNow - startTime).TotalSeconds;
			double num2 = ((runIterations != 0) ? (totalSeconds / (double)runIterations) : double.MaxValue);
			double num3 = num2 * (double)totalEstimatedIterationsLeft;
			if (double.IsInfinity(num3))
			{
				m_estimatedGenerateLocationsCompletionTime = DateTime.MaxValue;
			}
			else
			{
				m_estimatedGenerateLocationsCompletionTime = utcNow.AddSeconds(num3);
			}
			m_generateLocationsProgress = (float)(i + 1) / (float)ordered.Count;
		}
		LocationsGenerated = true;
		ZLog.Log(" Done generating locations, duration:" + (DateTime.UtcNow - startTime).TotalMilliseconds + " ms");
		m_generateLocationsCoroutine = null;
	}

	private int CountNrOfLocation(ZoneLocation location)
	{
		int num = 0;
		foreach (LocationInstance value in m_locationInstances.Values)
		{
			if (value.m_location.m_prefab.Name == location.m_prefab.Name)
			{
				num++;
			}
		}
		if (num > 0)
		{
			SoftReference<GameObject> prefab = location.m_prefab;
			ZLog.Log("Old location found " + prefab.ToString() + " x " + num);
		}
		return num;
	}

	private IEnumerator GenerateLocationsTimeSliced(ZoneLocation location, Stopwatch timeSliceStopwatch, ZPackage iterationsPkg)
	{
		DateTime t = DateTime.Now;
		int seed = WorldGenerator.instance.GetSeed() + location.m_prefab.Name.GetStableHashCode();
		UnityEngine.Random.State state = UnityEngine.Random.state;
		UnityEngine.Random.InitState(seed);
		int errorLocationInZone = 0;
		int errorCenterDistance = 0;
		int errorBiome = 0;
		int errorBiomeArea = 0;
		int errorAlt = 0;
		int errorForest = 0;
		int errorSimilar = 0;
		int errorNotSimilar = 0;
		int errorTerrainDelta = 0;
		int errorVegetation = 0;
		float maxRadius = Mathf.Max(location.m_exteriorRadius, location.m_interiorRadius);
		int attempts = (location.m_prioritized ? 200000 : 100000);
		int iterations = 0;
		int placed = CountNrOfLocation(location);
		float maxRange = 10000f;
		if (location.m_centerFirst)
		{
			maxRange = location.m_minDistance;
		}
		if (!location.m_unique || placed <= 0)
		{
			s_tempVeg.Clear();
			int i = 0;
			while (i < attempts && placed < location.m_quantity)
			{
				if (timeSliceStopwatch.Elapsed.TotalSeconds >= (double)m_timeSlicedGenerationTimeBudget)
				{
					UnityEngine.Random.State insideState = UnityEngine.Random.state;
					UnityEngine.Random.state = state;
					yield return null;
					timeSliceStopwatch.Restart();
					state = UnityEngine.Random.state;
					UnityEngine.Random.state = insideState;
				}
				Vector2i zoneID = GetRandomZone(maxRange);
				if (location.m_centerFirst)
				{
					maxRange += 1f;
				}
				int num;
				if (m_locationInstances.ContainsKey(zoneID))
				{
					num = errorLocationInZone + 1;
					errorLocationInZone = num;
				}
				else if (!IsZoneGenerated(zoneID))
				{
					Vector3 zonePos = GetZonePos(zoneID);
					Heightmap.BiomeArea biomeArea = WorldGenerator.instance.GetBiomeArea(zonePos);
					if ((location.m_biomeArea & biomeArea) == 0)
					{
						num = errorBiomeArea + 1;
						errorBiomeArea = num;
					}
					else
					{
						for (int j = 0; j < 20; num = j + 1, j = num)
						{
							if (timeSliceStopwatch.Elapsed.TotalSeconds >= (double)m_timeSlicedGenerationTimeBudget)
							{
								UnityEngine.Random.State insideState = UnityEngine.Random.state;
								UnityEngine.Random.state = state;
								yield return null;
								timeSliceStopwatch.Restart();
								state = UnityEngine.Random.state;
								UnityEngine.Random.state = insideState;
							}
							num = iterations + 1;
							iterations = num;
							Vector3 randomPointInZone = GetRandomPointInZone(zoneID, maxRadius);
							float magnitude = randomPointInZone.magnitude;
							if (location.m_minDistance != 0f && magnitude < location.m_minDistance)
							{
								num = errorCenterDistance + 1;
								errorCenterDistance = num;
								continue;
							}
							if (location.m_maxDistance != 0f && magnitude > location.m_maxDistance)
							{
								num = errorCenterDistance + 1;
								errorCenterDistance = num;
								continue;
							}
							Heightmap.Biome biome = WorldGenerator.instance.GetBiome(randomPointInZone);
							if ((location.m_biome & biome) == 0)
							{
								num = errorBiome + 1;
								errorBiome = num;
								continue;
							}
							randomPointInZone.y = WorldGenerator.instance.GetHeight(randomPointInZone.x, randomPointInZone.z, out var mask);
							float num2 = (float)((double)randomPointInZone.y - 30.0);
							if (num2 < location.m_minAltitude || num2 > location.m_maxAltitude)
							{
								num = errorAlt + 1;
								errorAlt = num;
								continue;
							}
							if (location.m_inForest)
							{
								float forestFactor = WorldGenerator.GetForestFactor(randomPointInZone);
								if (forestFactor < location.m_forestTresholdMin || forestFactor > location.m_forestTresholdMax)
								{
									num = errorForest + 1;
									errorForest = num;
									continue;
								}
							}
							if (location.m_minDistanceFromCenter > 0f || location.m_maxDistanceFromCenter > 0f)
							{
								float num3 = Utils.LengthXZ(randomPointInZone);
								if ((location.m_minDistanceFromCenter > 0f && num3 < location.m_minDistanceFromCenter) || (location.m_maxDistanceFromCenter > 0f && num3 > location.m_maxDistanceFromCenter))
								{
									continue;
								}
							}
							WorldGenerator.instance.GetTerrainDelta(randomPointInZone, location.m_exteriorRadius, out var delta, out var _);
							if (delta > location.m_maxTerrainDelta || delta < location.m_minTerrainDelta)
							{
								num = errorTerrainDelta + 1;
								errorTerrainDelta = num;
								continue;
							}
							if (location.m_minDistanceFromSimilar > 0f && HaveLocationInRange(location.m_prefab.Name, location.m_group, randomPointInZone, location.m_minDistanceFromSimilar))
							{
								num = errorSimilar + 1;
								errorSimilar = num;
								continue;
							}
							if (location.m_maxDistanceFromSimilar > 0f && !HaveLocationInRange(location.m_prefabName, location.m_groupMax, randomPointInZone, location.m_maxDistanceFromSimilar, maxGroup: true))
							{
								num = errorNotSimilar + 1;
								errorNotSimilar = num;
								continue;
							}
							float a = mask.a;
							if (location.m_minimumVegetation > 0f && a <= location.m_minimumVegetation)
							{
								num = errorVegetation + 1;
								errorVegetation = num;
								continue;
							}
							if (location.m_maximumVegetation < 1f && a >= location.m_maximumVegetation)
							{
								num = errorVegetation + 1;
								errorVegetation = num;
								continue;
							}
							if (location.m_surroundCheckVegetation)
							{
								float num4 = 0f;
								for (int k = 0; k < location.m_surroundCheckLayers; k++)
								{
									float num5 = (float)(k + 1) / (float)location.m_surroundCheckLayers * location.m_surroundCheckDistance;
									for (int l = 0; l < 6; l++)
									{
										float f = (float)l / 6f * MathF.PI * 2f;
										Vector3 vector = randomPointInZone + new Vector3(Mathf.Sin(f) * num5, 0f, Mathf.Cos(f) * num5);
										WorldGenerator.instance.GetHeight(vector.x, vector.z, out var mask2);
										float num6 = (location.m_surroundCheckDistance - num5) / (location.m_surroundCheckDistance * 2f);
										num4 += mask2.a * num6;
									}
								}
								s_tempVeg.Add(num4);
								if (s_tempVeg.Count < 10)
								{
									continue;
								}
								float num7 = s_tempVeg.Max();
								float num8 = s_tempVeg.Average();
								float num9 = num8 + (num7 - num8) * location.m_surroundBetterThanAverage;
								if (num4 < num9)
								{
									continue;
								}
								ZLog.DevLog($"Surround check passed with a value of {num4}, cutoff was {num9}, max: {num7}, average: {num8}.");
							}
							RegisterLocation(location, randomPointInZone, generated: false);
							num = placed + 1;
							placed = num;
							break;
						}
					}
				}
				num = i + 1;
				i = num;
			}
			if (placed < location.m_quantity)
			{
				ZLog.LogWarning("Failed to place all " + location.m_prefab.Name + ", placed " + placed + " out of " + location.m_quantity);
				ZLog.DevLog("errorLocationInZone " + errorLocationInZone);
				ZLog.DevLog("errorCenterDistance " + errorCenterDistance);
				ZLog.DevLog("errorBiome " + errorBiome);
				ZLog.DevLog("errorBiomeArea " + errorBiomeArea);
				ZLog.DevLog("errorAlt " + errorAlt);
				ZLog.DevLog("errorForest " + errorForest);
				ZLog.DevLog("errorSimilar " + errorSimilar);
				ZLog.DevLog("errorNotSimilar " + errorNotSimilar);
				ZLog.DevLog("errorTerrainDelta " + errorTerrainDelta);
				ZLog.DevLog("errorVegetation " + errorVegetation);
			}
		}
		UnityEngine.Random.state = state;
		_ = DateTime.Now - t;
		iterationsPkg.Write(iterations);
		iterationsPkg.SetPos(0);
	}

	public float GetEstimatedGenerationCompletionTimeFromNow()
	{
		if (m_generateLocationsCoroutine == null)
		{
			return 0f;
		}
		DateTime utcNow = DateTime.UtcNow;
		return (float)(m_estimatedGenerateLocationsCompletionTime - utcNow).TotalSeconds;
	}

	public static float GetGenerationTimeBudgetForTargetFrameRate(out float targetFrameTime)
	{
		float num;
		if (QualitySettings.vSyncCount > 0)
		{
			num = (float)Screen.currentResolution.refreshRateRatio.denominator / (float)Screen.currentResolution.refreshRateRatio.numerator * (float)QualitySettings.vSyncCount;
		}
		else
		{
			num = 1f / (float)Application.targetFrameRate;
			if (num < 0f)
			{
				num = 0f;
			}
		}
		targetFrameTime = Mathf.Clamp(num, 1f / 60f, 1f / 30f);
		float num2 = 1f / 150f;
		return targetFrameTime - num2;
	}

	private static Vector2i GetRandomZone(float range)
	{
		int num = (int)range / 64;
		Vector2i vector2i;
		do
		{
			vector2i = new Vector2i(UnityEngine.Random.Range(-num, num), UnityEngine.Random.Range(-num, num));
		}
		while (!(GetZonePos(vector2i).magnitude < 10000f));
		return vector2i;
	}

	private static Vector3 GetRandomPointInZone(Vector2i zone, float locationRadius)
	{
		Vector3 zonePos = GetZonePos(zone);
		float x = UnityEngine.Random.Range(-32f + locationRadius, 32f - locationRadius);
		float z = UnityEngine.Random.Range(-32f + locationRadius, 32f - locationRadius);
		return zonePos + new Vector3(x, 0f, z);
	}

	private static Vector3 GetRandomPointInZone(float locationRadius)
	{
		Vector3 zonePos = GetZonePos(GetZone(new Vector3(UnityEngine.Random.Range(-10000f, 10000f), 0f, UnityEngine.Random.Range(-10000f, 10000f))));
		return new Vector3(UnityEngine.Random.Range(zonePos.x - 32f + locationRadius, zonePos.x + 32f - locationRadius), 0f, UnityEngine.Random.Range(zonePos.z - 32f + locationRadius, zonePos.z + 32f - locationRadius));
	}

	private void PlaceLocations(Vector2i zoneID, Vector3 zoneCenterPos, Transform parent, Heightmap hmap, List<ClearArea> clearAreas, SpawnMode mode, List<GameObject> spawnedObjects)
	{
		DateTime now = DateTime.Now;
		if (m_locationInstances.TryGetValue(zoneID, out var value) && !value.m_placed)
		{
			Vector3 p = value.m_position;
			GetGroundData(ref p, out var _, out var _, out var _, out var _);
			if (value.m_location.m_snapToWater)
			{
				p.y = 30f;
			}
			if (value.m_location.m_clearArea)
			{
				ClearArea item = new ClearArea(p, value.m_location.m_exteriorRadius);
				clearAreas.Add(item);
			}
			Quaternion rot = Quaternion.identity;
			if (value.m_location.m_slopeRotation)
			{
				GetTerrainDelta(p, value.m_location.m_exteriorRadius, out var _, out var slopeDirection);
				Vector3 forward = new Vector3(slopeDirection.x, 0f, slopeDirection.z);
				forward.Normalize();
				rot = Quaternion.LookRotation(forward);
				Vector3 eulerAngles = rot.eulerAngles;
				eulerAngles.y = Mathf.Round(eulerAngles.y / 22.5f) * 22.5f;
				rot.eulerAngles = eulerAngles;
			}
			else if (value.m_location.m_randomRotation)
			{
				rot = Quaternion.Euler(0f, (float)UnityEngine.Random.Range(0, 16) * 22.5f, 0f);
			}
			int seed = WorldGenerator.instance.GetSeed() + zoneID.x * 4271 + zoneID.y * 9187;
			SpawnLocation(value.m_location, seed, p, rot, mode, spawnedObjects);
			value.m_placed = true;
			m_locationInstances[zoneID] = value;
			TimeSpan timeSpan = DateTime.Now - now;
			string[] obj = new string[5] { "Placed locations in zone ", null, null, null, null };
			Vector2i vector2i = zoneID;
			obj[1] = vector2i.ToString();
			obj[2] = "  duration ";
			obj[3] = timeSpan.TotalMilliseconds.ToString();
			obj[4] = " ms";
			ZLog.Log(string.Concat(obj));
			if (value.m_location.m_unique)
			{
				RemoveUnplacedLocations(value.m_location);
			}
			if (value.m_location.m_iconPlaced)
			{
				SendLocationIcons(ZRoutedRpc.Everybody);
			}
		}
	}

	private void RemoveUnplacedLocations(ZoneLocation location)
	{
		List<Vector2i> list = new List<Vector2i>();
		foreach (KeyValuePair<Vector2i, LocationInstance> locationInstance in m_locationInstances)
		{
			if (locationInstance.Value.m_location == location && !locationInstance.Value.m_placed)
			{
				list.Add(locationInstance.Key);
			}
		}
		foreach (Vector2i item in list)
		{
			m_locationInstances.Remove(item);
		}
		ZLog.DevLog("Removed " + list.Count + " unplaced locations of type " + location.m_prefab.Name);
	}

	public bool TestSpawnLocation(string name, Vector3 pos, bool disableSave = true)
	{
		if (!ZNet.instance.IsServer())
		{
			return false;
		}
		ZoneLocation location = GetLocation(name);
		if (location == null)
		{
			ZLog.Log("Missing location:" + name);
			Console.instance.Print("Missing location:" + name);
			return false;
		}
		if (!location.m_prefab.IsValid)
		{
			ZLog.Log("Missing prefab in location:" + name);
			Console.instance.Print("Missing location:" + name);
			return false;
		}
		float num = Mathf.Max(location.m_exteriorRadius, location.m_interiorRadius);
		Vector3 zonePos = GetZonePos(GetZone(pos));
		pos.x = Mathf.Clamp(pos.x, zonePos.x - 32f + num, zonePos.x + 32f - num);
		pos.z = Mathf.Clamp(pos.z, zonePos.z - 32f + num, zonePos.z + 32f - num);
		string[] obj = new string[6]
		{
			"radius ",
			num.ToString(),
			"  ",
			null,
			null,
			null
		};
		Vector3 vector = zonePos;
		obj[3] = vector.ToString();
		obj[4] = " ";
		vector = pos;
		obj[5] = vector.ToString();
		ZLog.Log(string.Concat(obj));
		MessageHud.instance.ShowMessage(MessageHud.MessageType.Center, "Location spawned, " + (disableSave ? "world saving DISABLED until restart" : "CAUTION! world saving is ENABLED, use normal location command to disable it!"));
		m_didZoneTest = disableSave;
		float y = (float)UnityEngine.Random.Range(0, 16) * 22.5f;
		List<GameObject> spawnedGhostObjects = new List<GameObject>();
		SpawnLocation(location, UnityEngine.Random.Range(0, 99999), pos, Quaternion.Euler(0f, y, 0f), SpawnMode.Full, spawnedGhostObjects);
		return true;
	}

	private bool PokeCanSpawnLocation(ZoneLocation location, bool isFirstSpawn)
	{
		LocationPrefabLoadData locationPrefabLoadData = null;
		for (int i = 0; i < m_locationPrefabs.Count; i++)
		{
			if (m_locationPrefabs[i].PrefabAssetID == location.m_prefab.m_assetID)
			{
				locationPrefabLoadData = m_locationPrefabs[i];
				break;
			}
		}
		if (locationPrefabLoadData == null)
		{
			locationPrefabLoadData = new LocationPrefabLoadData(location.m_prefab, isFirstSpawn);
			m_locationPrefabs.Add(locationPrefabLoadData);
		}
		locationPrefabLoadData.m_iterationLifetime = GetLocationPrefabLifetime();
		return locationPrefabLoadData.IsLoaded;
	}

	public int GetLocationPrefabLifetime()
	{
		int num = 2 * (m_activeArea + m_activeDistantArea) + 1;
		int num2 = num * num;
		int num3 = ((!ZNet.instance.IsServer()) ? 1 : (ZNet.instance.GetPeers().Count + 1));
		return num2 * num3;
	}

	public bool ShouldDelayProxyLocationSpawning(int hash)
	{
		ZoneLocation location = GetLocation(hash);
		if (location == null)
		{
			ZLog.LogWarning("Missing location:" + hash);
			return false;
		}
		return !PokeCanSpawnLocation(location, isFirstSpawn: false);
	}

	public GameObject SpawnProxyLocation(int hash, int seed, Vector3 pos, Quaternion rot)
	{
		ZoneLocation location = GetLocation(hash);
		if (location == null)
		{
			ZLog.LogWarning("Missing location:" + hash);
			return null;
		}
		List<GameObject> spawnedGhostObjects = new List<GameObject>();
		return SpawnLocation(location, seed, pos, rot, SpawnMode.Client, spawnedGhostObjects);
	}

	private GameObject SpawnLocation(ZoneLocation location, int seed, Vector3 pos, Quaternion rot, SpawnMode mode, List<GameObject> spawnedGhostObjects)
	{
		location.m_prefab.Load();
		ZNetView[] enabledComponentsInChildren = Utils.GetEnabledComponentsInChildren<ZNetView>(location.m_prefab.Asset);
		RandomSpawn[] enabledComponentsInChildren2 = Utils.GetEnabledComponentsInChildren<RandomSpawn>(location.m_prefab.Asset);
		for (int i = 0; i < enabledComponentsInChildren2.Length; i++)
		{
			enabledComponentsInChildren2[i].Prepare();
		}
		Location component = location.m_prefab.Asset.GetComponent<Location>();
		Vector3 vector = Vector3.zero;
		Vector3 vector2 = Vector3.zero;
		if ((bool)component.m_interiorTransform && (bool)component.m_generator)
		{
			vector = component.m_interiorTransform.localPosition;
			vector2 = component.m_generator.transform.localPosition;
		}
		Vector3 position = location.m_prefab.Asset.transform.position;
		Quaternion rotation = location.m_prefab.Asset.transform.rotation;
		location.m_prefab.Asset.transform.position = Vector3.zero;
		location.m_prefab.Asset.transform.rotation = Quaternion.identity;
		UnityEngine.Random.InitState(seed);
		bool flag = (bool)component && component.m_useCustomInteriorTransform && (bool)component.m_interiorTransform && (bool)component.m_generator;
		Vector3 localPosition = Vector3.zero;
		Vector3 localPosition2 = Vector3.zero;
		Quaternion localRotation = Quaternion.identity;
		if (flag)
		{
			localPosition = component.m_generator.transform.localPosition;
			localPosition2 = component.m_interiorTransform.localPosition;
			localRotation = component.m_interiorTransform.localRotation;
			Vector3 zonePos = GetZonePos(GetZone(pos));
			component.m_generator.transform.localPosition = Vector3.zero;
			Vector3 vector3 = zonePos + vector + vector2 - pos;
			Vector3 localPosition3 = (Matrix4x4.Rotate(Quaternion.Inverse(rot)) * Matrix4x4.Translate(vector3)).GetColumn(3);
			localPosition3.y = component.m_interiorTransform.localPosition.y;
			component.m_interiorTransform.localPosition = localPosition3;
			component.m_interiorTransform.localRotation = Quaternion.Inverse(rot);
		}
		if ((bool)component && (bool)component.m_generator && component.m_useCustomInteriorTransform != component.m_generator.m_useCustomInteriorTransform)
		{
			ZLog.LogWarning(component.name + " & " + component.m_generator.name + " don't have matching m_useCustomInteriorTransform()! If one has it the other should as well!");
		}
		GameObject gameObject = null;
		if (mode == SpawnMode.Full || mode == SpawnMode.Ghost)
		{
			UnityEngine.Random.InitState(seed);
			RandomSpawn[] array = enabledComponentsInChildren2;
			foreach (RandomSpawn obj in array)
			{
				Vector3 position2 = obj.gameObject.transform.position;
				Vector3 pos2 = pos + rot * position2;
				obj.Randomize(pos2, component);
			}
			WearNTear.m_randomInitialDamage = component.m_applyRandomDamage;
			ZNetView[] array2 = enabledComponentsInChildren;
			foreach (ZNetView zNetView in array2)
			{
				if (!zNetView.gameObject.activeSelf)
				{
					continue;
				}
				Vector3 position3 = zNetView.gameObject.transform.position;
				Vector3 position4 = pos + rot * position3;
				Quaternion rotation2 = zNetView.gameObject.transform.rotation;
				Quaternion rotation3 = rot * rotation2;
				if (mode == SpawnMode.Ghost)
				{
					ZNetView.StartGhostInit();
				}
				GameObject gameObject2 = UnityEngine.Object.Instantiate(zNetView.gameObject, position4, rotation3);
				gameObject2.HoldReferenceTo(location.m_prefab);
				DungeonGenerator component2 = gameObject2.GetComponent<DungeonGenerator>();
				if ((bool)component2)
				{
					if (flag)
					{
						component2.m_originalPosition = vector2;
					}
					component2.Generate(mode);
				}
				if (mode == SpawnMode.Ghost)
				{
					spawnedGhostObjects.Add(gameObject2);
					ZNetView.FinishGhostInit();
				}
			}
			WearNTear.m_randomInitialDamage = false;
			array = enabledComponentsInChildren2;
			for (int j = 0; j < array.Length; j++)
			{
				array[j].Reset();
			}
			array2 = enabledComponentsInChildren;
			for (int j = 0; j < array2.Length; j++)
			{
				array2[j].gameObject.SetActive(value: true);
			}
			location.m_prefab.Asset.transform.position = position;
			location.m_prefab.Asset.transform.rotation = rotation;
			if (flag)
			{
				component.m_generator.transform.localPosition = localPosition;
				component.m_interiorTransform.localPosition = localPosition2;
				component.m_interiorTransform.localRotation = localRotation;
			}
			CreateLocationProxy(location, seed, pos, rot, mode, spawnedGhostObjects);
		}
		else
		{
			UnityEngine.Random.InitState(seed);
			RandomSpawn[] array = enabledComponentsInChildren2;
			foreach (RandomSpawn obj2 in array)
			{
				Vector3 position5 = obj2.gameObject.transform.position;
				Vector3 pos3 = pos + rot * position5;
				obj2.Randomize(pos3, component);
			}
			ZNetView[] array2 = enabledComponentsInChildren;
			for (int j = 0; j < array2.Length; j++)
			{
				array2[j].gameObject.SetActive(value: false);
			}
			gameObject = SoftReferenceableAssets.Utils.Instantiate(location.m_prefab, pos, rot);
			gameObject.SetActive(value: true);
			array = enabledComponentsInChildren2;
			for (int j = 0; j < array.Length; j++)
			{
				array[j].Reset();
			}
			array2 = enabledComponentsInChildren;
			for (int j = 0; j < array2.Length; j++)
			{
				array2[j].gameObject.SetActive(value: true);
			}
			location.m_prefab.Asset.transform.position = position;
			location.m_prefab.Asset.transform.rotation = rotation;
			if (flag)
			{
				component.m_generator.transform.localPosition = localPosition;
				component.m_interiorTransform.localPosition = localPosition2;
				component.m_interiorTransform.localRotation = localRotation;
			}
		}
		location.m_prefab.Release();
		SnapToGround.SnappAll();
		return gameObject;
	}

	private void CreateLocationProxy(ZoneLocation location, int seed, Vector3 pos, Quaternion rotation, SpawnMode mode, List<GameObject> spawnedGhostObjects)
	{
		if (mode == SpawnMode.Ghost)
		{
			ZNetView.StartGhostInit();
		}
		GameObject gameObject = UnityEngine.Object.Instantiate(m_locationProxyPrefab, pos, rotation);
		LocationProxy component = gameObject.GetComponent<LocationProxy>();
		bool spawnNow = mode == SpawnMode.Full;
		component.SetLocation(location.m_prefab.Name, seed, spawnNow);
		if (mode == SpawnMode.Ghost)
		{
			spawnedGhostObjects.Add(gameObject);
			ZNetView.FinishGhostInit();
		}
	}

	private void RegisterLocation(ZoneLocation location, Vector3 pos, bool generated)
	{
		LocationInstance value = new LocationInstance
		{
			m_location = location,
			m_position = pos,
			m_placed = generated
		};
		Vector2i zone = GetZone(pos);
		if (m_locationInstances.ContainsKey(zone))
		{
			Vector2i vector2i = zone;
			ZLog.LogWarning("Location already exist in zone " + vector2i.ToString());
		}
		else
		{
			m_locationInstances.Add(zone, value);
		}
	}

	private bool HaveLocationInRange(string prefabName, string group, Vector3 p, float radius, bool maxGroup = false)
	{
		foreach (LocationInstance value in m_locationInstances.Values)
		{
			if ((value.m_location.m_prefab.Name == prefabName || (!maxGroup && group.Length > 0 && group == value.m_location.m_group) || (maxGroup && group.Length > 0 && group == value.m_location.m_groupMax)) && Vector3.Distance(value.m_position, p) < radius)
			{
				return true;
			}
		}
		return false;
	}

	public bool GetLocationIcon(string name, out Vector3 pos)
	{
		if (ZNet.instance.IsServer())
		{
			foreach (KeyValuePair<Vector2i, LocationInstance> locationInstance in m_locationInstances)
			{
				if ((locationInstance.Value.m_location.m_iconAlways || (locationInstance.Value.m_location.m_iconPlaced && locationInstance.Value.m_placed)) && locationInstance.Value.m_location.m_prefab.Name == name)
				{
					pos = locationInstance.Value.m_position;
					return true;
				}
			}
		}
		else
		{
			foreach (KeyValuePair<Vector3, string> locationIcon in m_locationIcons)
			{
				if (locationIcon.Value == name)
				{
					pos = locationIcon.Key;
					return true;
				}
			}
		}
		pos = Vector3.zero;
		return false;
	}

	public void GetLocationIcons(Dictionary<Vector3, string> icons)
	{
		if (ZNet.instance.IsServer())
		{
			foreach (LocationInstance value in m_locationInstances.Values)
			{
				if (value.m_location.m_iconAlways || (value.m_location.m_iconPlaced && value.m_placed))
				{
					icons[value.m_position] = value.m_location.m_prefab.Name;
				}
			}
			return;
		}
		foreach (KeyValuePair<Vector3, string> locationIcon in m_locationIcons)
		{
			icons.Add(locationIcon.Key, locationIcon.Value);
		}
	}

	private void GetTerrainDelta(Vector3 center, float radius, out float delta, out Vector3 slopeDirection)
	{
		int num = 10;
		float num2 = -999999f;
		float num3 = 999999f;
		Vector3 vector = center;
		Vector3 vector2 = center;
		for (int i = 0; i < num; i++)
		{
			Vector2 vector3 = UnityEngine.Random.insideUnitCircle * radius;
			Vector3 vector4 = center + new Vector3(vector3.x, 0f, vector3.y);
			float groundHeight = GetGroundHeight(vector4);
			if (groundHeight < num3)
			{
				num3 = groundHeight;
				vector2 = vector4;
			}
			if (groundHeight > num2)
			{
				num2 = groundHeight;
				vector = vector4;
			}
		}
		delta = num2 - num3;
		slopeDirection = Vector3.Normalize(vector2 - vector);
	}

	public bool IsBlocked(Vector3 p)
	{
		p.y += 2000f;
		if (Physics.Raycast(p, Vector3.down, 10000f, m_blockRayMask))
		{
			return true;
		}
		return false;
	}

	public float GetGroundHeight(Vector3 p)
	{
		Vector3 origin = p;
		origin.y = 6000f;
		if (Physics.Raycast(origin, Vector3.down, out var hitInfo, 10000f, m_terrainRayMask))
		{
			return hitInfo.point.y;
		}
		return p.y;
	}

	public bool GetGroundHeight(Vector3 p, out float height)
	{
		p.y = 6000f;
		if (Physics.Raycast(p, Vector3.down, out var hitInfo, 10000f, m_terrainRayMask))
		{
			height = hitInfo.point.y;
			return true;
		}
		height = 0f;
		return false;
	}

	public float GetSolidHeight(Vector3 p)
	{
		Vector3 origin = p;
		origin.y += 1000f;
		if (Physics.Raycast(origin, Vector3.down, out var hitInfo, 2000f, m_solidRayMask))
		{
			return hitInfo.point.y;
		}
		return p.y;
	}

	public bool GetSolidHeight(Vector3 p, out float height, int heightMargin = 1000)
	{
		p.y += heightMargin;
		if (Physics.Raycast(p, Vector3.down, out var hitInfo, 2000f, m_solidRayMask) && !hitInfo.collider.attachedRigidbody)
		{
			height = hitInfo.point.y;
			return true;
		}
		height = 0f;
		return false;
	}

	public bool GetSolidHeight(Vector3 p, float radius, out float height, Transform ignore)
	{
		height = p.y - 1000f;
		p.y += 1000f;
		int num = ((!(radius <= 0f)) ? Physics.SphereCastNonAlloc(p, radius, Vector3.down, rayHits, 2000f, m_solidRayMask) : Physics.RaycastNonAlloc(p, Vector3.down, rayHits, 2000f, m_solidRayMask));
		s_rayHits.Clear();
		s_rayHitsHeight.Clear();
		for (int i = 0; i < num; i++)
		{
			RaycastHit item = rayHits[i];
			float y = item.point.y;
			Utils.InsertSortNoAlloc(s_rayHits, item, s_rayHitsHeight, y);
		}
		for (int num2 = s_rayHits.Count - 1; num2 >= 0; num2--)
		{
			RaycastHit raycastHit = rayHits[num2];
			Collider collider = raycastHit.collider;
			if (!(collider.attachedRigidbody != null) && (!(ignore != null) || !Utils.IsParent(collider.transform, ignore)))
			{
				height = Mathf.Max(height, s_rayHitsHeight[num2]);
				return true;
			}
		}
		return false;
	}

	public bool GetSolidHeight(Vector3 p, out float height, out Vector3 normal, out GameObject go)
	{
		p.y += 1000f;
		if (Physics.Raycast(p, Vector3.down, out var hitInfo, 2000f, m_solidRayMask) && !hitInfo.collider.attachedRigidbody)
		{
			height = hitInfo.point.y;
			normal = hitInfo.normal;
			go = hitInfo.collider.gameObject;
			return true;
		}
		height = 0f;
		normal = Vector3.zero;
		go = null;
		return false;
	}

	public bool GetStaticSolidHeight(Vector3 p, out float height, out Vector3 normal)
	{
		p.y += 1000f;
		if (Physics.Raycast(p, Vector3.down, out var hitInfo, 2000f, m_staticSolidRayMask) && !hitInfo.collider.attachedRigidbody)
		{
			height = hitInfo.point.y;
			normal = hitInfo.normal;
			return true;
		}
		height = 0f;
		normal = Vector3.zero;
		return false;
	}

	public bool FindFloor(Vector3 p, out float height)
	{
		if (Physics.Raycast(p + Vector3.up * 1f, Vector3.down, out var hitInfo, 1000f, m_solidRayMask))
		{
			height = hitInfo.point.y;
			return true;
		}
		height = 0f;
		return false;
	}

	public float GetGroundOffset(Vector3 position)
	{
		GetGroundData(ref position, out var _, out var _, out var _, out var hmap);
		if ((bool)hmap)
		{
			return hmap.GetHeightOffset(position);
		}
		return 0f;
	}

	public static bool IsLavaPreHeightmap(Vector3 position, float lavaValue = 0.6f)
	{
		if (WorldGenerator.instance.GetBiome(position.x, position.z) != Heightmap.Biome.AshLands)
		{
			return false;
		}
		WorldGenerator.instance.GetBiomeHeight(Heightmap.Biome.AshLands, position.x, position.z, out var mask);
		return mask.a > lavaValue;
	}

	public bool IsLava(Vector3 position, bool defaultTrue = false)
	{
		GetGroundData(ref position, out var _, out var _, out var _, out var hmap);
		if (!hmap)
		{
			return defaultTrue;
		}
		return hmap.IsLava(position);
	}

	public bool IsLava(ref Vector3 position, bool defaultTrue = false)
	{
		GetGroundData(ref position, out var _, out var _, out var _, out var hmap);
		if (!hmap)
		{
			return defaultTrue;
		}
		return hmap.IsLava(position);
	}

	public void GetGroundData(ref Vector3 p, out Vector3 normal, out Heightmap.Biome biome, out Heightmap.BiomeArea biomeArea, out Heightmap hmap)
	{
		biome = Heightmap.Biome.None;
		biomeArea = Heightmap.BiomeArea.Everything;
		hmap = null;
		if (Physics.Raycast(p + Vector3.up * 5000f, Vector3.down, out var hitInfo, 10000f, m_terrainRayMask))
		{
			p.y = hitInfo.point.y;
			normal = hitInfo.normal;
			Heightmap component = hitInfo.collider.GetComponent<Heightmap>();
			if ((bool)component)
			{
				biome = component.GetBiome(hitInfo.point);
				biomeArea = component.GetBiomeArea();
				hmap = component;
			}
		}
		else
		{
			normal = Vector3.up;
		}
	}

	private void UpdateTTL(float dt)
	{
		foreach (KeyValuePair<Vector2i, ZoneData> zone in m_zones)
		{
			zone.Value.m_ttl += dt;
		}
		foreach (KeyValuePair<Vector2i, ZoneData> zone2 in m_zones)
		{
			if (zone2.Value.m_ttl > m_zoneTTL && !ZNetScene.instance.HaveInstanceInSector(zone2.Key))
			{
				UnityEngine.Object.Destroy(zone2.Value.m_root);
				m_zones.Remove(zone2.Key);
				break;
			}
		}
	}

	public bool FindClosestLocation(string name, Vector3 point, out LocationInstance closest)
	{
		float num = 999999f;
		closest = default(LocationInstance);
		bool result = false;
		foreach (LocationInstance value in m_locationInstances.Values)
		{
			float num2 = Vector3.Distance(value.m_position, point);
			if (value.m_location.m_prefab.Name == name && num2 < num)
			{
				num = num2;
				closest = value;
				result = true;
			}
		}
		return result;
	}

	public bool FindLocations(string name, ref List<LocationInstance> locations)
	{
		locations.Clear();
		foreach (LocationInstance value in m_locationInstances.Values)
		{
			if (value.m_location.m_prefab.Name == name)
			{
				locations.Add(value);
			}
		}
		return locations.Count > 0;
	}

	public static Vector2i GetZone(Vector3 point)
	{
		int x = Utils.FloorToInt((float)(((double)point.x + 32.0) / 64.0));
		int y = Utils.FloorToInt((float)(((double)point.z + 32.0) / 64.0));
		return new Vector2i(x, y);
	}

	public static Vector3 GetZonePos(Vector2i id)
	{
		return new Vector3((float)((double)id.x * 64.0), 0f, (float)((double)id.y * 64.0));
	}

	private void SetZoneGenerated(Vector2i zoneID)
	{
		m_generatedZones.Add(zoneID);
	}

	private bool IsZoneGenerated(Vector2i zoneID)
	{
		return m_generatedZones.Contains(zoneID);
	}

	public bool IsZoneReadyForType(Vector2i zoneID, ZDO.ObjectType objectType)
	{
		if (m_loadingObjectsInZones.Count <= 0)
		{
			return true;
		}
		if (!m_loadingObjectsInZones.ContainsKey(zoneID))
		{
			return true;
		}
		foreach (ZDO item in m_loadingObjectsInZones[zoneID])
		{
			if ((int)objectType < (int)item.Type)
			{
				return false;
			}
		}
		return true;
	}

	public void SetLoadingInZone(ZDO zdo)
	{
		Vector2i sector = zdo.GetSector();
		if (m_loadingObjectsInZones.ContainsKey(sector))
		{
			m_loadingObjectsInZones[sector].Add(zdo);
			return;
		}
		List<ZDO> list = new List<ZDO>();
		list.Add(zdo);
		m_loadingObjectsInZones.Add(sector, list);
	}

	public void UnsetLoadingInZone(ZDO zdo)
	{
		Vector2i sector = zdo.GetSector();
		m_loadingObjectsInZones[sector].Remove(zdo);
		if (m_loadingObjectsInZones[sector].Count <= 0)
		{
			m_loadingObjectsInZones.Remove(sector);
		}
	}

	public bool SkipSaving()
	{
		if (!m_error)
		{
			return m_didZoneTest;
		}
		return true;
	}

	public float TimeSinceStart()
	{
		return m_lastFixedTime - m_startTime;
	}

	public void ResetGlobalKeys()
	{
		ClearGlobalKeys();
		SetStartingGlobalKeys(send: false);
		SendGlobalKeys(ZRoutedRpc.Everybody);
	}

	public void ResetWorldKeys()
	{
		for (int i = 0; i < 32; i++)
		{
			GlobalKeys globalKeys = (GlobalKeys)i;
			RemoveGlobalKey(globalKeys.ToString());
		}
	}

	public void SetStartingGlobalKeys(bool send = true)
	{
		for (int i = 0; i < 32; i++)
		{
			GlobalKeys globalKeys = (GlobalKeys)i;
			GlobalKeyRemove(globalKeys.ToString(), canSaveToServerOptionKeys: false);
		}
		string text = null;
		m_tempKeys.Clear();
		m_tempKeys.AddRange(ZNet.World.m_startingGlobalKeys);
		foreach (string tempKey in m_tempKeys)
		{
			GetKeyValue(tempKey.ToLower(), out var value, out var gk);
			if (gk == GlobalKeys.Preset)
			{
				text = value;
			}
			GlobalKeyAdd(tempKey, canSaveToServerOptionKeys: false);
		}
		if (text != null)
		{
			ServerOptionsGUI.m_instance.SetPreset(ZNet.World, text);
		}
		if (send)
		{
			SendGlobalKeys(ZRoutedRpc.Everybody);
		}
	}

	public void SetGlobalKey(GlobalKeys key, float value)
	{
		SetGlobalKey($"{key} {value.ToString(CultureInfo.InvariantCulture)}");
	}

	public void SetGlobalKey(GlobalKeys key)
	{
		SetGlobalKey(key.ToString());
	}

	public void SetGlobalKey(string name)
	{
		ZRoutedRpc.instance.InvokeRoutedRPC("SetGlobalKey", name);
	}

	public bool GetGlobalKey(GlobalKeys key)
	{
		return m_globalKeysEnums.Contains(key);
	}

	public bool GetGlobalKey(GlobalKeys key, out string value)
	{
		return m_globalKeysValues.TryGetValue(key.ToString().ToLower(), out value);
	}

	public bool GetGlobalKey(GlobalKeys key, out float value)
	{
		if (m_globalKeysValues.TryGetValue(key.ToString().ToLower(), out var value2) && float.TryParse(value2, NumberStyles.Any, CultureInfo.InvariantCulture, out value))
		{
			return true;
		}
		value = 0f;
		return false;
	}

	public bool GetGlobalKey(string name)
	{
		string value;
		return GetGlobalKey(name, out value);
	}

	public bool GetGlobalKey(string name, out string value)
	{
		return m_globalKeysValues.TryGetValue(name.ToLower(), out value);
	}

	public bool GetGlobalKeyExact(string fullLine)
	{
		return m_globalKeys.Contains(fullLine);
	}

	public bool CheckKey(string key, GameKeyType type = GameKeyType.Global, bool trueWhenKeySet = true)
	{
		switch (type)
		{
		case GameKeyType.Global:
			return instance.GetGlobalKey(key) == trueWhenKeySet;
		case GameKeyType.Player:
			if ((bool)Player.m_localPlayer)
			{
				return Player.m_localPlayer.HaveUniqueKey(key) == trueWhenKeySet;
			}
			return false;
		default:
			ZLog.LogError("Unknown GameKeyType type");
			return false;
		}
	}

	private void RPC_SetGlobalKey(long sender, string name)
	{
		if (!m_globalKeys.Contains(name))
		{
			GlobalKeyAdd(name);
			SendGlobalKeys(ZRoutedRpc.Everybody);
		}
	}

	public void RemoveGlobalKey(GlobalKeys key)
	{
		RemoveGlobalKey(key.ToString());
	}

	public void RemoveGlobalKey(string name)
	{
		ZRoutedRpc.instance.InvokeRoutedRPC("RemoveGlobalKey", name);
	}

	private void RPC_RemoveGlobalKey(long sender, string name)
	{
		if (GlobalKeyRemove(name))
		{
			SendGlobalKeys(ZRoutedRpc.Everybody);
		}
	}

	public List<string> GetGlobalKeys()
	{
		return new List<string>(m_globalKeys);
	}

	public Dictionary<Vector2i, LocationInstance>.ValueCollection GetLocationList()
	{
		return m_locationInstances.Values;
	}
}
using System;
using System.IO;
using System.Security.Cryptography;
using UnityEngine;

public class ZPackage
{
	private MemoryStream m_stream = new MemoryStream();

	private BinaryWriter m_writer;

	private BinaryReader m_reader;

	public ZPackage()
	{
		m_writer = new BinaryWriter(m_stream);
		m_reader = new BinaryReader(m_stream);
	}

	public ZPackage(string base64String)
	{
		m_writer = new BinaryWriter(m_stream);
		m_reader = new BinaryReader(m_stream);
		if (!string.IsNullOrEmpty(base64String))
		{
			byte[] array = Convert.FromBase64String(base64String);
			m_stream.Write(array, 0, array.Length);
			m_stream.Position = 0L;
		}
	}

	public ZPackage(byte[] data)
	{
		m_writer = new BinaryWriter(m_stream);
		m_reader = new BinaryReader(m_stream);
		m_stream.Write(data, 0, data.Length);
		m_stream.Position = 0L;
	}

	public ZPackage(byte[] data, int dataSize)
	{
		m_writer = new BinaryWriter(m_stream);
		m_reader = new BinaryReader(m_stream);
		m_stream.Write(data, 0, dataSize);
		m_stream.Position = 0L;
	}

	public void SetReader(BinaryReader reader)
	{
		m_reader = reader;
	}

	public void SetWriter(BinaryWriter writer)
	{
		m_writer = writer;
	}

	public void Load(byte[] data)
	{
		Clear();
		m_stream.Write(data, 0, data.Length);
		m_stream.Position = 0L;
	}

	public void Write(ZPackage pkg)
	{
		byte[] array = pkg.GetArray();
		m_writer.Write(array.Length);
		m_writer.Write(array);
	}

	public void WriteCompressed(ZPackage pkg)
	{
		byte[] array = Utils.Compress(pkg.GetArray());
		m_writer.Write(array.Length);
		m_writer.Write(array);
	}

	public void Write(byte[] array)
	{
		m_writer.Write(array.Length);
		m_writer.Write(array);
	}

	public void Write(byte data)
	{
		m_writer.Write(data);
	}

	public void Write(sbyte data)
	{
		m_writer.Write(data);
	}

	public void Write(char data)
	{
		m_writer.Write(data);
	}

	public void Write(bool data)
	{
		m_writer.Write(data);
	}

	public void Write(int data)
	{
		m_writer.Write(data);
	}

	public void Write(uint data)
	{
		m_writer.Write(data);
	}

	public void Write(short data)
	{
		m_writer.Write(data);
	}

	public void Write(ushort data)
	{
		m_writer.Write(data);
	}

	public void Write(long data)
	{
		m_writer.Write(data);
	}

	public void Write(ulong data)
	{
		m_writer.Write(data);
	}

	public void Write(float data)
	{
		m_writer.Write(data);
	}

	public void Write(double data)
	{
		m_writer.Write(data);
	}

	public void Write(string data)
	{
		m_writer.Write(data);
	}

	public void Write(ZDOID id)
	{
		m_writer.Write(id.UserID);
		m_writer.Write(id.ID);
	}

	public void Write(Vector3 v3)
	{
		m_writer.Write(v3.x);
		m_writer.Write(v3.y);
		m_writer.Write(v3.z);
	}

	public void Write(Vector2i v2)
	{
		m_writer.Write(v2.x);
		m_writer.Write(v2.y);
	}

	public void Write(Vector2s v2)
	{
		m_writer.Write(v2.x);
		m_writer.Write(v2.y);
	}

	public void Write(Quaternion q)
	{
		m_writer.Write(q.x);
		m_writer.Write(q.y);
		m_writer.Write(q.z);
		m_writer.Write(q.w);
	}

	public void WriteNumItems(int numItems)
	{
		if (numItems < 128)
		{
			m_writer.Write((byte)numItems);
			return;
		}
		m_writer.Write((byte)((numItems >> 8) | 0x80));
		m_writer.Write((byte)numItems);
	}

	public ZDOID ReadZDOID()
	{
		return new ZDOID(m_reader.ReadInt64(), m_reader.ReadUInt32());
	}

	public bool ReadBool()
	{
		return m_reader.ReadBoolean();
	}

	public char ReadChar()
	{
		return m_reader.ReadChar();
	}

	public byte ReadByte()
	{
		return m_reader.ReadByte();
	}

	public int ReadNumItems()
	{
		int num = m_reader.ReadByte();
		if ((num & 0x80) != 0)
		{
			num = ((num & 0x7F) << 8) | m_reader.ReadByte();
		}
		return num;
	}

	public sbyte ReadSByte()
	{
		return m_reader.ReadSByte();
	}

	public short ReadShort()
	{
		return m_reader.ReadInt16();
	}

	public ushort ReadUShort()
	{
		return m_reader.ReadUInt16();
	}

	public int ReadInt()
	{
		return m_reader.ReadInt32();
	}

	public uint ReadUInt()
	{
		return m_reader.ReadUInt32();
	}

	public long ReadLong()
	{
		return m_reader.ReadInt64();
	}

	public ulong ReadULong()
	{
		return m_reader.ReadUInt64();
	}

	public float ReadSingle()
	{
		return m_reader.ReadSingle();
	}

	public double ReadDouble()
	{
		return m_reader.ReadDouble();
	}

	public string ReadString()
	{
		return m_reader.ReadString();
	}

	public Vector3 ReadVector3()
	{
		return new Vector3
		{
			x = m_reader.ReadSingle(),
			y = m_reader.ReadSingle(),
			z = m_reader.ReadSingle()
		};
	}

	public Vector2i ReadVector2i()
	{
		return new Vector2i
		{
			x = m_reader.ReadInt32(),
			y = m_reader.ReadInt32()
		};
	}

	public Vector2s ReadVector2s()
	{
		return new Vector2s
		{
			x = m_reader.ReadInt16(),
			y = m_reader.ReadInt16()
		};
	}

	public Quaternion ReadQuaternion()
	{
		return new Quaternion
		{
			x = m_reader.ReadSingle(),
			y = m_reader.ReadSingle(),
			z = m_reader.ReadSingle(),
			w = m_reader.ReadSingle()
		};
	}

	public ZPackage ReadCompressedPackage()
	{
		int count = m_reader.ReadInt32();
		return new ZPackage(Utils.Decompress(m_reader.ReadBytes(count)));
	}

	public ZPackage ReadPackage()
	{
		int count = m_reader.ReadInt32();
		return new ZPackage(m_reader.ReadBytes(count));
	}

	public void ReadPackage(ref ZPackage pkg)
	{
		int count = m_reader.ReadInt32();
		byte[] array = m_reader.ReadBytes(count);
		pkg.Clear();
		pkg.m_stream.Write(array, 0, array.Length);
		pkg.m_stream.Position = 0L;
	}

	public byte[] ReadByteArray()
	{
		int count = m_reader.ReadInt32();
		return m_reader.ReadBytes(count);
	}

	public byte[] ReadByteArray(int num)
	{
		return m_reader.ReadBytes(num);
	}

	public string GetBase64()
	{
		return Convert.ToBase64String(GetArray());
	}

	public byte[] GetArray()
	{
		m_writer.Flush();
		m_stream.Flush();
		return m_stream.ToArray();
	}

	public void SetPos(int pos)
	{
		m_stream.Position = pos;
	}

	public int GetPos()
	{
		return (int)m_stream.Position;
	}

	public int Size()
	{
		m_writer.Flush();
		m_stream.Flush();
		return (int)m_stream.Length;
	}

	public void Clear()
	{
		m_writer.Flush();
		m_stream.SetLength(0L);
		m_stream.Position = 0L;
	}

	public byte[] GenerateHash()
	{
		byte[] array = GetArray();
		return SHA512.Create().ComputeHash(array);
	}
}
using System;
using System.Collections.Generic;
using PlayFab;
using PlayFab.MultiplayerModels;
using Splatform;

public class ZPlayFabLobbySearch
{
	private delegate void QueueableAPICall();

	private readonly ZPlayFabMatchmakingSuccessCallback m_successAction;

	private readonly ZPlayFabMatchmakingFailedCallback m_failedAction;

	private readonly ZPlayFabMatchmakingNewServersCallback m_newServersAction;

	private readonly ZPlayFabMatchmakingServerSearchDoneCallback m_finishedAction;

	private readonly string[] m_searchFilters;

	private readonly bool m_joinLobby;

	private readonly bool m_verboseLog;

	private int m_retries;

	private float m_retryIn = -1f;

	private int m_currentPage;

	private int m_currentFilter;

	private const float rateLimit = 2f;

	private DateTime m_previousAPICallTime = DateTime.MinValue;

	private Queue<QueueableAPICall> m_APICallQueue = new Queue<QueueableAPICall>();

	internal bool IsDone { get; private set; }

	internal ZPlayFabLobbySearch(ZPlayFabMatchmakingNewServersCallback newServersAction, ZPlayFabMatchmakingServerSearchDoneCallback finishedAction, string[] searchFilters)
	{
		m_newServersAction = newServersAction;
		m_finishedAction = finishedAction;
		m_searchFilters = searchFilters;
		m_joinLobby = false;
	}

	internal ZPlayFabLobbySearch(ZPlayFabMatchmakingSuccessCallback successAction, ZPlayFabMatchmakingFailedCallback failedAction, string searchFilter, ZPlayFabLobbySearchFlags flags)
	{
		m_successAction = successAction;
		m_failedAction = failedAction;
		m_searchFilters = new string[1] { searchFilter };
		m_joinLobby = flags.HasFlag(ZPlayFabLobbySearchFlags.Join);
		if (!flags.HasFlag(ZPlayFabLobbySearchFlags.Queued))
		{
			FindLobby();
		}
		if (flags.HasFlag(ZPlayFabLobbySearchFlags.AllowRetry))
		{
			m_retries = 3;
		}
	}

	internal void Update(float deltaTime)
	{
		if (m_retryIn > 0f)
		{
			m_retryIn -= deltaTime;
			if (m_retryIn <= 0f)
			{
				FindLobby();
			}
		}
		TickAPICallRateLimiter();
	}

	internal void FindLobby()
	{
		if (m_newServersAction == null)
		{
			FindLobbiesRequest request = new FindLobbiesRequest
			{
				Filter = m_searchFilters[m_currentFilter]
			};
			QueueAPICall(delegate
			{
				PlayFabMultiplayerAPI.FindLobbies(request, OnFindLobbySuccess, OnFindLobbyFailed);
			});
		}
		else
		{
			FindLobbyWithPagination();
		}
	}

	private void FindLobbyWithPagination()
	{
		FindLobbiesRequest request = new FindLobbiesRequest
		{
			Filter = m_searchFilters[m_currentFilter] + string.Format(" and {0} eq {1}", "number_key11", m_currentPage),
			Pagination = new PaginationRequest
			{
				PageSizeRequested = 50u
			}
		};
		if (m_verboseLog)
		{
			ZLog.Log($"Page {m_currentPage}, {4 - m_currentPage - 1} remains: {request.Filter}");
		}
		QueueAPICall(delegate
		{
			PlayFabMultiplayerAPI.FindLobbies(request, OnFindServersSuccess, OnFindLobbyFailed);
		});
	}

	private void RetryOrFail(string error)
	{
		if (m_retries > 0)
		{
			m_retries--;
			m_retryIn = 1f;
		}
		else
		{
			ZLog.Log($"PlayFab lobby matching search filter '{m_searchFilters[m_currentFilter]}': {error}");
			OnFailed(ZPLayFabMatchmakingFailReason.Unknown);
		}
	}

	private void OnFindLobbyFailed(PlayFabError error)
	{
		if (!IsDone)
		{
			RetryOrFail(error.ToString());
		}
	}

	private void OnFindLobbySuccess(FindLobbiesResult result)
	{
		if (IsDone)
		{
			return;
		}
		if (result.Lobbies.Count == 0)
		{
			RetryOrFail("Got back zero lobbies");
			return;
		}
		LobbySummary lobbySummary = result.Lobbies[0];
		if (result.Lobbies.Count > 1)
		{
			ZLog.LogWarning($"Expected zero or one lobby got {result.Lobbies.Count} matching lobbies, returning newest lobby");
			long num = long.Parse(lobbySummary.SearchData["string_key9"]);
			foreach (LobbySummary lobby in result.Lobbies)
			{
				long num2 = long.Parse(lobby.SearchData["string_key9"]);
				if (num < num2)
				{
					lobbySummary = lobby;
					num = num2;
				}
			}
		}
		if (m_joinLobby)
		{
			JoinLobby(lobbySummary.LobbyId, lobbySummary.ConnectionString);
			ZPlayFabMatchmaking.JoinCode = lobbySummary.SearchData["string_key4"];
		}
		else
		{
			DeliverLobby(lobbySummary);
			IsDone = true;
		}
	}

	private void JoinLobby(string lobbyId, string connectionString)
	{
		JoinLobbyRequest request = new JoinLobbyRequest
		{
			ConnectionString = connectionString,
			MemberEntity = ZPlayFabMatchmaking.GetEntityKeyForLocalUser()
		};
		QueueAPICall(delegate
		{
			PlayFabMultiplayerAPI.JoinLobby(request, delegate(JoinLobbyResult result)
			{
				OnJoinLobbySuccess(result.LobbyId);
			}, delegate(PlayFabError error)
			{
				OnJoinLobbyFailed(error, lobbyId);
			});
		});
	}

	private void OnJoinLobbySuccess(string lobbyId)
	{
		if (!IsDone)
		{
			GetLobbyRequest request = new GetLobbyRequest
			{
				LobbyId = lobbyId
			};
			QueueAPICall(delegate
			{
				PlayFabMultiplayerAPI.GetLobby(request, OnGetLobbySuccess, OnGetLobbyFailed);
			});
		}
	}

	private void OnJoinLobbyFailed(PlayFabError error, string lobbyId)
	{
		switch (error.Error)
		{
		case PlayFabErrorCode.LobbyPlayerAlreadyJoined:
			OnJoinLobbySuccess(lobbyId);
			break;
		case PlayFabErrorCode.LobbyNotJoinable:
			ZLog.Log("Can't join lobby because it's not joinable, likely because it's full.");
			OnFailed(ZPLayFabMatchmakingFailReason.ServerFull);
			break;
		case PlayFabErrorCode.APIRequestLimitExceeded:
		case PlayFabErrorCode.APIClientRequestRateLimitExceeded:
		case PlayFabErrorCode.LobbyPlayerMaxLobbyLimitExceeded:
			OnFailed(ZPLayFabMatchmakingFailReason.APIRequestLimitExceeded);
			break;
		default:
			ZLog.LogError("Failed to get lobby: " + error.ToString());
			OnFailed(ZPLayFabMatchmakingFailReason.Unknown);
			break;
		}
	}

	private void DeliverLobby(LobbySummary lobbySummary)
	{
		PlayFabMatchmakingServerData playFabMatchmakingServerData = ToServerData(lobbySummary.LobbyId, lobbySummary.CurrentPlayers, lobbySummary.MaxPlayers, lobbySummary.SearchData, null, subtractOneFromPlayerCountIfDedicated: true);
		if (m_verboseLog && playFabMatchmakingServerData != null)
		{
			ZLog.Log("Deliver server data\n" + playFabMatchmakingServerData.ToString());
		}
		m_successAction(playFabMatchmakingServerData);
	}

	private void DeliverLobbies(IReadOnlyList<LobbySummary> lobbySummaies)
	{
		PlayFabMatchmakingServerData[] array = new PlayFabMatchmakingServerData[lobbySummaies.Count];
		for (int i = 0; i < lobbySummaies.Count; i++)
		{
			LobbySummary lobbySummary = lobbySummaies[i];
			PlayFabMatchmakingServerData playFabMatchmakingServerData = ToServerData(lobbySummary.LobbyId, lobbySummary.CurrentPlayers, lobbySummary.MaxPlayers, lobbySummary.SearchData, null, subtractOneFromPlayerCountIfDedicated: true);
			if (m_verboseLog && playFabMatchmakingServerData != null)
			{
				ZLog.Log("Deliver server data\n" + playFabMatchmakingServerData.ToString());
			}
			array[i] = playFabMatchmakingServerData;
		}
		m_newServersAction(array);
	}

	private void OnFindServersSuccess(FindLobbiesResult result)
	{
		if (IsDone)
		{
			return;
		}
		DeliverLobbies(result.Lobbies);
		m_currentPage++;
		if (m_currentPage >= 4)
		{
			m_currentFilter++;
			if (m_currentFilter >= m_searchFilters.Length)
			{
				OnFinished(ZPLayFabMatchmakingFailReason.None);
				return;
			}
			m_currentPage = 0;
		}
		FindLobbyWithPagination();
	}

	private void OnGetLobbySuccess(GetLobbyResult result)
	{
		PlayFabMatchmakingServerData playFabMatchmakingServerData = ToServerData(result);
		if (IsDone)
		{
			OnFailed(ZPLayFabMatchmakingFailReason.Cancelled);
			return;
		}
		if (playFabMatchmakingServerData == null)
		{
			OnFailed(ZPLayFabMatchmakingFailReason.InvalidServerData);
			return;
		}
		IsDone = true;
		ZLog.Log("Get Lobby\n" + playFabMatchmakingServerData.ToString());
		m_successAction(playFabMatchmakingServerData);
	}

	private void OnGetLobbyFailed(PlayFabError error)
	{
		ZLog.LogError("Failed to get lobby: " + error.ToString());
		OnFailed(ZPLayFabMatchmakingFailReason.Unknown);
	}

	private static PlayFabMatchmakingServerData ToServerData(string lobbyID, uint playerCount, uint maxPlayerCount, Dictionary<string, string> searchData, Dictionary<string, string> lobbyData = null, bool subtractOneFromPlayerCountIfDedicated = false)
	{
		try
		{
			if (!bool.TryParse(searchData["string_key3"], out var result) || !bool.TryParse(searchData["string_key7"], out var result2) || !long.TryParse(searchData["string_key9"], out var result3))
			{
				ZLog.LogWarning("Got PlayFab lobby entry with invalid data");
				return null;
			}
			string versionString = searchData["string_key6"];
			uint num = uint.Parse(searchData["number_key13"]);
			if (!GameVersion.TryParseGameVersion(versionString, out var version) || version < Version.FirstVersionWithNetworkVersion)
			{
				num = 0u;
			}
			if (num != 36 || !searchData.TryGetValue("string_key14", out var value) || !StringUtils.TryDecodeStringAsIDictionary<Dictionary<string, string>>(value, out var decodedDictionary) || !ServerOptionsGUI.TryConvertCompactKVPToModifierKeys(decodedDictionary, out var result4))
			{
				result4 = new string[0];
			}
			if (!PlatformUserID.TryParse(searchData["string_key8"], out var platform))
			{
				platform = PlatformUserID.None;
			}
			PlayFabMatchmakingServerData playFabMatchmakingServerData = new PlayFabMatchmakingServerData
			{
				isCommunityServer = result,
				isDedicatedServer = result2,
				joinCode = searchData["string_key4"],
				lobbyId = lobbyID,
				numPlayers = ((result2 && subtractOneFromPlayerCountIfDedicated) ? (playerCount - 1) : playerCount),
				maxNumPlayers = ((result2 && subtractOneFromPlayerCountIfDedicated) ? (maxPlayerCount - 1) : maxPlayerCount),
				remotePlayerId = searchData["string_key1"],
				serverIp = searchData["string_key10"],
				serverName = searchData["string_key5"],
				tickCreated = result3,
				gameVersion = version,
				modifiers = result4,
				networkVersion = num,
				platformUserID = platform,
				platformRestriction = new Platform((searchData["string_key12"] == "None") ? null : searchData["string_key12"])
			};
			if (lobbyData != null)
			{
				playFabMatchmakingServerData.havePassword = bool.Parse(lobbyData[PlayFabAttrKey.HavePassword.ToKeyString()]);
				playFabMatchmakingServerData.networkId = lobbyData[PlayFabAttrKey.NetworkId.ToKeyString()];
				playFabMatchmakingServerData.worldName = lobbyData[PlayFabAttrKey.WorldName.ToKeyString()];
			}
			return playFabMatchmakingServerData;
		}
		catch (KeyNotFoundException)
		{
			ZLog.LogWarning("Got PlayFab lobby entry with missing key(s)");
			return null;
		}
		catch
		{
			return null;
		}
	}

	private static PlayFabMatchmakingServerData ToServerData(GetLobbyResult result)
	{
		return ToServerData(result.Lobby.LobbyId, (uint)result.Lobby.Members.Count, result.Lobby.MaxPlayers, result.Lobby.SearchData, result.Lobby.LobbyData);
	}

	private void OnFailed(ZPLayFabMatchmakingFailReason failReason)
	{
		if (!IsDone)
		{
			IsDone = true;
			if (m_failedAction != null)
			{
				m_failedAction(failReason);
			}
		}
	}

	private void OnFinished(ZPLayFabMatchmakingFailReason failReason)
	{
		if (!IsDone)
		{
			IsDone = true;
			if (m_finishedAction != null)
			{
				m_finishedAction(failReason);
			}
		}
	}

	public void Cancel()
	{
		IsDone = true;
	}

	private void QueueAPICall(QueueableAPICall apiCallDelegate)
	{
		m_APICallQueue.Enqueue(apiCallDelegate);
		TickAPICallRateLimiter();
	}

	private void TickAPICallRateLimiter()
	{
		if (m_APICallQueue.Count > 0 && (DateTime.UtcNow - m_previousAPICallTime).TotalSeconds >= 2.0)
		{
			m_APICallQueue.Dequeue()();
			m_previousAPICallTime = DateTime.UtcNow;
		}
	}
}
using System;

[Flags]
public enum ZPlayFabLobbySearchFlags
{
	None = 0,
	Join = 1,
	Queued = 2,
	AllowRetry = 4
}
public delegate void ZPlayFabMatchmakeLobbyLeftCallback(bool success);
using System;
using System.Collections.Generic;
using System.Threading;
using NetworkingUtils;
using PartyCSharpSDK;
using PlayFab;
using PlayFab.ClientModels;
using PlayFab.MultiplayerModels;
using PlayFab.Party;
using Splatform;
using UnityEngine;

public class ZPlayFabMatchmaking
{
	private enum State
	{
		Uninitialized,
		Creating,
		RegenerateJoinCode,
		Active
	}

	private static ZPlayFabMatchmaking m_instance;

	private static string m_publicIP = "";

	private static readonly object m_mtx = new object();

	private static Thread m_publicIpLookupThread;

	private static int m_getPublicIpAttempts;

	public const uint JoinStringLength = 6u;

	public const uint MaxPlayers = 10u;

	internal const int NumSearchPages = 4;

	public const string RemotePlayerIdSearchKey = "string_key1";

	public const string IsActiveSearchKey = "string_key2";

	public const string IsCommunityServerSearchKey = "string_key3";

	public const string JoinCodeSearchKey = "string_key4";

	public const string ServerNameSearchKey = "string_key5";

	public const string GameVersionSearchKey = "string_key6";

	public const string IsDedicatedServerSearchKey = "string_key7";

	public const string PlatformUserIdSearchKey = "string_key8";

	public const string CreatedSearchKey = "string_key9";

	public const string ServerIpSearchKey = "string_key10";

	public const string PageSearchKey = "number_key11";

	public const string PlatformRestrictionKey = "string_key12";

	public const string NetworkVersionSearchKey = "number_key13";

	public const string ModifiersSearchKey = "string_key14";

	private const int NumStringSearchKeys = 14;

	public const string NoPlatformRestrictionString = "None";

	private State m_state;

	private PlayFabMatchmakingServerData m_serverData;

	private int m_retries;

	private float m_retryIn = -1f;

	private const float LostNetworkRetryDuration = 30f;

	private float m_lostNetworkRetryIn = -1f;

	private bool m_isConnectingToNetwork;

	private bool m_isResettingNetwork;

	private float m_submitBackgroundSearchIn = -1f;

	private int m_serverPort = -1;

	private float m_refreshLobbyTimer;

	private const float RefreshLobbyDurationMin = 540f;

	private const float RefreshLobbyDurationMax = 840f;

	private const float DurationBetwenBackgroundSearches = 2f;

	private readonly List<ZPlayFabLobbySearch> m_activeSearches = new List<ZPlayFabLobbySearch>();

	private readonly Queue<ZPlayFabLobbySearch> m_pendingSearches = new Queue<ZPlayFabLobbySearch>();

	private Action m_pendingRegisterServer;

	public static ZPlayFabMatchmaking instance
	{
		get
		{
			if (m_instance == null)
			{
				m_instance = new ZPlayFabMatchmaking();
			}
			return m_instance;
		}
	}

	public static string JoinCode { get; internal set; }

	public static string PublicIP
	{
		get
		{
			lock (m_mtx)
			{
				return m_publicIP;
			}
		}
		private set
		{
			lock (m_mtx)
			{
				m_publicIP = value;
			}
		}
	}

	public static event ZPlayFabMatchmakeLobbyLeftCallback LobbyLeft;

	public static void Initialize(bool isServer)
	{
		JoinCode = (isServer ? "" : "000000");
	}

	public void Update(float deltaTime)
	{
		if (!ReconnectNetwork(deltaTime))
		{
			RefreshLobby(deltaTime);
			RetryJoinCodeUniquenessCheck(deltaTime);
			UpdateActiveLobbySearches(deltaTime);
			UpdateBackgroundLobbySearches(deltaTime);
		}
	}

	private bool IsJoinedToNetwork()
	{
		if (m_serverData != null)
		{
			return !string.IsNullOrEmpty(m_serverData.networkId);
		}
		return false;
	}

	private bool IsReconnectNetworkTimerActive()
	{
		return m_lostNetworkRetryIn > 0f;
	}

	private void StartReconnectNetworkTimer(int code = -1)
	{
		m_lostNetworkRetryIn = 30f;
		if (DoFastRecovery(code))
		{
			ZLog.Log("PlayFab host fast recovery");
			m_lostNetworkRetryIn = 12f;
		}
	}

	private static bool DoFastRecovery(int code)
	{
		if (code != 63)
		{
			return code == 11;
		}
		return true;
	}

	private void StopReconnectNetworkTimer()
	{
		m_isResettingNetwork = false;
		m_lostNetworkRetryIn = -1f;
		if (m_serverData != null && !IsJoinedToNetwork())
		{
			CreateAndJoinNetwork();
		}
	}

	private bool ReconnectNetwork(float deltaTime)
	{
		if (!IsReconnectNetworkTimerActive())
		{
			if (IsJoinedToNetwork() && !PlayFabMultiplayerManager.Get().IsConnectedToNetworkState())
			{
				PlayFabMultiplayerManager.Get().ResetParty();
				StartReconnectNetworkTimer();
				m_serverData.networkId = null;
			}
			return false;
		}
		m_lostNetworkRetryIn -= deltaTime;
		if (m_lostNetworkRetryIn <= 0f)
		{
			ZLog.Log($"PlayFab reconnect server '{m_serverData.serverName}'");
			m_isConnectingToNetwork = false;
			m_serverData.networkId = null;
			StopReconnectNetworkTimer();
		}
		else if (!m_isConnectingToNetwork && !m_isResettingNetwork && m_lostNetworkRetryIn <= 12f)
		{
			PlayFabMultiplayerManager.Get().ResetParty();
			m_isResettingNetwork = true;
			m_isConnectingToNetwork = false;
		}
		return true;
	}

	private void StartRefreshLobbyTimer()
	{
		m_refreshLobbyTimer = UnityEngine.Random.Range(540f, 840f);
	}

	private void RefreshLobby(float deltaTime)
	{
		if (m_serverData == null || m_serverData.networkId == null)
		{
			return;
		}
		bool flag = m_serverData.isDedicatedServer && string.IsNullOrEmpty(m_serverData.serverIp) && !string.IsNullOrEmpty(PublicIP);
		m_refreshLobbyTimer -= deltaTime;
		if (m_refreshLobbyTimer < 0f || flag)
		{
			StartRefreshLobbyTimer();
			UpdateLobbyRequest updateLobbyRequest = new UpdateLobbyRequest
			{
				LobbyId = m_serverData.lobbyId
			};
			if (flag)
			{
				m_serverData.serverIp = GetServerIPAndPort();
				ZLog.Log("Updating lobby with public IP " + m_serverData.serverIp);
				Dictionary<string, string> searchData = new Dictionary<string, string> { ["string_key10"] = m_serverData.serverIp };
				updateLobbyRequest.SearchData = searchData;
			}
			PlayFabMultiplayerAPI.UpdateLobby(updateLobbyRequest, delegate
			{
				ZLog.Log($"Lobby {m_serverData.lobbyId} for world '{m_serverData.serverName}' and network {m_serverData.networkId} refreshed");
			}, OnRefreshFailed);
		}
	}

	private void OnRefreshFailed(PlayFabError err)
	{
		CreateLobby(refresh: true, delegate
		{
			ZLog.Log($"Lobby {m_serverData.lobbyId} for world '{m_serverData.serverName}' recreated");
		}, delegate(PlayFabError playFabError)
		{
			ZLog.LogWarning($"Failed to refresh lobby {m_serverData.lobbyId} for world '{m_serverData.serverName}': {playFabError.GenerateErrorReport()}");
		});
	}

	private void RetryJoinCodeUniquenessCheck(float deltaTime)
	{
		if (m_retryIn > 0f)
		{
			m_retryIn -= deltaTime;
			if (m_retryIn <= 0f)
			{
				CheckJoinCodeIsUnique();
			}
		}
	}

	private void UpdateActiveLobbySearches(float deltaTime)
	{
		for (int i = 0; i < m_activeSearches.Count; i++)
		{
			ZPlayFabLobbySearch zPlayFabLobbySearch = m_activeSearches[i];
			if (zPlayFabLobbySearch.IsDone)
			{
				m_activeSearches.RemoveAt(i);
				i--;
			}
			else
			{
				zPlayFabLobbySearch.Update(deltaTime);
			}
		}
	}

	private void UpdateBackgroundLobbySearches(float deltaTime)
	{
		if (m_submitBackgroundSearchIn >= 0f)
		{
			m_submitBackgroundSearchIn -= deltaTime;
		}
		else if (m_pendingSearches.Count > 0)
		{
			m_submitBackgroundSearchIn = 2f;
			ZPlayFabLobbySearch zPlayFabLobbySearch = m_pendingSearches.Dequeue();
			zPlayFabLobbySearch.FindLobby();
			m_activeSearches.Add(zPlayFabLobbySearch);
		}
	}

	private void OnFailed(string what, PlayFabError error)
	{
		ZLog.LogError("PlayFab " + what + " failed: " + error.ToString());
		UnregisterServer();
	}

	private void OnSessionUpdated(State newState)
	{
		m_state = newState;
		switch (m_state)
		{
		case State.Creating:
			ZLog.Log($"Session \"{m_serverData.serverName}\" registered with join code {JoinCode}");
			m_retries = 100;
			CheckJoinCodeIsUnique();
			break;
		case State.RegenerateJoinCode:
			RegenerateLobbyJoinCode();
			ZLog.Log($"Created new join code {JoinCode} for session \"{m_serverData.serverName}\"");
			break;
		case State.Active:
			ZLog.Log($"Session \"{m_serverData.serverName}\" with join code {JoinCode} is active with {m_serverData.numPlayers} player(s)");
			break;
		}
	}

	private void SetPlatformMatchmakingData()
	{
		IMatchmakingProvider matchmakingProvider = PlatformManager.DistributionPlatform.MatchmakingProvider;
		if (matchmakingProvider != null)
		{
			MultiplayerSessionData multiplayerSession = new MultiplayerSessionData
			{
				m_connectionString = m_serverData.remotePlayerId,
				m_maxPlayers = 10u,
				m_currentPlayers = m_serverData.numPlayers,
				m_joinRestriction = MultiplayerJoinRestriction.Friends
			};
			matchmakingProvider.SetMultiplayerSession(multiplayerSession);
		}
	}

	private void ClearPlatformMatchmakingData()
	{
		PlatformManager.DistributionPlatform.MatchmakingProvider?.ClearMultiplayerSession();
	}

	private void UpdateNumPlayers(string info)
	{
		m_serverData.numPlayers = ZPlayFabSocket.NumSockets();
		if (!m_serverData.isDedicatedServer)
		{
			m_serverData.numPlayers++;
		}
		ZLog.Log($"{info} server \"{m_serverData.serverName}\" that has join code {JoinCode}, now {m_serverData.numPlayers} player(s)");
	}

	private void OnRemotePlayerLeft(object sender, PlayFabPlayer player)
	{
		if (player == null)
		{
			ZLog.LogWarning("Player that left was null! Ignoring.");
			return;
		}
		ZPlayFabSocket.LostConnection(player);
		UpdateNumPlayers("Player connection lost");
	}

	private void OnRemotePlayerJoined(object sender, PlayFabPlayer player)
	{
		StopReconnectNetworkTimer();
		ZPlayFabSocket.QueueConnection(player);
		UpdateNumPlayers("Player joined");
	}

	private void OnNetworkJoined(object sender, string networkId)
	{
		ZLog.Log($"Joined PlayFab Party network with ID \"{networkId}\"");
		if (m_serverData.networkId == null || m_serverData.networkId != networkId)
		{
			m_serverData.networkId = networkId;
			CreateLobby(refresh: false, OnCreateLobbySuccess, delegate(PlayFabError error)
			{
				OnFailed("create lobby", error);
			});
		}
		m_isConnectingToNetwork = false;
		m_isResettingNetwork = false;
		StopReconnectNetworkTimer();
		StartRefreshLobbyTimer();
	}

	private void CreateLobby(bool refresh, Action<CreateLobbyResult> resultCallback, Action<PlayFabError> errorCallback)
	{
		PlayFab.MultiplayerModels.EntityKey entityKeyForLocalUser = GetEntityKeyForLocalUser();
		List<Member> members = new List<Member>
		{
			new Member
			{
				MemberEntity = entityKeyForLocalUser
			}
		};
		Dictionary<string, string> lobbyData = new Dictionary<string, string>
		{
			[PlayFabAttrKey.HavePassword.ToKeyString()] = m_serverData.havePassword.ToString(),
			[PlayFabAttrKey.WorldName.ToKeyString()] = m_serverData.worldName,
			[PlayFabAttrKey.NetworkId.ToKeyString()] = m_serverData.networkId
		};
		string value = "";
		if (ServerOptionsGUI.TryConvertModifierKeysToCompactKVP<Dictionary<string, string>>(m_serverData.modifiers, out var result))
		{
			value = StringUtils.EncodeDictionaryAsString(result, encloseInQuotes: false);
		}
		Dictionary<string, string> searchData = new Dictionary<string, string>
		{
			["string_key9"] = DateTime.UtcNow.Ticks.ToString(),
			["string_key5"] = m_serverData.serverName,
			["string_key3"] = m_serverData.isCommunityServer.ToString(),
			["string_key4"] = m_serverData.joinCode,
			["string_key2"] = refresh.ToString(),
			["string_key1"] = m_serverData.remotePlayerId,
			["string_key6"] = m_serverData.gameVersion.ToString(),
			["string_key14"] = value,
			["number_key13"] = m_serverData.networkVersion.ToString(),
			["string_key7"] = m_serverData.isDedicatedServer.ToString(),
			["string_key8"] = m_serverData.platformUserID.ToString(),
			["string_key10"] = m_serverData.serverIp,
			["number_key11"] = GetSearchPage().ToString(),
			["string_key12"] = ((PlatformManager.DistributionPlatform.PrivilegeProvider.CheckPrivilege(Privilege.CrossPlatformMultiplayer) == PrivilegeResult.Granted) ? "None" : PlatformManager.DistributionPlatform.Platform.ToString())
		};
		Debug.Log("This is the serverIP used to register the server: " + m_serverData.serverIp);
		CreateLobbyRequest request = new CreateLobbyRequest
		{
			AccessPolicy = AccessPolicy.Public,
			MaxPlayers = 10u,
			Members = members,
			Owner = entityKeyForLocalUser,
			LobbyData = lobbyData,
			SearchData = searchData
		};
		if (m_serverData.isCommunityServer)
		{
			AddNameSearchFilter(searchData, m_serverData.serverName);
		}
		PlayFabMultiplayerAPI.CreateLobby(request, resultCallback, errorCallback);
	}

	private static int GetSearchPage()
	{
		return UnityEngine.Random.Range(0, 4);
	}

	internal static PlayFab.MultiplayerModels.EntityKey GetEntityKeyForLocalUser()
	{
		PlayFab.ClientModels.EntityKey entity = PlayFabManager.instance.Entity;
		return new PlayFab.MultiplayerModels.EntityKey
		{
			Id = entity.Id,
			Type = entity.Type
		};
	}

	private void OnCreateLobbySuccess(CreateLobbyResult result)
	{
		ZLog.Log($"Created PlayFab lobby with ID \"{result.LobbyId}\", ConnectionString \"{result.ConnectionString}\" and owned by \"{m_serverData.remotePlayerId}\"");
		m_serverData.lobbyId = result.LobbyId;
		OnSessionUpdated(State.Creating);
	}

	private void GenerateJoinCode()
	{
		JoinCode = UnityEngine.Random.Range(0, (int)Math.Pow(10.0, 6.0)).ToString("D" + 6u);
		m_serverData.joinCode = JoinCode;
	}

	private void RegenerateLobbyJoinCode()
	{
		GenerateJoinCode();
		PlayFabMultiplayerAPI.UpdateLobby(new UpdateLobbyRequest
		{
			LobbyId = m_serverData.lobbyId,
			SearchData = new Dictionary<string, string> { ["string_key4"] = JoinCode }
		}, OnSetLobbyJoinCodeSuccess, delegate(PlayFabError error)
		{
			OnFailed("set lobby join-code", error);
		});
	}

	private void OnSetLobbyJoinCodeSuccess(LobbyEmptyResult _)
	{
		CheckJoinCodeIsUnique();
	}

	private void CheckJoinCodeIsUnique()
	{
		PlayFabMultiplayerAPI.FindLobbies(new FindLobbiesRequest
		{
			Filter = string.Format("{0} eq '{1}'", "string_key4", JoinCode)
		}, OnCheckJoinCodeSuccess, delegate(PlayFabError error)
		{
			OnFailed("find lobbies", error);
		});
	}

	private void ScheduleJoinCodeCheck()
	{
		m_retryIn = 1f;
	}

	private void OnCheckJoinCodeSuccess(FindLobbiesResult result)
	{
		if (result.Lobbies.Count == 0)
		{
			if (m_retries > 0)
			{
				m_retries--;
				ZLog.Log("Retry join-code check " + m_retries);
				ScheduleJoinCodeCheck();
			}
			else
			{
				ZLog.LogWarning("Zero lobbies returned, should be at least one");
				UnregisterServer();
			}
		}
		else if (result.Lobbies.Count == 1 && result.Lobbies[0].Owner.Id == GetEntityKeyForLocalUser().Id)
		{
			ActivateSession();
		}
		else
		{
			OnSessionUpdated(State.RegenerateJoinCode);
		}
	}

	private void ActivateSession()
	{
		PlayFabMultiplayerAPI.UpdateLobby(new UpdateLobbyRequest
		{
			LobbyId = m_serverData.lobbyId,
			SearchData = new Dictionary<string, string> { ["string_key2"] = true.ToString() }
		}, OnActivateLobbySuccess, delegate(PlayFabError error)
		{
			OnFailed("activate lobby", error);
		});
		SetPlatformMatchmakingData();
	}

	private void OnActivateLobbySuccess(LobbyEmptyResult _)
	{
		OnSessionUpdated(State.Active);
	}

	public void RegisterServer(string name, bool havePassword, bool isCommunityServer, GameVersion gameVersion, string[] modifiers, uint networkVersion, string worldName, bool needServerAccount = true)
	{
		bool flag = false;
		if (!PlayFabMultiplayerAPI.IsEntityLoggedIn())
		{
			ZLog.LogWarning("Calling ZPlayFabMatchmaking.RegisterServer() without logged in user");
			m_pendingRegisterServer = delegate
			{
				RegisterServer(name, havePassword, isCommunityServer, gameVersion, modifiers, networkVersion, worldName, needServerAccount);
			};
			return;
		}
		m_serverData = new PlayFabMatchmakingServerData
		{
			havePassword = havePassword,
			isCommunityServer = isCommunityServer,
			isDedicatedServer = flag,
			remotePlayerId = PlayFabManager.instance.Entity.Id,
			serverName = name,
			gameVersion = gameVersion,
			modifiers = modifiers,
			networkVersion = networkVersion,
			worldName = worldName
		};
		m_serverData.serverIp = GetServerIPAndPort();
		UpdateNumPlayers("New session");
		ZLog.Log(string.Format("Register PlayFab server \"{0}\"{1}", name, flag ? (" with IP " + m_serverData.serverIp) : ""));
		m_serverData.platformUserID = PlatformManager.DistributionPlatform.LocalUser.PlatformUserID;
		GenerateJoinCode();
		CreateAndJoinNetwork();
		PlayFabMultiplayerManager playFabMultiplayerManager = PlayFabMultiplayerManager.Get();
		playFabMultiplayerManager.OnNetworkJoined -= OnNetworkJoined;
		playFabMultiplayerManager.OnNetworkJoined += OnNetworkJoined;
		playFabMultiplayerManager.OnNetworkChanged -= OnNetworkChanged;
		playFabMultiplayerManager.OnNetworkChanged += OnNetworkChanged;
		playFabMultiplayerManager.OnError -= OnNetworkError;
		playFabMultiplayerManager.OnError += OnNetworkError;
		playFabMultiplayerManager.OnRemotePlayerJoined -= OnRemotePlayerJoined;
		playFabMultiplayerManager.OnRemotePlayerJoined += OnRemotePlayerJoined;
		playFabMultiplayerManager.OnRemotePlayerLeft -= OnRemotePlayerLeft;
		playFabMultiplayerManager.OnRemotePlayerLeft += OnRemotePlayerLeft;
	}

	private string GetServerIPAndPort()
	{
		if (!m_serverData.isDedicatedServer || string.IsNullOrEmpty(PublicIP))
		{
			return "";
		}
		if (PublicIP.Contains(":"))
		{
			Debug.Log($"Likely an IPV6 address, returning [{PublicIP}]:{m_serverPort}");
			return $"[{PublicIP}]:{m_serverPort}";
		}
		Debug.Log($"IPv4, returning {PublicIP}:{m_serverPort}");
		return $"{PublicIP}:{m_serverPort}";
	}

	private bool IsIPv6(string address)
	{
		return true;
	}

	public static void LookupPublicIP()
	{
		if (string.IsNullOrEmpty(PublicIP) && m_publicIpLookupThread == null)
		{
			m_publicIpLookupThread = new Thread(BackgroundLookupPublicIP);
			m_publicIpLookupThread.Name = "PlayfabLooupThread";
			m_publicIpLookupThread.Start();
		}
	}

	private static void BackgroundLookupPublicIP(object obj)
	{
		while (string.IsNullOrEmpty(PublicIP))
		{
			PublicIP = ZNet.GetPublicIP(m_getPublicIpAttempts++);
			Thread.Sleep(10);
		}
	}

	private void CreateAndJoinNetwork()
	{
		PlayFabNetworkConfiguration networkConfiguration = new PlayFabNetworkConfiguration
		{
			MaxPlayerCount = 10u,
			DirectPeerConnectivityOptions = (PARTY_DIRECT_PEER_CONNECTIVITY_OPTIONS)15u
		};
		ZLog.Log($"Server '{m_serverData.serverName}' begin PlayFab create and join network for server ");
		PlayFabMultiplayerManager.Get().CreateAndJoinNetwork(networkConfiguration);
		m_isConnectingToNetwork = true;
		StartReconnectNetworkTimer();
	}

	public void UnregisterServer()
	{
		Debug.Log("ZPlayFabMatchmaking::UnregisterServer - unregistering server now. State: " + m_state);
		if (m_state != State.Uninitialized)
		{
			ZLog.Log($"Unregister PlayFab server \"{m_serverData.serverName}\" and leaving network \"{m_serverData.networkId}\"");
			DeleteLobby(m_serverData.lobbyId);
			ZPlayFabSocket.DestroyListenSocket();
			PlayFabMultiplayerManager.Get().LeaveNetwork();
			PlayFabMultiplayerManager.Get().OnNetworkJoined -= OnNetworkJoined;
			PlayFabMultiplayerManager.Get().OnNetworkChanged -= OnNetworkChanged;
			PlayFabMultiplayerManager.Get().OnError -= OnNetworkError;
			PlayFabMultiplayerManager.Get().OnRemotePlayerJoined -= OnRemotePlayerJoined;
			PlayFabMultiplayerManager.Get().OnRemotePlayerLeft -= OnRemotePlayerLeft;
			m_serverData = null;
			m_retries = 0;
			m_state = State.Uninitialized;
			StopReconnectNetworkTimer();
		}
		else
		{
			ZPlayFabMatchmaking.LobbyLeft?.Invoke(success: true);
		}
	}

	internal static void ResetParty()
	{
		if (instance != null && instance.IsJoinedToNetwork())
		{
			instance.OnNetworkError(null, new PlayFabMultiplayerManagerErrorArgs(9999, "Forced ResetParty", PlayFabMultiplayerManagerErrorType.Error));
		}
		else
		{
			ZLog.Log("No active PlayFab Party to reset");
		}
	}

	private void OnNetworkError(object sender, PlayFabMultiplayerManagerErrorArgs args)
	{
		if (!IsReconnectNetworkTimerActive())
		{
			ZLog.LogWarning($"PlayFab network error in session '{m_serverData.serverName}' and network {m_serverData.networkId} with type '{args.Type}' and code '{args.Code}': {args.Message}");
			StartReconnectNetworkTimer(args.Code);
		}
	}

	private void OnNetworkChanged(object sender, string newNetworkId)
	{
		ZLog.LogWarning($"PlayFab network session '{m_serverData.serverName}' and network {m_serverData.networkId} changed to network {newNetworkId}");
		m_serverData.networkId = newNetworkId;
		Dictionary<string, string> lobbyData = new Dictionary<string, string> { [PlayFabAttrKey.NetworkId.ToKeyString()] = m_serverData.networkId };
		PlayFabMultiplayerAPI.UpdateLobby(new UpdateLobbyRequest
		{
			LobbyId = m_serverData.lobbyId,
			LobbyData = lobbyData
		}, delegate
		{
			ZLog.Log($"Lobby {m_serverData.lobbyId} for world '{m_serverData.serverName}' change to network {m_serverData.networkId}");
		}, OnRefreshFailed);
	}

	private void DeleteLobby(string lobbyId)
	{
		PlayFabMultiplayerAPI.UpdateLobby(new UpdateLobbyRequest
		{
			LobbyId = lobbyId,
			SearchData = new Dictionary<string, string> { ["string_key2"] = false.ToString() }
		}, delegate
		{
			ZLog.Log("Deactivated PlayFab lobby " + lobbyId);
		}, delegate(PlayFabError error)
		{
			ZLog.LogWarning($"Failed to deactive lobby '{lobbyId}': {error.GenerateErrorReport()}");
		});
		LeaveLobby(lobbyId);
		ClearPlatformMatchmakingData();
	}

	public static void LeaveLobby(string lobbyId)
	{
		PlayFabMultiplayerAPI.LeaveLobby(new LeaveLobbyRequest
		{
			LobbyId = lobbyId,
			MemberEntity = GetEntityKeyForLocalUser()
		}, delegate
		{
			ZLog.Log("Left PlayFab lobby " + lobbyId);
			ZPlayFabMatchmaking.LobbyLeft?.Invoke(success: true);
		}, delegate(PlayFabError error)
		{
			ZLog.LogError($"Failed to leave lobby '{lobbyId}': {error.GenerateErrorReport()}");
			ZPlayFabMatchmaking.LobbyLeft?.Invoke(success: false);
		});
	}

	public static void LeaveEmptyLobby()
	{
		ZPlayFabMatchmaking.LobbyLeft?.Invoke(success: true);
	}

	public static void ResolveJoinCode(string joinCode, ZPlayFabMatchmakingSuccessCallback successAction, ZPlayFabMatchmakingFailedCallback failedAction)
	{
		string searchFilter = string.Format("{0} eq '{1}' and {2} eq '{3}'", "string_key4", joinCode, "string_key2", true.ToString());
		instance.m_activeSearches.Add(new ZPlayFabLobbySearch(successAction, failedAction, searchFilter, ZPlayFabLobbySearchFlags.None));
	}

	public static void CheckHostOnlineStatus(string hostName, ZPlayFabMatchmakingSuccessCallback successAction, ZPlayFabMatchmakingFailedCallback failedAction, bool joinLobby = false)
	{
		FindHostSession(string.Format("{0} eq '{1}' and {2} eq '{3}'", "string_key1", hostName, "string_key2", true.ToString()), successAction, failedAction, joinLobby);
	}

	public static void FindHostByIp(IPEndPoint hostIp, ZPlayFabMatchmakingSuccessCallback successAction, ZPlayFabMatchmakingFailedCallback failedAction, bool joinLobby = false)
	{
		if (!hostIp.IsPublic)
		{
			failedAction?.Invoke(ZPLayFabMatchmakingFailReason.EndPointNotOnInternet);
			return;
		}
		FindHostSession(string.Format("{0} eq '{1}' and {2} eq '{3}'", "string_key10", hostIp, "string_key2", true.ToString()), successAction, failedAction, joinLobby);
	}

	public static void FindServerByHostUser(PlatformUserID user, ZPlayFabMatchmakingSuccessCallback successAction, ZPlayFabMatchmakingFailedCallback failedAction, bool joinLobby = false)
	{
		if (!user.IsValid)
		{
			failedAction?.Invoke(ZPLayFabMatchmakingFailReason.InvalidParameter);
			return;
		}
		FindHostSession(string.Format("{0} eq '{1}' and {2} eq '{3}'", "string_key8", user, "string_key2", true.ToString()), successAction, failedAction, joinLobby);
	}

	private static Dictionary<char, int> CreateCharHistogram(string str)
	{
		Dictionary<char, int> dictionary = new Dictionary<char, int>();
		string text = str.ToLowerInvariant();
		foreach (char key in text)
		{
			if (dictionary.ContainsKey(key))
			{
				dictionary[key]++;
			}
			else
			{
				dictionary.Add(key, 1);
			}
		}
		return dictionary;
	}

	private static void AddNameSearchFilter(Dictionary<string, string> searchData, string serverName)
	{
		Dictionary<char, int> dictionary = CreateCharHistogram(serverName);
		for (char c = 'a'; c <= 'z'; c = (char)(c + 1))
		{
			if (CharToKeyName(c, out var key))
			{
				dictionary.TryGetValue(c, out var value);
				searchData.Add(key, value.ToString());
			}
		}
	}

	private static string CreateNameSearchFilter(string name)
	{
		Dictionary<char, int> dictionary = CreateCharHistogram(name);
		string text = "";
		string text2 = name.ToLowerInvariant();
		foreach (char c in text2)
		{
			if (CharToKeyName(c, out var key) && dictionary.TryGetValue(c, out var value))
			{
				text += $" and {key} ge {value}";
			}
		}
		return text;
	}

	private static bool CharToKeyName(char ch, out string key)
	{
		int num = "eariotnslcudpmhgbfywkvxzjq".IndexOf(ch);
		if (num < 0 || num >= 16)
		{
			key = null;
			return false;
		}
		key = $"number_key{num + 14 + 1}";
		return true;
	}

	private void CancelPendingSearches()
	{
		foreach (ZPlayFabLobbySearch activeSearch in instance.m_activeSearches)
		{
			activeSearch.Cancel();
		}
		m_pendingSearches.Clear();
	}

	private static void FindHostSession(string searchFilter, ZPlayFabMatchmakingSuccessCallback successAction, ZPlayFabMatchmakingFailedCallback failedAction, bool joinLobby)
	{
		if (joinLobby)
		{
			instance.CancelPendingSearches();
			instance.m_activeSearches.Add(new ZPlayFabLobbySearch(successAction, failedAction, searchFilter, ZPlayFabLobbySearchFlags.Join | ZPlayFabLobbySearchFlags.AllowRetry));
		}
		else
		{
			instance.m_pendingSearches.Enqueue(new ZPlayFabLobbySearch(successAction, failedAction, searchFilter, ZPlayFabLobbySearchFlags.Queued));
		}
	}

	public static ZPlayFabLobbySearch ListServers(string nameFilter, ZPlayFabMatchmakingNewServersCallback serversFoundAction, ZPlayFabMatchmakingServerSearchDoneCallback listDone)
	{
		string text = string.Format("{0} eq '{1}' and {2} eq '{3}'", "string_key3", true.ToString(), "string_key2", true.ToString());
		if (nameFilter == null)
		{
			nameFilter = string.Empty;
		}
		text = ((nameFilter.Length != 0) ? (text + CreateNameSearchFilter(nameFilter)) : (text + string.Format(" and {0} eq {1}", "number_key13", 36u)));
		bool flag = PlatformManager.DistributionPlatform.PrivilegeProvider.CheckPrivilege(Privilege.CrossPlatformMultiplayer).IsGranted();
		List<string> list = new List<string>(2);
		list.Add(CreateSearchFilter(text, flag));
		if (PlatformManager.DistributionPlatform.Platform != "Steam" && flag)
		{
			list.Add(CreateSearchFilter(text, isCrossplay: false));
		}
		ZPlayFabLobbySearch zPlayFabLobbySearch = new ZPlayFabLobbySearch(serversFoundAction, listDone, list.ToArray());
		instance.m_pendingSearches.Enqueue(zPlayFabLobbySearch);
		return zPlayFabLobbySearch;
	}

	private static string CreateSearchFilter(string baseFilter, bool isCrossplay)
	{
		string text = (isCrossplay ? "None" : PlatformManager.DistributionPlatform.Platform.ToString());
		return baseFilter + " and string_key12 eq '" + text + "'";
	}

	public static bool IsJoinCode(string joinString)
	{
		int result;
		if ((long)joinString.Length == 6)
		{
			return int.TryParse(joinString, out result);
		}
		return false;
	}

	public static void SetDataPort(int serverPort)
	{
		if (instance != null)
		{
			instance.m_serverPort = serverPort;
		}
	}

	public static void OnLogin()
	{
		if (instance != null && instance.m_pendingRegisterServer != null)
		{
			instance.m_pendingRegisterServer();
			instance.m_pendingRegisterServer = null;
		}
	}

	internal static void ForwardProgress()
	{
		if (instance != null)
		{
			instance.StopReconnectNetworkTimer();
		}
	}
}
public delegate void ZPlayFabMatchmakingFailedCallback(ZPLayFabMatchmakingFailReason failReason);
public enum ZPLayFabMatchmakingFailReason
{
	None,
	Unknown,
	Cancelled,
	InvalidServerData,
	ServerFull,
	NotLoggedIn,
	APIRequestLimitExceeded,
	EndPointNotOnInternet,
	InvalidParameter
}
public delegate void ZPlayFabMatchmakingNewServersCallback(PlayFabMatchmakingServerData[] serverData);
public delegate void ZPlayFabMatchmakingServerSearchDoneCallback(ZPLayFabMatchmakingFailReason failReason);
public delegate void ZPlayFabMatchmakingSuccessCallback(PlayFabMatchmakingServerData serverData);
using System;
using System.Collections.Generic;
using PlayFab.Party;
using Splatform;
using UnityEngine;

public class ZPlayFabSocket : ZNetStats, IDisposable, ISocket
{
	public class InFlightQueue
	{
		private readonly Queue<byte[]> m_payloads = new Queue<byte[]>();

		private float m_nextResend;

		private uint m_size;

		private uint m_head;

		private uint m_tail;

		public uint Bytes => m_size;

		public uint Head => m_head;

		public uint Tail => m_tail;

		public bool IsEmpty => m_payloads.Count == 0;

		public float NextResend => m_nextResend;

		public void Enqueue(byte[] payload)
		{
			m_payloads.Enqueue(payload);
			m_size += (uint)payload.Length;
			m_head++;
		}

		public void Drop()
		{
			m_size -= (uint)m_payloads.Dequeue().Length;
			m_tail++;
			ResetRetransTimer();
		}

		public byte[] Peek()
		{
			return m_payloads.Peek();
		}

		public void CopyPayloads(List<byte[]> payloads)
		{
			while (m_payloads.Count > 0)
			{
				payloads.Add(m_payloads.Dequeue());
			}
			foreach (byte[] payload in payloads)
			{
				m_payloads.Enqueue(payload);
			}
		}

		public void ResetRetransTimer(bool small = false)
		{
			m_nextResend = Time.time + (small ? 1f : 3f);
		}

		public void ResetAll()
		{
			m_payloads.Clear();
			m_nextResend = 0f;
			m_size = 0u;
			m_head = 0u;
			m_tail = 0u;
		}
	}

	private const byte PAYLOAD_DAT = 17;

	private const byte PAYLOAD_ACK = 42;

	private const byte PAYLOAD_INT = 64;

	private const int PAYLOAD_HEADER_LEN = 5;

	private const float PARTY_RESET_GRACE_SEC = 3f;

	private const float PARTY_RESET_TIMEOUT_SEC = 20f;

	private const float KICKSTART_COOLDOWN = 6f;

	private const float NETWORK_ERROR_WATCHDOG = 26f;

	private const float INFLIGHT_SCALING_FACTOR = 0.25f;

	private const byte INT_PLATFORM_ID = 1;

	private static ZPlayFabSocket s_listenSocket;

	private static readonly Dictionary<string, ZPlayFabSocket> s_connectSockets = new Dictionary<string, ZPlayFabSocket>();

	private static float s_durationToPartyReset;

	private static DateTime s_lastReception;

	private ZPlayFabSocketState m_state;

	private PlayFabPlayer[] m_peer;

	private string m_lobbyId;

	private readonly byte[] m_sndMsg = new byte[5];

	private readonly bool m_isClient;

	public readonly string m_remotePlayerId;

	private PlatformUserID m_platformPlayerId;

	private readonly Queue<ZPackage> m_recvQueue = new Queue<ZPackage>();

	private readonly Dictionary<uint, byte[]> m_outOfOrderQueue = new Dictionary<uint, byte[]>();

	private readonly Queue<byte[]> m_sendQueue = new Queue<byte[]>();

	private readonly InFlightQueue m_inFlightQueue = new InFlightQueue();

	private readonly List<byte[]> m_retransmitCache = new List<byte[]>();

	private readonly List<Action> m_delayedInitActions = new List<Action>();

	private readonly PlayFabZLibWorkQueue m_zlibWorkQueue = new PlayFabZLibWorkQueue();

	private readonly Queue<ZPlayFabSocket> m_backlog = new Queue<ZPlayFabSocket>();

	private uint m_next;

	private float m_partyResetTimeout;

	private float m_partyResetConnectTimeout;

	private bool m_partyNetworkLeft;

	private bool m_didRecover;

	private float m_canKickstartIn;

	private bool m_useCompression;

	private Action<PlayFabMatchmakingServerData> m_serverDataFoundCallback;

	public ZPlayFabSocket()
	{
		m_state = ZPlayFabSocketState.LISTEN;
		PlayFabMultiplayerManager.Get().LogLevel = PlayFabMultiplayerManager.LogLevelType.None;
	}

	public ZPlayFabSocket(string remotePlayerId, Action<PlayFabMatchmakingServerData> serverDataFoundCallback)
	{
		PlayFabMultiplayerManager.Get().LogLevel = PlayFabMultiplayerManager.LogLevelType.None;
		m_state = ZPlayFabSocketState.CONNECTING;
		m_remotePlayerId = remotePlayerId;
		ClientConnect();
		PlayFabMultiplayerManager.Get().OnDataMessageReceived += OnDataMessageReceived;
		PlayFabMultiplayerManager.Get().OnRemotePlayerJoined += OnRemotePlayerJoined;
		m_isClient = true;
		m_platformPlayerId = PlatformManager.DistributionPlatform.LocalUser.PlatformUserID;
		m_serverDataFoundCallback = serverDataFoundCallback;
		ZPackage zPackage = new ZPackage();
		zPackage.Write((byte)1);
		zPackage.Write(m_platformPlayerId.ToString());
		Send(zPackage, 64);
		ZLog.Log("PlayFab socket with remote ID " + remotePlayerId + " sent local Platform ID " + GetHostName());
	}

	private void ClientConnect()
	{
		ZPlayFabMatchmaking.CheckHostOnlineStatus(m_remotePlayerId, OnRemotePlayerSessionFound, OnRemotePlayerNotFound, joinLobby: true);
	}

	private ZPlayFabSocket(PlayFabPlayer remotePlayer)
	{
		InitRemotePlayer(remotePlayer);
		Connect(remotePlayer);
		m_isClient = false;
		m_remotePlayerId = remotePlayer.EntityKey.Id;
		PlayFabMultiplayerManager.Get().OnDataMessageReceived += OnDataMessageReceived;
		ZLog.Log("PlayFab listen socket child connected to remote player " + m_remotePlayerId);
	}

	private void InitRemotePlayer(PlayFabPlayer remotePlayer)
	{
		m_delayedInitActions.Add(delegate
		{
			remotePlayer.IsMuted = true;
			ZLog.Log("Muted PlayFab remote player " + remotePlayer.EntityKey.Id);
		});
	}

	private void OnRemotePlayerSessionFound(PlayFabMatchmakingServerData serverData)
	{
		m_serverDataFoundCallback?.Invoke(serverData);
		if (m_state != ZPlayFabSocketState.CLOSED)
		{
			string networkId = PlayFabMultiplayerManager.Get().NetworkId;
			m_lobbyId = serverData.lobbyId;
			if (m_state == ZPlayFabSocketState.CONNECTING)
			{
				ZLog.Log("Joining server '" + serverData.serverName + "' at PlayFab network " + serverData.networkId + " from lobby " + serverData.lobbyId);
				PlayFabMultiplayerManager.Get().JoinNetwork(serverData.networkId);
				PlayFabMultiplayerManager.Get().OnNetworkJoined += OnNetworkJoined;
			}
			else if (networkId == null || networkId != serverData.networkId || m_partyNetworkLeft)
			{
				ZLog.Log("Re-joining server '" + serverData.serverName + "' at new PlayFab network " + serverData.networkId);
				PlayFabMultiplayerManager.Get().JoinNetwork(serverData.networkId);
				m_partyNetworkLeft = false;
			}
			else if (PartyResetInProgress())
			{
				ZLog.Log("Leave server '" + serverData.serverName + "' at new PlayFab network " + serverData.networkId + ", try to re-join later");
				ResetPartyTimeout();
				PlayFabMultiplayerManager.Get().LeaveNetwork();
				m_partyNetworkLeft = true;
			}
		}
	}

	private void OnRemotePlayerNotFound(ZPLayFabMatchmakingFailReason failReason)
	{
		ZLog.LogWarning("Failed to locate network session for PlayFab player " + m_remotePlayerId);
		switch (failReason)
		{
		case ZPLayFabMatchmakingFailReason.InvalidServerData:
			ZNet.SetExternalError(ZNet.ConnectionStatus.ErrorVersion);
			break;
		case ZPLayFabMatchmakingFailReason.ServerFull:
			ZNet.SetExternalError(ZNet.ConnectionStatus.ErrorFull);
			break;
		case ZPLayFabMatchmakingFailReason.APIRequestLimitExceeded:
			ResetPartyTimeout();
			return;
		}
		Close();
	}

	private void CheckReestablishConnection(byte[] maybeCompressedBuffer)
	{
		try
		{
			OnDataMessageReceivedCont(m_zlibWorkQueue.UncompressOnThisThread(maybeCompressedBuffer));
			return;
		}
		catch
		{
		}
		byte msgType = GetMsgType(maybeCompressedBuffer);
		if (GetMsgId(maybeCompressedBuffer) == 0 && msgType == 64)
		{
			ZLog.Log("Assume restarted game session for remote ID " + GetEndPointString() + " and Platform ID " + GetHostName());
			ResetAll();
			OnDataMessageReceivedCont(maybeCompressedBuffer);
		}
	}

	private void ResetAll()
	{
		m_recvQueue.Clear();
		m_outOfOrderQueue.Clear();
		m_sendQueue.Clear();
		m_inFlightQueue.ResetAll();
		m_retransmitCache.Clear();
		m_zlibWorkQueue.Poll(out var _, out var _);
		m_next = 0u;
		m_canKickstartIn = 0f;
		m_useCompression = false;
		m_didRecover = false;
		CancelResetParty();
	}

	private void OnDataMessageReceived(object sender, PlayFabPlayer from, byte[] compressedBuffer)
	{
		if (!(from.EntityKey.Id == m_remotePlayerId))
		{
			return;
		}
		DelayedInit();
		if (m_useCompression)
		{
			if (!m_isClient && m_didRecover)
			{
				CheckReestablishConnection(compressedBuffer);
			}
			else
			{
				m_zlibWorkQueue.Decompress(compressedBuffer);
			}
		}
		else
		{
			OnDataMessageReceivedCont(compressedBuffer);
		}
	}

	private void OnDataMessageReceivedCont(byte[] buffer)
	{
		byte msgType = GetMsgType(buffer);
		uint msgId = GetMsgId(buffer);
		s_lastReception = DateTime.UtcNow;
		IncRecvBytes(buffer.Length);
		if (msgType == 42)
		{
			ProcessAck(msgId);
			return;
		}
		if (m_next != msgId)
		{
			SendAck(m_next);
			if (msgId - m_next < int.MaxValue && !m_outOfOrderQueue.ContainsKey(msgId))
			{
				m_outOfOrderQueue.Add(msgId, buffer);
			}
			return;
		}
		switch (msgType)
		{
		case 17:
			m_recvQueue.Enqueue(new ZPackage(buffer, buffer.Length - 5));
			break;
		case 64:
			InternalReceive(new ZPackage(buffer, buffer.Length - 5));
			break;
		default:
			ZLog.LogError("Unknown message type " + msgType + " received by socket!\nByte array:\n" + BitConverter.ToString(buffer));
			return;
		}
		SendAck(++m_next);
		if (m_outOfOrderQueue.Count != 0)
		{
			TryDeliverOutOfOrder();
		}
	}

	private void ProcessAck(uint msgId)
	{
		while (m_inFlightQueue.Tail != msgId)
		{
			if (m_inFlightQueue.IsEmpty)
			{
				Close();
				break;
			}
			m_inFlightQueue.Drop();
		}
	}

	private void TryDeliverOutOfOrder()
	{
		byte[] value;
		while (m_outOfOrderQueue.TryGetValue(m_next, out value))
		{
			m_outOfOrderQueue.Remove(m_next);
			OnDataMessageReceivedCont(value);
		}
	}

	private void InternalReceive(ZPackage pkg)
	{
		if (pkg.ReadByte() == 1)
		{
			m_platformPlayerId = new PlatformUserID(pkg.ReadString());
			ZLog.Log("PlayFab socket with remote ID " + GetEndPointString() + " received local Platform ID " + GetHostName());
		}
		else
		{
			ZLog.LogError("Unknown data in internal receive! Ignoring");
		}
	}

	private void SendAck(uint nextMsgId)
	{
		SetMsgType(m_sndMsg, 42);
		SetMsgId(m_sndMsg, nextMsgId);
		InternalSend(m_sndMsg);
	}

	private static void SetMsgType(byte[] payload, byte t)
	{
		payload[4] = t;
	}

	private static void SetMsgId(byte[] payload, uint id)
	{
		payload[0] = (byte)id;
		payload[1] = (byte)(id >> 8);
		payload[2] = (byte)(id >> 16);
		payload[3] = (byte)(id >> 24);
	}

	private uint GetMsgId(byte[] buffer)
	{
		int num = buffer.Length - 5;
		return (uint)(0 + buffer[num] + (buffer[num + 1] << 8) + (buffer[num + 2] << 16) + (buffer[num + 3] << 24));
	}

	private byte GetMsgType(byte[] buffer)
	{
		return buffer[^1];
	}

	private void DelayedInit()
	{
		if (m_delayedInitActions.Count == 0)
		{
			return;
		}
		foreach (Action delayedInitAction in m_delayedInitActions)
		{
			delayedInitAction();
		}
		m_delayedInitActions.Clear();
	}

	private void OnNetworkJoined(object sender, string networkId)
	{
		ZLog.Log("PlayFab client socket to remote player " + m_remotePlayerId + " joined network " + networkId);
		if (m_isClient && m_state == ZPlayFabSocketState.CONNECTED)
		{
			ClientConnect();
		}
		ZRpc.SetLongTimeout(enable: true);
	}

	private void OnRemotePlayerJoined(object sender, PlayFabPlayer player)
	{
		InitRemotePlayer(player);
		if (player.EntityKey.Id == m_remotePlayerId)
		{
			ZLog.Log("PlayFab socket connected to remote player " + m_remotePlayerId);
			Connect(player);
		}
	}

	private void Connect(PlayFabPlayer remotePlayer)
	{
		string id = remotePlayer.EntityKey.Id;
		if (!s_connectSockets.ContainsKey(id))
		{
			s_connectSockets.Add(id, this);
			s_lastReception = DateTime.UtcNow;
		}
		if (m_state == ZPlayFabSocketState.CONNECTED)
		{
			ZLog.Log("Resume TX on " + GetEndPointString());
		}
		m_peer = new PlayFabPlayer[1] { remotePlayer };
		m_state = ZPlayFabSocketState.CONNECTED;
		CancelResetParty();
		if (m_sendQueue.Count > 0)
		{
			m_inFlightQueue.ResetRetransTimer();
			while (m_sendQueue.Count > 0)
			{
				InternalSend(m_sendQueue.Dequeue());
			}
		}
		else
		{
			KickstartAfterRecovery();
		}
	}

	private bool PartyResetInProgress()
	{
		return m_partyResetTimeout > 0f;
	}

	private void CancelResetParty()
	{
		m_didRecover = PartyResetInProgress();
		m_partyNetworkLeft = false;
		m_partyResetTimeout = 0f;
		m_partyResetConnectTimeout = 0f;
		s_durationToPartyReset = 0f;
	}

	private void InternalSend(byte[] payload)
	{
		if (PartyResetInProgress())
		{
			return;
		}
		IncSentBytes(payload.Length);
		if (m_useCompression)
		{
			if (ZNet.instance != null && ZNet.instance.HaveStopped)
			{
				InternalSendCont(m_zlibWorkQueue.CompressOnThisThread(payload));
			}
			else
			{
				m_zlibWorkQueue.Compress(payload);
			}
		}
		else
		{
			InternalSendCont(payload);
		}
	}

	private void InternalSendCont(byte[] compressedPayload)
	{
		if (PartyResetInProgress())
		{
			return;
		}
		if (PlayFabMultiplayerManager.Get().SendDataMessage(compressedPayload, m_peer, DeliveryOption.Guaranteed))
		{
			if (!m_isClient)
			{
				ZPlayFabMatchmaking.ForwardProgress();
			}
			return;
		}
		if (m_isClient)
		{
			ScheduleResetParty();
		}
		ResetPartyTimeout();
		ZLog.Log("Failed to send, suspend TX on " + GetEndPointString() + " while trying to reconnect");
	}

	private void ResetPartyTimeout()
	{
		m_partyResetConnectTimeout = UnityEngine.Random.Range(9f, 11f) + s_durationToPartyReset;
		m_partyResetTimeout = UnityEngine.Random.Range(18f, 22f) + s_durationToPartyReset;
	}

	internal static void ScheduleResetParty()
	{
		if (s_durationToPartyReset <= 0f)
		{
			s_durationToPartyReset = UnityEngine.Random.Range(2.6999998f, 3.3000002f);
		}
	}

	public void Dispose()
	{
		Debug.Log("ZPlayFabSocket::Dispose. State: " + m_state);
		m_zlibWorkQueue.Dispose();
		ResetAll();
		if (m_state == ZPlayFabSocketState.CLOSED)
		{
			return;
		}
		if (m_state == ZPlayFabSocketState.LISTEN)
		{
			s_listenSocket = null;
			foreach (ZPlayFabSocket item in m_backlog)
			{
				item.Close();
			}
		}
		else
		{
			PlayFabMultiplayerManager.Get().OnDataMessageReceived -= OnDataMessageReceived;
		}
		if (!ZNet.instance.IsServer())
		{
			PlayFabMultiplayerManager.Get().OnRemotePlayerJoined -= OnRemotePlayerJoined;
			PlayFabMultiplayerManager.Get().OnNetworkJoined -= OnNetworkJoined;
			PlayFabMultiplayerManager.Get().LeaveNetwork();
		}
		if (m_state == ZPlayFabSocketState.CONNECTED)
		{
			s_connectSockets.Remove(m_peer[0].EntityKey.Id);
		}
		Debug.Log("ZPlayFabSocket::Dispose. leave lobby. LobbyId: " + m_lobbyId);
		if (m_lobbyId != null)
		{
			ZPlayFabMatchmaking.LeaveLobby(m_lobbyId);
		}
		m_state = ZPlayFabSocketState.CLOSED;
	}

	private void Update(float dt)
	{
		if (m_canKickstartIn >= 0f)
		{
			m_canKickstartIn -= dt;
		}
		if (!m_isClient)
		{
			return;
		}
		if (PartyResetInProgress())
		{
			m_partyResetTimeout -= dt;
			if (m_partyResetConnectTimeout > 0f)
			{
				m_partyResetConnectTimeout -= dt;
				if (m_partyResetConnectTimeout <= 0f)
				{
					ClientConnect();
				}
			}
		}
		else if ((DateTime.UtcNow - s_lastReception).TotalSeconds >= 26.0 && m_state == ZPlayFabSocketState.CONNECTED)
		{
			ZLog.Log("Do a reset party as nothing seems to be received");
			ResetPartyTimeout();
			PlayFabMultiplayerManager.Get().ResetParty();
		}
	}

	private void LateUpdate()
	{
		m_zlibWorkQueue.Poll(out var compressedBuffers, out var decompressedBuffers);
		if (compressedBuffers != null)
		{
			foreach (byte[] item in compressedBuffers)
			{
				InternalSendCont(item);
			}
		}
		if (decompressedBuffers == null)
		{
			return;
		}
		foreach (byte[] item2 in decompressedBuffers)
		{
			OnDataMessageReceivedCont(item2);
		}
	}

	public bool IsConnected()
	{
		if (m_state != ZPlayFabSocketState.CONNECTED)
		{
			return m_state == ZPlayFabSocketState.CONNECTING;
		}
		return true;
	}

	public void VersionMatch()
	{
		m_useCompression = true;
	}

	public void Send(ZPackage pkg, byte messageType)
	{
		if (pkg.Size() != 0 && IsConnected())
		{
			pkg.Write(m_inFlightQueue.Head);
			pkg.Write(messageType);
			byte[] array = pkg.GetArray();
			m_inFlightQueue.Enqueue(array);
			if (m_state == ZPlayFabSocketState.CONNECTED)
			{
				InternalSend(array);
			}
			else
			{
				m_sendQueue.Enqueue(array);
			}
		}
	}

	public void Send(ZPackage pkg)
	{
		Send(pkg, 17);
	}

	public ZPackage Recv()
	{
		CheckRetransmit();
		if (!GotNewData())
		{
			return null;
		}
		return m_recvQueue.Dequeue();
	}

	private void CheckRetransmit()
	{
		if (!m_inFlightQueue.IsEmpty && !PartyResetInProgress() && m_state == ZPlayFabSocketState.CONNECTED && !(Time.time < m_inFlightQueue.NextResend))
		{
			DoRetransmit();
		}
	}

	private void DoRetransmit(bool canKickstart = true)
	{
		if (canKickstart && CanKickstartRatelimit())
		{
			KickstartAfterRecovery();
		}
		else if (!m_inFlightQueue.IsEmpty)
		{
			InternalSend(m_inFlightQueue.Peek());
			m_inFlightQueue.ResetRetransTimer(small: true);
		}
	}

	private bool CanKickstartRatelimit()
	{
		return m_canKickstartIn <= 0f;
	}

	private void KickstartAfterRecovery()
	{
		try
		{
			TryKickstartAfterRecovery();
		}
		catch (Exception ex)
		{
			ZLog.LogWarning("Failed to resend data on $" + GetEndPointString() + ", closing socket: " + ex.Message);
			Close();
		}
	}

	private void TryKickstartAfterRecovery()
	{
		if (!m_inFlightQueue.IsEmpty)
		{
			m_inFlightQueue.CopyPayloads(m_retransmitCache);
			foreach (byte[] item in m_retransmitCache)
			{
				InternalSend(item);
			}
			m_retransmitCache.Clear();
			m_inFlightQueue.ResetRetransTimer();
		}
		m_canKickstartIn = 6f;
	}

	public int GetSendQueueSize()
	{
		return (int)((float)m_inFlightQueue.Bytes * 0.25f);
	}

	public int GetCurrentSendRate()
	{
		throw new NotImplementedException();
	}

	internal void StartHost()
	{
		if (s_listenSocket != null)
		{
			ZLog.LogError("Multiple PlayFab listen sockets");
		}
		else
		{
			s_listenSocket = this;
		}
	}

	public bool IsHost()
	{
		return m_state == ZPlayFabSocketState.LISTEN;
	}

	public bool GotNewData()
	{
		return m_recvQueue.Count > 0;
	}

	public string GetEndPointString()
	{
		string text = "";
		if (m_peer != null)
		{
			text = m_peer[0].EntityKey.Id;
		}
		return "playfab/" + text;
	}

	public ISocket Accept()
	{
		if (m_backlog.Count == 0)
		{
			return null;
		}
		ZRpc.SetLongTimeout(enable: true);
		return m_backlog.Dequeue();
	}

	public int GetHostPort()
	{
		if (!IsHost())
		{
			return -1;
		}
		return 0;
	}

	public bool Flush()
	{
		throw new NotImplementedException();
	}

	public string GetHostName()
	{
		return m_platformPlayerId.ToString();
	}

	public void Close()
	{
		Dispose();
	}

	internal static void LostConnection(PlayFabPlayer player)
	{
		string id = player.EntityKey.Id;
		if (s_connectSockets.TryGetValue(id, out var value))
		{
			ZLog.Log("Keep socket for " + value.GetEndPointString() + ", try to reconnect before timeout");
		}
	}

	internal static void QueueConnection(PlayFabPlayer player)
	{
		string id = player.EntityKey.Id;
		if (s_connectSockets.TryGetValue(id, out var value))
		{
			ZLog.Log("Resume TX on " + value.GetEndPointString());
			value.Connect(player);
		}
		else if (s_listenSocket != null)
		{
			s_listenSocket.m_backlog.Enqueue(new ZPlayFabSocket(player));
		}
		else
		{
			ZLog.LogError("Incoming PlayFab connection without any open listen socket");
		}
	}

	internal static void DestroyListenSocket()
	{
		while (s_connectSockets.Count > 0)
		{
			Dictionary<string, ZPlayFabSocket>.Enumerator enumerator = s_connectSockets.GetEnumerator();
			enumerator.MoveNext();
			enumerator.Current.Value.Close();
		}
		s_listenSocket.Close();
		s_listenSocket = null;
	}

	internal static uint NumSockets()
	{
		return (uint)s_connectSockets.Count;
	}

	internal static void UpdateAllSockets(float dt)
	{
		if (s_durationToPartyReset > 0f)
		{
			s_durationToPartyReset -= dt;
			if (s_durationToPartyReset < 0f)
			{
				ZLog.Log("Reset party to clear network error");
				PlayFabMultiplayerManager.Get().ResetParty();
			}
		}
		foreach (ZPlayFabSocket value in s_connectSockets.Values)
		{
			value.Update(dt);
		}
	}

	internal static void LateUpdateAllSocket()
	{
		foreach (ZPlayFabSocket value in s_connectSockets.Values)
		{
			value.LateUpdate();
		}
	}
}
internal enum ZPlayFabSocketState
{
	CLOSED,
	LISTEN,
	CONNECTING,
	CONNECTED
}
using System;
using System.Collections.Generic;

public class ZRoutedRpc
{
	public class RoutedRPCData
	{
		public long m_msgID;

		public long m_senderPeerID;

		public long m_targetPeerID;

		public ZDOID m_targetZDO;

		public int m_methodHash;

		public ZPackage m_parameters = new ZPackage();

		public void Serialize(ZPackage pkg)
		{
			pkg.Write(m_msgID);
			pkg.Write(m_senderPeerID);
			pkg.Write(m_targetPeerID);
			pkg.Write(m_targetZDO);
			pkg.Write(m_methodHash);
			pkg.Write(m_parameters);
		}

		public void Deserialize(ZPackage pkg)
		{
			m_msgID = pkg.ReadLong();
			m_senderPeerID = pkg.ReadLong();
			m_targetPeerID = pkg.ReadLong();
			m_targetZDO = pkg.ReadZDOID();
			m_methodHash = pkg.ReadInt();
			m_parameters = pkg.ReadPackage();
		}
	}

	public static long Everybody;

	public Action<long> m_onNewPeer;

	private int m_rpcMsgID = 1;

	private bool m_server;

	private long m_id;

	private readonly List<ZNetPeer> m_peers = new List<ZNetPeer>();

	private readonly Dictionary<int, RoutedMethodBase> m_functions = new Dictionary<int, RoutedMethodBase>();

	private static ZRoutedRpc s_instance;

	public static ZRoutedRpc instance => s_instance;

	public ZRoutedRpc(bool server)
	{
		s_instance = this;
		m_server = server;
	}

	public void SetUID(long uid)
	{
		m_id = uid;
	}

	public void AddPeer(ZNetPeer peer)
	{
		m_peers.Add(peer);
		peer.m_rpc.Register<ZPackage>("RoutedRPC", RPC_RoutedRPC);
		if (m_onNewPeer != null)
		{
			m_onNewPeer(peer.m_uid);
		}
	}

	public void RemovePeer(ZNetPeer peer)
	{
		m_peers.Remove(peer);
	}

	private ZNetPeer GetPeer(long uid)
	{
		foreach (ZNetPeer peer in m_peers)
		{
			if (peer.m_uid == uid)
			{
				return peer;
			}
		}
		return null;
	}

	public void InvokeRoutedRPC(long targetPeerID, string methodName, params object[] parameters)
	{
		InvokeRoutedRPC(targetPeerID, ZDOID.None, methodName, parameters);
	}

	public void InvokeRoutedRPC(string methodName, params object[] parameters)
	{
		InvokeRoutedRPC(GetServerPeerID(), methodName, parameters);
	}

	private long GetServerPeerID()
	{
		if (m_server)
		{
			return m_id;
		}
		if (m_peers.Count > 0)
		{
			return m_peers[0].m_uid;
		}
		return 0L;
	}

	public void InvokeRoutedRPC(long targetPeerID, ZDOID targetZDO, string methodName, params object[] parameters)
	{
		RoutedRPCData routedRPCData = new RoutedRPCData();
		routedRPCData.m_msgID = m_id + m_rpcMsgID++;
		routedRPCData.m_senderPeerID = m_id;
		routedRPCData.m_targetPeerID = targetPeerID;
		routedRPCData.m_targetZDO = targetZDO;
		routedRPCData.m_methodHash = methodName.GetStableHashCode();
		ZRpc.Serialize(parameters, ref routedRPCData.m_parameters);
		routedRPCData.m_parameters.SetPos(0);
		if (targetPeerID == m_id || targetPeerID == 0L)
		{
			HandleRoutedRPC(routedRPCData);
		}
		if (targetPeerID != m_id)
		{
			RouteRPC(routedRPCData);
		}
	}

	private void RouteRPC(RoutedRPCData rpcData)
	{
		ZPackage zPackage = new ZPackage();
		rpcData.Serialize(zPackage);
		if (m_server)
		{
			if (rpcData.m_targetPeerID != 0L)
			{
				ZNetPeer peer = GetPeer(rpcData.m_targetPeerID);
				if (peer != null && peer.IsReady())
				{
					peer.m_rpc.Invoke("RoutedRPC", zPackage);
				}
				return;
			}
			{
				foreach (ZNetPeer peer2 in m_peers)
				{
					if (rpcData.m_senderPeerID != peer2.m_uid && peer2.IsReady())
					{
						peer2.m_rpc.Invoke("RoutedRPC", zPackage);
					}
				}
				return;
			}
		}
		foreach (ZNetPeer peer3 in m_peers)
		{
			if (peer3.IsReady())
			{
				peer3.m_rpc.Invoke("RoutedRPC", zPackage);
			}
		}
	}

	private void RPC_RoutedRPC(ZRpc rpc, ZPackage pkg)
	{
		RoutedRPCData routedRPCData = new RoutedRPCData();
		routedRPCData.Deserialize(pkg);
		if (routedRPCData.m_targetPeerID == m_id || routedRPCData.m_targetPeerID == 0L)
		{
			HandleRoutedRPC(routedRPCData);
		}
		if (m_server && routedRPCData.m_targetPeerID != m_id)
		{
			RouteRPC(routedRPCData);
		}
	}

	private void HandleRoutedRPC(RoutedRPCData data)
	{
		if (data.m_targetZDO.IsNone())
		{
			if (m_functions.TryGetValue(data.m_methodHash, out var value))
			{
				value.Invoke(data.m_senderPeerID, data.m_parameters);
			}
			return;
		}
		ZDO zDO = ZDOMan.instance.GetZDO(data.m_targetZDO);
		if (zDO != null)
		{
			ZNetView zNetView = ZNetScene.instance.FindInstance(zDO);
			if (zNetView != null)
			{
				zNetView.HandleRoutedRPC(data);
			}
		}
	}

	public void Register(string name, Action<long> f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod(f));
	}

	public void Register<T>(string name, Action<long, T> f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T>(f));
	}

	public void Register<T, U>(string name, Action<long, T, U> f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T, U>(f));
	}

	public void Register<T, U, V>(string name, Action<long, T, U, V> f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T, U, V>(f));
	}

	public void Register<T, U, V, B>(string name, RoutedMethod<T, U, V, B>.Method f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T, U, V, B>(f));
	}

	public void Register<T, U, V, B, K>(string name, RoutedMethod<T, U, V, B, K>.Method f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T, U, V, B, K>(f));
	}

	public void Register<T, U, V, B, K, M>(string name, RoutedMethod<T, U, V, B, K, M>.Method f)
	{
		m_functions.Add(name.GetStableHashCode(), new RoutedMethod<T, U, V, B, K, M>(f));
	}
}
using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEngine;

public class ZRpc : IDisposable
{
	public enum ErrorCode
	{
		Success,
		Disconnected,
		IncompatibleVersion
	}

	private interface RpcMethodBase
	{
		void Invoke(ZRpc rpc, ZPackage pkg);
	}

	public class RpcMethod : RpcMethodBase
	{
		public delegate void Method(ZRpc RPC);

		private Method m_action;

		public RpcMethod(Method action)
		{
			m_action = action;
		}

		public void Invoke(ZRpc rpc, ZPackage pkg)
		{
			m_action(rpc);
		}
	}

	private class RpcMethod<T> : RpcMethodBase
	{
		private Action<ZRpc, T> m_action;

		public RpcMethod(Action<ZRpc, T> action)
		{
			m_action = action;
		}

		public void Invoke(ZRpc rpc, ZPackage pkg)
		{
			m_action.DynamicInvoke(Deserialize(rpc, m_action.Method.GetParameters(), pkg));
		}
	}

	private class RpcMethod<T, U> : RpcMethodBase
	{
		private Action<ZRpc, T, U> m_action;

		public RpcMethod(Action<ZRpc, T, U> action)
		{
			m_action = action;
		}

		public void Invoke(ZRpc rpc, ZPackage pkg)
		{
			m_action.DynamicInvoke(Deserialize(rpc, m_action.Method.GetParameters(), pkg));
		}
	}

	private class RpcMethod<T, U, V> : RpcMethodBase
	{
		private Action<ZRpc, T, U, V> m_action;

		public RpcMethod(Action<ZRpc, T, U, V> action)
		{
			m_action = action;
		}

		public void Invoke(ZRpc rpc, ZPackage pkg)
		{
			m_action.DynamicInvoke(Deserialize(rpc, m_action.Method.GetParameters(), pkg));
		}
	}

	public class RpcMethod<T, U, V, B> : RpcMethodBase
	{
		public delegate void Method(ZRpc RPC, T p0, U p1, V p2, B p3);

		private Method m_action;

		public RpcMethod(Method action)
		{
			m_action = action;
		}

		public void Invoke(ZRpc rpc, ZPackage pkg)
		{
			m_action.DynamicInvoke(Deserialize(rpc, m_action.Method.GetParameters(), pkg));
		}
	}

	private ISocket m_socket;

	private ZPackage m_pkg = new ZPackage();

	private Dictionary<int, RpcMethodBase> m_functions = new Dictionary<int, RpcMethodBase>();

	private int m_sentPackages;

	private int m_sentData;

	private int m_recvPackages;

	private int m_recvData;

	private float m_pingTimer;

	private float m_timeSinceLastPing;

	private static float m_pingInterval = 1f;

	private static float m_timeout = 30f;

	private static bool m_DEBUG = false;

	public ZRpc(ISocket socket)
	{
		m_socket = socket;
	}

	public void Dispose()
	{
		m_socket.Dispose();
	}

	public ISocket GetSocket()
	{
		return m_socket;
	}

	public ErrorCode Update(float dt)
	{
		if (!m_socket.IsConnected())
		{
			return ErrorCode.Disconnected;
		}
		for (ZPackage zPackage = m_socket.Recv(); zPackage != null; zPackage = m_socket.Recv())
		{
			m_recvPackages++;
			m_recvData += zPackage.Size();
			try
			{
				HandlePackage(zPackage);
			}
			catch (EndOfStreamException ex)
			{
				ZLog.LogError("EndOfStreamException in ZRpc::HandlePackage: Assume incompatible version: " + ex.Message);
				return ErrorCode.IncompatibleVersion;
			}
			catch (Exception ex2)
			{
				ZLog.Log("Exception in ZRpc::HandlePackage: " + ex2);
			}
		}
		UpdatePing(dt);
		return ErrorCode.Success;
	}

	private void UpdatePing(float dt)
	{
		m_pingTimer += dt;
		if (m_pingTimer > m_pingInterval)
		{
			m_pingTimer = 0f;
			m_pkg.Clear();
			m_pkg.Write(0);
			m_pkg.Write(data: true);
			SendPackage(m_pkg);
		}
		m_timeSinceLastPing += dt;
		if (m_timeSinceLastPing > m_timeout)
		{
			ZLog.LogWarning("ZRpc timeout detected");
			m_socket.Close();
		}
	}

	private void ReceivePing(ZPackage package)
	{
		if (package.ReadBool())
		{
			m_pkg.Clear();
			m_pkg.Write(0);
			m_pkg.Write(data: false);
			SendPackage(m_pkg);
		}
		else
		{
			m_timeSinceLastPing = 0f;
		}
	}

	public float GetTimeSinceLastPing()
	{
		return m_timeSinceLastPing;
	}

	public bool IsConnected()
	{
		return m_socket.IsConnected();
	}

	private void HandlePackage(ZPackage package)
	{
		int num = package.ReadInt();
		RpcMethodBase value2;
		if (num == 0)
		{
			ReceivePing(package);
		}
		else if (m_DEBUG)
		{
			package.ReadString();
			if (m_functions.TryGetValue(num, out var value))
			{
				value.Invoke(this, package);
			}
		}
		else if (m_functions.TryGetValue(num, out value2))
		{
			value2.Invoke(this, package);
		}
	}

	public void Register(string name, RpcMethod.Method f)
	{
		int stableHashCode = name.GetStableHashCode();
		m_functions.Remove(stableHashCode);
		m_functions.Add(stableHashCode, new RpcMethod(f));
	}

	public void Register<T>(string name, Action<ZRpc, T> f)
	{
		int stableHashCode = name.GetStableHashCode();
		m_functions.Remove(stableHashCode);
		m_functions.Add(stableHashCode, new RpcMethod<T>(f));
	}

	public void Register<T, U>(string name, Action<ZRpc, T, U> f)
	{
		int stableHashCode = name.GetStableHashCode();
		m_functions.Remove(stableHashCode);
		m_functions.Add(stableHashCode, new RpcMethod<T, U>(f));
	}

	public void Register<T, U, V>(string name, Action<ZRpc, T, U, V> f)
	{
		int stableHashCode = name.GetStableHashCode();
		m_functions.Remove(stableHashCode);
		m_functions.Add(stableHashCode, new RpcMethod<T, U, V>(f));
	}

	public void Register<T, U, V, W>(string name, RpcMethod<T, U, V, W>.Method f)
	{
		int stableHashCode = name.GetStableHashCode();
		m_functions.Remove(stableHashCode);
		m_functions.Add(stableHashCode, new RpcMethod<T, U, V, W>(f));
	}

	public void Unregister(string name)
	{
		int stableHashCode = name.GetStableHashCode();
		m_functions.Remove(stableHashCode);
	}

	public void Invoke(string method, params object[] parameters)
	{
		if (IsConnected())
		{
			m_pkg.Clear();
			int stableHashCode = method.GetStableHashCode();
			m_pkg.Write(stableHashCode);
			if (m_DEBUG)
			{
				m_pkg.Write(method);
			}
			Serialize(parameters, ref m_pkg);
			SendPackage(m_pkg);
		}
	}

	private void SendPackage(ZPackage pkg)
	{
		m_sentPackages++;
		m_sentData += pkg.Size();
		m_socket.Send(m_pkg);
	}

	public static void Serialize(object[] parameters, ref ZPackage pkg)
	{
		foreach (object obj in parameters)
		{
			if (obj is int)
			{
				pkg.Write((int)obj);
			}
			else if (obj is uint)
			{
				pkg.Write((uint)obj);
			}
			else if (obj is long)
			{
				pkg.Write((long)obj);
			}
			else if (obj is float)
			{
				pkg.Write((float)obj);
			}
			else if (obj is double)
			{
				pkg.Write((double)obj);
			}
			else if (obj is bool)
			{
				pkg.Write((bool)obj);
			}
			else if (obj is string)
			{
				pkg.Write((string)obj);
			}
			else if (obj is ZPackage)
			{
				pkg.Write((ZPackage)obj);
			}
			else if (obj is List<string>)
			{
				List<string> list = obj as List<string>;
				pkg.Write(list.Count);
				foreach (string item in list)
				{
					pkg.Write(item);
				}
			}
			else if (obj is Vector3)
			{
				pkg.Write(((Vector3)obj).x);
				pkg.Write(((Vector3)obj).y);
				pkg.Write(((Vector3)obj).z);
			}
			else if (obj is Quaternion)
			{
				pkg.Write(((Quaternion)obj).x);
				pkg.Write(((Quaternion)obj).y);
				pkg.Write(((Quaternion)obj).z);
				pkg.Write(((Quaternion)obj).w);
			}
			else if (obj is ZDOID)
			{
				pkg.Write((ZDOID)obj);
			}
			else if (obj is HitData)
			{
				(obj as HitData).Serialize(ref pkg);
			}
			else if (obj is ISerializableParameter)
			{
				(obj as ISerializableParameter).Serialize(ref pkg);
			}
		}
	}

	public static object[] Deserialize(ZRpc rpc, ParameterInfo[] paramInfo, ZPackage pkg)
	{
		List<object> parameters = new List<object>();
		parameters.Add(rpc);
		Deserialize(paramInfo, pkg, ref parameters);
		return parameters.ToArray();
	}

	public static void Deserialize(ParameterInfo[] paramInfo, ZPackage pkg, ref List<object> parameters)
	{
		for (int i = 1; i < paramInfo.Length; i++)
		{
			ParameterInfo parameterInfo = paramInfo[i];
			if (parameterInfo.ParameterType == typeof(int))
			{
				parameters.Add(pkg.ReadInt());
			}
			else if (parameterInfo.ParameterType == typeof(uint))
			{
				parameters.Add(pkg.ReadUInt());
			}
			else if (parameterInfo.ParameterType == typeof(long))
			{
				parameters.Add(pkg.ReadLong());
			}
			else if (parameterInfo.ParameterType == typeof(float))
			{
				parameters.Add(pkg.ReadSingle());
			}
			else if (parameterInfo.ParameterType == typeof(double))
			{
				parameters.Add(pkg.ReadDouble());
			}
			else if (parameterInfo.ParameterType == typeof(bool))
			{
				parameters.Add(pkg.ReadBool());
			}
			else if (parameterInfo.ParameterType == typeof(string))
			{
				parameters.Add(pkg.ReadString());
			}
			else if (parameterInfo.ParameterType == typeof(ZPackage))
			{
				parameters.Add(pkg.ReadPackage());
			}
			else if (parameterInfo.ParameterType == typeof(List<string>))
			{
				int num = pkg.ReadInt();
				List<string> list = new List<string>(num);
				for (int j = 0; j < num; j++)
				{
					list.Add(pkg.ReadString());
				}
				parameters.Add(list);
			}
			else if (parameterInfo.ParameterType == typeof(Vector3))
			{
				Vector3 vector = new Vector3(pkg.ReadSingle(), pkg.ReadSingle(), pkg.ReadSingle());
				parameters.Add(vector);
			}
			else if (parameterInfo.ParameterType == typeof(Quaternion))
			{
				Quaternion quaternion = new Quaternion(pkg.ReadSingle(), pkg.ReadSingle(), pkg.ReadSingle(), pkg.ReadSingle());
				parameters.Add(quaternion);
			}
			else if (parameterInfo.ParameterType == typeof(ZDOID))
			{
				parameters.Add(pkg.ReadZDOID());
			}
			else if (parameterInfo.ParameterType == typeof(HitData))
			{
				HitData hitData = new HitData();
				hitData.Deserialize(ref pkg);
				parameters.Add(hitData);
			}
			else if (typeof(ISerializableParameter).IsAssignableFrom(parameterInfo.ParameterType))
			{
				ISerializableParameter serializableParameter = (ISerializableParameter)Activator.CreateInstance(parameterInfo.ParameterType);
				serializableParameter.Deserialize(ref pkg);
				parameters.Add(serializableParameter);
			}
			else if (typeof(ISerializableParameter).IsAssignableFrom(parameterInfo.ParameterType))
			{
				ISerializableParameter serializableParameter2 = (ISerializableParameter)Activator.CreateInstance(parameterInfo.ParameterType);
				serializableParameter2.Deserialize(ref pkg);
				parameters.Add(serializableParameter2);
			}
		}
	}

	public static void SetLongTimeout(bool enable)
	{
		if (enable)
		{
			m_timeout = 90f;
		}
		else
		{
			m_timeout = 30f;
		}
		ZLog.Log($"ZRpc timeout set to {m_timeout}s ");
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class ZSFX : MonoBehaviour, IMonoUpdater
{
	public bool m_playOnAwake = true;

	[Header("Captions")]
	[Tooltip("If set, will create an entry in the Closed Captions display.")]
	public string m_closedCaptionToken = "";

	[Tooltip("Appended after the first token, usually used for actions - $enemyname $attack for example.")]
	public string m_secondaryCaptionToken = "";

	[Tooltip("Sorted in order of importance. If too many captions are pushed, low importance ones will be removed first.")]
	public ClosedCaptions.CaptionType m_captionType;

	[Tooltip("Don't draw a caption if the sound is quieter than this (takes distance fading into account)")]
	public float m_minimumCaptionVolume = 0.3f;

	[Header("Clips")]
	public AudioClip[] m_audioClips = new AudioClip[0];

	[Header("Audio System")]
	[Tooltip("How many of the same sound can play in a small area? Uses the min distance of 3D sounds, or 1 meter, whichever is higher")]
	public int m_maxConcurrentSources;

	[Tooltip("Ignore the distance check, don't play sound if any other of the same sound were played recently")]
	public bool m_ignoreConcurrencyDistance;

	[Header("Random")]
	public float m_maxPitch = 1f;

	public float m_minPitch = 1f;

	public float m_maxVol = 1f;

	public float m_minVol = 1f;

	[Header("Fade")]
	public float m_fadeInDuration;

	public float m_fadeOutDuration;

	public float m_fadeOutDelay;

	public bool m_fadeOutOnAwake;

	[Header("Pan")]
	public bool m_randomPan;

	public float m_minPan = -1f;

	public float m_maxPan = 1f;

	[Header("Delay")]
	public float m_maxDelay;

	public float m_minDelay;

	[Header("Reverb")]
	public bool m_distanceReverb = true;

	public bool m_useCustomReverbDistance;

	public float m_customReverbDistance = 10f;

	[HideInInspector]
	public int m_hash;

	private const float m_globalReverbDistance = 64f;

	private const float m_minReverbSpread = 45f;

	private const float m_maxReverbSpread = 120f;

	private float m_delay;

	private float m_time;

	private float m_fadeOutTimer = -1f;

	private float m_fadeInTimer = -1f;

	private float m_vol = 1f;

	private float m_concurrencyVolumeModifier = 1f;

	private float m_volumeModifier = 1f;

	private float m_pitchModifier = 1f;

	private float m_reverbPitchModifier;

	private bool m_disabledFromConcurrency;

	private float m_baseSpread;

	private float m_basePitch;

	private float m_updateReverbTimer;

	private AudioSource m_audioSource;

	public static List<IMonoUpdater> Instances { get; } = new List<IMonoUpdater>();

	public event Action<ZSFX> OnDestroyingSfx = delegate
	{
	};

	public void Awake()
	{
		m_delay = UnityEngine.Random.Range(m_minDelay, m_maxDelay);
		m_audioSource = GetComponent<AudioSource>();
		m_baseSpread = m_audioSource.spread;
	}

	private void Start()
	{
		CustomUpdate(0f, float.NaN);
	}

	private void OnEnable()
	{
		if (m_audioSource != null)
		{
			Instances.Add(this);
		}
	}

	private void OnDisable()
	{
		if (m_audioSource != null && m_playOnAwake && m_audioSource.loop)
		{
			m_time = 0f;
			m_delay = UnityEngine.Random.Range(m_minDelay, m_maxDelay);
			m_audioSource.Stop();
		}
		Instances.Remove(this);
	}

	private void OnDestroy()
	{
		this.OnDestroyingSfx(this);
	}

	public void CustomUpdate(float dt, float time)
	{
		m_time += dt;
		if (m_delay >= 0f && m_time >= m_delay)
		{
			m_delay = -1f;
			if (m_playOnAwake)
			{
				Play();
			}
		}
		if (IsLooping())
		{
			m_concurrencyVolumeModifier = Mathf.MoveTowards(m_concurrencyVolumeModifier, (!m_disabledFromConcurrency) ? 1 : 0, dt / 0.5f);
		}
		if (!m_audioSource.isPlaying)
		{
			return;
		}
		if (m_distanceReverb && m_audioSource.loop)
		{
			m_updateReverbTimer += dt;
			if (m_updateReverbTimer > 1f)
			{
				m_updateReverbTimer = 0f;
				UpdateReverb();
			}
		}
		if (m_fadeOutOnAwake && m_time > m_fadeOutDelay)
		{
			m_fadeOutOnAwake = false;
			FadeOut();
		}
		float vol = m_vol;
		float num = 1f;
		if (m_fadeOutTimer >= 0f)
		{
			m_fadeOutTimer += dt;
			if (m_fadeOutTimer >= m_fadeOutDuration)
			{
				m_audioSource.volume = 0f;
				Stop();
				return;
			}
			num = 1f - Mathf.Clamp01(m_fadeOutTimer / m_fadeOutDuration);
		}
		else if (m_fadeInTimer >= 0f)
		{
			m_fadeInTimer += dt;
			num = Mathf.Clamp01(m_fadeInTimer / m_fadeInDuration);
			if (m_fadeInTimer > m_fadeInDuration)
			{
				m_fadeInTimer = -1f;
			}
		}
		m_audioSource.volume = vol * num * m_concurrencyVolumeModifier * m_volumeModifier;
		float num2 = m_basePitch * m_pitchModifier;
		num2 -= num2 * m_reverbPitchModifier;
		m_audioSource.pitch = num2;
	}

	public void FadeOut()
	{
		if (m_fadeOutTimer < 0f)
		{
			m_fadeOutTimer = 0f;
		}
	}

	public void Stop()
	{
		if (m_audioSource != null)
		{
			m_audioSource.Stop();
		}
	}

	public bool IsPlaying()
	{
		if (m_audioSource == null)
		{
			return false;
		}
		return m_audioSource.isPlaying;
	}

	private void UpdateReverb()
	{
		Camera mainCamera = Utils.GetMainCamera();
		if (m_distanceReverb && m_audioSource.spatialBlend != 0f && mainCamera != null)
		{
			float num = Vector3.Distance(mainCamera.transform.position, base.transform.position);
			bool num2 = Mister.InsideMister(base.transform.position);
			float num3 = (m_useCustomReverbDistance ? m_customReverbDistance : 64f);
			float num4 = Mathf.Clamp01(num / num3);
			float b = Mathf.Clamp01(m_audioSource.maxDistance / num3) * Mathf.Clamp01(num / m_audioSource.maxDistance);
			float num5 = Mathf.Max(num4, b);
			if (num2)
			{
				num5 = Mathf.Lerp(num5, 0f, num4);
				m_reverbPitchModifier = 0.5f * num4;
			}
			m_audioSource.bypassReverbZones = false;
			m_audioSource.reverbZoneMix = num5;
			if (m_baseSpread < 120f)
			{
				float a = Mathf.Max(m_baseSpread, 45f);
				m_audioSource.spread = Mathf.Lerp(a, 120f, num5);
			}
		}
		else
		{
			m_audioSource.bypassReverbZones = true;
		}
	}

	public void Play()
	{
		if (!(m_audioSource == null) && m_audioClips.Length != 0 && m_audioSource.gameObject.activeInHierarchy && AudioMan.instance.RequestPlaySound(this))
		{
			if (m_audioSource.loop && m_disabledFromConcurrency)
			{
				m_concurrencyVolumeModifier = 0f;
			}
			if (ClosedCaptions.Valid && !m_audioSource.loop && m_closedCaptionToken.Length > 0)
			{
				ClosedCaptions.Instance.RegisterCaption(this);
			}
			int num = UnityEngine.Random.Range(0, m_audioClips.Length);
			m_audioSource.clip = m_audioClips[num];
			m_audioSource.pitch = UnityEngine.Random.Range(m_minPitch, m_maxPitch);
			m_basePitch = m_audioSource.pitch;
			if (m_randomPan)
			{
				m_audioSource.panStereo = UnityEngine.Random.Range(m_minPan, m_maxPan);
			}
			m_vol = UnityEngine.Random.Range(m_minVol, m_maxVol);
			if (m_fadeInDuration > 0f)
			{
				m_audioSource.volume = 0f;
				m_fadeInTimer = 0f;
			}
			else
			{
				m_audioSource.volume = m_vol;
			}
			UpdateReverb();
			m_audioSource.Play();
		}
	}

	public void GenerateHash()
	{
		m_hash = Guid.NewGuid().GetHashCode();
	}

	public float GetConcurrencyDistance()
	{
		if (!m_ignoreConcurrencyDistance)
		{
			return Mathf.Max(1f, m_audioSource.minDistance);
		}
		return float.PositiveInfinity;
	}

	public void ConcurrencyDisable()
	{
		m_disabledFromConcurrency = true;
	}

	public void ConcurrencyEnable()
	{
		m_disabledFromConcurrency = false;
	}

	public float GetVolumeModifierByDistance(float distance)
	{
		float num = 0f;
		switch (m_audioSource.rolloffMode)
		{
		default:
			return Mathf.InverseLerp(m_audioSource.maxDistance, m_audioSource.minDistance, distance);
		case AudioRolloffMode.Logarithmic:
		{
			float f = distance / m_audioSource.minDistance;
			return 1f * (1f / (1f + 1f * Mathf.Log(f)));
		}
		case AudioRolloffMode.Custom:
		{
			float time = Mathf.InverseLerp(m_audioSource.minDistance, m_audioSource.maxDistance, distance);
			return m_audioSource.GetCustomCurve(AudioSourceCurveType.CustomRolloff).Evaluate(time);
		}
		}
	}

	public bool IsLooping()
	{
		return m_audioSource.loop;
	}

	public void SetVolumeModifier(float v)
	{
		m_volumeModifier = v;
	}

	public float GetVolumeModifier()
	{
		return m_volumeModifier;
	}

	public void SetPitchModifier(float p)
	{
		m_pitchModifier = p;
	}

	public float GetPitchModifier()
	{
		return m_pitchModifier;
	}
}
using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Sockets;
using System.Threading;

public class ZSocket : IDisposable
{
	private Socket m_socket;

	private Mutex m_mutex = new Mutex();

	private Mutex m_sendMutex = new Mutex();

	private Queue<Socket> m_newConnections = new Queue<Socket>();

	private static int m_maxRecvBuffer = 10485760;

	private int m_recvOffset;

	private byte[] m_recvBuffer;

	private byte[] m_recvSizeBuffer = new byte[4];

	private Queue<ZPackage> m_pkgQueue = new Queue<ZPackage>();

	private bool m_isSending;

	private Queue<byte[]> m_sendQueue = new Queue<byte[]>();

	private IPEndPoint m_endpoint;

	private string m_originalHostName;

	private int m_listenPort;

	private int m_lastRecvPkgSize;

	private int m_totalSent;

	private int m_totalRecv;

	public ZSocket()
	{
		m_socket = CreateSocket();
	}

	public static Socket CreateSocket()
	{
		return new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp)
		{
			NoDelay = true
		};
	}

	public ZSocket(Socket socket, string originalHostName = null)
	{
		m_socket = socket;
		m_originalHostName = originalHostName;
		try
		{
			m_endpoint = m_socket.RemoteEndPoint as IPEndPoint;
		}
		catch
		{
			Close();
			return;
		}
		BeginReceive();
	}

	public void Dispose()
	{
		Close();
		m_mutex.Close();
		m_sendMutex.Close();
		m_recvBuffer = null;
	}

	public void Close()
	{
		if (m_socket != null)
		{
			try
			{
				if (m_socket.Connected)
				{
					m_socket.Shutdown(SocketShutdown.Both);
				}
			}
			catch (Exception)
			{
			}
			m_socket.Close();
		}
		m_socket = null;
		m_endpoint = null;
	}

	public static IPEndPoint GetEndPoint(string host, int port)
	{
		return new IPEndPoint(Dns.GetHostEntry(host).AddressList[0], port);
	}

	public bool Connect(string host, int port)
	{
		ZLog.Log("Connecting to " + host + " : " + port);
		IPEndPoint endPoint = GetEndPoint(host, port);
		m_socket.BeginConnect(endPoint, null, null).AsyncWaitHandle.WaitOne(3000, exitContext: true);
		if (!m_socket.Connected)
		{
			return false;
		}
		try
		{
			m_endpoint = m_socket.RemoteEndPoint as IPEndPoint;
		}
		catch
		{
			Close();
			return false;
		}
		BeginReceive();
		ZLog.Log(" connected");
		return true;
	}

	public bool StartHost(int port)
	{
		if (m_listenPort != 0)
		{
			Close();
		}
		if (!BindSocket(m_socket, IPAddress.Any, port, port + 10))
		{
			ZLog.LogWarning("Failed to bind socket");
			return false;
		}
		m_socket.Listen(100);
		m_socket.BeginAccept(AcceptCallback, m_socket);
		return true;
	}

	private bool BindSocket(Socket socket, IPAddress ipAddress, int startPort, int endPort)
	{
		for (int i = startPort; i <= endPort; i++)
		{
			try
			{
				IPEndPoint localEP = new IPEndPoint(ipAddress, i);
				m_socket.Bind(localEP);
				m_listenPort = i;
				ZLog.Log("Bound socket port " + i);
				return true;
			}
			catch
			{
				ZLog.Log("Failed to bind port:" + i);
			}
		}
		return false;
	}

	private void BeginReceive()
	{
		m_socket.BeginReceive(m_recvSizeBuffer, 0, m_recvSizeBuffer.Length, SocketFlags.None, PkgSizeReceived, m_socket);
	}

	private void PkgSizeReceived(IAsyncResult res)
	{
		int num;
		try
		{
			num = m_socket.EndReceive(res);
		}
		catch (Exception)
		{
			Disconnect();
			return;
		}
		m_totalRecv += num;
		if (num != 4)
		{
			Disconnect();
			return;
		}
		int num2 = BitConverter.ToInt32(m_recvSizeBuffer, 0);
		if (num2 == 0 || num2 > 10485760)
		{
			ZLog.LogError("Invalid pkg size " + num2);
			return;
		}
		m_lastRecvPkgSize = num2;
		m_recvOffset = 0;
		m_lastRecvPkgSize = num2;
		if (m_recvBuffer == null)
		{
			m_recvBuffer = new byte[m_maxRecvBuffer];
		}
		m_socket.BeginReceive(m_recvBuffer, m_recvOffset, m_lastRecvPkgSize, SocketFlags.None, PkgReceived, m_socket);
	}

	private void Disconnect()
	{
		if (m_socket != null)
		{
			try
			{
				m_socket.Disconnect(reuseSocket: true);
			}
			catch
			{
			}
		}
	}

	private void PkgReceived(IAsyncResult res)
	{
		int num;
		try
		{
			num = m_socket.EndReceive(res);
		}
		catch (Exception)
		{
			Disconnect();
			return;
		}
		m_totalRecv += num;
		m_recvOffset += num;
		if (m_recvOffset < m_lastRecvPkgSize)
		{
			int size = m_lastRecvPkgSize - m_recvOffset;
			if (m_recvBuffer == null)
			{
				m_recvBuffer = new byte[m_maxRecvBuffer];
			}
			m_socket.BeginReceive(m_recvBuffer, m_recvOffset, size, SocketFlags.None, PkgReceived, m_socket);
		}
		else
		{
			ZPackage item = new ZPackage(m_recvBuffer, m_lastRecvPkgSize);
			m_mutex.WaitOne();
			m_pkgQueue.Enqueue(item);
			m_mutex.ReleaseMutex();
			BeginReceive();
		}
	}

	private void AcceptCallback(IAsyncResult res)
	{
		Socket item;
		try
		{
			item = m_socket.EndAccept(res);
		}
		catch
		{
			Disconnect();
			return;
		}
		m_mutex.WaitOne();
		m_newConnections.Enqueue(item);
		m_mutex.ReleaseMutex();
		m_socket.BeginAccept(AcceptCallback, m_socket);
	}

	public ZSocket Accept()
	{
		if (m_newConnections.Count == 0)
		{
			return null;
		}
		Socket socket = null;
		m_mutex.WaitOne();
		if (m_newConnections.Count > 0)
		{
			socket = m_newConnections.Dequeue();
		}
		m_mutex.ReleaseMutex();
		if (socket != null)
		{
			return new ZSocket(socket);
		}
		return null;
	}

	public bool IsConnected()
	{
		if (m_socket != null)
		{
			return m_socket.Connected;
		}
		return false;
	}

	public void Send(ZPackage pkg)
	{
		if (pkg.Size() == 0 || m_socket == null || !m_socket.Connected)
		{
			return;
		}
		byte[] array = pkg.GetArray();
		byte[] bytes = BitConverter.GetBytes(array.Length);
		m_sendMutex.WaitOne();
		if (!m_isSending)
		{
			if (array.Length > 10485760)
			{
				ZLog.LogError("Too big data package: " + array.Length);
			}
			try
			{
				m_totalSent += bytes.Length;
				m_socket.BeginSend(bytes, 0, bytes.Length, SocketFlags.None, PkgSent, null);
				m_isSending = true;
				m_sendQueue.Enqueue(array);
			}
			catch (Exception ex)
			{
				ZLog.Log("Handled exception in ZSocket:Send:" + ex);
				Disconnect();
			}
		}
		else
		{
			m_sendQueue.Enqueue(bytes);
			m_sendQueue.Enqueue(array);
		}
		m_sendMutex.ReleaseMutex();
	}

	private void PkgSent(IAsyncResult res)
	{
		m_sendMutex.WaitOne();
		if (m_sendQueue.Count > 0 && IsConnected())
		{
			byte[] array = m_sendQueue.Dequeue();
			try
			{
				m_totalSent += array.Length;
				m_socket.BeginSend(array, 0, array.Length, SocketFlags.None, PkgSent, null);
			}
			catch (Exception ex)
			{
				ZLog.Log("Handled exception in pkgsent:" + ex);
				m_isSending = false;
				Disconnect();
			}
		}
		else
		{
			m_isSending = false;
		}
		m_sendMutex.ReleaseMutex();
	}

	public ZPackage Recv()
	{
		if (m_socket == null)
		{
			return null;
		}
		if (m_pkgQueue.Count == 0)
		{
			return null;
		}
		ZPackage result = null;
		m_mutex.WaitOne();
		if (m_pkgQueue.Count > 0)
		{
			result = m_pkgQueue.Dequeue();
		}
		m_mutex.ReleaseMutex();
		return result;
	}

	public string GetEndPointString()
	{
		if (m_endpoint != null)
		{
			return m_endpoint.ToString();
		}
		return "None";
	}

	public string GetEndPointHost()
	{
		if (m_endpoint != null)
		{
			return m_endpoint.Address.ToString();
		}
		return "None";
	}

	public IPEndPoint GetEndPoint()
	{
		return m_endpoint;
	}

	public bool IsPeer(string host, int port)
	{
		if (!IsConnected())
		{
			return false;
		}
		if (m_endpoint == null)
		{
			return false;
		}
		IPEndPoint endpoint = m_endpoint;
		if (endpoint.Address.ToString() == host && endpoint.Port == port)
		{
			return true;
		}
		if (m_originalHostName != null && m_originalHostName == host && endpoint.Port == port)
		{
			return true;
		}
		return false;
	}

	public bool IsHost()
	{
		return m_listenPort != 0;
	}

	public int GetHostPort()
	{
		return m_listenPort;
	}

	public bool IsSending()
	{
		if (!m_isSending)
		{
			return m_sendQueue.Count > 0;
		}
		return true;
	}

	public void GetAndResetStats(out int totalSent, out int totalRecv)
	{
		totalSent = m_totalSent;
		totalRecv = m_totalRecv;
		m_totalSent = 0;
		m_totalRecv = 0;
	}
}
using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Sockets;
using System.Threading;

public class ZSocket2 : ZNetStats, IDisposable, ISocket
{
	private TcpListener m_listner;

	private TcpClient m_socket;

	private Mutex m_mutex = new Mutex();

	private Mutex m_sendMutex = new Mutex();

	private static int m_maxRecvBuffer = 10485760;

	private int m_recvOffset;

	private byte[] m_recvBuffer;

	private int m_recvSizeOffset;

	private byte[] m_recvSizeBuffer = new byte[4];

	private Queue<ZPackage> m_pkgQueue = new Queue<ZPackage>();

	private bool m_isSending;

	private Queue<byte[]> m_sendQueue = new Queue<byte[]>();

	private IPEndPoint m_endpoint;

	private string m_originalHostName;

	private int m_listenPort;

	private int m_lastRecvPkgSize;

	private int m_totalSent;

	private int m_totalRecv;

	private bool m_gotData;

	public ZSocket2()
	{
	}

	public static TcpClient CreateSocket()
	{
		TcpClient tcpClient = new TcpClient(AddressFamily.InterNetwork);
		ConfigureSocket(tcpClient);
		return tcpClient;
	}

	private static void ConfigureSocket(TcpClient socket)
	{
		socket.NoDelay = true;
		socket.SendBufferSize = 2048;
	}

	public ZSocket2(TcpClient socket, string originalHostName = null)
	{
		m_socket = socket;
		m_originalHostName = originalHostName;
		try
		{
			m_endpoint = m_socket.Client.RemoteEndPoint as IPEndPoint;
		}
		catch
		{
			Close();
			return;
		}
		BeginReceive();
	}

	public void Dispose()
	{
		Close();
		m_mutex.Close();
		m_sendMutex.Close();
		m_recvBuffer = null;
	}

	public void Close()
	{
		ZLog.Log("Closing socket " + GetEndPointString());
		if (m_listner != null)
		{
			m_listner.Stop();
			m_listner = null;
		}
		if (m_socket != null)
		{
			m_socket.Close();
			m_socket = null;
		}
		m_endpoint = null;
	}

	public static IPEndPoint GetEndPoint(string host, int port)
	{
		return new IPEndPoint(Dns.GetHostEntry(host).AddressList[0], port);
	}

	public bool StartHost(int port)
	{
		if (m_listner != null)
		{
			m_listner.Stop();
			m_listner = null;
		}
		if (!BindSocket(port, port + 10))
		{
			ZLog.LogWarning("Failed to bind socket");
			return false;
		}
		return true;
	}

	private bool BindSocket(int startPort, int endPort)
	{
		for (int i = startPort; i <= endPort; i++)
		{
			try
			{
				m_listner = new TcpListener(IPAddress.Any, i);
				m_listner.Start();
				m_listenPort = i;
				ZLog.Log("Bound socket port " + i);
				return true;
			}
			catch
			{
				ZLog.Log("Failed to bind port:" + i);
				m_listner = null;
			}
		}
		return false;
	}

	private void BeginReceive()
	{
		m_recvSizeOffset = 0;
		m_socket.GetStream().BeginRead(m_recvSizeBuffer, 0, m_recvSizeBuffer.Length, PkgSizeReceived, m_socket);
	}

	private void PkgSizeReceived(IAsyncResult res)
	{
		if (m_socket == null || !m_socket.Connected)
		{
			ZLog.LogWarning("PkgSizeReceived socket closed");
			Close();
			return;
		}
		int num;
		try
		{
			num = m_socket.GetStream().EndRead(res);
		}
		catch (Exception ex)
		{
			ZLog.LogWarning("PkgSizeReceived exception " + ex.ToString());
			Close();
			return;
		}
		if (num == 0)
		{
			ZLog.LogWarning("PkgSizeReceived Got 0 bytes data,closing socket");
			Close();
			return;
		}
		m_gotData = true;
		m_recvSizeOffset += num;
		if (m_recvSizeOffset < m_recvSizeBuffer.Length)
		{
			int count = m_recvSizeBuffer.Length - m_recvOffset;
			m_socket.GetStream().BeginRead(m_recvSizeBuffer, m_recvSizeOffset, count, PkgSizeReceived, m_socket);
			return;
		}
		int num2 = BitConverter.ToInt32(m_recvSizeBuffer, 0);
		if (num2 == 0 || num2 > 10485760)
		{
			ZLog.LogError("PkgSizeReceived Invalid pkg size " + num2);
			return;
		}
		m_lastRecvPkgSize = num2;
		m_recvOffset = 0;
		m_lastRecvPkgSize = num2;
		if (m_recvBuffer == null)
		{
			m_recvBuffer = new byte[m_maxRecvBuffer];
		}
		m_socket.GetStream().BeginRead(m_recvBuffer, m_recvOffset, m_lastRecvPkgSize, PkgReceived, m_socket);
	}

	private void PkgReceived(IAsyncResult res)
	{
		int num;
		try
		{
			num = m_socket.GetStream().EndRead(res);
		}
		catch (Exception ex)
		{
			ZLog.Log("PkgReceived error " + ex.ToString());
			Close();
			return;
		}
		if (num == 0)
		{
			ZLog.LogWarning("PkgReceived: Got 0 bytes data,closing socket");
			Close();
			return;
		}
		m_gotData = true;
		m_totalRecv += num;
		m_recvOffset += num;
		IncRecvBytes(num);
		if (m_recvOffset < m_lastRecvPkgSize)
		{
			int count = m_lastRecvPkgSize - m_recvOffset;
			if (m_recvBuffer == null)
			{
				m_recvBuffer = new byte[m_maxRecvBuffer];
			}
			m_socket.GetStream().BeginRead(m_recvBuffer, m_recvOffset, count, PkgReceived, m_socket);
		}
		else
		{
			ZPackage item = new ZPackage(m_recvBuffer, m_lastRecvPkgSize);
			m_mutex.WaitOne();
			m_pkgQueue.Enqueue(item);
			m_mutex.ReleaseMutex();
			BeginReceive();
		}
	}

	public ISocket Accept()
	{
		if (m_listner == null)
		{
			return null;
		}
		if (!m_listner.Pending())
		{
			return null;
		}
		TcpClient socket = m_listner.AcceptTcpClient();
		ConfigureSocket(socket);
		return new ZSocket2(socket);
	}

	public bool IsConnected()
	{
		if (m_socket != null)
		{
			return m_socket.Connected;
		}
		return false;
	}

	public void Send(ZPackage pkg)
	{
		if (pkg.Size() == 0 || m_socket == null || !m_socket.Connected)
		{
			return;
		}
		byte[] array = pkg.GetArray();
		byte[] bytes = BitConverter.GetBytes(array.Length);
		byte[] array2 = new byte[array.Length + bytes.Length];
		bytes.CopyTo(array2, 0);
		array.CopyTo(array2, 4);
		IncSentBytes(array.Length);
		m_sendMutex.WaitOne();
		if (!m_isSending)
		{
			if (array2.Length > 10485760)
			{
				ZLog.LogError("Too big data package: " + array2.Length);
			}
			try
			{
				m_totalSent += array2.Length;
				m_socket.GetStream().BeginWrite(array2, 0, array2.Length, PkgSent, m_socket);
				m_isSending = true;
			}
			catch (Exception ex)
			{
				ZLog.Log("Handled exception in ZSocket:Send:" + ex);
				Close();
			}
		}
		else
		{
			m_sendQueue.Enqueue(array2);
		}
		m_sendMutex.ReleaseMutex();
	}

	private void PkgSent(IAsyncResult res)
	{
		try
		{
			m_socket.GetStream().EndWrite(res);
		}
		catch (Exception ex)
		{
			ZLog.Log("PkgSent error " + ex.ToString());
			Close();
			return;
		}
		m_sendMutex.WaitOne();
		if (m_sendQueue.Count > 0 && IsConnected())
		{
			byte[] array = m_sendQueue.Dequeue();
			try
			{
				m_totalSent += array.Length;
				m_socket.GetStream().BeginWrite(array, 0, array.Length, PkgSent, m_socket);
			}
			catch (Exception ex2)
			{
				ZLog.Log("Handled exception in pkgsent:" + ex2);
				m_isSending = false;
				Close();
			}
		}
		else
		{
			m_isSending = false;
		}
		m_sendMutex.ReleaseMutex();
	}

	public ZPackage Recv()
	{
		if (m_socket == null)
		{
			return null;
		}
		if (m_pkgQueue.Count == 0)
		{
			return null;
		}
		ZPackage result = null;
		m_mutex.WaitOne();
		if (m_pkgQueue.Count > 0)
		{
			result = m_pkgQueue.Dequeue();
		}
		m_mutex.ReleaseMutex();
		return result;
	}

	public string GetEndPointString()
	{
		if (m_endpoint != null)
		{
			return m_endpoint.ToString();
		}
		return "None";
	}

	public string GetHostName()
	{
		if (m_endpoint != null)
		{
			return m_endpoint.Address.ToString();
		}
		return "None";
	}

	public IPEndPoint GetEndPoint()
	{
		return m_endpoint;
	}

	public bool IsPeer(string host, int port)
	{
		if (!IsConnected())
		{
			return false;
		}
		if (m_endpoint == null)
		{
			return false;
		}
		IPEndPoint endpoint = m_endpoint;
		if (endpoint.Address.ToString() == host && endpoint.Port == port)
		{
			return true;
		}
		if (m_originalHostName != null && m_originalHostName == host && endpoint.Port == port)
		{
			return true;
		}
		return false;
	}

	public bool IsHost()
	{
		return m_listenPort != 0;
	}

	public int GetHostPort()
	{
		return m_listenPort;
	}

	public int GetSendQueueSize()
	{
		if (!IsConnected())
		{
			return 0;
		}
		m_sendMutex.WaitOne();
		int num = 0;
		foreach (byte[] item in m_sendQueue)
		{
			num += item.Length;
		}
		m_sendMutex.ReleaseMutex();
		return num;
	}

	public bool IsSending()
	{
		if (!m_isSending)
		{
			return m_sendQueue.Count > 0;
		}
		return true;
	}

	public bool GotNewData()
	{
		bool gotData = m_gotData;
		m_gotData = false;
		return gotData;
	}

	public bool Flush()
	{
		return true;
	}

	public int GetCurrentSendRate()
	{
		return 0;
	}

	public int GetAverageSendRate()
	{
		return 0;
	}

	public void VersionMatch()
	{
	}
}
